insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (3, 17, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1029) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يقولوا: لَا إِلَهَ إِلَّا اللَّهُ، فَإِذَا قَالُوهَا مَنَعُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ، إِلَّا بِحَقِّهَا، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധനക്കർഹനില്ല എന്ന് പ്രഖ്യാപിക്കുന്നത് വരെ ജനങ്ങളോട് യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ അവർ പറയുന്നപക്ഷം അന്യായമായി അവരുടെ രക്തവും സമ്പത്തും കൈകാര്യം ചെയ്യുന്നതിൽ നിന്നും അവർ എന്നെ തടഞ്ഞിരിക്കുന്നു. അവരുടെ വിചാരണ അല്ലാഹുവിന്റെ അടുക്കലാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ – وَفِي رِوَايَةٍ: الْمُشْرِكِينَ – حَتَّى يَشْهَدُوا: أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنْ يَسْتَقْبِلُوا قِبْلَتَنَا، وَأَنْ يَأْكُلُوا ذَبِيحَتَنَا، وَأَنْ يُصَلُّوا صَلَاتَنَا. فَإِذَا فَعَلُوا ذَلِكَ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ، إِلَّا بِحَقِّهَا: لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَى الْمُسْلِمِينَ". (د,ن)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ - മറ്റൊരു റിപ്പോർട്ടിൽ ബഹുദൈവാരാധകർ - അല്ലാഹുവല്ലാതെ ആരാധനക്കർഹനില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ ദാസനും ദൂതനുമാണെന്നും പ്രഖ്യാപിക്കുകയും നമ്മുടെ ഖിബ്‌ലയെ അംഗീകരിക്കുകയും നാം അറുത്തത് ഭക്ഷിക്കുകയും നമ്മുടെ നിസ്കാരം പുന്തുടരുകയും ചെയ്യുന്നതുവരെ അവരോട് സമരം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ അവർ ചെയ്യുന്ന പക്ഷം അന്യായമായി അവരുടെ രക്തവും സമ്പത്തും കൈകാര്യം ചെയ്യുന്നത് നമുക്കു നിഷിദ്ധമാണ്; മുസ്‌ലിംകൾക്കുള്ള അവകാശങ്ങളും ബാധ്യതകളും അവർക്കും ബാധകമാണ്." (ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ: الْمُشْرِكِينَ – حَتَّى يَشْهَدُوا: أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنْ يَسْتَقْبِلُوا قِبْلَتَنَا، وَأَنْ يَأْكُلُوا ذَبِيحَتَنَا، وَأَنْ يُصَلُّوا صَلَاتَنَا. فَإِذَا فَعَلُوا ذَلِكَ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ، إِلَّا بِحَقِّهَا: لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَى الْمُسْلِمِينَ". (د,ن)', 'മറ്റൊരു നിവേദനിൽ ബഹുദൈവാരാധകർ - അല്ലാഹുവല്ലാതെ ആരാധനക്കർഹനില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ ദാസനും ദൂതനുമാണെന്നും പ്രഖ്യാപിക്കുകയും നമ്മുടെ ഖിബ്‌ലയെ അംഗീകരിക്കുകയും നാം അറുത്തത് ഭക്ഷിക്കുകയും നമ്മുടെ നിസ്കാരം പുന്തുടരുകയും ചെയ്യുന്നതുവരെ അവരോട് സമരം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ അവർ ചെയ്യുന്ന പക്ഷം അന്യായമായി അവരുടെ രക്തവും സമ്പത്തും കൈകാര്യം ചെയ്യുന്നത് നമുക്കു നിഷിദ്ധമാണ്; മുസ്‌ലിംകൾക്കുള്ള അവകാശങ്ങളും ബാധ്യതകളും അവർക്കും ബാധകമാണ്." (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً إِلَى الْحُرَقَاتِ، فَنَذِرُوا بِنَا، فَهَرَبُوا، فَأَدْرَكْنَا رَجُلًا، فَلَمَّا غَشِينَاهُ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، فَضَرَبْنَاهُ، حَتَّى قَتَلْنَاهُ، فَذَكَرْتُهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَنْ لَكَ بِلَا إِلَهَ إِلَّا اللَّهُ يَوْمَ الْقِيَامَةِ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّمَا قَالَهَا مَخَافَةَ السِّلَاحِ. قَالَ: "أَفَلَا شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ مِنْ أَجْلِ ذَلِكَ قَالَهَا أَمْ لَا؟ مَنْ لَكَ بِلَا إِلَهَ إِلَّا اللَّهُ يَوْمَ الْقِيَامَةِ". فَمَا زَالَ يَقُولُهَا حَتَّى وَدِدْتُ أَنِّي لَمْ أُسْلِمْ إِلَّا يَوْمَئِذٍ. (ق,د)', 'ഉസാമതുബ്നു സൈദ്(റ): റസൂൽ(സ) ഞങ്ങളെ ഹുറഖാത്ത് എന്ന സ്ഥലത്തേക്ക് യുദ്ധത്തിനയച്ചു. ഭയചകിതരായ ശത്രുക്കൾ ഓടിപ്പോയി. ഒരാൾ ഞങ്ങളുടെ പിടിയിലായി. ഞങ്ങൾ അവനെ വലയം ചെയ്തപ്പോൾ അവൻ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് പറഞ്ഞു. അപ്പോൾ ഞങ്ങൾ അവനെ വെട്ടിക്കൊലപ്പെടുത്തി. ഈ സംഭവം റസൂൽ(സ)യോട് ഞാൻ ഉണർത്തി. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ലാഇലാഹ ഇല്ലല്ലാഹു എന്ന് പറഞ്ഞ ഒരുത്തനെ വധിച്ചതിനുള്ള ശിക്ഷയിൽ നിന്നും അന്ത്യനാളിൽ നിന്നെ ആര് തടയും?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ആയുധം ഭയന്നതിനാൽ മാത്രമാണ് അയാൾ അത് പറഞ്ഞത്. റസൂൽ(സ) ചോദിച്ചു: "അയാളുടെ ഹൃദയം കീറി നോക്കിയാണോ അയാൾ അക്കാരണത്താലാണത് പറഞ്ഞത് എന്ന് നീ മനസ്സിലാക്കത്? ലാഇലാഹ ഇല്ലല്ലാഹ് എന്ന് പറഞ്ഞവനെ വധിച്ചതിനുള്ള ശിക്ഷയിൽ നിന്ന് അന്ത്യനാളിൽ നിന്നെ ആര് തടയും?" റസൂൽ(സ) ഈ വാക്ക് ആവർത്തിച്ചുകൊണ്ടിരുന്നു. ആ ദിവസത്തിന് മുമ്പ് ഞാൻ മുസ്‌ലിമായിരുന്നില്ലെങ്കിൽ എന്നുവരെ ഞാൻ ആഗ്രഹിച്ചു. (ബു,മു,ദ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 867, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ رَضِيَ اللَّهُ عَنْهُ قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ لَقِيتُ رَجُلًا مِنَ الْكُفَّارِ فَقَاتَلَنِي، فَضَرَبَ إِحْدَى يَدَيَّ بِالسَّيْفِ، ثُمَّ لَاذَ مِنِّي بِشَجَرَةٍ، فَقَالَ: أَسْلَمْتُ لِلَّهِ، أَفَأَقْتُلُهُ يَا رَسُولَ اللَّهِ بَعْدَ أَنْ قَالَهَا؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْتُلْهُ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهُ قَطَعَ يَدِي؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْتُلْهُ، فَإِنْ قَتَلْتَهُ فَإِنَّهُ بِمَنْزِلَتِكَ قَبْلَ أَنْ تَقْتُلَهُ، وَأَنْتَ بِمَنْزِلَتِهِ قَبْلَ أَنْ يَقُولَ كَلِمَتَهُ الَّتِي قَالَ". (ق,د)', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അവിശ്വാസികളിലൊരാളെ ഞാൻ കാണുകയും അവനെന്നോട് ഏറ്റുമുട്ടുകയും ചെയ്തു. എന്റെ ഒരു കൈ അവൻ വാളുകൊണ്ട് വെട്ടി. ശേഷം അവൻ ഒരു മരത്തിന്റെ മറവുപറ്റിക്കൊണ്ട് എന്നോട് പറഞ്ഞു: ഞാൻ അല്ലാഹുവിന് വഴങ്ങിയിരിക്കുന്നു (മുസ്‌ലിമായിരിക്കുന്നു). എന്നാൽ അത് പറഞ്ഞശേഷം അവനെ എനിക്ക് വധിക്കാൻ പറ്റുമോ? റസൂൽ(സ) പറഞ്ഞു: "അരുത്, അവനെ നീ വധിക്കരുത്." ഞാൻ ചോദിച്ചു: അവൻ എന്റെ കൈ മുറിച്ചില്ലേ? പ്രവാചകരേ? റസൂൽ(സ) പറഞ്ഞു: "നീ അവനെ വധിക്കരുത്. നീ അവനെ കൊല്ലുകയാണെങ്കിൽ കൊല്ലുന്നതിന്റെ മുമ്പുള്ള നിന്റെ സ്ഥാനത്തായിരിക്കും അവൻ. അവൻ ആ വാക്ക് പറയുന്നതിന് മുമ്പുള്ള അവന്റെ അവസ്ഥയിലേക്ക് നീയും മാറും." (ബു,മു,ദ)', 'الْمِقْدَادِ بْنِ الْأَسْوَدِ', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا أُخْرِجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَخْرَجُوا نَبِيَّهُمْ، إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، لَيَهْلِكُنَّ. فَنَزَلَتْ: {أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا وَإِنَّ اللَّهَ عَلَى نَصْرِهِمْ لَقَدِيرٌ} [الحج: ٣٩] فَعَرَفْتُ أَنَّهُ سَيَكُونُ قِتَالٌ. قَالَ ابْنُ عَبَّاسٍ: فَهِيَ أَوَّلُ آيَةٍ نَزَلَتْ فِي الْقِتَالِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മക്കയിൽനിന്നും പുറത്താക്കപ്പെട്ടപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അവർ തങ്ങളുടെ പ്രവാചകനെ പുറത്താക്കിയോ? ഇന്നാലില്ലാഹി വഇന്നാ ഇലൈഹി റാജിഊൻ (നാം അല്ലാഹുവിനുള്ളവരാണ്, നാം അവനിലേക്ക് തന്നെ മടങ്ങുന്നവരുമാണ്). തീർച്ചയായും അവർക്കു നാശമുണ്ടാകും. അപ്പോൾ വിശുദ്ധ ഖുർആനിലെ സൂക്തം അവതരിച്ചു: ''അവർ അക്രമിക്കപ്പെട്ട കാരണത്താൽ യുദ്ധം ചെയ്യാൻ അവർക്ക് അനുവാദം നൽകപ്പെട്ടിരിക്കുന്നു. അല്ലാഹു അവരെ സഹായിക്കുവാൻ കഴിവുള്ളവനാകുന്നു.'' (ഹജ്ജ്: 39) അപ്പോൾ ശേഷം യുദ്ധമുണ്ടാകുമെന്ന് ഞാൻ മനസിലാക്കി. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: യുദ്ധത്തെ സംബന്ധിച്ച് ഇറങ്ങിയ ആദ്യ സൂക്തമാണിത്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الحج: ٣٩', null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَأَصْحَابًا لَهُ – رَضِيَ اللَّهُ عَنْهُمْ – أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّا كُنَّا فِي عِزٍّ وَنَحْنُ مُشْرِكُونَ، فَلَمَّا آمَنَّا صِرْنَا أَذِلَّةً؟ فَقَالَ: "إِنِّي أُمِرْتُ بِالْعَفْوِ، فَلَا تُقَاتِلُوا". فَلَمَّا حَوَّلَنَا اللَّهُ إِلَى الْمَدِينَةِ أَمَرَنَا بِالْقِتَالِ فَكَفُّوا، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {أَلَمْ تَرَ إِلَى الَّذِينَ قِيلَ لَهُمْ كُفُّوا أَيْدِيَكُمْ وَأَقِيمُوا الصَّلَاةَ} [النساء: ٧٧]. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ)വും തന്റെ ഏതാനും അനുയായികളും മക്കയിൽവെച്ച് ഒരിക്കൽ റസൂൽ(സ)യെ സമീപിച്ചുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഞങ്ങൾ ബഹുദൈവവിശ്വാസികളായിരുന്നപ്പോൾ വളരെ അന്തസ്സിലായിരുന്നു. ഞങ്ങൾ വിശ്വാസികളായി മാറിയപ്പോൾ നിന്ദ്യരായിരിക്കുന്നല്ലോ? അവിടുന്ന് പറഞ്ഞു: "വിട്ടുവീഴ്ച ചെയ്യാനാണ് എന്നോട് കൽപിക്കപ്പെട്ടിരിക്കുന്നത്. അതുകൊണ്ട് നിങ്ങൾ യുദ്ധം ചെയ്യരുത്. പിന്നീട് അല്ലാഹു ഞങ്ങളെ മദീനയിലേക്കു മാറ്റിയപ്പോൾ യുദ്ധം ചെയ്യാൻ ഞങ്ങൾ കൽപിക്കപ്പെടുകയും അപ്പോൾ ജനങ്ങൾ വിട്ടു നിൽക്കുകയും ചെയതു. അപ്പോൾ അല്ലാഹു ഈ സൂക്തം ഇറക്കി: ''യുദ്ധം ചെയ്യുന്നതിൽ നിന്നും നിങ്ങൾ വിട്ടുനിൽക്കുകയും നിസ്കാരം നിലനിർത്തുകയും ചെയ്യുക എന്ന് പറയപ്പെട്ട ഒരു സമൂഹത്തെക്കുറിച്ച് താങ്കൾ ചിന്തിക്കുന്നില്ലേ?'' (നിസാഅ്: 77) (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النساء: ٧٧', null, 868, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بُعِثْتُ بِجَوَامِعِ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَبَيْنَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدِي". قَالَ أَبُو هُرَيْرَةَ: فَذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنْتُمْ تَنْتَثِلُونَهَا. (خ,ن)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "അർത്ഥഗാംഭീര്യമുള്ള സംക്ഷിപ്ത വാക്കുകൾ കൊണ്ട് ഞാൻ നിയോഗിക്കപ്പെട്ടു. ശത്രുമനസ്സുകളിൽ ഭയം നൽകി ഞാൻ സഹായിക്കപ്പെട്ടു. ഞാൻ ഉറങ്ങിക്കൊണ്ടിരിക്കുമ്പോൾ ഭൂമിയിലെ ഖജനാവുകളുടെ താക്കോൽ എന്റെ കൈകളിൽ നൽകപ്പെട്ടു." അബുഹുറൈറ(റ) പറയുന്നു: റസൂൽ(സ) യാത്രയായി. നിങ്ങൾ അവയെ പുറത്തെടുത്തു കൊണ്ടിരിക്കുന്നു. (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتُخْلِفَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ – وَفِي رِوَايَةٍ: وَكَانَ أَبُوبَكْرٍ بَعْدَهُ – وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ. قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: يَا أَبَا بَكْرٍ، كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللَّهُ، فَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ عَصَمَ مِنِّي نَفْسَهُ وَمَالَهُ إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ". – وَفِي رِوَايَةٍ: "فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّهَا". – قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: وَاللَّهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللَّهِ لَوْ مَنَعُونِي عَنَاقًا كَانُوا يُؤَدُّونَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهَا. فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ، فَعَرَفْتُ أَنَّهُ الْحَقُّ. (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യുടെ വേർപാടിന് ശേഷം അബൂബകർ(റ) ഖിലാഫത് സ്ഥാനം ഏറ്റെടുക്കുകയും - മറ്റൊരു ഉദ്ധരണിയിൽ: റസൂൽ(സ)ക്ക് ശേഷം അബൂബകർ(റ) വരികയും - അറബികളിൽ കുറേ പേർ സത്യനിഷേധികളാവുകയും ചെയ്തപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അബൂബക്കർ, എങ്ങനെയാണ് താങ്കൾ ജനങ്ങളോട് യുദ്ധം ചെയ്യുന്നത്? റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലെയോ: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് പറയുന്നതുവരെ ജനങ്ങളോട് യുദ്ധംചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടു. ഒരാളത് പറഞ്ഞാൽ അവകാശത്തോടുകൂടെ എടുക്കുന്നതല്ലാത്ത അവന്റെ സമ്പത്തും ശരീരവും എന്നിൽ നിന്ന് അവൻ സംരക്ഷിച്ചിരിക്കുന്നു. അവന്റെ വിചാരണ അല്ലാഹുവിന്റെ അടുക്കലാണ്." മറ്റൊരു നിവേദനം: "അവർ അപ്രകാരം പറഞ്ഞാൽ തങ്ങളുടെ രക്തവും സമ്പത്തും അവകാശത്തോടുകടെയല്ലാതെ ഞാൻ കൈകാര്യം ചെയ്യുന്നതിനെ അവർ സംരക്ഷിച്ചിരുക്കുന്നു." അബൂബകർ(റ) പറഞ്ഞു: അല്ലാഹുവിനെതന്നെയാണ് സത്യം, നിസ്കാരത്തിനും നിർബന്ധ ദാനത്തിനുമിടയിൽ വ്യത്യാസം കാണിക്കുന്നവരോട് തീർച്ചയായും ഞാൻ പോരാടുകതന്നെ ചെയ്യും. സകാത്ത് ധനത്തിലെ ബാദ്ധ്യതയാണ്. റസൂൽ(സ)ക്ക് കൊടുത്തുകൊണ്ടിരുന്ന കയർ ആരെങ്കിലും എനിക്ക് തരാതിരിക്കുകയാണെങ്കിൽ അതുകാരണം അവരോട് ഞാൻ യുദ്ധംചെയ്യും. ഉമർ(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം, തീർച്ചയായും യുദ്ധത്തിന് വേണ്ടി അബൂബകർ(റ)വിന്റെ ഹൃദയം അല്ലാഹു വിശാലമാക്കിക്കൊടുത്തുവെന്ന് ഞാൻ മനസ്സിലാക്കുകയും അത് സത്യമാണെന്ന് എനിക്ക് ബോധ്യപ്പെടുകയും ചെയ്തു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 869, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=8), 1, 'وَفِي رِوَايَةٍ: وَكَانَ أَبُوبَكْرٍ بَعْدَهُ – وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ. قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: يَا أَبَا بَكْرٍ، كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللَّهُ، فَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ عَصَمَ مِنِّي نَفْسَهُ وَمَالَهُ إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ". –', 'മറ്റൊരു നിവേദനം: "അവർ അപ്രകാരം പറഞ്ഞാൽ തങ്ങളുടെ രക്തവും സമ്പത്തും അവകാശത്തോടുകടെയല്ലാതെ ഞാൻ കൈകാര്യം ചെയ്യുന്നതിനെ അവർ സംരക്ഷിച്ചിരുക്കുന്നു." അബൂബകർ(റ) പറഞ്ഞു: അല്ലാഹുവിനെതന്നെയാണ് സത്യം, നിസ്കാരത്തിനും നിർബന്ധ ദാനത്തിനുമിടയിൽ വ്യത്യാസം കാണിക്കുന്നവരോട് തീർച്ചയായും ഞാൻ പോരാടുകതന്നെ ചെയ്യും. സകാത്ത് ധനത്തിലെ ബാദ്ധ്യതയാണ്. റസൂൽ(സ)ക്ക് കൊടുത്തുകൊണ്ടിരുന്ന കയർ ആരെങ്കിലും എനിക്ക് തരാതിരിക്കുകയാണെങ്കിൽ അതുകാരണം അവരോട് ഞാൻ യുദ്ധംചെയ്യും. ഉമർ(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം, തീർച്ചയായും യുദ്ധത്തിന് വേണ്ടി അബൂബകർ(റ)വിന്റെ ഹൃദയം അല്ലാഹു വിശാലമാക്കിക്കൊടുത്തുവെന്ന് ഞാൻ മനസ്സിലാക്കുകയും അത് സത്യമാണെന്ന് എനിക്ക് ബോധ്യപ്പെടുകയും ചെയ്തു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=8), 2, 'وَفِي رِوَايَةٍ: "فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّهَا". – قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: وَاللَّهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللَّهِ لَوْ مَنَعُونِي عَنَاقًا كَانُوا يُؤَدُّونَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهَا. فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ، فَعَرَفْتُ أَنَّهُ الْحَقُّ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ارْتَدَّتِ الْعَرَبُ، قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: يَا أَبَا بَكْرٍ، كَيْفَ تُقَاتِلُ الْعَرَبَ؟ فَقَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: إِنَّمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ". وَاللَّهِ لَوْ مَنَعُونِي عَنَاقًا مِمَّا كَانُوا يُعْطُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَيْهِ. قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: فَلَمَّا رَأَيْتُ رَأْيَ أَبِي بَكْرٍ قَدْ شُرِحَ عَلِمْتُ أَنَّهُ الْحَقُّ. (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) വഫാത്തായപ്പോൾ അറബികൾ അവിശ്വാസികളായി. ഉമർ(റ) ചോദിച്ചു: അബൂബകറേ, താങ്കൾ എന്തടിസ്ഥാനത്തിലാണ് അറബികളോട് യുദ്ധംചെയ്യുക? അബൂബകർ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുള്ളത് ഇതാണ്: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അല്ലാഹുവിന്റെ റസൂലാണെന്നും സാക്ഷ്യംവഹിക്കുകയും നിസ്കാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും ചെയ്യുന്നതുവരെ ജനങ്ങളോട് യുദ്ധംചെയ്യാൻ എന്നോട് കൽപിക്കപ്പെട്ടു." അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ)ക്ക് കൊടുത്തുകൊണ്ടിരുന്ന ഒരു കയർ അവർ എനിക്ക് നൽകാതിരിക്കുകയാണെങ്കിൽ അതിന്റെ പേരിൽ ഞാൻ അവരോട് യുദ്ധംചെയ്യും. ഉമർ(റ) പറഞ്ഞു: അബൂബകർ(റ)വിന്റെ അഭിപ്രായം വിശാലമാക്കപ്പെട്ടിരിക്കുന്നുവെന്ന് കണ്ടപ്പോൾ അത് വാസ്തവമാണെന്ന് എനിക്ക് ബോധ്യമായി. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "جَاهِدُوا الْمُشْرِكِينَ بِأَمْوَالِكُمْ وَأَيْدِيكُمْ وَأَلْسِنَتِكُمْ". (ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സമ്പത്ത് കൊണ്ടും കരങ്ങൾ കൊണ്ടും നാവുകൾ കൊണ്ടും ബഹുദൈവാരാധകരോട് നിങ്ങൾ പോരാടുക." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللَّهِ وَهُمْ كَذَلِكَ". (م)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമൂഹത്തിൽ നിന്ന് ഒരു വിഭാഗം സത്യത്തിൻമേൽ അതിജയിച്ചവരായി നിലകൊള്ളും. അവരെ നിന്ദ്യമാക്കിയവർക്ക് അവരെ ഒന്നും ചെയ്യാൻ കഴിയില്ല. അല്ലാഹുവിന്റെ കൽപന വന്നെത്തുംവരെ അവർ അതേ അവസ്ഥയിലായിരിക്കും." (മു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ الْمَهْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ مَسْلَمَةَ بْنِ مُخَلَّدٍ، وَعِنْدَهُ عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ، فَقَالَ عَبْدُ اللَّهِ: لَا تَقُومُ السَّاعَةُ إِلَّا عَلَى شِرَارِ الْخَلْقِ، هُمْ شَرٌّ مِنْ أَهْلِ الْجَاهِلِيَّةِ، لَا يَدْعُونَ اللَّهَ بِشَيْءٍ إِلَّا رَدَّهُ عَلَيْهِمْ. فَبَيْنَمَا هُمْ عَلَى ذَلِكَ أَقْبَلَ عُقْبَةُ بْنُ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ لَهُ مَسْلَمَةُ: يَا عُقْبَةُ اسْمَعْ مَا يَقُولُ عَبْدُ اللَّهِ، فَقَالَ عُقْبَةُ: هُوَ أَعْلَمُ، وَأَمَّا أَنَا فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَزَالُ عِصَابَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى أَمْرِ اللَّهِ، قَاهِرِينَ لِعَدُوِّهِمْ، لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ، حَتَّى تَأْتِيَهُمُ السَّاعَةُ وَهُمْ عَلَى ذَلِكَ". فَقَالَ عَبْدُ اللَّهِ: أَجَلْ. "ثُمَّ يَبْعَثُ اللَّهُ رِيحًا كَرِيحِ الْمِسْكِ، مَسُّهَا مَسُّ الْحَرِيرِ، فَلَا تَتْرُكُ نَفْسًا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنَ الْإِيمَانِ إِلَّا قَبَضَتْهُ، ثُمَّ يَبْقَى شِرَارُ النَّاسِ، عَلَيْهِمْ تَقُومُ السَّاعَةُ". (م)', 'അബ്ദുർറഹ്മാനുബ്നു ശിമാസതുൽ മഹ്‌രി(റ): ഞാൻ മസ്‌ലമതുബ്നു മുഖല്ലദ്(റ)വിന്റെ കൂടെയായിരുന്നു. അദ്ദേഹത്തിന്റെ കൂടെ അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)വും ഉണ്ടായിരുന്നു. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: അന്ത്യദിനം ദുഷിച്ച സൃഷ്ടികളുടെ മേലേ ഉണ്ടാകൂ. അവർ ജാഹിലിയ്യാ കാലക്കാരേക്കൾ ദുഷിച്ചവരായിരിക്കും. അവർ അല്ലാഹുവിനോട് ചോദിക്കുന്നതത്രയും അവൻ തടയും. അപ്പോൾ ഉഖ്ബതുബ്നു ആമിർ(റ) അവരുടെ അടുത്തേക്ക് വന്നു. അദ്ദേഹത്തോട് മസ്‌ലമ(റ) പറഞ്ഞു: ഓ ഉഖ്ബാ, താങ്കൾ അബ്ദുല്ല(റ) പറയുന്നത് കേൾക്കുക. അപ്പോൾ ഉഖ്ബ(റ) പറഞ്ഞു: അദ്ദേഹമാണ് ഏറ്റവും അറിയുന്നവൻ. എന്നാൽ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "ശത്രുക്കളെ അതിജയിച്ച്, അല്ലാഹുവിന്റെ കൽപനയുടെ മേൽ യുദ്ധം ചെയ്യുന്ന ഒരു വിഭാഗം എന്റെ സമൂഹത്തിൽ ഉണ്ടായിക്കൊണ്ടിരിക്കും. അവരെ എതിർക്കുന്നവർക്ക് അവരെ ഒന്നും ചെയ്യാൻ കഴിയില്ല. അങ്ങനെ നിലകൊള്ളുന്ന നിലക്ക് അവർക്ക് അന്ത്യദിനം വന്നുചേരും." അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: അതെ, "പിന്നെ അല്ലാഹു കസ്തൂരി ഗന്ധമുള്ള ഒരു കാറ്റയക്കും. അതിന് പട്ടിന്റെ നൈർമല്യമാണ്. ഹൃദയത്തിൽ നെൽമണിയോളം ഈമാനുള്ളവനെയൊക്കെ ആ കാറ്റ് പിടികൂടും. പിന്നെ ദുഷിച്ച ജനങ്ങൾ അവശേഷിക്കും. അവർക്ക് മേലാണ് അന്ത്യദിനം കടന്നുവരിക." (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ الْمَهْرِيِّ', 'അബ്ദുർറഹ്മാനുബ്നു ശിമാസതുൽ മഹ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 870, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ أَهْلُ الْغَرْبِ ظَاهِرِينَ عَلَى الْحَقِّ حَتَّى تَقُومَ السَّاعَةُ". (م)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പടിഞ്ഞാറ് നിവാസികൾ അന്ത്യദിനം വരെ സത്യത്തിന്മേൽ അതിജയിച്ചവരായി നിലനിൽക്കും." (മു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ، ظَاهِرِينَ عَلَى مَنْ نَاوَأَهُمْ، حَتَّى يُقَاتِلَ آخِرُهُمُ الْمَسِيحَ الدَّجَّالَ". (د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമൂഹത്തിൽ നിന്നൊരു വിഭാഗം സത്യത്തിന് വേണ്ടി യുദ്ധം ചെയ്തുകൊണ്ടിരിക്കും. അവരെ നേരിട്ടവരെയൊക്കെ അവർ അതിജയിക്കും. അങ്ങനെ അവരിലെ അവസാനത്തവർ മസീഹ് ദജ്ജാലിനോട് യുദ്ധം ചെയ്യും." (ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، أَيُّ النَّاسِ أَفْضَلُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مُؤْمِنٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ". قَالُوا: ثُمَّ مَنْ؟ قَالَ: "مُؤْمِنٌ فِي شِعْبٍ مِنَ الشِّعَابِ يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ". (خ,ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: ദൈവദൂതരേ, മനുഷ്യരിൽ ഏറ്റവും ഉൽകൃഷ്ടർ· ആരാണ്? അവിടുന്ന് പറഞ്ഞു: "ധനം കൊണ്ടും ശരീരം കൊണ്ടും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്ന സത്യവിശ്വാസി." അവർ ചോദിച്ചു: പിന്നീടാര്? അവിടുന്ന് പറഞ്ഞു: "ഏതെങ്കിലും ഒരു മലഞ്ചെരുവിൽ അല്ലാഹുവിനെ സൂക്ഷിച്ചുകൊണ്ടും മനുഷ്യർക്ക് താൻ കാരണം ബുദ്ധിമുട്ട് വരുത്താതെയും ജീവിക്കുന്നവൻ." (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ، وَاللَّهُ أَعْلَمُ بِمَنْ يُجَاهِدُ فِي سَبِيلِهِ، كَمَثَلِ الصَّائِمِ الْقَائِمِ، وَتَوَكَّلَ اللَّهُ لِلْمُجَاهِدِ فِي سَبِيلِهِ بِأَنْ يَتَوَفَّاهُ أَنْ يُدْخِلَهُ الْجَنَّةَ، أَوْ يَرْجِعَهُ سَالِمًا مَعَ أَجْرٍ أَوْ غَنِيمَةٍ". (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവന്റെ സ്ഥിതി - അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവൻ ആരാണെന്ന് അവന്ന് മാത്രമേ അറിയൂ - നോമ്പനുഷ്ഠിക്കുകയും നമസ്കരിക്കുകയും ചെയ്യുന്നവന്റേതു പോലെയാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവൻ മരിക്കുന്ന പക്ഷം അവന് സ്വർഗ്ഗം പ്രദാനംചെയ്യുമെന്നും മറിച്ച് സുരക്ഷിതനായി യുദ്ധത്തിൽ നിന്ന് മടങ്ങുകയാണെങ്കിൽ അല്ലാഹുവിൽനിന്നുള്ള പുണ്യവും യുദ്ധത്തിൽ കൈവന്ന ധനവും അവന്ന് ലഭിക്കുമെന്നും അല്ലാഹു ഏറ്റെടുത്തിരിക്കുന്നു." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 871, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: دُلَّنِي عَلَى عَمَلٍ يَعْدِلُ الْجِهَادَ، قَالَ: "لَا أَجِدُهُ". قَالَ: "هَلْ تَسْتَطِيعُ إِذَا خَرَجَ الْمُجَاهِدُ أَنْ تَدْخُلَ مَسْجِدَكَ فَتَقُومَ وَلَا تَفْتُرَ، وَتَصُومَ وَلَا تُفْطِرَ". قَالَ: وَمَنْ يَسْتَطِيعُ ذَلِكَ؟ (خ,م,ن)', 'അബൂഹുറൈറ(റ): ഒരാൾ റസൂൽ(സ)യോട് പറഞ്ഞു: ധർമ്മയുദ്ധത്തിന് തുല്യമായ ഒരു സൽകർമ്മം അവിടുന്ന് പറഞ്ഞുതന്നാലും. അവിടുന്ന് പറഞ്ഞു: "അങ്ങനെയൊരു പ്രവർത്തനം ഞാൻ കാണുന്നില്ല." എന്നിട്ട് പറഞ്ഞു: "യോദ്ധാക്കൾ യുദ്ധത്തിന് പോയിക്കഴിഞ്ഞാൽ നിനക്ക് നിന്റെ പള്ളിയിൽ ചെന്ന് അലസത തോന്നാതെ നിസ്കരിച്ചുകൊണ്ടിരിക്കാനും തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കാനും കഴിയുമോ?" അയാൾ ചോദിച്ചു: ആർക്കാണതിനു കഴിയുക? (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','م','ن']::text[], array['ബു','മു','ന']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَضَمَّنَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ، لَا يُخْرِجُهُ إِلَّا جِهَادًا فِي سَبِيلِي وَإِيمَانًا بِي وَتَصْدِيقًا بِرُسُلِي، فَهُوَ عَلَيَّ ضَامِنٌ أَنْ أُدْخِلَهُ الْجَنَّةَ، أَوْ أَرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ، نَائِلًا مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، مَا مِنْ كَلْمٍ يُكْلَمُ فِي سَبِيلِ اللَّهِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهِ حِينَ كُلِمَ، لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْلَا أَنْ يَشُقَّ عَلَى الْمُسْلِمِينَ مَا قَعَدْتُ خِلَافَ سَرِيَّةٍ تَغْزُو فِي سَبِيلِ اللَّهِ أَبَدًا، وَلَكِنْ لَا أَجِدُ سَعَةً فَأَحْمِلَهُمْ، وَلَا يَجِدُونَ سَعَةً، وَيَشُقُّ عَلَيْهِمْ أَنْ يَتَخَلَّفُوا عَنِّي. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوَدِدْتُ أَنِّي أَغْزُو فِي سَبِيلِ اللَّهِ فَأُقْتَلُ، ثُمَّ أَغْزُو فَأُقْتَلُ، ثُمَّ أَغْزُو فَأُقْتَلُ". (ق,ن,جه)', 'അബൂഹുറൈറ(റ) റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ വഴിയിൽ പുറപ്പെട്ടവർക്ക് അവൻ സംരക്ഷണം നൽകും. എന്റെ പ്രവാചകരെ കൊണ്ട് വാസ്തവമാക്കലും എന്നെക്കൊണ്ടുള്ള വിശ്വാസവും എന്റെ മാർഗ്ഗത്തിലുള്ള ധർമ്മസമരവും മാത്രം ലക്ഷ്യമാക്കി പുറപ്പെടുന്നവനാണവൻ. അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയോ അല്ലെങ്കിൽ തനിക്ക് ലഭിക്കുന്ന പ്രതിഫലത്തോടും യുദ്ധമുതലിനോടും കൂടെ പുറപ്പെട്ട വീട്ടിൽ തിരിച്ചെത്തിക്കുകയോ ചെയ്യൽ എന്റെ ഉത്തരവാദിത്തമാണ്. മുഹമ്മദ്(സ)യുടെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ സത്യം, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പറ്റിയ ഏതൊരു മുറിവും പാരത്രികലോകത്ത് അത് ഏറ്റ അതേരൂപത്തിൽ വരാതിരിക്കുകയില്ല. അതിന്റെ നിറം രക്തത്തിന്റേതും വാസന കസ്തൂരിയുടേതും ആയിരിക്കും. മുഹമ്മദ്(സ)യുടെ ശരീരം ആരുടെ അധികാരത്തിലാണോ അവനെതന്നെ സത്യം, മുസ്‌ലിംകൾക്ക് ബുദ്ധിമുട്ടാകുമായിരുന്നില്ലെങ്കിൽ അല്ലാഹുവിന്റെ മാർഗത്തിൽ പോരാടുന്ന ഒരു സംഘത്തോടൊപ്പവും ഞാൻ ഒരിക്കലും വരാതിരിക്കുമായിരുന്നില്ല. പക്ഷേ, അവരെ കൊണ്ടുപോകാനുള്ള ഐശ്വര്യം എനിക്ക് ലഭിച്ചില്ല. അവർക്കും ഐശ്വര്യമില്ല. എന്നെത്തൊട്ട് പിന്തൽ അവർക്ക് ബുദ്ധിമുട്ടാവുകയും ചെയ്യുന്നു. മുഹമ്മദ്(സ)യുടെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ സത്യം, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുകയും അങ്ങനെ കൊല്ലപ്പെടുകയും വീണ്ടും യുദ്ധം ചെയ്യുകയും കൊല്ലപ്പെടുകയും വീണ്ടും യുദ്ധം ചെയ്യുകയും കൊല്ലപ്പെടുകയും ചെയ്യുന്നത് ഞാൻ ഇഷ്ടപ്പെടുന്നു." (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَجُلٌ: مَا أُبَالِي أَنْ لَا أَعْمَلَ عَمَلًا بَعْدَ الْإِسْلَامِ إِلَّا أَنْ أَسْقِيَ الْحَاجَّ، وَقَالَ آخَرُ: مَا أُبَالِي أَنْ لَا أَعْمَلَ عَمَلًا بَعْدَ الْإِسْلَامِ إِلَّا أَنْ أَعْمُرَ الْمَسْجِدَ الْحَرَامَ، وَقَالَ آخَرُ: الْجِهَادُ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِمَّا قُلْتُمْ، فَزَجَرَهُمْ عُمَرُ رَضِيَ اللَّهُ عَنْهُ وَقَالَ: لَا تَرْفَعُوا أَصْوَاتَكُمْ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَوْمُ الْجُمُعَةِ، وَلَكِنْ إِذَا صَلَّيْتُ الْجُمُعَةَ دَخَلْتُ فَاسْتَفْتَيْتُهُ فِيمَا اخْتَلَفْتُمْ فِيهِ. فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {أَجَعَلْتُمْ سِقَايَةَ الْحَاجِّ وَعِمَارَةَ الْمَسْجِدِ الْحَرَامِ كَمَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ...} الْآيَةُ إِلَى آخِرِهَا. (م)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): ഞാൻ റസൂൽ(സ)യുടെ മിമ്പറിന്റെ അടുത്തായിരിക്കുമ്പോൾ ഒരു വ്യക്തി പറഞ്ഞു: മുസ്‌ലിമായതിന് ശേഷം ഹജ്ജാജിമാർക്ക് വെള്ളം നൽകുക എന്നതല്ലാതെ ഒരു കർമ്മവും ചെയ്യണമെന്ന് എനിക്ക് താൽപര്യമില്ല. മറ്റൊരു വ്യക്തി പറഞ്ഞു: മുസ്‌ലിമായ ശേഷം മസ്ജിദുൽ ഹറാമിന്റെ പരിപാലനമല്ലാതെ ഒരു കർമ്മവും ചെയ്യണമെന്നെനിക്ക് താൽപര്യമില്ല. മറ്റൊരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള സമരം നിങ്ങൾ പറഞ്ഞ കാര്യങ്ങളേക്കാൾ ഉത്തമമാണ്. ഇതുകേട്ടപ്പോൾ ഉമർ(റ) അവരെ സംസാരത്തിൽ നിന്ന് വിലക്കി. എന്നിട്ടവരോട് പറഞ്ഞു: "ഇത് വെള്ളിയാഴ്ച ദിവസമാണ്. അതുകൊണ്ട് റസൂൽ(സ)യുടെ മിമ്പറിന്റെയടുത്ത് വെച്ച് നിങ്ങൾ ശബ്ദമുയർത്തരുത്. ഇന്ന് ജുമുഅ നമസ്കാരത്തിന് ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുപോയി നിങ്ങൾക്ക് അഭിപ്രായ വ്യത്യാസമുള്ള ഈ വിഷയത്തിൽ തീരുമാനമുണ്ടാക്കിത്തരാം. അപ്പോഴാണ് അല്ലാഹു ഈ സൂക്തമിറക്കുന്നത്: ''ഹജ്ജാജിമാർക്ക് വെള്ളം നൽകലും മസ്ജിദുൽ ഹറാമിനെ പരിപാലിക്കലും അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നത് പോലെയാണെന്ന് നിങ്ങൾ കരുതുന്നുണ്ടോ.'' (മു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سُئِلَ: أَيُّ الْمُؤْمِنِينَ أَكْمَلُ إِيمَانًا؟ قَالَ: "رَجُلٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ، وَرَجُلٌ يَعْبُدُ اللَّهَ فِي شِعْبٍ مِنَ الشِّعَابِ، قَدْ كُفِيَ النَّاسُ شَرَّهُ". (ق,د,ت,ن,جه)', 'അബൂസഈദ്(റ): നബി(സ)യോട് ഇപ്രകാരം ചോദിക്കപ്പെട്ടു: വിശ്വാസികളിൽ പൂർണ്ണനായ വിശ്വാസിയാരാണ്? തിരുമേനി(സ) പറഞ്ഞു: "സ്വന്തം ധനം കൊണ്ടും ശരീരം കൊണ്ടും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവനും, ജനങ്ങൾക്ക് ശല്യം ചെയ്യാതെ ഏതെങ്കിലുമൊരു മലമടക്കിൽ പോയി അല്ലാഹുവിനെ ആരാധിക്കുന്നവനും." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ؟ مَا يَعْدِلُ الْجِهَادَ؟ قَالَ: "إِنَّكُمْ لَا تَسْتَطِيعُونَهُ". فَرَدُّوا عَلَيْهِ مَرَّتَيْنِ أَوْ ثَلَاثًا، كُلُّ ذَلِكَ يَقُولُ: "لَا تَسْتَطِيعُونَهُ". فَقَالَ فِي الثَّالِثَةِ: "مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ مَثَلُ الْقَائِمِ الصَّائِمِ، الَّذِي لَا يَفْتُرُ مِنْ صَلَاةٍ وَلَا صِيَامٍ، حَتَّى يَرْجِعَ الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യോട് ഇപ്രകാരം ചോദിക്കപ്പെട്ടു: ധർമ്മസമരത്തോട് സമാനമാകുന്ന കാര്യം എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്കത് ചെയ്യാൻ കഴിയുകയില്ല." അവർ രണ്ടോ മൂന്നോ പ്രാവശ്യം ആ ചോദ്യമാവർത്തിച്ചു. "നിങ്ങൾക്ക് അത് ചെയ്യാൻ കഴിയില്ല" എന്ന് അതിനെല്ലാം തിരുമേനി(സ) മറുപടിയും പറഞ്ഞു. മൂന്നാം പ്രാവശ്യം റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരടിക്കുന്നവൻ താൻ മടങ്ങുന്ന സമയം വരെ വിശ്രമമില്ലാതെ നമസ്കരിക്കുകയും നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുന്നവനെപ്പോലെയാണ്." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَقُولُ اللَّهُ عَزَّ وَجَلَّ: الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ هُوَ عَلَيَّ ضَامِنٌ: إِنْ قَبَضْتُهُ أَوْرَثْتُهُ الْجَنَّةَ، وَإِنْ رَجَعْتُهُ رَجَعْتُهُ بِأَجْرٍ أَوْ غَنِيمَةٍ". صَحِيحٌ. (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: എന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവന്റെ ആത്മാവിനെ ഞാൻ പിടിച്ചാൽ അവന് സ്വർഗ്ഗം നൽകുമെന്നതിനും അവനെ ജീവനോടെ മടക്കിയാൽ പ്രതിഫലം കൊണ്ടോ യുദ്ധമുതൽ കൊണ്ടോ മടക്കുമെന്നതിനും ഞാൻ ഉത്തരവാദിയാണ്." ഹദീസ് സ്വഹീഹാണ്. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 873, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ؟ رَجُلٌ مُمْسِكٌ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ. أَلَا أُخْبِرُكُمْ بِالَّذِي يَتْلُوهُ؟ رَجُلٌ مُعْتَزِلٌ فِي غُنَيْمَةٍ لَهُ يُؤَدِّي حَقَّ اللَّهِ فِيهَا. أَلَا أُخْبِرُكُمْ بِشَرِّ النَّاسِ؟ رَجُلٌ يُسْأَلُ بِاللَّهِ وَلَا يُعْطِي بِهِ". حَسَنٌ. (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിൽ ഏറ്റവും ഉത്തമനെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചുതരട്ടെയോ! അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാൻ തന്റെ കുതിരയുടെ കടിഞ്ഞാൺ പിടിക്കുന്നവനാണവൻ. അവന്റെ അടുത്ത സ്ഥാനക്കാരനെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ! തന്റെ ആട്ടിൻപറ്റത്തോടൊപ്പം ഒഴിഞ്ഞുകഴിയുകയും അതിലുള്ള അല്ലാഹുവിന്റെ അവകാശം കൊടുത്തുവീട്ടുകയും ചെയ്യുന്നവനാണവൻ. ജനങ്ങളിൽ ഏറ്റവും മോശക്കാരനെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ! അല്ലാഹുവിനെ മുൻനിർത്തി ചോദിക്കപ്പെടുമ്പോൾ അവനെ മുൻനിർത്തി ആ കാര്യം നൽകാത്തവനാണവൻ." ഹദീസ് ഹസനാണ്. (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ حَقٌّ عَلَى اللَّهِ عَوْنُهُمْ: الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ، وَالْمُكَاتَبُ الَّذِي يُرِيدُ الْأَدَاءَ، وَالنَّاكِحُ الَّذِي يُرِيدُ الْعَفَافَ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്നുപേരെ സഹായിക്കൽ അല്ലാഹുവിന്റെ കടമയാണ്: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവൻ, കടം കൊടുത്തു വീട്ടണമെന്നാഗ്രഹിക്കുന്ന മോചനപത്രം എഴുതപ്പെട്ട അടിമ, സച്ചരിതത്വം ആഗ്രഹിച്ച് വിവാഹം കഴിക്കുന്നവൻ." (തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْأَعْمَالِ أَفْضَلُ؟ أَوْ: أَيُّ الْأَعْمَالِ خَيْرٌ؟ قَالَ: "إِيمَانٌ بِاللَّهِ وَرَسُولِهِ". قِيلَ: ثُمَّ أَيُّ شَيْءٍ؟ قَالَ: "الْجِهَادُ سَنَامُ الْعَمَلِ". قِيلَ: ثُمَّ أَيُّ شَيْءٍ يَا رَسُولَ اللَّهِ؟ قَالَ: "ثُمَّ حَجٌّ مَبْرُورٌ". حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: ഏത് പ്രവർത്തനമാണ് ഏറ്റവും ശ്രേഷ്ഠമായത്, അല്ലെങ്കിൽ ഏത് കർമ്മമാണ് ഏറ്റവും ഉത്തമം? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിക്കലാണ്." പിന്നെയേതാണ് ഉത്തമം എന്ന് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ധർമ്മസമരം ഏറ്റവും മുകളിൽ നിൽക്കുന്ന കർമ്മമാണ്." വീണ്ടും ചോദിക്കപ്പെട്ടു: പിന്നെയേതാണ് ഉത്തമം, അല്ലാഹുവിന്റെ റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "സ്വീകാര്യമായ ഹജ്ജ്." (ബു,മു,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِلشَّهِيدِ عِنْدَ اللَّهِ سِتُّ خِصَالٍ: يُغْفَرُ لَهُ فِي أَوَّلِ دَفْعَةٍ، وَيَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُجَارُ مِنْ عَذَابِ الْقَبْرِ، وَيَأْمَنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَيُوضَعُ عَلَى رَأْسِهِ تَاجُ الْوَقَارِ: الْيَاقُوتَةُ مِنْهَا خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَيُزَوَّجُ اثْنَتَيْنِ وَسَبْعِينَ زَوْجَةً مِنَ الْحُورِ الْعِينِ، وَيُشَفَّعُ فِي سَبْعِينَ مِنْ أَقَارِبِهِ". حَسَنٌ صَحِيحٌ غَرِيبٌ. (ت,جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): റസൂൽ(സ) പറഞ്ഞു: "രക്തസാക്ഷിക്ക് അല്ലാഹുവിങ്കൽ ആറുകാര്യങ്ങളുണ്ട്: ആദ്യനിമിഷം തന്നെ അവന് പൊറുക്കപ്പെടും, സ്വർഗ്ഗത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ ദർശിക്കും, ഖബ്റിലെ ശിക്ഷയിൽ നിന്ന് അവൻ സംരക്ഷിക്കപ്പെടുകയും ഏറ്റവും വലിയ വിപത്തിൽ നിന്ന് അവന് നിർഭയത്വം ലഭിക്കുകയും ചെയ്യും, ആദരവിന്റെ കിരീടം അവന്റെ തലയുടെ മുകളിൽ വെക്കപ്പെടും. അതിൽ നിന്നുള്ള ഒരു മുത്ത് (യാഖൂത്) പോലും ഐഹികലോകത്തേക്കാളും അതിലുള്ളതിനേക്കാളും ഉത്തമമായിരിക്കും, ഹൂറുൽ ഈനുകളിൽ നിന്ന് എഴുപത്തിരണ്ട് പേരെ അവന് ഭാര്യമാരായി നൽകപ്പെടും, തന്റെ സ്വന്തക്കാരിൽ നിന്ന് എഴുപത് പേർക്ക് ശുപാർശ ചെയ്യാൻ അവന് അധികാരം നൽകപ്പെടും." ഹദീസ് ഹസനും സ്വഹീഹും ഗരീബുമാണ്. (തു,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 874, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَفْدُ اللَّهِ عَزَّ وَجَلَّ ثَلَاثَةٌ: الْغَازِي، وَالْحَاجُّ، وَالْمُعْتَمِرُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ സംഘം മൂന്ന് പേരാണ്: യോദ്ധാവ്, ഹജ്ജ് നിർവഹിക്കുന്നവൻ, ഉംറ ചെയ്യുന്നവൻ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَأَلَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ خَيْرٌ؟ قَالَ: "إِيمَانٌ بِاللَّهِ، وَجِهَادٌ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ". (ن)', 'അബൂദർറ്(റ): അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: "ഏതുകർമ്മമാണ് ഉത്തമം?" നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലുള്ള വിശ്വാസവും അവന്റെ മാർഗ്ഗത്തിലുള്ള സമരവും." (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ – وَاللَّهُ أَعْلَمُ بِمَنْ يُجَاهِدُ فِي سَبِيلِهِ – كَمَثَلِ الصَّائِمِ الْقَائِمِ الْخَاشِعِ الرَّاكِعِ السَّاجِدِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവൻ - തന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവർ ആരാണെന്ന് അല്ലാഹുവിനാണ് അറിയുക - നോമ്പനുഷ്ഠിക്കുന്ന, നമസ്കരിക്കുന്ന, ഭയഭക്തിയുള്ള, അല്ലാഹുവിനെ വഴങ്ങുന്ന, അവന് സാഷ്ടാംഗം ചെയ്യുന്ന ഒരു വ്യക്തിയെപ്പോലെയാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "انْتَدَبَ اللَّهُ عَزَّ وَجَلَّ لِمَنْ يَخْرُجُ فِي سَبِيلِهِ – لَا يُخْرِجُهُ إِلَّا الْإِيمَانُ بِي وَالْجِهَادُ فِي سَبِيلِي – أَنَّهُ ضَامِنٌ حَتَّى أُدْخِلَهُ الْجَنَّةَ بِأَيِّهِمَا كَانَ: إِمَّا بِقَتْلٍ أَوْ وَفَاةٍ، أَوْ أَرُدَّهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ نَالَ مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "തന്നിലുള്ള വിശ്വാസവും തന്റെ മാർഗ്ഗത്തിലുള്ള സമരവും ലക്ഷ്യം വെച്ചിറങ്ങുന്ന വ്യക്തിക്ക് അല്ലാഹു ജാമ്യം നൽകുന്നതാണ്. അവൻ മരിക്കുകയോ കൊല്ലപ്പെടുകയോ ചെയ്താൽ അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുമെന്ന്, അല്ലെങ്കിൽ തനിക്ക് ലഭിക്കുന്ന പ്രതിഫലത്തോടും യുദ്ധമുതലോടുമൊപ്പം താൻ പുറപ്പെട്ട സ്ഥലത്തേക്ക് അവനെ മടക്കുമെന്ന്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا أَبَا سَعِيدٍ، مَنْ رَضِيَ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا، وَجَبَتْ لَهُ الْجَنَّةُ". قَالَ: فَعَجِبَ لَهَا أَبُو سَعِيدٍ، قَالَ: أَعِدْهَا عَلَيَّ يَا رَسُولَ اللَّهِ. فَفَعَلَ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَأُخْرَى يُرْفَعُ بِهَا الْعَبْدُ مِائَةَ دَرَجَةٍ فِي الْجَنَّةِ، مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ". قَالَ: وَمَا هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: "الْجِهَادُ فِي سَبِيلِ اللَّهِ، الْجِهَادُ فِي سَبِيلِ اللَّهِ". (م,ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "അബൂസഈദേ, ആരെങ്കിലും അല്ലാഹുവിനെ സംരക്ഷകനായും ഇസ്‌ലാമിനെ മതമായും മുഹമ്മദ്(സ)യെ നബിയായും തൃപ്തിപ്പെട്ടാൽ അവന്ന് സ്വർഗ്ഗം നിർബന്ധമായിരിക്കുന്നു." ഇതുകേട്ട് അബൂസഈദ്(റ) അത്ഭുതപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അതെനിക്ക് ഒന്നുകൂടെ പറഞ്ഞുതരൂ റസൂലേ. അപ്പോൾ റസൂൽ(സ) അപ്രകാരം ചെയ്തു. ശേഷം പറഞ്ഞു: "മറ്റൊരു കാര്യമുണ്ട്, അതുകൊണ്ട് അടിമക്ക് സ്വർഗത്തിൽ നൂറ് പദവികൾ ഉയർത്തപ്പെടും. അവയിൽ ഓരോരോ പദവികൾക്കിടയിലുള്ള ദൂരം ആകാശഭൂമികൾക്കിടയിലുള്ള ദൂരം പോലെയാണ്." അബൂസഈദ്(റ) ചോദിച്ചു: അത് എന്താണ് റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള സമരം, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള സമരം." (മു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 875, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَقَامَ الصَّلَاةَ، وَآتَى الزَّكَاةَ، وَمَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا، كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يَغْفِرَ لَهُ، هَاجِرًا وَمَاتَ فِي مَوْلِدِهِ". فَقُلْنَا: يَا رَسُولَ اللَّهِ، أَلَا نُخْبِرُ بِهَا النَّاسَ فَيَسْتَبْشِرُوا بِهَا؟ فَقَالَ: "إِنَّ لِلْجَنَّةِ مِائَةَ دَرَجَةٍ، بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِهِ. وَلَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ، وَلَا أَجِدُ مَا أَحْمِلُهُمْ عَلَيْهِ، وَلَا تَطِيبُ أَنْفُسُهُمْ أَنْ يَتَخَلَّفُوا بَعْدِي، مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ. وَلَوَدِدْتُ أَنِّي أُقْتَلُ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلَ". (ن)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നമസ്കാരം നിലനിർത്തുകയും, സക്കാത്ത് നൽകുകയും, അല്ലാഹുവിനോട് ഒന്നും പങ്കുചേർക്കാതെ മരിക്കുകയും ചെയ്താൽ അവൻ പാലായനം നടത്തിയവനാണെങ്കിലും സ്വന്തം നാട്ടിൽ മരിച്ചവനാണെങ്കിലും അവന് പൊറുത്ത് കൊടുക്കൽ അല്ലാഹുവിന്റെ കടമയാണ്." ഞങ്ങൾ ചോദിച്ചു: റസൂലേ, ഞങ്ങളിത് ജനങ്ങളോട് പറയട്ടെ? എന്നാലവർക്ക് സന്തോഷമാകും. റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിൽ നൂറ് സ്ഥാനങ്ങളുണ്ട്. അതിൽ ഓരോ സ്ഥാനങ്ങൾക്കുമിടയിലുള്ള അകലം ആകാശഭൂമികൾക്കിടയിലുള്ള അകലം പോലെയാണ്. അവയെ തന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവർക്കായി അല്ലാഹു ഒരുക്കിവെച്ചതാണ്. വിശ്വാസികൾക്ക് പ്രയാസമില്ലാതിരിക്കുകയും അവരെ കൂട്ടിക്കൊണ്ട് പോകാൻ സൗകര്യം ഇല്ല എന്ന പ്രശ്നവും, അവരെ ഇവിടെ നിർത്തി ഞാൻ പോകുന്നത് അവർക്കിഷ്ടമില്ല എന്ന പ്രശ്നവും ഇല്ലാതിരിക്കുകയും ചെയ്യുകയാണെങ്കിൽ ഞാൻ ഒരു യുദ്ധസംഘത്തെത്തൊട്ടും വിട്ടുനിൽക്കുമായിരുന്നില്ല. ഞാൻ കൊല്ലപ്പെടുകയും വീണ്ടും ജീവൻ നൽകപ്പെടുകയും വീണ്ടും കൊല്ലപ്പെടുകയും ചെയ്തെങ്കിലെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു." (ന)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ مَضْمُونٌ عَلَى اللَّهِ: إِمَّا أَنْ يَكْفِتَهُ إِلَى مَغْفِرَتِهِ وَرَحْمَتِهِ، وَإِمَّا أَنْ يَرْجِعَهُ بِأَجْرٍ وَغَنِيمَةٍ. وَمَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ كَمَثَلِ الصَّائِمِ الْقَائِمِ الَّذِي لَا يَفْتُرُ، حَتَّى يَرْجِعَ". فِي إِسْنَادِهِ ضَعِيفٌ. (جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവന് അല്ലാഹു ജാമ്യം നിൽക്കുന്നതാണ്, ഒന്നുകിൽ തന്റെ അനുഗ്രഹത്തിലേക്കും പാപമോചനത്തിലേക്കും അവനെ ചേർക്കാൻ, അല്ലെങ്കിൽ പ്രതിഫലത്തോടും യുദ്ധമുതലോടും കൂടെ അവനെ മടക്കാൻ. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവൻ താൻ മടങ്ങും വരെ വിശ്രമമില്ലാതെ നിസ്കരിക്കുകയും നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുന്നവനെപ്പോലെയാണ്." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: عَرَضَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ فِي الْقِتَالِ، وَأَنَا ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْنِي، وَعَرَضَنِي يَوْمَ الْخَنْدَقِ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً فَأَجَازَنِي. قَالَ نَافِعٌ: فَقَدِمْتُ عَلَى عُمَرَ بْنِ عَبْدِ الْعَزِيزِ رَضِيَ اللَّهُ عَنْهُ وَهُوَ يَوْمَئِذٍ خَلِيفَةٌ، فَحَدَّثْتُهُ هَذَا الْحَدِيثَ، فَقَالَ: إِنَّ هَذَا لَحَدٌّ بَيْنَ الصَّغِيرِ وَالْكَبِيرِ، فَكَتَبَ إِلَى عُمَّالِهِ أَنْ يَفْرِضُوا لِمَنْ كَانَ ابْنَ خَمْسَ عَشْرَةَ سَنَةً، وَمَنْ كَانَ دُونَ ذَلِكَ فَاجْعَلُوهُ فِي الْعِيَالِ. (م)', 'ഇബ്നുഉമർ(റ): എനിക്ക് പതിനാല് വയസ്സുള്ളപ്പോൾ ഉഹ്ദ് യുദ്ധദിവസം യുദ്ധത്തിനായി റസൂൽ(സ) എന്നെ പരിശോധിച്ചു. പക്ഷേ, അവിടുന്ന് എനിക്ക് അനുവാദം തന്നില്ല. എനിക്ക് പതിനഞ്ച് വയസ്സുള്ളപ്പോൾ ഖൻദഖ് യുദ്ധദിവസം അവിടുന്ന് എന്നെ പരിശോധിക്കുകയും എനിക്ക് അനുവാദം നൽകുകയും ചെയ്തു. നാഫിഅ്(റ) പറയുന്നു: ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) ഖലീഫയായിരിക്കെ ഞാൻ അദ്ദേഹത്തിന്റെയടുത്ത് പോകുകയും ഈ ഹദീസ് പറഞ്ഞുകൊടുക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇത് പ്രായപൂർത്തിയായവർക്കും ആകാത്തവർക്കും ഇടയിലുള്ള പരിധിയാണ്. അങ്ങനെ അദ്ദേഹം പതിനഞ്ച് വയസ്സുള്ളവർക്ക് വിഹിതം നൽകാനും അതിനിടയിലുള്ളവരെ ആശ്രിതരുടെ കൂട്ടത്തിൽ ഉൾപ്പെടുത്താനും ആവശ്യപ്പെട്ട് തന്റെ ഗവർണർമാർക്ക് സന്ദേശമെഴുതി. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 876, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: عُرِضْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَيْشٍ وَأَنَا ابْنُ أَرْبَعَ عَشْرَةَ فَلَمْ يَقْبَلْنِي، ثُمَّ عُرِضْتُ عَلَيْهِ مِنْ قَابِلٍ فِي جَيْشٍ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ فَقَبِلَنِي. حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): എനിക്ക് പതിനാല് വയസ്സുള്ളപ്പോൾ ഒരു സൈന്യത്തോടൊപ്പം റസൂൽ(സ)ക്ക് എന്നെ കാണിക്കപ്പെട്ടപ്പോൾ അവിടുന്ന് എന്നെ സ്വീകരിച്ചില്ല. അടുത്ത വർഷം, എനിക്ക് പതിനഞ്ച് വയസ്സുള്ളപ്പോൾ ഒരു സൈന്യത്തോടൊപ്പം എന്നെ റസൂൽ(സ)ക്ക് കാണിക്കപ്പെടുകയും അവിടന്ന് എന്നെ സ്വീകരിക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ وَلَمْ يَغْزُ، وَلَمْ يُحَدِّثْ بِهِ نَفْسَهُ، مَاتَ عَلَى شُعْبَةٍ مِنْ نِفَاقٍ". قَالَ عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ: فَنُرَى أَنَّ ذَلِكَ كَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധം ചെയ്യാതെയോ അതിനെക്കുറിച്ച് മനസ്സിൽ ചിന്തിക്കാതെയോ ഒരാൾ മരിച്ചാൽ കാപട്യത്തിന്റെ ഒരു ശാഖയുമായാണ് അവൻ മരിച്ചത്." അബ്ദുല്ലാഹിബ്നു മുബാറക്(റ) പറഞ്ഞു: അത് റസൂൽ(സ)യുടെ കാലത്തെ കാര്യമാണെന്നാണ് ഞങ്ങളുടെ അഭിപ്രായം. (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَمْ يَغْزُ، أَوْ يُجَهِّزْ غَازِيًا، أَوْ يَخْلُفْ غَازِيًا فِي أَهْلِهِ بِخَيْرٍ، أَصَابَهُ اللَّهُ بِقَارِعَةٍ". وَفِي رِوَايَةٍ: "قَبْلَ يَوْمِ الْقِيَامَةِ". (د,جه)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "യുദ്ധം ചെയ്യാതിരിക്കുകയോ, ഒരു യോദ്ധാവിന് വേണ്ട സാമഗ്രികൾ നൽകാതിരിക്കുകയോ അല്ലെങ്കിൽ ഒരു യോദ്ധാവിന്റെ കുടുംബത്തിൽ നന്മയോടെ പ്രാതിനിധ്യം നിറവേറ്റാതിരിക്കുകയോ ചെയ്യുന്നവന് അല്ലാഹു വിപത്ത് ഇറക്കുന്നതാണ്." മറ്റൊരു നിവേദനം: "അന്ത്യനാളിനു മുമ്പ് (വിപത്ത് ഇറക്കും)." (ദ,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=37), 1, 'وَفِي رِوَايَةٍ: "قَبْلَ يَوْمِ الْقِيَامَةِ". (د,جه)', 'മറ്റൊരു നിവേദനം: "അന്ത്യനാളിനു മുമ്പ് (വിപത്ത് ഇറക്കും)." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "جَاهِدُوا الْمُشْرِكِينَ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ وَأَلْسِنَتِكُمْ". (د,ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സമ്പത്ത് കൊണ്ടും ശരീരങ്ങൾ കൊണ്ടും നാവുകൾ കൊണ്ടും ബഹുദൈവാരാധകരോട് പോരാടുക." (ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 877, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَقِيَ اللَّهَ وَلَيْسَ لَهُ أَثَرٌ فِي سَبِيلِ اللَّهِ لَقِيَ اللَّهَ وَفِيهِ ثُلْمَةٌ". (ت,جه)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ആരെങ്കിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള (യുദ്ധം ചെയ്തതിന്റെ) പാടുകളില്ലാതെ അല്ലാഹുവിനെ അഭിമുഖീകരിച്ചാൽ തന്നിൽ ന്യൂനതയുള്ളവനായി അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزَاةٍ فَقَالَ: "إِنَّ أَقْوَامًا بِالْمَدِينَةِ خَلْفَنَا، مَا سَلَكْنَا شِعْبًا وَلَا وَادِيًا إِلَّا وَهُمْ مَعَنَا فِيهِ، حَبَسَهُمُ الْعُذْرُ". (ق,جه)', 'അനസ്(റ): തിരുദൂതർ(സ) ഒരു യുദ്ധത്തിലേർപ്പെട്ടിരിക്കുമ്പോൾ പറഞ്ഞു: "നമ്മുടെ കൂടെ വരാതെ മദീനയിൽ തങ്ങിയവരുണ്ട്. ഏതൊരു മലയിടുക്കിലോ താഴ്വരയിലോ നാം പ്രവേശിച്ചിട്ടുണ്ടെങ്കിലും അവർ നമ്മുടെ കൂടെ ഉണ്ടാവാതിരിക്കുകയില്ല. ചില പ്രതിബന്ധങ്ങൾ മാത്രമാണവരെ തടഞ്ഞിട്ടുള്ളത്." (ബു,മു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: جِئْتُ أُبَايِعُكَ عَلَى الْهِجْرَةِ، وَتَرَكْتُ أَبَوَيَّ يَبْكِيَانِ. فَقَالَ: "ارْجِعْ عَلَيْهِمَا، فَأَضْحِكْهُمَا كَمَا أَبْكَيْتَهُمَا". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: ഹിജ്റയുടെ കാര്യത്തിൽ അങ്ങയോട് ഉടമ്പടി ചെയ്യാനാണ് ഞാൻ വന്നിരിക്കുന്നത്. ഞാൻ വരുമ്പോൾ എന്റെ മാതാപിതാക്കൾ കരയുകയായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവരിലേക്ക് മടങ്ങിച്ചെന്ന് അവരെ കരയിച്ചതുപോലെത്തന്നെ ചിരിപ്പിക്കുകയും ചെയ്യുക." (ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا هَاجَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْيَمَنِ، فَقَالَ: "هَلْ لَكَ أَحَدٌ بِالْيَمَنِ". قَالَ: أَبَوَايَ، قَالَ: "أَذِنَا لَكَ". قَالَ: لَا، قَالَ: "ارْجِعْ إِلَيْهِمَا فَاسْتَأْذِنْهُمَا، فَإِنْ أَذِنَا لَكَ فَجَاهِدْ، وَإِلَّا فَبَرَّهُمَا". (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): ഒരു മനുഷ്യൻ യമനിൽ നിന്നും തിരുദൂതർ(സ)യുടെ അടുത്തേക്ക് പലായനം ചെയ്തു. തൽസമയം പ്രവാചകർ(സ) ചോദിച്ചു: "യമനിൽ നിന്റെ ആരെങ്കിലും ഉണ്ടോ?" അയാൾ പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ ഉണ്ട്. പ്രവാചകർ(സ) ചോദിച്ചു: "അവർ നിനക്ക് സമ്മതം തന്നോ?" അയാൾ പറഞ്ഞു: ഇല്ല. പ്രവാചകർ(സ) പറഞ്ഞു: "അവരിലേക്ക് മടങ്ങുകയും സമ്മതം വാങ്ങുകയും ചെയ്യുക. അവരുടെ അനുമതി ലഭിച്ചാൽ യുദ്ധം ചെയ്യുക. അല്ലെങ്കിൽ അവർക്ക് ഗുണം ചെയ്യുക." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْذِنُهُ فِي الْجِهَادِ، فَقَالَ: "أَلَكَ وَالِدَانِ". قَالَ: نَعَمْ، قَالَ: "فَفِيهِمَا فَجَاهِدْ". حَسَنٌ صَحِيحٌ. (خ,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരു മനുഷ്യൻ തിരുദൂതർ(സ)യുടെയടുത്തേക്കു വന്ന് യുദ്ധത്തിന് അനുമതി ചോദിച്ചു. പ്രവാചകർ(സ) ചോദിച്ചു: "നിനക്ക് മാതാപിതാക്കൾ ഉണ്ടോ?" ആഗതൻ പറഞ്ഞു: അതെ. പ്രവാചകർ(സ) പറഞ്ഞു: "എങ്കിൽ അവർ രണ്ടുപേരിലും നീ കഠിനാധ്വാനം ചെയ്യുക." (ബു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ جَاهِمَةَ السَّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَدْتُ أَنْ أَغْزُوَ، وَقَدْ جِئْتُ أَسْتَشِيرُكَ؟ فَقَالَ: "هَلْ لَكَ مِنْ أُمٍّ". قَالَ: نَعَمْ. قَالَ: "فَالْزَمْهَا، فَإِنَّ الْجَنَّةَ تَحْتَ رِجْلَيْهَا". (ن)', 'ജാഹിമതുസ്സലമി(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ സന്നിധിയിൽചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ യുദ്ധം ചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. അങ്ങയുടെ അഭിപ്രായമറിയാനാണ് ഞാൻ വന്നിരിക്കുന്നത്. റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് മാതാവുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "നീ അവരുടെ സമീപം ചെല്ലുക. തീർച്ചയായും സ്വർഗ്ഗം മാതാവിന്റെ കാലുകൾക്ക് കീഴിലാണ്." (ന)', 'جَاهِمَةَ السَّلَمِيِّ', 'ജാഹിമതുസ്സലമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ غَزْوَةِ تَبُوكَ، فَدَنَا مِنَ الْمَدِينَةِ، قَالَ: "إِنَّ بِالْمَدِينَةِ لَقَوْمًا: مَا سِرْتُمْ مِنْ مَسِيرٍ، وَلَا قَطَعْتُمْ وَادِيًا، إِلَّا كَانُوا مَعَكُمْ فِيهِ". قَالُوا: يَا رَسُولَ اللَّهِ، وَهُمْ بِالْمَدِينَةِ؟ قَالَ: "وَهُمْ بِالْمَدِينَةِ، حَبَسَهُمُ الْعُذْرُ". (د,جه)', 'അനസുബ്നു മാലിക്(റ): തബൂക്ക് യുദ്ധത്തിൽ നിന്ന് മടങ്ങി മദീനയോടടുത്തപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും മദീനയിൽ ഒരു വിഭാഗമുണ്ട്. അവർ കൂടെയില്ലാതെ നിങ്ങൾ മലമടക്കുകളിലൂടെ നടക്കുകയോ താഴ്വരയെ മുറിച്ചു കടക്കുകയോ ചെയ്തിട്ടില്ല." അനുചരർ ചോദിച്ചു: അവർ മദീനയിലാണോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അവർ മദീനയിലാണ്. പ്രതിബന്ധങ്ങൾ അവരെ തടഞ്ഞിരിക്കുന്നു." (ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ مُعَاوِيَةَ بْنِ جَاهِمَةَ السُّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ أَرَدْتُ الْجِهَادَ مَعَكَ، أَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ وَالدَّارَ الْآخِرَةَ. قَالَ: "وَيْحَكَ، أَحَيَّةٌ أُمُّكَ". قُلْتُ: نَعَمْ. قَالَ: "ارْجِعْ فَبَرَّهَا". ثُمَّ أَتَيْتُهُ مِنَ الْجَانِبِ الْآخَرِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ أَرَدْتُ الْجِهَادَ مَعَكَ، أَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ وَالدَّارَ الْآخِرَةَ. قَالَ: "وَيْحَكَ، أَحَيَّةٌ أُمُّكَ". قُلْتُ: نَعَمْ، يَا رَسُولَ اللَّهِ. قَالَ: "فَارْجِعْ إِلَيْهَا فَبَرَّهَا". ثُمَّ أَتَيْتُهُ مِنْ أَمَامِهِ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ أَرَدْتُ الْجِهَادَ مَعَكَ أَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ وَالدَّارَ الْآخِرَةَ. قَالَ: "وَيْحَكَ، أَحَيَّةٌ أُمُّكَ". قُلْتُ: نَعَمْ، يَا رَسُولَ اللَّهِ. قَالَ: "وَيْحَكَ، الْزَمْ رِجْلَهَا، فَثَمَّ الْجَنَّةُ". (ن,جه)', 'മുആവിയതുബ്നു ജാഹിമതുസ്സലമി(റ): തിരുദൂതർ(സ)യുടെ സവിധത്തിൽ ചെന്ന് ഞാൻ പറഞ്ഞു: അല്ലഹുവിന്റെ ദൂതരേ, ഞാൻ അങ്ങയോടെപ്പം യുദ്ധം ചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. അതുകൊണ്ട് പാരത്രികലോകത്തെയും അല്ലാഹുവിന്റെ തൃപ്തിയെയും ഞാൻ ആഗ്രഹിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "കഷ്ടം! നിന്റെ മാതാവ് ജീവിച്ചിരിപ്പുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. പ്രവാചകർ(സ) പറഞ്ഞു: "നീ മടങ്ങുക, അവർക്ക് ഗുണം ചെയ്യുക." ശേഷം മറ്റൊരു ഭാഗത്തുകൂടെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: നബിയേ, ഞാൻ അവിടുത്തോടുകൂടെ യുദ്ധം ചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. പാരത്രികലോകത്തെയും അല്ലാഹുവിന്റെ തൃപ്തിയും അതുകൊണ്ട് ഞാൻ കാംക്ഷിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "കഷ്ടം! നിന്റെ മാതാവ് ജീവിച്ചിരിപ്പുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, റസൂലേ. അവിടുന്ന് പറഞ്ഞു: "അവരിലേക്ക് മടങ്ങി ഗുണംചെയ്യുക. ശേഷം റസൂൽ(സ)യുടെ മുൻഭാഗത്തുകൂടെ വന്ന് ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹുവിന്റെ പ്രീതിയും പാരത്രിക മോക്ഷവും ആഗ്രഹിച്ച് അങ്ങയോടൊത്ത് സായുധ സമരത്തിൽ പങ്കെടുക്കാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. പ്രവാചകർ(സ) ചോദിച്ചു: "കഷ്ടം! നിന്റെ മാതാവ് ജീവിച്ചിരിപ്പുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, തിരുദൂതരേ. പ്രവാചകർ(സ) പറഞ്ഞു: "കഷ്ടം, നീ മാതാവിന്റെ പാദങ്ങളോടൊപ്പം കഴിയുക. സ്വർഗ്ഗം അവിടെയാണ്." (ന,ജ)', 'مُعَاوِيَةَ بْنِ جَاهِمَةَ السُّلَمِيِّ', 'മുആവിയതുബ്നു ജാഹിമതുസ്സലമി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: {إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا} [التّوبة: ٣٩] وَ{مَا كَانَ لِأَهْلِ الْمَدِينَةِ} إِلَى قَوْلِهِ: {يَعْمَلُونَ} نَسَخَتْهَا الْآيَةُ الَّتِي تَلِيهَا: {وَمَا كَانَ الْمُؤْمِنُونَ لِيَنْفِرُوا كَافَّةً}. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങൾ യുദ്ധത്തിന് പോയില്ലെങ്കിൽ അല്ലാഹു നിങ്ങളെ വേദനാജനകമായ ശിക്ഷക്കർഹരാക്കും.'' (തൗബ: 39) എന്ന സൂക്തത്തെയും ''മദീനാ നിവാസികൾക്ക് യോജിച്ചതല്ല'' എന്നതു മുതൽ ''അവർ പ്രവർത്തിക്കുന്ന കാര്യങ്ങൾക്ക്'' എന്നത് വരെയുള്ള സൂക്തത്തെയും ''സത്യവിശ്വാസികൾ മുഴുവനായും യുദ്ധത്തിന് പോകേണ്ടവരല്ല'' എന്ന, അതിനു ശേഷമുള്ള സൂക്തം നസ്ഖ് ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'التّوبة: ٣٩', null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ نَجْدَةَ بْنِ نُفَيْعٍ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ عَنْ هَذِهِ الْآيَةِ: {إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا} قَالَ: فَأُمْسِكَ عَنْهُمُ الْمَطَرُ، وَكَانَ عَذَابَهُمْ. (د)', 'അബ്ദുനജ്ദതിബ്നി നുഫൈഅ്(റ): ''നിങ്ങൾ യുദ്ധത്തിന് പോയില്ലെങ്കിൽ അല്ലാഹു നിങ്ങളെ വേദനാജനകമായ ശിക്ഷക്കർഹരാക്കും'' എന്ന സൂക്തത്തെക്കുറിച്ച് ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അപ്പോൾ അവർക്ക് മഴ തടയപ്പെട്ടു. അതായിരുന്നു അവരുടെ ശിക്ഷ. (ദ)', 'عَبْدِ نَجْدَةَ بْنِ نُفَيْعٍ قَالَ', 'അബ്ദുനജ്ദതിബ്നി നുഫൈഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ مِنْ أَصْلِ الْإِيمَانِ: الْكَفُّ عَمَّنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نُكَفِّرُهُ بِذَنْبٍ، وَلَا نُخْرِجُهُ مِنَ الْإِسْلَامِ بِعَمَلٍ. وَالْجِهَادُ مَاضٍ مُنْذُ بَعَثَنِي اللَّهُ إِلَى أَنْ يُقَاتِلَ آخِرُ أُمَّتِي الدَّجَّالَ، لَا يُبْطِلُهُ جَوْرُ جَائِرٍ، وَلَا عَدْلُ عَادِلٍ. وَالْإِيمَانُ بِالْأَقْدَارِ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കാര്യങ്ങൾ ഈമാനിന്റെ അടിസ്ഥാനത്തിൽ പെട്ടതാണ്: അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ലെന്ന് പറഞ്ഞവനെതിരെ യുദ്ധം ചെയ്യാതിരിക്കൽ. അപ്രകാരം പറഞ്ഞവനെ ഒരു ദോഷം കാരണത്താലും നാം സത്യനിഷേധിയാക്കുകയില്ല, ഒരു പ്രവർത്തനം കാരണത്താലും അവനെ നാം ഇസ്‌ലാമിൽ നിന്ന് പുറത്താക്കുകയില്ല. എന്നെ അല്ലാഹു നിയോഗിച്ചത് മുതൽ എന്റെ സമുദായത്തിലെ അവസാനത്തെ വ്യക്തി ദജ്ജാലിനോട് പോരാടുന്നത് വരെ തുടർന്നുകൊണ്ടിരിക്കുന്ന ധർമ്മസമരം. ഒരു ക്രൂര ഭരണാധികാരിയുടെ ക്രൂരതയോ ഒരു നീതിമാന്റെ നീതിയോ അതിനെ നശിപ്പിക്കുകയില്ല. വിധികളിൽ വിശ്വസിക്കൽ എന്നിവയാണവ." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْجِهَادُ وَاجِبٌ عَلَيْكُمْ مَعَ كُلِّ أَمِيرٍ، بَرًّا كَانَ أَوْ فَاجِرًا. وَالصَّلَاةُ وَاجِبَةٌ عَلَيْكُمْ خَلْفَ كُلِّ مُسْلِمٍ، بَرًّا كَانَ أَوْ فَاجِرًا، وَإِنْ عَمِلَ الْكَبَائِرَ. وَالصَّلَاةُ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ، بَرًّا كَانَ أَوْ فَاجِرًا، وَإِنْ عَمِلَ الْكَبَائِرَ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നല്ലവനാണെങ്കിലും തെമ്മാടിയാണെങ്കിലും ഏതൊരു ഭരണാധികാരിയുടെയുംകൂടെ ധർമ്മസമരം ചെയ്യൽ നിങ്ങളുടെ മേൽ നിർബന്ധമാണ്. നല്ലവനാണെങ്കിലും തെമ്മാടിയാണെങ്കിലും ഏതൊരു മുസ്‌ലിമിന്റെയും പിന്നിൽ നിസ്കരിക്കൽ നിങ്ങളുടെ മേൽ നിർബന്ധമാണ്. അവൻ വൻപാപങ്ങൾ പ്രവർത്തിച്ചാലും ശരി. നല്ലവനാണെങ്കിലും തെമ്മാടിയാണെങ്കിലും ഏതൊരു മുസ്‌ലിമിന്റെയും മേൽ നമസ്കാരം നിർബന്ധമാണ്. അവൻ വൻകുറ്റങ്ങൾ പ്രവർത്തിച്ചാലും ശരി." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَجْتَمِعَانِ فِي النَّارِ اجْتِمَاعًا يَضُرُّ أَحَدُهُمَا الْآخَرَ". قِيلَ: مَنْ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: "مُؤْمِنٌ قَتَلَ كَافِرًا ثُمَّ سَدَّدَ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടിലൊരാൾ മറ്റെയാളെ ബുദ്ധിമുട്ടിക്കുന്നു. അപ്രകാരമുള്ള രണ്ടുപേർ നരകത്തിൽ ഒരുമിക്കുകയില്ല." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അവർ ആരാണ് റസൂലേ? അവിടുന്ന് പറഞ്ഞു: "ഒരു സത്യനിഷേധിയെ വധിച്ചശേഷം നല്ല രീതിയിൽ ജീവിക്കുന്ന സത്യവിശ്വാസി." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ فِي جَوْفِ عَبْدٍ مُسْلِمٍ". (ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുസ്‌ലിമായ അടിമയുടെ ഉള്ളിൽ നരകത്തിലെ പുകയും അല്ലാഹുവിന്റെ മാർഗത്തിലുള്ള പോരാട്ടഭൂമിയിലെ പൊടിയും ഒരുമിക്കുകയില്ല." (തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ رَاحَ رَوْحَةً فِي سَبِيلِ اللَّهِ كَانَ لَهُ بِمِثْلِ مَا أَصَابَهُ مِنَ الْغُبَارِ مِسْكًا يَوْمَ الْقِيَامَةِ". (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിന്റെ മാർഗത്തിൽ ധർമ്മസമരം ചെയ്യുന്നതിനു വേണ്ടി (വൈകുന്നേരം) പുറപ്പെട്ടാൽ തന്റെ ശരീരത്തിൽ പതിച്ച പൊടിപടലങ്ങൾ കണക്കെ അന്ത്യനാളിൽ അവന് കസ്തൂരി ലഭിക്കുന്നതാണ്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ مَرْوَانَ بْنَ الْحَكَمِ جَالِسًا فِي الْمَسْجِدِ، فَجِئْتُ حَتَّى جَلَسْتُ إِلَى جَنْبِهِ فَحَدَّثَنَا أَنَّ زَيْدَ بْنَ ثَابِتٍ حَدَّثَهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُنْزِلَ عَلَيْهِ: {لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ... وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ} [النّساء: ٩٥] فَجَاءَ ابْنُ أُمِّ مَكْتُومٍ وَهُوَ يُمِلُّهَا عَلَيَّ فَقَالَ: يَا رَسُولَ اللَّهِ، لَوْ أَسْتَطِيعُ الْجِهَادَ لَجَاهَدْتُ. وَكَانَ رَجُلًا أَعْمَى، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ وَفَخِذُهُ عَلَى فَخِذِي، فَثَقُلَتْ عَلَيَّ حَتَّى خِفْتُ أَنْ تَرُضَّ – وَفِي رِوَايَةٍ: حَتَّى هَمَّتْ تَرُضُّ – فَخِذِي، ثُمَّ سُرِّيَ عَنْهُ: {غَيْرُ أُولِي الضَّرَرِ}. (خ,ن)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): മർവാനുബ്നു ഹകമിനെ പള്ളിയിൽ ഇരിക്കുന്നതായി ഞാൻ കണ്ടു. ഞാൻ ചെന്ന് അദ്ദേഹത്തിന്റെ സമീപത്തിരുന്നു. തദവസരം സൈദുബ്നു സാബിത്(റ) തനിക്ക് ഇപ്രകാരം പറഞ്ഞുതന്നതായി അദ്ദേഹം പറഞ്ഞു: സൈദുബ്നു സാബിത്(റ) പറഞ്ഞു: ''യുദ്ധത്തിന് പോകാതെ ഒഴിഞ്ഞിരിക്കുന്ന വിശ്വാസികളും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവരും തുല്യരാവുകയില്ല'' എന്ന സൂക്തം റസൂൽ(സ)ക്ക് അവതരിച്ചു. തിരുമേനി(സ) ആ സൂക്തം എനിക്ക് ഓതിത്തന്നുകൊണ്ടിരിക്കെ ഇബ്നു ഉമ്മിമക്തൂം(റ) വന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എനിക്ക് കഴിയുമായിരുന്നെങ്കിൽ ഞാൻ യുദ്ധത്തിന് പോകുമായിരുന്നല്ലോ. ആ സമയത്ത് റസൂൽ(സ)യുടെ തുട എന്റെ തുടയുടെ മേലെയായിരുന്നു. (വഹ്‌യ് അവതരിക്കുന്നതിനാൽ) റസൂൽ(സ)യുടെ തുട വളരെ ഭാരമുള്ളതാവുകയും എന്റെ തുട പൊട്ടിപ്പോകുമോ എന്ന് ഞാൻ ഭയക്കുകയും ചെയ്തു - മറ്റൊരു നിവേദനം: എന്റെ തുട പൊട്ടാനടുക്കുകയും ചെയ്തു - ശേഷം റസൂൽ(സ)യുടെ ഭാരം ഇല്ലാതാവുകയും ''പ്രതിസന്ധികൾ ഉള്ളവർ ഒഴികെ'' എന്ന വാക്യം അവതരിക്കുകയും ചെയ്തു. (ബു,ന)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], 'النّساء: ٩٥', null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=54), 1, 'وَفِي رِوَايَةٍ: حَتَّى هَمَّتْ تَرُضُّ – فَخِذِي، ثُمَّ سُرِّيَ عَنْهُ: {غَيْرُ أُولِي الضَّرَرِ}. (خ,ن)', 'മറ്റൊരു നിവേദനം: എന്റെ തുട പൊട്ടാനടുക്കുകയും ചെയ്തു - ശേഷം റസൂൽ(സ)യുടെ ഭാരം ഇല്ലാതാവുകയും ''പ്രതിസന്ധികൾ ഉള്ളവർ ഒഴികെ'' എന്ന വാക്യം അവതരിക്കുകയും ചെയ്തു. (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ائْتُونِي بِالْكَتِفِ وَاللَّوْحِ". فَكَتَبَ: {لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ...} وَعَمْرُو بْنُ أُمِّ مَكْتُومٍ خَلْفَهُ، فَقَالَ: هَلْ لِي رُخْصَةٌ؟ فَنَزَلَتْ: {غَيْرُ أُولِي الضَّرَرِ}. وَفِي رِوَايَةٍ: قَالَ: لَمَّا نَزَلَتْ: {لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ} جَاءَ ابْنُ أُمِّ مَكْتُومٍ وَكَانَ أَعْمَى، فَقَالَ: يَا رَسُولَ اللَّهِ، فَكَيْفَ فِيَّ وَأَنَا أَعْمَى؟ قَالَ: فَمَا بَرِحَ حَتَّى نَزَلَتْ: {غَيْرُ أُولِي الضَّرَرِ}. (ق,ت,ن)', 'ബറാഅ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പലകയും എല്ലും കൊണ്ടുവരിക." അങ്ങനെ റസൂൽ(സ) ഇപ്രകാരം എഴുതി: "സത്യവിശ്വാസികളിൽ യുദ്ധം ചെയ്യാതെ ഒഴിഞ്ഞിരിക്കുന്നവരും (യുദ്ധം ചെയ്യുന്നവരും) സമമാകുകയില്ല." അംറുബ്നു ഉമ്മിമക്തൂം(റ) റസൂൽ(സ)യുടെ പിന്നിൽ നിൽക്കുകയായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: എനിക്ക് വല്ല ഇളവുമുണ്ടോ? അപ്പോൾ ''പ്രതിസന്ധികൾ ഉള്ളവർ ഒഴികെ'' എന്ന സൂക്തം അവതരിച്ചു. മറ്റൊരു നിവേദനം: ''സത്യവിശ്വാസികളിൽ യുദ്ധം ചെയ്യാതെ ഒഴിഞ്ഞിരിക്കുന്നവരും (യുദ്ധം ചെയ്യുന്നവരും) സമമാകില്ല'' എന്ന സൂക്തം ഇറങ്ങിയപ്പോൾ അന്ധനായ ഇബ്നു ഉമ്മിമക്തൂം(റ) വന്ന് ചോദിച്ചു: റസൂലേ, അന്ധനായ ഞാൻ എന്തുചെയ്യണം? നിവേദകൻ പറയുന്നു: ''പ്രതിസന്ധികൾ ഉള്ളവർ ഒഴികെ'' എന്ന് അവതരിക്കും വരെ അദ്ദേഹമത് ചോദിച്ചുകൊണ്ടിരുന്നു. (ബു,മു,തു,ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 881, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=55), 1, 'وَفِي رِوَايَةٍ: قَالَ: لَمَّا نَزَلَتْ: {لَا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ} جَاءَ ابْنُ أُمِّ مَكْتُومٍ وَكَانَ أَعْمَى، فَقَالَ: يَا رَسُولَ اللَّهِ، فَكَيْفَ فِيَّ وَأَنَا أَعْمَى؟ قَالَ: فَمَا بَرِحَ حَتَّى نَزَلَتْ: {غَيْرُ أُولِي الضَّرَرِ}. (ق,ت,ن)', 'മറ്റൊരു നിവേദനം: ''സത്യവിശ്വാസികളിൽ യുദ്ധം ചെയ്യാതെ ഒഴിഞ്ഞിരിക്കുന്നവരും (യുദ്ധം ചെയ്യുന്നവരും) സമമാകില്ല'' എന്ന സൂക്തം ഇറങ്ങിയപ്പോൾ അന്ധനായ ഇബ്നു ഉമ്മിമക്തൂം(റ) വന്ന് ചോദിച്ചു: റസൂലേ, അന്ധനായ ഞാൻ എന്തുചെയ്യണം? നിവേദകൻ പറയുന്നു: ''പ്രതിസന്ധികൾ ഉള്ളവർ ഒഴികെ'' എന്ന് അവതരിക്കും വരെ അദ്ദേഹമത് ചോദിച്ചുകൊണ്ടിരുന്നു. (ബു,മു,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَقَابُ قَوْسٍ فِي الْجَنَّةِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ". وَقَالَ: "لَغَدْوَةٌ أَوْ رَوْحَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സൂര്യന്റെ ഉദയാസ്തമയങ്ങളെ അനുഭവിക്കുന്ന സർവ്വ വസ്തുക്കളേക്കാളും ഉത്തമമാണ് സ്വർഗ്ഗത്തിൽ ഒരു അമ്പിൻ വില്ല്." നബി(സ) പറഞ്ഞു: "ഉദയാസ്തമയങ്ങളെ അനുഭവിക്കുന്ന സർവ്വ വസ്തുക്കളേക്കാളും ഉത്തമമാണ് ദൈവമാർഗ്ഗത്തിൽ പ്രഭാതത്തിലോ പ്രദോഷത്തിലോ പുറപ്പെടൽ." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ رَجُلٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِعْبٍ فِيهِ عُيَيْنَةٌ مِنْ مَاءٍ عَذْبَةٌ، فَأَعْجَبَتْهُ لِطِيبِهَا، فَقَالَ: لَوِ اعْتَزَلْتُ النَّاسَ فَأَقَمْتُ فِي هَذَا الشِّعْبِ، وَلَنْ أَفْعَلَ حَتَّى أَسْتَأْذِنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَا تَفْعَلْ، فَإِنَّ مُقَامَ أَحَدِكُمْ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ صَلَاتِهِ فِي بَيْتِهِ سَبْعِينَ عَامًا، أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَيُدْخِلَكُمُ الْجَنَّةَ؟ اغْزُوا فِي سَبِيلِ اللَّهِ، مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ فُوَاقَ نَاقَةٍ وَجَبَتْ لَهُ الْجَنَّةُ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യുടെ അനുചരന്മാരിലൊരാൾ ശുദ്ധജല തടാകമുള്ള ഒരു മലഞ്ചെരുവിലൂടെ നടക്കുകയായിരുന്നു. അതിന്റെ മാധുര്യം അദ്ദേഹത്തെ അത്ഭുതപ്പെടുത്തി. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളെയെല്ലാം വെടിഞ്ഞ് ഞാൻ ഈ മലഞ്ചെരുവിൽ കഴിയുകയാണെങ്കിൽ അതാണ് ഉത്തമം. പക്ഷേ, റസൂൽ(സ)യോട് സമ്മതം ചോദിക്കാതെ ഞാനത് ചെയ്യുകയില്ല. അദ്ദേഹം അക്കാര്യം നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അത് ചെയ്യരുത്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ നിങ്ങളിലൊരുത്തൻ സമരം ചെയ്യൽ തന്റെ വീട്ടിൽ വെച്ച് എഴുപത് വർഷം നമസ്കരിക്കുന്നതിനേക്കാൾ ശ്രേഷ്ഠമാണ്. അല്ലാഹു നിങ്ങൾക്ക് പൊറുത്തുതരണമെന്നും സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കണമെന്നും നിങ്ങൾ ആഗ്രഹിക്കുന്നില്ലേ? നിങ്ങൾ ദൈവമാർഗ്ഗത്തിൽ സമരം ചെയ്യുക. ആരെങ്കിലും ഒട്ടകത്തെ രണ്ട് പ്രാവശ്യം കറക്കുന്നതിനിടയിലുള്ള സമയം (അൽപ സമയം) ദൈവമാർഗ്ഗത്തിൽ സമരം ചെയ്താൽ അവന് സ്വർഗ്ഗം നിർബന്ധമായിരിക്കുന്നു." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "غَدْوَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَمَوْضِعُ سَوْطٍ فِي الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا". حَسَنٌ صَحِيحٌ. (ق,ت)', 'സഹ്‌ലുബ്നു സഅ്ദിസ്സാഇദി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പ്രദോഷത്തിൽ പുറപ്പെടൽ ഐഹികലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്. കുതിരയുടെ കാലടി, സ്വർഗ്ഗത്തിൽ, ഐഹിക ലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്." (ബു,മു,തു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്‌ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 883, 883, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَغَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَقَابُ قَوْسِ أَحَدِكُمْ أَوْ مَوْضِعُ يَدِهِ فِي الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا. وَلَوْ أَنَّ امْرَأَةً مِنْ نِسَاءِ أَهْلِ الْجَنَّةِ اطَّلَعَتْ إِلَى الْأَرْضِ لَأَضَاءَتْ مَا بَيْنَهُمَا، وَلَمَلَأَتْ مَا بَيْنَهُمَا رِيحًا، وَلَنَصِيفُهَا عَلَى رَأْسِهَا خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا". (ق,ت,ن,جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യാൻ പ്രഭാതപ്രദോഷങ്ങളിൽ പുറപ്പെടൽ ഐഹിക ലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്. നിങ്ങളിലൊരുത്തന്റെ അമ്പിൻ വില്ല് അല്ലെങ്കിൽ അവന്റെ കൈപ്പിടി, സ്വർഗ്ഗത്തിൽ, ഐഹികലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്. സ്വർഗ്ഗീയ സ്ത്രീകളിൽ ഒരുത്തി ഈ ഭൂമിയിൽ പ്രത്യക്ഷപ്പെട്ടാൽ അതിലുള്ള സർവ്വവും പ്രകാശിക്കും. അതിൽ മുഴുവൻ അവളുടെ സുഗന്ധം പരക്കും. അവളുടെ തലയിലെ തട്ടം ഐഹിക ലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്." (ബു,മു,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 883, 883, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَرْكَبُ الْبَحْرَ إِلَّا حَاجٌّ أَوْ مُعْتَمِرٌ أَوْ غَازٍ فِي سَبِيلِ اللَّهِ، فَإِنَّ تَحْتَ الْبَحْرِ نَارًا، وَتَحْتَ النَّارِ بَحْرًا". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജ് ചെയ്യുന്നവനോ, ഉംറ ചെയ്യുന്നവനോ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവനോ അല്ലാതെ കടലിലൂടെ സഞ്ചരിക്കരുത്. കാരണം, കടലിനടിയിൽ തീയുണ്ട്. തീയിനടിയിൽ കടലുമുണ്ട്." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 883, 883, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَتْنِي أُمُّ حَرَامٍ بِنْتُ مِلْحَانَ أُخْتُ أُمِّ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ عِنْدَهُمْ، فَاسْتَيْقَظَ وَهُوَ يَضْحَكُ، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، مَا أَضْحَكَكَ؟ قَالَ: "رَأَيْتُ قَوْمًا مِمَّنْ يَرْكَبُ ظَهْرَ هَذَا الْبَحْرِ كَالْمُلُوكِ عَلَى الْأَسِرَّةِ". قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: "فَإِنَّكِ مِنْهُمْ". قَالَتْ: ثُمَّ نَامَ فَاسْتَيْقَظَ وَهُوَ يَضْحَكُ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا أَضْحَكَكَ؟ فَقَالَ مِثْلَ مَقَالَتِهِ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: "أَنْتِ مِنَ الْأَوَّلِينَ". قَالَ: فَتَزَوَّجَهَا عُبَادَةُ بْنُ الصَّامِتِ فَغَزَا فِي الْبَحْرِ فَحَمَلَهَا مَعَهُ، فَلَمَّا رَجَعَ قُرِّبَتْ لَهَا بَغْلَةٌ لِتَرْكَبَهَا فَصَرَعَتْهَا فَانْدَقَّتْ عُنُقُهَا فَمَاتَتْ. وَفِي رِوَايَةٍ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا ذَهَبَ إِلَى قُبَاءَ يَدْخُلُ عَلَى أُمِّ حَرَامٍ بِنْتِ مِلْحَانَ رَضِيَ اللَّهُ عَنْهَا، وَكَانَتْ تَحْتَ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ، فَدَخَلَ عَلَيْهَا يَوْمًا، فَأَطْعَمَتْهُ وَجَلَسَتْ تَفْلِي رَأْسَهُ، وَسَاقَ هَذَا الْحَدِيثَ. (ق,د,ت,جه)', 'അനസുബ്നുമാലിക്(റ): അദ്ദേഹം പറഞ്ഞു: ഉമ്മുസുലൈം(റ)യുടെ സഹോദരിയായ ഉമ്മുഹറാം ബിൻത് മിൽഹാൻ(റ) എന്നോട് പറഞ്ഞു: ഒരു ദിവസം റസൂൽ(സ) അവരുടെ വീട്ടിൽ ഉച്ചയുറക്കമുറങ്ങി. എന്നിട്ട് ചിരിച്ചുകൊണ്ട് ഉണർന്നു. ഉമ്മുഹറാം(റ) ചോദിച്ചു: എന്തിനാണ് അങ്ങ് ചിരിച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "രാജാക്കന്മാർ കട്ടിലിലിരിക്കും പോലെ ഈ കടലിലൂടെ യാത്ര ചെയ്യുന്ന ഒരു കൂട്ടരെ ഞാൻ കണ്ടു." ഉമ്മുഹറാം(റ) പറഞ്ഞു: എന്നെയും അവരിലുൾപ്പെടുത്താൻ അങ്ങ് പ്രാർത്ഥിക്കുക. റസൂൽ(സ) പറഞ്ഞു: "നീ അവരിൽ പെട്ടവളാണ്." ഉമ്മുഹറാം(റ) പറയുന്നു: റസൂൽ(സ) വീണ്ടും ഉറങ്ങി. ചിരിച്ചുകൊണ്ട് വീണ്ടും ഉണർന്നു. ഉമ്മുഹറാം(റ) ചോദിച്ചു: അങ്ങ് എന്തിനാണ് ചിരിച്ചത്? റസൂൽ(സ) മുമ്പ് പറഞ്ഞ അതേ മറുപടി പറഞ്ഞു. ഉമ്മുഹറാം(റ) പറഞ്ഞു: എന്നെ അവരിലുൾപ്പെടുത്താൻ അങ്ങ് പ്രാർത്ഥക്കുക. റസൂൽ(സ) പറഞ്ഞു: "നീ ആദ്യ വിഭാഗത്തിൽപ്പെട്ടവളാണ്." നിവേദകൻ പറഞ്ഞു: ഉമ്മുഹറാം(റ)യെ ശേഷം ഉബാദതുബ്നു സ്വാമിത്(റ) വിവാഹം ചെയ്യുകയും നാവികയുദ്ധത്തിനായി തന്റെ കൂടെ അവരെ കൊണ്ടുപോവുകയും ചെയ്തു. മടങ്ങുമ്പോൾ യാത്രക്കായി ഒരു കോവർകഴുതയുടെ പുറത്തുകയറുന്നതിനിടെ അവരെയത് വീഴ്ത്തുകയും കഴുത്തൊടിഞ്ഞ് അവർ മരിക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: റസൂൽ(സ) ഖുബായിലേക്ക് പോവുകയാണെങ്കിൽ ഉമ്മുഹറാം ബിൻത് മിൽഹാൻ(റ)യുടെ അടുക്കൽ പോകുമായിരുന്നു. അവർ ഉബാദതുബ്നു സ്വാമിത്(റ)വിന്റെ കീഴിലായിരുന്നു. ഒരു ദിവസം റസൂൽ(സ) അവരുടെ അടുത്ത് പോവുകയും അവർ റസൂൽ(സ)ക്ക് ഭക്ഷണം നൽകുകയും ശേഷം റസൂൽ(സ)യുടെ പേൻ നോക്കാൻ വേണ്ടി മഹതി ഇരിക്കുകയും ചെയ്തു. ശേഷം മുൻപറഞ്ഞ ഹദീസ് പറഞ്ഞു. (ബു,മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 883, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=61), 1, 'وَفِي رِوَايَةٍ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا ذَهَبَ إِلَى قُبَاءَ يَدْخُلُ عَلَى أُمِّ حَرَامٍ بِنْتِ مِلْحَانَ رَضِيَ اللَّهُ عَنْهَا، وَكَانَتْ تَحْتَ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ، فَدَخَلَ عَلَيْهَا يَوْمًا، فَأَطْعَمَتْهُ وَجَلَسَتْ تَفْلِي رَأْسَهُ، وَسَاقَ هَذَا الْحَدِيثَ. (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: റസൂൽ(സ) ഖുബായിലേക്ക് പോവുകയാണെങ്കിൽ ഉമ്മുഹറാം ബിൻത് മിൽഹാൻ(റ)യുടെ അടുക്കൽ പോകുമായിരുന്നു. അവർ ഉബാദതുബ്നു സ്വാമിത്(റ)വിന്റെ കീഴിലായിരുന്നു. ഒരു ദിവസം റസൂൽ(സ) അവരുടെ അടുത്ത് പോവുകയും അവർ റസൂൽ(സ)ക്ക് ഭക്ഷണം നൽകുകയും ശേഷം റസൂൽ(സ)യുടെ പേൻ നോക്കാൻ വേണ്ടി മഹതി ഇരിക്കുകയും ചെയ്തു. ശേഷം മുൻപറഞ്ഞ ഹദീസ് പറഞ്ഞു. (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أُخْتِ أُمِّ سُلَيْمٍ الرُّمَيْصَاءِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَيْقَظَ، وَكَانَتْ تَغْسِلُ رَأْسَهَا، فَاسْتَيْقَظَ وَهُوَ يَضْحَكُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، أَتَضْحَكُ مِنْ رَأْسِي؟ قَالَ: "لَا.." وَسَاقَ هَذَا الْخَبَرَ: يَزِيدُ وَيَنْقُصُ. قَالَ أَبُو دَاوُدَ: الرُّمَيْصَاءُ أُخْتُ أُمِّ سُلَيْمٍ مِنَ الرَّضَاعَةِ. (د)', 'ഉമ്മുസുലൈം(റ)യുടെ സഹോദരി റുമൈസാഅ്(റ): അവർ പറഞ്ഞു: മഹതി തന്റെ തല കഴുകിക്കൊണ്ടിരിക്കെ റസൂൽ(സ) ഉറങ്ങുകയും ഉണരുകയും ചെയ്തു. റസൂൽ(സ) ചിരിച്ചുകൊണ്ടാണ് ഉണർന്നത്. അപ്പോൾ റുമൈസാഅ്(റ) ചോദിച്ചു: എന്റെ തല കണ്ടിട്ടാണോ അങ്ങ് ചിരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ല." ശേഷം നിവേദകൻ കൂട്ടിയും കുറച്ചും മുൻപറഞ്ഞ ഹദീസ് പറഞ്ഞു. അബൂദാവൂദ്(റ) പറഞ്ഞു: ഉമ്മുസുലൈം(റ)യുടെ മുലകുടിബന്ധത്തിലുള്ള സഹോദരിയാണ് റുമൈസാഅ്(റ). (ദ)', 'أُخْتِ أُمِّ سُلَيْمٍ الرُّمَيْصَاءِ', 'ഉമ്മുസുലൈം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 884, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أُمِّ حَرَامٍ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْمَائِدُ فِي الْبَحْرِ الَّذِي يُصِيبُهُ الْقَيْءُ، لَهُ أَجْرُ شَهِيدٍ، وَالْغَرِقُ لَهُ أَجْرُ شَهِيدَيْنِ". (د)', 'ഉമ്മുഹറാം(റ): നബി(സ) പറഞ്ഞു: "കടലിലെ കാറ്റിൽപ്പെട്ട് തലചുറ്റുന്നവന്നും അങ്ങനെ ഛർദ്ദി ബാധിക്കുന്നവന്നും രക്തസാക്ഷിയുടെ കൂലിയുണ്ട്. മുങ്ങിമരിക്കുന്നവന് രണ്ട് രക്തസാക്ഷികളുടെ കൂലിയുണ്ട്." (ദ)', 'أُمِّ حَرَامٍ', 'ഉമ്മുഹറാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 884, 884, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةٌ كُلُّهُمْ ضَامِنٌ عَلَى اللَّهِ عَزَّ وَجَلَّ: رَجُلٌ خَرَجَ غَازِيًا فِي سَبِيلِ اللَّهِ، فَهُوَ ضَامِنٌ عَلَى اللَّهِ حَتَّى يَتَوَفَّاهُ فَيُدْخِلَهُ الْجَنَّةَ، أَوْ يَرُدَّهُ بِمَا نَالَ مِنْ أَجْرٍ وَغَنِيمَةٍ. وَرَجُلٌ رَاحَ إِلَى الْمَسْجِدِ، فَهُوَ ضَامِنٌ عَلَى اللَّهِ حَتَّى يَتَوَفَّاهُ فَيُدْخِلَهُ الْجَنَّةَ، أَوْ يَرُدَّهُ بِمَا نَالَ مِنْ أَجْرٍ وَغَنِيمَةٍ. وَرَجُلٌ دَخَلَ بَيْتَهُ بِسَلَامٍ، فَهُوَ ضَامِنٌ عَلَى اللَّهِ عَزَّ وَجَلَّ". (ق,د,ن)', 'അബൂഉമാമതുൽ ബാഹിലി(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് പേർക്ക് അല്ലാഹു ജാമ്യം നിൽക്കുന്നതാണ്: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യാൻ പുറപ്പെട്ടയാൾ, ഒന്നുകിൽ അവനെ മരിപ്പിച്ച് സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയോ അല്ലെങ്കിൽ തനിക്ക് ലഭിച്ച പ്രതിഫലത്തോടും യുദ്ധമുതലോടും കൂടെ അവനെ മടക്കി അയക്കുകയോ ചെയ്യുന്ന കാര്യത്തിൽ അല്ലാഹു അവന് ജാമ്യം നിൽക്കുന്നതാണ്. മറ്റൊരുത്തൻ പള്ളിയിലേക്ക് പോകുന്ന വ്യക്തി, ഒന്നുകിൽ അവനെ മരിപ്പിച്ച് സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയോ അല്ലെങ്കിൽ തനിക്ക് ലഭിച്ച പ്രതിഫലത്തോടും മുതലോടും കൂടെ അവനെ തിരിച്ചയക്കുകയോ ചെയ്യുന്ന കാര്യത്തിൽ അല്ലാഹു അവന് ജാമ്യം നിൽക്കുന്നതാണ്. തന്റെ വീട്ടിലേക്ക് സലാം പറഞ്ഞ് പ്രവേശിക്കുന്നവനാണ് മറ്റൊരു വ്യക്തി. അവനും അല്ലാഹു ജാമ്യം നിൽക്കുന്നതാണ്." (ബു,മു,ദ,ന)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലി(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 884, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ عَلَى أُمِّ حَرَامٍ بِنْتِ مِلْحَانَ فَتُطْعِمُهُ، وَكَانَتْ أُمُّ حَرَامٍ تَحْتَ عُبَادَةَ بْنِ الصَّامِتِ، فَدَخَلَ عَلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَأَطْعَمَتْهُ وَجَلَسَتْ تَفْلِي رَأْسَهُ، فَنَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ اسْتَيْقَظَ وَهُوَ يَضْحَكُ، قَالَتْ: فَقُلْتُ: مَا يُضْحِكُكَ يَا رَسُولَ اللَّهِ. قَالَ: "نَاسٌ مِنْ أُمَّتِي، عُرِضُوا عَلَيَّ غُزَاةً فِي سَبِيلِ اللَّهِ، يَرْكَبُونَ ثَبَجَ هَذَا الْبَحْرِ، مُلُوكٌ عَلَى الْأَسِرَّةِ. أَوْ: مِثْلَ الْمُلُوكِ عَلَى الْأَسِرَّةِ". قُلْتُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. فَدَعَا لَهَا، ثُمَّ وَضَعَ رَأْسَهُ فَنَامَ، ثُمَّ اسْتَيْقَظَ وَهُوَ يَضْحَكُ، قَالَتْ: فَقُلْتُ: مَا يُضْحِكُكَ يَا رَسُولَ اللَّهِ؟ قَالَ: "نَاسٌ مِنْ أُمَّتِي عُرِضُوا عَلَيَّ غُزَاةً فِي سَبِيلِ اللَّهِ..." نَحْوَ مَا قَالَ فِي الْأَوَّلِ، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. قَالَ: "أَنْتِ مِنَ الْأَوَّلِينَ". قَالَ: فَرَكِبَتْ أُمُّ حَرَامٍ الْبَحْرَ فِي زَمَانِ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، فَصُرِعَتْ عَنْ دَابَّتِهَا حِينَ خَرَجَتْ مِنَ الْبَحْرِ، فَهَلَكَتْ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഉമ്മുഹറാം ബിൻത് മിൽഹാൻ(റ)യുടെ അടുത്ത് പോവുകയും അവർ റസൂൽ(സ)ക്ക് ഭക്ഷണം നൽകുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഉമ്മുഹറാം(റ) ഉബാദതുബിൻത് സ്വാമിത്(റ)വിന്റെ കീഴിലായിരുന്നു. ഒരു ദിവസം റസൂൽ(സ) ഉമ്മുഹറാം(റ)യുടെ അടുത്ത് പോവുകയും അവർ റസൂൽ(സ)ക്ക് ഭക്ഷണം നൽകുകയും ശേഷം അവർ തിരുമേനി(സ)യുടെ തലയിലെ പേൻ നോക്കാൻ വേണ്ടി ഇരിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) ഉറങ്ങി. ശേഷം പുഞ്ചിരിച്ച് കൊണ്ട് ഉണർന്നു. ഉമ്മുഹറാം(റ) ചോദിച്ചു: റസൂലേ, എന്തിനാണ് അങ്ങ് പുഞ്ചിരിക്കുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "കട്ടിലിലിരിക്കുന്ന രാജാക്കന്മാരായിട്ട് അല്ലെങ്കിൽ കട്ടിലിലിരിക്കുന്ന രാജാക്കന്മാരെപ്പോലെ ഈ കടലിന്റെ നടുവിലൂടെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാൻ വേണ്ടി യാത്ര പോകുന്ന എന്റെ സമുദായത്തിലെ ചിലയാളുകളെ എനിക്ക് കാണിക്കപ്പെട്ടു." ഉമ്മുഹറാം(റ) പറഞ്ഞു: റസൂലേ, അവരിൽ എന്നെയും ഉൾപ്പെടുത്താൻ അങ്ങ് പ്രാർത്ഥിക്കണം. അപ്പോൾ റസൂൽ(സ) അപ്രകാരം പ്രാർത്ഥിച്ചു. ശേഷം തലവെച്ചുറങ്ങി, പിന്നെയും പുഞ്ചിരിച്ചുകൊണ്ട് ഉണർന്നു. ഉമ്മുഹറാം(റ) ചോദിച്ചു: എന്തിനാണ് അങ്ങ് പുഞ്ചിരിക്കുന്നത്, റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവരായിട്ട് എന്റെ സമുദായത്തിൽപ്പെട്ട ചിലയാളുകളെ എനിക്ക് കാണിക്കപ്പെട്ടു....." മുമ്പ് പറഞ്ഞത് പോലെ റസൂൽ(സ) പറഞ്ഞു. ഉമ്മുഹറാം(റ) പറഞ്ഞു: എന്നെയും അവരിലുൾപ്പെടുത്താൻ അങ്ങ് പ്രാർത്ഥിക്കുക. റസൂൽ(സ) പറഞ്ഞു: "നീ ആദ്യക്കാരിൽപ്പെട്ടവളാണ്." നിവേദകൻ പറഞ്ഞു: ശേഷം മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)വിന്റെ കാലത്ത് ഉമ്മുഹറാം(റ) കടൽയാത്ര നടത്തി. കടലിൽ നിന്ന് പുറത്തുവന്നപ്പോൾ തന്റെ വാഹനത്തിൽ നിന്ന് വീണ് അവർ വഫാത്തായി. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 885, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "غَزْوَةٌ فِي الْبَحْرِ مِثْلُ عَشْرِ غَزَوَاتٍ فِي الْبَرِّ، وَالَّذِي يَسْدَرُ فِي الْبَحْرِ كَالْمُتَشَحِّطِ فِي دَمِهِ فِي سَبِيلِ اللَّهِ سُبْحَانَهُ". فِي إِسْنَادِهِ ضَعِيفٌ. (جه)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കടലിലുള്ള ഒരു യുദ്ധം കരയിലുള്ള പത്ത് യുദ്ധത്തിന് തുല്യമാണ്. കടലിൽ തലകറങ്ങി മരിക്കുന്നവൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രക്തം പുരണ്ട് മരിക്കുന്നവനെപ്പോലെയാണ്." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 885, 885, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "شَهِيدُ الْبَحْرِ مِثْلُ شَهِيدَيِ الْبَرِّ، وَالْمَائِدُ فِي الْبَحْرِ كَالْمُتَشَحِّطِ فِي دَمِهِ فِي الْبَرِّ، وَمَا بَيْنَ الْمَوْجَتَيْنِ كَقَاطِعِ الدُّنْيَا فِي طَاعَةِ اللَّهِ، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ وَكَّلَ مَلَكَ الْمَوْتِ بِقَبْضِ الْأَرْوَاحِ، إِلَّا شَهِيدَ الْبَحْرِ فَإِنَّهُ يَتَوَلَّى قَبْضَ أَرْوَاحِهِمْ، وَيَغْفِرُ لِشَهِيدِ الْبَرِّ الذُّنُوبَ كُلَّهَا إِلَّا الدَّيْنَ، وَلِشَهِيدِ الْبَحْرِ الذُّنُوبَ وَالدَّيْنَ". (جه)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "കടലിലെ ഒരു രക്തസാക്ഷി കരയിലെ രണ്ട് രക്തസാക്ഷിക്ക് തുല്യമാണ്. കടലിൽ തലകറങ്ങി മരിക്കുന്നവൻ കരയിൽ വെച്ച് രക്തം പുരണ്ട് മരിക്കുന്നവനെപ്പോലെയാണ്. രണ്ട് തിരമാലകൾക്കിടയിലുള്ള ദൂരം മുറിച്ചുകടക്കുന്നവൻ അല്ലാഹുവിന്റെ അനുസരണയിലായി ഐഹികലോകം മുഴുവൻ യാത്ര ചെയ്യുന്നവനെപ്പോലെയാണ്. കടലിലെ രക്തസാക്ഷിയുടേതല്ലാത്ത ആത്മാവുകളെ പിടിക്കാൻ അല്ലാഹു മരണമാലാഖയെ ചുമതലപ്പെടുത്തി. കടലിലെ രക്തസാക്ഷികളുടെ ആത്മാവുകളെ അല്ലാഹു തന്നെ ഏറ്റെടുക്കും. കരയിലെ രക്തസാക്ഷിക്ക് കടമല്ലാത്ത സർവ്വ പാപവും അല്ലാഹു പൊറുത്തുകൊടുക്കും. കടലിലെ രക്തസാക്ഷിക്ക് കടവും പാപങ്ങളും പൊറുത്തുകൊടുക്കും." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 886, 886, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَمَوْضِعُ سَوْطِ أَحَدِكُمْ مِنَ الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَالرَّوْحَةُ يَرُوحُهَا الْعَبْدُ فِي سَبِيلِ اللَّهِ أَوِ الْغَدْوَةُ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا". (ق,ت,ن,جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു രാപ്പകൽ സമയം ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ ഐഹിക ലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്. സ്വർഗ്ഗത്തിൽ നിങ്ങളിലൊരുത്തന്റെ കുതിരയുടെ കാലടി ഐഹിക ലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്. ദൈവിക മാർഗ്ഗത്തിൽ ഒരടിമ പ്രദോഷത്തിലോ പ്രഭാതത്തിലോ പുറപ്പെടൽ ഐഹികലോകത്തേക്കാളും അതിലുള്ള സർവ്വത്തേക്കാളും ഉത്തമമാണ്." (ബു,മു,തു,ന,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 886, 886, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَالَ: "كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ، إِلَّا الَّذِي مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ، فَإِنَّهُ يُنْمَى لَهُ عَمَلُهُ إِلَى يَوْمِ الْقِيَامَةِ، وَيَأْمَنُ مِنْ فِتْنَةِ الْقَبْرِ". قَالَ: وَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ". (د,ت)', 'ഫളാലതുബ്നു ഉബൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഴുവൻ മരിച്ചവരുടെയും കർമ്മങ്ങൾക്കു മേൽ സീൽ വെക്കപ്പെടും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ശത്രുവിനെ പ്രതീക്ഷിക്കുന്നവനായി മരിച്ചവനൊഴികെ. അന്ത്യനാൾ വരെ അവന്റെ കർമ്മങ്ങൾ വളർത്തപ്പെടുകയും ഖബ്റിലെ ശിക്ഷയെത്തൊട്ട് അവൻ സംരക്ഷിക്കപ്പെടുകയും ചെയ്യുന്നതാണ്." ഫളാല(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ധർമ്മയുദ്ധം നടത്തുന്നവനെന്നാൽ സ്വന്തം ശരീരത്തോട് പോരടിക്കുന്നവനാണ്." (ദ,തു)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 886, 886, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللَّهُ عَنْهُ، وَقَدْ مَرَّ بِشُرَحْبِيلَ بْنِ السِّمْطِ، وَهُوَ فِي مُرَابِطٍ لَهُ، وَقَدْ شَقَّ عَلَيْهِ وَعَلَى أَصْحَابِهِ، قَالَ: أَلَا أُحَدِّثُكَ يَا ابْنَ السِّمْطِ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: بَلَى. قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ أَفْضَلُ – وَرُبَّمَا قَالَ: خَيْرٌ مِنْ صِيَامِ شَهْرٍ وَقِيَامِهِ، وَمَنْ مَاتَ فِيهِ وُقِيَ فِتْنَةَ الْقَبْرِ، وَنُمِّيَ لَهُ عَمَلُهُ إِلَى يَوْمِ الْقِيَامَةِ". حَسَنٌ. (ت,ن)', 'സൽമാനുൽ ഫാരിസി(റ): ശുറഹ്ബീലുബ്നു സിംത്(റ) ശത്രുക്കളെ നിരീക്ഷിക്കുന്ന കേന്ദ്രത്തിലായിരിക്കെ, അദ്ദേഹവും തന്റെ അനുചരരും വളരെ ബുദ്ധിമുട്ടിക്കൊണ്ടിരിക്കുന്ന സന്ദർഭത്തിൽ സൽമാനുൽ ഫാരിസി(റ) അദ്ദേഹത്തിന്റെ അടുത്തുകൂടെ കടന്നുപോയി. സൽമാനുൽ ഫാരിസി(റ) പറഞ്ഞു: ഇബ്നു സിംത്, അല്ലാഹുവിന്റെ റസൂലിൽ നിന്നുകേട്ട ഒരു ഹദീസ് ഞാൻ നിനക്ക് പറഞ്ഞുതരട്ടെയോ? ഇബ്നു സിംത്(റ) പറഞ്ഞു: അതെ. സൽമാനുൽ ഫാരിസി(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു ദിവസം ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ ഒരു മാസം മുഴുവൻ നമസ്കരിക്കുന്നതിനേക്കാളും നോമ്പനുഷ്ഠിക്കുന്നതിനേക്കാളും ഉത്തമമായതാണ് - ഒരുപക്ഷേ, ''നല്ലതാണ്'' എന്നായിരിക്കും നബി(സ) പറഞ്ഞത് - ആ അവസ്ഥയിൽ ഒരുത്തൻ മരിച്ചാൽ ഖബ്റിലെ ശിക്ഷയിൽ നിന്നവൻ സംരക്ഷിക്കപ്പെടുകയും അന്ത്യനാൾ വരെ തന്റെ കർമ്മം അവന് വളർത്തപ്പെടുകയും ചെയ്യുന്നതാണ്." ഹദീസ് ഹസനാണ്. (തു,ന)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുൽ ഫാരിസി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 886, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ وَهُوَ عَلَى الْمِنْبَرِ: إِنِّي كَتَمْتُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَرَاهِيَةَ تَفَرُّقِكُمْ عَنِّي، ثُمَّ بَدَا لِي أَنْ أُحَدِّثَكُمُوهُ لِيَخْتَارَ امْرُؤٌ لِنَفْسِهِ مَا بَدَا لَهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ مِنَ الْمَنَازِلِ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): പ്രസംഗപീഠത്തിൽ നിൽക്കെ അദ്ദേഹം ഇപ്രകാരം പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ഒരു വചനത്തെ നിങ്ങൾ എന്നിൽ നിന്നും പിരിഞ്ഞുപോകുമോ എന്ന് പേടിച്ച് ഞാൻ മറച്ചുവെച്ചിരിക്കുന്നു. ഓരോ വ്യക്തിയും തനിക്കിഷ്ടമുള്ളത് തിരഞ്ഞെടുക്കട്ടെ എന്നു കരുതി നിങ്ങൾക്കത് പറഞ്ഞുതരണമെന്ന് പിന്നീട് എനിക്ക് തോന്നി. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു ദിവസം ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ വീട്ടിലിരിക്കുന്ന മറ്റുള്ള ആയിരം ദിവസങ്ങളേക്കാൾ നല്ലതാണ്." (തു,ന,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 887, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا يَجِدُ الشَّهِيدُ مِنْ مَسِّ الْقَتْلِ إِلَّا كَمَا يَجِدُ أَحَدُكُمْ مِنْ مَسِّ الْقَرْصَةِ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉറുമ്പ് കടിക്കുമ്പോൾ നിങ്ങളിലൊരുത്തനുണ്ടാകുന്ന അനുഭവമേ രക്തസാക്ഷിക്ക് മരണത്തിൽ നിന്നനുഭവപ്പെടൂ." (തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 887, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ شَيْءٌ أَحَبَّ إِلَى اللَّهِ مِنْ قَطْرَتَيْنِ وَأَثَرَيْنِ: قَطْرَةٌ مِنْ دُمُوعٍ فِي خَشْيَةِ اللَّهِ، وَقَطْرَةُ دَمٍ تُهَرَاقُ فِي سَبِيلِ اللَّهِ. وَأَمَّا الْأَثَرَانِ: فَأَثَرٌ فِي سَبِيلِ اللَّهِ، وَأَثَرٌ فِي فَرِيضَةٍ مِنْ فَرَائِضِ اللَّهِ". حَسَنٌ غَرِيبٌ. (ت)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് തുള്ളികളേക്കാളും രണ്ട് അടയാളങ്ങളേക്കാളും അല്ലാഹുവിന് ഇഷ്ടപ്പെട്ട ഒരു വസ്തുവുമില്ല: അല്ലാഹുവിനെ ഭയപ്പെട്ടതിനാലുള്ള കണ്ണുനീരിന്റെ തുള്ളി, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒലിപ്പിക്കപ്പെടുന്ന രക്തത്തുള്ളി (എന്നിവയാണ് രണ്ടു തുള്ളികൾ). അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള അടയാളവും അല്ലാഹുവിനുള്ള നിർബന്ധകാര്യങ്ങളിൽ ഒന്ന് ചെയ്തിട്ടുണ്ടാകുന്ന അടയാളവുമാണ് രണ്ട് അടയാളങ്ങൾ." ഹദീസ് ഹസനും ഗരീബുമാണ്. (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 887, 887, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ شُرَحْبِيلَ بْنِ السِّمْطِ رَضِيَ اللَّهُ عَنْهُ، عَنْ سَلْمَانَ الْخَيْرِ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَابَطَ يَوْمًا وَلَيْلَةً فِي سَبِيلِ اللَّهِ كَانَ لَهُ كَأَجْرِ صِيَامِ شَهْرٍ وَقِيَامِهِ. وَمَنْ مَاتَ مُرَابِطًا أُجْرِيَ لَهُ مِثْلُ ذَلِكَ مِنَ الْأَجْرِ، وَأُجْرِيَ عَلَيْهِ الرِّزْقُ، وَأَمِنَ مِنَ الْفَتَّانِ". (م,ن)', 'ശുറഹ്ബീലുബ്നു സിംത്(റ): സൽമാനുൽ ഖൈർ(റ)വിൽ നിന്ന് നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു രാപ്പകൽ സമയം ഒരുത്തൻ ശത്രുവിനെ പ്രതീക്ഷിച്ചിരുന്നാൽ ഒരു മാസം മുഴുവൻ നോമ്പനുഷ്ഠിക്കുകയും നമസ്കരിക്കുകയും ചെയ്ത പുണ്യം അവനുണ്ടാകും. ശത്രുവിനെ പ്രതീക്ഷിച്ച് കൊണ്ടിരിക്കെ ഒരുത്തൻ മരിച്ചാൽ അതുപോലുള്ള പ്രവർത്തനത്തിന്റെ കൂലി അവന് തുടരും. തന്റെ ഭക്ഷണം അവന് നൽകപ്പെടും. ശിക്ഷകളിൽ നിന്ന് അവൻ നിർഭയനാകും." (മു,ന)', 'شُرَحْبِيلَ بْنِ السِّمْطِ', 'ശുറഹ്ബീലുബ്നു സിംത്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 887, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ مِنَ الْمَنَازِلِ". وَفِي رِوَايَةٍ: "يَوْمٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ". (ن)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു ദിവസം ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ വീട്ടിലിരിക്കുന്ന മറ്റുള്ള ആയിരം ദിവസങ്ങളേക്കാൾ നല്ലതാണ്." മറ്റൊരു നിവേദനത്തിൽ: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള ഒരു ദിവസം മറ്റുള്ള ആയിരം ദിവസങ്ങളേക്കാളുത്തമമാണ്." (ന)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=75), 1, 'وَفِي رِوَايَةٍ: "يَوْمٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള ഒരു ദിവസം മറ്റുള്ള ആയിരം ദിവസങ്ങളേക്കാളുത്തമമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَطَبَ عُثْمَانُ بْنُ عَفَّانَ النَّاسَ، فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنِّي سَمِعْتُ حَدِيثًا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَمْ يَمْنَعْنِي أَنْ أُحَدِّثَكُمْ بِهِ إِلَّا الضَّنُّ بِكُمْ وَبِصَحَابَتِكُمْ، فَلْيَخْتَرْ مُخْتَارٌ لِنَفْسِهِ أَوْ لِيَدَعْ. سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَابَطَ لَيْلَةً فِي سَبِيلِ اللَّهِ سُبْحَانَهُ كَانَتْ كَأَلْفِ لَيْلَةٍ، صِيَامِهَا وَقِيَامِهَا". فِي إِسْنَادِهِ ضَعِيفٌ. (جه)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) ജനങ്ങളോട് പ്രസംഗിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു. ഓ ജനങ്ങളേ, റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ ഒരു ഹദീസ് കേട്ടു. നിങ്ങളോടും നിങ്ങളുടെ ആളുകളോടുമുള്ള താൽപര്യം മൂലമാണ് ഞാൻ നിങ്ങൾക്ക് അത് പറഞ്ഞുതരാതിരുന്നത്. ആർക്കെങ്കിലും അത് ആവശ്യമുണ്ടെങ്കിൽ ചെയ്യട്ടെ, അല്ലെങ്കിൽ ഉപേക്ഷിക്കട്ടെ. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരുത്തൻ ഒരു രാത്രി ശത്രുവിനെ പ്രതീക്ഷിച്ചിരുന്നാൽ ആയിരം രാത്രി നമസ്കരിക്കുകയും നോമ്പനുഷ്ഠിക്കുകയും ചെയ്തതുപോലെയാണ്." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ أَجْرَى عَلَيْهِ أَجْرَ عَمَلِهِ الصَّالِحِ الَّذِي كَانَ يَعْمَلُ، وَأَجْرَى عَلَيْهِ رِزْقَهُ، وَأَمِنَ مِنَ الْفَتَّانِ، وَبَعَثَهُ اللَّهُ يَوْمَ الْقِيَامَةِ آمِنًا مِنَ الْفَزَعِ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കുന്നവനായിട്ട് ഒരുത്തൻ മരിച്ചാൽ താൻ ചെയ്തുകൊണ്ടിരുന്ന സൽപ്രവർത്തനങ്ങൾ അല്ലാഹു അവന് തുടർത്തിക്കൊടുക്കും. അവന്റെ ഭക്ഷണവും അവന് നൽകും. ശിക്ഷകളിൽ നിന്ന് അവൻ നിർഭയനാകും. അന്ത്യനാളിൽ വിഭ്രാന്തികളിൽ നിന്ന് നിർഭയനായിട്ട് അല്ലാഹു അവനെ പുനർജനിപ്പിക്കും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 888, 888, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَرِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ، مِنْ وَرَاءِ عَوْرَةِ الْمُسْلِمِينَ، مُحْتَسِبًا، مِنْ غَيْرِ شَهْرِ رَمَضَانَ أَعْظَمُ أَجْرًا مِنْ عِبَادَةِ مِائَةِ سَنَةٍ، صِيَامِهَا وَقِيَامِهَا. وَرِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ، مِنْ وَرَاءِ عَوْرَةِ الْمُسْلِمِينَ، مُحْتَسِبًا، مِنْ شَهْرِ رَمَضَانَ، أَفْضَلُ عِنْدَ اللَّهِ وَأَعْظَمُ أَجْرًا أُرَاهُ قَالَ: مِنْ عِبَادَةِ أَلْفِ سَنَةٍ، صِيَامِهَا وَقِيَامِهَا. فَإِنْ رَدَّهُ اللَّهُ إِلَى أَهْلِهِ سَالِمًا لَمْ تُكْتَبْ عَلَيْهِ سَيِّئَةٌ أَلْفَ سَنَةٍ، وَتُكْتَبُ لَهُ الْحَسَنَاتُ، وَيُجْرَى لَهُ أَجْرُ الرِّبَاطِ إِلَى يَوْمِ الْقِيَامَةِ". ضَعِيفٌ. (جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകളെ സംരക്ഷിക്കാൻ വേണ്ടി, കൂലിയെ പ്രതീക്ഷിച്ച് റമളാനല്ലാത്ത ഒരു മാസത്തിൽ ഒരു ദിവസം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ നൂറുവർഷം നമസ്കാരവും നോമ്പുമനുഷ്ഠിച്ച് ആരാധന നടത്തുന്നതിലും കൂടുതൽ പ്രതിഫലമുള്ളതാണ്. മുസ്ലിംകളെ സംരക്ഷിക്കാൻ വേണ്ടി, കൂലി പ്രതീക്ഷിച്ച് റമളാൻ മാസത്തിലെ ഒരു ദിവസം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കൽ ആയിരം വർഷം നമസ്കാരവും നോമ്പുമനുഷ്ഠിച്ച് ആരാധന നടത്തുന്നതിലും കൂടുതൽ പ്രതിഫലമുള്ളതും അല്ലാഹുവിന്റെയടുത്ത് ഉത്തമവുമാണ്. സുരക്ഷിതനായി തന്റെ കുടുംബത്തിലേക്ക് അല്ലാഹു അവനെ മടക്കുകയാണെങ്കിൽ ആയിരം വർഷത്തേക്ക് ഒരു കുറ്റവും അവന് എഴുതപ്പെടുകയില്ല. അവന്റെ നന്മകൾ എഴുതപ്പെടുകയും അന്ത്യനാൾ വരെ ശത്രുവിനെ പ്രതീക്ഷിച്ചിരിക്കുന്നതിന്റെ കൂലി അവന് തുടർത്തപ്പെടുകയും ചെയ്യുന്നതാണ്." ഹദീസ് ബലഹീനമാണ്. (ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 888, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَدْخُلُ بَيْتًا بِالْمَدِينَةِ غَيْرَ بَيْتِ أُمِّ سُلَيْمٍ إِلَّا عَلَى أَزْوَاجِهِ، فَقِيلَ لَهُ؟ فَقَالَ: "إِنِّي أَرْحَمُهَا قُتِلَ أَخُوهَا مَعِي". (خ)', 'അനസ്(റ): നബി(സ) തന്റെ ഭാര്യമാരുടെ വീടുകൾ കൂടാതെ മദീനയിലെ ഒരു വീട്ടിലും കയറാറുണ്ടായിരുന്നില്ല, ഉമ്മു സുലൈമിന്റെ വീടൊഴികെ. അതിനെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഞാൻ ഉമ്മുസുലൈമിനോട് കരുണ കാണിക്കുന്നു. കാരണം എന്റെ കൂടെയുണ്ടായിരുന്ന അവളുടെ സഹോദരൻ വധിക്കപ്പെട്ടു." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ فَتًى مِنْ أَسْلَمَ قَالَ: يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ الْغَزْوَ، وَلَيْسَ مَعِي مَا أَتَجَهَّزُ [بِهِ]. قَالَ: "ائْتِ فُلَانًا، فَإِنَّهُ قَدْ كَانَ تَجَهَّزَ فَمَرِضَ". فَأَتَاهُ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُكَ السَّلَامَ وَيَقُولُ: أَعْطِنِي الَّذِي تَجَهَّزْتَ بِهِ. قَالَ: يَا فُلَانَةُ أَعْطِيهِ الَّذِي تَجَهَّزْتُ بِهِ، وَلَا تَحْبِسِي عَنْهُ شَيْئًا، فَوَاللَّهِ لَا تَحْبِسِي مِنْهُ شَيْئًا فَيُبَارَكَ لَكِ فِيهِ. (م)', 'അനസ്(റ): അസ്ലം ഗോത്രത്തിലെ ഒരു യുവാവ് പറഞ്ഞു: റസൂലേ, ഞാൻ യുദ്ധത്തിന് പോകാനാഗ്രഹിക്കുന്നു. പക്ഷേ, എന്റെ അടുത്ത് അതിനുള്ള സന്നാഹങ്ങളില്ല. റസൂൽ(സ) പറഞ്ഞു: "നീ ഇന്നയാളുടെ അടുത്ത് പോവുക. അദ്ദേഹം യുദ്ധസന്നാഹം നടത്തിയിരുന്നു. പക്ഷേ, അദ്ദേഹം രോഗിയായി." അപ്പോൾ ആ യുവാവ് അയാളുടെ അടുത്ത് പോയി പറഞ്ഞു: റസൂൽ(സ) അങ്ങയോട് സലാം പറയുകയും അങ്ങയുടെ യുദ്ധസന്നാഹങ്ങൾ എനിക്ക് നൽകണമെന്ന് പറയുകയും ചെയ്തിരിക്കുന്നു. ആ മനുഷ്യൻ പറഞ്ഞു: പെണ്ണേ, എന്റെ യുദ്ധസജ്ജീകരണങ്ങളെ ഇവന് നൽകൂ. അതിൽ നിന്ന് ഒന്നും നീ തടഞ്ഞുവെക്കരുത്. അല്ലാഹു തന്നെ സത്യം, നീ അതിൽ നിന്ന് തടഞ്ഞുവെക്കുന്ന ഒന്നിലും അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യില്ല. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'بِهِ', null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ فَقَدْ غَزَا، وَمَنْ خَلَفَهُ فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا". (ق,د,ت,ن,جه)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു യോദ്ധാവിന് വേണ്ട സന്നാഹങ്ങൾ നൽകിയാൽ അവൻ യുദ്ധം ചെയ്തിരിക്കുന്നു. ആരെങ്കിലും ഒരു യോദ്ധാവിന്റെ കുടുംബത്തെ നല്ല നിലക്ക് പരിചരിച്ചാൽ അവൻ യുദ്ധം ചെയ്തിരിക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 889, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى بَنِي لَحْيَانَ وَقَالَ: "لِيَخْرُجْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ". ثُمَّ قَالَ لِلْقَاعِدِ: "أَيُّكُمْ خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ". (م,د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ബനൂലിഹ്യാൻ ഗോത്രത്തിലേക്ക് റസൂൽ(സ) സന്ദേശമയച്ചു: "ഓരോ ഈരണ്ടുപേരിൽ ഒരാൾ യുദ്ധത്തിന് പുറപ്പെടണം." പിന്നെ യുദ്ധത്തിന് പോകാത്തവരോടായി അവിടന്ന് പറഞ്ഞു: "നിങ്ങളിൽ ആരാണോ യുദ്ധത്തിന് പോകുന്നവന്റെ കുടുംബത്തെയും മുതലിനെയും സംരക്ഷിക്കുന്നത് അവന് യുദ്ധത്തിന് പോയവന്റെ പകുതി പ്രതിഫലമുണ്ടാകും." (മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ الْأَحْنَفِ بْنِ قَيْسٍ قَالَ: خَرَجْنَا حُجَّاجًا، فَقَدِمْنَا الْمَدِينَةَ وَنَحْنُ نُرِيدُ الْحَجَّ، فَبَيْنَا نَحْنُ فِي مَنَازِلِنَا نَضَعُ رِحَالَنَا إِذْ أَتَانَا آتٍ فَقَالَ: إِنَّ النَّاسَ قَدِ اجْتَمَعُوا فِي الْمَسْجِدِ وَفَزِعُوا، فَانْطَلَقْنَا فَإِذَا النَّاسُ مُجْتَمِعُونَ عَلَى نَفَرٍ فِي وَسَطِ الْمَسْجِدِ، وَفِيهِمْ عَلِيٌّ وَالزُّبَيْرُ وَطَلْحَةُ وَسَعْدُ بْنُ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُمْ، فَإِنَّا لَكَذَلِكَ إِذْ جَاءَ عُثْمَانُ رَضِيَ اللَّهُ عَنْهُ عَلَيْهِ مُلَاءَةٌ صَفْرَاءُ، قَدْ قَنَّعَ بِهَا رَأْسَهُ، فَقَالَ: أَهَاهُنَا طَلْحَةُ؟ أَهَاهُنَا الزُّبَيْرُ؟ أَهَاهُنَا سَعْدٌ؟ قَالُوا: نَعَمْ. قَالَ: فَإِنِّي أَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، أَتَعْلَمُونَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ يَبْتَاعُ مِرْبَدَ بَنِي فُلَانٍ غَفَرَ اللَّهُ لَهُ". فَابْتَعْتُهُ بِعِشْرِينَ أَلْفًا، أَوْ بِخَمْسَةٍ وَعِشْرِينَ أَلْفًا، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَقَالَ: "اجْعَلْهُ فِي مَسْجِدِنَا، وَأَجْرُهُ لَكَ". قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: أَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ ابْتَاعَ بِئْرَ رُومَةَ غَفَرَ اللَّهُ لَهُ". فَابْتَعْتُهَا بِكَذَا وَكَذَا، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: قَدِ ابْتَعْتُهَا بِكَذَا وَكَذَا، قَالَ: "اجْعَلْهَا سِقَايَةً لِلْمُسْلِمِينَ، وَأَجْرُهَا لَكَ". قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: أَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَظَرَ فِي وُجُوهِ الْقَوْمِ فَقَالَ: "مَنْ يُجَهِّزُ هَؤُلَاءِ غَفَرَ اللَّهُ لَهُ". يَعْنِي جَيْشَ الْعُسْرَةِ، فَجَهَّزْتُهُمْ حَتَّى لَمْ يَفْقِدُوا عِقَالًا وَلَا خِطَامًا؟ فَقَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ. (ن)', 'അഹ്നഫുബ്നു ഖൈസ്(റ): ഞങ്ങൾ ഹജ്ജിന് പുറപ്പെട്ടു. ഹജ്ജ് ഉദ്ദേശിച്ച് ഞങ്ങൾ മദീനയിലെത്തി. താമസസ്ഥലത്ത് ഞങ്ങളുടെ ചരക്ക് ഇറക്കിവെക്കവെ ഒരാൾ വന്നു പറഞ്ഞു: ജനങ്ങൾ പള്ളിയിൽ ഒരുമിച്ച് കൂടിയിരിക്കുന്നു, അവർ വിഭ്രാന്തിയിലാണ്. അങ്ങനെ ഞങ്ങൾ പോയിനോക്കുമ്പോൾ പള്ളിയുടെ മധ്യഭാഗത്ത് ചിലയാളുകൾക്ക് ചുറ്റും ജനങ്ങൾ കൂടിനിൽകുന്നു. അലി(റ), സുബൈർ(റ), ത്വൽഹ(റ), സഅ്ദുബ്നു അബീവഖാസ്(റ) എന്നിവർ അക്കൂട്ടത്തിലുണ്ട്. അങ്ങനെയിരിക്കെ മഞ്ഞവസ്ത്രമണിഞ്ഞ് അതുകൊണ്ടുതന്നെ തല മൂടി ഉസ്മാൻ(റ) വന്നു. എന്നിട്ട് ചോദിച്ചു: സുബൈർ(റ) ഇവിടെയുണ്ടോ? ത്വൽഹ(റ) ഇവിടെയുണ്ടോ? സഅ്ദ്(റ) ഇവിടെയുണ്ടോ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: തന്നെ കൂടാതെ മറ്റൊരു ഇലാഹില്ലാത്ത അല്ലാഹുവിനെ മുൻനിർത്തി ഞാൻ ചോദിക്കുന്നു: നിങ്ങൾക്കറിയില്ലേ, റസൂൽ(സ) പറഞ്ഞു: "ഇന്നയാളുടെ മിർബദ് (ഈത്തപ്പഴം ഉണക്കാനിടുന്ന സ്ഥലം) ആരെങ്കിലും വാങ്ങിയാൽ അല്ലാഹു അവനു പൊറുത്തുകൊടക്കുന്നതാണ്." അപ്പോൾ 20,000 അല്ലെങ്കിൽ 25,000 നൽകി ഞാനത് വാങ്ങി, റസൂൽ(സ)യുടെ അടുത്ത്ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീ അത് നമ്മുടെ പള്ളിയിൽ ഉൾപ്പെടുത്തുക. അതിന്റെ പ്രതിഫലം നിനക്ക് തന്നെയായിരിക്കും." അവർ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അത് ശരിയാണ്. ഉസ്മാൻ(റ) പറഞ്ഞു: തന്നെ കൂടാതെ മറ്റൊരു ഇലാഹില്ലാത്ത അല്ലാഹുവിനെ മുൻനിർത്തി ഞാൻ ചോദിക്കുന്നു: നിങ്ങൾക്കറിയില്ലേ, റസൂൽ(സ) പറഞ്ഞു: "റൂമാ കിണർ വാങ്ങുന്നവന്ന് അല്ലാഹു പൊറുത്തുകൊടുക്കുന്നതാണ്." അപ്പോൾ ഇത്ര വില കൊടുത്ത് ഞാനത് വാങ്ങി. ഞാൻ തിരുമേനി(സ)യെ സമീപിച്ചു പറഞ്ഞു: ഇത്ര വില നൽകി ഞാനത് വാങ്ങിയിരിക്കുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീ അത് മുസ്ലിംകൾക്ക് വെള്ളമെടുക്കാനുള്ള സ്ഥലമാക്കുക. അതിന്റെ പ്രതിഫലം നിനക്കാണ്." അവർ പറഞ്ഞു: അല്ലാഹു സത്യം, അതു ശരിയാണ്. ഉസ്മാൻ(റ) പറഞ്ഞു: തന്നെകൂടാതെ മറ്റൊരു ഇലാഹില്ലാത്ത അല്ലാഹുവിനെ മുൻനിർത്തി ഞാൻ ചോദിക്കുന്നു: നിങ്ങൾക്കറിയില്ലേ, റസൂൽ(സ) ജനങ്ങളുടെ മുഖത്തുനോക്കി ഇപ്രകാരം പറഞ്ഞു: "യുദ്ധസാമഗ്രികൾ നൽകി ഇവരെ യുദ്ധത്തിന് സജ്ജമാക്കുന്നവർക്ക് അല്ലാഹു പൊറുത്തു കൊടുക്കുന്നതാണ്." തബൂക്കിലേക്കുള്ള സൈന്യത്തെയാണ് ഉദ്ദേശിക്കുന്നത്. അപ്പോൾ ഞാനവർക്ക് വേണ്ട സാമഗ്രികൾ നൽകി. ഒരു കയറിന്റെയോ മൂക്കയറിന്റേയോ കുറവ് പോലും അവർക്ക് വന്നില്ല. അവർ പറഞ്ഞു: അല്ലാഹു സത്യം, അതു ശരിയാണ്. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവേ നീ സാക്ഷിയാവുക, അല്ലാഹുവേ നീ സാക്ഷിയാവുക, അല്ലാഹുവേ നീ സാക്ഷിയാവുക. (ന)', 'الْأَحْنَفِ بْنِ قَيْسٍ قَالَ', 'അഹ്നഫുബ്നു ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 890, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ حَتَّى يَسْتَقِلَّ كَانَ لَهُ مِثْلُ أَجْرِهِ، حَتَّى يَمُوتَ أَوْ يَرْجِعَ". (جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്യുന്നവന് പൂർണമായ രീതിയിൽ ആരെങ്കിലും സജ്ജീകരണങ്ങൾ ചെയ്താൽ ആ യോദ്ധാവ് മരിക്കുംവരെയോ അല്ലെങ്കിൽ മടങ്ങും വരെയോ ആ യോദ്ധാവിന്റെ പ്രതിഫലം ഇവന്നുമുണ്ടാകും." (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ زَيْدِ بْنِ خَالِدِ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ كَانَ لَهُ مِثْلُ أَجْرِهِ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَجْرِ الْغَازِي شَيْئًا". (ت,جه)', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള ഒരു യോദ്ധാവിന് വേണ്ട സാമഗ്രികൾ നൽകിയാൽ ആ യോദ്ധാവിന് ലഭിക്കുന്ന പ്രതിഫലത്തിൽ ഒരു കുറവും വരാതെ അതുപോലുള്ള പ്രതിഫലം അവനും ലഭിക്കുന്നതാണ്." (തു,ജ)', 'زَيْدِ بْنِ خَالِدِ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ غَازِيَةٍ أَوْ سَرِيَّةٍ تَغْزُو، فَتَغْنَمُ وَتَسْلَمُ، إِلَّا كَانُوا قَدْ تَعَجَّلُوا ثُلُثَيْ أُجُورِهِمْ. وَمَا مِنْ غَازِيَةٍ أَوْ سَرِيَّةٍ تُخْفِقُ وَتُصَابُ إِلَّا تَمَّ أُجُورُهُمْ". (م,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധം ചെയ്ത് യുദ്ധമുതൽ ലഭിച്ച് രക്ഷപ്പെടുന്ന ഒരു സൈന്യവുമില്ല, തങ്ങളുടെ പ്രതിഫലത്തിന്റെ മൂന്നിൽ രണ്ടുഭാഗം അവർക്ക് പെട്ടെന്ന് ലഭിച്ചിട്ടല്ലാതെ. ലക്ഷ്യം നേടാതെ വിപത്തിൽ പെടുന്ന ഒരു സൈന്യവുമില്ല. അവരുടെ പ്രതിഫലം മുഴുവൻ ലഭിച്ചിട്ടല്ലാതെ." (മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ غَازِيَةٍ تَغْزُو فِي سَبِيلِ اللَّهِ، فَيُصِيبُونَ غَنِيمَةً، إِلَّا تَعَجَّلُوا ثُلُثَيْ أَجْرِهِمْ مِنَ الْآخِرَةِ وَيَبْقَى لَهُمُ الثُّلُثُ، فَإِنْ لَمْ يُصِيبُوا غَنِيمَةً تَمَّ لَهُمْ أَجْرُهُمْ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത് യുദ്ധമുതൽ ലഭിക്കുന്ന ഒരു സൈന്യവുമില്ല, ആഖിറത്തിൽ നിന്നുള്ള തങ്ങളുടെ പ്രതിഫലത്തിന്റെ മൂന്നിൽ രണ്ടുഭാഗം ആദ്യമേ അവർക്കു ലഭിച്ചിട്ടല്ലാതെ. ബാക്കി മൂന്നിൽ ഒരു ഭാഗം അവർക്കു ശേഷിക്കും. അവർക്ക് യുദ്ധമുതൽ ലഭിക്കുന്നെങ്കിൽ അവരുടെ പ്രതിഫലം മുഴുവൻ അവർക്ക് ലഭിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فِيمَا يَحْكِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ – قَالَ: "أَيُّمَا عَبْدٍ مِنْ عِبَادِي خَرَجَ مُجَاهِدًا فِي سَبِيلِ اللَّهِ، ابْتِغَاءَ مَرْضَاتِي، ضَمِنْتُ لَهُ أَنْ أُرْجِعَهُ إِنْ أَرْجَعْتُهُ بِمَا أَصَابَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ، وَإِنْ قَبَضْتُهُ غَفَرْتُ لَهُ وَرَحِمْتُهُ". (ن)', 'ഇബ്നുഉമർ(റ): തന്റെ രക്ഷിതാവ് പറഞ്ഞതായിട്ട് റസൂൽ(സ) പറയുന്നു: "എന്റെ തൃപ്തിയെ കാംക്ഷിച്ചുകൊണ്ട് എന്റെ ഏതെങ്കിലുമൊരു അടിമ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാൻ പോയാൽ, അവൻ മടങ്ങുകയാണെങ്കിൽ പ്രതിഫലത്തോടും യുദ്ധമുതലോടും കൂടെ ഞാനവനെ മടക്കുമെന്നും ഞാനവന്റെ ആത്മാവിനെ പിടിക്കുകയാണെങ്കിൽ അവന് പൊറുത്തുകൊടുക്കുമെന്നും കരുണചെയ്യുമെന്നും ഞാൻ ജാമ്യം നിൽക്കുന്നു." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ تَبُوكَ يَخْطُبُ النَّاسَ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى رَاحِلَتِهِ، فَقَالَ: "أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ وَشَرِّ النَّاسِ؟ إِنَّ مِنْ خَيْرِ النَّاسِ رَجُلًا عَمِلَ فِي سَبِيلِ اللَّهِ عَلَى ظَهْرِ فَرَسِهِ، أَوْ عَلَى ظَهْرِ بَعِيرِهِ، أَوْ عَلَى قَدَمِهِ، حَتَّى يَأْتِيَهُ الْمَوْتُ. وَإِنَّ مِنْ شَرِّ النَّاسِ رَجُلًا فَاجِرًا، يَقْرَأُ كِتَابَ اللَّهِ، لَا يَرْعَوِي إِلَى شَيْءٍ مِنْهُ". (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): തബൂക് യുദ്ധദിവസം റസൂൽ(സ) തന്റെ ഒട്ടകക്കട്ടിലിൽ ചാരി ജനങ്ങളോട് പ്രസംഗിച്ചുകൊണ്ടിരിക്കുമ്പോൾ പറഞ്ഞു: "ജനങ്ങളിൽ ഉത്തമരെക്കുറിച്ചും ദുഷിച്ചവരെക്കുറിച്ചും ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ? തന്റെ കുതിരപ്പുറത്തോ, ഒട്ടകപ്പുറത്തോ അല്ലെങ്കിൽ കാൽ നടയായോ മരിക്കുംവരെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവൻ ജനങ്ങളിലെ ഉത്തമരിൽപ്പെട്ടവനാണ്. അല്ലാഹുവിന്റെ ഗ്രന്ഥം പാരായണം ചെയ്യുകയും അതിലുള്ള ഒന്നിനെയും സൂക്ഷിക്കാതിരിക്കുകയും ചെയ്യുന്ന തെമ്മാടിയായ മനുഷ്യൻ ഏറ്റവും ദുഷിച്ച ജനങ്ങളിൽപ്പെട്ടവനാണ്." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَا يَبْكِي أَحَدٌ مِنْ خَشْيَةِ اللَّهِ فَتَطْعَمُهُ النَّارُ حَتَّى يُرَدَّ اللَّبَنُ فِي الضَّرْعِ، وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ فِي مَنْخَرَيْ مُسْلِمٍ أَبَدًا. (ن)', 'അബൂഹുറൈറ(റ): പാൽ അകിടിലേക്ക് മടക്കപ്പെടുംവരെ¹ അല്ലാഹുവിനെ പേടിച്ച് കരഞ്ഞ ഒരുത്തനെ നരകം ഭക്ഷിക്കുകയില്ല. ഒരു മുസ്ലിമിന്റെ തരിമൂക്കിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള യുദ്ധക്കളത്തിലെ പൊടിയും നരകത്തിലെ പുകയും ഒരിക്കലും ഒരുമിച്ചുകൂടുകയില്ല. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '¹ പാൽ അകിടിലേക്കുതന്നെ മടക്കപ്പെടുക എന്നത് അസംഭവ്യമായതുപോലെ അല്ലാഹുവിനെയോർത്ത് കരഞ്ഞവനെ നരകം ഭക്ഷിക്കുക എന്നതും അസംഭവ്യമാണെന്നർത്ഥം.', null, array['ن']::text[], array['ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَلِجُ النَّارَ رَجُلٌ بَكَى مِنْ خَشْيَةِ اللَّهِ تَعَالَى حَتَّى يَعُودَ اللَّبَنُ فِي الضَّرْعِ، وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ نَارِ جَهَنَّمَ". (ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പാൽ അകിടിലേക്ക് മടങ്ങുംവരെ അല്ലാഹുവിനെ പേടിച്ച് കരഞ്ഞവൻ നരകത്തിൽ പ്രവേശിക്കുകയില്ല. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള (യുദ്ധക്കളത്തിൽ) പൊടിയും നരകത്തിലെ തീയിന്റെ പുകയും ഒരുമിച്ചുകൂടുകയില്ല." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَجْتَمِعَانِ فِي النَّارِ: مُسْلِمٌ قَتَلَ كَافِرًا ثُمَّ سَدَّدَ وَقَارَبَ. وَلَا يَجْتَمِعَانِ فِي جَوْفِ مُؤْمِنٍ: غُبَارٌ فِي سَبِيلِ اللَّهِ وَفَيْحُ جَهَنَّمَ. وَلَا يَجْتَمِعَانِ فِي قَلْبِ عَبْدٍ: الْإِيمَانُ وَالْحَسَدُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു അവിശ്വാസിയെ വധിച്ച ശേഷം നല്ലനിലയിലായി ജീവിച്ച മുസ്ലിമും (അവൻ വധിച്ച അവിശ്വാസിയും) നരകത്തിൽ ഒരുമിക്കുകയില്ല. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലെ (യുദ്ധത്തിലുള്ള) പൊടിയും നരകത്തിലെ പുകയും സത്യവിശ്വാസിയുടെ ഉള്ളിൽ ഒരുമിക്കുകയില്ല. ഒരു അടിമയുടെ ഹൃദയത്തിൽ വിശ്വാസവും അസൂയയും ഒരുമിക്കുകയില്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 892, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لاَ يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ فِي جَوْفِ عَبْدٍ – وَفِي رِوَايَةٍ: وَجْهِ رَجُلٍ – أَبَدًا، وَلاَ يَجْتَمِعُ الشُّحُّ وَالإِيمَانُ فِي قَلْبٍ – وَفِي رِوَايَةٍ: جَوْفِ – عَبْدٍ أَبَدًا. (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു അടിമയുടെ ഉള്ളിൽ നരകത്തിലെ പുകയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള സമരത്തിലെ പൊടിയും ഒരുമിക്കുകയില്ല." ഒരു നിവേദനത്തിൽ: "ഒരുത്തന്റെ മുഖത്ത് ഒരിക്കലും" എന്നുണ്ട്. "ഒരു അടിമയുടെ ഹൃദയത്തിൽ വിശ്വാസവും പിശുക്കും ഒരുമിക്കുകയില്ല." ഒരു നിവേദനത്തിൽ "അടിമയുടെ ഉള്ളിൽ ഒരിക്കലും" എന്നാണുള്ളത്. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=93), 1, 'وَفِي رِوَايَةٍ: وَجْهِ رَجُلٍ – أَبَدًا، وَلاَ يَجْتَمِعُ الشُّحُّ وَالإِيمَانُ فِي قَلْبٍ –', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=93), 2, 'وَفِي رِوَايَةٍ: جَوْفِ – عَبْدٍ أَبَدًا. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لاَ يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَدُخَانُ جَهَنَّمَ فِي مَنْخَرَيْ مُسْلِمٍ أَبَدًا، وَلاَ يَجْتَمِعُ شُحٌّ وَإِيمَانٌ فِي قَلْبِ رَجُلٍ مُسْلِمٍ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള (യുദ്ധത്തിലെ) പൊടിപടലവും നരകത്തിലെ പുകയും ഒരിക്കലും ഒരു മുസ്ലിമിന്റെ തരിമൂക്കിൽ ഒരുമിക്കുകയില്ല. ഒരു മുസ്ലിമായ വ്യക്തിയുടെ ഹൃദയത്തിൽ വിശ്വാസവും പിശുക്കും ഒരുമിക്കുന്നതല്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ يَزِيدِ بْنِ أَبِي مَرْيَمَ قَالَ: لَحِقَنِي عَبَايَةُ بْنُ رَافِعٍ وَأَنَا مَاشٍ إِلَى الْجُمُعَةِ فَقَالَ: أَبْشِرْ، فَإِنَّ خُطَاكَ هَذِهِ فِي سَبِيلِ اللَّهِ، سَمِعْتُ أَبَا عَبْسٍ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اغْبَرَّتْ قَدَمَاهُ فِي سَبِيلِ اللَّهِ فَهُوَ حَرَامٌ عَلَى النَّارِ". (خ,ت,ن)', 'യസീദുബ്നു മർയം(റ): ഞാൻ ജുമുഅക്ക് വേണ്ടി നടന്നുകൊണ്ടിരിക്കെ അബായതുബ്നു റാഫിഅ്(റ) എന്നെ കണ്ടുമുട്ടി. അദ്ദേഹം പറഞ്ഞു: താങ്കൾ സന്തോഷിക്കുക. താങ്കളുടെ ഈ കാലടികൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ളതാണ്. അബൂഅബ്സ്(റ) പറയുന്നതായി ഞാൻ കേട്ടു: റസൂൽ(സ) പറഞ്ഞു: "ഒരുത്തന്റെ പാദങ്ങളിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പൊടിപുരണ്ടാൽ അത് നരകത്തിന് നിഷിദ്ധമാണ്." (ബു,തു,ന)', 'يَزِيدِ بْنِ أَبِي مَرْيَمَ قَالَ', 'യസീദുബ്നു മർയം(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَتُفْتَحُ عَلَيْكُمْ أَرَضُونَ وَيَكْفِيكُمُ اللَّهُ، فَلَا يَعْجِزُ أَحَدُكُمْ أَنْ يَلْهُوَ بِأَسْهُمِهِ". (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾക്ക് നാടുകൾ കീഴടങ്ങും. നിങ്ങളുടെ ശത്രുക്കളുടെ ശല്യം അവസാനിക്കും. അപ്പോൾ നിങ്ങളിലൊരുത്തനും അമ്പെയ്ത് അഭ്യസിക്കാതിരിക്കരുത്." (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 893, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شَمَاسَةَ: أَنَّ فُقَيْمًا اللَّخْمِيَّ قَالَ لِعُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ: تَخْتَلِفُ بَيْنَ هَذَيْنِ الْغَرَضَيْنِ، وَأَنْتَ كَبِيرٌ يَشُقُّ عَلَيْكَ؟ قَالَ عُقْبَةُ: لَوْلَا كَلَامٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ أُعَانِيهِ. قَالَ الْحَارِثُ: فَقُلْتُ لِابْنِ شَمَاسَةَ: وَمَا ذَاكَ؟ قَالَ: إِنَّهُ قَالَ: "مَنْ عَلِمَ الرَّمْيَ ثُمَّ تَرَكَهُ فَلَيْسَ مِنَّا. أَوْ قَدْ عَصَى". (م)', 'അബ്ദുർറഹ്മാനുബ്നു ശമാമ(റ): ഫുഖൈമുല്ലഖ്മി(റ) ഉഖ്ബതുബ്നു ആമിർ(റ)വിനോട് പറഞ്ഞു: താങ്കൾ ഈ രണ്ടു നാട്ടക്കുറികൾക്കിടയിൽ പോയിവരുന്നു, താങ്കൾ പ്രായമുള്ളയാളായതിനാൽ അത് അങ്ങേക്ക് ബുദ്ധിമുട്ടാവില്ലേ? ഉഖ്ബ(റ) പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ കേട്ട ഒരു കാര്യമില്ലായിരുന്നുവെങ്കിൽ ഞാനതിനെ ഗൗനിക്കുമായിരുന്നില്ല. ഹാരിസ്(റ) പറഞ്ഞു: ഞാൻ ഇബ്നുശമ്മാസ്(റ)വിനോട് ചോദിച്ചു: ആ കാര്യം എന്താണ്? ഇബ്നുശമ്മാസ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "ഒരുത്തന് അമ്പെയ്ത്ത് അറിയുകയും ശേഷം അവനത് ഉപേക്ഷിക്കുകയും ചെയ്താൽ അവൻ നമ്മിൽപ്പെട്ടവനല്ല. അല്ലെങ്കിൽ അവൻ കുറ്റക്കാരനായിരിക്കുന്നു." (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ شَمَاسَةَ', 'അബ്ദുർറഹ്മാനുബ്നു ശമാമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ تَعَالَى كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ، وَمَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ تَعَالَى – بَلَغَ الْعَدُوَّ أَوْ لَمْ يَبْلُغْ – كَانَ لَهُ كَعِتْقِ رَقَبَةٍ، وَمَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً كَانَتْ لَهُ فِدَاءَهُ مِنَ النَّارِ: عُضْوًا بِعُضْوٍ". (ن)', 'അംറുബ്നു അബസ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലായിട്ട് ഒരുത്തൻ നരച്ചാൽ (വൃദ്ധനായാൽ) അത് അന്ത്യനാളിൽ അവന് പ്രകാശമായി മാറും. ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു അമ്പെയ്താൽ അത് അവന് ഒരു അടിമയെ മോചിപ്പിക്കുന്നതിന് തുല്യമായിരിക്കും, ആ അമ്പ് ശത്രുവിന് ഏറ്റാലും ഇല്ലെങ്കിലും. ആരെങ്കിലും ഒരു സത്യവിശ്വാസിയായ അടിമയെ മോചിപ്പിച്ചാൽ അത് അവന് നരകമോചനകാരണമാകുന്നതാണ്. ഓരോ അവയവങ്ങൾക്ക് പകരം ഓരോ അവയവവും." (ന)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي نَجِيحٍ السُّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ بَلَغَ بِسَهْمٍ فِي سَبِيلِ اللَّهِ فَهُوَ لَهُ دَرَجَةٌ فِي الْجَنَّةِ". فَبَلَّغْتُ يَوْمَئِذٍ سِتَّةَ عَشَرَ سَهْمًا. قَالَ: وَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ فَهُوَ عِدْلُ مُحَرَّرٍ". (د,ت,ن,جه)', 'അബൂനജീഹുസ്സലമി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു അമ്പെയ്ത് കൊള്ളിച്ചാൽ അത് അവന് സ്വർഗ്ഗത്തിൽ ഒരു സ്ഥാനമായിരിക്കും." അങ്ങനെ ഒരു ദിവസം ഞാൻ പതിനാറ് അമ്പെയ്ത് കൊള്ളിച്ചു. അബൂനജീഹ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും ഒരു അമ്പെയ്താൽ ഒരു അടിമയെ മോചിപ്പിച്ചതിന് തുല്യമാണ്." (ദ,തു,ന,ജ)', 'أَبِي نَجِيحٍ السُّلَمِيِّ', 'അബൂനജീഹുസ്സലമി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ شُرَحْبِيلَ بْنِ السِّمْطِ رَضِيَ اللَّهُ عَنْهُ: قَالَ لِكَعْبِ بْنِ مُرَّةَ رَضِيَ اللَّهُ عَنْهُ: يَا كَعْبُ، حَدِّثْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاحْذَرْ. قَالَ: سَمِعْتُهُ يَقُولُ: "مَنْ شَابَ شَيْبَةً فِي الْإِسْلَامِ فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ". سَمِعْتُهُ يَقُولُ: "ارْمُوا مَنْ بَلَغَ الْعَدُوَّ بِسَهْمٍ رَفَعَهُ اللَّهُ بِهِ دَرَجَةً". قَالَ ابْنُ النَّحَّامِ: يَا رَسُولَ اللَّهِ، وَمَا الدَّرَجَةُ؟ قَالَ: "أَمَا إِنَّهَا لَيْسَتْ بِعَتَبَةِ أُمِّكَ، وَلَكِنْ مَا بَيْنَ الدَّرَجَتَيْنِ مِائَةُ عَامٍ". (ن)', 'ശുറഹ്ബീലുബ്നു സ്വിംത്(റ): അദ്ദേഹം കഅ്ബുബ്നു മുർറ(റ)വിനോട് പറഞ്ഞു: കഅ്ബേ, റസൂൽ(സ)യുടെ ഹദീസ് നീ ഞങ്ങൾക്ക് പറഞ്ഞുതരിക, നീ സൂക്ഷ്മത പുലർത്തുകയും ചെയ്യുക. കഅ്ബ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആർക്കെങ്കിലും ഇസ്ലാമിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലായിട്ട് നര ബാധിച്ചാൽ അത് അന്ത്യനാളിൽ അവന് പ്രകാശമായി മാറുന്നതാണ്." റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ അമ്പെയ്യുക. ആരെങ്കിലും ഒരു ശത്രുവിനെ അമ്പെയ്ത് കൊള്ളിച്ചാൽ സ്വർഗ്ഗത്തിൽ അല്ലാഹു അവന് ഒരു പദവി വർദ്ധിപ്പിക്കുന്നതാണ്." അന്നേരം ഇബ്നുന്നഹാം(റ) ചോദിച്ചു: റസൂലേ, എന്താണ് ആ പദവി? റസൂൽ(സ) പറഞ്ഞു: "അത് നിന്റെ ഉമ്മയുടെ (വീട്ടിലെ) വാതിൽ പടിയല്ല, അതിൽ നിന്ന് ഓരോ രണ്ടെണ്ണത്തിന്റെയും ഇടയിലെ ദൂരം നൂറ് വർഷത്തെ വഴിദൂരമാണ്." (ന)', 'شُرَحْبِيلَ بْنِ السِّمْطِ', 'ശുറഹ്ബീലുബ്നു സ്വിംത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 894, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ فَبَلَغَ الْعَدُوَّ – أَخْطَأَ أَوْ أَصَابَ – كَانَ لَهُ كَعِدْلِ رَقَبَةٍ، وَمَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً كَانَ فِدَاءَ كُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنْ نَارِ جَهَنَّمَ، وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ". (ن,جه)', 'അംറുബ്നു അബസ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ആരെങ്കിലും ഒരു അമ്പെയ്ത് ശത്രുവിലെത്തിച്ചാൽ ലക്ഷ്യം തെറ്റിയാലും ഇല്ലെങ്കിലും അത് ഒരു അടിമയെ മോചിപ്പിക്കുന്നതിന് തുല്യമാണ്. ആരെങ്കിലും ഒരു മുസ്ലിമായ അടിമയെ മോചിപ്പിച്ചാൽ അവന്റെ ഓരോ അവയവത്തിന് പകരവും ഇവന്റെ ഓരോ അവയവും നരകത്തിൽ നിന്ന് മോചിപ്പിക്കപ്പെടും. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലായിട്ട് ആരെങ്കിലും വാർദ്ധക്യം എത്തിച്ചാൽ അത് അന്ത്യനാളിൽ അവനൊരു പ്രകാശമായി മാറുന്നതാണ്." (ന,ജ)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ عَلَى الْمِنْبَرِ: "{وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ} [الأنفال:٦٠] أَلَا وَإِنَّ الْقُوَّةَ الرَّمْيُ" ثَلَاثَ مَرَّاتٍ. (م,د,جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): റസൂൽ(സ) മിമ്പറിൽ നിന്ന് ഓതുന്നത് ഞാൻ കേട്ടു: "ശത്രുക്കൾക്കെതിരെ നിങ്ങൾക്ക് സാധ്യമാകുന്നയത്ര ശക്തി ശേഖരിക്കുക.'' അറിയുക, ശക്തിയെന്നാൽ അമ്പെയ്ത്താണ്." മൂന്ന് പ്രാവശ്യം റസൂൽ(സ) അപ്രകാരം പറഞ്ഞു. (മു,ദ,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], 'الأنفال:٦٠', null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ تَعَلَّمَ الرَّمْيَ ثُمَّ تَرَكَهُ فَقَدْ عَصَانِي". (جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും അമ്പെയ്ത്ത് പഠിച്ച ശേഷം അതിനെ ഉപേക്ഷിച്ചാൽ അവൻ എനിക്ക് എതിര് പ്രവർത്തിച്ചിരിക്കുന്നു." (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَفَرٍ يَرْمُونَ، فَقَالَ: "رَمْيًا بَنِي إِسْمَعِيلَ، فَإِنَّ أَبَاكُمْ كَانَ رَامِيًا". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അമ്പെയ്തുകൊണ്ടിരിക്കുന്ന ചിലരുടെ അടുത്തുകൂടെ നബി(സ) നടന്നു പോയി. അവിടന്ന് പറഞ്ഞു: "ഇസ്മാഈലിന്റെ പുത്രന്മാരെ, നിങ്ങൾ അമ്പെയ്യുക, നിങ്ങളുടെ പിതാവും അമ്പെയ്ത്തുകാരനായിരുന്നു." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنِ النُّعْمَانِ بْنِ مُقَرِّنٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ إِذَا طَلَعَ الْفَجْرُ أَمْسَكَ حَتَّى تَطْلُعَ الشَّمْسُ، فَإِذَا طَلَعَتْ قَاتَلَ، فَإِذَا انْتَصَفَ النَّهَارُ أَمْسَكَ حَتَّى تَزُولَ الشَّمْسُ، فَإِذَا زَالَتِ الشَّمْسُ قَاتَلَ حَتَّى الْعَصْرِ، ثُمَّ أَمْسَكَ حَتَّى يُصَلِّيَ الْعَصْرَ ثُمَّ يُقَاتِلُ. قَالَ: وَكَانَ يُقَالُ: عِنْدَ ذَلِكَ تَهِيجُ رِيَاحُ النَّصْرِ، وَيَدْعُو الْمُؤْمِنُونَ لِجُيُوشِهِمْ فِي صَلَاتِهِمْ. (د,ت)', 'നുഅ്മാനുബ്നു മുഖർറിൻ(റ): ഞാൻ നബി(സ)യോടൊപ്പം യുദ്ധം ചെയ്തു. പ്രഭാതമായാൽ നബി(സ) സൂര്യനുദിക്കും വരെ യുദ്ധം നിർത്തിവെക്കുമായിരുന്നു. സൂര്യനുദിച്ചാൽ യുദ്ധം ചെയ്യും. ഉച്ചയായാൽ സൂര്യൻ മധ്യത്തിൽനിന്ന് തെറ്റുന്നതുവരെ യുദ്ധം നിർത്തിവെക്കും. സൂര്യൻ മധ്യത്തിൽ നിന്ന് തെറ്റിയാൽ അസ്വ്റ് വരെ നബി(സ) യുദ്ധം ചെയ്യും. ശേഷം അസ്വ്റ് നമസ്കരിക്കും വരെ നബി(സ) യുദ്ധം നിർത്തിവെക്കും. ശേഷം യുദ്ധം ചെയ്യും. നിവേദകൻ പറഞ്ഞു: ഇപ്രകാരം പറയപ്പെടാറുണ്ടായിരുന്നു. ആ സമയത്ത് സഹായത്തിന്റെ കാറ്റ് വീശിയടിക്കും, മുഅ്മിനുകൾ നിസ്കാരത്തിൽ തങ്ങളുടെ സൈന്യത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്യും. (ദ,തു)', 'النُّعْمَانِ بْنِ مُقَرِّنٍ', 'നുഅ്മാനുബ്നു മുഖർറിൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 895, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ بَعَثَ النُّعْمَانَ بْنَ مُقَرِّنٍ إِلَى الْهُرْمُزَانِ – فَذَكَرَ الْحَدِيثَ بِطُولِهِ – فَقَالَ النُّعْمَانُ بْنُ مُقَرِّنٍ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ إِذَا لَمْ يُقَاتِلْ أَوَّلَ النَّهَارِ، انْتَظَرَ حَتَّى تَزُولَ الشَّمْسُ وَتَهُبَّ الرِّيَاحُ وَيَنْزِلَ النَّصْرُ. (خ,د,ت)', 'മഅ്ഖിലുബ്നു യസാർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) നുഅ്മാനുബ്നു മുഖർരിൻ(റ)വിനെ ഹുർമുസാനിലേക്ക് അയച്ചു - ശേഷം നിവേദകൻ ഹദീസ് മുഴുവൻ പറഞ്ഞു - അപ്പോൾ നുഅ്മാനുബ്നു മുഖർറിൻ(റ) പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പം ഞാൻ യുദ്ദത്തിൽ പങ്കെടുത്തു. റസൂൽ(സ) പ്രഭാതത്തിന്റെ ആദ്യ ഭാഗത്ത് യുദ്ധംചെയ്യുന്നില്ലെങ്കിൽ സൂര്യൻ മധ്യത്തിൽ നിന്ന് തെറ്റുംവരെയും കാറ്റടിക്കുംവരെയും സഹായം ഇറങ്ങുംവരെയും കാത്തുനിൽക്കുമായിരുന്നു. (ബു,ദ,തു)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖിലുബ്നു യസാർ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ سَأَلَ اللَّهَ الشَّهَادَةَ بِصِدْقٍ بَلَّغَهُ اللَّهُ مَنَازِلَ الشُّهَدَاءِ، وَإِنْ مَاتَ عَلَى فِرَاشِهِ". (م,د,ت,ن,جه)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): തിരുനബി(സ) പറഞ്ഞു: "ദൃഢവിശ്വാസത്തോടെ ഒരാൾ അല്ലാഹുവിനോട് രക്തസാക്ഷിത്വത്തെ ചോദിച്ചാൽ അവന് രക്തസാക്ഷികളുടെ പദവി ലഭിക്കുന്നതാണ്. അവൻ വിരിപ്പിൽ കിടന്ന് മരിക്കുകയാണെങ്കിലും." (മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ، يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَأَنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ، غَيْرُ الشَّهِيدِ، فَإِنَّهُ يَتَمَنَّى أَنْ يَرْجِعَ فَيُقْتَلَ عَشْرَ مَرَّاتٍ، لِمَا يَرَى مِنَ الْكَرَامَةِ". (ق,ت,ن,جه)', 'അനസ്(റ): തിരുനബി(സ) പറഞ്ഞു: "രക്തസാക്ഷിയൊഴികെ ഒരു സ്വർഗ്ഗവാസിയും, തനിക്കു ലഭിക്കുന്ന ഭൗതിക മഹത്വം എത്രമാത്രമുണ്ടെങ്കിലും, ഇഹത്തിലേക്ക് മടങ്ങി വരാൻ ആഗ്രഹിക്കില്ല. രക്തസാക്ഷി തനിക്ക് ലഭിച്ചിട്ടുള്ള സ്ഥാനങ്ങളുടെ പേരിൽ ഇഹത്തിലേക്ക് വീണ്ടും വീണ്ടും മടങ്ങിവന്ന് പത്ത് പ്രാവശ്യം രക്തസാക്ഷിയാകാൻ ആഗ്രഹിക്കും." (ബു,മു,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَبْدِ اللَّهِ بْنِ جَبْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَادَ جَبْرًا، فَلَمَّا دَخَلَ سَمِعَ النِّسَاءَ يَبْكِينَ وَيَقُلْنَ: كُنَّا نَحْسَبُ وَفَاتَكَ قَتْلاً فِي سَبِيلِ اللَّهِ. فَقَالَ: "وَمَا تَعُدُّونَ الشَّهَادَةَ إِلاَّ مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ؟ إِنَّ شُهَدَاءَكُمْ إِذًا لَقَلِيلٌ: الْقَتْلُ فِي سَبِيلِ اللَّهِ شَهَادَةٌ، وَالْبَطْنُ شَهَادَةٌ، وَالْحَرْقُ شَهَادَةٌ، وَالْغَرَقُ شَهَادَةٌ، وَالْمَغْمُومُ – يَعْنِي الْهَدَمَ – شَهَادَةٌ، وَالْمَجْنُونُ شَهَادَةٌ، وَالْمَرْأَةُ تَمُوتُ بِجُمْعٍ شَهِيدَةٌ". قَالَ رَجُلٌ: أَتَبْكِينَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ؟ قَالَ: "دَعْهُنَّ، فَإِذَا وَجَبَ فَلَا تَبْكِيَنَّ عَلَيْهِ بَاكِيَةٌ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ജബ്ർ(റ): റസൂൽ(സ) ജബ്ർ(റ)വിനെ സന്ദർശിച്ചു. റസൂൽ(സ) അവിടെ പ്രവേശിച്ചപ്പോൾ സ്ത്രീകൾ കരയുന്നതു കേട്ടു. അവർ പറയുന്നു: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ടായിരിക്കും അങ്ങയുടെ മരണമെന്നാണ് ഞങ്ങൾ വിചാരിച്ചിരുന്നത്. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെടലിനെ മാത്രമാണോ നിങ്ങൾ രക്തസാക്ഷിത്വമായി കാണുന്നത്. അങ്ങനെയെങ്കിൽ നിങ്ങളിലെ രക്തസാക്ഷികൾ വളരെ കുറവായിരിക്കും. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ടാൽ രക്തസാക്ഷിത്വമാണ്, വയറിന് രോഗം ബാധിച്ച് മരിക്കൽ രക്തസാക്ഷിത്വമാണ്, തീ പിടിച്ച് മരിക്കൽ രക്തസാക്ഷിത്വമാണ്, മുങ്ങിമരിക്കൽ രക്തസാക്ഷിത്വമാണ്, കെട്ടിടം വീണ് മരിക്കൽ രക്തസാക്ഷിത്വമാണ്, ഭ്രാന്തന്റെ മരണം രക്തസാക്ഷിത്വമാണ്, ഗർഭിണിയായ സ്ത്രീയുടെ മരണം രക്തസാക്ഷിത്വമാണ്." ഒരാൾ ചോദിച്ചു: റസൂൽ(സ) ഇരിക്കുന്നതിനിടയിൽ നിങ്ങൾ കരയുന്നുവോ? റസൂൽ(സ) പറഞ്ഞു: "അവരെ വിട്ടേക്കുക, ജബ്ർ(റ) മരിച്ചാൽ ഒരാളും അദ്ദേഹത്തിന്റെ പേരിൽ കരയാൻ പാടില്ല." (ന,ജ)', 'عَبْدِ اللَّهِ بْنِ جَبْرٍ', 'അബ്ദുല്ലാഹിബ്നു ജബ്ർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 896, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُؤْتَى بِالرَّجُلِ مِنْ أَهْلِ الْجَنَّةِ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: يَا ابْنَ آدَمَ، كَيْفَ وَجَدْتَ مَنْزِلَكَ؟ فَيَقُولُ: أَيْ رَبِّ، خَيْرَ مَنْزِلٍ. فَيَقُولُ: سَلْ وَتَمَنَّ. فَيَقُولُ: أَسْأَلُكَ أَنْ تَرُدَّنِي إِلَى الدُّنْيَا فَأُقْتَلَ فِي سَبِيلِكَ عَشْرَ مَرَّاتٍ. لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ". (ن)', 'അനസ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "സ്വർഗവാസിയായ ഒരാളെ കൊണ്ടുവന്ന് അല്ലാഹു ചോദിക്കും: മനുഷ്യാ, നിന്റെ പദവി എങ്ങനെയുണ്ട്? അവൻ പറയും: എന്റെ നാഥാ, ഉത്തമ പദവി. അല്ലാഹു തിരിച്ച് പറയും: നീ ആഗ്രഹിക്കുന്നത് ചോദിക്കൂ. അവൻ പറയും: നിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത് പത്ത് തവണ കൊല്ലപ്പെടണമെന്നും അതിന് വേണ്ടി ഭൂമിയിലേക്ക് എന്നെ മടക്കണമെന്നും ഞാൻ നിന്നോട് ആവശ്യപ്പെടുന്നു. രക്തസാക്ഷിത്വത്തിന്റെ മഹത്വം അവൻ മനസ്സിലാക്കിയതു കൊണ്ടാണിത്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ ابْنِ أَبِي عَمِيرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنَ النَّاسِ مِنْ نَفْسٍ مُسْلِمَةٍ يَقْبِضُهَا رَبُّهَا، تُحِبُّ أَنْ تَرْجِعَ إِلَيْكُمْ وَأَنَّ لَهَا الدُّنْيَا وَمَا فِيهَا، غَيْرُ الشَّهِيدِ". قَالَ ابْنُ أَبِي عَمِيرَةَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَلَأَنْ أُقْتَلَ فِي سَبِيلِ اللَّهِ أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي أَهْلُ الْوَبَرِ وَالْمَدَرِ". (ن)', 'അബ്ദുറഹ്മാനുബ്നു അബീഅമീറ(റ): തിരുനബി(സ) പറയുന്നു: "ഭൂമിയും അതിലുള്ള വസ്തുക്കളും തന്റെ അധീനതയിൽ ഉണ്ടെങ്കിൽ പോലും മുസ്ലിമായ ഒരു വ്യക്തിയുടെ ആത്മാവ്, തന്റെ നാഥൻ പിടിച്ച ശേഷം ഭൂമിയിലേക്ക് മടങ്ങാൻ കൊതിക്കുകയില്ല, രക്തസാക്ഷിയൊഴികെ." ഇബ്നു അബീഅമീറ(റ) പറയുന്നു: തിരുനബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെടുന്നതാണ് നഗരവാസികളും ഗ്രാമവാസികളും എനിക്ക് കീഴ്പ്പെടുന്നതിനേക്കാൾ എനിക്ക് താൽപര്യമുള്ളത്." (ന)', 'ابْنِ أَبِي عَمِيرَةَ', 'അബ്ദുറഹ്മാനുബ്നു അബീഅമീറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَالَ: "مَا تَقُولُونَ فِي الشَّهِيدِ فِيكُمْ". قَالُوا: الْقَتْلُ فِي سَبِيلِ اللَّهِ. قَالَ: "إِنَّ شُهَدَاءَ أُمَّتِي إِذًا لَقَلِيلٌ. مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ، وَمَنْ مَاتَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ، وَالْمَبْطُونُ شَهِيدٌ، وَالْمَطْعُونُ شَهِيدٌ". وَفِي رِوَايَةٍ: "وَالْغَرِقُ شَهِيدٌ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ചോദിച്ചു: "നിങ്ങളിലെ രക്തസാക്ഷികളെക്കുറിച്ച് നിങ്ങൾക്കെന്താണു പറയാനുള്ളത്?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെടുക. തിരുനബി(സ) പറഞ്ഞു: "അങ്ങനെയെങ്കിൽ എന്റെ സമുദായത്തിലെ രക്തസാക്ഷികൾ വളരെ തുഛമായിരിക്കും. അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്ത് കൊല്ലപ്പെട്ടവൻ ശഹീദാണ്. വയറുവേദന പിടിച്ച് മരിച്ചവനും ശഹീദാണ്. പ്ലേഗ് ബാധിച്ച് മരിക്കുന്നവനും ശഹീദാണ്." മറ്റൊരു നിവേദനത്തിൽ: "മുങ്ങിമരിക്കുന്നവനും ശഹീദാകുന്നു." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=112), 1, 'وَفِي رِوَايَةٍ: "وَالْغَرِقُ شَهِيدٌ". (جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "മുങ്ങിമരിക്കുന്നവനും ശഹീദാകുന്നു." (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُمَّ الرُّبَيِّعِ بِنْتَ الْبَرَاءِ، وَهِيَ أُمُّ حَارِثَةَ بْنِ سُرَاقَةَ، أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا نَبِيَّ اللَّهِ أَلَا تُحَدِّثُنِي عَنْ حَارِثَةَ، وَكَانَ قُتِلَ يَوْمَ بَدْرٍ أَصَابَهُ سَهْمٌ غَرْبٌ، فَإِنْ كَانَ فِي الْجَنَّةِ صَبَرْتُ، وَإِنْ كَانَ غَيْرَ ذَلِكَ اجْتَهَدْتُ عَلَيْهِ فِي الْبُكَاءِ، قَالَ: "يَا أُمَّ حَارِثَةَ، إِنَّهَا جِنَانٌ فِي الْجَنَّةِ، وَإِنَّ ابْنَكِ أَصَابَ الْفِرْدَوْسَ الْأَعْلَى". (خ)', 'അനസുബ്നു മാലിക്(റ): റുബയ്യിഅ് ബിൻതുൽബറാഅ്(റ) (അവർ ഹാരിസതുബ്നു സുറാഖയുടെ മാതാവാണ്) തിരുനബി(സ)യുടെ അടുത്ത് വന്നു പറഞ്ഞു: തിരുദൂതരേ, ഹാരിസത്തിന്റെ സ്ഥിതിയെക്കുറിച്ച് അവിടുന്ന് എനിക്ക് വിവരിച്ചു തരില്ലേ? ഹാരിസത്ത് ബദ്റിൽ ശഹീദായവരാണ്. ഓർക്കാപ്പുറത്ത് ഒരമ്പ് അദ്ദേഹത്തിനേറ്റു. അദ്ദേഹം ഇപ്പോൾ സ്വർഗ്ഗത്തിലാണെങ്കിൽ എനിക്ക് ക്ഷമിക്കാം. മറിച്ചാണെങ്കിൽ അദ്ദേഹത്തിന് വേണ്ടി വലപിക്കാൻ ഞാൻ അങ്ങേയറ്റം പാട് പെടേണ്ടിവരും. തിരുനബി(സ) പറഞ്ഞു: "ഹാരിസത്തിന്റെ മാതാവേ, സ്വർഗത്തിൽ പല പദവികളുമുണ്ട്. നിന്റെ പുത്രന് ലഭിച്ചിരിക്കുന്നത് മഹോന്നതമായ ഫിർദൗസാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْخَنْدَقِ، فَإِذَا الْمُهَاجِرُونَ وَالْأَنْصَارُ يَحْفِرُونَ فِي غَدَاةٍ بَارِدَةٍ، فَلَمْ يَكُنْ لَهُمْ عَبِيدٌ يَعْمَلُونَ ذَلِكَ لَهُمْ، فَلَمَّا رَأَى مَا بِهِمْ مِنَ النَّصَبِ وَالْجُوعِ قَالَ: "اللَّهُمَّ إِنَّ الْعَيْشَ عَيْشُ الْآخِرَهْ فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَهْ". فَقَالُوا مُجِيبِينَ لَهُ: نَحْنُ الَّذِينَ بَايَعُوا مُحَمَّدَا عَلَى الْجِهَادِ مَا بَقِينَا أَبَدَا. (خ)', 'അനസ്(റ): റസൂൽ(സ) ഖന്ദഖിലേക്ക് ചെന്നു. അവിടെ, കടുത്ത ശൈത്യമുള്ള പ്രഭാതത്തിൽ മുഹാജിറുകളും അൻസാരികളും കിടങ്ങ് കുഴിക്കുകയായിരുന്നു. അവർക്ക് അത് ചെയ്തുകൊടുക്കാൻ ഭൃത്യന്മാർ ഉണ്ടായിരുന്നില്ല. അവരെ ബാധിച്ച ക്ഷീണവും വിശപ്പും കണ്ടപ്പോൾ തിരുനബി(സ) ഇങ്ങനെ പാടി: "അല്ലാഹുവേ, യഥാർത്ഥജീവതം പാരത്രിക ജീവിതം തന്നെ. മുഹാജിറുകൾക്കും അൻസാരികൾക്കും നീ പൊറുത്ത് കൊടുക്കേണമേ." തിരുനബി(സ)ക്ക് മറുപടിയായി അനുചരർ ഇങ്ങനെ പാടി: ജീവിച്ചിരിക്കുന്ന കാലമത്രയും പോരാട്ടത്തിൽ ഉറച്ച് നിൽക്കുമെന്ന് മുഹമ്മദ്(സ)യുമായി ഉടമ്പടി ചെയ്തവരാണ് ഞങ്ങൾ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ وَيَقُولُونَ: نَحْنُ الَّذِينَ بَايَعُوا مُحَمَّدَا عَلَى الْإِسْلَامِ مَا بَقِينَا أَبَدَا وَهُوَ يُجِيبُهُمْ: "اللَّهُمَّ إِنَّهُ لَا خَيْرَ إِلَّا خَيْرُ الْآخِرَهْ فَبَارِكْ فِي الْأَنْصَارِ وَالْمُهَاجِرَهْ". (خ)', 'അനസ്(റ): അവർ പാടിയതിങ്ങനെയായിരുന്നു: ജീവിച്ചിരിക്കുന്ന കാലമത്രയും ഇസ്ലാമിൽ ഉറച്ചുനിൽക്കുമെന്ന് മുഹമ്മദ്(സ)യുമായി ഉടമ്പടി ചെയ്തവരാണ് ഞങ്ങൾ. തിരുനബി(സ) മറുപടിയായി ഇങ്ങനെ പാടി: "അല്ലാഹുവേ, നന്മ യഥാർത്ഥത്തിൽ പരലോക നന്മയാണ്. അൻസാരികൾക്കും മുഹാജിറുകൾക്കും നീ ബറകത് നൽകേണമേ." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 898, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْأَحْزَابِ، يَنْقُلُ التُّرَابَ وَقَدْ وَارَى التُّرَابُ بَيَاضَ بَطْنِهِ وَهُوَ يَقُولُ: "لَوْلَا أَنْتَ مَا اهْتَدَيْنَا وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا فَأَنْزِلَنْ سَكِينَةً عَلَيْنَا وَثَبِّتِ الْأَقْدَامَ إِنْ لَاقَيْنَا إِنَّ الْأُلَى قَدْ بَغَوْا عَلَيْنَا إِذَا أَرَادُوا فِتْنَةً أَبَيْنَا". (خ)', 'ബറാഅ്(റ): അഹ്സാബ് യുദ്ധദിനത്തിൽ തിരുനബി(സ) മണ്ണ് ചുമന്നുകൊണ്ട് പോകുന്നതായി ഞാൻ കണ്ടു. തിരുനബി(സ)യുടെ വയറിന്റെ വെളുപ്പ് മണ്ണ് പുരണ്ട് മറഞ്ഞിരുന്നു. അന്നേരം തിരുനബി(സ) ഇങ്ങനെ പാടിക്കൊണ്ടിരിന്നു: "അല്ലാഹുവേ, നീയില്ലെങ്കിൽ ഞങ്ങൾ നേർമാർഗത്തിലാകുകയില്ലായിരുന്നു, ഞങ്ങൾ നിസ്കരിക്കുകയും ദാനം ചെയ്യുകയും ചെയ്യില്ലായിരുന്നു. അതുകൊണ്ട് ഞങ്ങൾക്കുമേൽ നീ ശാന്തി ചൊരിയണമേ, ശത്രുക്കളുമായി കണ്ടുമുട്ടുമ്പോൾ ഞങ്ങളുടെ പാദങ്ങളെ ഉറപ്പിച്ചു നിർത്തേണമേ. ഞങ്ങളെ അക്രമിച്ചിരിക്കുന്നവർ ഞങ്ങളെ മർദ്ദിക്കാനുദ്ദേശിക്കുന്നുണ്ടെങ്കിൽ ഞങ്ങളത് തടയുക തന്നെ ചെയ്യും." (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مُقَنَّعٌ بِالْحَدِيدِ، فَقَالَ: يَا رَسُولَ اللَّهِ أُقَاتِلُ أَوْ أُسْلِمُ، قَالَ: "أَسْلِمْ، ثُمَّ قَاتِلْ". فَأَسْلَمَ ثُمَّ قَاتَلَ فَقُتِلَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَمِلَ قَلِيلاً وَأُجِرَ كَثِيرًا". (خ)', 'ബറാഅ്(റ): തിരുദൂതർ(സ)യുടെ അടുക്കൽ ഇരുമ്പിന്റെ ആയുധങ്ങളേന്തിയ ഒരു മനുഷ്യൻ വന്ന് ചോദിച്ചു: തിരുദൂതരേ, ഞാൻ യുദ്ധം ചെയ്യുകയാണോ മുസ്ലിമാവുകയാണോ ചെയ്യേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: "നീ മുസ്ലിമാവുക. പിന്നെ യുദ്ധം ചെയ്യുക." ഉടനെ അദ്ദേഹം ഇസ്ലാം സ്വീകരിച്ചു. എന്നിട്ട് പോരാടി ശഹീദായി. തിരുനബി(സ) പറഞ്ഞു: "അദ്ദേഹം കുറച്ച് പ്രവർത്തിച്ചു, കൂടുതൽ കൂലി നേടുകയും ചെയ്തു." (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ آمَنَ بِاللَّهِ وَبِرَسُولِهِ وَأَقَامَ الصَّلَاةَ، وَصَامَ رَمَضَانَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ، جَاهَدَ فِي سَبِيلِ اللَّهِ أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا". فَقَالُوا: يَا رَسُولَ اللَّهِ، أَفَلَا نُبَشِّرُ النَّاسَ؟ قَالَ: "إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ، مَا بَيْنَ الدَّرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَاسْأَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ وَأَعْلَى الْجَنَّةِ". أُرَاهُ قَالَ: "فَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിലും അവന്റെ ദൂതരിലും വിശ്വസിക്കുകയും നിസ്കാരം നിലനിർത്തുകയും റമളാൻ മാസത്തിൽ നോമ്പനുഷ്ഠിക്കുകയും ചെയ്താൽ അവനെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കൽ അല്ലാഹുവിന്റെ കടമയാണ്. അവൻ യുദ്ധം ചെയ്യുകയോ, യുദ്ധം ചെയ്യാതെ തന്റെ ജന്മദേശത്ത് കഴിയുകയോ ചെയ്താലും ശരി." അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ ജനങ്ങളെ സന്തോഷവാർത്തയറിയിക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "തന്റെ മാർഗത്തിൽ പോരാടുന്നവർക്കായി അല്ലാഹു ഒരുക്കിവെച്ച നൂറ് പദവികൾ സ്വർഗത്തിലുണ്ട്. അതിൽ ഓരോ രണ്ട് പദവികൾക്കുമിടയിലെ അകലം ആകാശഭൂമികൾക്കിടയിലെ അകലം പോലെയാണ്. നിങ്ങൾ അല്ലാഹുവിനോട് ചോദിക്കുന്നുവെങ്കിൽ ഫിർദൗസ് എന്ന സ്വർഗം ചോദിക്കുക. അത് സ്വർഗത്തിന്റെ മധ്യഭാഗവും ഉയർന്ന ഭാഗവുമാണ്." നബി(സ) ഇതുകൂടി പറഞ്ഞുവെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്: "അതിന് മുകളിലാണ് പരമകാരുണ്യവാനായ അല്ലാഹുവിന്റെ അർശ്. സ്വർഗീയ നദികൾ അതിൽ നിന്നാണ് ഉത്ഭവിക്കുന്നത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 899, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَا يُكْلَمُ أَحَدٌ فِي سَبِيلِ اللَّهِ، وَاللَّهُ أَعْلَمُ بِمَنْ يُكْلَمُ فِي سَبِيلِهِ، إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ وَاللَّوْنُ لَوْنُ الدَّمِ. وَالرِّيحُ رِيحُ الْمِسْكِ". (خ)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ അധീനതയിലാണോ അവനെ കൊണ്ട് സത്യം, ദൈവമാർഗ്ഗത്തിൽ മുറിവേൽക്കുന്ന ഏതൊരാളും - അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുറിവേൽക്കുന്നയാൾ ആരാണെന്ന് അല്ലാഹുവിനാണറിയുക - തന്റെ നിറം രക്തത്തിന്റെ നിറവും വാസന കസ്തൂരിയുടേതുമായി അന്ത്യനാളിൽ വരുന്നതാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ مَسْرُوقٍ قَالَ: سَأَلْنَا عَبْدَ اللَّهِ بْنَ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنْ هَذِهِ الْآيَةِ: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ} [آل عمران: ١٦٩] قَالَ: أَمَا إِنَّا قَدْ سَأَلْنَا عَنْ ذَلِكَ، فَقَالَ: "أَرْوَاحُهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ، لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالْعَرْشِ، تَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شَاءَتْ، ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ، فَاطَّلَعَ إِلَيْهِمْ رَبُّهُمُ اطِّلَاعَةً فَقَالَ: هَلْ تَشْتَهُونَ شَيْئًا؟ قَالُوا: أَيَّ شَيْءٍ نَشْتَهِي، وَنَحْنُ نَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شِئْنَا؟ فَفَعَلَ ذَلِكَ بِهِمْ ثَلَاثَ مَرَّاتٍ، فَلَمَّا رَأَوْا أَنَّهُمْ لَنْ يُتْرَكُوا مِنْ أَنْ يُسْأَلُوا، قَالُوا: يَا رَبِّ، نُرِيدُ أَنْ تَرُدَّ أَرْوَاحَنَا فِي أَجْسَادِنَا، حَتَّى نُقْتَلَ فِي سَبِيلِكَ مَرَّةً أُخْرَى. فَلَمَّا رَأَى أَنْ لَيْسَ لَهُمْ حَاجَةٌ تُرِكُوا". (م,ت,جه)', 'മസ്റൂഖ്(റ): ''അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെട്ടവർ മരിച്ചുപോയവരാണെന്ന് നീ ധരിക്കരുത്. അവർ അവരുടെ രക്ഷിതാവിന്റെ അടുക്കൽ ജീവിച്ചിരിക്കുന്നവരാണ്. അവർക്ക് ഭക്ഷണവും നൽകപ്പെട്ടുകൊണ്ടിരിക്കും'' (ആലുഇംറാൻ: 169) എന്ന ഖുർആൻ സൂക്തത്തെക്കുറിച്ച് ഞങ്ങൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അതിനെക്കുറിച്ച് തിരുനബി(സ)യോട് ഞങ്ങൾ ചോദിച്ചപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവരുടെ ആത്മാക്കൾ പച്ചനിറത്തിലുള്ള പക്ഷികൾക്കുള്ളിലാണ്. അവർക്ക് കിനാദികളുണ്ട്, അവ അർശുമായി ബന്ധിപ്പിക്കപ്പെട്ടതാണ്. ആ പക്ഷികൾ ഉദ്ദേശിക്കുമ്പോഴെല്ലാം സ്വർഗ്ഗത്തിൽ നിന്ന് പറന്ന് പോകും. പിന്നീട് ആ കിനാദികളിലേക്ക് മടങ്ങിവരും. ആ സമയം അല്ലാഹു അവരിലേക്ക് വന്ന് ചോദിക്കും: നിങ്ങൾ വല്ലതും ആഗ്രഹിക്കുന്നുണ്ടോ? അവർ പറയും: ഞങ്ങൾ എന്താഗ്രഹിക്കാനാണ്, ഞങ്ങൾ ആഗ്രഹിക്കുമ്പോഴെല്ലാം പുറത്ത് പോകുന്നുണ്ടല്ലോ. ഇങ്ങനെ ചോദ്യവും മറുപടിയും മൂന്ന് തവണ ആവർത്തിക്കും. ചോദിക്കാതെ വിടില്ല എന്നാകുമ്പോൾ അവർ പറയും: ഞങ്ങളുടെ നാഥാ, ഞങ്ങളുടെ ആത്മാക്കളെ നീ ഞങ്ങളുടെ ശരീരങ്ങളിലേക്ക് തന്നെ മടക്കി ഒരു പ്രാവശ്യം കൂടി നിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്ത് കൊല്ലപ്പെടുവാൻ ഞങ്ങൾ ആഗ്രഹിക്കുന്നു. അവർക്ക് ആവശ്യങ്ങളൊന്നുമില്ലെന്ന് കാണുമ്പോൾ അല്ലാഹു അവരെ അപ്രകാരം തന്നെ നിലനിർത്തും." (മു,തു,ജ)', 'مَسْرُوقٍ قَالَ', 'മസ്റൂഖ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], 'آل عمران: ١٦٩', null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ عَنْ أَبِيهِ قَالَ: سَمِعْتُ أَبِي وَهُوَ بِحَضْرَةِ الْعَدُوِّ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَبْوَابَ الْجَنَّةِ تَحْتَ ظِلاَلِ السُّيُوفِ". فَقَامَ رَجُلٌ رَثُّ الْهَيْئَةِ، فَقَالَ: يَا أَبَا مُوسَى، آنْتَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ هَذَا؟ قَالَ: نَعَمْ، قَالَ: فَرَجَعَ إِلَى أَصْحَابِهِ فَقَالَ: أَقْرَأُ عَلَيْكُمُ السَّلاَمَ، ثُمَّ كَسَرَ جَفْنَ سَيْفِهِ فَأَلْقَاهُ، ثُمَّ مَشَى بِسَيْفِهِ إِلَى الْعَدُوِّ فَضَرَبَ بِهِ حَتَّى قُتِلَ. (م,ت)', 'അബൂബക്റുബ്നു അബ്ദില്ല(റ) തന്റെ പിതാവിൽനിന്ന് ഉദ്ധരിക്കുന്നു: എന്റെ പിതാവ് ശത്രുക്കളുടെ സമീപത്തുവെച്ച് പറയുന്നത് ഞാൻ കേട്ടു: തിരുദൂതർ(സ) പറഞ്ഞു: "സ്വർഗ്ഗ കവാടങ്ങൾ വാളുകളുടെ നിഴലിന് കീഴെയാണ്." അപ്പോൾ ശരീരം ക്ഷീണിച്ച് അവശനായ ഒരാൾ എഴുന്നേറ്റുനിന്ന് ചോദിച്ചു: അബൂമൂസാ, തിരുനബി(സ) ഇങ്ങനെ പറയുന്നത് താങ്കൾ കേട്ടിട്ടുണ്ടോ?. അദ്ദേഹം പറഞ്ഞു: അതെ. നിവേദകൻ പറഞ്ഞു: പിന്നീട് അദ്ദേഹം തന്റെ അനുയായികളുടെ അടുത്തേക്ക് ചെന്ന് പറഞ്ഞു: ഞാൻ നിങ്ങൾക്ക് അഭിവാദ്യമർപ്പിക്കുന്നു. ശേഷം അദ്ദേഹം തന്റെ വാളുറ കീറി വാൾ പുറത്തെടുത്ത് ശത്രുവിന്റെ അടുക്കലേക്ക് പോവുകയും അതുമായി യുദ്ധംചെയ്ത് വധിക്കപ്പെടുകയും ചെയ്തു. (മു,തു)', 'أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ عَنْ أَبِيهِ قَالَ', 'അബൂബക്റുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 900, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ نَاسٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ [فَقَالُوا]: أَنِ ابْعَثْ مَعَنَا رِجَالاً يُعَلِّمُونَا الْقُرْآنَ وَالسُّنَّةَ. فَبَعَثَ إِلَيْهِمْ سَبْعِينَ رَجُلاً مِنَ الأَنْصَارِ يُقَالُ لَهُمُ الْقُرَّاءُ، فِيهِمْ خَالِي حَرَامٌ يَقْرَءُونَ الْقُرْآنَ وَيَتَدَارَسُونَ بِاللَّيْلِ يَتَعَلَّمُونَ، وَكَانُوا بِالنَّهَارِ يَجِيئُونَ بِالْمَاءِ فَيَضَعُونَهُ فِي الْمَسْجِدِ، وَيَحْتَطِبُونَ فَيَبِيعُونَهُ وَيَشْتَرُونَ بِهِ الطَّعَامَ لأَهْلِ الصُّفَّةِ وَلِلْفُقَرَاءِ، فَبَعَثَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ فَعَرَضُوا لَهُمْ. فَقَتَلُوهُمْ قَبْلَ أَنْ يَبْلُغُوا الْمَكَانَ، فَقَالُوا: اللَّهُمَّ بَلِّغْ عَنَّا نَبِيَّنَا أَنَّا قَدْ لَقِينَاكَ فَرَضِينَا عَنْكَ وَرَضِيتَ عَنَّا. [قَالَ]: وَأَتَى رَجُلٌ حَرَامًا خَالَ أَنَسٍ مِنْ خَلْفِهِ فَطَعَنَهُ بِرُمْحٍ حَتَّى أَنْفَذَهُ، فَقَالَ حَرَامٌ: فُزْتُ وَرَبِّ الْكَعْبَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَصْحَابِهِ: "إِنَّ إِخْوَانَكُمْ قَدْ قُتِلُوا، وَإِنَّهُمْ قَالُوا: اللَّهُمَّ بَلِّغْ عَنَّا نَبِيَّنَا أَنَّا قَدْ لَقِينَاكَ فَرَضِينَا عَنْكَ وَرَضِيتَ عَنَّا". (م)', 'അനസ്(റ): കുറച്ചാളുകൾ തിരുനബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: ഞങ്ങൾക്ക് ഖുർആനും സുന്നത്തും പഠിപ്പിക്കാൻ കുറച്ച് പേരെ അയച്ചുതരണം. അപ്പോൾ നബി(സ) അവരിലേക്ക് അൻസാറുകളിൽപ്പെട്ട ഖുർറാഉകൾ (ഓതുന്നവർ) എന്നറിയപ്പെടുന്ന എഴുപതാളുകളെ അയച്ചുകൊടുത്തു. അവരിൽ എന്റെ അമ്മാവൻ ഹറാം എന്നയാളുമുണ്ടായിരുന്നു. അവർ ഖുർആൻ പാരായണം ചെയ്യുകയും രാത്രി ഓതി പഠിക്കുകയും ചെയ്യുമായിരുന്നു. പകലിലവർ പള്ളിയിൽ വെള്ളം കൊണ്ടുവന്ന് വെക്കും. പിന്നെ വിറകുണ്ടാക്കി വിൽക്കുകയും കിട്ടിയ പണം കൊണ്ട് സാധുക്കൾക്കും സ്വുഫ്ഫത്തിന്റെ ആളുകൾക്കും ഭക്ഷണം വാങ്ങിക്കൊടുക്കുകയും ചെയ്യും. അങ്ങനെയവരെ നബി(സ) അവരിലേക്ക് അയച്ചു. ആ സ്ഥലത്തെത്തുന്നതിന് മുമ്പ് അവരെ അവർ വധിച്ചു. അവർ പറഞ്ഞു: അല്ലാഹുവേ, ഞങ്ങൾ നിന്നെ കാണുകയും ഞങ്ങൾ നിന്നെയും നീ ഞങ്ങളെയും തൃപ്തിപ്പെട്ടിരിക്കുകയും ചെയ്തിരിക്കുന്നുവെന്ന് ഞങ്ങളുടെ പ്രവാചകന് നീ അറിയിച്ച് കൊടുക്കണേ. നിവേദകൻ പറഞ്ഞു: അനസ്(റ)വിന്റെ അമ്മാവൻ ഹറാം(റ)വിന്റെ പിന്നിലൂടെ ഒരാൾ വന്ന് അദ്ദേഹത്തെ കുന്തം കൊണ്ട് കുത്തി വധിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കഅ്ബയുടെ രക്ഷിതാവിനെ സത്യം, ഞാൻ വിജയിച്ചിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) സ്വഹാബികളോട് പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരന്മാർ വധിക്കപ്പെട്ടിരിക്കുന്നു. അവർ പറഞ്ഞു: അല്ലാഹുവേ, ഞങ്ങൾ നിന്നെ കണ്ടുമുട്ടിയെന്നും നീ ഞങ്ങളെയും ഞങ്ങൾ നിന്നെയും തൃപ്തിപ്പെട്ടിരിക്കുന്നുവെന്നും ഞങ്ങളുടെ പ്രവാചകന് എത്തിക്കണേ." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ فَأَخَّرَهُ، فَشَكَرَ اللَّهُ لَهُ، فَغَفَرَ لَهُ". وَقَالَ: "الشُّهَدَاءُ خَمْسَةٌ: الْمَطْعُونُ، وَالْمَبْطُونُ، وَالْغَرِقُ، وَصَاحِبُ الْهَدْمِ، وَالشَّهِيدُ فِي سَبِيلِ اللَّهِ [عَزَّ وَجَلَّ]". (م)', 'അബുഹുറൈറ(റ): തിരുനബി(സ) പറഞ്ഞു: "ഒരാൾ വഴിയിലൂടെ നടക്കുമ്പോൾ വഴിയിൽ ഒരു മുള്ള് നിറഞ്ഞ ചില്ല കാണുകയും അതെടുത്ത് ഒഴിവാക്കുകയും ചെയ്തു. അതുകാരണം അല്ലാഹു അവന്ന് നന്ദി ചെയ്യുകയും പൊറുത്ത് കൊടുക്കുകയും ചെയ്തു." ശേഷം നബി(സ) പറഞ്ഞു: "രക്തസാക്ഷികൾ അഞ്ച് വിധമാണ്. കുത്തേറ്റ് മരിച്ചയാൾ, വയറ് വേദന പിടിച്ച് മരിച്ചവൻ, മുങ്ങി മരിച്ചവൻ, കെട്ടിടം പൊളിഞ്ഞ് വീണ് മരിച്ചവൻ, പിന്നെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രക്തസാക്ഷിയായവനും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'عَزَّ وَجَلَّ', null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ حَفْصَةَ بِنْتِ سِيرِينَ قَالَتْ: قَالَ لِي أَنَسُ بْنُ مَالِكٍ: بِمَ مَاتَ يَحْيَى بْنُ أَبِي عَمْرَةَ رَضِيَ اللَّهُ عَنْهُمْ؟ قَالَتْ: قُلْتُ: بِالطَّاعُونِ، [قَالَتْ]: فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الطَّاعُونُ شَهَادَةٌ لِكُلِّ مُسْلِمٍ". (ق)', 'ഹഫ്സതുബിൻത് സീരീൻ(റ): അനസുബ്നു മാലിക്(റ) എന്നോട് ചോദിച്ചു: എങ്ങനെയാണ് യഹ്യബ്നു അബീ അംറ(റ) മരണപ്പട്ടത്? ഞാൻ പറഞ്ഞു: പ്ലേഗ് ബാധിച്ച്. അവർ പറയുന്നു: അപ്പോൾ അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: തിരുനബി(സ) പറഞ്ഞിട്ടുണ്ട്: "എല്ലാ മുസ്ലിമിനും പ്ലേഗ് മരണം രക്തസാക്ഷിത്വമാണ്." (ബു,മു)', 'حَفْصَةَ بِنْتِ سِيرِينَ قَالَتْ', 'ഹഫ്സതുബിൻത് സീരീൻ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'قَالَتْ', null, 901, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُغْفَرُ لِلشَّهِيدِ كُلُّ ذَنْبٍ إِلَّا الدَّيْنَ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംരിബ്നിൽ ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രക്തസാക്ഷിക്ക് കടബാധ്യതയല്ലാത്ത എല്ലാ ദോഷങ്ങളും പൊറുക്കപ്പെടും." (മു)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംരിബ്നിൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَامَ فِيهِمْ فَذَكَرَ لَهُمْ أَنَّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَالْإِيمَانَ بِاللَّهِ أَفْضَلُ الْأَعْمَالِ، فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، [أَرَأَيْتَ] إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ، تُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ، إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَيْفَ قُلْتَ". قَالَ: أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ أَتُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ، وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ إِلَّا الدَّيْنَ، فَإِنَّ جِبْرِيلَ عَلَيْهِ السَّلَام قَالَ لِي ذَلِكَ". (م,ت,ن)', 'അബുഖതാദ(റ): റസൂൽ(സ) ജനങ്ങൾക്കിടയിൽ എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്യുകയും അല്ലാഹുവിൽ വിശ്വസിക്കലുമാണ് ഏറ്റവും പുണ്യമായ കർമങ്ങൾ." അപ്പോൾ ഒരാൾ എഴുന്നേറ്റ് നിന്ന് ചോദിച്ചു: റസൂലേ, ഞാൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ടാൽ എന്റെ ദോഷങ്ങൾക്കൊക്കെ അത് പ്രായശ്ചിത്തമാവുമോ? റസൂൽ (സ) അയാളോട് പറഞ്ഞു: "അതെ, നീ ക്ഷമിച്ച് പ്രതിഫലം ആഗ്രഹിച്ച് പിന്തിരിയാതെ മുന്നോട്ട് പോയി അല്ലാഹുവിന്റെ മാർഗത്തിൽ വധിക്കപ്പെട്ടാൽ." പിന്നെ നബി(സ) ചോദിച്ചു: "നീ എങ്ങനെയാണ് പറഞ്ഞത്?" അയാൾ പറഞ്ഞു: ഞാൻ അല്ലാഹുവിന്റെ മാർഗത്തിൽ വധിക്കപ്പെട്ടാൽ എന്റെ ദോഷങ്ങൾ പൊറുക്കപ്പെടുമേ? റസൂൽ പറഞ്ഞു: "അതെ, നീ ക്ഷമിച്ച് പ്രതിഫലം ആഗ്രഹിച്ച് പിന്തിരിയാതെ മുന്നോട്ട് പോയി യുദ്ധം ചെയ്താൽ കടമല്ലാത്തത് പൊറുക്കപ്പെടും. ജബ്രീൽ(അ) അതെന്നോട് പറഞ്ഞു." (മു,തു,ന)', 'أَبِي قَتَادَةَ', 'അബുഖതാദ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], 'أَرَأَيْتَ', null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ جَاءَ رَجُلٌ يُرِيدُ أَخْذَ مَالِي؟ قَالَ: "فَلَا تُعْطِهِ مَالَكَ". قَالَ: أَرَأَيْتَ إِنْ قَاتَلَنِي؟ قَالَ: "قَاتِلْهُ". قَالَ: أَرَأَيْتَ إِنْ قَتَلَنِي؟ قَالَ: "فَأَنْتَ شَهِيدٌ". قَالَ: أَرَأَيْتَ إِنْ قَتَلْتُهُ؟ قَالَ: "هُوَ فِي النَّارِ". (م)', 'അബൂഹുറൈറ(റ): ഒരാൾ തിരുദൂതർ(സ)യുടെ സന്നിധിയിൽ വന്നിട്ട് ചോദിച്ചു: തിരുദൂതരേ, ഒരാൾ എന്റെ സമ്പത്ത് കൊള്ളയടിക്കാനുദ്ദേശിച്ച് വന്നാൽ അയാളെക്കുറിച്ച് എന്താണ് അങ്ങയുടെ അഭിപ്രായം? നബി(സ) പറഞ്ഞു: "നിന്റെ മുതൽ അവന് നൽകരുത്." അയാൾ ചോദിച്ചു: അയാൾ എന്നോട് യുദ്ധം ചെയ്താലോ? നബി(സ) പറഞ്ഞു: "അവനോട് നീ യുദ്ധം ചെയ്യുക." അയാൾ ചോദിച്ചു: അവൻ എന്നെ വധിച്ചാൽ എന്താണങ്ങയുടെ അഭിപ്രായം? നബി(സ) പറഞ്ഞു: "അപ്പോൾ നീ രക്തസാക്ഷിയാണ്." അയാൾ ചോദിച്ചു: ഞാനവനെ വധിച്ചാലോ? നബി(സ) അരുളി: "അവൻ നരകത്തിലാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنْ بَنِي النَّبِيتِ – قَبِيلٌ مِنَ الأَنْصَارِ – فَقَالَ: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّكَ عَبْدُهُ وَرَسُولُهُ. ثُمَّ تَقَدَّمَ فَقَاتَلَ حَتَّى قُتِلَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَمِلَ هَذَا يَسِيرًا وَأُجِرَ كَثِيرًا". (م)', 'ബറാഅ്(റ): അൻസാറുകളുടെ ഒരു ഗോത്രമായ ബനുന്നബീതിൽ പെട്ട ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്നു പറഞ്ഞു: അല്ലാഹു അല്ലാതെ ആരാധ്യനില്ല എന്നും അവിടുന്ന് അവന്റെ അടിമയും ദൂതരുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. പിന്നെ അദ്ദേഹം പോയി യുദ്ധം ചെയ്ത് കൊല്ലപ്പെട്ടു. അന്നേരം നബി(സ) പറഞ്ഞു: "അദ്ദേഹം വളരെ കുറച്ച് മാത്രം പ്രവർത്തിക്കുകയും കൂടുതൽ പ്രതിഫലം നൽകപ്പടുകയും ചെയ്തു." (മു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 902, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عجب رَبُّنَا مِنْ رَجُلٍ غَزَا فِي سَبِيلِ اللَّهِ فَانْهَزَمَ – يَعْنِي أَصْحَابَهُ – فَعَلِمَ مَا عَلَيْهِ، فَرَجَعَ حَتَّى أُهَرِيقَ دَمُهُ، فَيَقُولُ اللَّهُ تَعَالَى لِمَلَائِكَتِهِ: انْظُرُوا إِلَى عَبْدِي: رَجَعَ رَغْبَةً فِيمَا عِنْدِي، وَشَفَقَةً مِمَّا عِنْدِي، حَتَّى أُهَرِيقَ دَمُهُ". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത ഒരുത്തന്റെ കാര്യത്തിൽ നമ്മുടെ രക്ഷിതാവ് അത്ഭുതപ്പെട്ടിരിക്കുന്നു. തന്റെ കൂടെയുള്ള ആളുകൾ പിന്തിരിഞ്ഞപ്പോൾ അയാൾ തന്റെ ബാധ്യത കണ്ടറിഞ്ഞ് വീണ്ടും മടങ്ങിച്ചെന്ന് യുദ്ധംചെയ്ത് മരിച്ചു. അപ്പോൾ അല്ലാഹു തന്റെ മാലാഖമാരോട് പറഞ്ഞു: എന്റെ അടിമയിലേക്ക് നോക്കൂ, എന്റെയടുത്തുള്ള കാര്യങ്ങൾ ആഗ്രഹിച്ചുകൊണ്ടും അതിൽ കൊതിച്ചുകൊണ്ടും അവൻ യുദ്ധഭൂമിയിലേക്ക് മടങ്ങിവന്നു. അങ്ങനെ അവൻ രക്തസാക്ഷിയായി." (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا مَاتَ النَّجَاشِيُّ كُنَّا نَتَحَدَّثُ: أَنَّهُ لَا يَزَالُ يُرَى عَلَى قَبْرِهِ نُورٌ. (د)', 'ആഇശ(റ): നജ്ജാശി മരിച്ചപ്പോൾ ഞങ്ങൾ പരസ്പരം പറഞ്ഞുകൊണ്ടിരുന്നു: അദ്ദേഹത്തിന്റെ ഖബ്റിന്മേൽ ഒരു പ്രകാശമുണ്ടായിക്കൊണ്ടേയിരിക്കും. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: آخَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ رَجُلَيْنِ، فَقُتِلَ أَحَدُهُمَا وَمَاتَ الْآخَرُ بَعْدَهُ بِجُمُعَةٍ أَوْ نَحْوِهَا، فَصَلَّيْنَا عَلَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا قُلْتُمْ". فَقُلْنَا: دَعَوْنَا، وَقُلْنَا: اللَّهُمَّ اغْفِرْ لَهُ وَأَلْحِقْهُ بِصَاحِبِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَأَيْنَ صَلَاتُهُ بَعْدَ صَلَاتِهِ، وَصَوْمُهُ بَعْدَ صَوْمِهِ، وَعَمَلُهُ بَعْدَ عَمَلِهِ، إِنَّ بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ". (د)', 'ഉബൈദുബ്നു ഖാലിദിസ്സുലമി(റ): രണ്ടാളുകൾക്കിടയിൽ നബി(സ) പരസ്പരം സാഹോദര്യം ചേർത്തി. ഒരാൾ യുദ്ധത്തിൽ കൊല്ലപ്പെട്ടു. രണ്ടാമൻ വെള്ളിയാഴ്ചയോ സമാനമായ മറ്റൊരു ദിനത്തിലോ മരണപ്പെട്ടു. ഞങ്ങൾ അയാളുടെ മേൽ ജനാസ നിസ്കരിച്ചു. അല്ലാഹുവിന്റെ റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ എന്താണ് പറഞ്ഞത്?" ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ ഇപ്രകാരം പ്രാർത്ഥിച്ചിരിക്കുന്നു: അല്ലാഹുവേ, ഇദ്ദേഹത്തിന് പൊറുത്തുകൊടുക്കുകയും അവന്റെ കൂട്ടുകാരനോടൊപ്പം ചേർക്കുകയും ചെയ്യേണമേ. അപ്പോൾ നബി(സ)പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ നിസ്കാരത്തിനെ അപേക്ഷിച്ച് ഇദ്ദേഹത്തിന്റെ നിസ്കാരവും അദ്ദേഹത്തിന്റെ നോമ്പിനെ അപേക്ഷിച്ച് ഇദ്ദേഹത്തിന്റെ നോമ്പും അദ്ദേഹത്തിന്റെ കർമ്മത്തിനെ അപേക്ഷിച്ച് ഇദ്ദേഹത്തിന്റെ കർമ്മവും എവിടെ കിടക്കുന്നു. നിശ്ചയം ഇവർ തമ്മിലുള്ള അന്തരം ആകാശഭൂമികളൾക്കിടയിലുള്ള അന്തരമാണ്." (ദ)', 'عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ', 'ഉബൈദുബ്നു ഖാലിദിസ്സുലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ نِمْرَانِ بْنِ عُتْبَةَ الذِّمَارِيِّ قَالَ: دَخَلْنَا عَلَى أُمِّ الدَّرْدَاءِ وَنَحْنُ أَيْتَامٌ فَقَالَتْ: أَبْشِرُوا، فَإِنِّي سَمِعْتُ أَبَا الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُشَفَّعُ الشَّهِيدُ فِي سَبْعِينَ مِنْ أَهْلِ بَيْتِهِ". (د)', 'നിംറാനുബ്നു ഉത്ബതുദ്ദിമാരി(റ): ഉമ്മുദർദാഅ്(റ)യുടെ അടുക്കൽ ഞങ്ങൾ ചെന്നു. ഞങ്ങൾ അനാഥരായിരുന്നു. മഹതി പറഞ്ഞു: നിങ്ങൾ സന്തോഷിച്ചുകൊള്ളുക. അബുദ്ദർദാഅ്(റ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "രക്തസാക്ഷിക്ക് തന്റെ കുടുംബത്തിലെ എഴുപത് പേർക്ക് ശഫാഅത്ത് ചെയ്യാം." (ദ)', 'نِمْرَانِ بْنِ عُتْبَةَ الذِّمَارِيِّ قَالَ', 'നിംറാനുബ്നു ഉത്ബതുദ്ദിമാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 903, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَجْتَمِعُ فِي النَّارِ كَافِرٌ وَقَاتِلُهُ أَبَدًا". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു സത്യനിഷേധിയും അവനെ വധിച്ചവനും ഒരിക്കലും നരകത്തിൽ ഒരുമിച്ചുണ്ടാവുകയില്ല." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ فَصَلَ فِي سَبِيلِ اللَّهِ فَمَاتَ أَوْ قُتِلَ فَهُوَ شَهِيدٌ، أَوْ وَقَصَهُ فَرَسُهُ أَوْ بَعِيرُهُ – أَوْ لَدَغَتْهُ هَامَّةٌ، أَوْ مَاتَ عَلَى فِرَاشِهِ، أَوْ بِأَيٍّ حَتْفٍ شَاءَ اللَّهُ – فَإِنَّهُ شَهِيدٌ، وَإِنَّ لَهُ الْجَنَّةَ". (د)', 'അബൂമാലിക്കിൽ അശ്അരി(റ): തിരുദൂതർ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരാൾ വീട് വിട്ടിറങ്ങി മരിക്കുകയോ അല്ലെങ്കിൽ കൊല്ലപ്പെടുകയോ ചെയ്താൽ അയാൾ രക്തസാക്ഷിയാണ്. അല്ലെങ്കിൽ അവന്റെ കുതിരയോ ഒട്ടകമോ അവനെ ചവിട്ടിക്കൊന്നു - അല്ലെങ്കിൽ ഏതെങ്കിലും വിഷജന്തു കടിച്ചു, അതല്ലെങ്കിൽ അവൻ വിരിപ്പിൽ കിടന്ന് മരിച്ചു, അല്ലെങ്കിൽ അല്ലാഹു ഉദ്ദേശിച്ച ഏതെങ്കിലും നാശം വന്ന് അവൻ മരിച്ചു - എന്നാലുമവൻ രക്തസാക്ഷിയാണ്. അവന് സ്വർഗ്ഗമുണ്ട്." (ദ)', 'أَبِي مَالِكٍ الْأَشْعَرِيِّ', 'അബൂമാലിക്കിൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عمرو بْنَ أُقَيْشٍ كَانَ لَهُ رِبًا فِي الْجَاهِلِيَّةِ، فَكَرِهَ أَنْ يُسْلِمَ حَتَّى يَأْخُذَهُ، فَجَاءَ يَوْمُ أُحُدٍ فَقَالَ: أَيْنَ بَنُو عَمِّي؟ قَالُوا: بِأُحُدٍ، قَالَ: أَيْنَ فُلَانٌ؟ قَالُوا: بِأُحُدٍ، قَالَ: فَأَيْنَ فُلَانٌ؟ قَالُوا: بِأُحُدٍ، فَلَبِسَ لَأْمَتَهُ وَرَكِبَ فَرَسَهُ ثُمَّ تَوَجَّهَ قِبَلَهُمْ، فَلَمَّا رَآهُ الْمُسْلِمُونَ قَالُوا: إِلَيْكَ عَنَّا يَا عَمْرُو، قَالَ: إِنِّي قَدْ آمَنْتُ، فَقَاتَلَ حَتَّى جُرِحَ، فَحُمِلَ إِلَى أَهْلِهِ جَرِيحًا، فَجَاءَهُ سَعْدُ بْنُ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ لِأُخْتِهِ: سَلِيهِ: حَمِيَّةً لِقَوْمِكَ، أَوْ غَضَبًا لَهُمْ، أَمْ غَضَبًا لِلَّهِ؟ فَقَالَ: بَلْ غَضَبًا لِلَّهِ وَلِرَسُولِهِ. فَمَاتَ، فَدَخَلَ الْجَنَّةَ وَمَا صَلَّى لِلَّهِ صَلَاةً. (د)', 'അബൂഹുറൈറ(റ): അംറുബ്നു ഉഖൈശ്(റ) ജാഹിലിയ്യാ കാലത്ത് പലിശക്ക് പണം കൊടുക്കാറുണ്ടായിരുന്നു. അത് വാങ്ങുന്നതുവരെ ഇസ്ലാം സ്വീകരിക്കാൻ അദ്ദേഹം അറച്ചുനിന്നു. അങ്ങനെ ഉഹ്ദ് യുദ്ധദിവസമായപ്പോൾ അദ്ദേഹം ചോദിച്ചു: എന്റെ പിതൃസഹോദരന്റെ മക്കളെവിടെ? അവർ പറഞ്ഞു: ഉഹ്ദിലാണ്. അദ്ദേഹം ചോദിച്ചു: ഇന്നയാളെവിടെ? അവർ പറഞ്ഞു: ഉഹ്ദിൽ. വീണ്ടും ചോദിച്ചു: ഇന്നയാൾ എവിടെ? അവർ പറഞ്ഞു: ഉഹ്ദിൽ. അപ്പോൾ അദ്ദേഹം പടയങ്കിയണിഞ്ഞ് കുതിരപ്പുറത്ത് കയറി അവർക്ക് നേരെ തിരിച്ചു. മുസ്ലിംകൾ അദ്ദേഹത്തെ കണ്ടപ്പോൾ പറഞ്ഞു: അംറേ, മാറി നിൽക്കുക. അദ്ദേഹം പറഞ്ഞു: ഞാൻ സത്യവിശ്വാസമുൾകൊണ്ടിരിക്കുന്നു. അങ്ങനെ അദ്ദേഹം യുദ്ധം ചെയ്തു, മുറിവ് പറ്റി. മുറിവേറ്റവനായിക്കൊണ്ട് അദ്ദേഹത്തെ കുടുംബക്കാരിലേക്ക് കൊണ്ടുപോയി. അന്നേരം സഅ്ദുബ്നു മുആദ്(റ) അദ്ദേഹത്തിന്റെയടുത്ത് വന്ന് അദ്ദേഹത്തിന്റെ സഹോദരിയോട് പറഞ്ഞു. അദ്ദേഹത്തോട് ഇപ്രകാരം ചോദിക്കുക: തന്റെ ആളുകളുടെ രക്ഷക്ക് വേണ്ടിയാണോ അതോ അവർക്ക് വേണ്ടിയുള്ള രോഷത്തിനാണോ അല്ലെങ്കിൽ അല്ലാഹുവിന് വേണ്ടിയുള്ള രോഷത്തിന് വേണ്ടിയാണോ യുദ്ധം ചെയതതെന്ന്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്നും അവന്റെ റസൂലിനും വേണ്ടിയുള്ള രോഷത്തിന്റെ പേരിലാണ് യുദ്ധം ചെയ്തത്. പിന്നീട് അദ്ദേഹം മരിച്ചു, സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്തു. അദ്ദേഹം ഒരിക്കൽ പോലും അല്ലാഹുവിന് വേണ്ടി നമസ്കരിച്ചിട്ടില്ല. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سمع رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ فُوَاقَ نَاقَةٍ فَقَدْ وَجَبَتْ لَهُ الْجَنَّةُ، وَمَنْ سَأَلَ اللَّهَ الْقَتْلَ مِنْ نَفْسِهِ صَادِقًا – ثُمَّ مَاتَ أَوْ قُتِلَ – فَإِنَّ لَهُ أَجْرَ شَهِيدٍ، زَادَ ابْنُ الْمُصَفَّى مِنْ هُنَا وَمَنْ جُرِحَ جُرْحًا فِي سَبِيلِ اللَّهِ – أَوْ نُكِبَ نَكْبَةً – فَإِنَّهَا تَجِيءُ يَوْمَ الْقِيَامَةِ كَأَغْزَرِ مَا كَانَتْ: لَوْنُهَا لَوْنُ الزَّعْفَرَانِ وَرِيحُهَا رِيحُ الْمِسْكِ، وَمَنْ خَرَجَ بِهِ خُرَاجٌ فِي سَبِيلِ اللَّهِ فَإِنَّ عَلَيْهِ طَابَعَ الشُّهَدَاءِ". (د,ت,ن,جه)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ, ഒട്ടകത്തെ രണ്ടുപ്രാവശ്യം കറക്കുന്നതിനിടയിലുള്ളയത്ര സമയം യുദ്ധംചെയ്താൽ സ്വർഗ്ഗം അവന് നിർബന്ധമായിരിക്കുന്നു. ഒരാൾ സത്യസന്ധമായ ഹൃദയത്തോടെ തന്റെ രക്ഷിതാവിനോട് രക്തസാക്ഷിത്വത്തെ ആവശ്യപ്പെട്ടാൽ - പിന്നെ മരിക്കുകയോ കൊല്ലപ്പെടുകയോ ചെയ്താൽ - അവന് രക്തസാക്ഷിയുടെ കൂലിയുണ്ട്. ഇബ്നുൽ മുസ്വഫാ(റ) ഇവിടെ ഇതുകൂടി പറഞ്ഞിട്ടുണ്ട്: ഒരാൾക്ക് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുറിവ് പറ്റിയാൽ ഖിയാമത് നാളിൽ അവന്റെ മുറിവ് കുങ്കുമത്തിന്റെ നിറവും കസ്തൂരിയുടെ ഗന്ധവുമുള്ളതായി കൂടുതൽ രക്തം പുരണ്ട അവസ്ഥയിൽ വരും. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വല്ല മുറിവും പറ്റിയ വ്യക്തിക്ക് ശഹീദിന്റെ മുദ്രയുണ്ടായിരിക്കും." (ദ,തു,ന,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 904, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَمَّا أُصِيبَ إِخْوَانُكُمْ بِأُحُدٍ جَعَلَ اللَّهُ أَرْوَاحَهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ، تَرِدُ أَنْهَارَ الْجَنَّةِ تَأْكُلُ مِنْ ثِمَارِهَا، وَتَأْوِي إِلَى قَنَادِيلَ مِنْ ذَهَبٍ مُعَلَّقَةٍ فِي ظِلِّ الْعَرْشِ، فَلَمَّا وَجَدُوا طِيبَ مَأْكَلِهِمْ وَمَشْرَبِهِمْ وَمَقِيلِهِمْ قَالُوا: مَنْ يُبَلِّغُ إِخْوَانَنَا عَنَّا أَنَّا أَحْيَاءٌ فِي الْجَنَّةِ نُرْزَقُ، لِئَلَّا يَزْهَدُوا فِي الْجِهَادِ وَلَا يَنْكُلُوا عِنْدَ الْحَرْبِ؟ فَقَالَ اللَّهُ سُبْحَانَهُ: أَنَا أُبَلِّغُهُمْ عَنْكُمْ، قَالَ: فَأَنْزَلَ اللَّهُ: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ} إِلَى آخِرِ الْآيَةِ [آل عمران: ١٦٩]". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരങ്ങൾ ഉഹ്ദിൽ കൊല്ലപ്പെട്ടപ്പോൾ അവരുടെ ആത്മാവുകളെ അല്ലാഹു ഒരു തരം പച്ചവർണ്ണത്തിലുള്ള കിളികളുടെ ഉള്ളിലാക്കി. അവർ സ്വർഗ്ഗത്തിലെ പുഴകളിൽ വരികയും അവിടത്തെ പഴവർഗ്ഗങ്ങൾ ഭക്ഷിക്കുകയും അർശിന്റെ തണലിൽ ബന്ധിക്കപ്പെട്ട സ്വർണ്ണ വിളക്കുകളിലേക്ക് പറന്നടുക്കുകയും ചെയ്യും. അവയുടെ തീറ്റയുടെയും കുടിയുടെയും ഉറക്കങ്ങളുടെയും സുഗന്ധം അനുഭവിക്കുമ്പോൾ അവ പറയും: ഞങ്ങൾ സ്വർഗ്ഗത്തിൽ ജീവിക്കുകയും ഭക്ഷിക്കുകയും ചെയ്യുന്നുണ്ടെന്ന് ആരാണ് ഞങ്ങളുടെ സഹോദരങ്ങളെ അറിയിക്കുക, അവർ യുദ്ധത്തിൽ നിന്ന് മാറിനിൽക്കാതിരിക്കാനും അവർക്ക് അതിനെത്തൊട്ട് വിരക്തി വരാതിരിക്കാനും വേണ്ടിയാണിത്. അപ്പോൾ അല്ലാഹു പറയും: ഞാനറിയിച്ചുകൊള്ളും." നബി(സ) പറയുന്നു: "അന്നേരം അല്ലാഹു ഈ സൂക്തമിറക്കി: ''അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെട്ടവർ മരിച്ചവരാണെന്ന് നിങ്ങൾ വിചാരിക്കേണ്ട. അവർ അവന്റെയടുത്ത് ജീവിച്ചുകൊണ്ടിരിക്കുന്നു'' അവസാനം വരെ." (ആലു ഇംറാൻ: 169) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'آل عمران: ١٦٩', null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَسْلَمَ بْنِ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ فِي الْجَنَّةِ؟ قَالَ: "النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْجَنَّةِ، وَالشَّهِيدُ فِي الْجَنَّةِ، وَالْمَوْلُودُ فِي الْجَنَّةِ، وَالْوَئِيدُ فِي الْجَنَّةِ". (د)', 'അസ്ലമുബ്നു സുലൈം(റ): നബി(സ)യോട് ഞാൻ ചോദിച്ചു: ആരൊക്കെയാണ് സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുക? നബി(സ) പറഞ്ഞു: "നബി(സ) സ്വർഗ്ഗത്തിലാണ്, രക്തസാക്ഷി സ്വർഗ്ഗത്തിലാണ്, പിറന്നപാടെയുള്ള ശിശുവും സ്വർഗ്ഗത്തിലാണ്. കുഴിച്ചുമൂടപ്പെട്ട കുട്ടിയും സ്വർഗ്ഗത്തിലാണ്." (ദ)', 'أَسْلَمَ بْنِ سُلَيْمٍ', 'അസ്ലമുബ്നു സുലൈം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْقَتْلُ فِي سَبِيلِ اللَّهِ يُكَفِّرُ كُلَّ خَطِيئَةٍ. فَقَالَ جِبْرِيلُ: إِلَّا الدَّيْنَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِلَّا الدَّيْنَ". (ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള യുദ്ധം സർവ്വ ദോശങ്ങളെയും പൊറുക്കും. ജിബ്രീൽ(അ) പറഞ്ഞു: കടമൊഴികെ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "കടമൊഴികെ." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَرْوَاحَ الشُّهَدَاءِ فِي طَيْرٍ خُضْرٍ، تَعْلُقُ مِنْ ثَمَرِ الْجَنَّةِ. أَوْ: شَجَرِ الْجَنَّةِ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'കഅ്ബുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "രക്തസാക്ഷികളുടെ ആത്മാവുകൾ ഒരുതരം പച്ചപക്ഷികളിലാണ്. സ്വർഗ്ഗത്തിലെ ഫലങ്ങളുമായി, അല്ലെങ്കിൽ വൃക്ഷങ്ങളുമായി അവ ബന്ധപ്പെട്ടു കിടക്കുന്നു." (തു,ന,ജ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عُرِضَ عَلَيَّ أَوَّلُ ثَلَاثَةٍ يَدْخُلُونَ الْجَنَّةَ: شَهِيدٌ، وَعَفِيفٌ مُتَعَفِّفٌ، وَعَبْدٌ أَحْسَنَ عِبَادَةَ اللَّهِ وَنَصَحَ لِمَوَالِيهِ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്ന ആദ്യ മൂന്ന് കൂട്ടരെക്കുറിച്ച് എനിക്ക് വെളിവാക്കപ്പെട്ടു. രക്തസാക്ഷി, ഉള്ളതുകൊണ്ട് തൃപ്തിപ്പെട്ട് സച്ചരിതനായി ജീവിക്കുന്നവൻ, അല്ലാഹുവിന് നന്നായി ഇബാദത്ത് ചെയ്യുകയും കൂടെയുള്ളവരെ ഉപദേശിക്കുകയും ചെയ്യുന്നവൻ എന്നിവരാണവർ." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ عَبْدٍ يَمُوتُ، لَهُ عِنْدَ اللَّهِ خَيْرٌ، يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَأَنَّ لَهُ الدُّنْيَا وَمَا فِيهَا، إِلَّا الشَّهِيدُ، لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ، فَإِنَّهُ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ مَرَّةً أُخْرَى". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു:"മരിച്ച് അല്ലാഹുവിന്റെയടുത്ത് ഗുണം ലഭിച്ച ഒരു അടിമയും, ദുൻയാവും അതിലുള്ളത് മുഴുവനും ലഭിച്ചാലും, ദുൻയാവിലേക്ക് മടങ്ങാൻ ആഗ്രഹിക്കുകയില്ല. രക്തസാക്ഷിയൊഴികെ. എന്തുകൊണ്ടെന്നാൽ രക്തസാക്ഷിത്വത്തിന്റെ ശ്രേഷ്ഠത അവൻ കാണുന്നു. അവൻ ദുൻയാവിലേക്ക് മടങ്ങിവന്ന് വീണ്ടും രക്ത സാക്ഷിയായി മരിക്കാൻ ആഗ്രഹിക്കുന്നു." (തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الشُّهَدَاءُ أَرْبَعَةٌ: رَجُلٌ مُؤْمِنٌ جَيِّدُ الْإِيمَانِ، لَقِيَ الْعَدُوَّ فَصَدَقَ اللَّهَ حَتَّى قُتِلَ، فَذَلِكَ الَّذِي يَرْفَعُ النَّاسُ إِلَيْهِ أَعْيُنَهُمْ يَوْمَ الْقِيَامَةِ هَكَذَا". وَرَفَعَ رَأْسَهُ حَتَّى وَقَعَتْ قَلَنْسُوَتُهُ، قَالَ: فَمَا أَدْرِي أَقَلَنْسُوَةَ عُمَرَ أَرَادَ أَمْ قَلَنْسُوَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: "وَرَجُلٌ مُؤْمِنٌ جَيِّدُ الْإِيمَانِ، لَقِيَ الْعَدُوَّ فَكَأَنَّمَا ضُرِبَ جِلْدُهُ بِشَوْكِ طَلْحٍ مِنَ الْجُبْنِ، أَتَاهُ سَهْمٌ غَرْبٌ فَقَتَلَهُ، فَهُوَ فِي الدَّرَجَةِ الثَّانِيَةِ. وَرَجُلٌ مُؤْمِنٌ، خَلَطَ عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا، لَقِيَ الْعَدُوَّ فَصَدَقَ اللَّهَ حَتَّى قُتِلَ، فَذَلِكَ فِي الدَّرَجَةِ الثَّالِثَةِ. وَرَجُلٌ مُؤْمِنٌ أَسْرَفَ عَلَى نَفْسِهِ، لَقِيَ الْعَدُوَّ فَصَدَقَ اللَّهَ حَتَّى قُتِلَ، فَذَلِكَ فِي الدَّرَجَةِ الرَّابِعَةِ". حَسَنٌ. (ت)', 'ഫുളാലതുബ്നു ഉബൈദ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) പറയുന്നതായി ഞാൻ കേട്ടു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "രക്തസാക്ഷികൾ നാല് വിധമാണ്. നല്ല ഈമാനുള്ള മുഅ്മിനായ ഒരു മനുഷ്യൻ, അവൻ ശത്രുവിനെ കണ്ടുമുട്ടുകയും അല്ലാഹുവിനെ സത്യമാക്കുകയും അങ്ങനെ കൊല്ലപ്പെടുകയും ചെയ്തു. ഇത്തരത്തിലുള്ളവനെ അന്ത്യനാളിൽ ജനങ്ങൾ കണ്ണുകൾകൊണ്ട് മേൽപ്പോട്ട് ഇപ്രകാരം നോക്കും." എന്ന് പറഞ്ഞുകൊണ്ട് അവിടന്ന് തലയുയർത്തിക്കാണിച്ചു. തലയിലെ തൊപ്പി വീണു. നിവേദകൻ പറയുന്നു: നബി(സ)യുടെ തൊപ്പിയെക്കുറിച്ചാണോ അതോ ഉമർ(റ)വിന്റെ തൊപ്പിയെക്കുറിച്ചാണോ പറഞ്ഞതെന്ന് എനിക്കറിയില്ല. നബി(സ) പറയുന്നു: "രണ്ടാമത്തെയാൾ നല്ല ഈമാനുറച്ച മുഅ്മിനായ മനുഷ്യൻ, അവൻ ശത്രുവിനെ കണ്ടുമുട്ടി. അവന്റെ തൊലി, ത്വൽഹി (മുള്ളുനിറഞ്ഞ ഒരു മരം) വൃക്ഷത്തെ പൊതിഞ്ഞ മുള്ള് കണക്കെ ഭീരുത്വം നിറഞ്ഞിരിക്കുന്നു. അവിചാരിതമായി ഒരമ്പ് വന്ന് തറച്ച് അവൻ മരണപ്പെടുന്നു. ഇവൻ രണ്ടാം സ്ഥാനത്താണ്. ഒരു വിശ്വാസിയായ മനുഷ്യൻ, സൽപ്രവർത്തനങ്ങളും ഹീനകൃത്യങ്ങളും അവൻ കൂട്ടിക്കലർത്തി. ശത്രുവിനെ അവൻ കണ്ടു, അല്ലാഹുവിനെ സത്യമാക്കി അവൻ പോരാടി മരിച്ചു. അവന്റെ സ്ഥാനം മൂന്നാമതാണ്. ഒരുപാട് വീഴ്ചകൾ വരുത്തിയ വിശ്വാസിയായ വ്യക്തി, അവൻ ശത്രുവിനെ അഭിമുഖീകരിക്കുകയും അല്ലാഹുവിനെ സത്യമാക്കി പോരാടി മരിക്കുകയും ചെയ്തു. അവൻ നാലാം സ്ഥാനക്കാരനാണ്." ഹദീസ് ഹസനാണ്. (തു)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫുളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 906, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَمْسٌ مَنْ قُبِضَ فِي شَيْءٍ مِنْهُنَّ فَهُوَ شَهِيدٌ: الْمَقْتُولُ فِي سَبِيلِ اللَّهِ شَهِيدٌ، وَالْغَرِقُ فِي سَبِيلِ اللَّهِ شَهِيدٌ، وَالْمَبْطُونُ فِي سَبِيلِ اللَّهِ شَهِيدٌ، وَالْمَطْعُونُ فِي سَبِيلِ اللَّهِ شَهِيدٌ، وَالنُّفَسَاءُ فِي سَبِيلِ اللَّهِ شَهِيدٌ". (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) പറഞ്ഞു: "അഞ്ച് കാര്യങ്ങളിൽ ഏതെങ്കിലുമൊന്ന് കാരണം മരിച്ചാൽ അവൻ രക്തസാക്ഷിയാണ്: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെട്ടവൻ ശഹീദാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുങ്ങിമരിച്ചവൻ ശഹീദാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്തുകൊണ്ടിരിക്കെ വയറ്റിലുള്ള അസുഖം കാരണം മരിച്ചവൻ ശഹീദാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുമ്പോൾ പ്ലേഗ് ബാധിച്ച് മരിച്ചവൻ ശഹീദാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധത്തിലായിരിക്കെ ''നിഫാസ്'' (പ്രസവം) കാരണം മരിച്ചവർ ശഹീദാണ്." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَخْتَصِمُ الشُّهَدَاءُ وَالْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِلَى رَبِّنَا فِي الَّذِينَ يُتَوَفَّوْنَ مِنَ الطَّاعُونِ، فَيَقُولُ الشُّهَدَاءُ: إِخْوَانُنَا، قُتِلُوا كَمَا قُتِلْنَا. وَيَقُولُ الْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ: إِخْوَانُنَا مَاتُوا عَلَى فُرُشِهِمْ كَمَا مُتْنَا. فَيَقُولُ رَبُّنَا: انْظُرُوا إِلَى جِرَاحِهِمْ، فَإِنْ أَشْبَهَ جِرَاحُهُمْ جِرَاحَ الْمَقْتُولِينَ فَإِنَّهُمْ مِنْهُمْ وَمَعَهُمْ، فَإِذَا جِرَاحُهُمْ قَدْ أَشْبَهَتْ جِرَاحَهُمْ". (ن)', 'ഇർബാളുബ്നു സാരിയ(റ): നബി(സ) പറഞ്ഞു: "പ്ലേഗ് കാരണം മരണപ്പെട്ടവരുടെ വിഷയത്തിൽ, രക്തസാക്ഷികളും വിരിപ്പിൽ കിടന്ന് സാധാരണ മരണം മരിച്ചവരും തമ്മിൽ അല്ലാഹുവിനോട് തർക്കിക്കും. അപ്പോൾ രക്തസാക്ഷികൾ പറയും: അവർ ഞങ്ങളുടെ സഹോദരങ്ങളാണ്. ഞങ്ങൾ കൊല്ലപ്പെട്ടതു പോലെത്തന്നെയാണ് അവരും കൊല്ലപ്പെട്ടത്. സാധാരണ മരണം വരിച്ചവർ പറയും: അവർ ഞങ്ങളുടെ സഹോദരങ്ങളാണ്. ഞങ്ങൾ മരിച്ചതു പോലെ വിരിപ്പിൽ കിടന്നാണ് അവരും മരണപ്പെട്ടത്. അപ്പോൾ റബ്ബ് പറയും: അവരുടെ മുറിവുകളിലേക്ക് നിങ്ങൾ നോക്കൂ. അവരുടെ മുറിവുകൾ കൊല്ലപ്പെട്ടവരുടെ മുറിവകളോട് സാമ്യമുണ്ടെങ്കിൽ അവർ അവരിൽ പെട്ടവരും അവരുടെ കൂടെയുമാണ്. അന്നേരം അവരുടെ മുറിവുകൾ കൊല്ലപ്പെട്ടവരുടെ മുറിവുകളുടേത് പോലെയുണ്ടാകും" (ന)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَامَ فِيهِمْ، فَذَكَرَ لَهُمْ أَنَّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَالْإِيمَانَ بِاللَّهِ أَفْضَلُ الْأَعْمَالِ، فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ، أَيُكَفِّرُ اللَّهُ عَنِّي خَطَايَايَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ، إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ، إِلَّا الدَّيْنَ، فَإِنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ قَالَ لِي ذَلِكَ". (ن)', 'അബൂഖതാദ(റ): നബി(സ) അവർക്കിടയിൽ എഴുന്നേറ്റുനിൽക്കുകയും, അല്ലാഹുവിനെക്കൊണ്ട് വിശ്വസിക്കലും അവന്റെ മാർഗ്ഗത്തിൽ ധർമ്മയുദ്ധം ചെയ്യലുമാണ് കർമ്മങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായതെന്ന് അവരോട് പറയുകയും ചെയ്തു. അപ്പോൾ ഒരാൾ എഴുന്നേറ്റുനിന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ വധിക്കപ്പെട്ടാൽ എന്റെ ദോഷങ്ങൾ അല്ലാഹു പൊറുത്തുതരുമോ? നബി(സ) പറഞ്ഞു: "അതെ, കൂലിയാഗ്രഹിച്ച് കൊണ്ട് ക്ഷമയുള്ളവനായി, പിന്തിരിയാതെ മുന്നേറുന്നവനായ നിലയിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെട്ടാൽ (നിന്റെ ദോഷങ്ങൾ പൊറുക്കപ്പെടും), കടമൊഴികെ. അക്കാര്യം ജിബ്രീൽ(അ) എന്നോട് പറഞ്ഞിട്ടുണ്ട്." (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ عَلَى الْمِنْبَرِ، فَقَالَ: أَرَأَيْتَ إِنْ قَاتَلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا، مُقْبِلًا غَيْرَ مُدْبِرٍ، أَيُكَفِّرُ اللَّهُ عَنِّي سَيِّئَاتِي؟ قَالَ: "نعم". ثُمَّ سَكَتَ سَاعَةً، قَالَ: "أَيْنَ السَّائِلُ آنِفًا". فَقَالَ الرَّجُلُ: هَا أَنَا ذَا. قَالَ: "مَا قُلْتَ". قَالَ: أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا، مُقْبِلًا غَيْرَ مُدْبِرٍ، أَيُكَفِّرُ اللَّهُ عَنِّي سَيِّئَاتِي؟ قَالَ: "نعم، إِلَّا الدَّيْنَ، سَارَّنِي بِهِ جِبْرِيلُ آنِفًا". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) മിമ്പറിൽ കയറി പ്രസംഗിച്ച് കൊണ്ടിരിക്കെ ഒരാൾ വന്നുകൊണ്ട് ചോദിച്ചു: ക്ഷമ കൈക്കൊണ്ട്, കൂലിയാഗ്രഹിച്ച്, മുന്നോട്ട് ചെന്ന് പിന്തിരിയാതെ ഞാൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്താൽ എന്റെ ദോഷങ്ങൾ അല്ലാഹു പൊറുക്കുമോ? എന്താണ് അങ്ങയുടെ അഭിപ്രായം? നബി(സ) പറഞ്ഞു: "അതെ." പിന്നെ തിരുമേനി(സ) അൽപനേരം മൗനം പാലിച്ചു. ശേഷം ചോദിച്ചു: "ഇപ്പോൾ ചോദിച്ചയാൾ എവിടെ?" അപ്പോൾ അയാൾ പറഞ്ഞു: ഇതാ, ഞാനിവിടെയുണ്ട്. നബി(സ) ചോദിച്ചു: "താങ്കളെന്താണ് ചോദിച്ചത്?" അയാൾ പറഞ്ഞു: നബിയേ, പറഞ്ഞുതരിക, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ, ക്ഷമ കൈവരിച്ച് കൂലിയാഗ്രഹിച്ച് പിന്തിരിയാതെ മുന്നേറി യുദ്ധം ചെയ്ത് ഞാൻ കൊല്ലപ്പെട്ടാൽ അല്ലാഹു എന്റെ ദോഷങ്ങളെ പൊറുക്കുമോ? നബി(സ) പറഞ്ഞു: "അതെ, കടമൊഴികെ. ജിബ്രീൽ(അ) ഇപ്പോൾ എനിക്ക് രഹസ്യമായി അത് പറഞ്ഞുതന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ خَيْبَرَ قَاتَلَ أَخِي قِتَالًا شَدِيدًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَارْتَدَّ عَلَيْهِ سَيْفُهُ فَقَتَلَهُ، فَقَالَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ وَشَكُّوا فِيهِ: رَجُلٌ مَاتَ بِسِلَاحِهِ. قَالَ سَلَمَةُ: فَقَفَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خَيْبَرَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَتَأْذَنُ لِي أَنْ أَرْتَجِزَ بِكَ؟ فَأَذِنَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: اعْلَمْ مَا تَقُولُ. فَقُلْتُ:
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=148), 1, 'وَفِي رِوَايَةٍ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَذَبُوا، مَاتَ جَاهِدًا مُجَاهِدًا، فَلَهُ أَجْرُهُ مَرَّتَيْنِ" وَأَشَارَ بِأُصْبُعَيْهِ. (م,د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: നബി(സ) പറഞ്ഞു: "അവർ കളവാണ് പറഞ്ഞിരിക്കുന്നത്. അദ്ദേഹം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ബുദ്ധിമുട്ടിയും പോരാടുന്നവനുമായാണ് മരിച്ചത്. അത്കൊണ്ട് അദ്ദേഹത്തിന് രണ്ട് കൂലിയുണ്ട്." നബി(സ) രണ്ട് വിരൽ കൊണ്ട് ആംഗ്യം കാണിച്ചു. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَجُلٌ يَوْمَ أُحُدٍ: أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ، فَأَيْنَ أَنَا؟ قَالَ: "فِي الْجَنَّةِ". فَأَلْقَى تَمَرَاتٍ فِي يَدِهِ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ. (ن)', 'ജാബിർ(റ): ഉഹ്ദ് യുദ്ധത്തിൽ ഒരാൾ ചോദിച്ചു: നബിയേ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ ഇപ്പോൾ കൊല്ലപ്പെട്ടാൽ ഞാൻ എവിടെയായിരിക്കും? നബി(സ) അരുളി: "സ്വർഗ്ഗത്തിൽ." അപ്പോൾ അദ്ദേഹം തന്റെ കയ്യിലുണ്ടായിരുന്ന കാരക്കൾ വലിച്ചെറിഞ്ഞു. എന്നിട്ട് യുദ്ധം ചെയ്ത് രക്തസാക്ഷിയായി മരിച്ചുവീണു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَضَرْتُ حَرْبًا، فَقَالَ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ: يَا نَفْسُ!
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَيُّ الْجِهَادِ أَفْضَلُ؟ قَالَ: "مَنْ أُهَرِيقَ دَمُهُ، وَعُقِرَ جَوَادُهُ". فِي إِسْنَادِهِ ضَعِيفٌ. (د,ت,ن,جه)', 'അംറുബ്നു അബസ(റ): ഞാൻ നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എങ്ങനെയുള്ള യുദ്ധമാണ് ശ്രേഷ്ഠതയേറിയത്? നിബി(സ) പറഞ്ഞു: "രക്തം ചിന്തപ്പെടുകയും തന്റെ കുതിര കൊല്ലപ്പെടുകയും ചെയ്തവന്റെ യുദ്ധം." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ദ,തു,ന,ജ)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مَجْرُوحٍ يُجْرَحُ فِي سَبِيلِ اللَّهِ، وَاللَّهُ أَعْلَمُ بِمَنْ يُجْرَحُ فِي سَبِيلِهِ، إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ وَجُرْحُهُ كَهَيْئَتِهِ يَوْمَ جُرِحَ، اللَّوْنُ لَوْنُ دَمٍ، وَالرِّيحُ رِيحُ مِسْكٍ". (جه)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത് മുറിവുപറ്റുന്ന ഏതൊരുത്തനും (തന്റെ മാർഗ്ഗത്തിൽ മുറിവുപറ്റുന്നവർ ആരെന്ന് അല്ലാഹുവിന്നറിയും) അന്ത്യനാളിൽ വരുമ്പോൾ, അവന്റെ മുറിവ് അത് പറ്റിയ ആ ദിവസത്തെ അതേ രൂപത്തിലായിരിക്കും. അതിന്റെ നിറം രക്തത്തിന്റെ നിറവും ഗന്ധം കസ്തൂരിയുടേതുമായിരിക്കും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 909, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ذُكِرَ الشُّهَدَاءُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لا تجفُّ الأرضُ مِنْ دَمِ الشَّهِيدِ حتى تبتدره زوجتاه، كأنهما ظِئْرَانِ أضَلَّتَا فصيلَيْهِمَا في بَرَاحٍ مِنَ الأرضِ، وفي يد كلِّ واحدةٍ مِنْهُمَا حُلَّةٌ، خيرٌ مِنَ الدُّنْيَا وما فيها". فِي إِسْنَادِهِ ضَعِيفٌ. (جه)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അടുത്ത് ശുഹദാക്കളെക്കുറിച്ച് പറയപ്പെട്ടപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "വിശാലമായ സമതലസ്ഥലത്ത് വെച്ച് തങ്ങളുടെ മക്കളെ നഷ്ടപ്പെട്ട ആയകളെപ്പോലെയുള്ള തന്റെ രണ്ട് ഭാര്യമാർ, തങ്ങളുടെ ഓരോരുത്തരുടെയും കയ്യിൽ ഐഹികലോകത്തേക്കാളും അതിലുള്ളതിനേക്കാളും ശ്രേഷ്ഠമായ ഓരോ വസ്ത്രവും പിടിച്ച്, തന്നിലേക്ക് ഓടിവരുന്നതുവരെ ഒരു രക്തസാക്ഷിയുടെ രക്തം ഭൂമിയിൽ നിന്ന് വറ്റിപ്പോവുകയില്ല." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا قُتِلَ عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ حَرَامٍ يَوْمَ أُحُدٍ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا جَابِرُ، أَلَا أُخْبِرُكَ مَا قَالَ اللَّهُ عَزَّ وَجَلَّ لِأَبِيكَ". قُلْتُ: بَلَى. قَالَ: "مَا كَلَّمَ اللَّهُ أَحَدًا إِلَّا مِنْ وَرَاءِ حِجَابٍ، وَكَلَّمَ أَبَاكَ كِفَاحًا، فَقَالَ: يَا عَبْدِي، تَمَنَّ عَلَيَّ أُعْطِكَ. قَالَ: يَا رَبِّ، تُحْيِينِي فَأُقْتَلُ فِيكَ ثَانِيَةً. قَالَ: إِنَّهُ سَبَقَ مِنِّي: أَنَّهُمْ إِلَيْهَا لَا يُرْجَعُونَ. قَالَ: يَا رَبِّ، فَأَبْلِغْ مَنْ وَرَائِي. فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةَ: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا} [آل عمران: ١٦٩] الْآيَةَ كُلَّهَا". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ഹറാം(റ) ഉഹ്ദ് യുദ്ധത്തിൽ വധിക്കപ്പെട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "ജാബിറേ, അല്ലാഹു നിന്റെ പിതാവിനോട് പറഞ്ഞതെന്താണെന്ന് ഞാൻ നിനക്ക് പറഞ്ഞുതരട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അല്ലാഹു ഒരുത്തനോടും മറയിൽ നിന്നുകൊണ്ടല്ലാതെ സംസാരിച്ചിട്ടില്ല. പക്ഷേ, നിന്റെ പിതാവിനോട് മുഖാമുഖമായാണ് സംസാരിച്ചത്. അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമേ, നിനക്കാഗ്രഹമുള്ളത് പറയുക, ഞാൻ നൽകാം. അദ്ദേഹം പറഞ്ഞു: റബ്ബേ, നീ എന്നെ വീണ്ടും ജീവിപ്പിക്കുക, നിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ രണ്ടാമതും കൊല്ലപ്പെടട്ടെ. അല്ലാഹു പറഞ്ഞു: അവർ ഭൂമിയിലേക്ക് വീണ്ടും മടക്കപ്പെടുകയില്ല എന്ന് എന്നിൽ നിന്നും ആദ്യമേ തീരുമാനിക്കപ്പെട്ടിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, എങ്കിൽ എന്റെ ശേഷമുള്ളവർക്ക് എന്റെ വാർത്ത നീ അറിയിക്കുക. അപ്പോൾ അല്ലാഹു ഈ ആയത്തിറക്കി: ''അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെട്ടവർ മരിച്ചിട്ടുണ്ടെന്ന് നിങ്ങൾ കരുതരുത്.'' ആയത്തിന്റെ അവസാനം വരെ." (ആലുഇംറാൻ: 169) (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'آل عمران: ١٦٩', null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَابَ عَمِّي أَنَسُ بْنُ النَّضْرِ رَضِيَ اللَّهُ عَنْهُ عَنْ قِتَالِ بَدْرٍ، فَقَالَ: يَا رَسُولَ اللَّهِ، غِبْتُ عَنْ أَوَّلِ قِتَالٍ قَاتَلْتُ الْمُشْرِكِينَ، لَئِنِ اللَّهُ أَشْهَدَنِي قِتَالَ الْمُشْرِكِينَ لَيَرَيَنَّ اللَّهُ مَا أَصْنَعُ، فَلَمَّا كَانَ يَوْمُ أُحُدٍ وَانْكَشَفَ الْمُسْلِمُونَ قَالَ: اللَّهُمَّ إِنِّي أَعْتَذِرُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ يَعْنِي أَصْحَابَهُ، وَأَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ يَعْنِي الْمُشْرِكِينَ، ثُمَّ تَقَدَّمَ، فَاسْتَقْبَلَهُ سَعْدُ بْنُ مُعَاذٍ، فَقَالَ: يَا سَعْدَ بْنَ مُعَاذٍ، الْجَنَّةَ وَرَبِّ النَّضْرِ، إِنِّي أَجِدُ رِيحَهَا مِنْ دُونِ أُحُدٍ، قَالَ سَعْدٌ: فَمَا اسْتَطَعْتُ يَا رَسُولَ اللَّهِ مَا صَنَعَ، قَالَ أَنَسٌ: فَوَجَدْنَا بِهِ بِضْعًا وَثَمَانِينَ ضَرْبَةً بِالسَّيْفِ أَوْ طَعْنَةً بِرُمْحٍ، أَوْ رَمْيَةً بِسَهْمٍ. وَوَجَدْنَاهُ قَدْ قُتِلَ، وَقَدْ مَثَّلَ بِهِ الْمُشْرِكُونَ فَمَا عَرَفَهُ أَحَدٌ إِلَّا أُخْتُهُ بِبَنَانِهِ، قَالَ أَنَسٌ: كُنَّا نُرَى أَوْ نَظُنُّ أَنَّ هَذِهِ الْآيَةَ نَزَلَتْ فِيهِ وَفِي أَشْبَاهِهِ: {مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ} إِلَى آخِرِ الْآيَةِ، وَقَالَ: إِنَّ أُخْتَهُ وَهِيَ تُسَمَّى الرُّبَيِّعَ كَسَرَتْ ثَنِيَّةَ امْرَأَةٍ فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْقِصَاصِ، فَقَالَ أَنَسٌ: يَا رَسُولَ اللَّهِ، وَالَّذِي بَعَثَكَ بِالْحَقِّ لَا تُكْسَرُ ثَنِيَّتُهَا، فَرَضُوا بِالْأَرْشِ وَتَرَكُوا الْقِصَاصَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ". (خ)', 'അനസുബ്നു മാലിക്(റ): എന്റെ പിതൃവ്യൻ അനസുബ്നുന്നള്ർ(റ)വിന് ബദർ യുദ്ധത്തിൽ പങ്കെടുക്കാൻ കഴിഞ്ഞില്ല. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ബഹുദൈവാരാധകരുമായി അവിടന്ന് ആദ്യം ചെയ്ത യുദ്ധത്തിൽ എനിക്ക് പങ്കെടുക്കാൻ കഴിഞ്ഞില്ല. ബഹുദൈവാരാധകരോടുള്ള യുദ്ധത്തിൽ അല്ലാഹു എന്നെ പങ്കെടുപ്പിക്കുകയാണെങ്കിൽ ഞാൻ എന്താണ് ചെയ്യുകയെന്ന് അല്ലാഹു കാണുക തന്നെ ചെയ്യും. അങ്ങനെ ഉഹ്ദ് യുദ്ധത്തിൽ മുസ്ലിംകൾ പിന്തിരിഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ, ഇവർ ചെയ്ത ഈ കാര്യത്തിന് ഞാൻ നിന്നോട് കാരണം ബോധിപ്പിക്കുന്നു. തന്റെ അനുചരരെയാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത്. ബഹുദൈവാരാധകർ ചെയ്ത ഈ കാര്യത്തിൽ നിന്ന് ഞാൻ നിന്നോട് നിരപരാധിത്വം ചോദിക്കുന്നു. പിന്നെ അദ്ദേഹം മുന്നിട്ടപ്പോൾ സഅ്ദുബ്നു മുആദ്(റ) അദ്ദേഹത്തെ അഭിമുഖീകരിച്ചു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: സഅ്ദുബ്നു മുആദേ, നള്റിന്റെ രക്ഷിതാവിനെത്തന്നെ സത്യം, സ്വർഗ്ഗത്തിന്റെ സുഗന്ധം ഉഹ്ദിന്റെ ഭാഗത്ത് നിന്നും അടിച്ചുവീശുന്നതായി എനിക്കനുഭവപ്പെടുന്നു. സഅ്ദ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, പിന്നെ എന്താണദ്ദേഹം ചെയ്തതെന്ന് പോലും എനിക്കറിയില്ല. അനസ്(റ) പറയുന്നു: അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ വാള് കൊണ്ടുള്ള വെട്ടുകളോ കുന്തം കൊണ്ടുള്ള കുത്തുകളോ, അമ്പ് കൊണ്ടുള്ള ഏറുകളോ കൊണ്ടുണ്ടായ എൺപതിൽപരം മുറിവുകളുണ്ടായിരുന്നതായി ഞങ്ങൾ കണ്ടെത്തി. അദ്ദേഹം കൊല്ലപ്പെടുകയും മുശ്രിക്കുകൾ അദ്ദേഹത്തെ അംഗഛേദം ചെയ്ത് തുണ്ടമാക്കുകയും ചെയ്തിരുന്നു. അദ്ദേഹത്തിന്റെ വിരൽത്തുമ്പുകൾ കണ്ട് തന്റെ സഹോദരി മാത്രമാണ് അദ്ദേഹത്തെ തിരിച്ചറിഞ്ഞത്. അനസ്(റ) പറയുന്നു: ''സത്യവിശ്വാസികളിൽ അല്ലാഹുവിനോടുള്ള കരാറിനെ പൂർത്തീകരിച്ച ചിലരുണ്ട്'' എന്ന സൂക്തം അദ്ദേഹത്തെയും അതുപോലെയുള്ളവരെയും കുറിച്ചാണ് ഇറങ്ങിയതെന്ന് ഞങ്ങൾ മനസ്സിലാക്കുന്നു, അല്ലെങ്കിൽ അഭിപ്രായപ്പെടുന്നു. നിവേദകൻ പറയുന്നു: റുബയ്യിഅ് എന്ന് പേരുള്ള അദ്ദേഹത്തിന്റെ സഹോദരി ഒരു സ്ത്രീയുടെ മുൻപല്ല് പൊട്ടിച്ചു. നബി(സ) പ്രതിക്രിയ ചെയ്യാൻ കൽപിച്ചു. അപ്പോൾ അനസ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സത്യവുമായി അങ്ങയെ അയച്ചവനെത്തന്നെ സത്യം, അവരുടെ മുൻപല്ല് പൊട്ടിക്കപ്പെടുകയില്ല. അപ്പോൾ അവർ നഷ്ടപരിഹാരം കൊണ്ട് തൃപ്തിപ്പെടുകയും പ്രതിക്രിയ ഒഴിവാക്കുകയും ചെയ്തു. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹുവിന്റെ അടിമകളിൽ ചിലരുണ്ട്, അവർ അല്ലാഹുവിന്റെ മേൽ വല്ലതും സത്യം ചെയ്തു പറഞ്ഞാൽ അല്ലാഹു അവർക്ക് അതിനെ നടപ്പാക്കിക്കൊടുക്കും." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 910, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَسَخْتُ الصُّحُفَ فِي الْمَصَاحِفِ، فَفَقَدْتُ آيَةً مِنْ سُورَةِ الْأَحْزَابِ كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِهَا، فَلَمْ أَجِدْهَا إِلَّا مَعَ خُزَيْمَةَ بْنِ ثَابِتٍ الْأَنْصَارِيِّ الَّذِي جَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهَادَتَهُ شَهَادَةَ رَجُلَيْنِ وَهُوَ قَوْلُهُ: {مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ}. (خ)', 'സൈദുബ്നു സാബിത്(റ): മുസ്ഹഫുകളിൽ ചില മുസ്ഹഫുകളെ ഞാൻ നസ്ഖ് (ദുർബലപ്പെടുത്തുക) ചെയ്യുമ്പോൾ അഹ്സാബ് സൂറത്തിൽ നിന്നുള്ള, നബി(സ) ഓതുന്നതായി ഞാൻ കേൾക്കാറുണ്ടായിരുന്ന ഒരു സൂക്തത്തെ എനിക്ക് നഷ്ടപ്പെട്ടു. നബി(സ), തന്റെ സാക്ഷിത്വത്തെ രണ്ടാളുടെ സാക്ഷിത്വത്തിന്റെ സ്ഥാനത്ത് വെച്ച, ഖുസൈമതുൽ അൻസാരി(റ)വിൽ നിന്ന് മാത്രമാണ് എനിക്കത് ലഭിച്ചത്. ആ സൂക്തം ഇതായിരുന്നു: ''അല്ലാഹുവിനോട് ചെയ്ത കരാർ പൂർത്തീകരിച്ച ഒരു കൂട്ടമാളുകൾ മുഅ്മിനീങ്ങളിലുണ്ട്.'' (ബു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, 'ദുർബലപ്പെടുത്തുക', 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ ثَابِتٍ قَالَ: قَالَ أَنَسٌ رَضِيَ اللَّهُ عَنْهُ: عَمِّيَ الَّذِي سُمِّيتُ بِهِ، لَمْ يَشْهَدْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَدْرًا، قَالَ: فَشَقَّ عَلَيْهِ، قَالَ: أَوَّلُ مَشْهَدٍ شَهِدَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُيِّبْتُ عَنْهُ، وَإِنْ أَرَانِيَ اللَّهُ مَشْهَدًا فِيمَا بَعْدُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَيَرَانِيَ اللَّهُ [تعالى] مَا أَصْنَعُ. قَالَ: فَهَابَ أَنْ يَقُولَ غَيْرَهَا، قَالَ: فَشَهِدَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، قَالَ فَاسْتَقْبَلَ سَعْدُ بْنُ مُعَاذٍ، فَقَالَ لَهُ أَنَسٌ: يَا أَبَا عَمْرٍو أَيْنَ؟ فَقَالَ: وَاهًا لِرِيحِ الْجَنَّةِ أَجِدُهُ دُونَ أُحُدٍ. قَالَ: فَقَاتَلَهُمْ حَتَّى قُتِلَ، قَالَ: فَوُجِدَ فِي جَسَدِهِ بِضْعٌ وَثَمَانُونَ مِنْ بَيْنِ ضَرْبَةٍ وَطَعْنَةٍ وَرَمْيَةٍ، قَالَ: فَقَالَتْ أُخْتُهُ عَمَّتِي الرُّبَيِّعُ بِنْتُ النَّضْرِ: فَمَا عَرَفْتُ أَخِي إِلَّا بِبَنَانِهِ. وَنَزَلَتْ هَذِهِ الْآيَةُ: {رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا} [الأحزاب: ٢٣] قَالَ: فَكَانُوا يُرَوْنَ أَنَّهَا نَزَلَتْ فِيهِ وَفِي أَصْحَابِهِ. (م)', 'സാബിത്(റ): അനസ്(റ) പറയുന്നു: എന്റെ പേര് തന്നെയുള്ള എന്റെ പിതൃവ്യൻ നബി(സ)യുടെ കൂടെ ബദ്റിൽ പങ്കെടുത്തിട്ടില്ലായിരുന്നു. അനസ്(റ) പറയുന്നു: അത് അദ്ദേഹത്തിനെ ആകെ അസ്വസ്ഥനാക്കി. അദ്ദേഹം പറഞ്ഞു: നബി(സ) പങ്കെടുത്ത ആദ്യ യുദ്ധത്തിൽ എനിക്ക് പങ്കെടുക്കാൻ കഴിഞ്ഞില്ല. തിരുദൂതർ(സ)യുടെ കൂടെ ഇനിയുള്ള യുദ്ധത്തിൽ അല്ലാഹു എനിക്ക് അവസരം തരികയാണെങ്കിൽ ഞാൻ ചെയ്യുന്നത് അല്ലാഹു കാണുക തന്നെ ചെയ്യും. അതിനപ്പുറം വല്ലതും പറയാൻ അദ്ദേഹം ഭയപ്പെട്ടു. നിവേദകൻ പറയുന്നു: ഉഹ്ദ് യുദ്ധത്തിൽ അദ്ദേഹം നബി(സ)യുടെ കൂടെ പങ്കെടുത്തു. അനസ്(റ) പറയുന്നു: അപ്പോൾ സഅ്ദുബ്നു മുആദ്(റ) അദ്ദേഹത്തെ അഭിമുഖീകരിച്ചു. അപ്പോൾ അദ്ദേഹത്തോട് അനസ്(റ) ചോദിച്ചു: അബൂഅംറേ, എവിടേക്കാണ്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: സ്വർഗ്ഗത്തിന്റെ ഗന്ധത്തിനെന്തൊരു രസമാണ്. ഉഹ്ദിന്റെ ഭാഗത്ത് നിന്ന് ഞാനതനുഭവിക്കുന്നു. അദ്ദേഹം പറയുന്നു: അങ്ങനെ അദ്ദേഹം അവരോട് പോരാടുകയും വധിക്കപ്പെടുകയും ചെയ്തു. വെട്ടും കുത്തും ഏറും കൊണ്ട് അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ എൺപതിലേറെ മുറിവുകളുണ്ടായിരുന്നു. അദ്ദേഹം പറയുന്നു. എന്റെ പിതൃസഹോദരിയായ അദ്ദേഹത്തിന്റെ സഹോദരി റുബയ്യിഅ് ബിൻതുനള്ർ(റ) പറയുന്നു: എന്റെ സഹോദരനെ ഞാൻ അദ്ദേഹത്തിന്റെ വിരൽത്തുമ്പുകൾ കണ്ടുകൊണ്ടാണ് തിരിച്ചറിഞ്ഞത്. അപ്പോൾ ഈ സൂക്തമിറങ്ങി: ''അല്ലാഹുവിനോട് ചെയ്ത കരാറിനെ പൂർത്തീകരിച്ച ചിലയാളുകളുണ്ട്. തങ്ങളുടെ ഊഴത്തെ എത്തിച്ചവരും അതിനെ കാത്തിരിക്കുന്നവരും അവരിലുണ്ട്. അവർ അതിൽ മാറ്റം വരുത്തിയിട്ടില്ല.'' അനസ്(റ) പറയുന്നു: ഈ സൂക്തം അദ്ദേഹത്തിന്റെയും കൂട്ടുകാരുടെയും പേരിലാണ് ഇറങ്ങിയതെന്ന് സ്വഹാബികൾ അഭിപ്രായപ്പെട്ടിരുന്നു. (മു)', 'ثَابِتٍ قَالَ', 'സാബിത്(റ)', null, null, array['م']::text[], array['മു']::text[], 'الأحزاب: ٢٣', null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يَعْجَبُ مِنْ رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا صَاحِبَهُ – وَقَالَ مَرَّةً أُخْرَى: لَيَضْحَكُ مِنْ رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا صَاحِبَهُ – ثُمَّ يَدْخُلَانِ الْجَنَّةَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രണ്ടാളുകളെക്കുറിച്ച് അല്ലാഹു അത്ഭുതപ്പെടും, അവരിൽ ഒരാൾ മറ്റവനെ വധിക്കുന്നു - മറ്റൊരിക്കൽ നബി(സ) പറഞ്ഞു: രണ്ടാളുകളുടെ അവസ്ഥ കണ്ട് അല്ലാഹു ചിരിക്കുന്നു, അവരിലൊരാൾ മറ്റവനെ വധിക്കുന്നു - പിന്നെ അവർ രണ്ടുപേരും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്യുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَضْحَكُ اللَّهُ لِرَجُلَيْنِ، يَقْتُلُ أَحَدُهُمَا الْآخَرَ، كِلَاهُمَا يَدْخُلُ الْجَنَّةَ". قَالُوا: كَيْفَ يَا رَسُولَ اللَّهِ؟ قَالَ: "يُقْتَلُ هَذَا فَيَلِجُ الْجَنَّةَ، ثُمَّ يَتُوبُ اللَّهُ عَلَى الْآخَرِ، فَيَهْدِيهِ إِلَى الْإِسْلَامِ، ثُمَّ يُجَاهِدُ فِي سَبِيلِ اللَّهِ فَيُسْتَشْهَدُ". (ق,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രണ്ടാളുകളുടെ കാര്യത്തിൽ അല്ലാഹു ചിരിക്കും. അവരിലൊരാൾ മറ്റൊരാളെ വധിക്കുകയും രണ്ടാളും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്യുന്നു." സ്വഹാബികൾ ചോദിച്ചു: അതെങ്ങനെയാണ് റസൂലേ സംഭവിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "ആദ്യത്തെയാൾ കൊല്ലപ്പെടുകയും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്യുന്നു. രണ്ടാമത്തെയാളുടെ പശ്ചാത്താപം അല്ലാഹു സ്വീകരിക്കുകയും അങ്ങനെ അവനെ ഇസ്ലാമിലേക്ക് മാർഗ്ഗദർശനം ചെയ്യുകയും ചെയ്യുന്നു. പിന്നെ അവൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത് രക്തസാക്ഷിയാകുന്നു." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُكْلَمُ أَحَدٌ فِي سَبِيلِ اللَّهِ – وَاللَّهُ أَعْلَمُ بِمَنْ يُكْلَمُ فِي سَبِيلِهِ – إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ وَجُرْحُهُ يَثْعَبُ دَمًا: اللَّوْنُ لَوْنُ دَمٍ وَالرِّيحُ رِيحُ الْمِسْكِ". (ق,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുറിവ് പറ്റുന്ന ഏതൊരുത്തനും - അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുറിവ് പറ്റിയവൻ ആരെന്ന് അല്ലാഹുവിന് അറിയും - അന്ത്യനാളിൽ മുറിവിൽ നിന്നും രക്തം ഒഴുകിക്കൊണ്ടായിരിക്കും വരിക. അതിന്റെ നിറം രക്തത്തിന്റേതും ഗന്ധം കസ്തൂരിയുടേതുമായിരിക്കും." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "زَمِّلُوهُمْ بِدِمَائِهِمْ، فَإِنَّهُ لَيْسَ كَلْمٌ يُكْلَمُ فِي اللَّهِ إِلَّا أَتَى يَوْمَ الْقِيَامَةِ جُرْحُهُ يَدْمَى: لَوْنُهُ لَوْنُ دَمٍ، وَرِيحُهُ رِيحُ الْمِسْكِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സഅ്ലബ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "അവരെ അവരുടെ രക്തത്തോടൊപ്പം പുതപ്പിക്കുക. കാരണം, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുറിവ് പറ്റിയ ഏതൊരുത്തനും തന്റെ മുറിവിൽ നിന്ന് രക്തം ഒലിക്കുന്നവനായാണ് അന്ത്യനാളിൽ വരിക. അതിന്റെ നിറം രക്തത്തിന്റെ നിറവും ഗന്ധം കസ്തൂരിയുടേതുമായിരിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ', 'അബ്ദുല്ലാഹിബ്നു സഅ്ലബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي سَلَّامٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَغَرْنَا عَلَى حَيٍّ مِنْ جُهَيْنَةَ، فَطَلَبَ رَجُلٌ مِنَ الْمُسْلِمِينَ رَجُلًا مِنْهُمْ فَضَرَبَهُ فَأَخْطَأَهُ، وَأَصَابَ نَفْسَهُ بِالسَّيْفِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَخُوكُمْ يَا مَعْشَرَ الْمُسْلِمِينَ". فَابْتَدَرَهُ النَّاسُ فَوَجَدُوهُ قَدْ مَاتَ، فَلَفَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثِيَابِهِ وَدِمَائِهِ وَصَلَّى عَلَيْهِ وَدَفَنَهُ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَشَهِيدٌ هُوَ؟ قَالَ: "نَعَمْ، وَأَنَا لَهُ شَهِيدٌ". (د)', 'അബൂസല്ലാം(റ): അദ്ദേഹം ഒരു സ്വഹാബിയിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: ജുഹൈനയിലെ ഒരു ഗോത്രത്തോട് ഞങ്ങൾ യുദ്ധം ചെയ്തു. മുസ്ലിംകളിൽ നിന്നൊരുത്തൻ അവരിലൊരാളെ തേടിപ്പിടിച്ചു. എന്നിട്ടയാളെ വെട്ടി. പക്ഷേ, അത് പിഴക്കുകയും വാൾ അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ തന്നെ പതിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മുസ്ലിം സമൂഹമേ, നിങ്ങളുടെ സഹോദരൻ!" അവർ അദ്ദേഹത്തെ ധൃതിപ്പെട്ട് ചെന്നുനോക്കി. അപ്പോൾ അദ്ദേഹം മരിച്ചിരുന്നു. നബി(സ) അദ്ദേഹത്തെ തന്റെ രക്തത്തോടും വസ്ത്രത്തോടുംകൂടെ കഫൻ ചെയ്യുകയും മയ്യിത്ത് നിസ്കരിക്കുകയും ഖബറടക്കുകയും ചെയ്തു. സ്വഹാബികൾ ചോദിച്ചു: റസൂലേ, അദ്ദേഹം രക്തസാക്ഷിയാണോ? നബി(സ) പറഞ്ഞു: "അതെ, ഞാനദ്ദേഹത്തിന് സാക്ഷിയാണ്." (ദ)', 'أَبِي سَلَّامٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'അബൂസല്ലാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 913, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَرْتُ فَإِذَا أَبُو جَهْلٍ صَرِيعٌ قَدْ ضُرِبَتْ رِجْلُهُ، فَقُلْتُ: يَا عَدُوَّ اللَّهِ يَا أَبَا جَهْلٍ، قَدْ أَخْزَى اللَّهُ الْأَخِرَ. قَالَ: وَلَا أَهَابُهُ عِنْدَ ذَلِكَ، فَقَالَ: أَبْعَدُ مِنْ رَجُلٍ قَتَلَهُ قَوْمُهُ! فَضَرَبْتُهُ بِسَيْفٍ غَيْرِ طَائِلٍ، فَلَمْ يُغْنِ شَيْئًا حَتَّى سَقَطَ سَيْفُهُ مِنْ يَدِهِ، فَضَرَبْتُهُ بِهِ حَتَّى بَرَدَ. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): യുദ്ധഭൂമിയിലൂടെ ഞാൻ നടന്നുപോവുമ്പോൾ അബൂജഹ്ൽ കാലിന് വെട്ടേറ്റുവീണുകിടക്കുന്നതു കണ്ടു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ശത്രു, അബൂജഹ്ലേ, അല്ലാഹുവിന്റെ ദയയെത്തൊട്ട് വിദൂരത്തായവനെ അല്ലാഹു അപമാനിച്ചിരിക്കുന്നു. അദ്ദേഹം പറയുന്നു: അന്നേരം അദ്ദേഹത്തെ ഞാൻ ഒട്ടും ഭയപ്പെട്ടില്ല. അപ്പോൾ അബൂജഹ്ൽ പറഞ്ഞു: തന്റെ സ്വന്തം സമൂഹത്താൽ തന്നെ വധിക്കപ്പെടുന്നവൻ എത്ര നിന്ദ്യൻ. അപ്പോൾ ഞാൻ നീളം കുറഞ്ഞ വാളുകൊണ്ട് അവനെ വെട്ടി. പക്ഷേ, അതുകൊണ്ട് യാതൊരുപകാരവും ഉണ്ടായില്ല. അന്നേരം അവന്റെ കയ്യിൽ നിന്ന് അവന്റെ വാൾ നിലത്തുവീണു. അതെടുത്ത് അവന്റെ ജീവൻ പോകുന്നതുവരെ ഞാൻ വെട്ടിക്കൊണ്ടിരുന്നു. (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ هِشَامِ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: شُكِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجِرَاحَاتُ يَوْمَ أُحُدٍ، فَقَالَ: "احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا، وَادْفِنُوا الِاثْنَيْنِ وَالثَّلَاثَةَ فِي قَبْرٍ وَاحِدٍ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا". فَمَاتَ أَبِي، فَقُدِّمَ بَيْنَ يَدَيْ رَجُلَيْنِ. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ഹിശാമുബ്നു ആമിർ(റ): ഉഹ്ദ് യുദ്ധദിവസം മുറിവ്പറ്റി മരിച്ചവരെക്കുറിച്ച് നബി(സ)യോട് പരാതി ബോധിപ്പിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിശാലതയോടെയും നന്നാക്കിയും കുഴി കുഴിക്കുക. രണ്ടോ മൂന്നോ പേരെ ഒന്നിച്ച് ഒരു ഖബ്റിൽ മറമാടുക. അവരിൽ കൂടുതൽ ഖുർആൻ അറിയുന്നവർക്ക് മുൻഗണന നൽകുക." എന്റെ പിതാവ് മരണപ്പെട്ടിരുന്നു. അദ്ദേഹം രണ്ടാളുകളേക്കാൾ മുന്തിക്കപ്പെട്ടു. (ദ,തു,ന,ജ)', 'هِشَامِ بْنِ عَامِرٍ', 'ഹിശാമുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا كَانَ يَوْمُ أُحُدٍ جَاءَتْ عَمَّتِي بِأَبِي لِتَدْفِنَهُ فِي مَقَابِرِنَا، فَنَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رُدُّوا الْقَتْلَى إِلَى مَضَاجِعِهِمْ". حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉഹ്ദ് യുദ്ധത്തിന്റെ ദിവസം എന്റെ പിതൃസഹോദരി എന്റെ പിതാവിനെ ഞങ്ങളുടെ ഖബ്ർസ്ഥാനിൽ മറവുചെയ്യാൻ കൊണ്ടുവന്നു. അപ്പോൾ തിരുമേനി(സ)യുടെ വക്താവ് ഇപ്രകാരം വിളിച്ചുപറഞ്ഞു: "കൊല്ലപ്പെട്ടവരെ അവർ കിടന്ന സ്ഥലങ്ങളിലേക്ക് തന്നെ മടക്കുക." (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ تُنْصَرُونَ وَتُرْزَقُونَ إِلَّا بِضُعَفَائِكُمْ". (خ)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലെ ബലഹീനന്മാരെക്കൊണ്ട് മാത്രമാണ് നിങ്ങൾ സഹായിക്കപ്പെടുന്നതും നിങ്ങൾക്ക് എല്ലാം നൽകപ്പെടുന്നതും." (ബു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَأْتِي زَمَانٌ يَغْزُو فِئَامٌ مِنَ النَّاسِ، فَيُقَالُ: فِيكُمْ مَنْ صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَيُقَالُ: نَعَمْ، فَيُفْتَحُ عَلَيْهِ، ثُمَّ يَأْتِي زَمَانٌ فَيُقَالُ: فِيكُمْ مَنْ صَحِبَ أَصْحَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَيُقَالُ: نَعَمْ، فَيُفْتَحُ عَلَيْهِ، ثُمَّ يَأْتِي زَمَانٌ فَيُقَالُ: فِيكُمْ مَنْ صَحِبَ صَاحِبَ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَيُقَالُ: نَعَمْ، فَيُفْتَحُ". (خ)', 'അബൂസഇൗദ്(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങളിൽ ഒരു വിഭാഗം യുദ്ധം ചെയ്യുന്ന ഒരു കാലം വരും. അവരോട് ചെദിക്കപ്പെടും: നിങ്ങളുടെ കൂട്ടത്തിൽ നബി(സ)യുമായി സഹവസിച്ചവരാരെങ്കിലുമുണ്ടോ? അപ്പോൾ പറയപ്പെടും: അതെ. അപ്പോൾ അവർ വിജയിക്കും. പിന്നെ ഒരു കാലം വരും. അപ്പോൾ ചോദിക്കപ്പെടും: നിങ്ങളിൽ നബി(സ)യുടെ അനുയായികളുമായി സഹവസിച്ചവരാരെങ്കിലുമുണ്ടോ? അപ്പോൾ പറയപ്പെടും: അതെ. അങ്ങനെ അവർ വിജയം വരിക്കും. പിന്നെ ഒരു കാലം വരും. അപ്പോൾ ചോദിക്കപ്പെടും: നിങ്ങളിൽ നബി(സ)യുടെ അനുചരന്മാരുടെ സഹവാസികളോട് സഹവസിച്ചവരാരെങ്കിലുമുണ്ടോ? അപ്പോൾ പറയപ്പെടും: അതെ. അങ്ങനെ അവർ വിജയിക്കും." (ബു)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ ظَنَّ أَنَّ لَهُ فَضْلًا عَلَى مَنْ دُونَهُ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَنْصُرُ اللَّهُ هَذِهِ الْأُمَّةَ بِضَعِيفِهَا: بِدَعْوَتِهِمْ وَصَلَاتِهِمْ وَإِخْلَاصِهِمْ". (ن)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ)യുടെ സ്വഹാബികളിൽ തന്റെ താഴെയുള്ളവരെക്കാൾ തനിക്ക് മഹത്വമുണ്ടെന്ന് അദ്ദേഹത്തിന് തോന്നി. അന്നേരം നബി(സ) പറഞ്ഞു: "ഈ സമുദായത്തിലെ ബലഹീനരുടെ പ്രാർത്ഥന കൊണ്ടും നമസ്കാരം കൊണ്ടും ആത്മാർത്ഥത കൊണ്ടുമാണ് അല്ലാഹു ഈ സമുദായത്തിന് സഹായം നൽകുന്നത്." (ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "ابْغُونِي الضَّعِيفَ، فَإِنَّكُمْ إِنَّمَا تُرْزَقُونَ وَتُنْصَرُونَ بِضُعَفَائِكُمْ". (د,ت,ن)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "എനിക്ക് വേണ്ടി നിങ്ങൾ അബലന്മാരെ തേടുക. നിശ്ചയം നിങ്ങൾക്ക് നൽകപ്പെടുന്നതും നിങ്ങൾ സഹായിക്കപ്പെടുന്നതും നിങ്ങളിലെ ബലഹീനരെക്കൊണ്ടാണ്." (ദ,തു,ന)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا تَصَدَّقَ بِنَاقَةٍ مَخْطُومَةٍ فِي سَبِيلِ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيَأْتِيَنَّ يَوْمَ الْقِيَامَةِ بِسَبْعِ مِائَةِ نَاقَةٍ مَخْطُومَةٍ". (ن)', 'അബൂമസ്ഊദ്(റ): ഒരു സ്വഹാബി മൂക്കയറിട്ട ഒരൊട്ടകത്തെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ദാനം ചെയ്തു. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ മൂക്കയറിട്ട എഴുന്നൂറ് ഒട്ടകങ്ങളുമായി അദ്ദേഹം വരും." (ന)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ نُودِيَ فِي الْجَنَّةِ: يَا عَبْدَ اللَّهِ، هَذَا خَيْرٌ. فَمَنْ كَانَ مِنْ أَهْلِ الصَّلَاةِ دُعِيَ مِنْ بَابِ الصَّلَاةِ، وَمَنْ كَانَ مِنْ أَهْلِ الْجِهَادِ دُعِيَ مِنْ بَابِ الْجِهَادِ، وَمَنْ كَانَ مِنْ أَهْلِ الصَّدَقَةِ دُعِيَ مِنْ بَابِ الصَّدَقَةِ، وَمَنْ كَانَ مِنْ أَهْلِ الصِّيَامِ دُعِيَ مِنْ بَابِ الرَّيَّانِ". فَقَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: هَلْ عَلَى مَنْ دُعِيَ مِنْ هَذِهِ الْأَبْوَابِ مِنْ ضَرُورَةٍ، فَهَلْ يُدْعَى أَحَدٌ مِنْ هَذِهِ الْأَبْوَابِ كُلِّهَا؟ قَالَ: "نَعَمْ، وَأَرْجُو أَنْ تَكُونَ مِنْهُمْ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രണ്ടുതരം സൽക്കർമ്മങ്ങൾ ആരെങ്കിലും ചെയ്താൽ സ്വർഗ്ഗത്തിൽ വിളിക്കപ്പെടും: അല്ലാഹുവിന്റെ അടിമേ, ഇത് നന്മയാണ്. അപ്പോൾ ഒരാൾ നിസ്കരിച്ചവരുടെ കൂട്ടത്തിലാണ് ഉള്ളതെങ്കിൽ നിസ്കാരത്തിന്റെ കവാടത്തിൽ വെച്ച് അദ്ദേഹം വിളിക്കപ്പെടും. ധർമ്മസമരത്തിന്റെ ആളുകളിൽ പെട്ടവനാണെങ്കിൽ ജിഹാദിന്റെ വാതിലിൽ വെച്ച് വിളിക്കപ്പെടും. ദാനത്തിന്റെ ആളുകളിൽ പെട്ടവനാണെങ്കിൽ സ്വദഖയുടെ വാതിലിൽ വെച്ച് വിളിക്കപ്പെടും. നോമ്പുകാരുടെ കൂട്ടത്തിൽ പെട്ടവനാണെങ്കിൽ അവൻ റയ്യാൻ വാതിലിൽ വെച്ച് വിളിക്കപ്പെടും." അപ്പോൾ അബൂബക്കർ സിദ്ദീഖ്(റ) ചോദിച്ചു: ഈ വാതിലുകളിൽ വെച്ച് വിളിക്കപ്പെട്ടവർക്ക് വല്ല ബുദ്ധിമുട്ടുമുണ്ടാവുമോ? എല്ലാ വാതിലുകളിലും വെച്ച് ആരെങ്കിലും വിളിക്കപ്പെടുമോ? നബി(സ) പറഞ്ഞു: "അതെ, താങ്കൾ അവരിൽ പെട്ട ഒരാളാണെന്ന് ഞാൻ പ്രതീക്ഷിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ دَعَتْهُ خَزَنَةُ الْجَنَّةِ مِنْ أَبْوَابِ الْجَنَّةِ: يَا فُلَانُ، هَلُمَّ فَادْخُلْ". فَقَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللَّهِ، ذَاكَ الَّذِي لَا تَوَى عَلَيْهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَرْجُو أَنْ تَكُونَ مِنْهُمْ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രണ്ടുതരം നന്മകൾ ഒരാൾ ചെയ്താൽ സ്വർഗ്ഗകവാടങ്ങളിലെ കാവൽക്കാർ അവനെ വിളിക്കും: മനുഷ്യാ, വരൂ, നീ ഇതിലൂടെ പ്രവേശിക്കൂ." അപ്പോൾ അബൂബക്കർ സിദ്ദീഖ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അയാൾ പരാജയം സംഭവിക്കാത്തവനാണല്ലോ? അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "താങ്കളും അവരിൽ പെട്ടവരാണെന്ന് ഞാൻ കരുതുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ صَعْصَعَةَ بْنِ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقِيتُ أَبَا ذَرٍّ رَضِيَ اللَّهُ عَنْهُ، قُلْتُ: حَدِّثْنِي. قَالَ: نَعَمْ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ عَبْدٍ مُسْلِمٍ يُنْفِقُ مِنْ كُلِّ مَالٍ لَهُ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ إِلَّا اسْتَقْبَلَتْهُ حَجَبَةُ الْجَنَّةِ، كُلُّهُمْ يَدْعُوهُ إِلَى مَا عِنْدَهُ". قُلْتُ: وَكَيْفَ ذَلِكَ؟ قَالَ: إِنْ كَانَتْ إِبِلًا فَبَعِيرَيْنِ، وَإِنْ كَانَتْ بَقَرًا فَبَقَرَتَيْنِ. (ن)', 'സ്വഅ്സ്വഅതുബ്നു മുആവിയ(റ): അബൂദർറ്(റ)വിനെ ഞാൻ കണ്ടുമുട്ടി. ഞാൻ പറഞ്ഞു: എനിക്ക് ഹദീസ് പറഞ്ഞുതരൂ. അദ്ദേഹം പറഞ്ഞു: ഞാൻ പറഞ്ഞുതരാം. നബി(സ) പറഞ്ഞു: "തന്റെ മുഴുവൻ സ്വത്തിൽ നിന്നും രണ്ട് ഇനങ്ങളെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുന്ന ഏതൊരു മുസ്ലിമായ അടിമയെയും സ്വർഗ്ഗത്തിന്റെ കാവൽക്കാർ സ്വീകരിക്കാതിരിക്കുകയില്ല. എല്ലാവരും അവരുടെയടുത്തുള്ളതിലേക്ക് അവനെ ക്ഷണിക്കും." ഞാൻ ചോദിച്ചു: എങ്ങനെയാണത്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഒട്ടകമാണെങ്കിൽ രണ്ട് ഒട്ടകത്തെയും പശുവാണെങ്കിൽ രണ്ട് പശുവിനെയും ചെലവഴിക്കുക. (ന)', 'صَعْصَعَةَ بْنِ مُعَاوِيَةَ', 'സ്വഅ്സ്വഅതുബ്നു മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ خُرَيْمِ بْنِ فَاتِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ كُتِبَتْ لَهُ بِسَبْعِ مِائَةِ ضِعْفٍ". (ن)', 'ഖുറൈമുബ്നു ഫാതിക്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ എന്തെങ്കിലും ചെലവഴിച്ചാൽ എഴുന്നൂറിരട്ടിയായി അത് അവന് എഴുതപ്പെടും." (ന)', 'خُرَيْمِ بْنِ فَاتِكٍ', 'ഖുറൈമുബ്നു ഫാതിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 916, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ: دِينَارٌ يُنْفِقُهُ عَلَى عِيَالِهِ، وَدِينَارٌ يُنْفِقُهُ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ، وَدِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ". (م,ت,جه)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മനുഷ്യൻ ചെലവഴിക്കുന്ന ഏറ്റവും മഹത്വമേറിയ ദീനാർ തന്റെ ആശ്രിതർക്കു വേണ്ടി ചെലവഴിക്കുന്ന ദീനാറും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരു കുതിരക്ക് വേണ്ടി ചെലവഴിക്കുന്ന ദീനാറും, പിന്നെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ തന്റെ സുഹൃത്തുക്കൾക്ക് വേണ്ടി ചെലവഴിക്കുന്ന ദീനാറുമാണ്." (മു,തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 917, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، وَأَبِي الدَّرْدَاءِ، وَأَبِي هُرَيْرَةَ، وَأَبِي أُمَامَةَ الْبَاهِلِيِّ، وَعَبْدِ اللَّهِ بْنِ عُمَرَ، وَجَابِرِ بْنِ عَبْدِ اللَّهِ، وَعِمْرَانَ بْنِ الْحُصَيْنِ، رَضِيَ اللَّهُ عَنْهُمْ، كُلُّهُمْ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَالَ: "مَنْ أَرْسَلَ بِنَفَقَةٍ فِي سَبِيلِ اللَّهِ، وَأَقَامَ فِي بَيْتِهِ، فَلَهُ بِكُلِّ دِرْهَمٍ سَبْعُ مِائَةِ دِرْهَمٍ، وَمَنْ غَزَا بِنَفْسِهِ فِي سَبِيلِ اللَّهِ، وَأَنْفَقَ فِي وَجْهِ ذَلِكَ، فَلَهُ بِكُلِّ دِرْهَمٍ سَبْعُ مِائَةِ أَلْفِ دِرْهَمٍ" ثُمَّ تَلَا هَذِهِ الْآيَةَ: {وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ} [البقرة: ٢٦١]. فِي إِسْنَادِهِ مَجْهُولٌ. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ), അബുദ്ദർദാഅ്(റ), അബൂഹുറൈറ(റ), അബൂഉമാമത്തുൽ ബാഹിലി(റ), അബ്ദുല്ലാഹിബ്നു അംറ്(റ), ജാബിറുബ്നു അബ്ദില്ല(റ), ഇംറാനുബ്നുൽ ഹുസൈൻ(റ): ഇവരെല്ലാം റസൂൽ(സ)യിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: നബി(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കാൻ കൊടുത്തയച്ചു. അവൻ വീട്ടിൽ തന്നെ നിന്നു. എന്നാൽ അവന് ഓരോ ദിർഹമിനും എഴുന്നൂറ് ദിർഹമുണ്ട്. ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുകയും അതിന്റെ കാര്യത്തിനായി ചെലവഴിക്കുകയും ചെയ്താൽ അവന് ഓരോ ദിർഹമിനും ഏഴു ലക്ഷം ദിർഹമിന്റെ പ്രതിഫലമുണ്ട്." പിന്നെ നബി(സ) ഈ സൂക്തം ഓതി: ''അല്ലാഹു ഉദ്ദേശിക്കുന്നവന് അവൻ ഇരട്ടിപ്പിച്ചുകൊടുക്കും'' (അൽബഖറ: 261) ഇതിന്റെ പരമ്പരയിൽ ഒരു അജ്ഞാതനുണ്ട്. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ، وَأَبِي الدَّرْدَاءِ، وَأَبِي هُرَيْرَةَ، وَأَبِي أُمَامَةَ الْبَاهِلِيِّ، وَعَبْدِ اللَّهِ بْنِ عُمَرَ، وَجَابِرِ بْنِ عَبْدِ اللَّهِ، وَعِمْرَانَ بْنِ الْحُصَيْنِ،', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'البقرة: ٢٦١', null, 917, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْأَعْمَالُ بِالنِّيَّةِ، وَإِنَّمَا لِامْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَتَزَوَّجُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ". (ق,ت,ن,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "കർമ്മങ്ങൾ നിയ്യത്ത് (ഉദ്ദേശ്യം) കൊണ്ടാണുള്ളത്. ഓരോ മനുഷ്യന്നും അവൻ കരുതിയതാണുള്ളത്. ഒരാളുടെ ഹിജ്റ (പലായനം) അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കും ആണെങ്കിൽ (കരുതിയതെങ്കിൽ) അത് അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കുമാണ്. ഒരാളുടെ ഹിജ്റ ദുൻയാവിന് വേണ്ടിയാണെങ്കിൽ അതവന് ലഭിക്കും. ഒരു പെണ്ണിന് വേണ്ടിയാണെങ്കിൽ അവളെ വിവാഹം കഴിക്കും. അപ്പോൾ അവന്റെ ഹിജ്റ അവൻ ഏതൊന്നിന് വേണ്ടിയാണോ ഹിജ്റ പോയത്, അതിലേക്കാണ്." (ബു,മു,തു,ന,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 917, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَعْرَابِيًّا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، الرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ، وَالرَّجُلُ يُقَاتِلُ لِيُذْكَرَ، وَالرَّجُلُ يُقَاتِلُ لِيُرَى مَكَانُهُ، فَمَنْ فِي سَبِيلِ اللَّهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ أَعْلَى فَهُوَ فِي سَبِيلِ اللَّهِ". (ق,د,ت,ن,جه)', 'അബൂമൂസൽഅശ്അരി(റ): അഅ്റാബിയായ ഒരാൾ നബി(സ)യുടെ അടുത്തേക്ക് വന്നുചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരാൾ ഗനീമത്തിന് (യുദ്ധമുതൽ) വേണ്ടി യുദ്ധം ചെയ്യുന്നു. ഒരാൾ അവനെക്കുറിച്ച് പറയപ്പെടാൻ വേണ്ടി യുദ്ധം ചെയ്യുന്നു. ഒരാൾ അവന്റെ സ്ഥാനം കാണിക്കപ്പെടാൻ വേണ്ടി യുദ്ധം ചെയ്യുന്നു. ഇതിൽ ആരാണ് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധംചെയ്യുന്നവൻ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ വചനം അത്യുന്നതമാവാൻ വേണ്ടി ആര് പോരാടുന്നുവോ അവനാണ് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവൻ." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽഅശ്അരി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 917, 918, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ سُلَيْمَانَ بْنِ يَسَارٍ قَالَ: تَفَرَّقَ النَّاسُ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ لَهُ نَاتِلُ أَهْلِ الشَّامِ: أَيُّهَا الشَّيْخُ، حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: نَعَمْ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيَامَةِ عَلَيْهِ رَجُلٌ اسْتُشْهِدَ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ: قَاتَلْتُ فِيكَ حَتَّى اسْتُشْهِدْتُ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ قَاتَلْتَ لِأَنْ يُقَالَ جَرِيءٌ فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ. وَرَجُلٌ تَعَلَّمَ الْعِلْمَ وَعَلَّمَهُ، وَقَرَأَ الْقُرْآنَ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ، وَقَرَأْتُ فِيكَ الْقُرْآنَ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِمٌ، وَقَرَأْتَ الْقُرْآنَ لِيُقَالَ هُوَ قَارِئٌ، فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ. وَرَجُلٌ وَسَّعَ اللَّهُ عَلَيْهِ، وَأَعْطَاهُ مِنْ أَصْنَافِ الْمَالِ كُلِّهِ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ: مَا تَرَكْتُ مِنْ سَبِيلٍ تُحِبُّ أَنْ يُنْفَقَ فِيهَا، إِلَّا أَنْفَقْتُ فِيهَا لَكَ. قَالَ: كَذَبْتَ وَلَكِنَّكَ فَعَلْتَ لِيُقَالَ: هُوَ جَوَادٌ، فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ ثُمَّ أُلْقِيَ فِي النَّارِ". (م)', 'സുലൈമാനുബ്നു യസാർ(റ): അബൂഹുറൈറ(റ)യുടെയടുത്ത് നിന്ന് ജനങ്ങൾ പിരിഞ്ഞുപോയപ്പോൾ അദ്ദേഹത്തോട് ശാമിലെ ''നാതിൽ'' എന്നയാൾ പറഞ്ഞു: അല്ലയോ നേതാവേ, നബി(സ)യിൽ നിന്ന് താങ്കൾ കേട്ട ഒരു ഹദീസ് ഞങ്ങൾക്ക് പറഞ്ഞുതരിക. അദ്ദേഹം പറഞ്ഞു: അതെ. നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അന്ത്യനാളിൽ ആദ്യമായി വിധിനിർണ്ണയിക്കപ്പെടുക രക്തസാക്ഷിയായ ഒരാളുടെ മേലിലായിരിക്കും. അങ്ങനെ അവനെ കൊണ്ടുവരപ്പെടും. അവന് അല്ലാഹു ചെയ്തുകൊടുത്ത അനുഗ്രഹങ്ങൾ മുഴുവൻ അവനെ അറിയിക്കും. എല്ലാം അവൻ മനസ്സിലാക്കും. ശേഷം അവനോട് ചോദിക്കും: എന്നിട്ട് നീയെന്തു ചെയ്തു? അവൻ പറയും: ഞാൻ നിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്ത് ശഹീദായി. അല്ലാഹു പറയും: നീ പറയുന്നത് കള്ളമാണ്. നീ യുദ്ധം ചെയ്തത് ഒരു ധൈര്യശാലിയാണെന്ന് പറയപ്പെടാൻ വേണ്ടിയായിരുന്നു. അങ്ങനെ പറയപ്പെടുകയും ചെയ്തു. പിന്നെ അവനെ നരകത്തിലിടാൻ കൽപിക്കും. അവൻ മുഖം കീഴായി വലിച്ചിഴക്കപ്പെടുകയും അങ്ങനെ നരകത്തിൽ എറിയപ്പെടുകയും ചെയ്യും. അടുത്തതായി ധാരാളം അറിവ് നേടുകയും പഠിപ്പിക്കുകയും ഖുർആനോതുകയും ചെയ്ത ഒരാളെയായിരിക്കും വിചാരണചെയ്യുക. അവനെ കൊണ്ടുവരപ്പെടുകയും അവന് ലഭിച്ച അനുഗ്രഹങ്ങൾ പറഞ്ഞുകൊടുക്കുകയും അവൻ അത് തിരിച്ചറിയുകയും ചെയ്യും. അവനോട് ചോദിക്കും: നീയെന്താണ് ചെയ്തത്? അവൻ പറയും: ഞാൻ വിദ്യ അഭ്യസിക്കുകയും പഠിപ്പിക്കുകയും നിനക്ക് വേണ്ടി ഖുർആൻ ഓതുകയും ചെയ്തിട്ടുണ്ട്. അല്ലാഹു പറയും: നീ നുണയാണ് പറഞ്ഞത്. മറിച്ച് നീ അറിവ് നേടിയത് പണ്ഡിതൻ എന്ന് വിളിക്കപ്പെടാനും, ഖുർആൻ ഓതിയത് നന്നായി പാരായണം ചെയ്യുന്നയാൾ എന്നറിയപ്പെടാനും വേണ്ടിയാണ്. അങ്ങനെ പറയപ്പെടുകയും ചെയ്തിട്ടുണ്ട്. പിന്നെ അവനെ നരകത്തിലിടാൻ കൽപിക്കപ്പെടുകയും മുഖത്തിന്മേൽ വലിച്ചിഴക്കപ്പെടുകയും അങ്ങനെ നരകത്തിലെറിയപ്പെടുകയും ചെയ്യും. അടുത്തതായി വിചാരണ ചെയ്യപ്പെടുക അല്ലാഹു വിശാലമായി സമ്പത്ത് കൊടുത്തയാളായിരിക്കും. അവന് എല്ലാ തരത്തിലുള്ള മുതലുകളും നൽകിയിട്ടുണ്ട്. അവനെ കൊണ്ടുവരികയും അവന് ലഭിച്ച അനുഗ്രഹങ്ങൾ അറിയിച്ചുകൊടുക്കുകയും അവൻ അത് മനസ്സിലാക്കുകയും ചെയ്യും. അവനോട് ചോദിക്കും: നീ ഈ അനുഗ്രഹങ്ങളൊക്കെയുണ്ടായിട്ട് എന്തുചെയ്തു? അവൻ പറയും: നീ ചെലവഴിക്കാൻ ഇഷ്ടപ്പെടുന്ന ഒരു മാർഗ്ഗത്തിലും ഞാൻ നിനക്ക് വേണ്ടി ചെലവഴിക്കാതിരുന്നിട്ടില്ല. അല്ലാഹു പറയും: നീ കളവാണ് പറയുന്നത്. നീ ഇതെല്ലാം ചെയ്തത് ഉദാരനെന്ന് വിളിക്കപ്പെടാൻ വേണ്ടിയാണ്. അങ്ങനെ വിളിക്കപ്പെടുകയും ചെയ്തു. പിന്നെ അവനെ നരകത്തിലിടാൻ കൽപിക്കപ്പെടുകയും മുഖത്തിന്മേൽ വലിച്ചിഴക്കപ്പെടുകയും പിന്നെ നരകത്തിലെറിയപ്പെടുകയും ചെയ്യും." (മു)', 'سُلَيْمَانَ بْنِ يَسَارٍ قَالَ', 'സുലൈമാനുബ്നു യസാർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 918, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْغَزْوُ غَزْوَانِ: فَأَمَّا مَنِ ابْتَغَى وَجْهَ اللَّهِ وَأَطَاعَ الْإِمَامَ، وَأَنْفَقَ الْكَرِيمَةَ، وَيَاسَرَ الشَّرِيكَ، وَاجْتَنَبَ الْفَسَادَ، فَإِنَّ نَوْمَهُ وَنُبْهَهُ أَجْرٌ كُلُّهُ. وَأَمَّا مَنْ غَزَا فَخْرًا وَرِيَاءً وَسُمْعَةً، وَعَصَى الْإِمَامَ، وَأَفْسَدَ فِي الْأَرْضِ، فَإِنَّهُ لَمْ يَرْجِعْ بِالْكَفَافِ". (د,ن)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) പറഞ്ഞു: "യുദ്ധം രണ്ടു വിധമാണ്. ഒരാൾ അല്ലാഹുവിനെ ആഗ്രഹിച്ച്, ഇമാമിനെ അനുസരിച്ച്, മാന്യമായ നിലയിൽ ചെലവഴിച്ച്, കൂടെയുള്ളവരോട് നന്നായി പെരുമാറി, അക്രമങ്ങൽ ഉപേക്ഷിച്ച് യുദ്ധം ചെയ്യുന്നു. അപ്പോൾ അവന്റെ ഉറക്കവും ഉണർച്ചയും മുഴുവൻ അവന് കൂലിയാണ്. ഒരാൾ നേതാവിനെ അനുസരിക്കാതെ, അഹന്തയ്ക്കും പ്രശസ്തിക്കും ഭൂമിയിൽ ഫസാദുണ്ടാക്കാനും വേണ്ടി യുദ്ധം ചെയ്യുന്നു. അവൻ കൂലി മതിയായിക്കൊണ്ട് മടങ്ങുകയില്ല." (ദ,ന)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 919, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، رَجُلٌ يُرِيدُ الْجِهَادَ فِي سَبِيلِ اللَّهِ، وَهُوَ يَبْتَغِي عَرَضًا مِنْ عَرَضِ الدُّنْيَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا أَجْرَ لَهُ". فَأَعْظَمَ ذَلِكَ النَّاسُ، وَقَالُوا لِلرَّجُلِ: عُدْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَعَلَّكَ لَمْ تُفَهِّمْهُ. فَقَالَ: يَا رَسُولَ اللَّهِ، رَجُلٌ يُرِيدُ الْجِهَادَ فِي سَبِيلِ اللَّهِ، وَهُوَ يَبْتَغِي عَرَضًا مِنْ عَرَضِ الدُّنْيَا؟ فَقَالَ: "لَا أَجْرَ لَهُ". فَقَالُوا لِلرَّجُلِ: عُدْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ الثَّالِثَةَ، فَقَالَ لَهُ: "لَا أَجْرَ لَهُ". (د)', 'അബൂഹുറൈറ(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധംചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. അതിൽ ദുൻയാവിലെ കാര്യങ്ങളിൽ നിന്ന് ഒരു ലക്ഷ്യവുമുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവന് കൂലിയില്ല." ജനങ്ങൾ ഇത് വലിയ വിഷയമാക്കി. അവർ അയാളോട് പറഞ്ഞു: നീ നബി(സ)യോട് ഒന്നുകൂടി ചോദിക്കുക, നീ നബി(സ)ക്ക് മനസ്സിലാക്കിക്കൊടുത്തിട്ടില്ല. അദ്ദേഹം വീണ്ടും നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഒരാൾ യുദ്ധം ചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. ദുൻയാവിലെ ഒരു ഉപകാരം നേടാൻ അവൻ ആഗ്രഹിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവന് കൂലി ലഭിക്കുകയില്ല." ജനങ്ങൾ അദ്ദേഹത്തോട് പറഞ്ഞു: നീ നബി(സ)യോട് ഒന്നുകൂടി ചോദിക്കുക. അദ്ദേഹം മൂന്നാം പ്രാവശ്യവും നബി(സ)യോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അവന് കൂലിയില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 919, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي عَنِ الْجِهَادِ وَالْغَزْوِ؟ فَقَالَ: "يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو، إِنْ قَاتَلْتَ صَابِرًا مُحْتَسِبًا، بَعَثَكَ اللَّهُ صَابِرًا مُحْتَسِبًا وَإِنْ قَاتَلْتَ مُرَائِيًا مُكَاثِرًا بَعَثَكَ اللَّهُ مُرَائِيًا مُكَاثِرًا. يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو، عَلَى أَيِّ حَالٍ قَاتَلْتَ أَوْ قُتِلْتَ بَعَثَكَ اللَّهُ عَلَى تِلْكَ الْحَالِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അല്ലാഹുവിന്റെ റസൂലേ, യുദ്ധത്തിനെക്കുറിച്ചും ജിഹാദിനെക്കുറിച്ചും പറഞ്ഞുതരിക? അപ്പോൾ നബി(സ) പറഞ്ഞു: "അബ്ദുല്ലാഹിബ്നു അംറേ, നീ കൂലി ആഗ്രഹിച്ചുകൊണ്ടും ക്ഷമയുള്ളവനായിക്കൊണ്ടും യുദ്ധംചെയ്താൽ അല്ലാഹു കൂലി ആഗ്രഹിക്കുന്നവനായും ക്ഷമയുള്ളവനായും നിന്നെ പുനർജീവിപ്പിക്കും. ഇനി നീ ജനങ്ങളെ കാണിച്ചുകൊണ്ടും കൂടുതൽ ലഭിക്കാൻ (ജനങ്ങളിൽ നിന്ന് (പ്രശംസവാക്കുകളും മറ്റും) ഉദ്ദേശിച്ചുകൊണ്ടും യുദ്ധം ചെയ്താൽ അല്ലാഹു നിന്നെ പ്രദർശിപ്പിക്കുന്നവനായും കൂടുതൽ ലഭിക്കാൻ ആഗ്രഹിക്കുന്നവനായും പുനർജീവിപ്പിക്കും. അബ്ദുല്ലാഹിബ്നു അംറേ, നീ ഏതൊരവസ്ഥയിലാണോ യുദ്ധംചെയ്തത്, അല്ലെങ്കിൽ കൊല്ലപ്പെട്ടത്, അതേ അവസ്ഥയിൽ അല്ലാഹു നിന്നെ ഉയിർത്തെഴുന്നേൽപിക്കും." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 919, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَبْدِ اللَّهِ بْنِ حَوَالَةَ الْأَزْدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِنَغْنَمَ عَلَى أَقْدَامِنَا، فَرَجَعْنَا فَلَمْ نَغْنَمْ شَيْئًا، وَعَرَفَ الْجَهْدَ فِي وُجُوهِنَا، فَقَامَ فِينَا فَقَالَ: "اللَّهُمَّ لَا تَكِلْهُمْ إِلَيَّ فَأَضْعُفَ عَنْهُمْ، وَلَا تَكِلْهُمْ إِلَى أَنْفُسِهِمْ فَيَعْجِزُوا عَنْهَا، وَلَا تَكِلْهُمْ إِلَى النَّاسِ فَيَسْتَأْثِرُوا عَلَيْهِمْ". ثُمَّ وَضَعَ يَدَهُ عَلَى رَأْسِي، أَوْ قَالَ: عَلَى هَامَتِي، ثُمَّ قَالَ: "يَا ابْنَ حَوَالَةَ، إِذَا رَأَيْتَ الْخِلَافَةَ قَدْ نَزَلَتْ أَرْضَ الْمُقَدَّسَةِ فَقَدْ دَنَتِ الزَّلَازِلُ وَالْبَلَابِلُ وَالْأُمُورُ الْعِظَامُ، وَالسَّاعَةُ يَوْمَئِذٍ أَقْرَبُ مِنَ النَّاسِ مِنْ يَدِي هَذِهِ مِنْ رَأْسِكَ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഹവാലതിൽ അസ്ദി(റ): കാൽനടയായിച്ചെന്ന് യുദ്ധമുതൽ പിടിക്കാൻവേണ്ടി, നബി(സ)ഞങ്ങളെ പറഞ്ഞയച്ചു. പക്ഷേ, ഞങ്ങൾ ഒന്നും ലഭിക്കാതെ മടങ്ങിവന്നു. ഞങ്ങളുടെ മുഖത്തു നിന്ന് ഞങ്ങളുടെ ബുദ്ധിമുട്ട് നബി(സ) മനസ്സിലാക്കി. നബി(സ) ഞങ്ങളുടെയിടയിൽ എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: "അല്ലാഹുവേ, അവരെ എന്നെ ഏൽപിക്കരുത്, ഞാൻ അവരെത്തൊട്ട് അശക്തനാകും. അവരെ അവരിലേക്ക് തന്നെ ഏൽപിക്കരുത്, കാരണം അവർ അക്കാര്യത്തിൽ അശക്തരാകും. ജനങ്ങലിലേക്ക് അവരെ നീ ഏൽപിക്കരുത്. കാരണം ജനങ്ങൾ സ്വന്തത്തിന് നല്ലത് തെരഞ്ഞെടുക്കും." പിന്നെ അവിടുത്തെ കൈ എന്റെ തലയിൽ വെച്ചു. (റഅ്സ് എന്നാണോ ഹാമ്മത്ത് എന്നാണോ പറഞ്ഞതെന്നതിൽ നിവേദകൻ സംശയിക്കുന്നു.) പിന്നീട് പറഞ്ഞു: "ഇബ്നു ഹവാല, പരിശുദ്ധ ഭൂമിയിൽ ഖിലാഫത്ത് വന്നുവെന്ന് നീ കാണുമ്പോൾ ഭുകമ്പങ്ങളും ബുദ്ധിമുട്ടുകളും പ്രാധാന്യം നിറഞ്ഞ പല കാര്യങ്ങളും അടുത്തിട്ടുണ്ടാകും. എന്റെ കയ്യിനും നിന്റെ തലക്കുമിടയിലുള്ള അടുപ്പത്തേക്കാൾ അന്ത്യനാൾ അന്ന് ജനങ്ങളോട് അടുത്തിരിക്കും." (ദ)', 'عَبْدِ اللَّهِ بْنِ حَوَالَةَ الْأَزْدِيِّ', 'അബ്ദുല്ലാഹിബ്നു ഹവാലതിൽ അസ്ദി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, 'റഅ്സ് എന്നാണോ ഹാമ്മത്ത് എന്നാണോ പറഞ്ഞതെന്നതിൽ നിവേദകൻ സംശയിക്കുന്നു.', 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَرَأَيْتَ رَجُلًا غَزَا يَلْتَمِسُ الْأَجْرَ وَالذِّكْرَ، مَالَهُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا شَيْءَ لَهُ". فَأَعَادَهَا ثَلَاثَ مَرَّاتٍ يَقُولُ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا شَيْءَ لَهُ". ثُمَّ قَالَ: "إِنَّ اللَّهَ لَا يَقْبَلُ مِنَ الْعَمَلِ إِلَّا مَا كَانَ لَهُ خَالِصًا، وَابْتُغِيَ بِهِ وَجْهُهُ". (ن)', 'അബൂഉമാമതുൽ ബാഹിലി(റ): നബി(സ)യുടെ സന്നിധിയിൽ ഒരാൾ വന്നു ചോദിച്ചു: കൂലി പ്രതീക്ഷിച്ചും പ്രശംസ ആഗ്രഹിച്ചും യുദ്ധംചെയ്യുന്ന ഒരാളെക്കുറിച്ച് അങ്ങയുടെ അഭിപ്രായമെന്താണ് നബിയേ, അവന്ന് എന്താണുള്ളത്? നബി(സ) പറഞ്ഞു: "അവന് ഒന്നുമില്ല." ഇപ്രകാരം അദ്ദേഹം മൂന്ന് പ്രാവശ്യം ചോദ്യമാവർത്തിച്ചു. അപ്പോഴെല്ലാം നബി(സ) പറഞ്ഞു: "അവന് ഒന്നമില്ല." പിന്നീട് അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ തൃപ്തിയെ ആഗ്രഹിച്ചുകൊണ്ടുള്ളതും ആത്മാർത്ഥതയോടുകൂടെയുള്ളതും അല്ലാത്ത കർമ്മങ്ങൾ അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ന)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ غَزَا فِي سَبِيلِ اللَّهِ وَلَمْ يَنْوِ – وَفِي رِوَايَةٍ: وَهُوَ لَا يُرِيدُ – إِلَّا عِقَالًا فَلَهُ مَا نَوَى". (ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധംചെയ്തു. അവൻ ഒരു കയറല്ലാതെ മറ്റൊന്നും ആഗ്രഹിച്ചില്ല - മറ്റൊരു നിവേദനം: കരുതിയില്ല - എന്നാൽ അവന് താൻ കരുതിയതുണ്ട്." (ന)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=185), 1, 'وَفِي رِوَايَةٍ: وَهُوَ لَا يُرِيدُ – إِلَّا عِقَالًا فَلَهُ مَا نَوَى". (ن)', 'മറ്റൊരു നിവേദനം: കരുതിയില്ല - എന്നാൽ അവന് താൻ കരുതിയതുണ്ട്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُقَاتِلُ شَجَاعَةً، وَيُقَاتِلُ حَمِيَّةً، وَيُقَاتِلُ رِيَاءً؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ". (ق,د,ت,ن,جه)', 'അബൂമൂസ(റ): ധീരത കാണിക്കാൻ വേണ്ടിയും, ആത്മാഭിമാനത്തിന്ന് (തൻപോരിമക്ക്) വേണ്ടിയും, പ്രദർശിപ്പിക്കാൻ വേണ്ടിയും യുദ്ധംചെയ്യുന്ന ഒരാളെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒരാൾ അല്ലാഹുവിന്റെ വചനം ഉന്നതമാവാൻ വേണ്ടി യുദ്ധംചെയ്താൽ അത് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 920, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ أَبِي عُقْبَةَ رَضِيَ اللَّهُ عَنْهُ – وَكَانَ مَوْلًى لِأَهْلِ فَارِسَ – قَالَ: شَهِدْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، فَضَرَبْتُ رَجُلًا مِنَ الْمُشْرِكِينَ، فَقُلْتُ: خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْفَارِسِيُّ. فَبَلَغَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَا قُلْتَ: خُذْهَا وَأَنَا الْغُلَامُ الْأَنْصَارِيُّ". (د,جه)', 'അബൂഉഖ്ബ(റ): - അദ്ദേഹം പേർഷ്യക്കാരുടെ അടിമയായിരുന്നു - ഉഹ്ദ് യുദ്ധത്തിൽ നബി(സ)യുടെ കൂടെ ഞാൻ പങ്കെടുത്തു. അങ്ങനെ മുശ്രിക്കുകളിൽ ഒരാളെ ഞാൻ വെട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: അതിനെ (വെട്ട്) എന്നിൽ നിന്ന് പിടിക്കൂ. ഞാൻ ഒരു പേർഷ്യൻ അടിമയാണ്. ഇക്കാര്യം നബി(സ)യുടെ കാതിലെത്തിയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിനക്ക് ഇങ്ങനെ പറയാമായിരുന്നില്ലേ: എന്നിൽ നിന്ന് അത് പിടിക്കൂ, ഞാനൊരു അൻസാരി അടിമയാണ്." (ദ,ജ)', 'أَبِي عُقْبَةَ', 'അബൂഉഖ്ബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 921, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: حَدَّثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ أَرَادَ أَنْ يَغْزُوَ فَقَالَ: "يَا مَعْشَرَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، إِنَّ مِنْ إِخْوَانِكُمْ قَوْمًا لَيْسَ لَهُمْ مَالٌ وَلَا عَشِيرَةٌ، فَلْيَضُمَّ أَحَدُكُمْ إِلَيْهِ الرَّجُلَيْنِ أَوِ الثَّلَاثَةَ، فَمَا لِأَحَدِنَا مِنْ ظَهْرٍ يَحْمِلُهُ إِلَّا عُقْبَةٌ كَعُقْبَةِ" يَعْنِي: أَحَدِهِمْ، قَالَ: فَضَمَمْتُ إِلَيَّ اثْنَيْنِ أَوْ ثَلَاثَةً، قَالَ: مَا لِي إِلَّا عُقْبَةٌ كَعُقْبَةِ أَحَدِهِمْ مِنْ جَمَلِي. (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ)യെക്കുറിച്ച് അദ്ദേഹം പറഞ്ഞു: നബി(സ) യുദ്ധം ചെയ്യാനുദ്ദേശിച്ചു, അവിടുന്ന് പറഞ്ഞു: "മുഹാജിറുകളേ, അൻസാരികളേ, നിങ്ങളുടെ സഹോദരങ്ങളിൽ സ്വത്തും കുടുംബവുമില്ലാത്ത ഒരു സംഘമുണ്ട്. അതിനാൽ നിങ്ങൾ ഓരോരുത്തരും രണ്ടോ മൂന്നോ ആളുകളെ വീതം കൂടെക്കൂട്ടുക. നമ്മിലൊരാൾക്ക് ഒരു വാഹനത്തിൽ അതിലുള്ള ഊഴം മാത്രമാണുണ്ടാവുക." നിവേദകൻ പറയുന്നു: ഞാനെന്റെ കൂടെ രണ്ടോ മൂന്നോ ആളുകളെ ചേർത്തി. അദ്ദേഹം പറയുന്നു: എന്റെ ഒട്ടകത്തിന്മേൽ എനിക്കും അവരെപ്പോലെ ഒരു ഊഴം മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 921, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ، قَسَمَ مُرُوطًا بَيْنَ نِسَاءٍ مِنْ نِسَاءِ الْمَدِينَةِ فَبَقِيَ مِرْطٌ جَيِّدٌ، فَقَالَ لَهُ بَعْضُ مَنْ عِنْدَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَعْطِ هَذَا ابْنَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّتِي عِنْدَكَ – يُرِيدُونَ أُمَّ كُلْثُومٍ بِنْتَ عَلِيٍّ – فَقَالَ عُمَرُ: أُمُّ سَلِيطٍ أَحَقُّ، وَأُمُّ سَلِيطٍ مِنْ نِسَاءِ الْأَنْصَارِ مِمَّنْ بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ عُمَرُ: فَإِنَّهَا كَانَتْ تَزْفِرُ لَنَا الْقِرَبَ يَوْمَ أُحُدٍ. (خ)', 'ഉമർ(റ): മദീനയിലെ സ്ത്രീകൾക്ക് ഉമർ(റ) കുറെ വസ്ത്രങ്ങൾ വീതിച്ചുനൽകി. അതിൽ നല്ലൊരു വസ്ത്രം ബാക്കിയായി. അപ്പോൾ തന്റെ അടുത്തുള്ള ചിലർ ഉമർ(റ)വിനോട് പറഞ്ഞു: അമീറുൽ മുഅ്മിനീനേ, ഇത് അങ്ങയുടെ അടുത്തുള്ള റസൂൽ(സ)യുടെ മകൾക്ക് നൽകുക - ഉമ്മുകുൽസൂം ബിൻത് അലി(റ)യെയാണ് അവർ ഉദ്ദേശിച്ചത് - ഉമർ(റ) പറഞ്ഞു: ഇതിന് ഏറ്റവും യോഗ്യ ഉമ്മുസ്വലീത്വാണ്. ഉമ്മുസ്വലീത്(റ) റസൂൽ(സ)യോട് ഉടമ്പടിചെയ്ത അൻസാരി വനിതയാണ്. ഉമർ(റ) പറഞ്ഞു: ഉഹ്ദ് യുദ്ധദിവസം ഉമ്മുസലീത്(റ) ഞങ്ങൾക്ക് തോൽപാത്രങ്ങളിൽ വെള്ളം കൊണ്ടുവന്നുതന്നിരുന്നു. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 921, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنَّا نَغْزُو مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَسْقِي الْقَوْمَ وَنَخْدُمُهُمْ وَنَرُدُّ الْجَرْحَى وَالْقَتْلَى إِلَى الْمَدِينَةِ. (خ)', 'റുബയ്യിഅ് ബിൻതുമുഅവ്വിദ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം യുദ്ധത്തിൽ പങ്കെടുക്കാറുണ്ടായിരുന്നു. അങ്ങനെ ഞങ്ങൾ ജനങ്ങൾക്ക് വെള്ളം നൽകുകയും അവർക്ക് സേവനം ചെയ്യുകയും മുറിവേറ്റവരെയും കൊല്ലപ്പെട്ടവരെയും മദീനയിലേക്ക് കൊണ്ടുപോവുകയും ചെയ്യുമായിരുന്നു. (ബു)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ', 'റുബയ്യിഅ് ബിൻതുമുഅവ്വിദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ وَلَا تُسَافِرَنَّ امْرَأَةٌ إِلَّا وَمَعَهَا مَحْرَمٌ". فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، اكْتُتِبْتُ فِي غَزْوَةِ كَذَا وَكَذَا، وَخَرَجَتِ امْرَأَتِي حَاجَّةً، قَالَ: "اذْهَبْ فَحُجَّ مَعَ امْرَأَتِكَ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഒരാളും ഒരു സ്ത്രീയോടൊപ്പം ഒഴിഞ്ഞിരിക്കരുത്. ഒരു മഹ്റമിന്റെ (കെട്ടുബന്ധം നിഷിദ്ധമായവൻ) കൂടെയല്ലാതെ സ്ത്രീ യാത്രചെയ്യരുത്." അപ്പോൾ ഒരാൾ എഴുന്നേറ്റ് പറഞ്ഞു: റസൂലേ, ഞാൻ ഇന്നാലിന്ന യുദ്ധസംഘത്തിലേക്ക് നിയോഗിക്കപ്പെടുകയും എന്റെ ഭാര്യ ഹജ്ജിന് വേണ്ടി പുറപ്പെടുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ ഭാര്യയുടെ കൂടെ പോയി ഹജ്ജ് ചെയ്യുക." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُمَّ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهَا اتَّخَذَتْ يَوْمَ حُنَيْنٍ خِنْجَرًا، فَكَانَ مَعَهَا، فَرَآهَا أَبُو طَلْحَةَ، فَقَالَ: يَا رَسُولَ اللَّهِ هَذِهِ أُمُّ سُلَيْمٍ مَعَهَا خِنْجَرٌ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا هَذَا الْخِنْجَرُ". قَالَتِ: اتَّخَذْتُهُ إِنْ دَنَا مِنِّي أَحَدٌ مِنَ الْمُشْرِكِينَ بَقَرْتُ بِهِ بَطْنَهُ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضْحَكُ، قَالَتْ: يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا مِنَ الطُّلَقَاءِ انْهَزَمُوا بِكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أُمَّ سُلَيْمٍ، إِنَّ اللَّهَ [عَزَّ وَجَلَّ] قَدْ كَفَى وَأَحْسَنَ". (م)', 'അനസ്(റ): ഉമ്മുസുലൈം(റ) ഹുനൈൻ യുദ്ധദിവസം ഒരു കഠാരയെടുത്ത് കയ്യിൽ പിടിച്ചു. അപ്പോൾ അവരെ അബൂത്വൽഹ(റ) കണ്ടു. അബൂത്വൽഹ(റ) പറഞ്ഞു: റസൂലേ, ഉമ്മുസുലൈം(റ) കഠാര പിടിച്ച് നിൽക്കുന്നു. റസൂൽ(സ) ഉമ്മുസുലൈം(റ)യോട് ചോദിച്ചു: "എന്തിനാണീ കഠാര?" ഉമ്മുസുലൈം(റ) പറഞ്ഞു: ബഹുദൈവാരാധകരിൽനിന്ന് ആരെങ്കിലും എന്റെ നേർക്ക് അടുത്താൽ അവന്റെ ഉദരം പിളർത്തുവാൻ വേണ്ടിയാണ് ഞാനിതെടുത്തത്. അപ്പോൾ റസൂൽ(സ) പുഞ്ചിരിക്കാൻ തുടങ്ങി. ഉമ്മുസുലൈം(റ) പറഞ്ഞു: അങ്ങയിൽ നിന്ന് പിന്തിരിഞ്ഞോടിയ തുലഖാഇ(ഫത്ഹ്മക്കയുടെ ദിനം മുസ്ലിമായവർ)നെ അങ്ങ് വധിക്കുക. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഏറ്റവും നല്ല രീതിയിലും വേണ്ട വിധത്തിലും പ്രവർത്തിച്ചിരിക്കുന്നു." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'عَزَّ وَجَلَّ', null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ أُحُدٍ انْهَزَمَ نَاسٌ مِنَ النَّاسِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَبُو طَلْحَةَ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُجَوِّبٌ عَلَيْهِ بِحَجَفَةٍ، قَالَ: وَكَانَ أَبُو طَلْحَةَ رَجُلًا رَامِيًا شَدِيدَ النَّزْعِ، وَكَسَرَ يَوْمَئِذٍ قَوْسَيْنِ أَوْ ثَلَاثًا، قَالَ: فَكَانَ الرَّجُلُ يَمُرُّ مَعَهُ الْجَعْبَةُ مِنَ النَّبْلِ، فَيَقُولُ: "انْثُرْهَا لِأَبِي طَلْحَةَ". قَالَ: وَيُشْرِفُ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ إِلَى الْقَوْمِ، فَيَقُولُ أَبُو طَلْحَةَ: يَا نَبِيَّ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي لَا تُشْرِفْ، لَا يُصِبْكَ سَهْمٌ مِنْ سِهَامِ الْقَوْمِ، نَحْرِي دُونَ نَحْرِكَ. قَالَ: وَلَقَدْ رَأَيْتُ عَائِشَةَ بِنْتَ أَبِي بَكْرٍ وَأُمَّ سُلَيْمٍ – رَضِيَ اللَّهُ عَنْهُمَا – وَإِنَّهُمَا لَمُشَمِّرَتَانِ أَرَى خَدَمَ سُوقِهِمَا، تَنْقُلَانِ الْقِرَبَ عَلَى مُتُونِهِمَا، ثُمَّ تُفْرِغَانِهِ فِي أَفْوَاهِهِمْ، ثُمَّ تَرْجِعَانِ فَتَمْلَآنِهَا، ثُمَّ تَجِيئَانِ تُفْرِغَانِهِ فِي أَفْوَاهِ الْقَوْمِ، وَلَقَدْ وَقَعَ السَّيْفُ مِنْ يَدَيْ أَبِي طَلْحَةَ إِمَّا مَرَّتَيْنِ وَإِمَّا ثَلَاثًا مِنَ النُّعَاسِ. (م)', 'അനസുബ്നു മാലിക്(റ): ഉഹ്ദ് യുദ്ധദിവസം ജനങ്ങളിൽ ചിലർ നബി(സ)യിൽ നിന്ന് പിന്തിരിഞ്ഞോടി. അബൂത്വൽഹ(റ) തോലിനാലുള്ള ഒരു പടയങ്കി ധരിച്ചുകൊണ്ട് നബി(സ)യുടെ മുന്നിൽ നിൽക്കുകയായിരുന്നു. അനസ്(റ) പറഞ്ഞു: അബൂത്വൽഹ(റ) ശക്തനായ അമ്പെയ്ത്തുകാരനായിരുന്നു. ആ ദിവസം അബൂത്വൽഹ(റ) രണ്ടോ മൂന്നോ വില്ല് പൊട്ടിച്ചു. അനസ്(റ) പറഞ്ഞു: ആരെങ്കിലും ആവനാഴിയുമായി അബൂത്വൽഹ(റ)വിന്റെ അടുത്തുകൂടെ പോയാൽ നബി(സ) പറയും: "അവയെ നീ ത്വൽഹ(റ)ക്ക് കൊടുക്കുക." അനസ്(റ) പറഞ്ഞു: നബി(സ) ജനങ്ങളെ വീക്ഷിക്കാൻ വേണ്ടി എത്തിനോക്കുമായിരുന്നു. അപ്പോൾ അബൂത്വൽഹ(റ) പറയും: നബിയേ, എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് ദണ്ഡമാണ്, അങ്ങ് എത്തിനോക്കരുത്. ജനങ്ങളുടെ ഒരമ്പും അങ്ങേക്ക് ഏൽക്കരുത്. എന്റെ കഴുത്ത് അങ്ങയുടെ കഴുത്തിന് മുമ്പിലാണ് (എന്റെ ആത്മാവ് അങ്ങേക്ക് ദണ്ഡമാണ്). അനസ്(റ) പറയുന്നു: ആഇശ ബിൻത് അബീബക്കർ(റ)യെയും ഉമ്മുസുലൈം(റ)യെയും ആ ദിവസം ഞാൻ കണ്ടു. ഇരുവരുടെയും കാലിലെ പാദസരങ്ങൾ കാണുംവിധം ഇരുവരും തയ്യാറെടുത്തിരുന്നു. അവർ തങ്ങളുടെ പുറത്ത് തോൽപാത്രങ്ങൾ ചുമന്ന് കൊണ്ടുവരികയും അത് ജനങ്ങളുടെ വായിലൊഴിച്ചു കൊടുക്കുകയും വീണ്ടും മടങ്ങി തോൽപാത്രങ്ങൾ നിറക്കുകയും വീണ്ടും വന്ന് ജനങ്ങളുടെ വായിൽ അത് ഒഴിച്ചുകൊടുക്കുകയും ചെയ്യുന്നുണ്ടായിരുന്നു. തൂങ്ങിയുറങ്ങിയത് കാരണത്താൽ രണ്ടോ മൂന്നോ പ്രാവശ്യം അബൂത്വൽഹ(റ)യുടെ കയ്യിൽ നിന്ന് വാൾ വീണിട്ടുണ്ട്. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 922, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أُمِّ عَطِيَّةَ الْأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعَ غَزَوَاتٍ، أَخْلُفُهُمْ فِي رِحَالِهِمْ، فَأَصْنَعُ لَهُمُ الطَّعَامَ، وَأُدَاوِي الْجَرْحَى، وَأَقُومُ عَلَى الْمَرْضَى. (م,جه)', 'ഉമ്മുഅതിയ്യത്തുൽ അൻസാരിയ്യ(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെ ഏഴ് പ്രാവശ്യം യുദ്ധംചെയ്തു. ഞാൻ അവരുടെ ഒട്ടകക്കട്ടിലുകൾക്കടുത്ത് നിന്നുകൊണ്ട് അവർക്ക് ഭക്ഷണം തയ്യാറാക്കുകയും മുറിവേറ്റവരെ ചികിത്സിക്കുകയും രോഗികളെ പരിചരിക്കുകയും ചെയ്യുമായിരുന്നു. (മു,ജ)', 'أُمِّ عَطِيَّةَ الْأَنْصَارِيَّةِ', 'ഉമ്മുഅതിയ്യത്തുൽ അൻസാരിയ്യ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 923, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْزُو بِأُمِّ سُلَيْمٍ وَنِسْوَةٍ مِنَ الْأَنْصَارِ، لِيَسْقِينَ الْمَاءَ وَيُدَاوِينَ الْجَرْحَى. (م,د,ت,ن)', 'അനസ്(റ): വെള്ളം കൊണ്ടുവരാനും മുറിവേറ്റവരെ ചികിത്സിക്കാനും വേണ്ടി ഉമ്മുസുലൈം(റ)യെയും അൻസാരികളിലെ ചില സ്ത്രീകളെയും റസൂൽ(സ) യുദ്ധത്തിന് കൊണ്ടുപോകാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 923, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُرْمَةُ نِسَاءِ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ كَحُرْمَةِ أُمَّهَاتِهِمْ، وَإِذَا خَلَفَهُ فِي أَهْلِهِ فَخَانَهُ قِيلَ لَهُ يَوْمَ الْقِيَامَةِ: هَذَا خَانَكَ فِي أَهْلِكَ، فَخُذْ مِنْ حَسَنَاتِهِ مَا شِئْتَ، فَمَا ظَنُّكُمْ". وَفِي رِوَايَةٍ: حُرْمَةُ نِسَاءِ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ فِي الْحُرْمَةِ كَأُمَّهَاتِهِمْ، وَمَا مِنْ رَجُلٍ مِنَ الْقَاعِدِينَ يَخْلُفُ رَجُلًا مِنَ الْمُجَاهِدِينَ فِي أَهْلِهِ إِلَّا نُصِبَ لَهُ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: يَا فُلَانُ، هَذَا فُلَانٌ، فَخُذْ مِنْ حَسَنَاتِهِ مَا شِئْتَ". ثُمَّ الْتَفَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَصْحَابِهِ فَقَالَ: "مَا ظَنُّكُمْ؟ تَرَوْنَ يَدَعُ لَهُ مِنْ حَسَنَاتِهِ شَيْئًا". (م,د,ن)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധത്തിന് പോകാത്തവരെ സംബന്ധത്തിച്ചിടത്തോളം, യുദ്ധത്തിന് പോയവരുടെ ഭാര്യമാർക്കുള്ള പവിത്രത അവരുടെ ഉമ്മമാർക്കുള്ള പവിത്രത പോലെയാണ്. യുദ്ധത്തിന് പോകാത്തവൻ യോദ്ധാവിന്റെ കുടുംബത്തെ ഏറ്റെടുത്ത് വഞ്ചിച്ചാൽ അന്ത്യനാളിൽ ആ യോദ്ധാവിനോട് ഇപ്രകാരം പറയപ്പെടും: ഇവൻ നിന്റെ കുടുംബകാര്യത്തിൽ നിന്നെ വഞ്ചിച്ചിരിക്കുന്നു. അതുകൊണ്ട് അവന്റെ നന്മകളിൽ നിന്ന് നിനക്കിഷ്ടമുള്ളത് നീ സ്വീകരിക്കുക. അതുകണ്ട് നിങ്ങൾ എന്താണ് വിചാരിക്കുന്നത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=196), 1, 'وَفِي رِوَايَةٍ: حُرْمَةُ نِسَاءِ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ فِي الْحُرْمَةِ كَأُمَّهَاتِهِمْ، وَمَا مِنْ رَجُلٍ مِنَ الْقَاعِدِينَ يَخْلُفُ رَجُلًا مِنَ الْمُجَاهِدِينَ فِي أَهْلِهِ إِلَّا نُصِبَ لَهُ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: يَا فُلَانُ، هَذَا فُلَانٌ، فَخُذْ مِنْ حَسَنَاتِهِ مَا شِئْتَ". ثُمَّ الْتَفَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَصْحَابِهِ فَقَالَ: "مَا ظَنُّكُمْ؟ تَرَوْنَ يَدَعُ لَهُ مِنْ حَسَنَاتِهِ شَيْئًا". (م,د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "യുദ്ധത്തിന് പോകാത്തവരെ സംബന്ധിച്ചിടത്തോളം യുദ്ധത്തിന് പോയവരുടെ ഭാര്യമാർക്കുള്ള പവിത്രത അവരുടെ ഉമ്മമാരുടെ പവിത്രത പോലെയാണ്. യുദ്ധത്തിനു പോകാത്ത ഒരാൾ ഒരു യോദ്ധാവിന്റെ കുടുംബത്തെ ഏറ്റെടുത്ത് (അവനെ വഞ്ചിച്ചാൽ) അന്ത്യനാളിൽ ആ യോദ്ധാവിന് വേണ്ടി അവൻ നിർത്തപ്പെടും. എന്നിട്ട് ഇപ്രകാരം പറയപ്പെടും: മനുഷ്യാ, ഇദ്ദേഹം ഇന്നവനാണ്. അതുകൊണ്ട് ഇവന്റെ നന്മകളിൽ നിന്ന് നിനക്കഷിടമുള്ളത് സ്വീകരിക്കുക. ശേഷം നബി(സ) സ്വഹാബികളിലേക്ക് തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "നിങ്ങളുടെ വിചാരമെന്താണ്, അവൻ മറ്റവന്റെ വല്ല നന്മയെയും ഒഴിവാക്കുമോ." (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَنَسٍ عَنْ أَبِي طَلْحَةَ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا غَلَبَ عَلَى قَوْمٍ أَقَامَ بِالْعَرْصَةِ ثَلَاثًا. وَفِي رِوَايَةٍ: إِذَا غَلَبَ قَوْمًا أَحَبَّ أَنْ يُقِيمَ بِعَرْصَتِهِمْ ثَلَاثًا. (ق,د,ت,ن,جه)', 'അബൂത്വൽഹ(റ)വിൽനിന്ന് അനസ്(റ): റസൂൽ(സ) ഒരു സമൂഹത്തെ കീഴടക്കിയാൽ അവരുടെ മൈദാനിയിൽ മൂന്ന് ദിവസം തങ്ങുമായിരുന്നു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) ഒരു സമൂഹത്തെ കീഴടക്കിയാൽ മൂന്ന് ദിവസം അവരുടെ മൈദാനിയിൽ നിൽക്കാൻ ആഗ്രഹിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ عَنْ أَبِي طَلْحَةَ', 'അബൂത്വൽഹ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 924, 924, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=197), 1, 'وَفِي رِوَايَةٍ: إِذَا غَلَبَ قَوْمًا أَحَبَّ أَنْ يُقِيمَ بِعَرْصَتِهِمْ ثَلَاثًا. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) ഒരു സമൂഹത്തെ കീഴടക്കിയാൽ മൂന്ന് ദിവസം അവരുടെ മൈദാനിയിൽ നിൽക്കാൻ ആഗ്രഹിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ فَرَّقَ بَيْنَ جَارِيَةٍ وَوَلَدِهَا، فَنَهَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، وَرَدَّ الْبَيْعَ. (د)', 'അലി(റ): അവർ ഒരു അടിമസ്ത്രീയെയും അവളുടെ കുട്ടിയെയും വേർപിരിച്ചു. നബി(സ) അതിനെത്തൊട്ട് അലി(റ)വിനെ വിലക്കി. കച്ചവടം മുടക്കുകയും ചെയ്തു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 924, 924, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ فَرَّقَ بَيْنَ وَالِدَةٍ وَوَلَدِهَا فَرَّقَ اللَّهُ بَيْنَهُ وَبَيْنَ أَحِبَّتِهِ يَوْمَ الْقِيَامَةِ". حَسَنٌ. (ت)', 'അബൂഅയ്യൂബ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും ഒരു മതാവിനെയും കുട്ടിയെയും വേർപിരിച്ചാൽ അവനെയും അവന്റെ സ്നേഹിതന്മാരെയും അല്ലാഹു അന്ത്യനാളിൽ വേർപിരിക്കും." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 924, 925, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ أَبِي بَكْرٍ – وَأَمَّرَهُ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فَغَزَوْنَا فَزَارَةَ، فَشَنَنَّا الْغَارَةَ، ثُمَّ نَظَرْتُ إِلَى عُنُقٍ مِنَ النَّاسِ فِيهِ الذُّرِّيَّةُ وَالنِّسَاءُ، فَرَمَيْتُ بِسَهْمٍ، فَوَقَعَ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ فَقَامُوا، فَجِئْتُ بِهِمْ إِلَى أَبِي بَكْرٍ، فِيهِمُ امْرَأَةٌ مِنْ فَزَارَةَ، وَعَلَيْهَا قِشْعٌ مِنْ أَدَمٍ، مَعَهَا بِنْتٌ لَهَا مِنْ أَحْسَنِ الْعَرَبِ، فَنَفَّلَنِي أَبُو بَكْرٍ ابْنَتَهَا، فَقَدِمْتُ الْمَدِينَةَ، فَلَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: "يَا سَلَمَةُ، هَبْ لِيَ الْمَرْأَةَ". فَقُلْتُ: وَاللَّهِ لَقَدْ أَعْجَبَتْنِي، وَمَا كَشَفْتُ لَهَا ثَوْبًا. فَسَكَتَ، حَتَّى إِذَا كَانَ مِنَ الْغَدِ لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السُّوقِ، فَقَالَ: "يَا سَلَمَةُ، هَبْ لِيَ الْمَرْأَةَ لِلَّهِ أَبُوكَ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، وَاللَّهِ مَا كَشَفْتُ لَهَا ثَوْبًا، وَهِيَ لَكَ. فَبَعَثَ بِهَا إِلَى أَهْلِ مَكَّةَ وَفِي أَيْدِيهِمْ أَسْرَى، فَفَادَاهُمْ بِتِلْكَ الْمَرْأَةِ. (م,د)', 'സലമ(റ): ഞങ്ങൾ അബൂബക്കർ(റ)വിന്റെ കൂടെ പുറപ്പെട്ട് ഫസാറ ഗോത്രത്തോട് യുദ്ധം ചെയ്തു - അബൂബക്കർ(റ)വിനെ റസൂൽ(സ) ഞങ്ങളുടെ നേതാവാക്കിയിരുന്നു - അങ്ങനെ ഞങ്ങൾ ഫസാറക്കാരെ കടന്നാക്രമിച്ചു. ശേഷം സ്ത്രീകളും കുട്ടികളുമടങ്ങുന്ന ഒരു കൂട്ടമാളുകളെ ഞാൻ കണ്ടു. ഞാൻ ഒരു അമ്പെയ്തു. അത് അവരുടെയും ഒരു മലയുടെയും ഇടയിൽ പതിച്ചു. അപ്പോൾ അവർ അവിടെ നിന്നു. ഞാൻ അവരെ അബൂബക്കർ(റ)വിലേക്ക് കൊണ്ടുവന്നു. അവരിൽ നേർത്ത തോലിന്റെ വസ്ത്രമണിഞ്ഞ ഫസാറക്കാരിയായ ഒരു സ്ത്രീയുണ്ടായിരുന്നു. അവളുടെ കൂടെ അറബികളിൽ ഏറ്റവും സൗന്ദര്യവതിയായ അവളുടെ മകളുമുണ്ടായിരുന്നു. അബൂബക്കർ(റ) അവളുടെ മകളെ എനിക്ക് നൽകി. അങ്ങനെ ഞാൻ മദീനയിൽ വന്നു. റസൂൽ(സ) എന്നെ കണ്ടുമുട്ടി. അവിടന്ന് എന്നോട് പറഞ്ഞു: "സലമാ, ആ സ്ത്രീയെ എനിക്ക് നൽകുക." ഞാൻ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അവളെ എനിക്ക് ഇഷ്ടമാണ്. ഞാൻ അവളുടെ വസ്ത്രമൂരിയിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) മിണ്ടാതിരുന്നു. പിറ്റെ ദിവസം അങ്ങാടിയിൽ വെച്ച് റസൂൽ(സ) എന്നെ കണ്ടുമുട്ടി. റസൂൽ(സ) പറഞ്ഞു: "സലമ, ആ സ്ത്രീയെ എനിക്ക് നൽകുക. നിന്റെ പിതാവ് അല്ലാഹുവിന് ദണ്ഡമാണ്." ഞാൻ പറഞ്ഞു: റസൂലേ, അല്ലാഹു തന്നെ സത്യം, ഞാനവളുടെ വസ്ത്രം ഊരിയിട്ടില്ല. അവൾ അങ്ങേക്കുള്ളതാണ്. അങ്ങനെ റൂസൽ(സ) അവളെ മക്കക്കാരിലേക്ക് കൊടുത്തയച്ചു. അവരുടെ കയ്യിൽ ബന്ധികളുണ്ടായിരുന്നു. അവർക്ക് മോചനദ്രവ്യമായി റസൂൽ(സ) ആ സ്ത്രീയെ നൽകി. (മു,ദ)', 'سَلَمَةَ', 'സലമ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 925, 925, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّاسُ إِذَا نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْزِلًا، تَفَرَّقُوا فِي الشِّعَابِ وَالْأَوْدِيَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ تَفَرُّقَكُمْ فِي هَذِهِ الشِّعَابِ وَالْأَوْدِيَةِ إِنَّمَا ذَلِكُمْ مِنَ الشَّيْطَانِ". فَلَمْ يَنْزِلْ بَعْدَ ذَلِكَ مَنْزِلًا إِلَّا انْضَمَّ بَعْضُهُمْ إِلَى بَعْضٍ، حَتَّى يُقَالَ: لَوْ بُسِطَ عَلَيْهِمْ ثَوْبٌ لَعَمَّهُمْ. (د)', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ): റസൂൽ(സ) ഒരു സ്ഥലത്ത് തമ്പടിച്ചാൽ ജനങ്ങൾ പലമലഞെരുവുകളിലും ഭാഗങ്ങളിലുമായി ചിന്നിച്ചിതറുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ മലഞെരുവുകളിലും മലയോരങ്ങളിലുമായി നിങ്ങൾ ചിന്നിച്ചിതറുന്നത് പിശാചിന്റെ ഭാഗത്തുനിന്നുള്ള കാര്യമാണ്." അതിനുശേഷം റസൂൽ(സ) വല്ല സ്ഥലത്തും തമ്പടിച്ചാൽ ജനങ്ങൾ ഒരു സ്ഥലത്തുതന്നെ ഒരുമിക്കുമായിരുന്നു. എത്രത്തോളമെന്നാൽ ഒരു വസ്ത്രം വിരിച്ചാൽ അവർ മുഴുവൻ മൂടപ്പെടുമെന്ന് പറയാം. (ദ)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 925, 926, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْتُ مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ كَذَا وَكَذَا، فَضَيَّقَ النَّاسُ الْمَنَازِلَ، وَقَطَعُوا الطَّرِيقَ، فَبَعَثَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنَادِيًا يُنَادِي فِي النَّاسِ: "أَنَّ مَنْ ضَيَّقَ مَنْزِلًا أَوْ قَطَعَ طَرِيقًا فَلَا جِهَادَ لَهُ". (د)', 'മുആദുബ്നു അനസുൽജുഹനി(റ): ഞാൻ റസൂൽ(സ)യോടൊപ്പം ഇന്നാലിന്ന യുദ്ധങ്ങളിലൊക്കെ പങ്കെടുത്തു. അങ്ങനെ ജനങ്ങൾ കൂടുതൽ സ്ഥലം കയ്യേറുകയും കവർച്ച നടത്തുകയും ചെയ്തു. അപ്പോൾ ജനങ്ങൾക്കിടയിൽ ഇപ്രകാരം വിളിച്ചുപറയാൻ റസൂൽ(സ) ഒരാളെ നിയോഗിച്ചു: "ആരെങ്കിലും സ്ഥലം കയ്യേറുകയും കവർച്ച നടത്തുകയും ചെയ്യുന്നുവെങ്കിൽ അവന് ധർമ്മസമരമില്ല." (ദ)', 'مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ', 'മുആദുബ്നു അനസുൽജുഹനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 926, 926, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الرَّجَّالَةِ يَوْمَ أُحُدٍ، وَكَانُوا خَمْسِينَ رَجُلًا، عَبْدَاللَّهِ بْنَ جُبَيْرٍ فَقَالَ: "إِنْ رَأَيْتُمُونَا تَخْطَفُنَا الطَّيْرُ فَلَا تَبْرَحُوا مَكَانَكُمْ هَذَا حَتَّى أُرْسِلَ إِلَيْكُمْ، وَإِنْ رَأَيْتُمُونَا هَزَمْنَا الْقَوْمَ وَأَوْطَأْنَاهُمْ فَلَا تَبْرَحُوا حَتَّى أُرْسِلَ إِلَيْكُمْ". فَهَزَمُوهُمْ، قَالَ: فَأَنَا وَاللَّهِ رَأَيْتُ النِّسَاءَ يَشْتَدِدْنَ قَدْ بَدَتْ خَلَاخِلُهُنَّ وَأَسْوُقُهُنَّ رَافِعَاتٍ ثِيَابَهُنَّ، فَقَالَ أَصْحَابُ عَبْدِاللَّهِ بْنِ جُبَيْرٍ: الْغَنِيمَةَ أَيْ قَوْمِ الْغَنِيمَةَ، ظَهَرَ أَصْحَابُكُمْ فَمَا تَنْتَظِرُونَ، فَقَالَ عَبْدُاللَّهِ بْنُ جُبَيْرٍ: أَنَسِيتُمْ مَا قَالَ لَكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالُوا: وَاللَّهِ لَنَأْتِيَنَّ النَّاسَ، فَلَنُصِيبَنَّ مِنَ الْغَنِيمَةِ، فَلَمَّا أَتَوْهُمْ صُرِفَتْ وُجُوهُهُمْ فَأَقْبَلُوا مُنْهَزِمِينَ، فَذَاكَ إِذْ يَدْعُوهُمُ الرَّسُولُ فِي أُخْرَاهُمْ، فَلَمْ يَبْقَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَيْرُ اثْنَيْ عَشَرَ رَجُلًا، فَأَصَابُوا مِنَّا سَبْعِينَ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ أَصَابُوا مِنَ الْمُشْرِكِينَ يَوْمَ بَدْرٍ أَرْبَعِينَ وَمِائَةً، سَبْعِينَ أَسِيرًا، وَسَبْعِينَ قَتِيلًا، فَقَالَ أَبُو سُفْيَانَ: أَفِي الْقَوْمِ مُحَمَّدٌ؟ ثَلَاثَ مَرَّاتٍ، فَنَهَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجِيبُوهُ، ثُمَّ قَالَ: أَفِي الْقَوْمِ ابْنُ أَبِي قُحَافَةَ؟ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: أَفِي الْقَوْمِ ابْنُ الْخَطَّابِ؟ ثَلَاثَ مَرَّاتٍ، ثُمَّ رَجَعَ إِلَى أَصْحَابِهِ، فَقَالَ: أَمَّا هَؤُلَاءِ فَقَدْ قُتِلُوا، فَمَا مَلَكَ عُمَرُ نَفْسَهُ، فَقَالَ: كَذَبْتَ وَاللَّهِ يَا عَدُوَّ اللَّهِ، إِنَّ الَّذِينَ عَدَدْتَ لَأَحْيَاءٌ كُلُّهُمْ، وَقَدْ بَقِيَ لَكَ مَا يَسُوءُكَ، قَالَ: يَوْمٌ بِيَوْمِ بَدْرٍ، وَالْحَرْبُ سِجَالٌ إِنَّكُمْ سَتَجِدُونَ فِي الْقَوْمِ مُثْلَةً لَمْ آمُرْ بِهَا وَلَمْ تَسُؤْنِي، ثُمَّ أَخَذَ يَرْتَجِزُ، أُعْلُ هُبَلْ، أُعْلُ هُبَلْ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا تُجِيبُوا لَهُ؟" قَالُوا: يَا رَسُولَ اللَّهِ مَا نَقُولُ؟ قَالَ: قُولُوا: "اللَّهُ أَعْلَى وَأَجَلُّ". قَالَ: إِنَّ لَنَا الْعُزَّى وَلَا عُزَّى لَكُمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا تُجِيبُوا لَهُ؟" قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ مَا نَقُولُ؟ قَالَ: "قُولُوا: اللَّهُ مَوْلَانَا وَلَا مَوْلَى لَكُمْ". (خ,د)', 'ബറാഉബ്നു ആസിബ്(റ): ഉഹ്ദ് ദിവസം നബി(സ) കാലാൾപ്പടയുടെ നേതൃത്വം അബ്ദുല്ലാഹിബ്നു ജുബൈർ(റ)വിന് നൽകി. അവർ അമ്പത് പേരായിരുന്നു. നബി(സ) പറഞ്ഞു: "ഞങ്ങളെ പക്ഷികൾ കൊത്തിക്കൊണ്ടുപോകുന്നത് കണ്ടാലും ഞാൻ നിങ്ങൾക്ക് വിവരമറിയിക്കുംവരെ നിങ്ങൾ ആ സ്ഥാനം വിട്ടുപോകരുത്. ഞങ്ങൾ ശത്രുക്കളെ പരാജയപ്പെടുത്തി അവരുടെ ശരീരങ്ങളിൽ ചവിട്ടി നടക്കുന്നത് കണ്ടാൽ പോലും ഞാൻ ആളെ അയക്കുംവരെ നിങ്ങൾ ആ സ്ഥാനത്തു നിന്നിളകരുത്." അങ്ങനെ മുസ്ലിംകൾ ശത്രുക്കളെ തുരത്തി. അല്ലാഹുവാണ് സത്യം, (ശത്രുക്കളിലെ) സ്ത്രീകൾ വസ്ത്രങ്ങൾ പൊക്കിപ്പിടിച്ച് കണങ്കാലുകളും പാദസരങ്ങളും പുറത്തുകാണും വിധം ധൃതിപിടിച്ചോടുന്നത് ഞാൻ കണ്ടു. അന്നേരം ഇബ്നുജുബൈർ(റ)വിന്റെ ആളുകൾ ഇപ്രകാരം പറയാൻ തുടങ്ങി. ''ഗനീമത്, ജനങ്ങളേ ഇതാ ഗനീമത്. നിങ്ങളുടെ കൂട്ടുകാർ വിജയം കൈവരിച്ചുകഴിഞ്ഞു, ഇനിയും എന്താണ് നിങ്ങൾ കാത്തിരിക്കുന്നത്? ഇബ്നു ജുബൈർ(റ) അവരോട് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് പറഞ്ഞതെല്ലാം നിങ്ങൾ മറന്നുവോ? അവർ പറഞ്ഞു: ഞങ്ങൾ അവരുടെ അടുത്ത് ചെന്ന് ഗനീമത് കരസ്ഥമാക്കുക തന്നെ ചെയ്യും. അവർ അങ്ങോട്ട് പോയപ്പോൾ ഓടിപ്പോയ ശത്രുക്കൾ പെട്ടെന്ന് തിരിച്ചുവന്നു. ''റസൂൽ(സ) പിന്നിൽ നിന്ന് വിളിച്ച് കൊണ്ടിരുന്നു''വെന്ന ഖുർആനിക സൂക്തത്തിന്റെ സന്ദർഭമതായിരുന്നു. അവസാനം പന്ത്രണ്ട് പേർ മാത്രമാണ് നബി(സ)യുടെ കൂടെ അവശേഷിച്ചത്. ശത്രുക്കൾ ഞങ്ങളിൽ നിന്ന് എഴുപത് പേരെ വധിച്ചു. ബദർ യുദ്ധ ദിവസം നബി(സ)യും അനുചരരും ബഹുദൈവാരാധകരിലെ നൂറ്റി നാൽപ്പത് പേർക്ക് അപകടം വരുത്തിയിരുന്നു. എഴുപത് പേരെ വധിച്ചു, എഴുപത് പേരെ ബന്ധനസ്ഥരാക്കി. അവസാനം അബൂസുഫ്യാൻ മൂന്ന് പ്രാവശ്യം ഇപ്രകാരം വിളിച്ചുപറഞ്ഞു. അക്കൂട്ടത്തിൽ മുഹമ്മദ് ഉണ്ടോ? പക്ഷേ, അതിനു മറുപടി നൽകാൻ റസൂൽ(സ) അനുവാദം നൽകിയില്ല. ശേഷം അക്കൂട്ടത്തിൽ അബൂഖുഹാഫയുടെ മകനുണ്ടോ? എന്നും മൂന്ന് പ്രാവശ്യം വിളിച്ച് ചോദിച്ചു. അതിനുശേഷം അക്കൂട്ടത്തിൽ ഖത്താബിന്റെ മകനുണ്ടോ? എന്നും മൂന്ന് പ്രാവശ്യം വിളിച്ചു ചോദിച്ചു. അനന്തരം തന്റെ അനുചരരുടെ അടുത്ത് പോയി അയാൾ ഇപ്രകാരം പറഞ്ഞു: ''ഇതാ, ഇവരെല്ലാവരും കൊല്ലപ്പെട്ടു കഴിഞ്ഞു.'' അതുകേട്ട് ഉമർ(റ)വിന് തന്റെ മനസ്സിനെ നിയന്ത്രിക്കാൻ കഴിഞ്ഞില്ല. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ശത്രുവേ, നീ പറഞ്ഞതെല്ലാം കളവാണ്. നീ എണ്ണിപ്പറഞ്ഞവരെല്ലാം ജീവിച്ചിരിപ്പുണ്ട്. നിന്നെ ബുദ്ധിമുട്ടാക്കുന്ന കാര്യങ്ങൾ ഇനിയും അവശേഷിച്ചിരിപ്പുണ്ട്. അബൂസുഫ്യാൻ പറഞ്ഞു: ഈ ദിനം ബദ്റിനുള്ള പ്രതികാരമാണ്, യുദ്ധത്തിൽ ജയപരാജയങ്ങളുണ്ടാവും. ജനങ്ങളിൽ ചിലർ അംഗഛേദം നടത്തപ്പെട്ടതായി നിങ്ങൾ കാണും. അത് ഞാൻ കൽപിച്ചതല്ല, അതിൽ എനിക്ക് ദുഃഖവുമില്ല. ശേഷം ഹുബലിന്റെ കക്ഷി ഉയർന്നു നിൽക്കട്ടെ, ഹുബലിന്റെ കക്ഷി ഉയർന്നു നിൽക്കട്ടെ എന്ന് പറഞ്ഞുകൊണ്ട് അബൂസുഫ്യാൻ ആഹ്ലാദിക്കാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങളവന് ഉത്തരം നൽകുന്നില്ലെയോ?" അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ എന്താണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് പരമോന്നതനും ഏറ്റവും പ്രതാപമുള്ളവനും എന്ന് നിങ്ങൾ പറയുക." അപ്പോൾ അബൂസുഫ്യാൻ പറഞ്ഞു: ഞങ്ങൾക്ക് ഉസ്സാ(ഒരു ദൈവത്തിന്റെ പേര്)യുണ്ട്, നിങ്ങൾക്ക് ഉസ്സായില്ല. ഇത് കേട്ടു റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ അവന് ഉത്തരം നൽകുന്നില്ലെയോ?" അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ എന്താണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഞങ്ങളുടെ സംരക്ഷകനാണ്, നിങ്ങൾക്ക് സംരക്ഷകനില്ല എന്ന് നിങ്ങൾ പറയുക." (ബു,ദ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 926, 927, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقَدْ أَتَانِي الْيَوْمَ رَجُلٌ فَسَأَلَنِي عَنْ أَمْرٍ مَا دَرَيْتُ مَا أَرُدُّ عَلَيْهِ، فَقَالَ: أَرَأَيْتَ رَجُلًا مُؤْدِيًا نَشِيطًا يَخْرُجُ مَعَ أُمَرَائِنَا فِي الْمَغَازِي، فَيَعْزِمُ عَلَيْنَا فِي أَشْيَاءَ لَا نُحْصِيهَا، فَقُلْتُ لَهُ: وَاللَّهِ مَا أَدْرِي مَا أَقُولُ لَكَ، إِلَّا أَنَّا كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَسَى أَنْ لَا يَعْزِمَ عَلَيْنَا فِي أَمْرٍ إِلَّا مَرَّةً حَتَّى نَفْعَلَهُ، وَإِنَّ أَحَدَكُمْ لَنْ يَزَالَ بِخَيْرٍ مَا اتَّقَى اللَّهَ، وَإِذَا شَكَّ فِي نَفْسِهِ شَيْءٌ سَأَلَ رَجُلًا فَشَفَاهُ مِنْهُ، وَأَوْشَكَ أَنْ لَا تَجِدُوهُ، وَالَّذِي لَا إِلَهَ إِلَّا هُوَ مَا أَذْكُرُ مَا غَبَرَ مِنَ الدُّنْيَا إِلَّا كَالثَّغْبِ، شُرِبَ صَفْوُهُ، وَبَقِيَ كَدَرُهُ. (خ)', 'അബദുല്ല(റ): ഇന്ന് ഒരാൾ എന്റെ അടുത്ത് വന്ന് ഒരു കാര്യത്തെക്കുറിച്ച് ചോദിച്ചു, എന്താണ് മറുപടി പറയേണ്ടതെന്ന് എനിക്ക് പിടികിട്ടിയില്ല. അദ്ദേഹം ഇപ്രകാരമാണ് പറഞ്ഞത്: ശക്തനും ഉന്മേഷവാനുമായ ഒരു വ്യക്തി ഞങ്ങളുടെ നേതാക്കൻമാർക്കൊപ്പം പുറപ്പെടുകയും ഞങ്ങളുടെ കഴിവിൽ കവിഞ്ഞ കാര്യങ്ങൾ ചെയ്യാൻ അദ്ദേഹം കൽപിക്കുകയും ചെയ്യുന്നു. അതിനെക്കുറിച്ച് അങ്ങയുടെ അഭിപ്രായമെന്താണ്? ഞാൻ അദ്ദേഹത്തോട് പറഞ്ഞു: എന്താണ് നിന്നോട് പറയേണ്ടതെന്ന് എനിക്കറിയില്ല, പക്ഷേ, ഞങ്ങൾ നബി(സ)യുടെ കൂടെയായിരിക്കുമ്പോൾ ഒരു പ്രാവശ്യത്തിൽ കൂടുതൽ പ്രാവശ്യം ഞങ്ങളോട് അവിടന്ന് കൽപിക്കാറുണ്ടായിരുന്നില്ല. അപ്പോൾതന്നെ ഞങ്ങൾ അത് നിർവ്വഹിച്ചിട്ടുണ്ടാകും. അല്ലാഹുവിനെ സൂക്ഷിച്ച് കഴിയുന്ന കാലത്തോലം നിങ്ങളെല്ലാവരും നന്മയിലായിരിക്കും. വല്ല സംശയവും മനസ്സിൽ തോന്നുന്ന പക്ഷം മറ്റൊരുത്തനോട് ചോദിച്ച് അത് ദൂരീകരിച്ച് കൊള്ളട്ടെ. പക്ഷേ, അത്തരം ഒരാളെ നിങ്ങൾക്ക് ലഭിക്കാത്ത കാലം ഇതാ അടുത്ത് കഴിഞ്ഞിരിക്കുന്നു. താനല്ലാതെ ഒരു ആരാധ്യനില്ലാത്ത അല്ലാഹുതന്നെ സത്യം, തെളിഞ്ഞവെള്ളം മുഴുവൻ കുടിക്കപ്പെട്ട് കലങ്ങിയ വെള്ളം മാത്രം അവശേഷിച്ച ഒരു ഉറവ പോലെയല്ലാതെ ഈ ലോകത്തിന്റെ സഞ്ചാരത്തെ ഞാൻ കാണുന്നില്ല. (നല്ലവർ പോയിക്കഴിഞ്ഞു, അവശേഷിച്ചവർ യോഗ്യരല്ല). (ബു)', 'عَبْدِاللَّهِ', 'അബദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 927, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ أَبِي مُسَى رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَهُ وَمُعَاذًا إِلَى الْيَمَنِ فَقَالَ: "يَسِّرَا وَلَا تُعَسِّرَا، وَبَشِّرَا وَلَا تُنَفِّرَا، وَتَطَاوَعَا وَلَا تَخْتَلِفَا". (م)', 'അബൂമൂസ(റ): നബി(സ) അബൂമൂസ(റ)വിനെയും മുആദ്(റ)വിനെയും യമനിലേക്കയച്ചു, എന്നിട്ട് പറഞ്ഞു: "നിങ്ങൾ (കാര്യങ്ങളെ) എളുപ്പമാക്കിക്കൊടുക്കുക, പ്രയാസകരമാക്കരുത്. (ജനങ്ങൾക്ക്) സന്തോഷവാർത്ത നൽകുക, വെറുപ്പിക്കരുത്. നിങ്ങൾ അനുസരണയുള്ളവരാകുക, അഭിപ്രായവ്യത്യാസമുള്ളവരാകരുത്." (മു)', 'أَبِي مُسَى', 'അബൂമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 928, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ بُرَيْدَةَ وَالنُّعْمَانِ بْنِ مُقَرِّنٍ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمَّرَ رَجُلًا عَلَى سَرِيَّةٍ أَوْصَاهُ فِي خَاصَّةِ نَفْسِهِ بِتَقْوَى اللَّهِ، وَمَنْ مَعَهُ مِنَ الْمُسْلِمِينَ خَيْرًا، فَقَالَ: "اغْزُوا بِاسْمِ اللَّهِ، وَفِي سَبِيلِ اللَّهِ. قَاتِلُوا مَنْ كَفَرَ بِاللَّهِ، اغْزُوا وَلَا تَغْدِرُوا، وَلَا تَغْلُوا، وَلَا تَمْثُلُوا، وَلَا تَقْتُلُوا وَلِيدًا. وَإِذَا أَنْتَ لَقِيتَ عَدُوَّكَ مِنَ الْمُشْرِكِينَ فَادْعُهُمْ إِلَى إِحْدَى ثَلَاثِ خِلَالٍ، أَوْ: خِصَالٍ، فَأَيَّتُهُنَّ أَجَابُوكَ إِلَيْهَا فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ: ادْعُهُمْ إِلَى الْإِسْلَامِ، فَإِنْ أَجَابُوكَ فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ. ثُمَّ ادْعُهُمْ إِلَى التَّحَوُّلِ مِنْ دَارِهِمْ إِلَى دَارِ الْمُهَاجِرِينَ، وَأَخْبِرْهُمْ إِنْ فَعَلُوا ذَلِكَ: أَنَّ لَهُمْ مَا لِلْمُهَاجِرِينَ، وَأَنَّ عَلَيْهِمْ مَا عَلَى الْمُهَاجِرِينَ، وَإِنْ أَبَوْا فَأَخْبِرْهُمْ أَنَّهُمْ يَكُونُونَ كَأَعْرَابِ الْمُسْلِمِينَ، يَجْرِي عَلَيْهِمْ حُكْمُ اللَّهِ الَّذِي يَجْرِي عَلَى الْمُؤْمِنِينَ، وَلَا يَكُونُ لَهُمْ فِي الْفَيْءِ وَالْغَنِيمَةِ شَيْءٌ، إِلَّا أَنْ يُجَاهِدُوا مَعَ الْمُسْلِمِينَ. فَإِنْ هُمْ أَبَوْا أَنْ يَدْخُلُوا فِي الْإِسْلَامِ فَسَلْهُمْ إِعْطَاءَ الْجِزْيَةِ، فَإِنْ فَعَلُوا فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ. فَإِنْ هُمْ أَبَوْا فَاسْتَعِنْ بِاللَّهِ عَلَيْهِمْ وَقَاتِلْهُمْ. وَإِنْ حَاصَرْتَ حِصْنًا، فَأَرَادُوكَ أَنْ تَجْعَلَ لَهُمْ ذِمَّةَ اللَّهِ وَذِمَّةَ نَبِيِّكَ، فَلَا تَجْعَلْ لَهُمْ ذِمَّةَ اللَّهِ وَلَا ذِمَّةَ نَبِيِّكَ، وَلَكِنِ اجْعَلْ لَهُمْ ذِمَّتَكَ وَذِمَّةَ أَبِيكَ وَذِمَّةَ أَصْحَابِكَ، فَإِنَّكُمْ إِنْ تُخْفِرُوا ذِمَّتَكُمْ وَذِمَّةَ آبَائِكُمْ، أَهْوَنُ عَلَيْكُمْ مِنْ أَنْ تُخْفِرُوا ذِمَّةَ اللَّهِ وَذِمَّةَ رَسُولِهِ. وَإِنْ حَاصَرْتَ حِصْنًا فَأَرَادُوكَ أَنْ يَنْزِلُوا عَلَى حُكْمِ اللَّهِ، فَلَا تُنْزِلْهُمْ عَلَى حُكْمِ اللَّهِ، وَلَكِنْ أَنْزِلْهُمْ عَلَى حُكْمِكَ، فَإِنَّكَ لَا تَدْرِي: أَتُصِيبُ فِيهِمْ حُكْمَ اللَّهِ أَمْ لَا". (م,د,ت,جه)', 'ബുറൈദ(റ), നുഅ്മാനുബ്നു മുഖർറിൻ(റ): റസൂൽ(സ) ആരെയെങ്കിലും ഒരു സൈന്യത്തിന്റെ നേതാവാക്കിയാൽ മുസ്ലിംകൾക്ക് നന്മചെയ്യണമെന്നും സ്വന്തത്തിൽ അല്ലാഹുവിന സൂക്ഷിക്കണമെന്നും അവരോട് ഉപദേശിച്ചുകൊണ്ട് ഇപ്രകാരം പറയും: "അല്ലാഹുവിന്റെ നാമത്തിലും അവന്റെ മാർഗ്ഗത്തിലുമായിട്ട് നിങ്ങൾ യുദ്ധം ചെയ്യുക. അല്ലാഹുവിനെ ധിക്കരിച്ചവരോട് നിങ്ങൾ പോരാടുക, നിങ്ങൾ യുദ്ധം ചെയ്യുക, സന്ധി ലംഘിക്കരുത്, യുദ്ധമുതൽ പൂഴ്ത്തിവെക്കരുത്, അംഗവിഛേദം നടത്തരുത്, കുട്ടികളെ വധിക്കരുത്. നിന്റെ ശത്രുവിനെ കണ്ടാൽ മൂന്നാലൊരു കാര്യത്തിലേക്ക് നീ അവരെ ക്ഷണിക്കുക. ആ കാര്യങ്ങൾ അവർ അംഗീകരിച്ചാൽ അത് സ്വീകരിക്കുകയും അവരെത്തൊട്ട് വാളിനെ തടഞ്ഞുവെക്കുകയും ചെയ്യുക. അവരെ നീ ഇസ്ലാമിലേക്ക് ക്ഷണിക്കുക. അതിന് അവർ സമ്മതിച്ചാൽ അത് സ്വീകരിക്കുകയും അവരെത്തൊട്ട് വാളിനെ പിടിച്ചുവെക്കുകയും ചെയ്യുക. ശേഷം തങ്ങളുടെ നാട്ടിൽനിന്ന് പലായനം ചെയ്തവരുടെ (മുഹാജിറുകൾ) നാട്ടിലേക്ക് പോകാൻ അവരോട് ആവശ്യപ്പെടുക, അവർ അപ്രകാരം ചെയ്യുന്നുവെങ്കിൽ പാലായനം ചെയ്തവർക്കുള്ള ആനുകൂല്യങ്ങളെല്ലാം അവർക്കുണ്ടാകുമെന്നും പലായനം ചെയ്തവരുടെ മേൽ നടപ്പാക്കപ്പെടുന്ന നിയമങ്ങൾ അവരുടെ മേലിലും നടപ്പാക്കപ്പെടുമെന്നും അവരോട് പറയുക. അവർ അത് സ്വീകരിച്ചില്ലെങ്കിൽ മലഞെരുവുകളിൽ താമസിക്കുന്ന (അഅ്റാബികളായ) മുസ്ലിംകളെപ്പോലെയായിരിക്കുമവർ എന്നും സത്യവിശ്വാസികളുടെ മേൽ നടപ്പാക്കപ്പെടുന്ന അല്ലാഹുവിന്റെ വിധികൾ അവരുടെ മേലിലും നടപ്പാക്കപ്പെടുമെന്നും, മുസ്ലിംകളോടൊപ്പം ധർമ്മസമരത്തിലേർപ്പെടാതെ ഗനീമതി(യുദ്ധമുതൽ)ൽ നിന്നോ ഫൈഇ(യുദ്ധം ചെയ്യാതെ ലഭിക്കുന്ന ശത്രുക്കളുടെ മുതൽ)ൽ നിന്നോ അവർക്ക് ഒരു വിഹിതവും ലഭിക്കില്ലെന്നും അവരോട് പറയുക. ഇസ്ലാമിലേക്ക് വരാൻ അവർ കൂട്ടാക്കിയില്ലെങ്കിൽ ജിസ്യ (സംരക്ഷണത്തിന് പകരം ചുമത്തുന്ന നികുതി) നൽകാൻ ആവശ്യപ്പെടുക. അവരത് സമ്മതിച്ചാൽ അത് സ്വീകരിക്കുകയും അവരിൽ നിന്ന് വാളിനെ തടഞ്ഞുവെക്കുകയും ചെയ്യുക. അതും അവർ സമ്മതിക്കുന്നില്ലെങ്കിൽ അവർക്കെതിരായി അല്ലാഹുവിനോട് സഹായം ചോദിക്കുക. എന്നിട്ട് അവരോട് യുദ്ധം ചെയ്യുക. നീ വല്ല കൊട്ടയും ഉപരോധിക്കുകയും അതിലുള്ളവർ അല്ലാഹുവിന്റെയും നിന്റെ നബിയുടെയും അഭയം നൽകണമെന്ന് നിന്നോട് ആവശ്യപ്പെടുകയും ചെയ്താൽ നീ അല്ലാഹുവിന്റെയും നിന്റെ നബിയുടെയും അഭയം അവർക്ക് നൽകരുത്, പകരം നിന്റെയും നിന്റെ പിതാവിന്റെയും നിന്റെ അനുചരരുടെയും അഭയം നൽകുക. കാരണം, നിങ്ങൾ നിങ്ങളുടെയും നിങ്ങളുടെ വാപ്പമാരുടെയും അഭയത്തെ പൊളിച്ചുകളയൽ അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും അഭയത്തെ പൊളിക്കുന്നതിനേക്കാൾ ഭേദമാണ്. നീ വല്ല കോട്ടയും ഉപരോധിക്കുകയും അല്ലാഹുവിന്റെ വിധിപ്രകാരം തങ്ങൾ ഇറങ്ങാമെന്ന് അവർ നിന്നോട് താൽപര്യപ്പെടുകയും ചെയ്താൽ അല്ലാഹുവിന്റെ വിധിപ്രകാരം നീ അവരെ ഇറക്കരുത്, നിന്റെ വിധിപ്രകാരമാണ് അവരെ ഇറക്കേണ്ടത്. കാരണം അല്ലാഹുവിന്റെ വിധി അവരിൽ നടപ്പാക്കാൻ നിനക്കാവുമോ ഇല്ലയോ എന്ന് നിനക്കറിയില്ല." (മു,ദ,തു,ജ)', 'بُرَيْدَةَ وَالنُّعْمَانِ بْنِ مُقَرِّنٍ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 928, 929, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمْ يُقْتَلْ مِنْ نِسَائِهِمْ – تَعْنِي بَنِي قُرَيْظَةَ – إِلَّا امْرَأَةٌ، إِنَّهَا لَعِنْدِي تُحَدِّثُ تَضْحَكُ ظَهْرًا وَبَطْنًا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْتُلُ رِجَالَهُمْ بِالسُّيُوفِ، إِذْ هَتَفَ هَاتِفٌ بِاسْمِهَا: أَيْنَ فُلَانَةُ؟ قَالَتْ: أَنَا، قُلْتُ: وَمَا شَأْنُكِ؟ قَالَتْ: حَدَثٌ أَحْدَثْتُهُ. قَالَتْ: فَانْطُلِقَ بِهَا، فَضُرِبَتْ عُنُقُهَا، فَمَا أَنْسَى عَجَبًا مِنْهَا أَنَّهَا تَضْحَكُ ظَهْرًا وَبَطْنًا، وَقَدْ عَلِمَتْ أَنَّهَا تُقْتَلُ. (د)', 'ആഇശ(റ): അവരിൽ നിന്ന് - ബനൂഖുറൈളക്കാരിൽ നിന്ന് - ഒരു സ്ത്രീയല്ലാതെ കൊല്ലപ്പെട്ടിട്ടില്ല. അവൾ എന്റെ അടുത്തിരുന്ന് ശക്തമായി ചിരിച്ച് സംസാരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) അവരിലെ പുരുഷന്മാരെ വാള് കൊണ്ട് വെട്ടിക്കൊണ്ടിരിക്കുന്നുണ്ടായിരുന്നു. ഉടനെ ഒരാൾ അവളുടെ പേര് വിളിച്ചു: ഇന്നാലിന്നവളെവിടെ? അവൾ പറഞ്ഞു: എന്നെയാണ് വിളിക്കുന്നത്. ഞാൻ ചോദിച്ചു: എന്താണ് നിനക്ക് പ്രശ്നം? അവൾ പറഞ്ഞു: ഞാൻ ചെയ്ത ഒരു പാതകമാണത്. ആഇശ(റ) പറഞ്ഞു: ആ മനുഷ്യൻ അവളെ കൊണ്ടുപോയി. അവളുടെ തലയറുക്കപ്പെട്ടു. താൻ വധിക്കപ്പെടുമെന്നറിഞ്ഞിട്ടും ശക്തമായി ചിരിച്ചുകൊണ്ടിരിക്കുന്ന അവളിലെ അത്ഭുതത്തെ എനിക്ക് മറക്കാൻ കഴിഞ്ഞിട്ടില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 929, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لِكَعْبِ بْنِ الْأَشْرَفِ، فَإِنَّهُ قَدْ آذَى اللَّهَ وَرَسُولَهُ". فَقَامَ مُحَمَّدُ بْنُ مَسْلَمَةَ فَقَالَ: أَنَا يَا رَسُولَ اللَّهِ، أَتُحِبُّ أَنْ أَقْتُلَهُ؟ قَالَ: نَعَمْ. قَالَ: فَأْذَنْ لِي أَنْ أَقُولَ شَيْئًا، قَالَ: "نَعَمْ، قُلْ". فَأَتَاهُ فَقَالَ: إِنَّ هَذَا الرَّجُلَ قَدْ سَأَلَنَا الصَّدَقَةَ، وَقَدْ عَنَّانَا، قَالَ: وَأَيْضًا لَتَمَلُّنَّهُ، قَالَ: اتَّبَعْنَاهُ فَنَحْنُ نَكْرَهُ أَنْ نَدَعَهُ حَتَّى نَنْظُرَ إِلَى أَيِّ شَيْءٍ يَصِيرُ أَمْرُهُ، وَقَدْ أَرَدْنَا أَنْ تُسْلِفَنَا وَسْقًا أَوْ وَسْقَيْنِ. قَالَ كَعْبٌ: أَيَّ شَيْءٍ تَرْهَنُونِي؟ قَالَ: وَمَا تُرِيدُ مِنَّا؟ قَالَ: نِسَاءَكُمْ، قَالُوا: سُبْحَانَ اللَّهِ، أَنْتَ أَجْمَلُ الْعَرَبِ، نَرْهَنُكَ نِسَاءَنَا فَيَكُونُ ذَلِكَ عَارًا عَلَيْنَا. قَالَ: فَتَرْهَنُونِي أَوْلَادَكُمْ، قَالُوا: سُبْحَانَ اللَّهِ، يُسَبُّ ابْنُ أَحَدِنَا فَيُقَالُ: رُهِنْتَ بِوَسْقٍ أَوْ وَسْقَيْنِ. قَالُوا: نَرْهَنُكَ اللَّأْمَةَ؟ – يُرِيدُ السِّلَاحَ – قَالَ: نَعَمْ، فَلَمَّا أَتَاهُ نَادَاهُ فَخَرَجَ إِلَيْهِ وَهُوَ مُتَطَيِّبٌ يَنْضَحُ رَأْسُهُ، فَلَمَّا أَنْ جَلَسَ إِلَيْهِ – وَقَدْ كَانَ جَاءَ مَعَهُ بِنَفَرٍ ثَلَاثَةٍ أَوْ أَرْبَعَةٍ فَذَكَرُوا لَهُ – قَالَ: عِنْدِي فُلَانَةُ، وَهِيَ أَعْطَرُ نِسَاءِ النَّاسِ. قَالَ: تَأْذَنُ لِي فَأَشُمَّ؟ قَالَ: نَعَمْ، فَأَدْخَلَ يَدَهُ فِي رَأْسِهِ فَشَمَّهُ، قَالَ: أَعُودُ؟ قَالَ: نَعَمْ، فَأَدْخَلَ يَدَهُ فِي رَأْسِهِ، فَلَمَّا اسْتَمْكَنَ مِنْهُ قَالَ: دُونَكُمْ، فَضَرَبُوهُ حَتَّى قَتَلُوهُ. (ق,د)', 'ജാബിർ(റ): റസൂൽ(സ) ചോദിച്ചു: "കഅ്ബുബ്നുൽ അശ്റഫിന്റെ കാര്യം ആര് ഏറ്റെടുക്കും? അവൻ അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും ഉപദ്രവിച്ചിരിക്കുന്നു." അപ്പോൾ മുഹമ്മദുബ്നു മസ്ലമ(റ) എഴുന്നേറ്റ് നിന്നു പറഞ്ഞു: ഞാൻ ഏറ്റെടുക്കാം ദൈവദൂതരേ, ഞാനവനെ കൊല്ലുന്നത് അങ്ങ് ഇഷ്ടപ്പെടുന്നുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "അതെ." അദ്ദേഹം പറഞ്ഞു: എങ്കിൽ അവനോട് കുറച്ച് കാര്യങ്ങൾ പറയാൻ അവിടന്ന് അനുവാദം തരുമോ? അവിടന്ന് പറഞ്ഞു: "അതെ, നീ പറയുക." അങ്ങനെ മുഹമ്മദ്(റ) അവന്റെയടുത്ത് പോയി പറഞ്ഞു: ഈ മനുഷ്യൻ (നബി) ഞങ്ങളോട് നികുതി ചോദിക്കുന്നു. ഞങ്ങളെ ബുദ്ധിമുട്ടിക്കുന്നു. അവൻ പറഞ്ഞു: ഇനിയും നിങ്ങൾ അദ്ദേഹത്തെ വെറുക്കും. മുഹമ്മദ്(റ) പറഞ്ഞു: ഞങ്ങൾ പിൻപറ്റി, ഇനി ഇതിന്റെ അവസാനം എന്താകുമെന്ന് അറിയും വരെ ഞങ്ങളദ്ദേഹത്തെ ഒഴിവാക്കാൻ ആഗ്രഹിക്കുന്നില്ല. ഒന്നോ രണ്ടോ വസ്ഖ് ഞങ്ങൾ താങ്കളോട് കടം ചോദിക്കാൻ ഉദ്ദേശിക്കുന്നു. കഅ്ബ് ചോദിച്ചു: എനിക്ക് എന്താണ് നിങ്ങൾ പണയമായി നൽകുക? മുഹമ്മദ്(റ) ചോദിച്ചു: നിങ്ങൾ എന്താണ് ഉദ്ദേശിക്കുന്നത്? കഅ്ബ് പറഞ്ഞു: നിങ്ങളുടെ സ്ത്രീകളെ. അവർ പറഞ്ഞു: അല്ലാഹു എത്ര പരിശുദ്ധൻ, താങ്കൾ അറബികളിൽ വെച്ചേറ്റവും സുന്ദരനാണല്ലോ, എന്നിട്ട് ഞങ്ങൾ സ്വന്തം ഭാര്യമാരെ താങ്കൾക്ക് പണയം വെക്കുന്നത് ഞങ്ങൾക്ക് മോശമാണ്. കഅ്ബ് പറഞ്ഞു: നിങ്ങളുടെ സന്താനങ്ങളെ എനിക്ക് പണയമായി നൽകുക. അവർ പറഞ്ഞു: അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു. ഒന്നോ രണ്ടോ വസ്ഖിന് പണയം വെക്കപ്പെട്ടവർ എന്ന് പറഞ്ഞ് ആളുകൾ അവരെ പരിഹസിക്കും. ശേഷം അവർ ചോദിച്ചു: ഞങ്ങൾ യുദ്ധായുധങ്ങൾ പണയം തരാം. കഅ്ബ് പറഞ്ഞു: അതെ. അങ്ങനെ പിന്നീട് അവന്റെയടുക്കൽ മുഹമ്മദ്(റ) വന്നപ്പോൾ അവനെ വിളിച്ചു. കഅ്ബ് പുറത്തേക്ക് വന്നു. അവൻ സുഗന്ധം പൂശിയിരുന്നു. തലയിൽ സുഗന്ധം തിളങ്ങുന്നുണ്ടായിരുന്നു. അങ്ങനെ അവൻ ഇരുന്നപ്പോൾ മുഹമ്മദ്(റ)വിന്റെ കൂടെ മൂന്നോ നാലോ ആളുകളുണ്ടായിരുന്നു. കഅ്ബ് പറഞ്ഞു: എന്റെയടുത്ത് ഒരു സ്ത്രീയുണ്ട്, അവൾ സ്ത്രീകളിൽ വെച്ച് ഏറ്റവും സുഗന്ധമുള്ളവളാണ്. മുഹമ്മദ്(റ) ചോദിച്ചു: ഞാൻ തല ഒന്ന് വാസനിച്ചോട്ടെ? അവൻ പറഞ്ഞു: അതെ, അപ്പോൾ മുഹമ്മദ്(റ) അവന്റെ തലയിൽ കൈവെച്ചു. മുഹമ്മദ്(റ) ചോദിച്ചു: ഒന്നുകൂടെ വാസനിച്ചോട്ടെ? കഅ്ബ് പറഞ്ഞു: അതെ. അങ്ങനെ മുഹമ്മദ്(റ) തന്റെ കൈ അവന്റെ തലയിൽ വെച്ചു. അവൻ കയ്യിൽ ഒതുങ്ങിയപ്പോൾ അടുത്തുള്ളവരോട് പറഞ്ഞു: നിങ്ങൾ വെട്ടി കൊള്ളുക. അപ്പോൾ അവർ അവനെ വെട്ടുകയും വധിക്കുകയും ചെയ്തു. (ബു,മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 930, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْإِيمَانُ قَيَّدَ الْفَتْكَ لَا يَفْتِكُ مُؤْمِنٌ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "ഓർക്കാപ്പുറത്തുള്ള അക്രമത്തെ ഈമാൻ ചങ്ങലക്കിടുന്നു, ഒരു സത്യവിശ്വാസിയും ഓർക്കാപ്പുറത്ത് ആക്രമിക്കുകയില്ല." (ദ)', 'أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنِ ابْنِ عَبَّاسٍ، عَنِ الصَّعْبِ بْنِ جَثَّامَةَ – رَضِيَ اللَّهُ عَنْهُمْ – أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّارِ مِنَ الْمُشْرِكِينَ يُبَيَّتُونَ، فَيُصَابُ مِنْ ذَرَارِيِّهِمْ وَنِسَائِهِمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُمْ مِنْهُمْ". وَفِي رِوَايَةٍ: "هُمْ مِنْ آبَائِهِمْ". ثُمَّ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ عَنْ قَتْلِ النِّسَاءِ وَالْوِلْدَانِ. (ق,د,ت,جه)', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): രാത്രി അക്രമിക്കപ്പെടുന്ന ബഹുദൈവാരാധകരുടെ വീടിനെക്കുറിച്ചും എന്നിട്ട് പിടികൂടപ്പെടുന്ന അവരിലെ സ്ത്രീകളെയും കുട്ടികളെയും കുറിച്ചും അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർ അവരിൽ (ബഹുദൈവരാധാകരിൽ) പെട്ടവരാണ്." മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "അവർ അവരുടെ വാപ്പമാരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." ശേഷം റസൂൽ(സ) സ്ത്രീകളെയും കുട്ടികളെയും വധിക്കുന്നത് നിരോധിച്ചു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ، عَنِ الصَّعْبِ بْنِ جَثَّامَةَ –', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=210), 1, 'وَفِي رِوَايَةٍ: "هُمْ مِنْ آبَائِهِمْ". ثُمَّ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ عَنْ قَتْلِ النِّسَاءِ وَالْوِلْدَانِ. (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "അവർ അവരുടെ വാപ്പമാരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." ശേഷം റസൂൽ(സ) സ്ത്രീകളെയും കുട്ടികളെയും വധിക്കുന്നത് നിരോധിച്ചു. (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ أَبِي بَكْرٍ هَوَازِنَ، عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْنَا مَاءً لِبَنِي فَزَارَةَ فَعَرَّسْنَا، حَتَّى إِذَا كَانَ عِنْدَ الصُّبْحِ شَنَنَّاهَا عَلَيْهِمْ غَارَةً، فَأَتَيْنَا أَهْلَ مَاءٍ فَبَيَّتْنَاهُمْ، فَقَتَلْنَاهُمْ: تِسْعَةً أَوْ سَبْعَةَ أَبْيَاتٍ. (د,جه)', 'സലമതുബ്നുൽ അക്വഅ്(റ): നബി(സ)യുടെ കാലത്ത് ഞങ്ങൾ അബൂബക്കർ(റ)വിന്റെ കൂടെ ഹവാസിൻ ഗോത്രത്തോട് യുദ്ധം ചെയ്തു. ഞങ്ങൾ ബനൂ ഫസാറക്കാരുടെ ഒരു ജലസ്രോതസ്സിനടുത്തെത്തി. അങ്ങനെ രാത്രി അവിടെ ഇറങ്ങി. നേരം പുലർന്നപ്പോൾ ഞങ്ങൾ അവരുടെ മേൽ ആക്രമണമഴിച്ചുവിട്ടു. ഞങ്ങൾ ജലസ്രോദസ്സിനടുത്തുള്ളവരുടെ അടുത്ത് പോയി രാത്രി അവരെ ആക്രമിച്ചു. ഏഴോ ഒമ്പതോ വീട്ടുകാരെ ഞങ്ങൾ വധിച്ചു. (ദ,ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "انْطَلِقُوا بِاسْمِ اللَّهِ وَبِاللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ، وَلَا تَقْتُلُوا شَيْخًا فَانِيًا، وَلَا طِفْلًا، وَلَا صَغِيرًا، وَلَا امْرَأَةً، وَلَا تَغُلُّوا، وَضُمُّوا غَنَائِمَكُمْ، وَأَصْلِحُوا، وَأَحْسِنُوا، إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെക്കൊണ്ടും അല്ലാഹുവിന്റെ നാമംകൊണ്ടും അല്ലാഹുവിന്റെ റസൂലിന്റെ മാർഗ്ഗത്തിലായിട്ടും നിങ്ങൾ പുറപ്പെടുക. വൃദ്ധന്മാരെയും ശിശുക്കളെയും കുട്ടികളെയും സ്ത്രീകളെയും നിങ്ങൾ വധിക്കരുത്. നിങ്ങൾ പൂഴ്ത്തിവെപ്പ് നടത്തരുത്. യുദ്ധമുതലിനെ നിങ്ങൾ ഒരുമിച്ചുകൂട്ടുകയും നന്മ പ്രവർത്തിക്കുകയും ഗുണവാന്മാരാവുകയും ചെയ്യുക. കാരണം അല്ലാഹു ഗുണവാന്മാരെ ഇഷ്ടപ്പെടുന്നു." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ عِصَامٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ فَقَالَ: "إِذَا رَأَيْتُمْ مَسْجِدًا أَوْ سَمِعْتُمْ مُؤَذِّنًا فَلَا تَقْتُلُوا أَحَدًا". (د,ت,ن)', 'ഇസാമുൽ മുസ്നി(റ): റസൂൽ(സ) ഞങ്ങളെ ഒരു സൈന്യത്തോടൊപ്പം അയച്ചു. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങൾ ഒരു പള്ളി കാണുകയോ ബാങ്കുവിളി കേൾക്കുകയോ ചെയ്താൽ ഒരാളെയും വധിക്കരുത്." (ദ,തു,ന)', 'عِصَامٍ الْمُزَنِيِّ', 'ഇസാമുൽ മുസ്നി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقْتُولَةً، فَأَنْكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَتْلَ النِّسَاءِ وَالصِّبْيَانِ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ചെയ്ത ഒരു യുദ്ധത്തിൽ ഒരു സ്ത്രീ കൊല്ലപ്പെട്ടതായി കാണപ്പെട്ടു, അപ്പോൾ റസൂൽ(സ) സ്ത്രീകളെയും കുട്ടികളെയും വധിക്കുന്നത് നിരോധിച്ചു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ رَبَاحِ بْنِ رَبِيعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، فَرَأَى النَّاسَ مُجْتَمِعِينَ عَلَى شَيْءٍ، فَبَعَثَ رَجُلًا فَقَالَ: "انْظُرْ عَلَامَ اجْتَمَعَ هَؤُلَاءِ". فَجَاءَ فَقَالَ: عَلَى امْرَأَةٍ قَتِيلٍ. فَقَالَ: "مَا كَانَتْ هَذِهِ لِتُقَاتِلَ". قَالَ: وَعَلَى الْمُقَدِّمَةِ خَالِدُ بْنُ الْوَلِيدِ، فَبَعَثَ رَجُلًا فَقَالَ: "قُلْ لِخَالِدٍ: لَا يَقْتُلَنَّ امْرَأَةً وَلَا عَسِيفًا". (د,جه)', 'റബാഹുബ്നു റബീഅ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഒരു യുദ്ധമുഖത്തായിരുന്നു. അപ്പോൾ ജനങ്ങളെല്ലാം ഒരിടത്ത് ഒരുമിച്ചുകൂടിയത് റസൂൽ(സ) കണ്ടു. നബി(സ) ഒരാളെ അയച്ചുകൊണ്ടു പറഞ്ഞു: "എന്തിനാണ് അവർ ഒരുമിച്ചുകൂടിയതെന്ന് നീ നോക്കുക." അദ്ദേഹം മടങ്ങിവന്ന് പറഞ്ഞു: കൊല്ലപ്പെട്ട ഒരു സ്ത്രീക്ക് ചുറ്റുമാണവർ. തിരുമേനി(സ) പറഞ്ഞു: "അവൾ കൊല്ലപ്പെടേണ്ടവളായിരുന്നില്ല." നിവേദകൻ പറയുന്നു: സൈന്യത്തിന്റെ മുമ്പിൽ ഖാലിദുബ്നുൽ വലീദ്(റ)വായിരുന്നു. റസൂൽ(സ) ഒരാളെ അയച്ചുകൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: "സ്ത്രീയെയോ വേലക്കാരെയോ വധിക്കരുതെന്ന് നീ ഖാലിദിനോട് പറയുക." (ദ,ജ)', 'رَبَاحِ بْنِ رَبِيعٍ', 'റബാഹുബ്നു റബീഅ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ وَاسْتَبْقُوا شَرْخَهُمْ". (د,ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ബഹുദൈവാരാധകരിലെ വൃദ്ധന്മാരെ നിങ്ങൾ വധിക്കുകയും അവരിലെ കുട്ടികളെ ഒഴിവാക്കുകയും ചെയ്യുക." (ദ,തു)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَرَجَ إِلَى خَيْبَرَ أَتَاهَا لَيْلًا، وَكَانَ إِذَا جَاءَ قَوْمًا بِلَيْلٍ لَمْ يُغِرْ عَلَيْهِمْ حَتَّى يُصْبِحَ، فَلَمَّا أَصْبَحَ خَرَجَتْ يَهُودُ بِمَسَاحِيهِمْ وَمَكَاتِلِهِمْ، فَلَمَّا رَأَوْهُ قَالُوا: مُحَمَّدٌ، وَافَقَ وَاللَّهِ مُحَمَّدٌ الْخَمِيسَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ". (ق,ت)', 'അനസ്(റ): റസൂൽ(സ) ഖൈബറിലേക്ക് പുറപ്പെട്ട് അവിടെയെത്തിയത് രാത്രിയിലായിരുന്നു. റസൂൽ(സ) രാത്രിയിൽ ഏതെങ്കിലും കൂട്ടരുടെ അടുത്തെത്തിയാൽ നേരം പുലരുന്നതിനുമുമ്പ് അവരെ അക്രമിക്കുമായിരുന്നില്ല. നേരം പുലർന്നപ്പോൾ ജൂതന്മാർ കലപ്പകളും പാത്രങ്ങളുമെടുത്ത് പുറത്തിറങ്ങി. റസൂൽ(സ)യെ കണ്ടപ്പോൾ അവർ പറഞ്ഞു: ഇതാ മുഹമ്മദ്. അല്ലാഹുവാണ് സത്യം, മുഹമ്മദ് സൈന്യവുമായാണ് വന്നിരിക്കുന്നത്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു അക്ബർ (അല്ലാഹുവാണ് വലിയവൻ), ഖൈബർ തകർന്നിരിക്കുന്നു. ഞങ്ങൾ ആരുടെയെങ്കിലും മുറ്റത്തിറങ്ങിയാൽ മുന്നറിയിപ്പ് നൽകപ്പെട്ടവരുടെ പ്രഭാതം വളരെ മോശമായിരിക്കും." (ബു,മു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخْبَرَنِي الصَّعْبُ بْنُ جَثَّامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ خَيْلَنَا أُوطِئَتْ مِنْ نِسَاءِ الْمُشْرِكِينَ وَأَوْلَادِهِمْ؟ قَالَ: "هُمْ مِنْ آبَائِهِمْ". (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): സ്വഅ്ബുബ്നു ജസ്സാമ(റ) എന്നോട് പറഞ്ഞു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, നമ്മുടെ കുതിരപ്പട ബഹുദൈവാരാധകരുടെ ചില കുട്ടികളെയും സ്ത്രീകളെയും അബദ്ധത്തിൽ വധിച്ചിരിക്കുന്നു? റസൂൽ(സ) പറഞ്ഞു: "അവർ തങ്ങളുടെ പിതാക്കന്മാരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." (ബു,മു, ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 932, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَرَصَتْ نَمْلَةٌ نَبِيًّا مِنَ الْأَنْبِيَاءِ فَأَمَرَ بِقَرْيَةِ النَّمْلِ فَأُحْرِقَتْ، فَأَوْحَى اللَّهُ إِلَيْهِ: أَنْ قَرَصَتْكَ نَمْلَةٌ أَحْرَقْتَ أُمَّةً مِنَ الْأُمَمِ تُسَبِّحُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു പ്രവാചകനെ ഒരു ഉറുമ്പ് കടിക്കുകയും അതിന്റെ പേരിൽ ഒരു ഉറുമ്പിൻ ഗ്രാമത്തെ കത്തിക്കാൻ ആ പ്രവാചകൻ കൽപിക്കുകയും അവ കത്തിക്കപ്പെടുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു അവരിലേക്ക് വഹ്യ്(ദിവ്യ ബോധനം) നൽകി. ഒരു ഉറുമ്പ് കടിച്ചതിന്റെ പേരിൽ അല്ലാഹുവിനെ വാഴ്ത്തിക്കൊണ്ടിരിക്കുന്ന ഒരു സമൂഹത്തെ താങ്കൾ കത്തിച്ചുകളഞ്ഞു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا تُرِيحُنِي مِنْ ذِي الْخَلَصَةِ؟" وَكَانَ بَيْتًا فِي خَثْعَمَ يُسَمَّى كَعْبَةَ الْيَمَانِيَةِ، قَالَ: فَانْطَلَقْتُ فِي خَمْسِينَ وَمِائَةِ فَارِسٍ مِنْ أَحْمَسَ، وَكَانُوا أَصْحَابَ خَيْلٍ، وَكُنْتُ لَا أَثْبُتُ عَلَى الْخَيْلِ، فَضَرَبَ فِي صَدْرِي حَتَّى رَأَيْتُ أَثَرَ أَصَابِعِهِ فِي صَدْرِي، وَقَالَ: "اللَّهُمَّ ثَبِّتْهُ وَاجْعَلْهُ هَادِيًا مَهْدِيًّا". فَانْطَلَقَ إِلَيْهَا فَكَسَرَهَا وَحَرَّقَهَا، ثُمَّ بَعَثَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخْبِرُهُ، فَقَالَ رَسُولُ جَرِيرٍ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا جِئْتُكَ حَتَّى تَرَكْتُهَا كَأَنَّهَا جَمَلٌ أَجْوَفُ أَوْ أَجْرَبُ، قَالَ: فَبَارَكَ فِي خَيْلِ أَحْمَسَ وَرِجَالِهَا خَمْسَ مَرَّاتٍ. (خ)', 'ജരീർ(റ): റസൂൽ(സ) എന്നോട് ചോദിച്ചു: "ദുൽ ഖലസയുടെ കാര്യത്തിൽ നീ എനിക്ക് മനസ്സമാധാനം കൈവരുത്തിത്തരികയില്ലേ?" ഖസ്അം ഗോത്രക്കാരുടെ ''കഅ്ബത്തുൽ യമാനിയ്യ'' എന്നറിയപ്പെടുന്ന ഒരു വിഗ്രഹാലയമായിരുന്നു ''ദുൽ ഖലസ.'' ജരീർ(റ) പറഞ്ഞു: അങ്ങനെ അഹ്മസ് ഗോത്രത്തിൽ പെട്ട 150 പേരുള്ള ഒരു കുതിരപ്പടയുമായി ഞാൻ പുറപ്പെട്ടു. അവരെല്ലാം അശ്വഭടന്മാരായിരുന്നു. എനിക്കാവട്ടെ കുതിരപ്പുറത്തിരുന്ന് പരിചയമുണ്ടായിരുന്നില്ല. അതറിഞ്ഞപ്പോൾ റസൂൽ(സ) എന്റെ നെഞ്ചിൽ അടിച്ചു. റസൂൽ(സ)യുടെ വിരലടയാളം എന്റെ നെഞ്ചിൽ ഞാൻ കണ്ടു. തിരുമേനി(സ) പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ നീ അദ്ദേഹത്തിന് കുതിരപ്പുറത്ത് സ്ഥിരത നൽകേണമേ, അദ്ദേഹത്തെ നീ മാർഗ്ഗദർശിയും മാർഗ്ഗദർശനം ലഭിച്ചവനുമാക്കേണമേ." അങ്ങനെ ജരീർ(റ) അവിടേക്ക് പോവുകയും അതെല്ലാം തകർത്ത് തീവെക്കുകയും ചെയ്തു. ശേഷം റസൂൽ(സ)ക്ക് ആ വിവരമെത്തിക്കാൻ ആളെ അയച്ചു. ജരീർ(റ)വിന്റെ ദൂതൻ റസൂൽ(സ)യോട് പറഞ്ഞു: സത്യവുമായി അങ്ങയെ അയച്ചവൻ തന്നെ സത്യം, ആ വിഗ്രഹാലയത്തെ ചൊറിപിടിച്ച അല്ലെങ്കിൽ ഉള്ള് പൊള്ളയായ ഒരു ഒട്ടകത്തെപ്പോലെയാക്കിയിട്ടാണ് ഞാൻ അങ്ങയുടെയടുത്ത് വന്നിരിക്കുന്നത്. അപ്പോൾ അഹ്മസ് ഗോത്രത്തിലെ കുതിരപ്പടയാളികൾക്കും കാലാൾപടയ്ക്കും അനുഗ്രഹത്തിനു വേണ്ടി തിരുമേനി(സ) അഞ്ചുപ്രാവശ്യം പ്രാർത്ഥിച്ചു. (ബു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: لَمَّا عَلِمَ أَنَّ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ حَرَّقَ قَوْمًا بِالنَّارِ، فَقَالَ: لَوْ كُنْتُ أَنَا لَمْ أُحَرِّقْهُمْ، لِأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُعَذِّبُوا بِعَذَابِ اللَّهِ". وَلَقَتَلْتُهُمْ كَمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു കൂട്ടമാളുകളെ അലി(റ) തീകൊണ്ട് കരിച്ചുകളഞ്ഞു എന്ന വാർത്തയറിഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അദ്ദേഹത്തിന്റെ സ്ഥാനത്ത് ഞാനായിരുന്നെങ്കിൽ അവരെ കരിക്കുമായിരുന്നില്ല. കാരണം, "അല്ലാഹു ശിക്ഷിക്കും പോലെ നിങ്ങൾ ശിക്ഷിക്കരുത്" എന്ന് നബി(സ) പറഞ്ഞിരിക്കുന്നു. "വല്ലവനും തന്റെ ദീൻ മാറ്റിയാൽ അവനെ കൊന്നുകളയുക." എന്ന് നബി(സ) പറഞ്ഞപോലെ ഞാനവരെ കൊല്ലുമായിരുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 933, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أُسَامَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَهِدَ إِلَيْهِ فَقَالَ: "أَغِرْ عَلَى أُبْنَى صَبَاحًا وَحَرِّقْ". (د,جه)', 'ഉസാമ(റ): റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഉബ്ന ദേശത്തെ നീ പ്രഭാതത്തിൽ ആക്രമിക്കുകയും കരിച്ച് കളയുകയും ചെയ്യുക." (ദ,ജ)', 'أُسَامَةَ', 'ഉസാമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ حَمْزَةَ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّرَهُ عَلَى سَرِيَّةٍ، قَالَ: فَخَرَجْتُ فِيهَا، وَقَالَ: "إِنْ وَجَدْتُمْ فُلَانًا فَأَحْرِقُوهُ بِالنَّارِ". فَوَلَّيْتُ، فَنَادَانِي، فَرَجَعْتُ إِلَيْهِ، فَقَالَ: "إِنْ وَجَدْتُمْ فُلَانًا فَاقْتُلُوهُ وَلَا تُحْرِقُوهُ، فَإِنَّهُ لَا يُعَذِّبُ بِالنَّارِ إِلَّا رَبُّ النَّارِ". (د)', 'ഹംസത്തുൽ അസ്ലമി(റ): റസൂൽ(സ) അദ്ദേഹത്തെ ഒരു സൈന്യത്തിന്റെ നേതാവാക്കി. അദ്ദേഹം പറയുന്നു: ഞാൻ ആ സൈന്യത്തിൽ പുറപ്പെട്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാലിന്ന വ്യക്തിയെക്കണ്ടാൽ നിങ്ങൾ അവനെ കരിച്ചുകളയുക." ശേഷം ഞാൻ തിരിഞ്ഞുനടന്നു. അപ്പോൾ റസൂൽ(സ) എന്നെ വിളിക്കുകയും ഞാൻ മടങ്ങുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാലിന്നവനെ കിട്ടിയാൽ നിങ്ങൾ കൊന്നുകളയുക, കരിക്കരുത്. കാരണം തീ കൊണ്ട് ശിക്ഷിക്കേണ്ടവൻ തീയിന്റെ നാഥൻ മാത്രമാണ്." (ദ)', 'حَمْزَةَ الْأَسْلَمِيِّ', 'ഹംസത്തുൽ അസ്ലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَانْطَلَقَ لِحَاجَتِهِ، فَرَأَيْنَا حُمَّرَةً مَعَهَا فَرْخَانِ، فَأَخَذْنَا فَرْخَيْهَا، فَجَاءَتِ الْحُمَّرَةُ فَجَعَلَتْ تَفْرُشُ، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَنْ فَجَعَ هَذِهِ بِوَلَدِهَا؟ رُدُّوا وَلَدَهَا إِلَيْهَا". وَرَأَى قَرْيَةَ نَمْلٍ قَدْ حَرَّقْنَاهَا، فَقَالَ: "مَنْ حَرَّقَ هَذِهِ". قُلْنَا: نَحْنُ. قَالَ: "إِنَّهُ لَا يَنْبَغِي أَنْ يُعَذِّبَ بِالنَّارِ إِلَّا رَبُّ النَّارِ". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ ഒരു യാത്രയിൽ റസൂൽ(സ)യുടെ കൂടെയായിരുന്നു. റസൂൽ(സ) സ്വന്തം ആവശ്യത്തിന് വേണ്ടി പോയി. അപ്പോൾ ഒരു പക്ഷിയെയും അതിന്റെ കൂടെ രണ്ടു കുഞ്ഞുങ്ങളെയും ഞങ്ങൾ കണ്ടു. അതിന്റെ രണ്ട് കുഞ്ഞുങ്ങളെയും ഞങ്ങൾ പിടികൂടി. അപ്പോൾ ആ പക്ഷി വന്ന് അതിന്റെ ചിറക് വിടർത്തി നിന്നു. ഉടനെ നബി(സ) വന്നുചോദിച്ചു: "ആരാണ് ഈ പക്ഷിയെ അതിന്റെ കുഞ്ഞിന്റെ കാര്യത്തിൽ വേദനിപ്പിച്ചത്, അതിന്റെ കുഞ്ഞിനെ തിരികെ നൽകുക." ഞങ്ങൾ കരിച്ച ഒരു ഉറുമ്പിൻകൂട്ടത്തെയും നബി(സ) കണ്ടു. അപ്പോൾ ചോദിച്ചു: "ആരാണ് ഇവയെ കരിച്ചത്?" ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ തന്നെ. തിരുമേനി(സ) പറഞ്ഞു: "തീയെ പടച്ചവന് മാത്രമേ അതുകൊണ്ട് ശിക്ഷിക്കാൻ പറ്റൂ." (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْثٍ، فَقَالَ: "إِنْ وَجَدْتُمْ فُلَانًا وَفُلَانًا – لِرَجُلَيْنِ مِنْ قُرَيْشٍ – فَأَحْرِقُوهُمَا بِالنَّارِ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَرَدْنَا الْخُرُوجَ: "إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ تُحْرِقُوا فُلَانًا وَفُلَانًا بِالنَّارِ، وَإِنَّ النَّارَ لَا يُعَذِّبُ بِهَا إِلَّا اللَّهُ، فَإِنْ وَجَدْتُمُوهُمَا فَاقْتُلُوهُمَا". (خ,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഞങ്ങളെ ഒരു സംഘത്തോടൊപ്പമയച്ചുകൊണ്ട് പറഞ്ഞു: "ഇന്നാലിന്നവനെയും ഇന്നാലിന്നവനെയും - ഖുറൈശികളിൽ പെട്ട രണ്ടാളുകൾ - നിങ്ങൾക്ക് ലഭിച്ചാൽ അവരെ കരിച്ചുകളയുക." ശേഷം ഞങ്ങൾ പുറപ്പെടുന്ന സമയം റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാലിന്ന രണ്ട് വ്യക്തികളെ കരിച്ചുകളയാൻ ഞാൻ നിങ്ങളോട് കൽപിച്ചിട്ടുണ്ടായിരുന്നു, തീ കൊണ്ട് ശിക്ഷിക്കേണ്ടവൻ അല്ലാഹു മാത്രമാണ്, അതുകൊണ്ട് അവരെ കണ്ടെത്തിയാൽ നിങ്ങൾ കൊന്നുകളയുക." (ബു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّقَ نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ، وَهِيَ الْبُوَيْرَةُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً} الْآيَةَ. وَفِي رِوَايَةٍ: وَفِيهِ يَقُولُ شَاعِرُهُمْ: فَهَانَ عَلَى سَرَاةِ بَنِي لُؤَيٍّ حَرِيقٌ بِالْبُوَيْرَةِ مُسْتَطِيرُ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ബനുന്നളീർ ഗോത്രക്കാരുടെ ഈത്തപ്പനകൾ കരിക്കുകയും മുറിക്കുകയും ചെയ്തു. ബുവൈറ എന്നിടത്തായിരുന്നു അവ. അപ്പോൾ ''നിങ്ങൾ വല്ല ഈത്തപ്പനകളെയും മുറിക്കുകയോ ഉപേക്ഷിക്കുകയോ ചെയ്യുന്നുവെങ്കിൽ'' എന്ന് തുടങ്ങുന്ന സൂക്തം അല്ലാഹു ഇറക്കി. ഒരു നിവേദത്തിൽ ഇപ്രകാരമുണ്ട്: ഈ വിഷയത്തിൽ അവരുടെ കവി ഇപ്രകാരം പറയുന്നു:
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=226), 1, 'وَفِي رِوَايَةٍ: وَفِيهِ يَقُولُ شَاعِرُهُمْ: فَهَانَ عَلَى سَرَاةِ بَنِي لُؤَيٍّ حَرِيقٌ بِالْبُوَيْرَةِ مُسْتَطِيرُ. (ق,د,ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً إِلَى خَثْعَمٍ، فَاعْتَصَمَ نَاسٌ مِنْهُمْ بِالسُّجُودِ، فَأَسْرَعَ فِيهِمُ الْقَتْلَ، قَالَ: فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ لَهُمْ بِنِصْفِ الْعَقْلِ، وَقَالَ: "أَنَا بَرِيءٌ مِنْ كُلِّ مُسْلِمٍ يُقِيمُ بَيْنَ أَظْهُرِ الْمُشْرِكِينَ". قَالُوا: يَا رَسُولَ اللَّهِ، لِمَ؟ قَالَ: "لَا تَرَاءَى نَارَاهُمَا". (د,ت)', 'ജരീറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഖസ്അം ഗോത്രത്തിലേക്ക് ഒരു സൈന്യത്തെ അയച്ചു. ഗോത്രക്കാരിൽ ചിലർ സുജൂദിൽ കിടന്ന് രക്ഷ തേടി. അപ്പോൾ സൈന്യം അവരെ പെട്ടെന്ന് കൊന്നുകളഞ്ഞു. ഈ വിവരം നബി(സ)യുടെ അടുത്തെത്തുകയും നഷ്ടപരിഹാരത്തുകയുടെ പകുതി അവർക്ക് നൽകണമെന്ന് അവിടന്ന് കൽപിക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "ബഹുദൈവാരാധകർക്കിടയിൽ നിലകൊള്ളുന്ന എല്ലാ മുസ്ലിംകളിൽ നിന്നും ഞാൻ നിരപരാധിയാണ്." അവർ ചോദിച്ചു: എന്ത് കൊണ്ടാണ് റസൂലേ, അത്? റസൂൽ(സ) പറഞ്ഞു: "ആ രണ്ട് കൂട്ടരുടെയും തീ പരസ്പരം കാണരുത് (അകന്ന് കഴിയണം)." (ദ,തു)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 935, 935, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنِ الْعَبَّاسِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ قَالَ لِلزُّبَيْرِ: هَا هُنَا أَمَرَكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَرْكُزَ الرَّايَةَ. (خ)', 'അബ്ബാസ്(റ): അവർ സുബൈർ(റ)വിനോട് പറഞ്ഞു: ഇവിടെ കൊടി നാട്ടാൻ താങ്കളോട് നബി(സ) കൽപിച്ചു. (ബു)', 'الْعَبَّاسِ', 'അബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 935, 935, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا، وَقَدْ سُئِلَ عَنْ رَايَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا كَانَتْ؟ فَقَالَ: كَانَتْ سَوْدَاءَ مُرَبَّعَةً مِنْ نَمِرَةٍ. (د,ت)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ)യുടെ കൊടി എങ്ങിനെയായിരുന്നുവെന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് വരയുള്ള ചതുരത്തിലുള്ള കറുത്ത കൊടിയായിരുന്നു. (ദ,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 935, 935, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، يَرْفَعُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ لِوَاؤُهُ يَوْمَ دَخَلَ مَكَّةَ أَبْيَضَ. (د,ن,جه)', 'ജാബിർ(റ): അവർ ഹദീസിനെ നബി(സ)യിലേക്ക് ഉയർത്തിപ്പറയുന്നു: മക്കയിൽ പ്രവേശിച്ച ദിവസം നബി(സ)യുടെ പതാക വെളുത്തതായിരുന്നു. (ദ,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 935, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ سِمَاكٍ، عَنْ رَجُلٍ مِنْ قَوْمِهِ، عَنْ آخَرَ مِنْهُمْ، قَالَ: رَأَيْتُ رَايَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفْرَاءَ. (د)', 'സിമാക്(റ): തന്റെ സമൂഹത്തിലെ ഒരുത്തനിൽ നിന്നും അദ്ദേഹം അവരിൽപെട്ട മറ്റൊരാളിൽ നിന്നും നിവേദനം: റസൂൽ(സ)യുടെ കൊടി മഞ്ഞയായിരുന്നെന്ന് ഞാൻ കണ്ടു. (ദ)', 'سِمَاكٍ، عَنْ رَجُلٍ مِنْ قَوْمِهِ، عَنْ آخَرَ مِنْهُمْ، قَالَ', 'സിമാക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ رَايَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَوْدَاءَ، وَلِوَاؤُهُ أَبْيَضَ. حَسَنٌ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ കൊടി കറുത്തതും പതാക വെളുത്തതുമായിരുന്നു. ഹദീസ് ഹസനാണ്. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنِ الْحَارِثِ بْنِ حَسَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمْتُ الْمَدِينَةَ، فَرَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا عَلَى الْمِنْبَرِ، وَبِلَالٌ قَائِمٌ بَيْنَ يَدَيْهِ مُتَقَلِّدٌ سَيْفًا، وَإِذَا رَايَةٌ سَوْدَاءُ، فَقُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذَا عَمْرُو بْنُ الْعَاصِ، قَدِمَ مِنْ غَزَاةٍ. (ت,جه)', 'ഹാരിസുബ്നു ഹസ്സാൻ(റ): ഞാൻ മദീനയിലെത്തി. അപ്പോൾ നബി(സ) മിമ്പറിൽ നിൽക്കുന്നതും മുന്നിൽ വാളേന്തി ബിലാൽ(റ) നിൽക്കുന്നതും ഞാൻ കണ്ടു. അവിടെ ഒരു കറുത്ത കൊടിയുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: ആരാണത്? അവർ പറഞ്ഞു: യുദ്ധം കഴിഞ്ഞ് മടങ്ങിയെത്തിയ അംറുബ്നുൽ ആസ്വാണത്. (തു,ജ)', 'الْحَارِثِ بْنِ حَسَّانَ', 'ഹാരിസുബ്നു ഹസ്സാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَكْثَمَ بْنِ الْجَوْنِ الْخُزَاعِيِّ: "يَا أَكْثَمُ، اغْزُ مَعَ غَيْرِ قَوْمِكَ يَحْسُنْ خُلُقُكَ، وَتَكْرُمْ عَلَى رُفَقَائِكَ. يَا أَكْثَمُ، خَيْرُ الرُّفَقَاءِ أَرْبَعَةٌ، وَخَيْرُ السَّرَايَا أَرْبَعُمِائَةٍ، وَخَيْرُ الْجُيُوشِ أَرْبَعَةُ آلَافٍ. وَلَنْ يُغْلَبَ اثْنَا عَشَرَ أَلْفًا مِنْ قِلَّةٍ". ضَعِيفٌ. (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അക്സമുബ്നു ജൗനിൽഖുസാഇ(റ)വിനോട് പറഞ്ഞു: "അക്സമേ, നിന്റെ സമൂഹമല്ലാത്തവരോടൊപ്പം നീ യുദ്ധം ചെയ്യുക, എങ്കിൽ നിന്റെ സ്വഭാവം നന്നാവും, നിന്റെ സുഹൃത്തുകളോട് നീ മാന്യതയുള്ളവനാകും. അക്സമേ, സുഹൃത്തുക്കളിൽ ഏറ്റവും ഉൽകൃഷ്ടമായത് നാല് പേരാണ്. യുദ്ധ സംഘങ്ങളിൽ ഏറ്റവും ഉത്തമമായത് നാനൂറ് പേരാണ്. സൈന്യങ്ങളിൽ ഏറ്റവും ഉത്തമമായത് നാലായിരം പേരാണ്. പന്ത്രണ്ടായിരം പേർ കുറവ് മൂലം പരാചയപ്പെടുകയില്ല." ഹദീസ് ബലഹീനമാണ്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نَتَحَدَّثُ أَنَّ أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانُوا يَوْمَ بَدْرٍ ثَلَاثَ مِائَةٍ وَبِضْعَةَ عَشَرَ، عَلَى عِدَّةِ أَصْحَابِ طَالُوتَ، مَنْ جَازَ مَعَهُ النَّهَرَ، وَمَا جَازَ مَعَهُ إِلَّا مُؤْمِنٌ. (خ,جه)', 'ബറാഉബ്നു ആസിബ്(റ): ബദ്ർ ദിനത്തിൽ തിരുദൂതർ(സ)യുടെ അനുചരർ മൂന്നൂറ്റിപ്പത്തിൽചില്ലാനം പേരാണുണ്ടായിരുന്നത് എന്ന് ഞങ്ങൾ പറയാറുണ്ടായിരുന്നു. ത്വാലൂതിന്റെ കൂടെ പുഴമുറിച്ചു കടന്ന തന്റെ അനുചരരുടെ എണ്ണം തന്നെ. അദ്ദേഹത്തിന്റെ കൂടെ സത്യവിശാസികൾ മാത്രമേ പുഴമുറിച്ചു കടന്നിരുന്നുള്ളൂ. (ബു,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ أَبِي الْوَرْدِ رَضِيَ اللَّهُ عَنْهُ – صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَ: إِيَّاكُمْ وَالسَّرِيَّةَ الَّتِي إِنْ لَقِيَتْ فَرَّتْ، وَإِنْ غَنِمَتْ غَلَّتْ. (جه)', 'നബി(സ)യുടെ അനുചരനായ അബുൽവർദ്(റ): ശത്രുവിനെ കണ്ടാൽ പേടിച്ചോടുകയും യുദ്ധമുതൽ ലഭിച്ചാൽ പൂഴ്ത്തിവെക്കുകയും ചെയ്യുന്ന യുദ്ധസംഘത്തെ നിങ്ങൾ സൂക്ഷിക്കുക. (ജ)', 'أَبِي الْوَرْدِ', 'നബി(സ)യുടെ അനുചരനായ അബുൽവർദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى بَنِي لَحْيَانَ: "لِيَخْرُجْ مِنْ كُلِّ رَجُلَيْنِ رَجُلٌ". ثُمَّ قَالَ لِلْقَاعِدِ: "أَيُّكُمْ خَلَفَ الْخَارِجَ فِي أَهْلِهِ وَمَالِهِ بِخَيْرٍ كَانَ لَهُ مِثْلُ نِصْفِ أَجْرِ الْخَارِجِ". (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): "ഓരോ ഈരണ്ടു പേരിലും ഒരാൾ യുദ്ധത്തിന് പുറപ്പെടണം" എന്ന് ബനൂ ലിഹ്യാൻ ഗേത്രക്കാരിലേക്ക് നബി(സ) സന്ദേശമയച്ചു. ശേഷം യുദ്ധത്തിന് പോകാത്തവരോട് പറഞ്ഞു: "നിങ്ങളിൽ ആരാണോ യുദ്ധത്തിന് പോകുന്നവരുടെ കുടുംബത്തിൽ നല്ല രീതിയിൽ അവർക്ക് പകരക്കാരനാകുന്നത്, അവന് യുദ്ധത്തിന് പോകുന്നവരുടെ പ്രതിഫലത്തിന്റെ പകുതി ലഭിക്കുന്നതാണ്." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، ائْذَنْ لِي فِي السِّيَاحَةِ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ سِيَاحَةَ أُمَّتِي الْجِهَادُ فِي سَبِيلِ اللَّهِ تَعَالَى". (د)', 'അബൂഉമാമ(റ): ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് യാത്രക്ക് അനുവാദം നൽകിയാലും. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള വിശുദ്ധ യുദ്ധമാണ് എന്റെ സമുദായത്തിന്റെ തീർത്ഥയാത്ര." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ صَخْرٍ الْغَامِدِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي بُكُورِهَا". وَكَانَ إِذَا بَعَثَ سَرِيَّةً أَوْ جَيْشًا بَعَثَهُمْ مِنْ أَوَّلِ النَّهَارِ. وَكَانَ صَخْرٌ رَجُلًا تَاجِرًا، وَكَانَ يَبْعَثُ تِجَارَتَهُ مِنْ أَوَّلِ النَّهَارِ، فَأَثْرَى وَكَثُرَ مَالُهُ. (د,ت,جه)', 'സഖ്റുൽ ഗാമിദി(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, എന്റെ സമുദായത്തിന് പ്രഭാത സമയങ്ങളിൽ നീ അനുഗ്രഹം നൽകണേ." നബി(സ) യുദ്ധസംഘത്തെയോ സൈന്യത്തെയോ അയക്കുകയാണെങ്കിൽ പകലിന്റെ ആദ്യ സമയത്ത് അവരെ അയക്കുമായിരുന്നു. സ്ഖ്ർ(റ) കച്ചവടക്കാരനായിരുന്നു. തന്റെ കച്ചവട സംഘത്തെ പകലിന്റെ ആദ്യ സമയത്തായിരുന്നു അദ്ദേഹം അയച്ചിരുന്നത്. അങ്ങനെ അദ്ദേഹത്തിന് ലാഭം ലഭിക്കുകയും സമ്പത്ത് അധികമാവുകയും ചെയ്തു. (ദ,തു,ജ)', 'صَخْرٍ الْغَامِدِيِّ', 'സഖ്റുൽ ഗാമിദി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالدُّلْجَةِ، فَإِنَّ الْأَرْضَ تُطْوَى بِاللَّيْلِ". (د)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ രാത്രിയുടെ ആദ്യസമയം സഞ്ചരിക്കുക. കാരണം രാത്രിയിൽ ഭൂമി ചുരുട്ടപ്പെടും." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 938, 938, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُرْسِلُوا مَوَاشِيَكُمْ إِذَا غَابَتِ الشَّمْسُ حَتَّى تَذْهَبَ فَحْمَةُ الْعِشَاءِ، فَإِنَّ الشَّيَاطِينَ تَعِيثُ إِذَا غَابَتِ الشَّمْسُ حَتَّى تَذْهَبَ فَحْمَةُ الْعِشَاءِ". (م,د)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സൂര്യനസ്തമിച്ചാൽ രാത്രിയുടെ ആദ്യഭാഗത്തുള്ള ഇരുട്ട് പോകും വരെ നിങ്ങളുടെ മൃഗങ്ങളെ നിങ്ങൾ പറഞ്ഞയക്കരുത്. കാരണം സൂര്യനസ്തമിച്ച് രാത്രിയുടെ ആദ്യഭാഗത്തുള്ള ഇരുട്ട് പോകും വരെ പിശാച് ഫസാദ് ഉണ്ടാക്കിക്കൊണ്ടിരിക്കും." (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 938, 938, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَلَّمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْرُجُ فِي سَفَرٍ إِلَّا يَوْمَ الْخَمِيسِ. (خ,د)', 'കഅ്ബുബ്നു മാലിക്(റ): റസൂൽ(സ) വ്യാഴാഴ്ചയല്ലാത്ത ദിവസങ്ങളിൽ യാത്ര പോകുന്നത് വളരെ കുറവായിരുന്നു. (ബു,ദ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 938, 938, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ قَالَ: "اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ. اللَّهُمَّ اطْوِ لَنَا الْأَرْضَ، وَهَوِّنْ عَلَيْنَا السَّفَرَ". (م,د,ن)', 'അബൂഹുറൈറ(റ): യാത്ര ചെയ്യുകയാണെങ്കിൽ റസൂൽ(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, യാത്രയിലെ കൂട്ടുകാരനും കുടുംബത്തിലെ പ്രതിനിധിയും നീയാണ്. അല്ലാഹുവേ, യാത്രയിലെ ബുദ്ധിമുട്ടിൽ നിന്നും ദുഃഖകരമായ മടക്കത്തിൽ നിന്നും കുടുംബത്തിലുള്ള മോശമായ പരിചരണത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, നീ ഞങ്ങൾക്ക് ഭൂമിയെ ചുരുട്ടിത്തരികയും യാത്ര പ്രയാസ രഹിതമാക്കുകയും ചെയ്യേണമേ." (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 938, 938, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اسْتَوَى عَلَى بَعِيرِهِ خَارِجًا إِلَى سَفَرٍ كَبَّرَ ثَلَاثًا، ثُمَّ قَالَ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ. وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ} [الزخرف: ١٣، ١٤]. اللَّهُمَّ إِنِّي أَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى. اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، اللَّهُمَّ اطْوِ لَنَا الْبُعْدَ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ وَالْمَالِ". وَإِذَا رَجَعَ قَالَهُنَّ، وَزَادَ فِيهِنَّ: "آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ". وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجُيُوشُهُ إِذَا عَلَوُا الثَّنَايَا كَبَّرُوا، وَإِذَا هَبَطُوا سَبَّحُوا، فَوُضِعَتِ الصَّلَاةُ عَلَى ذَلِكَ. (م,د,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) വല്ല യാത്രകൾക്കും പുറപ്പെട്ട് തന്റെ ഒട്ടകപ്പുറത്ത് കയറിയാൽ മൂന്ന് പ്രാവശ്യം തക്ബീർ ചൊല്ലുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു: "നമുക്ക് ഇതിനെ കീഴ്പ്പെടുത്തിത്തന്നവൻ എത്ര പരിശുദ്ധൻ, നമുക്കിതിനെ ഇണക്കുവാൻ കഴിയുമായിരുന്നില്ല. നാം നമ്മുടെ നാഥനിലേക്ക് മടങ്ങുന്നവരാണ്. (സുഖ്റുഫ്: 13,14) അല്ലാഹുവേ, ഞങ്ങളുടെ ഈ യാത്രയിൽ നന്മയെയും ഭക്തിയെയും നീ തൃപ്തിപ്പെടുന്ന കർമ്മങ്ങളെയും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, ഈ യാത്ര ഞങ്ങൾക്ക് എളുപ്പമാക്കിത്തരണേ. അല്ലാഹുവേ, ദൂരങ്ങളെ ഞങ്ങൾക്ക് നീ ചുരുക്കിത്തരണേ. അല്ലാഹുവേ, യാത്രയിലെ കൂട്ടുകാരനും മുതലിലും കുടുംബത്തിലുമുള്ള പ്രതിനിധിയും നീയാണ്." യാത്രയിൽ നിന്ന് മടങ്ങിയാൽ റസൂൽ(സ) ഇപ്പോൾ പറഞ്ഞ കാര്യങ്ങൾക്കൊപ്പം ഇതും പറയാറുണ്ടായിരുന്നു: "ഞങ്ങൾ നാഥനിലേക്ക് മടങ്ങുന്നവരും പശ്ചാത്തപിക്കുന്നവരും അവനെ ആരാധിക്കുന്നവരും തങ്ങളുടെ നാഥനെ സ്തുതിക്കുന്നവരുമാണ്." നബി(സ)യും തന്റെ സൈന്യങ്ങളും മലമുകളിൽ കയറിയാൽ തക്ബീർ ചൊല്ലുകയും അതിൽ നിന്നിറങ്ങിയാൽ തസ്ബീഹ് ചൊല്ലുകയും ചെയ്യുമായിരുന്നു. പിന്നീട് നിസ്കാരം അപ്രകാരമാണ് നിശ്ചയിക്കപ്പെട്ടത്. (മു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], 'الزخرف: ١٣، ١٤', null, 938, 939, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا إِذَا صَعِدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا. (خ)', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരി(റ): ഞങ്ങൾ (താഴ്വരയിൽ നിന്ന്) കയറുന്ന നേരത്ത് തക്ബീറും ഇറങ്ങുന്ന നേരത്ത് തസ്ബീഹും ചൊല്ലുമായിരുന്നു. (ബു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 939, 939, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ قَزَعَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: هَلُمَّ أُوَدِّعْكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ". (د,ت,جه)', 'ഖസഅ(റ): ഇബ്നുഉമർ(റ) എന്നോട് പറഞ്ഞു: വരിക, റസൂൽ(സ) എന്നെ യാത്രയാക്കിയതുപോലെ ഞാൻ നിന്നെയും യാത്രയാക്കാം: "നിന്റെ കർമ്മത്തിന്റെ അന്ത്യങ്ങളെയും സൂക്ഷിപ്പ്സ്വത്തിനെയും ദീനിനെയും ഞാൻ അല്ലാഹുവിനെ ഏൽപ്പിക്കുന്നു." (ദ,തു,ജ)', 'قَزَعَةَ', 'ഖസഅ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 939, 939, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ عَبْدِ اللَّهِ الْخَطْمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَسْتَوْدِعَ الْجَيْشَ قَالَ: "أَسْتَوْدِعُ اللَّهَ دِينَكُمْ وَأَمَانَتَكُمْ وَخَوَاتِيمَ أَعْمَالِكُمْ". (د)', 'അബ്ദുല്ലാഹിബ്നുൽ ഖത്മി(റ): നബി(സ) സൈന്യത്തെ യാത്രയാക്കാൻ ഉദ്ദേശിച്ചാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "നിങ്ങളുടെ കർമ്മങ്ങളുടെ അന്ത്യങ്ങളെയും സൂക്ഷിപ്പ് സ്വത്തിനെയും ദീനിനെയും ഞാൻ അല്ലാഹുവിനെ ഏൽപിക്കുന്നു." (ദ)', 'عَبْدِ اللَّهِ الْخَطْمِيِّ', 'അബ്ദുല്ലാഹിബ്നുൽ ഖത്മി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 939, 939, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ، وَأُتِيَ بِدَابَّةٍ لِيَرْكَبَهَا، فَلَمَّا وَضَعَ رِجْلَهُ فِي الرِّكَابِ قَالَ: بِسْمِ اللَّهِ، فَلَمَّا اسْتَوَى عَلَى ظَهْرِهَا قَالَ: الْحَمْدُ لِلَّهِ، ثُمَّ قَالَ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ. وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ} [الزخرف: ١٣،١٤]. ثُمَّ قَالَ: الْحَمْدُ لِلَّهِ، ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ، ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. ثُمَّ ضَحِكَ، فَقِيلَ: يَا أَمِيرَ الْمُؤْمِنِينَ، مِنْ أَيِّ شَيْءٍ ضَحِكْتَ؟ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ كَمَا فَعَلْتُ، ثُمَّ ضَحِكَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، مِنْ أَيِّ شَيْءٍ ضَحِكْتَ؟ قَالَ: "إِنَّ رَبَّكَ يَعْجَبُ مِنْ عَبْدِهِ إِذَا قَالَ: اغْفِرْ لِي ذُنُوبِي، يَعْلَمُ أَنَّهُ لَا يَغْفِرُ الذُّنُوبَ غَيْرِي". (د,ت)', 'അലി(റ): അവർക്ക് യാത്ര ചെയ്യാൻ ഒരു വാഹനം കൊണ്ടുവന്നു. ചവിട്ടുപടിയിൽ കാൽ വെച്ചപ്പോൾ അവർ പറഞ്ഞു: ബിസ്മില്ല. പുറത്തുകയറിയിരുന്നപ്പോൾ അവർ പറഞ്ഞു: അൽഹംദുലില്ലാഹ്. ശേഷം പറഞ്ഞു: ''ഈ വാഹനത്തെ നമുക്ക് കീഴ്പ്പെടുത്തിത്തന്നവൻ എത്ര പരിശുദ്ധൻ, നാമതിനെ കീഴ്പെടുത്താൻ കഴിയുന്നവരായിരുന്നില്ല, നാം നമ്മുടെ നാഥനിലേക്ക് മടങ്ങുന്നവരാണ്.'' (സുഖ്റുഫ്: 13, 14) ശേഷം അൽഹംദുലില്ലാഹ് എന്ന് മൂന്ന് പ്രാവശ്യവും അല്ലാഹു അക്ബർ എന്ന് മൂന്ന് പ്രാവശ്യവും പറഞ്ഞു: ശേഷം ''നിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു. ഞാൻ എന്റെ ശരീരത്തോട് അക്രമം പ്രവർത്തിച്ചവനായിരിക്കുന്നു. അതുകൊണ്ട് നീ എനിക്ക് പൊറുത്തുതരണേ, കാരണം ദോഷങ്ങളെ പൊറുക്കുന്നവൻ നീ മാത്രമാണ്'' എന്ന് പറഞ്ഞു. എന്നിട്ട് ചിരിച്ചു. അപ്പോൾ അവരോട് ഇപ്രകാരം ചോദിക്കപ്പെട്ടു: അമീറുൽ മുഅ്മിനീനേ, എന്തിനാണ് അങ്ങ് ചിരിച്ചത്? അവർ പറഞ്ഞു: ഞാൻ ചെയ്യുന്നത് പോലെ നബി(സ) ചെയ്യുന്നതും ശേഷം ചിരിക്കുന്നതും ഞാൻ കണ്ടു, അപ്പോൾ ഞാൻ ചോദിച്ചു: റസൂലേ, എന്തിനാണ് അങ്ങ് ചിരിച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "താനല്ലാതെ ദോഷം പൊറുക്കുന്ന ആരുമില്ല എന്ന് മനസ്സിലാക്കിയിട്ടും ''നീ എന്റെ ദോഷങ്ങൾ പൊറുത്തുതരണേ'' എന്ന് ഒരു അടിമ പറയുമ്പോൾ അവന്റെ കാര്യത്തിൽ നിന്റെ റബ്ബ് സന്തോഷിക്കും." (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الزخرف: ١٣،١٤', null, 939, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ، يَمْنَعُ أَحَدَكُمْ نَوْمَهُ وَطَعَامَهُ وَشَرَابَهُ، فَإِذَا قَضَى أَحَدُكُمْ نَهْمَتَهُ مِنْ وَجْهِهِ فَلْيُعَجِّلْ إِلَى أَهْلِهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "യാത്ര ശിക്ഷയുടെ ഒരു ഭാഗമാണ്, അത് നിങ്ങളിൽ ഒരാളുടെ ഉറക്കത്തെയും ഭക്ഷണത്തെയും പാനീയത്തെയും തടയുന്നു. അതിനാൽ നിങ്ങളിലാരുടെയെങ്കിലും യാത്രാലക്ഷ്യം പൂർത്തിയായാൽ തന്റെ കുടുംബത്തിലേക്ക് വേഗം മടങ്ങിക്കൊള്ളട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَرِضَ الْعَبْدُ أَوْ سَافَرَ كُتِبَ لَهُ مِثْلُ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا". (خ)', 'അബൂമൂസാ(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമ രോഗിയാവുകയോ യാത്രപോകുകയോ ചെയ്താൽ ആരോഗ്യമുള്ളപ്പോഴും നാട്ടിലുണ്ടാവുമ്പോഴുമുള്ള പ്രവർത്തനത്തിന്റെ അതേ പ്രതിഫലം അവന് എഴുതപ്പെടും." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَطْرُقَ الرَّجُلُ أَهْلَهُ لَيْلًا، يَتَخَوَّنُهُمْ أَوْ يَطْلُبُ عَثَرَاتِهِمْ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): രാത്രിയിൽ ഒരുത്തൻ തന്റെ കുടുംബത്തിലേക്ക് മടങ്ങുന്നത് നബി(സ) നിരോധിച്ചു. കാരണം, അവർ വഞ്ചിച്ചുവെന്ന് ഇവൻ സംശയിക്കുന്നുവെന്നും അവരുടെ ന്യൂനത ഇവൻ തേടിപ്പിടിക്കുകയാണെന്നും അവർക്ക് തോന്നും. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَطْرُقُ أَهْلَهُ لَيْلًا، وَكَانَ يَأْتِيهِمْ غُدْوَةً أَوْ عَشِيَّةً. (م)', 'അനസ്(റ): റസൂൽ(സ) രാത്രിയിൽ തന്റെ കുടുംബത്തിലേക്ക് മടങ്ങാറില്ലായിരുന്നു. പ്രഭാതത്തിലോ പ്രദോഷത്തിലോ ആയിരുന്നു നബി(സ) അവരിലേക്ക് ചെന്നിരുന്നത്. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُ أَنْ يَأْتِيَ الرَّجُلُ أَهْلَهُ طُرُوقًا. (ق,د,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരാൾ തന്റെ കുടുംബത്തിലേക്ക് രാത്രി മടങ്ങിയെത്തുന്നത് റസൂൽ(സ) വെറുത്തിരുന്നു. (ബു,മു,ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَحْسَنَ مَا دَخَلَ الرَّجُلُ عَلَى أَهْلِهِ إِذَا قَدِمَ مِنْ سَفَرٍ أَوَّلُ اللَّيْلِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ യാത്രകഴിഞ്ഞെത്തിയാൽ തന്റെ കുടുംബത്തിലേക്ക് പ്രവേശിക്കാൻ പറ്റിയ നല്ല സമയം രാത്രിയുടെ ആദ്യ ഭാഗമാണ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَلَمَّا ذَهَبْنَا لِنَدْخُلَ قَالَ: "أَمْهِلُوا، حَتَّى نَدْخُلَ لَيْلًا، لِكَيْ تَمْتَشِطَ الشَّعِثَةُ وَتَسْتَحِدَّ الْمُغِيبَةُ". (ق,د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ)യോടൊപ്പമുള്ള യാത്രയ്ക്കു ശേഷം ഞങ്ങൾ വീടുകളിൽ പ്രവേശിക്കാനൊരുങ്ങിയപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അൽപം വൈകിക്കുക, മുടി ജടപിടിച്ച സ്ത്രീകൾ അത് വാർന്നതിന് ശേഷവും, ഭർത്താവ് ഒപ്പമില്ലാതിരുന്ന സ്ത്രീകൾ ഗുഹ്യരോമങ്ങൾ നീക്കിയതിനു ശേഷവും നമുക്ക് രാത്രിയിൽ പ്രവേശിക്കാം." (ബു,മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا سَافَرْتُمْ فِي الْخِصْبِ فَأَعْطُوا الْإِبِلَ حَظَّهَا مِنَ الْأَرْضِ، وَإِذَا سَافَرْتُمْ فِي السَّنَةِ فَأَسْرِعُوا عَلَيْهَا السَّيْرَ، وَإِذَا عَرَّسْتُمْ بِاللَّيْلِ فَاجْتَنِبُوا الطَّرِيقَ، فَإِنَّهَا مَأْوَى الْهَوَامِّ بِاللَّيْلِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ക്ഷേമ കാലത്ത് നിങ്ങൾ യാത്ര ചെയ്യുകയാണെങ്കിൽ ഒട്ടകത്തിന് ഭൂമിയിൽ നിന്നുള്ള അതിന്റെ വിഹിതം നൽകുക. ക്ഷാമകാലത്താണ് നിങ്ങൾ യാത്ര ചെയ്യുന്നതെങ്കിൽ അതിന്മേലുള്ള യാത്ര വേഗത്തിലാക്കുക. രാത്രിയിൽ തമ്പടിക്കുകയാണെങ്കിൽ വഴി ഒഴിച്ചിടുക. കാരണം, രാത്രിയിൽ അവ ഇഴജന്തുക്കളുടെ സങ്കേതമാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَتَى أَحَدُكُمْ عَلَى مَاشِيَةٍ: فَإِنْ كَانَ فِيهَا صَاحِبُهَا فَلْيَسْتَأْذِنْهُ، فَإِنْ أَذِنَ لَهُ فَلْيَحْتَلِبْ وَلْيَشْرَبْ، فَإِنْ لَمْ يَكُنْ فِيهَا فَلْيُصَوِّتْ ثَلَاثًا، فَإِنْ أَجَابَهُ فَلْيَسْتَأْذِنْهُ، وَإِلَّا فَلْيَحْتَلِبْ وَلْيَشْرَبْ وَلَا يَحْمِلْ". (د,ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും നാൽക്കാലികളുടെ അടുത്ത് കൂടെ സഞ്ചരിക്കുകയാണെങ്കിൽ, അവിടെ അതിന്റെ ഉടമയുണ്ടെങ്കിൽ അദ്ദേഹത്തോട് സമ്മതം ചോദിക്കുക. സമ്മതം ലഭിച്ചാൽ കറക്കുകയും കുടിക്കുകയും ചെയ്ത് കൊള്ളട്ടെ. അതിന്റെ ഉടമ അവിടെയില്ലെങ്കിൽ മൂന്ന് പ്രാവശ്യം ശബ്ദിക്കുകയും ഉടമ ഉത്തരം നൽകിയാൽ അവനോട് സമ്മതം ചോദിക്കുകയും ചെയ്യണം. ഇല്ലെങ്കിൽ അവൻ കറക്കുകയും കുടിക്കുകയും ചെയ്യട്ടെ, സൂക്ഷിക്കാനുള്ളത് ചുമക്കരുത്." (ദ,തു)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 941, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ عَبَّادِ بْنِ شُرَحْبِيلَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَصَابَتْنِي سَنَةٌ، فَدَخَلْتُ حَائِطًا مِنْ حِيطَانِ الْمَدِينَةِ فَفَرَكْتُ سُنْبُلًا، فَأَكَلْتُ وَحَمَلْتُ فِي ثَوْبِي، فَجَاءَ صَاحِبُهُ فَضَرَبَنِي وَأَخَذَ ثَوْبِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: "مَا عَلَّمْتَ إِذْ كَانَ جَاهِلًا، وَلَا أَطْعَمْتَ إِذْ كَانَ جَائِعًا. أَوْ قَالَ: سَاغِبًا". وَأَمَرَهُ فَرَدَّ عَلَيَّ ثَوْبِي، وَأَعْطَانِي وَسْقًا أَوْ نِصْفَ وَسْقٍ، مِنْ طَعَامٍ. (د,ن,جه)', 'അബ്ബാദുബ്നു ശുറഹ്ബീൽ(റ): എനിക്ക് ക്ഷാമം ബാധിച്ചു. അപ്പോൾ ഞാൻ മദീനയിലെ ഒരു തോട്ടത്തിൽ പ്രവേശിച്ച് ഒരു കുല പൊട്ടിച്ചു. ഞാൻ ഭക്ഷിക്കുകയും വസ്ത്രത്തിൽ ചുമന്നുകൊണ്ടുപോവുകയും ചെയ്തു. അപ്പോൾ അതിന്റെ ഉടമ വരികയും എന്നെ അടിക്കുകയും എന്റെ വസ്ത്രം പിടിച്ചുവെക്കുകയും ചെയ്തു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് വേവലാതി പറഞ്ഞു. അപ്പോൾ അവിടന്ന് അയാളോട് പറഞ്ഞു: "അദ്ദേഹം അറിവില്ലാത്തവനായിട്ടും താങ്കൾ അദ്ദേഹത്തിന് പഠിപ്പിച്ചു കൊടുത്തില്ല. അദ്ദേഹം വിശന്നവനായിട്ടും താങ്കൾ അദ്ദേഹത്തിന് ഭക്ഷണം നൽകിയില്ല." ശേഷം നബി(സ) കൽപിച്ചതനുസരിച്ച് അദ്ദേഹം എന്റെ വസ്ത്രം തിരിച്ചുതരികയും ഒരു വസ്ഖോ അല്ലെങ്കിൽ അതിന്റെ പകുതിയോ ഭക്ഷണം എനിക്ക് തരികയും ചെയ്തു. (ദ,ന,ജ)', 'عَبَّادِ بْنِ شُرَحْبِيلَ', 'അബ്ബാദുബ്നു ശുറഹ്ബീൽ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 942, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ رَافِعِ بْنِ عَمْرٍو الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ غُلَامًا أَرْمِي نَخْلَ الْأَنْصَارِ، فَأُتِيَ بِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا غُلَامُ، لِمَ تَرْمِي النَّخْلَ". قَالَ: آكُلُ، قَالَ: "فَلَا تَرْمِ النَّخْلَ، وَكُلْ مِمَّا يَسْقُطُ فِي أَسْفَلِهَا". ثُمَّ مَسَحَ رَأْسَهُ فَقَالَ: "اللَّهُمَّ أَشْبِعْ بَطْنَهُ". (د,ت,جه)', 'റാഫിഉബ്നു അംറുൽ ഗിഫ്ഫാരി(റ): ഞാൻ കുട്ടിയായിരുന്ന കാലത്ത് ഒരിക്കൽ അൻസാറുകളുടെ ഈത്തപ്പനയിലേക്ക് എറിയുകയായിരുന്നു. അപ്പോൾ എന്നെ നബി(സ)യുടെ അടുത്തെത്തിക്കപ്പെട്ടു. നബി(സ) ചോദിച്ചു: "കുട്ടീ, നീ എന്തിനാണ് ഈത്തപ്പനയിലേക്കെറിയുന്നത്?" ഞാൻ പറഞ്ഞു: ഭക്ഷിക്കാൻ വേണ്ടിയാണ്. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ ഈത്തപ്പനയിലെറിയരുത്, അതിന്റെ ചുവട്ടിൽ ചാടുന്നത് നീ ഭക്ഷിക്കുക." ശേഷം നബി(സ) അവന്റെ തലയിൽ തലോടി. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവേ, നീയിവന്റെ വയറ് നിറച്ച് കൊടുക്കണേ." (ദ,തു,ജ)', 'رَافِعِ بْنِ عَمْرٍو الْغِفَارِيِّ', 'റാഫിഉബ്നു അംറുൽ ഗിഫ്ഫാരി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 942, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحْلِبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ بِغَيْرِ إِذْنِهِ، أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ، فَتُكْسَرَ خِزَانَتُهُ، فَيُنْتَقَلَ طَعَامُهُ؟ فَإِنَّمَا تَخْزُنُ لَهُمْ ضُرُوعُ مَوَاشِيهِمْ أَطْعِمَتَهُمْ، فَلَا يَحْلِبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلَّا بِإِذْنِهِ". (ق,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളും സമ്മതം കൂടാതെ മറ്റുള്ളവരുടെ കാലിയെ കറക്കരുത്. നിങ്ങളുടെ സൂക്ഷിപ്പുസ്ഥലത്ത് ആരെങ്കിലും വന്ന് വിലക്ക് പൊട്ടിച്ച് അതിലുള്ള ഭക്ഷണം പരക്കെ വിതറപ്പെടുന്നത് നിങ്ങൾക്ക് ഇഷ്ടപ്പെടുമോ? എന്നാൽ കാലികളുടെ അകിടുകൾ അവയുടെ ഉടമസ്ഥരുടെ ഭക്ഷണം സൂക്ഷിച്ചിരിക്കുകയാണ്. അതിനാൽ ഒരാളും സമ്മതം കൂടാതെ മറ്റൊരാളുടെ കാലിയെ കറക്കരുത്." (ബു,മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 942, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَنَّ النَّاسَ يَعْلَمُونَ مَا أَعْلَمُ مِنَ الْوِحْدَةِ مَا سَرَى رَاكِبٌ بِلَيْلٍ – يَعْنِي – وَحْدَهُ". (خ,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏകാന്ത സഞ്ചാരത്തിലുള്ള പ്രശ്നം ഞാനറിയും പോലെ ജനങ്ങൾ അറിയുകയായിരുന്നെങ്കിൽ ഒരാളും രാത്രിയിൽ തനിയെ യാത്ര ചെയ്യുമായിരുന്നില്ല." (ബു,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرَّاكِبُ شَيْطَانٌ، وَالرَّاكِبَانِ شَيْطَانَانِ، وَالثَّلَاثَةُ رَكْبٌ". (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു യാത്രികൻ പിശാചാണ്, രണ്ട് യാത്രക്കാർ രണ്ടു പിശാചുകളാണ്, മൂന്ന് പേരുള്ളതാണ് യാത്രാ സംഘം." (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَجَ ثَلَاثَةٌ فِي سَفَرٍ فَلْيُؤَمِّرُوا أَحَدَهُمْ". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റൂസൂൽ(സ) പറഞ്ഞു: "മൂന്നുപേർ യാത്ര പുറപ്പെട്ടാൽ തങ്ങളിലൊരാളെ നേതാവാക്കിക്കൊള്ളട്ടെ." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُسَافَرَ بِالْقُرْآنِ إِلَى أَرْضِ الْعَدُوِّ. قَالَ مَالِكٌ: أُرَاهُ مَخَافَةَ أَنْ يَنَالَهُ الْعَدُوُّ. (ق,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഖുർആനുമായി ശത്രുനാട്ടിലേക്ക് യാത്ര പോകുന്നത് റസൂൽ(സ) നിരോധിച്ചു. മാലിക്(റ) പറഞ്ഞു: ഖുർആൻ ശത്രുക്കൾക്ക് ലഭിക്കുമോ എന്ന് പേടിച്ചിട്ടാണത് എന്നാണ് എന്റെ അഭിപ്രായം. (ബു,മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا سافر فَأَقْبَلَ اللَّيْلُ قَالَ: "يَا أَرْضُ، رَبِّي وَرَبُّكِ اللهُ، أَعُوذُ بِاللهِ مِنْ شَرِّكِ وَشَرِّ مَا فِيكِ، وَشَرِّ مَا خُلِقَ فِيكِ، وَمِنْ شَرِّ مَا يَدِبُّ عَلَيْكِ، وَأَعُوذُ بِاللهِ مِنْ أَسَدٍ وَأَسْوَدَ، وَمِنَ الْحَيَّةِ وَالْعَقْرَبِ، وَمِنْ سَاكِنِ الْبَلَدِ، وَمِنْ وَالِدٍ وَمَا وَلَدَ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): യാത്രയിലായിരിക്കെ രാത്രി വന്നെത്തിയാൽ റസൂൽ(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "ഭൂമിയേ, എന്റെയും നിന്റെയും നാഥൻ അല്ലാഹുവാണ്. നിന്റെയും നിന്നിലുള്ളതിന്റെയും, നിന്നിൽ സൃഷ്ടിക്കപ്പെട്ടതിന്റെയും, നിന്നിൽ സഞ്ചരിക്കുന്ന സർവ്വത്തിന്റെയും തിന്മയിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. വേട്ടമൃഗങ്ങളിൽ നിന്നും, സർപ്പങ്ങളിൽ നിന്നും, പാമ്പുകളിൽ നിന്നും, തേളുകളിൽ നിന്നും, നാട്ടിൽ താമസിക്കുന്നവരിൽ നിന്നും, പിതാവിൽ നിന്നും, അവന് ജനിക്കുന്ന സന്താനത്തിൽ നിന്നും ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു." (ദ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 944, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا نَزَلْنَا مَنْزِلًا لَا نُسَبِّحُ حَتَّى تُحَلَّ الرِّحَالُ. (د)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ ഒരിടത്ത് വാഹനമിറങ്ങുകയാണെങ്കിൽ ഒട്ടകക്കട്ടിലുകൾ അഴിക്കും മുമ്പ് തസ്ബീഹ് ചൊല്ലാറുണ്ടായിരുന്നില്ല. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 944, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكُنَّا إِذَا أَشْرَفْنَا عَلَى وَادٍ هَلَّلْنَا وَكَبَّرْنَا ارْتَفَعَتْ أَصْوَاتُنَا فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَيُّهَا النَّاسُ، ارْبَعُوا عَلَى أَنْفُسِكُمْ فَإِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا، إِنَّهُ مَعَكُمْ إِنَّهُ سَمِيعٌ قَرِيبٌ". (خ)', 'അബൂമൂസ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പോകുമ്പോൾ താഴ്വരയിൽ നിന്ന് മേൽപ്പോട്ടുകയറുന്ന സമയത്ത് തക്ബീറും തഹ്ലീലും ഉച്ചത്തിൽ ചൊല്ലാറുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ജനങ്ങളേ, നിങ്ങൾ മിതത്വം പാലിക്കുക. നിശ്ചയം അപ്രത്യക്ഷനെയോ ബധിരനെയോ അല്ല നിങ്ങൾ വിളിച്ച് പ്രാർത്ഥിക്കുന്നത്. അവൻ നിങ്ങളോടൊപ്പമുണ്ട്. അവൻ കേൾക്കുന്നവനും സമീപസ്ഥനുമാകുന്നു." (ബു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 944, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَدِمَ مِنْ سَفَرٍ ضُحًى دَخَلَ الْمَسْجِدَ فَصَلَّى رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ. (خ)', 'കഅ്ബ്(റ): നബി(സ) യാത്രകഴിഞ്ഞ് ളുഹാ സമയത്ത് മടങ്ങിയെത്തിയാൽ പള്ളിയിൽ പ്രവേശിച്ച് ഇരിക്കും മുമ്പ് രണ്ട് റക്അത്ത് നമസ്കരിക്കുമായിരുന്നു. (ബു)', 'كَعْبٍ', 'കഅ്ബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 944, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ أَقْبَلَ مِنْ حَجَّتِهِ دَخَلَ الْمَدِينَةَ، فَأَنَاخَ عَلَى بَابِ مَسْجِدِهِ، ثُمَّ دَخَلَهُ فَرَكَعَ فِيهِ رَكْعَتَيْنِ، ثُمَّ انْصَرَفَ إِلَى بَيْتِهِ، قَالَ نَافِعٌ: فَكَانَ ابْنُ عُمَرَ كَذَلِكَ يَصْنَعُ. (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) തന്റെ ഹജ്ജ് കഴിഞ്ഞ് മദീനയിലെത്തിയപ്പോൾ പള്ളിയുടെ വാതിലിന് മുന്നിൽ ഒട്ടകത്തെ മുട്ട് കുത്തിച്ചു, ശേഷം പള്ളിയിൽ പ്രവേശിച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ വീട്ടിലേക്ക് പോയി. നാഫിഅ്(റ) പറയുന്നു: ഇബ്നുഉമർ(റ)വും അപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 944, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ احْتَبَسَ فَرَسًا فِي سَبِيلِ اللهِ إِيمَانًا بِاللهِ، وَتَصْدِيقًا بِوَعْدِهِ، فَإِنَّ شِبَعَهُ وَرِيَّهُ وَرَوْثَهُ وَبَوْلَهُ فِي مِيزَانِهِ يَوْمَ الْقِيَامَةِ". (خ,ن)', 'അബൂഹുറൈറ: നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലുള്ള വിശ്വാസവും അവന്റെ വാഗ്ദാനത്തിലുള്ള ഉറപ്പും കൈമുതലാക്കി ഒരു കുതിരയെ ദൈവമാർഗത്തിലുള്ള യുദ്ധത്തിന് വേണ്ടി ഒരാൾ തയ്യാർ ചെയ്താൽ അതിന്റെ തീറ്റയും കുടിയും മലവും മൂത്രവുമെല്ലാം വിചാരണനാളിൽ അവന്റെ (നന്മ അളക്കുന്ന) തുലാസിൽ ഉണ്ടാകുന്നതാണ്." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 945, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْبَرَكَةُ فِي نَوَاصِي الْخَيْلِ". (خ,ن)', 'അനസുബ്നു മാലിക്(റ): തിരുദൂതർ (സ) പറഞ്ഞു: "കുതിരയുടെ മൂർദ്ധാവുകളിലാണ് ബറകത്ത്." (ബു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 945, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَبِي قَتَادَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الْخَيْلِ الْأَدْهَمُ، الْأَقْرَحُ، الْمُحَجَّلُ، الْأَرْثَمُ، طَلْقُ الْيَدِ الْيُمْنَى. فَإِنْ لَمْ يَكُنْ أَدْهَمَ فَكُمَيْتٌ عَلَى هَذِهِ الشِّيَةِ". (ت,جه)', 'അബൂഖതാദതുൽ അൻസാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "വലത് കയ്യിൽ വെളുപ്പില്ലാത്തതും മൂക്കും മുകൾ ചുണ്ടും കാലുകളും വെളുത്തതും നെറ്റിയിൽ വ്യക്തമായ വെളുത്ത പുള്ളിയുള്ളതുമായ കറുത്ത കുതിരയാണ് നല്ല കുതിര. കറുത്തതല്ലെങ്കിൽ ഇതേ വിശേഷണങ്ങളുള്ള ചുവന്ന കുതിരയാണ് നല്ലത്." (തു,ജ)', 'أَبِي قَتَادَةَ الْأَنْصَارِيِّ', 'അബൂഖതാദതുൽ അൻസാരി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 945, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ سَلَمَةَ بْنِ نُفَيْلٍ الْكِنْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، أَذَالَ النَّاسُ الْخَيْلَ وَوَضَعُوا السِّلَاحَ، وَقَالُوا: لَا جِهَادَ، قَدْ وَضَعَتِ الْحَرْبُ أَوْزَارَهَا. فَأَقْبَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَجْهِهِ وَقَالَ: "كَذَبُوا، الْآنَ جَاءَ الْقِتَالُ، وَلَا يَزَالُ مِنْ أُمَّتِي أُمَّةٌ يُقَاتِلُونَ عَلَى الْحَقِّ، وَيُزِيغُ اللهُ لَهُمْ قُلُوبَ أَقْوَامٍ وَيَرْزُقُهُمْ مِنْهُمْ، حَتَّى تَقُومَ السَّاعَةُ، وَحَتَّى يَأْتِيَ وَعْدُ اللهِ. وَالْخَيْلُ مَعْقُودٌ فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ، وَهُوَ يُوحَى إِلَيَّ أَنِّي مَقْبُوضٌ غَيْرُ مُلَبَّثٍ، وَأَنْتُمْ تَتْبَعُونِي أَفْنَادًا، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ، وَعُقْرُ دَارِ الْمُؤْمِنِينَ الشَّامُ". (ن)', 'സലമതുബ്നു നുഫൈലുൽ കിൻദി(റ): ഞാൻ റസൂൽ(സ)യുടെ സമീപത്ത് ഇരിക്കുമ്പോൾ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ജനങ്ങൾ കുതിരകളെ നിസാരമായി കാണുകയും ആയുധം ഉപേക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു, അവർ പറയുന്നു: ഇനി ധർമ്മസമരമില്ല, യുദ്ധം അതിന്റെ ഭാരങ്ങളെ ഇറക്കിവെച്ചിരിക്കുന്നു (അതിന്റെ സമയമെല്ലാം കഴിഞ്ഞിരിക്കുന്നു). അപ്പോൾ റസൂൽ(സ) മുമ്പോട്ട് തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "അവർ പറഞ്ഞത് കളവാണ്, ഇപ്പോൾ യുദ്ധം വന്നെത്തിയിരിക്കുന്നു. അന്ത്യനാൾ വരെയും അല്ലാഹുവിന്റെ വാഗ്ദത്വം എത്തുന്നതുവരെയും സത്യത്തിനുവേണ്ടി യുദ്ധംചെയ്യുന്ന ഒരു വിഭാഗം എന്റെ സമുദായത്തിൽ ഉണ്ടായിക്കൊണ്ടിരിക്കുകയും കുറേ ആളുകളുടെ ഹൃദയങ്ങളെ അവർക്കനുകൂലമായി അല്ലാഹു തിരിക്കുകയും ആ ജനങ്ങൾ മുഖേന അവർക്ക് അല്ലാഹു ജീവിതോപാധി നൽകിക്കൊണ്ടിരിക്കുകയും ചെയ്യുന്നതാണ്. കുതിരകളുടെ മൂർദ്ധാവുകളിൽ അന്ത്യനാൾ വരെ നന്മ ബന്ധിക്കപ്പെട്ടിരിക്കുന്നു. എന്റെ ആത്മാവ് ഉടൻ പിടിക്കപ്പെടുമെന്നും ഞാൻ കൂടുതൽ കാലം ജീവിച്ചിരിക്കുകയില്ലെന്നും, പരസ്പരം കഴുത്തറുക്കുന്ന വ്യത്യസ്ഥ വിഭാഗങ്ങളായാണ് നിങ്ങൾ എന്നെ പിന്തുടരുന്നതെന്നും, സത്യവിശ്വാസികളുടെ നാടുകളിൽ വെച്ച് ഏറ്റവും സുരക്ഷിതമായ കേന്ദ്രം ശാമാണെന്നും എനിക്ക് ദിവ്യബോധനം നൽകപ്പെടുന്നു." (ന)', 'سَلَمَةَ بْنِ نُفَيْلٍ الْكِنْدِيِّ', 'സലമതുബ്നു നുഫൈലുൽ കിൻദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 945, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْخَيْلُ مَعْقُودٌ فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ، الْخَيْلُ ثَلَاثَةٌ: فَهِيَ لِرَجُلٍ أَجْرٌ، وَهِيَ لِرَجُلٍ سِتْرٌ، وَهِيَ عَلَى رَجُلٍ وِزْرٌ. فَأَمَّا الَّذِي هِيَ لَهُ أَجْرٌ فَالَّذِي يَحْتَبِسُهَا فِي سَبِيلِ اللهِ، فَيَتَّخِذُهَا لَهُ، وَلَا تُغَيِّبُ فِي بُطُونِهَا شَيْئًا إِلَّا كُتِبَ لَهُ بِكُلِّ شَيْءٍ غُيِّبَتْ فِي بُطُونِهَا أَجْرٌ. وَلَوْ عَرَضَتْ لَهُ مَرَجٌ...". وَسَاقَ الْحَدِيثَ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=274), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْخَيْلُ لِرَجُلٍ أَجْرٌ وَلِرَجُلٍ سِتْرٌ وَعَلَى رَجُلٍ وِزْرٌ: فَأَمَّا الَّذِي هِيَ لَهُ أَجْرٌ: فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ اللهِ، فَأَطَالَ لَهَا فِي مَرْجٍ أَوْ رَوْضَةٍ، فَمَا أَصَابَتْ فِي طِيَلِهَا ذَلِكَ فِي الْمَرْجِ أَوِ الرَّوْضَةِ كَانَ لَهُ حَسَنَاتٌ، وَلَوْ أَنَّهَا قَطَعَتْ طِيَلَهَا ذَلِكَ فَاسْتَنَّتْ شَرَفًا أَوْ شَرَفَيْنِ كَانَتْ آثَارُهَا وَأَرْوَاثُهَا حَسَنَاتٍ لَهُ، وَلَوْ أَنَّهَا مَرَّتْ بِنَهَرٍ فَشَرِبَتْ مِنْهُ وَلَمْ يُرِدْ أَنْ تُسْقَى كَانَ ذَلِكَ حَسَنَاتٍ، فَهِيَ لَهُ أَجْرٌ. وَرَجُلٌ رَبَطَهَا تَغَنِّيًا وَتَعَفُّفًا، وَلَمْ يَنْسَ حَقَّ اللهِ عَزَّ وَجَلَّ فِي رِقَابِهَا وَلَا ظُهُورِهَا، فَهِيَ لِذَلِكَ سِتْرٌ. وَرَجُلٌ رَبَطَهَا فَخْرًا وَرِيَاءً وَنِوَاءً لِأَهْلِ الْإِسْلَامِ فَهِيَ عَلَى ذَلِكَ وِزْرٌ". وَسُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَمِيرِ؟ فَقَالَ: "لَمْ يَنْزِلْ عَلَيَّ فِيهَا شَيْءٌ إِلَّا هَذِهِ الْآيَةُ الْجَامِعَةُ الْفَاذَّةُ: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ} [الزَّلْزَلَة: ٦ – ٧]". (ق,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "കുതിര ഒരു വ്യക്തിക്ക് പ്രതിഫലവും മറ്റൊരുത്തന് ആവരണവും മറ്റൊരാൾക്ക് പാപവുമാണ്. കുതിര പ്രതിഫലമായി മാറുന്ന വ്യക്തി ഇതാണ്: ദൈവമാർഗ്ഗത്തിൽ അതിനെ ബന്ധിക്കുകയും ഒരു പുൽമേടിലോ തോട്ടത്തിലോ മേയാൻ വേണ്ടി അതിന്റെ കയർ നീട്ടിക്കൊടുക്കുകയും ചെയ്ത വ്യക്തി. ആ കയറിൽ നിന്നുകൊണ്ട് അത് ആ പുൽമേടിൽ നിന്നോ തോട്ടത്തിൽ നിന്നോ ഭക്ഷിച്ചതെല്ലാം അവന് നന്മകളായി മാറും. ഇനി അത് ആ കയർ പൊട്ടിച്ച് ഒന്നോ രണ്ടോ കുന്നുകൾ കയറിപ്പോയാൽ അതിന്റെ കാലടികളും മലവുമെല്ലാം അവനുള്ള നന്മകളായിരിക്കും. അതിന് വെള്ളം നൽകണമെന്ന് അവൻ ഉദ്ദേശിക്കാതെ തന്നെ അത് ഒരു നദിക്കരികിലൂടെ നടക്കുകയും അതിൽ നിന്ന് വെള്ളം കുടിക്കുകയും ചെയ്താൽ അവ നന്മകളായി മാറുന്നതാണ്. ആ കുതിര ആ വ്യക്തിക്ക് പ്രതിഫലമാണ്. ഐശ്വരിത്തിനു വേണ്ടിയും സച്ചരിതത്ത്വത്തിനു വേണ്ടിയും കുതിരയെ ബന്ധിക്കുകയും എന്നാൽ അതിലും അതിന്റെ പുറത്തുമുള്ള അല്ലാഹുവിന്റെ അവകാശത്തെ (സകാതും യാത്രക്കുവേണ്ടി വായ്പ നൽകലും) മറക്കാതിരിക്കുകയും ചെയ്യുന്ന വ്യക്തിക്ക് ആ കുതിര ഒരു ആവരണമാണ്. അഹന്തയ്ക്കും ജനങ്ങളെ കാണിക്കുന്നതിനും മുസ്ലിംകളോടുള്ള ശത്രുതയ്ക്കും വേണ്ടി കുതിരയെ ബന്ധിക്കുന്നവന് ആ കുതിര പാപമാണ്." ശേഷം കഴുതയെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "വളരെ സംക്ഷിപ്തമായ ഈ സൂക്തമല്ലാതെ മറ്റൊന്നും അതിനെക്കുറിച്ച് എനിക്ക് അവതരിക്കപ്പെട്ടിട്ടില്ല: ''ആരെങ്കിലും ഒരണുവിന്റെ തൂക്കം നന്മ ചെയ്താൽ അവനത് കാണും, ആരെങ്കിലും ഒരണുവിന്റെ തൂക്കം തിന്മ ചെയ്താൽ അതും അവൻ കാണും.'' (സൽസല: 6 - 7)." (ബു,മു,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ سَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَائِطِنَا فَرَسٌ يُقَالُ لَهُ اللُّحَيْفُ أَوِ اللُّخَيْفُ. (خ)', 'സഹ്ല്(റ): നബി(സ)യുടെ ലുഹൈഫ് അല്ലെങ്കിൽ ലുഖൈഫ് എന്ന് പേരുള്ള ഒരു കുതിര ഞങ്ങളടെ തോട്ടത്തിൽ മേഞ്ഞിരുന്നു. (ബു)', 'سَهْلٍ', 'സഹ്ല്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ مُعَاذٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ رِدْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى حِمَارٍ يُقَالُ لَهُ عُفَيْرٌ، فَقَالَ: "يَا مُعَاذُ، هَلْ تَدْرِي حَقَّ اللهِ عَلَى عِبَادِهِ؟" وَسَرَدَ الْحَدِيثَ وَقَدْ تَقَدَّمَ. (ق,د)', 'മുആദ്(റ): ഉഫൈർ എന്ന പേരുള്ള ഒരു കഴുതപ്പുറത്ത് നബി(സ)യുടെ സഹയാത്രികനായി ഞാൻ യാത്ര ചെയ്യുകയായിരുന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "മുആദേ, തന്റെ ദാസന്മാർക്ക് അല്ലാഹുവിനോടുള്ള ബാധ്യതകൾ എന്തെല്ലാമാണെന്ന് നിനക്കറിയുമോ?" ശേഷം ആ ഹദീസിന്റെ ബാക്കി അവർ തുടർന്നു. ഇത് മുമ്പ് വന്നിട്ടുണ്ട്. (ബു,മു,ദ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمْ يَكُنْ شَيْءٌ أَحَبَّ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ النِّسَاءِ مِنَ الْخَيْلِ. (ن)', 'അനസ്(റ): റസൂൽ(സ)ക്ക് സ്ത്രീകൾ കഴിഞ്ഞാൽ കുതിരകളോളം ഇഷ്ടപ്പെട്ട മറ്റൊരു വസ്തുവും ഉണ്ടായിരുന്നില്ല. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُمْنُ الْخَيْلِ فِي الشُّقْرِ". قَالَ تِرْمِذِي هَذَا حَدِيثٌ حَسَنٌ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കുതിരകളുടെ മാഹാത്മ്യം ചുവന്നതിലാണ്." തിർമിദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الْخَيْلِ الْأَدْهَمُ، الْأَقْرَحُ، الْأَرْثَمُ، ثُمَّ الْأَقْرَحُ الْمُحَجَّلُ طَلْقُ الْيَمِينِ، فَإِنْ لَمْ يَكُنْ أَدْهَمَ فَكُمَيْتٌ عَلَى هَذِهِ الشِّيَةِ". (ت,جه)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "കുതിരകളിലുത്തമം മേൽചുണ്ട് വെളുത്ത മുഖത്ത് അൽപം വെളുപ്പുള്ള കറുത്തിരുണ്ടവയാണ്. പിന്നെ ഒന്നൊഴികെ ബാക്കി എല്ലാ കാലുകളിലും വെളുപ്പുള്ള മുഖത്ത് അൽപം വെളുപ്പുള്ളവയാണ്. കറുത്തതല്ലെങ്കിൽ ഈ വിശേഷണങ്ങളൊത്ത ഇരുചെവികളിലും കറുപ്പുള്ള ചുവന്ന കുതിരയാണുത്തമം." (തു,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَبِي وَهْبٍ رَضِيَ اللهُ عَنْهُ – وَكَانَتْ لَهُ صُحْبَةٌ – قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: تَسَمَّوْا بِأَسْمَاءِ الْأَنْبِيَاءِ، وَأَحَبُّ الْأَسْمَاءِ إِلَى اللهِ عَزَّ وَجَلَّ عَبْدُ اللهِ وَعَبْدُ الرَّحْمَنِ. وَارْتَبِطُوا الْخَيْلَ، وَامْسَحُوا بِنَوَاصِيهَا وَأَكْفَالِهَا، وَقَلِّدُوهَا، وَلَا تُقَلِّدُوهَا الْأَوْتَارَ. وَعَلَيْكُمْ بِكُلِّ كُمَيْتٍ أَغَرَّ مُحَجَّلٍ، أَوْ أَشْقَرَ أَغَرَّ مُحَجَّلٍ، أَوْ أَدْهَمَ أَغَرَّ مُحَجَّلٍ". (د,ن)', 'അബൂവഹബ്(റ) - അദ്ദേഹം റസൂൽ(സ)യോട് സഹവസിച്ച വ്യക്തിയാണ് -: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പ്രവാചകന്മാരുടെ നാമങ്ങൾ കൊണ്ട് പേരിടുക. പേരുകളിൽ അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടത് അബ്ദുല്ല (അല്ലാഹുവിന്റെ അടിമ), അബ്ദുർറഹ്മാൻ (കരുണ ചെയ്യുന്നവന്റെ അടിമ) എന്നിവയാണ്. നിങ്ങൾ കുതിരകളെ പരിപാലിക്കുക. അവയുടെ മൂർദ്ധാവുകളിലും തുടകളിലും തടവുകയും അവയ്ക്ക് ഹാരമണിയിക്കുകയും ചെയ്യുക. എന്നാൽ അവയക്കുമേൽ നിങ്ങൾ മണികൾ തൂക്കിയിടരുത്. ചുവപ്പും കറുപ്പും കലർന്ന നിറമുള്ളതും മുഖത്ത് കൂടുതൽ വെളുപ്പുള്ളതും കാലുകളിൽ വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, അല്ലെങ്കിൽ ചുവപ്പ് നിറമുള്ളതും മുഖത്തും കാലിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, അല്ലെങ്കിൽ കറുപ്പ് നിറമുള്ളതും മുഖത്തും കാലുകളിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ നിങ്ങൾ സ്വന്തമാക്കുക." (ദ,ന)', 'أَبِي وَهْبٍ', 'അബൂവഹബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 947, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُ الشِّكَالَ مِنَ الْخَيْلِ، وَالشِّكَالُ: يَكُونُ الْفَرَسُ فِي رِجْلِهِ الْيُمْنَى بَيَاضٌ وَفِي يَدِهِ الْيُسْرَى بَيَاضٌ، أَوْ: فِي يَدِهِ الْيُمْنَى وَفِي رِجْلِهِ الْيُسْرَى. (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): കുതിരകളിൽ നിന്ന് ശികാൽ ഇനത്തെ നബി(സ) വെറുത്തിരുന്നു. ശികാൽ എന്നാൽ ഇടത്തെ കയ്യിലും വലത്തെ കാലിലും അല്ലെങ്കിൽ വലത്തെ കയ്യിലും ഇടത്തെ കാലിലും വെളുപ്പ് നിറമുള്ള കുതിരയാണ്. (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 948, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشُّؤْمُ فِي ثَلَاثَةٍ: الْمَرْأَةِ وَالْفَرَسِ وَالدَّارِ". وَفِي رِوَايَةٍ: "الشُّؤْمُ فِي الدَّارِ وَالْمَرْأَةِ وَالْفَرَسِ". (خ,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് വസ്തുക്കളിലാണ് ദുശ്ശകുനമുള്ളത്: സ്ത്രീ, കുതിര, വീട് എന്നിവയാണവ." മറ്റൊരു നിവേദനം: "വീട്, സ്ത്രീ, കുതിര എന്നിവയിലാണ് ദുശ്ശകുനമുള്ളത്." (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 948, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=282), 1, 'وَفِي رِوَايَةٍ: "الشُّؤْمُ فِي الدَّارِ وَالْمَرْأَةِ وَالْفَرَسِ". (خ,ن)', 'മറ്റൊരു നിവേദനം: "വീട്, സ്ത്രീ, കുതിര എന്നിവയിലാണ് ദുശ്ശകുനമുള്ളത്." (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنْ يَكُ فِي شَيْءٍ فَفِي الرَّبْعَةِ وَالْمَرْأَةِ وَالْفَرَسِ". (ن)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ല വസ്തുവിലും അത് (ദുശ്ശകുനം) ഉണ്ടെങ്കിൽ വീട്, സ്ത്രീ, കുതിര എന്നിവയിലാണുള്ളത്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 948, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتِلُ نَاصِيَةَ فَرَسٍ بَيْنَ أُصْبُعَيْهِ، وَيَقُولُ: "الْخَيْلُ مَعْقُودٌ فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ: الْأَجْرُ وَالْغَنِيمَةُ". (ق,ت,ن,جه)', 'ജരീർ(റ): റസൂൽ(സ) തന്റെ രണ്ട് വിരലുകൾക്കിടയിലിട്ട് ഒരു കുതിരയുടെ മൂർദ്ധാവ് പിരിക്കുന്നത് ഞാൻ കണ്ടു, ശേഷം അവിടന്ന് പറഞ്ഞു: "കുതിരകളുടെ മൂർദ്ധാവുകളിൽ അന്ത്യനാൾ വരെ നന്മ ബന്ധിക്കപ്പെട്ടിരിക്കുന്നു. പ്രതിഫലവും ഗനീമത് സ്വത്തുമാണ് ആ നന്മകൾ." (ബു,മു,തു,ന,ജ)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 948, 949, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ فَرَسٍ عَرَبِيٍّ إِلَّا يُؤْذَنُ لَهُ عِنْدَ كُلِّ سَحَرٍ بِدَعْوَتَيْنِ: اللَّهُمَّ خَوَّلْتَنِي مَنْ خَوَّلْتَنِي مِنْ بَنِي آدَمَ، وَجَعَلْتَنِي لَهُ، فَاجْعَلْنِي أَحَبَّ أَهْلِهِ وَمَالِهِ إِلَيْهِ. أَوْ: مِنْ أَحَبِّ مَالِهِ وَأَهْلِهِ إِلَيْهِ". (ن)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ അറബിക്കുതിരകൾക്കും ഓരോ അത്താഴ സമയത്തും രണ്ട് പ്രാർത്ഥനകൾക്ക് അനുവാദം നൽകപ്പെടുന്നതാണ്: അല്ലാഹുവേ, ആദം സന്തതികളിൽ ഒരാൾക്ക് നീ എന്നെ കീഴ്പെടുത്തിക്കൊടുക്കുകയും അവന് നീ എന്നെ നിശ്ചയിച്ചു നൽകുകയും ചെയ്തു. അതിനാൽ അവന്റെ മുതലിലും കുടുംബത്തിലും അവന് ഏറ്റവും ഇഷ്ടപ്പെട്ടതാക്കി നീ എന്നെ മാറ്റേണമേ. അല്ലെങ്കിൽ അവന്റെ കുടുംബത്തിലും മുതലിലും അവന് ഏറ്റവും ഇഷ്ടപ്പെട്ടതിൽ നീ എന്നെയും ഉൾപെടുത്തണേ." (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 949, 949, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ خَالِدِ بْنِ يَزِيدَ الْجُهَنِيِّ قَالَ: كَانَ عُقْبَةُ بْنُ عَامِرٍ يَمُرُّ بِي فَيَقُولُ: يَا خَالِدُ، اخْرُجْ بِنَا نَرْمِي. فَلَمَّا كَانَ ذَاتَ يَوْمٍ أَبْطَأْتُ عَنْهُ، فَقَالَ: يَا خَالِدُ، تَعَالَ أُخْبِرْكَ بِمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَتَيْتُهُ فَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ ثَلَاثَةَ نَفَرٍ الْجَنَّةَ: صَانِعَهُ يَحْتَسِبُ فِي صُنْعِهِ الْخَيْرَ، وَالرَّامِيَ بِهِ، وَمُنَبِّلَهُ. وَارْمُوا وَارْكَبُوا، وَأَنْ تَرْمُوا أَحَبُّ إِلَيَّ مِنْ أَنْ تَرْكَبُوا. وَلَيْسَ اللَّهْوُ إِلَّا فِي ثَلَاثَةٍ: تَأْدِيبِ الرَّجُلِ فَرَسَهُ، وَمُلَاعَبَتِهِ امْرَأَتَهُ، وَرَمْيِهِ بِقَوْسِهِ وَنَبْلِهِ. وَمَنْ تَرَكَ الرَّمْيَ بَعْدَ مَا عَلِمَهُ – رَغْبَةً عَنْهُ – فَإِنَّهَا نِعْمَةٌ كَفَرَهَا. أَوْ قَالَ: كَفَرَ بِهَا". (د,ت,ن,جه)', 'ഖാലിദുബ്നു യസീദിൽ ജുഹനി(റ): ഉഖ്ബതുബ്നു ആമിർ(റ) എന്റെ അടുത്തുകൂടെ നടന്നുപോകാറുണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹം പറയും: ഖാലിദേ, നീ നമ്മോടൊപ്പം വരിക, നമുക്ക് അമ്പെയ്യാം. ഒരു ദിവസം ഞാൻ അൽപം വൈകിച്ചെന്നപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഖാലിദേ വരിക, റസൂൽ(സ) പറഞ്ഞ കാര്യം ഞാൻ നിനക്ക് പറഞ്ഞുതരാം. ഞാൻ ചെന്നപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഒറ്റ അമ്പുകൊണ്ട് മൂന്ന് കൂട്ടരെ അല്ലാഹു സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കും: നിർമ്മാണത്തിൽ അല്ലാഹുവിന്റെ പ്രതിഫലം കാംക്ഷിക്കുന്ന അതിന്റെ നിർമ്മാതാവ്, അമ്പെയ്യുന്നവൻ, അമ്പെയ്തുകാരന് അതിനെ നൽകുന്നവൻ (എന്നിവരാണവർ). നിങ്ങൾ അമ്പെയ്ത്ത് നടത്തുകയും വാഹനം കയറുകയും ചെയ്യുക. നിങ്ങൾ അമ്പെയ്യുകയാണെങ്കിൽ അതാണ് നിങ്ങൾ വാഹനം കയറുന്നതിനേക്കാൾ എനിക്കിഷ്ടം. മൂന്ന് കാര്യങ്ങളിലല്ലാതെ കളികൾ അനുവദനീയമല്ല: ഒരാൾ തന്റെ കുതിരക്ക് പരിശീലനം നൽകൽ, തന്റെ ഭാര്യയെ കളിപ്പിക്കൽ, തന്റെ വില്ലുകൊണ്ടും അമ്പുകൊണ്ടും എറിയൽ എന്നിവയാണവ. ആരെങ്കിലും അമ്പെയ്ത്ത് അറിഞ്ഞ ശേഷം വെറുത്തുകൊണ്ട് അതിനെ ഉപേക്ഷിച്ചാൽ അത് അവൻ നിഷേധിക്കുന്ന ഒരു അനുഗ്രഹമാണ്." അല്ലെങ്കിൽ നബി(സ) പറഞ്ഞത്: "അവൻ നന്ദികേട് കാട്ടുന്ന" എന്നാണ്. (ദ,തു,ന,ജ)', 'خَالِدِ بْنِ يَزِيدَ الْجُهَنِيِّ قَالَ', 'ഖാലിദുബ്നു യസീദിൽ ജുഹനി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 949, 949, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَصْحَبُ الْمَلَائِكَةُ رِفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മണിയോ നായയോ ഒപ്പമുള്ള ഒരു കൂട്ടത്തോടൊപ്പം മലക്കുകളുണ്ടാവില്ല." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي الْجَرَسِ: "مِزْمَارُ الشَّيْطَانِ". (م,د)', 'അബൂഹുറൈറ(റ): മണിയുടെ വിഷയത്തിൽ നബി(സ) പറഞ്ഞു: "അത് പിശാചിന്റെ വീണയാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَبِي بَشِيرٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، قَالَ عَبْدُ اللهِ: حَسِبْتُ أَنَّهُ قَالَ: وَالنَّاسُ فِي مَبِيتِهِمْ، فَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَسُولًا أَنْ لَا يَبْقَيَنَّ فِي رَقَبَةِ بَعِيرٍ قِلَادَةٌ مِنْ وَتَرٍ أَوْ قِلَادَةٌ إِلَّا قُطِعَتْ". (خ,د)', 'അബൂബഷീറുൽ അൻസാരി(റ): അദ്ദേഹം ഒരു യാത്രയിൽ റൂസൂൽ(സ)യുടെ കൂടെയുണ്ടായിരുന്നു. അബ്ദുല്ല(റ) പറയുന്നു: ജനങ്ങൾ അവരുടെ വാസസ്ഥലങ്ങളിലായിരിക്കെ എന്നുകൂടി അദ്ദേഹം പറഞ്ഞുവെന്ന് ഞാൻ കരുതുന്നു. അപ്പോൾ റസൂൽ(സ) ഒരു ദൂതനെ ഇപ്രകാരം പറയാൻ വേണ്ടി അയച്ചു: ഒരൊട്ടകത്തിന്റെ കഴുത്തിലും നൂലോ കയറോ പൊട്ടിക്കപ്പെടാതെ അവശേഷിക്കരുത്. (ബു,ദ)', 'أَبِي بَشِيرٍ الْأَنْصَارِيِّ', 'അബൂബഷീറുൽ അൻസാരി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نُهِيَ عَنْ رُكُوبِ الْجَلَّالَةِ. وَفِي رِوَايَةٍ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَلَّالَةِ فِي الْإِبِلِ أَنْ يُرْكَبَ عَلَيْهَا. (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): കാഷ്ടം ഭക്ഷിക്കുന്ന മൃഗങ്ങളുടെ പുറത്ത് യാത്ര ചെയ്യുന്നത് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. മറ്റൊരു നിവേദനം: കാഷ്ടം ഭക്ഷിക്കുന്ന ഒട്ടകങ്ങളുടെ പുറത്ത് യാത്ര ചെയ്യുന്നതിനെ നബി(സ) നിരോധിച്ചു. (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=290), 1, 'وَفِي رِوَايَةٍ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَلَّالَةِ فِي الْإِبِلِ أَنْ يُرْكَبَ عَلَيْهَا. (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: കാഷ്ടം ഭക്ഷിക്കുന്ന ഒട്ടകങ്ങളുടെ പുറത്ത് യാത്ര ചെയ്യുന്നതിനെ നബി(സ) നിരോധിച്ചു. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُمَا: فَإِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمَّى خَيْلَنَا خَيْلَ اللهِ إِذَا فَزِعْنَا، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا إِذَا فَزِعْنَا بِالْجَمَاعَةِ وَالصَّبْرِ وَالسَّكِينَةِ، وَإِذَا قَاتَلْنَا. (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): നബി(സ) യുദ്ധസമയങ്ങളിൽ ഞങ്ങളുടെ കുതിരപ്പടയാളികളെ അല്ലാഹുവിന്റെ കുതിരപ്പടയാളികൾ എന്ന് പേര് വിളിക്കുമായിരുന്നു. ഞങ്ങൾ ശത്രുക്കളെ ഭയക്കുകയോ നേരിടുകയോ ചെയ്യുകയാണെങ്കിൽ കൂട്ടായ്മയെയും ക്ഷമയെയും ഒതുക്കത്തെയും മുറുകെപ്പിടിക്കാൻ റസൂൽ(സ) ഞങ്ങളോട് കൽപിക്കുമായിരുന്നു. (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يَقُولُ: ضَرَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَامَ خَيْبَرَ لِلزُّبَيْرِ بْنِ الْعَوَّامِ أَرْبَعَةَ أَسْهُمٍ: سَهْمًا لِلزُّبَيْرِ، وَسَهْمًا لِذِي الْقُرْبَى لِصَفِيَّةَ بِنْتِ عَبْدِ الْمُطَّلِبِ أُمِّ الزُّبَيْرِ، وَسَهْمَيْنِ لِلْفَرَسِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): അദ്ദേഹം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ഖൈബർ യുദ്ധ ദിവസം റസൂൽ(സ) സുബൈറുബ്നുൽ അവ്വാം(റ)വിന് നാല് ഓഹരികൾ നൽകി. ഒരു ഓഹരി സുബൈർ(റ)വിനുള്ളതും ഒരു ഓഹരി അടുത്ത കുടുംബങ്ങൾക്കുള്ള വിഹിതത്തിൽ നിന്ന് സബുബൈർ(റ)വിന്റെ മാതാവായ സ്വഫിയ്യതുബിൻതു അബ്ദിൽ മുത്ത്വലിബ്(റ)ക്ക് ലഭിച്ചതും രണ്ട് ഓഹരി കുതിരക്കുള്ളതും ആയിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 951, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنِ ابْنِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَعَلَ لِلْفَرَسِ سَهْمَيْنِ وَلِصَاحِبِهِ سَهْمًا. (خ)', 'ഇബ്നുഉമർ(റ): കുതിരക്ക് രണ്ട് വിഹിതവും കുതിരപ്പടയാളിക്ക് ഒരു വിഹിതവുമാണെന്ന് നബി(സ) നിശ്ചയിച്ചു. (ബു)', 'ابْنِ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 951, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي سَفَرٍ فَسَمِعَ لَعْنَةً، فَقَالَ: "مَا هَذِهِ". قَالُوا: هَذِهِ فُلَانَةُ لَعَنَتْ رَاحِلَتَهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ضَعُوا عَنْهَا، فَإِنَّهَا مَلْعُونَةٌ". فَوَضَعُوا عَنْهَا، قَالَ عِمْرَانُ: فَكَأَنِّي أَنْظُرُ إِلَيْهَا نَاقَةً وَرْقَاءَ. (م,د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) യാത്രയിലായിരിക്കെ ഒരു ശാപവാക്ക് കേട്ടു. നബി(സ) ചോദച്ചു: "എന്താണത്?" അവർ പറഞ്ഞു: ഒരു സ്ത്രീ തന്റെ വാഹനത്തെ ശപിക്കുകയാണ്. നബി(സ) പറഞ്ഞു: "ആ വാഹനത്തിൽ നിന്ന് ഒട്ടകക്കട്ടിൽ എടുത്തുമാറ്റുക, കാരണമത് ശപിക്കപ്പെട്ടതാണ്." അപ്പോൾ അവർ അതിലെ ഒട്ടകക്കട്ടിൽ എടുത്ത് മാറ്റി. ഇംറാൻ(റ) പറഞ്ഞു: ചാരവർണ്ണത്തിലുള്ള ആ ഒട്ടകത്തെ ഞാനിപ്പോഴും കാണുന്നതുപോലെയുണ്ട്. (മു,ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 951, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّحْرِيشِ بَيْنَ الْبَهَائِمِ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മൃഗങ്ങളെ പരസ്പരം പോരടിപ്പിക്കുന്നതിനെ റസൂൽ(സ) നിരോധിച്ചു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 951, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُسَمِّي الْأُنْثَى مِنَ الْخَيْلِ فَرَسًا. (د)', 'അബൂഹുറൈറ(റ): പെൺകുതിരയെക്കുറിച്ച് റസൂൽ(സ) ''ഫറസ്'' (കുതിര) എന്ന് പറയാറുണ്ടായിരുന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 951, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ سَهْلِ بْنِ الْحَنْظَلِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِبَعِيرٍ قَدْ لَحِقَ ظَهْرُهُ بِبَطْنِهِ، فَقَالَ: "اتَّقُوا اللهَ فِي هَذِهِ الْبَهَائِمِ الْمُعْجَمَةِ، فَارْكَبُوهَا صَالِحَةً، وَكُلُوهَا صَالِحَةً". (د)', 'സഹ്ലുബ്നു ഹൻളലിയ്യ(റ): വയറൊട്ടിയ ഒരു ഒട്ടകത്തിന്റെ സമീപത്തുകൂടെ റസൂൽ(സ) നടന്നുപോയി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "സംസാരിക്കാൻ സാധിക്കാത്ത ഈ മൃഗങ്ങളുടെ കാര്യത്തിൽ നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. അതിനാൽ മാന്യമായി നിങ്ങൾ അവയുടെ പുറത്ത് കയറുകയും മാന്യമായി അവയെ ഭക്ഷിക്കുകയും ചെയ്യുക." (ദ)', 'سَهْلِ بْنِ الْحَنْظَلِيَّةِ', 'സഹ്ലുബ്നു ഹൻളലിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَرْدَفَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَلْفَهُ ذَاتَ يَوْمٍ، فَأَسَرَّ إِلَيَّ حَدِيثًا لَا أُحَدِّثُ بِهِ أَحَدًا مِنَ النَّاسِ، وَكَانَ أَحَبُّ مَا اسْتَتَرَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ هَدَفًا أَوْ حَائِشَ نَخْلٍ، قَالَ: فَدَخَلَ حَائِطًا لِرَجُلٍ مِنَ الْأَنْصَارِ فَإِذَا جَمَلٌ، فَلَمَّا رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَنَّ وَذَرَفَتْ عَيْنَاهُ، فَأَتَاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَمَسَحَ ذِفْرَاهُ فَسَكَتَ، فَقَالَ: "مَنْ رَبُّ هَذَا الْجَمَلِ؟ لِمَنْ هَذَا الْجَمَلُ". فَجَاءَ فَتًى مِنَ الْأَنْصَارِ، فَقَالَ: لِي يَا رَسُولَ اللهِ، فَقَالَ: "أَفَلَا تَتَّقِي اللهَ فِي هَذِهِ الْبَهِيمَةِ الَّتِي مَلَّكَكَ اللهُ إِيَّاهَا، فَإِنَّهُ شَكَا إِلَيَّ أَنَّكَ تُجِيعُهُ وَتُدْئِبُهُ". (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): ഒരു ദിവസം റസൂൽ(സ) എന്നെ അവിടത്തെ സഹയാത്രികനാക്കി. അങ്ങനെ റസൂൽ(സ) എനിക്ക് ഒരു രഹസ്യം പറഞ്ഞുതന്നു. ആ വിഷയം ഞാനൊരാൾക്കും പറഞ്ഞുകൊടുക്കുകയില്ല. വിസർജ്ജ്യ ആവശ്യങ്ങൾക്ക് മറ പിടിക്കാൻ അവിടത്തേക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത് ചെറിയ കുന്നോ ഈത്തപ്പനയോ ആയിരുന്നു. അബ്ദുല്ല(റ) പറയുന്നു: അങ്ങനെ റസൂൽ(സ) അൻസാറുകളിൽ ഒരാളുടെ തോട്ടത്തിൽ കയറി. അവിടെ ഒരു ഒട്ടകമുണ്ടായിരുന്നു. നബി(സ)യെ കണ്ടപ്പോൾ അത് തേങ്ങിക്കരയുകയും കണ്ണുനീരൊലിപ്പിക്കുകയും ചെയ്തു. നബി(സ) അതിന്റെ അടുത്ത് ചെല്ലുകയും അതിന്റെ ചെവികൾ തടവുകുയം ചെയ്തപ്പോൾ അത് അടങ്ങിനിന്നു. നബി(സ) ചോദിച്ചു: "ആരാണ് ഈ ഒട്ടകത്തിന്റെ ഉടമ, ആരുടേതാണ് ഈ ഒട്ടകം?" അപ്പോൾ അൻസാരിയായ ഒരു യുവാവ് വന്നുകൊണ്ട് പറഞ്ഞു: റസൂലേ, അത് എന്റേതാണ്. തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്ക് ഉടമപ്പെടുത്തിത്തന്ന ഈ മൃഗത്തിന്റെ കാര്യത്തിൽ നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുന്നില്ലെയോ? നീയതിനെ പട്ടിണിക്കിടുന്നുവെന്നും ഭാരിച്ച ജോലികൾ ചെയ്യിപ്പിക്കുന്നുവെന്നും അത് എന്നോട് പരാതിപ്പെട്ടിരിക്കുന്നു." (മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ، فَاشْتَدَّ عَلَيْهِ الْعَطَشُ، فَوَجَدَ بِئْرًا، فَنَزَلَ فِيهَا فَشَرِبَ ثُمَّ خَرَجَ، فَإِذَا كَلْبٌ يَلْهَثُ يَأْكُلُ الثَّرَى مِنَ الْعَطَشِ، فَقَالَ الرَّجُلُ: لَقَدْ بَلَغَ هَذَا الْكَلْبَ مِنَ الْعَطَشِ مِثْلُ الَّذِي كَانَ بَلَغَنِي، فَنَزَلَ الْبِئْرَ فَمَلَأَ خُفَّهُ، فَأَمْسَكَهُ بِفِيهِ حَتَّى رَقِيَ، فَسَقَى الْكَلْبَ، فَشَكَرَ اللهُ لَهُ، فَغَفَرَ لَهُ". فَقَالُوا: يَا رَسُولَ اللهِ، وَإِنَّ لَنَا فِي الْبَهَائِمِ لَأَجْرًا؟ فَقَالَ: "فِي كُلِّ ذَاتِ كَبِدٍ رَطْبَةٍ أَجْرٌ". (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ഒരു വഴിയിലൂടെ നടക്കുകയായിരുന്നു, അവന് ശക്തമായി ദാഹിക്കുകയും ഒരു കിണർ കണ്ടെത്തുകയും ചെയ്തു. അവൻ ആ കിണറിൽ ഇറങ്ങി വെള്ളം കുടിച്ച് പുറത്ത് കടന്നപ്പോൾ ഒരു നായ നാവ് നീട്ടി മണ്ണ് കപ്പുന്നത് കണ്ടു. അവൻ ചിന്തിച്ചു: ''എനിക്കനുഭവപ്പെട്ട അതേ ദാഹം ഈ നായയും അനുഭവിക്കുന്നു.'' ഉടൻതന്നെ അവൻ ആ കിണറിൽ ഇറങ്ങി തന്റെ ഖുഫ്ഫ (ഷൂ)യിൽ വെള്ളം നിറച്ച് വായ കൊണ്ട് ഖുഫ്ഫ പിടിച്ച് മേൽപ്പോട്ട് കയറി. എന്നിട്ട് നായയെ കുടിപ്പിച്ചു. അപ്പോൾ അല്ലാഹു ആ മനുഷ്യന് നന്ദിചെയ്യുകയും അവന് പൊറുത്തുകൊടുക്കുകയും ചെയ്തു." അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങളുടെ മൃഗങ്ങളുടെ പേരിൽ ഞങ്ങൾക്ക് പ്രതിഫലം ലഭിക്കുമോ? റസൂൽ(സ) പറഞ്ഞു: "തുടിക്കുന്ന ഹൃദയമുള്ള എല്ലാറ്റിലും പ്രതിഫലമുണ്ട്." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 952, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَخٍ لِي حِينَ وُلِدَ لِيُحَنِّكَهُ، فَإِذَا هُوَ فِي مِرْبَدٍ يَسِمُ غَنَمًا فِي آذَانِهَا. (ق,د)', 'അനസുബ്നു മാലിക്(റ): എന്റെ സഹോദരൻ ജനിച്ചപ്പോൾ വായിൽ മധുരം നൽകാൻവേണ്ടി ഞാനവനെ നബി(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുപോയി. അപ്പോൾ നബി(സ) ഒരു ആലയിൽ ആടിന്റെ ചെവികളിൽ അടയാളം വെക്കുകയായിരുന്നു. (ബു,മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُرَّ عَلَيْهِ بِحِمَارٍ قَدْ وُسِمَ فِي وَجْهِهِ، فَقَالَ: "أَمَا بَلَغَكُمْ أَنِّي قَدْ لَعَنْتُ مَنْ وَسَمَ الْبَهِيمَةَ فِي وَجْهِهَا أَوْ ضَرَبَهَا فِي وَجْهِهَا". فَنَهَى عَنْ ذَلِكَ. (م,د,ت)', 'ജാബിർ(റ): മുഖത്ത് അടയാളം വെക്കപ്പെട്ട ഒരു കഴുതയെ നബി(സ)യുടെ അടുത്തുകൂടെ തെളിച്ചുകൊണ്ട് പോകപ്പെട്ടപ്പോൾ അവിടന്ന് പറഞ്ഞു: "മൃഗത്തെ മുഖത്തടിക്കുകയോ അതിന്റെ മുഖത്ത് അടയാളം വെക്കുകയോ ചെയ്തവരെ ഞാൻ ശപിച്ചുവെന്ന് നിങ്ങൾക്കറിയില്ലെയോ?" അങ്ങനെ റസൂൽ(സ) അത് നിരോധിച്ചു. (മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُهْدِيَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَغْلَةٌ فَرَكِبَهَا، فَقَالَ عَلِيٌّ: لَوْ حَمَلْنَا الْحَمِيرَ عَلَى الْخَيْلِ فَكَانَتْ لَنَا مِثْلُ هَذِهِ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَفْعَلُ ذَلِكَ الَّذِينَ لَا يَعْلَمُونَ". (د,ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ)ക്ക് ഒരു കോവർകഴുതയെ സമ്മാനിക്കപ്പെടുകയും അവിടുന്ന് അതിന്മേൽ കയറുകയും ചെയ്തു. അപ്പോൾ അലി(റ) പറഞ്ഞു: കുതിരയുടെ മേൽ കഴുതയെ നാം ഇണചേർക്കുകയാണെങ്കിൽ നമുക്ക് ഇതുപോലുള്ള മൃഗം ലഭിക്കും. റസൂൽ(സ) പറഞ്ഞു: "വിഡ്ഢികൾ മാത്രമേ അപ്രകാരം ചെയ്യുകയൊള്ളൂ." (ദ,ന)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: سَأَلَهُ رَجُلٌ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ؟ قَالَ: لَا. قَالَ: فَلَعَلَّهُ كَانَ يَقْرَأُ فِي نَفْسِهِ؟ قَالَ: خَمْشًا، هَذِهِ شَرٌّ مِنَ الْأُولَى، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَبْدٌ أَمَرَهُ اللهُ تَعَالَى بِأَمْرِهِ فَبَلَّغَهُ، وَاللهِ مَا اخْتَصَّنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشَيْءٍ دُونَ النَّاسِ إِلَّا بِثَلَاثَةٍ: أَمَرَنَا أَنْ نُسْبِغَ الْوُضُوءَ، وَأَنْ لَا نَأْكُلَ الصَّدَقَةَ، وَلَا نُنْزِيَ الْحُمُرَ عَلَى الْخَيْلِ. (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: റസൂൽ(സ) ളുഹ്റിലും അസ്വറിലും (നമസ്കാരങ്ങളിൽ) ഖുർആൻ ഓതാറുണ്ടായിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. അദ്ദേഹം പറഞ്ഞു: എങ്കിൽ തിരുമേനി(സ) രഹസ്യമായി ഓതാറുണ്ടായിരുന്നേക്കാം? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ലാഹു നിന്റെ മുഖത്തെ തൊലിയുരിയട്ടെ (നിന്റെ ഈ സംസാരത്തിന്റെ മോശത്തരം കാരണത്താൽ), ഈ വാക്ക് ആദ്യത്തേതിനേക്കാൾ മോശമായതാണ്. നിശ്ചയം അല്ലാഹു തന്റെ കൽപനകൾ അറിയിച്ചുകൊടുക്കുകയും അങ്ങനെ അത് ജനങ്ങൾക്ക് എത്തിച്ചു കൊടുക്കുകയും ചെയ്ത അല്ലാഹുവിന്റെ അടിമയാണ് റസൂൽ(സ). അല്ലാഹുവാണ് സത്യം, മറ്റു ജനങ്ങളേക്കാൾ മൂന്ന് കാര്യങ്ങൾ മാത്രമാണ് റസൂൽ(സ) ഞങ്ങൾക്ക് പ്രത്യേകമായി നൽകിയത്. വുളൂഇനെ പൂർണ്ണമായി ചെയ്യണമെന്നും സ്വദഖ ഭക്ഷിക്കരുതെന്നും കുതിരയുടെ മേൽ കഴുതയെ ചവിട്ടിക്കരുതെന്നും അവിടുന്ന് ഞങ്ങളോട് കൽപിച്ചു. (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 953, 954, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَدِمَ مِنْ سَفَرٍ اسْتُقْبِلَ بِنَا، فَأَيُّنَا اسْتُقْبِلَ أَوَّلًا جَعَلَهُ أَمَامَهُ، فَاسْتُقْبِلَ بِي فَحَمَلَنِي أَمَامَهُ، ثُمَّ اسْتُقْبِلَ بِحَسَنٍ أَوْ حُسَيْنٍ فَجَعَلَهُ خَلْفَهُ، فَدَخَلْنَا الْمَدِينَةَ وَإِنَّا لَكَذَلِكَ. (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): നബി(സ) വല്ല യാത്രയും കഴിഞ്ഞെത്തിയാൽ ഞങ്ങളിലേക്ക് മുന്നിട്ട് വരും. ഞങ്ങളിൽ ആരെയാണോ നബി(സ) ആദ്യം കാണുന്നത് അവരെ അവിടത്തെ മുന്നിലിരുത്തും. അങ്ങനെ നബി(സ) എന്നെ കാണുകയും എന്നെ തിരുമേനി(സ)യുടെ മുന്നിലിരുത്തുകുയം ചെയ്തു. പിന്നെ ഹസൻ(റ)വിനെയോ ഹുസൈൻ(റ)വിനെയോ കാണുകയും അവരെ അവിടത്തെ പിന്നിലിരുത്തുകയും ചെയ്തു. ശേഷം അതേ അവസ്ഥയിൽ തന്നെ ഞങ്ങൾ മദീനയിൽ പ്രവേശിച്ചു. (മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 954, 954, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ أَنْ تَتَّخِذُوا ظُهُورَ دَوَابِّكُمْ مَنَابِرَ، فَإِنَّ اللهَ إِنَّمَا سَخَّرَهَا لَكُمْ لِتُبَلِّغَكُمْ إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ، وَجَعَلَ لَكُمُ الْأَرْضَ فَعَلَيْهَا فَاقْضُوا حَاجَتَكُمْ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ മൃഗങ്ങളുടെ പുറങ്ങളെ പ്രസംഗപീഠമാക്കുന്നതിനെ നിങ്ങൾ സൂക്ഷിക്കുക. വളരെ പ്രയാസപ്പെട്ട് മാത്രം നിങ്ങൾക്ക് എത്താൻ കഴിയുന്ന നാടുകളിലേക്ക് നിങ്ങളെ എത്തിക്കാനാണ് അല്ലാഹു അവയെ നിങ്ങൾക്ക് കീഴ്പ്പെടുത്തിയത്. അല്ലാഹു നിങ്ങൾക്ക് ഭൂമിയെ തന്നിരിക്കുന്നു. അതിന്മേൽ നിങ്ങളുടെ ആവശ്യം നിർവ്വഹിച്ചു കൊള്ളുക." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 954, 954, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَكُونُ إِبِلٌ لِلشَّيَاطِينِ، وَبُيُوتٌ لِلشَّيَاطِينِ، فَأَمَّا إِبِلُ الشَّيَاطِينِ فَقَدْ رَأَيْتُهَا: يَخْرُجُ أَحَدُكُمْ بِجُنَيْبَاتٍ مَعَهُ قَدْ أَسْمَنَهَا، فَلَا يَعْلُو بَعِيرًا مِنْهَا، وَيَمُرُّ بِأَخِيهِ قَدِ انْقَطَعَ بِهِ فَلَا يَحْمِلُهُ. وَأَمَّا بُيُوتُ الشَّيَاطِينِ فَلَمْ أَرَهَا". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പിശാചിനുള്ള ഒട്ടകങ്ങളും വീടുകളുമുണ്ടാകും. അതിൽ പിശാചിന്റ ഒട്ടകങ്ങളെ ഞാൻ കണ്ടിട്ടുണ്ട്. തടിച്ചുകൊഴുപ്പിച്ച ഒട്ടകങ്ങളുമായി നിങ്ങളിലൊരുത്തൻ പുറപ്പെടുന്നു. അവയിൽ ഒന്നിന്റെയും പുറത്ത് അവൻ കയറുന്നില്ല. യാത്രാക്ലേശമനുഭവിക്കുന്ന തന്റെ സഹോദരന്റെയടുത്തുകൂടെ അവൻ സഞ്ചരിക്കുന്നുവെങ്കിലും അവനെയും അതിന്മേൽ കയറ്റുന്നില്ല. എന്നാൽ പിശാചിന്റെ വീടുകളെ ഞാൻ കണ്ടിട്ടില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 955, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْشِي جَاءَ رَجُلٌ وَمَعَهُ حِمَارٌ، فَقَالَ: يَا رَسُولَ اللهِ، ارْكَبْ. وَتَأَخَّرَ الرَّجُلُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا، أَنْتَ أَحَقُّ بِصَدْرِ دَابَّتِكَ مِنِّي، إِلَّا أَنْ تَجْعَلَهُ لِي". قَالَ: فَإِنِّي قَدْ جَعَلْتُهُ لَكَ، فَرَكِبَ. (د,ت)', 'ബുറൈദ(റ): റസൂൽ(സ) നടന്നുപോകുന്നതിനിടക്ക് ഒരാൾ വന്നു. അദ്ദേഹത്തോടൊപ്പം ഒരു കഴുതയുമുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: റസൂലേ, അങ്ങ് ഇതിന്മേൽ കയറിയാലും. ആ മനുഷ്യൻ അൽപം പിന്നോട്ട് നിന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ മൃഗത്തിന്റെ പുറത്ത് കയറാൻ ഏറ്റവും അവകാശപ്പട്ടവൻ നീ തന്നെയാണ്, നീയതിനെ എനിക്ക് തന്നാലൊഴികെ." അദ്ദേഹം പറഞ്ഞു: ഞാനതിനെ അങ്ങേക്ക് തന്നിരിക്കുന്നു. അപ്പോൾ തിരുമേനി(സ) അതിന്മേൽ കയറി. (ദ,തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 955, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ عَبَّادِ بْنِ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا قَالَ: حَدَّثَنِي أَبِي الَّذِي أَرْضَعَنِي – وَهُوَ أَحَدُ بَنِي مُرَّةَ بْنِ عَوْفٍ – وَكَانَ فِي تِلْكَ الْغَزَاةِ – غَزَاةِ مُؤْتَةَ – قَالَ: وَاللهِ لَكَأَنِّي أَنْظُرُ إِلَى جَعْفَرٍ حِينَ اقْتَحَمَ عَنْ فَرَسٍ لَهُ شَقْرَاءَ، فَعَقَرَهَا ثُمَّ قَاتَلَ الْقَوْمَ حَتَّى قُتِلَ. (د)', 'അബ്ബാദുബ്നു അബ്ദില്ലാഹിബ്നു സുബൈർ(റ): മുഅ്തത് യുദ്ധത്തിലെ യോദ്ധാക്കളോടൊപ്പമുണ്ടായിരുന്ന - മുർറതുബ്നു ഔഫിന്റെ മക്കളിൽ ഒരാളായ - എന്റെ വളർത്തുപിതാവ് എനിക്ക് ഇപ്രകാരം പറഞ്ഞുതന്നു: അല്ലാഹു തന്നെ സത്യം, ജഅ്ഫർ(റ) തന്റെ ചുവന്ന കുതിരപ്പുറത്ത് നിന്ന് വീണപ്പോൾ അതിനെ അറുക്കുകയും ശത്രുക്കളോട് പോരാടി കൊല്ലപ്പെടുകയും ചെയ്ത രംഗം ഞാൻ ഇപ്പോഴും കാണുന്നത് പോലെയുണ്ട്. (ദ)', 'عَبَّادِ بْنِ عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ബാദുബ്നു അബ്ദില്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 955, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَاقَةٌ يُقَالُ لَهَا الْعَضْبَاءُ لَا تُسْبَقُ، فَجَاءَ أَعْرَابِيٌّ عَلَى قَعُودٍ فَسَبَقَهَا فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ حَتَّى عَرَفَهُ، فَقَالَ: "حَقٌّ عَلَى اللهِ أَنْ لَا يَرْتَفِعَ شَيْءٌ مِنَ الدُّنْيَا إِلَّا وَضَعَهُ". (خ,ن)', 'അനസ്(റ): നബി(സ)ക്ക് ''അള്ബാഅ്'' (ചെവി മുറിക്കപ്പെട്ടത്) എന്ന് പേരുള്ള, ഒരിക്കലും പരാചയപ്പെട്ടിട്ടില്ലാത്ത ഒരൊട്ടകം ഉണ്ടായിരുന്നു. അങ്ങനെയിരിക്കെ ഒരു അഅ്റാബി തന്റെ ഒട്ടകപ്പുറത്ത് വരികയും അതിനെ പരാചയപ്പെടുത്തുകയും ചെയ്തു. അത് മുസ്ലിംകൾക്ക് മനഃപ്രയാസമുണ്ടാക്കുകയും നബി(സ) അത് അറിയുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഐഹിക ലോകത്ത് ഉയർന്നുകൊണ്ടിരിക്കുന്ന എല്ലാ വസ്തുക്കളെയും താഴ്ത്തൽ അല്ലാഹുവിന്റെ കടമയാണ്." (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 955, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا سَبَقَ إِلَّا فِي خُفٍّ أَوْ فِي حَافِرٍ أَوْ نَصْلٍ". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒട്ടകത്തിലോ കുതിരയിലോ അമ്പിലോ അല്ലാതെ മത്സരം പാടില്ല." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَابَقَ بَيْنَ الْخَيْلِ الَّتِي قَدْ ضُمِّرَتْ مِنَ الْحَفْيَاءِ، وَكَانَ أَمَدُهَا ثَنِيَّةَ الْوَدَاعِ. وَسَابَقَ بَيْنَ الْخَيْلِ الَّتِي لَمْ تُضَمَّرْ مِنَ الثَّنِيَّةِ إِلَى مَسْجِدِ بَنِي زُرَيْقٍ، وَإِنَّ عَبْدَ اللهِ كَانَ مِمَّنْ سَابَقَ بِهَا. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഭക്ഷണം നൽകി ആരോഗ്യം ലഭിച്ച കുതിരകൾക്കിടയിൽ ഹംയാഇൽ വെച്ച് നബി(സ) മത്സരം നടത്തി. അതിന്റെ അറ്റം സനിയ്യതുൽ വിദാഅ് വരെയായിരുന്നു. ഭക്ഷണം നൽകി ആരോഗ്യപ്പെടുത്തിയിട്ടാല്ലത്ത മൃഗങ്ങൾക്കിടയിൽ സനിയ്യത് മുതൽ മസ്ജിദു ബനീസുറൈഖ് വരെ നബി(സ) മത്സരം നടത്തി. അവയിൽ വിജയിച്ചത് അബ്ദുല്ല(റ)വായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُضَمِّرُ الْخَيْلَ يُسَابِقُ بِهَا. (د,جه)', 'ഇബ്നുഉമർ(റ): മൽസരം നടത്താൻവേണ്ടി നബി(സ) കുതിരയെ ഭക്ഷണം നൽകി ആരോഗ്യമുള്ളതാക്കുമായിരുന്നു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبَّقَ بَيْنَ الْخَيْلِ، وَفَضَّلَ الْقُرَّحَ فِي الْغَايَةِ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) കുതിരകൾക്കിടയിൽ മൽസരം നടത്തുകയും ലക്ഷ്യത്തിൽ ആറാമതായി പ്രവേശിക്കുന്നതിന് ശ്രേഷ്ടത നൽകുകയും ചെയ്തു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، قَالَتْ: فَسَابَقْتُهُ فَسَبَقْتُهُ عَلَى رِجْلَيَّ، فَلَمَّا حَمَلْتُ اللَّحْمَ سَابَقْتُهُ فَسَبَقَنِي، فَقَالَ: "هَذِهِ بِتِلْكَ السَّبْقَةِ". (د,جه)', 'ആഇശ(റ): മഹതി നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. മഹതി പറയുന്നു: അങ്ങനെ ഞാൻ റസൂൽ(സ)യോട് ഓട്ടമൽസരം നടത്തുകയും ഞാൻ വിജയുക്കുകയും ചെയ്തു. പിന്നീട് ഞാൻ തടികൂടിയ ശേഷം നബി(സ)യോട് മൽസരിക്കുകയും നബി(സ) വിജയിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് ആദ്യത്തെ മൽസരത്തിന് പകരമാണ്." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَدْخَلَ فَرَسًا بَيْنَ فَرَسَيْنِ" يَعْنِي: وَهُوَ لَا يُؤْمَنُ أَنْ يُسْبَقَ "فَلَيْسَ بِقِمَارٍ، وَمَنْ أَدْخَلَ فَرَسًا بَيْنَ فَرَسَيْنِ وَقَدْ أَمِنَ أَنْ يُسْبَقَ فَهُوَ قِمَارٌ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രണ്ട് കുതിരകൾക്കിടയിൽ ഒരു കുതിരയെ നിർത്തിയാൽ" - അതിന് ജയിക്കാൻ സാധിക്കുമെന്ന് തോന്നാത്ത വിധമുള്ളതാണ് നബി(സ) ഉദ്ദേശിക്കുന്നത് - "അത് പന്തയമല്ല, ജയിക്കാൻ സാധിക്കുമെന്ന് തോന്നും വിധം ആരെങ്കിലും രണ്ട് കുതിരകൾക്കിടയിൽ ഒരു കുതിരയെ നിർത്തിയാൽ അത് പന്തയമാണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا جَلَبَ وَلَا جَنَبَ فِي الرِّهَانِ". (د,ت,ن)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): നബി(സ) പറഞ്ഞു: "പന്തയത്തിൽ കുതിരയെ തെളിക്കാൻ ആളെ വിടലും കുതിര ക്ഷീണിക്കുമ്പോൾ മൽസരത്തിനറങ്ങാൻ മറ്റൊരു കുതിരയെ കൂടെ കൂട്ടലും പാടില്ല." (ദ,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا جَلَبَ وَلَا جَنَبَ وَلَا شِغَارَ فِي الْإِسْلَامِ، وَمَنِ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا". (د,ت,ن)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): നബി(സ) പറഞ്ഞു: "പന്തയത്തിൽ കുതിരയെ തെളിക്കാൻ ആളെ വിടലും, കുതിര ക്ഷീണിക്കുമ്പോൾ മൽസരത്തിനിറങ്ങാൻ മറ്റൊരു കുതിരയെ കൂടെ കൂട്ടലും, മഹ്റ് നൽകാതെ ഒരു ഭാര്യക്കു പകരം മറ്റൊരു ഭാര്യയെ വിവാഹം ചെയ്യലും ഇസ്ലാമിൽ പാടില്ല. ആരെങ്കിലും അതിക്രമപരമായി വല്ലതും പിടിച്ചെടുത്താൽ അവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكِبَ عَلَى حِمَارٍ عَلَى إِكَافٍ عَلَيْهِ قَطِيفَةٌ، وَأَرْدَفَ أُسَامَةَ وَرَاءَهُ. (خ)', 'ഉസാമതുബ്നു സൈദ്(റ): ജീനിയും അതിന്മേൽ തുണിയും വിരിച്ച് നബി(സ) ഒരു കഴുതപ്പുറത്ത് കയറുകയും ഉസാമ(റ)വിനെ തന്റെ പിന്നിലിരുത്തുകയും ചെയ്തു. (ബു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقْبَلَ يَوْمَ الْفَتْحِ مِنْ أَعْلَى مَكَّةَ عَلَى رَاحِلَتِهِ مُرْدِفًا أُسَامَةَ بْنَ زَيْدٍ، وَمَعَهُ بِلَالٌ، وَمَعَهُ عُثْمَانُ بْنُ طَلْحَةَ مِنَ الْحَجَبَةِ، حَتَّى أَنَاخَ فِي الْمَسْجِدِ، فَأَمَرَهُ أَنْ يَأْتِيَ بِمِفْتَاحِ الْبَيْتِ، فَفَتَحَ وَدَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمَعَهُ أُسَامَةُ وَبِلَالٌ وَعُثْمَانُ، فَمَكَثَ فِيهَا نَهَارًا طَوِيلًا، ثُمَّ خَرَجَ فَاسْتَبَقَ النَّاسُ، وَكَانَ عَبْدُاللهِ بْنُ عُمَرَ أَوَّلَ مَنْ دَخَلَ، فَوَجَدَ بِلَالًا وَرَاءَ الْبَابِ قَائِمًا فَسَأَلَهُ: أَيْنَ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَأَشَارَ لَهُ إِلَى الْمَكَانِ الَّذِي صَلَّى فِيهِ، قَالَ عَبْدُ اللهِ: فَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى مِنْ سَجْدَةٍ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മക്കാവിജയദിവസം മക്കയുടെ ഉയർന്ന ഭാഗത്തുനിന്ന് ഉസാമതുബ്നു സൈദ്(റ)വിനെ പിന്നിലിരുത്തി ഒരു വാഹനത്തിൽ നബി(സ) വന്നു. അവിടത്തോടൊപ്പം ബിലാൽ(റ)വും കഅ്ബയുടെ പരിപാലകരിൽപെട്ട ഉസ്മാനുബ്നു ത്വൽഹ(റ)വുമുണ്ടായിരുന്നു. നബി(സ) പള്ളിയിൽ വന്ന് ഒട്ടകത്തെ മുട്ടുകുത്തിച്ചു. ഉടനെ കഅ്ബയുടെ താക്കോൽ കൊണ്ടുവരാൻ അവിടുന്ന് ഉസ്മാൻ(റ)വിനോട് പറഞ്ഞു. ഉസ്മാൻ(റ) വാതിൽ തുറന്നു. നബി(സ) കഅ്ബയുടെ ഉള്ളിൽ കടന്നു. റസൂൽ(സ)യോടൊപ്പം ഉസാമ(റ)വും ബിലാൽ(റ)വും ഉസ്മാൻ(റ)വും ഉണ്ടായിരുന്നു. അതിനുള്ളിൽ റസൂൽ(സ) കുറേ സമയം ചെലവഴിച്ചു. ശേഷം പുറത്തുവന്നു. അപ്പോൾ ജനങ്ങളെല്ലാം കടന്നുവന്നു. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വായിരുന്നു ആദ്യം അകത്ത് വന്നത്. അപ്പോൾ ബിലാൽ(റ) വാതിലിനു പിറകിൽ നിൽക്കുന്നത് അദ്ദേഹം കണ്ടു. റസൂൽ(സ) എവിടെ വെച്ചാണ് നമസ്കരിച്ചതെന്ന് അദ്ദേഹം ബിലാൽ(റ)വിനോട് ചോദിച്ചു. ഉടനെ റസൂൽ(സ) നമസ്കരിച്ച ഭാഗത്തേക്ക് ബിലാൽ(റ) ആംഗ്യം കാണിച്ചു. അബ്ദുല്ല(റ) പറയുന്നു: റസൂൽ(സ) എത്ര റക്അത്ത് നമസ്കരിച്ചുവെന്ന് ചോദിക്കാൻ ഞാൻ മറന്നു. (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 957, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَقُصُّوا نَوَاصِيَ الْخَيْلِ وَلَا مَعَارِفَهَا وَلَا أَذْنَابَهَا، فَإِنَّ أَذْنَابَهَا مَذَابُّهَا، وَمَعَارِفَهَا دِفَاؤُهَا، وَنَوَاصِيَهَا مَعْقُودٌ فِيهَا الْخَيْرُ". (د)', 'ഉത്ബതുബ്നു അബ്ദിസ്സുലമി(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "കുതിരയുടെ മൂർദ്ധാവിലും പിരടിയിലും വാലിലുമുള്ള രോമം നിങ്ങൾ മുറിച്ച് കളയരുത്. കാരണം അതിന്റെ വാൽ പ്രാണികളെ ആട്ടുവാനുള്ള അവയവമാണ്. പിരടിയിലെ രോമം അതിന് ചൂട് നൽകുന്ന വസ്ത്രമാണ്. അതിന്റെ മൂർദ്ധാവ് അനുഗ്രഹം ബന്ധിപ്പിക്കപ്പെട്ട സ്ഥലമാണ്." (ദ)', 'عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ', 'ഉത്ബതുബ്നു അബ്ദിസ്സുലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 958, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ أَبِي وَهْبٍ الْجُشَمِيِّ – وَكَانَتْ لَهُ صُحْبَةٌ – رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِكُلِّ كُمَيْتٍ أَغَرَّ مُحَجَّلٍ، أَوْ أَشْقَرَ أَغَرَّ مُحَجَّلٍ، أَوْ أَدْهَمَ أَغَرَّ مُحَجَّلٍ". وَفِي رِوَايَةٍ: "عَلَيْكُمْ بِكُلِّ أَشْقَرَ أَغَرَّ مُحَجَّلٍ، أَوْ كُمَيْتٍ أَغَرَّ". فَذَكَرَ نَحْوَهُ. قِيلَ: لِمَ فُضِّلَ الْأَشْقَرُ؟ قَالَ: لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً فَكَانَ أَوَّلَ مَنْ جَاءَ بِالْفَتْحِ صَاحِبُ أَشْقَرَ. (د,ن)', 'അബൂവഹബിൽ ജുശമി(റ): അദ്ദേഹം പ്രവാചകർ(സ)യുടെ അനുചരനായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ചുവപ്പും കറുപ്പും കലർന്ന നിറമുള്ളതും മുഖത്ത് കൂടുതൽ വെളുപ്പുള്ളതും കാലുകളിൽ വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, അല്ലെങ്കിൽ ചുവപ്പ് നിറമുള്ളതും മുഖത്തും കാലുകളിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, അല്ലെങ്കിൽ കറുപ്പ് നിറമുള്ളതും മുഖത്തും കാലുകളിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ നിങ്ങൾ സ്വന്തമാക്കുക." മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "ചുവപ്പ് നിറമുള്ളതും മുഖത്തും കാലുകളിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, ചുവപ്പും കറുപ്പും കലർന്ന നിറമുള്ളതും മുഖത്ത് വെളുപ്പുള്ളതുമായ കുതിരകളെയോ നിങ്ങൾ സ്വന്തമാക്കുക." ശേഷം മുന്നെപ്പറഞ്ഞത് പോലെ പറഞ്ഞു: അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: എന്തുകൊണ്ടാണ് ചുവന്ന കുതിര ശ്രേഷ്ഠമാക്കപ്പെട്ടത്? അവർ പറഞ്ഞു: കാരണം നബി(സ) ഒരു യുദ്ധ സംഘത്തെ അയച്ചപ്പോൾ വിജയ സന്ദേശവുമായി ആദ്യം വന്നത് ചുവന്ന കുതിരക്കാരനായിരുന്നു. (ദ,ന)', 'أَبِي وَهْبٍ الْجُشَمِيِّ – وَكَانَتْ لَهُ صُحْبَةٌ –', 'അബൂവഹബിൽ ജുശമി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 958, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=321), 1, 'وَفِي رِوَايَةٍ: "عَلَيْكُمْ بِكُلِّ أَشْقَرَ أَغَرَّ مُحَجَّلٍ، أَوْ كُمَيْتٍ أَغَرَّ". فَذَكَرَ نَحْوَهُ. قِيلَ: لِمَ فُضِّلَ الْأَشْقَرُ؟ قَالَ: لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً فَكَانَ أَوَّلَ مَنْ جَاءَ بِالْفَتْحِ صَاحِبُ أَشْقَرَ. (د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "ചുവപ്പ് നിറമുള്ളതും മുഖത്തും കാലുകളിലും വെളുപ്പുള്ളതുമായ കുതിരകളെയോ, ചുവപ്പും കറുപ്പും കലർന്ന നിറമുള്ളതും മുഖത്ത് വെളുപ്പുള്ളതുമായ കുതിരകളെയോ നിങ്ങൾ സ്വന്തമാക്കുക." ശേഷം മുന്നെപ്പറഞ്ഞത് പോലെ പറഞ്ഞു: അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: എന്തുകൊണ്ടാണ് ചുവന്ന കുതിര ശ്രേഷ്ഠമാക്കപ്പെട്ടത്? അവർ പറഞ്ഞു: കാരണം നബി(സ) ഒരു യുദ്ധ സംഘത്തെ അയച്ചപ്പോൾ വിജയ സന്ദേശവുമായി ആദ്യം വന്നത് ചുവന്ന കുതിരക്കാരനായിരുന്നു. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَخَّصَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَالزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا فِي قَمِيصٍ مِنْ حَرِيرٍ مِنْ حِكَّةٍ كَانَتْ بِهِمَا. (خ)', 'അനസ്(റ): അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ), സുബൈർ(റ) എന്നിവർക്ക് ബാധിച്ചിരുന്ന ചൊറി കാരണം പട്ടുവസ്ത്രം ധരിക്കുന്നതിൽ നബി(സ) ഇരുവർക്കും ഇളവ് നൽകി. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 958, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهَا أَخْرَجَتْ جُبَّةً مُزَرَّرَةً بِالدِّيبَاجِ، فَقَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ هَذِهِ إِذَا لَقِيَ الْعَدُوَّ. (م,د,جه)', 'അസ്മാഉബിൻത് അബീബക്കർ(റ): ദീബാജ് (പട്ട്) കോർക്കപ്പെട്ട ഒരു ജുബ്ബ പുറത്തെടുത്തുകൊണ്ട് മഹതി പറഞ്ഞു: ശത്രുക്കളെ നേരിടുമ്പോൾ നബി(സ) ഇത് ധരിക്കാറുണ്ടായിരുന്നു. (മു,ദ,ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഉബിൻത് അബീബക്കർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَنْهَى عَنِ الْحَرِيرِ وَالدِّيبَاجِ إِلَّا مَا كَانَ هَكَذَا. ثُمَّ أَشَارَ بِإِصْبَعِهِ ثُمَّ الثَّانِيَةِ، ثُمَّ الثَّالِثَةِ، ثُمَّ الرَّابِعَةِ، وَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا عَنْهُ. (ق,د,ن,جه)', 'ഉമർ(റ): അദ്ദേഹം പട്ടും ദീബാജും (മുന്തിയ പട്ട്) നിരോധിക്കാറുണ്ടായിരുന്നു, ഇത്ര അളവ് ഒഴികെ. എന്നിട്ട് നിവേദകൻ തന്റെ വിരൽ കൊണ്ടും ശേഷം രണ്ടാമത്തെ വിരൽ കൊണ്ടും ശേഷം മൂന്നാമത്തെ വിരൽ കൊണ്ടും ശേഷം നാലാമത്തെ വിരൽ കൊണ്ടും ആ തോത് കാണിച്ചു തന്നു. ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) അതിനെ ഞങ്ങൾക്ക് നിരോധിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ، قَدْ أَرْخَى طَرَفَيْهَا بَيْنَ كَتِفَيْهِ. (جه)', 'അംറുബ്നുൽ ഹുറൈസ്(റ): കറുത്ത തലപ്പാവ് കെട്ടിയതായി ഞാൻ ഇപ്പോഴും റസൂൽ(സ)യെ കാണുന്നത് പോലെയുണ്ട്. അവിടന്ന് തലപ്പാവിന്റെ രണ്ട് ഭാഗങ്ങൾ തോളുകൾക്കിടയിലൂടെ തൂക്കിയിട്ടിരുന്നു. (ജ)', 'عَمْرِو بْنِ حُرَيْثٍ', 'അംറുബ്നുൽ ഹുറൈസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ وَعَلَيْهِ عَمَامَةٌ سَوْدَاءُ. (د,ت,جه)', 'ജാബിർ(റ): കറുത്ത തലപ്പാവ് അണിഞ്ഞുകൊണ്ടാണ് നബി(സ) മക്കയിൽ പ്രവേശിച്ചത്. (ദ,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنِ الصَّعْبِ بْنِ جَثَّامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ بِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْأَبْوَاءِ أَوْ بِوَدَّانَ وَسُئِلَ عَنْ أَهْلِ الدَّارِ يُبَيَّتُونَ مِنَ الْمُشْرِكِينَ، فَيُصَابُ مِنْ نِسَائِهِمْ وَذَرَارِيِّهِمْ، قَالَ: هُمْ مِنْهُمْ، وَسَمِعْتُهُ يَقُولُ: "لَا حِمَى إِلَّا لِلَّهِ وَلِرَسُولِهِ". (خ)', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ): അബവാഇൽ വെച്ചോ വദ്ദാനിൽ വെച്ചോ നബി(സ) എന്റെ അടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ ബഹുദൈവാരാധകരുടെ വീട് രാത്രിയിൽ അക്രമിക്കപ്പെട്ട് വധിക്കപ്പെടുന്ന സ്ത്രീകളെയും കുട്ടികളെയും കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അവർ ആ ബഹുദൈവാരാധകരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിനും അവന്റെ റസൂലിനുമല്ലാതെ സംരക്ഷണ മേഘലയില്ല." (ബു)', 'الصَّعْبِ بْنِ جَثَّامَةَ', 'സ്വഅ്ബുബ്നു ജസ്സാമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ شِعَارُ الْمُهَاجِرِينَ عَبْدَ اللهِ، وَشِعَارُ الْأَنْصَارِ عَبْدَ الرَّحْمَانِ. (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): മുഹാജിറുകളുടെ മുദ്രാവാക്യം അബ്ദുല്ല എന്നും അൻസാറുകളുടെ മുദ്രാവാക്യം അബ്ദുർറഹ്മാൻ എന്നുമായിരുന്നു. (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 959, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنِ الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ: أَخْبَرَنِي مَنْ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنْ بُيِّتُمْ فَلْيَكُنْ شِعَارُكُمْ حم لَا يُنْصَرُونَ". (د,ت)', 'മുഹല്ലബുബ്നു അബീസുഫ്റ(റ): ഒരാൾ എന്നോട് പറഞ്ഞു: അദ്ദേഹം റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് കേട്ടു: "നിങ്ങൾ രാത്രിയിൽ അക്രമിക്കപ്പെട്ടാൽ നിങ്ങളുടെ മുദ്രാവാക്യം ഹാമീം, ലാ യുൻസ്വറൂൻ (ഹാമീം, അവർ സഹായിക്കപ്പെടുകയില്ല) എന്നതായിരിക്കട്ടെ." (ദ,തു)', 'الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ', 'മുഹല്ലബുബ്നു അബീസുഫ്റ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 960, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا أَبَا بَكْرٍ رَضِيَ اللهُ عَنْهُ، فَغَزَوْنَا نَاسًا مِنَ الْمُشْرِكِينَ، فَبَيَّتْنَاهُمْ نَقْتُلُهُمْ، وَكَانَ شِعَارُنَا تِلْكَ اللَّيْلَةَ: أَمِتْ، أَمِتْ، قَالَ سَلَمَةُ: فَقَتَلْتُ بِيَدِي تِلْكَ اللَّيْلَةَ سَبْعَةَ أَهْلِ أَبْيَاتٍ مِنَ الْمُشْرِكِينَ. (د,جه)', 'സലമ(റ): റസൂൽ(സ) അബൂബക്കർ(റ)വിനെ ഞങ്ങളുടെ നേതാവാക്കുകയും അങ്ങനെ ഞങ്ങൾ ബഹുദൈവാരാധകരിൽ ചിലരോട് പോരാടുകയും ചെയ്തു. അവരെ ഞങ്ങൾ രാത്രി അക്രമിച്ച് കൊല്ലാൻ തുടങ്ങി. ആ രാത്രി ഞങ്ങളുടെ മുദ്രാവാക്യം ''നീ കൊല്ല്, നീ കൊല്ല്'' എന്നതായിരുന്നു. സലമ(റ) പറഞ്ഞു: ആ രാത്രി ബഹുദൈവാരാധകരിൽപെട്ട ഏഴ് കുടുംബക്കാരെ എന്റെ കൈകൊണ്ട് ഞാൻ വധിച്ചു. (ദ,ജ)', 'سَلَمَةَ', 'സലമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 960, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي قُبَّةٍ: "اللَّهُمَّ إِنِّي أَنْشُدُكَ عَهْدَكَ وَوَعْدَكَ، اللَّهُمَّ إِنْ شِئْتَ لَمْ تُعْبَدْ بَعْدَ الْيَوْمِ". فَأَخَذَ أَبُو بَكْرٍ بِيَدِهِ فَقَالَ: حَسْبُكَ يَا رَسُولَ اللهِ، فَقَدْ أَلْحَحْتَ عَلَى رَبِّكَ، وَهُوَ فِي الدِّرْعِ، فَخَرَجَ وَهُوَ يَقُولُ: {سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهَى وَأَمَرُّ} وَفِي رِوَايَةٍ: وَذَلِكَ يَوْمَ بَدْرٍ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു തമ്പിലിരുന്നുകൊണ്ട് നബി(സ) ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവേ, നീ ചെയ്ത കരാറുകളെയും വാഗ്ദാനങ്ങളെയും നിറവേറ്റിത്തരുവാൻ ഞാൻ നിന്നോട് ആവശ്യപ്പെടുന്നു. നീ ഉദ്ദേശിക്കുന്ന പക്ഷം ഇന്നത്തെ ദിവസത്തിനു ശേഷം നിന്നെ ആരാധിക്കുവാൻ ആരുമുണ്ടായിരിക്കില്ല." അപ്പോൾ അബൂബക്കർ(റ) തിരുമേനി(സ)യുടെ കൈ പിടിച്ച് ഇപ്രകാരം പറഞ്ഞു: റസൂലേ, മതിയാക്കിയാലും, അങ്ങ് വളരെ നിർബന്ധപൂർവ്വം റബ്ബിനോട് പ്രാർത്ഥിച്ചു കഴിഞ്ഞു. ആ സമയത്ത് നബി(സ) കവചം ധരിച്ചിട്ടുണ്ടായിരുന്നു. ഉടനെ ഇപ്രകാരം പറഞ്ഞുകൊണ്ട് നബി(സ) പുറത്തേക്കിറങ്ങി: "ആ കൂട്ടം തുരത്തപ്പെടും, പിന്തിരിഞ്ഞോടും, അല്ല, അന്ത്യനാളാണ് അവരുടെ നാശത്തിനുള്ള അവധി, അന്ത്യദിനം വളരെ ആപൽക്കരവും അങ്ങേയറ്റം കൈപ്പുള്ളതുമായിരിക്കും." ബദർ യുദ്ധദിവസമാണ് ഈ സംഭവമുണ്ടായതെന്ന് മറ്റൊരു നിവേദനത്തിലുണ്ട്. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 960, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=331), 1, 'وَفِي رِوَايَةٍ: وَذَلِكَ يَوْمَ بَدْرٍ. (خ)', 'മറ്റൊരു നിവേദനത്തിലുണ്ട്. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَخْرَجَ إِلَى الصَّحَابَةِ نَعْلَيْنِ جَرْدَاوَيْنِ لَهُمَا قِبَالَانِ، فَحَدَّثَ أَنَّهُمَا نَعْلَا النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസ്(റ): പഴകി കറുത്തതും രണ്ട് വാറുകളോടുകൂടിയതുമായ രണ്ട് ചെരിപ്പുകൾ നബി(സ)യുടെ സ്വഹാബികളിലേക്ക് കൊണ്ട് വന്ന് അദ്ദേഹം പറഞ്ഞു: ഇവയാണ് നബി(സ)യുടെ ചെരുപ്പുകൾ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 960, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَخْرَجَتْ كِسَاءً مُلَبَّدًا، وَقَالَتْ: فِي هَذَا نُزِعَ رُوحُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَخْرَجَتْ إِزَارًا غَلِيظًا مِمَّا يُصْنَعُ بِالْيَمَنِ، وَكِسَاءً مِنْ هَذِهِ الَّتِي تَدْعُونَهَا الْمُلَبَّدَةَ. (خ)', 'ആഇശ(റ): കണ്ടം വെച്ച ഒരു പുതപ്പ് പുറത്തെടുത്ത് മഹതി പറഞ്ഞു: ഇതിനുള്ളിൽ കിടന്നാണ് നബി(സ) വഫാത്തായത്. മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: യമനിൽ നെയ്തുണ്ടാക്കുന്ന പരുത്ത തുണിയും, നിങ്ങൾ മുലബ്ബദ് എന്ന് പറഞ്ഞുവരുന്ന ഒരു പുതപ്പും ആഇശ(റ) പുറത്തെടുത്തു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 961, 961, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=333), 1, 'وَفِي رِوَايَةٍ عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَخْرَجَتْ إِزَارًا غَلِيظًا مِمَّا يُصْنَعُ بِالْيَمَنِ، وَكِسَاءً مِنْ هَذِهِ الَّتِي تَدْعُونَهَا الْمُلَبَّدَةَ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: യമനിൽ നെയ്തുണ്ടാക്കുന്ന പരുത്ത തുണിയും, നിങ്ങൾ മുലബ്ബദ് എന്ന് പറഞ്ഞുവരുന്ന ഒരു പുതപ്പും ആഇശ(റ) പുറത്തെടുത്തു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ قَدَحَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْكَسَرَ فَاتَّخَذَ مَكَانَ الشَّعْبِ سِلْسِلَةً مِنْ فِضَّةٍ. (خ)', 'അനസ്(റ): നബി(സ)യുടെ കോപ്പ പൊട്ടുകയും പൊട്ടിയ സ്ഥലത്ത് നബി(സ) വെള്ളിയുടെ ഒരു കഷ്ണം വെച്ച് പിടിപ്പിക്കുകയും ചെയ്തു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 961, 961, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ، عَنْ رَجُلٍ قَدْ سَمَّاهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ظَاهَرَ يَوْمَ أُحُدٍ بَيْنَ دِرْعَيْنِ. أَوْ: لَبِسَ دِرْعَيْنِ. (د,جه)', 'സാഇബുബ്നു യസീദ്(റ): അദ്ദേഹം പേരുപറഞ്ഞ ഒരാളിൽനിന്ന് നിവേദനം ചെയ്യുന്നു: ഉഹ്ദ് യുദ്ധദിവസം രണ്ട് അങ്കിയണിഞ്ഞ് റസൂൽ(സ) യുദ്ധം ചെയ്തു. അല്ലെങ്കിൽ റസൂൽ(സ) രണ്ട് അങ്കിയണിഞ്ഞു. (ദ,ജ)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 961, 961, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ، عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: كَانَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دِرْعَانِ يَوْمَ أُحُدٍ، فَنَهَضَ إِلَى الصَّخْرَةِ فَلَمْ يَسْتَطِعْ، فَأَقْعَدَ طَلْحَةَ تَحْتَهُ فَصَعِدَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ حَتَّى اسْتَوَى عَلَى الصَّخْرَةِ، فَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَوْجَبَ طَلْحَةُ". قَالَ تِرْمِدِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'സുബൈറുബ്നുൽ അവ്വാം(റ)വിൽ നിന്ന് അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഉഹ്ദ് യുദ്ധ ദിവസം നബി(സ) രണ്ട് അങ്കിയണിഞ്ഞിരുന്നു. നബി(സ) ഒരു പാറയിൽ കയറാൻ ശ്രമിച്ചു, പക്ഷേ, സാധിച്ചില്ല. അങ്ങനെ ത്വൽഹ(റ)വിനെ അടിയിലിരുത്തി നബി(സ) പാറയിൽ കയറുകയും അതിന്മേൽ നിൽക്കുകയും ചെയ്തു. നിവേദകൻ പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ത്വൽഹ സ്വർഗ്ഗാവകാശിയായി." തുർമുദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (തു)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ، عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ –', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 961, 961, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، وَعَلَى رَأْسِهِ الْمِغْفَرُ، فَقِيلَ لَهُ: ابْنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ؟ فَقَالَ: "اقْتُلُوهُ". قَالَ تِرْمِدِي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): തലയിൽ പടത്തൊപ്പിയണിഞ്ഞ് നബി(സ) മക്കാവിജയ വർഷം മക്കയിൽ പ്രവേശിച്ചു. അപ്പോൾ നബി(സ)യോട് ഇപ്രകാരം പറയപ്പെട്ടു: ഇബ്നുഖതൽ കഅ്ബയുടെ വിരികളിൽ പിടിച്ച് അഭയം തേടിയിരിക്കുന്നു, നബി(സ) പറഞ്ഞു: "അവനെ നിങ്ങൾ വധിച്ചുകളയുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 961, 961, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ مَزِيدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْفَتْحِ وَعَلَى سَيْفِهِ ذَهَبٌ وَفِضَّةٌ. قَالَ: كَانَتْ قَبِيعَةُ السَّيْفِ فِضَّةً. قَالَ تِرْمِدِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'മസീദ(റ): റസൂൽ(സ) മക്കാവിജയ ദിവസം മക്കയിൽ പ്രവേശിക്കുമ്പോൾ അവിടത്തെ വാളിൽ സ്വർണ്ണവും വെള്ളിയുമുണ്ടായിരുന്നു. നിവേദകൻ പറഞ്ഞു: നബി(സ)യുടെ വാളിന്റെ പിടുത്തം വെള്ളിയായിരുന്നു. തുർമുദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (തു)', 'مَزِيدَةَ', 'മസീദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنِ ابْنِ سِيرِينَ قَالَ: صَنَعْتُ سَيْفِي عَلَى سَيْفِ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ، وَزَعَمَ سَمُرَةُ أَنَّهُ صَنَعَ سَيْفَهُ عَلَى سَيْفِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ حَنَفِيًّا. (ت)', 'ഇബ്നുസീരീൻ(റ): സമുറതുബ്നു ജുൻദുബ്(റ)വിന്റെ വാളിന്റെ രൂപത്തിലാണ് ഞാൻ എന്റെ വാള് നിർമ്മിച്ചത്. തന്റെ വാൾ റസൂൽ(സ)യുടെ വാളിന്റെ രൂപത്തിലാണ് നിർമ്മിച്ചതെന്ന് സമുറത്(റ) പറഞ്ഞിരുന്നു. റസൂൽ(സ)യുടെ വാൾ ബനൂ ഹനീഫക്കാരുടെ വാളിന്റെ ഇനത്തിൽ പെട്ടതായിരുന്നു. (തു)', 'ابْنِ سِيرِينَ قَالَ', 'ഇബ്നുസീരീൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُتَعَاطَى السَّيْفُ مَسْلُولًا. (د,ت)', 'ജാബിർ(റ): വാൾ ഊരപ്പെട്ട നിലയിൽ കൈമാറ്റം ചെയ്യുന്നതിനെ നബി(സ) നിരോധിച്ചു. (ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي خُطْبَتِهِ: "أَوْفُوا بِحِلْفِ الْجَاهِلِيَّةِ، فَإِنَّهُ لَا يَزِيدُهُ – يَعْنِي – الْإِسْلَامُ إِلَّا شِدَّةً، وَلَا تُحْدِثُوا حِلْفًا فِي الْإِسْلَامِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) തന്റെ പ്രസംഗത്തിൽ പറഞ്ഞു: "ജാഹിലിയ്യാ കാലത്തെ സഖ്യകരാറുകളെ നിങ്ങൾ പൂർത്തിയാക്കുക. നിശ്ചയം ഇസ്ലാം അതിന് ശക്തി പകരുകയേ ചെയ്യൂ. ഇസ്ലാമിൽ നിങ്ങൾ പുതിയ സഖ്യകരാറുകളിൽ ഏർപ്പെടരുത്." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ أَبِي أُسَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ اصْطَفَفْنَا يَوْمَ بَدْرٍ: "إِذَا أَكْثَبُوكُمْ – يَعْنِي إِذَا غَشُوكُمْ – فَارْمُوهُمْ بِالنَّبْلِ، وَاسْتَبْقُوا نَبْلَكُمْ". (خ,د)', 'അബൂഉസൈദ്(റ): ബദർ യുദ്ധദിവസം ഞങ്ങളുടെ അണി നേരെയാക്കിയപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർ നിങ്ങളോടടുത്താൽ നിങ്ങളവരെ അമ്പെയ്യുക, നിങ്ങളുടെ അമ്പുകളെ നിങ്ങൾ ബാക്കിയാക്കുക²." (ബു,ദ)', 'أَبِي أُسَيْدٍ', 'അബൂഉസൈദ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 962, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: عَبَّأَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبَدْرٍ لَيْلًا. (ت)', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): ബദ്റിൽ നബി(സ) രാത്രി സമയത്താണ് ഞങ്ങളുടെ അണി നേരെയാക്കിയത്. (തു)', 'ابْنِ عَبَّاسٍ', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ سُلَيْمَانِ بْنِ حَبِيبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْنَا عَلَى أَبِي أُمَامَةَ فَرَأَى فِي سُيُوفِنَا شَيْئًا مِنْ حِلْيَةِ فِضَّةٍ، فَغَضِبَ، وَقَالَ: لَقَدْ فَتَحَ الْفُتُوحَ قَوْمٌ، مَا كَانَ حِلْيَةُ سُيُوفِهِمْ مِنَ الذَّهَبِ وَالْفِضَّةِ، وَلَكِنِ الْآنُكُ وَالْحَدِيدُ وَالْعَلَابِيِّ. (خ,جه)', 'സുലൈമാനുബ്നു ഹബീബ്(റ): ഞങ്ങൾ അബൂഉമാമ(റ)വിന്റെ അടുത്ത് ചെന്നപ്പോൾ ചില വെള്ളിയാഭരണങ്ങൾ ഞങ്ങളുടെ വാളുകളിൽ പിടിപ്പിക്കപ്പെട്ടതായി അദ്ദേഹം കണ്ടു. അദ്ദേഹം ദേഷ്യപ്പെടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: ഒരു ജനത പല യുദ്ധങ്ങളിലും വിജയം നേടി. അവരുടെ വാളുകളെ സ്വർണ്ണം കൊണ്ടോ വെള്ളി കൊണ്ടോ അലങ്കരിക്കപ്പെട്ടിരുന്നില്ല. അവർ വാളുകളെ അലങ്കരിച്ചത് ഊറക്കിടാത്ത തോല്, ഇരുമ്പ്, ഈയം എന്നിവ കൊണ്ടായിരുന്നു. (ബു,ജ)', 'سُلَيْمَانِ بْنِ حَبِيبٍ', 'സുലൈമാനുബ്നു ഹബീബ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَنَفَّلَ سَيْفَهُ ذَا الْفَقَارِ يَوْمَ بَدْرٍ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ബദർ യുദ്ധദിവസം തന്റെ വാളായ ദുൽഫുഖാർ അധിക വിഹിതമായി എടുത്തു. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ الْمُغِيرَةُ بْنُ شُعْبَةَ إِذَا غَزَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمَلَ مَعَهُ رُمْحًا، فَإِذَا رَجَعَ طَرَحَ رُمْحَهُ حَتَّى يُحْمَلَ لَهُ. فَقَالَ لَهُ عَلِيٌّ: لَأَذْكُرَنَّ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: "لَا تَفْعَلْ، فَإِنَّكَ إِنْ فَعَلْتَ لَمْ تُرْفَعْ ضَالَّةٌ". قَالَ ابْنُ مَاجَه: فِي إِسْنَادِهِ مُخْتَلَفٌ فِيهِ. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): മുഗീറതുബ്നു ശുഅ്ബ(റ) നബി(സ)യോടൊപ്പം യുദ്ധം ചെയ്യുകയാണെങ്കിൽ ഒരു കുന്തം എടുക്കാറുണ്ടായിരുന്നു. മടങ്ങിവരുന്ന വഴിയിൽ തന്നിലേക്ക് തന്നെ അത് തിരിച്ച് കിട്ടുന്ന രീതിയിൽ അതിനെ ഉപേക്ഷിക്കുകയും ചെയ്യും. അപ്പോൾ അലി(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: ഞാനിത് റസൂൽ(സ)യോട് പറയുക തന്നെ ചെയ്യും. റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അപ്രകാരം ചെയ്യരുത്, ചെയ്യുകയാണെങ്കിൽ വീണുകിട്ടിയ മുതൽപോലെ അത് എടുക്കപ്പെടരുത്." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഈ ഹദീസിന്റെ പരമ്പരയിലെ ഒരാളെക്കുറിച്ച് അഭിപ്രായഭിന്നതയുണ്ട്. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', '2. ആവശ്യാനുസരണം മാത്രം അമ്പെയ്യുക എന്നർത്ഥം', null, array['جه']::text[], array['ജ']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ بِيَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْسٌ عَرَبِيَّةٌ، فَرَأَى رَجُلًا بِيَدِهِ قَوْسٌ فَارِسِيَّةٌ، فَقَالَ: "مَا هَذِهِ؟ أَلْقِها. وَعَلَيْكُمْ بِهَذِهِ وَأَشْبَاهِهَا، وَرِمَاحِ الْقَنَا. فَإِنَّهُمَا يَزِيدُ اللَّهُ لَكُمْ بِهِمَا فِي الدِّينِ، وَيُمَكِّنُ لَكُمْ فِي الْبِلَادِ". قَالَ ابْنُ مَاجَه: فِي إِسْنَادِهِ مُخْتَلَفٌ فِيهِ. (جه)', 'അലി(റ): റസൂൽ(സ)യുടെ കയ്യിൽ ഒരു അറേബ്യൻ വില്ല് ഉണ്ടായിരുന്നു. അങ്ങനെയിരിക്കെ കയ്യിൽ പേർഷ്യൻ വില്ല് പിടിച്ച് നിൽക്കുന്ന ഒരുത്തനെ റസൂൽ(സ) കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "എന്താണിത്? അത് ഉപേക്ഷിക്കുക. ഇതും ഇതുപോലുള്ളതും മരംകൊണ്ടുള്ള കുന്തവും നിങ്ങൾ സ്വന്തമാക്കുക. കാരണം, അവരണ്ടും കാരണത്താൽ മതത്തിലുള്ള ദൃഢതയും നാട്ടിലുള്ള നിലനിൽപും അല്ലാഹു നിങ്ങൾക്ക് അധികരിപ്പിക്കും." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഇതിന്റെ പരമ്പരയിലെ ഒരാളെക്കുറിച്ച് അഭിപ്രായഭിന്നതയുണ്ട്. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 963, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنْ ذِي الْجَوْشَنِ رَضِيَ اللَّهُ عَنْهُ – رَجُلٍ مِنَ الضِّبَابِ – قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ أَنْ فَرَغَ مِنْ أَهْلِ بَدْرٍ بِابْنِ فَرَسٍ لِي يُقَالُ لَهَا الْقَرْحَاءُ، فَقُلْتُ: يَا مُحَمَّدُ، إِنِّي قَدْ جِئْتُكَ بِابْنِ الْقَرْحَاءِ لِتَتَّخِذَهُ. قَالَ: "لَا حَاجَةَ لِي فِيهِ، وَإِنْ شِئْتَ أَنْ أُقِيضَكَ بِهِ الْمُخْتَارَةَ مِنْ دُرُوعِ بَدْرٍ فَعَلْتُ". قُلْتُ: مَا كُنْتُ أُقِيضُهُ الْيَوْمَ بِغُرَّةٍ، قَالَ: "فَلَا حَاجَةَ لِي فِيهِ". (د)', 'ളിബാബ് ഗോത്രത്തിൽപെട്ട ദുൽജൗശിൻ(റ): ബദർ യുദ്ധാനന്തരം ഖർഹാഅ് എന്ന എന്റെ കുതിരകുട്ടിയുമായി ഞാൻ നബി(സ)യുടെ സന്നിധിയിൽ ചെന്നു. ഞാൻ പറഞ്ഞു: മുഹമ്മദേ, ഖർഹാഅ് എന്ന് പേരുള്ള എന്റെ കുതിരക്കുട്ടിയെ അങ്ങേക്കുവേണ്ടി ഞാനിതാ കൊണ്ടുവന്നിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "എനിക്കത് ആവശ്യമില്ല. അതിനു പകരമായി ബദറിൽ നിന്ന് ലഭിച്ച വിലകൂടിയ അങ്കി ഞാൻ നൽകണമെന്ന് നീ ആഗ്രഹിക്കുന്നുവെങ്കിൽ ഞാൻ നൽകാം." ഞാൻ പറഞ്ഞു: ഒരു കുതിരക്ക് പകരം അതിനെ നൽകാൻ പോലും ഞാൻ തയ്യാറല്ല. നബി(സ) പറഞ്ഞു: "എന്നാൽ എനിക്കത് ആവശ്യമില്ല." (ദ)', 'ذِي الْجَوْشَنِ', 'ളിബാബ് ഗോത്രത്തിൽപെട്ട ദുൽജൗശിൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنْ أَبِي أُسَيْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَدْرٍ: "إِذَا أَكْثَبُوكُمْ فَارْمُوهُمْ بِالنَّبْلِ، وَلَا تَسُلُّوا السُّيُوفَ حَتَّى يَغْشَوْكُمْ". (خ,د)', 'അബൂഉസൈദിസ്സാഇദി(റ): നബി(സ) ബദർ യുദ്ധദിവസം പറഞ്ഞു: "അവർ നിങ്ങളോടടുത്താൽ നിങ്ങൾ അമ്പെയ്യുക, നിങ്ങളെ അവർ വലയം ചെയ്യും വരെ നിങ്ങൾ വാളൂരരുത്." (ബു,ദ)', 'أَبِي أُسَيْدٍ السَّاعِدِيِّ', 'അബൂഉസൈദിസ്സാഇദി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ أَمَرَ رَجُلًا كَانَ يَتَصَدَّقُ بِالنَّبْلِ فِي الْمَسْجِدِ: أَنْ لَا يَمُرَّ بِهَا إِلَّا وَهُوَ آخِذٌ بِنُصُولِهَا. (م,د)', 'ജാബിർ(റ): പള്ളിയിലൂടെ അമ്പുമായി നടക്കുകയായിരുന്ന ഒരാളോട് അമ്പിന്റെ മുന പിടിച്ചുകൊണ്ടല്ലാതെ അമ്പുമായി നടക്കരുതെന്ന് റസൂൽ(സ) കൽപിച്ചു. (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُفَدِّي رَجُلًا بَعْدَ سَعْدٍ، سَمِعْتُهُ يَقُولُ: "ارْمِ، فِدَاكَ أَبِي وَأُمِّي". (خ)', 'അലി(റ): സഅ്ദ്(റ)വിനോടല്ലാതെ ഒരാളോടും നബി(സ) ''നിനക്ക് ദണ്ഢമാണ്'' എന്ന് പറയുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. (സഅ്ദ്(റ)വിനോട്) നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അമ്പ് എറിയൂ, എന്റെ പിതാവും മാതാവും നിനക്ക് ദണ്ഢമാണ്." (ബു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَأَنْ أُشَيِّعَ مُجَاهِدًا فِي سَبِيلِ اللَّهِ فَأَكُفَّهُ عَلَى رَحْلِهِ، غَدْوَةً أَوْ رَوْحَةً، أَحَبُّ إِلَيَّ مِنَ الدُّنْيَا وَمَا فِيهَا". قَالَ ابْنُ مَاجَه: فِي سَنَدِهِ ضَعِيفَانِ. (جه)', 'മുആദുബ്നു അനസുൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്ന ഒരു യോദ്ധാവിനെ യാത്രയാക്കുന്നതും, എന്നിട്ട് അവന്റെ വസ്തുസാമഗ്രികൾക്ക് ഒരു പ്രഭാതത്തിലോ പ്രദോശത്തിലോ ഞാൻ കാവൽ നൽക്കുന്നതുമാണ് ഐഹികലോകത്തേക്കാളും അതിലെ സർവ്വത്തേക്കാളും എനിക്ക് ഇഷ്ടപ്പെട്ടത്." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഈ ഹദീസിന്റെ പരമ്പരയിൽ രണ്ട് ബലഹീനരുണ്ട്. (ജ)', 'مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ', 'മുആദുബ്നു അനസുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَدَّعَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَسْتَوْدِعُكَ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ". قَالَ ابْنُ مَاجَه: فِي إِسْنَادِهِ ابْنُ لَهِيعَةَ، وَهُوَ ضَعِيفٌ. (جه)', 'അബൂഹുറൈറ(റ): എന്നെ യാത്രയാക്കിക്കൊണ്ട് റസൂൽ(സ) പറഞ്ഞു: "ഒരിക്കലും നഷ്ടപ്പെടാത്ത സൂക്ഷിപ്പുകളുടെ ഉടമയായ അല്ലാഹുവിനെ ഞാൻ നിനക്ക് ഏൽപിച്ചു തരുന്നു." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഇബ്നുലഹീഅയുണ്ട്. അദ്ദേഹം ബലഹീനനാണ്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَشْخَصَ السَّرَايَا يَقُولُ لِلشَّاخِصِ: "أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ". (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) യുദ്ധസംഘങ്ങളെ അയക്കുകയാണെങ്കിൽ യുദ്ധത്തിനു പോകുന്നവരോട് പറയും: "നിന്റെ മതത്തെയും അമാനതിനെ(വിശ്വസിച്ചേൽപിച്ച മുതൽ)നെയും നിന്റെ കർമങ്ങളുടെ അന്ത്യത്തെയും ഞാൻ അല്ലാഹുവിനെ ഏൽപിക്കുന്നു." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ لَمْ يَبْقَ مِنَ الدُّنْيَا إِلَّا يَوْمٌ لَطَوَّلَهُ اللَّهُ عَزَّ وَجَلَّ حَتَّى يَمْلِكَ رَجُلٌ مِنْ أَهْلِ بَيْتِي، يَمْلِكُ جَبَلَ الدَّيْلَمِ وَالْقُسْطَنْطِينِيَّةَ". قَالَ ابْنُ مَاجَه: فِي سَنَدِهِ مُخْتَلَفٌ فِيهِ. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇഹലോകത്ത് ഒരു ദിവസം മാത്രം ശേഷിക്കുന്ന സന്ദർഭത്തിൽ അല്ലാഹു ആ ദിവസത്തെ ദീർഘിപ്പിക്കുകയും എന്റെ അഹ്ലുബൈത്തിൽപ്പെട്ട ഒരാൾ ലോകത്തിന്റെ അധികാരിയാവുകയും ചെയ്യും. അദ്ദേഹം ദൈലമിലേയും ഖുസ്തുൻതീനിയയിലേയും മലകളെ അധീനപ്പെടുത്തും." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഈ ഹദീസിന്റെ പരമ്പരയിലെ ഒരു നിവേദകനെക്കുറിച്ച് അഭിപ്രായവ്യത്യാസമുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَتُفْتَحُ عَلَيْكُمُ الْآفَاقُ، وَسَتُفْتَحُ عَلَيْكُمْ مَدِينَةٌ يُقَالُ لَهَا قَزْوِينُ، مَنْ رَابَطَ فِيهَا أَرْبَعِينَ يَوْمًا أَوْ أَرْبَعِينَ لَيْلَةً كَانَ لَهُ فِي الْجَنَّةِ عَمُودٌ مِنْ ذَهَبٍ، عَلَيْهِ زَبَرْجَدَةٌ خَضْرَاءُ، عَلَيْهَا قُبَّةٌ مِنْ يَاقُوتَةٍ حَمْرَاءَ، لَهَا سَبْعُونَ أَلْفَ مِصْرَاعٍ مِنْ ذَهَبٍ، عَلَى كُلِّ مِصْرَاعٍ زَوْجَةٌ مِنَ الْحُورِ الْعِينِ". قَالَ ابْنُ مَاجَه: ضَعِيفٌ. (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നാനാ ദിക്കുകളും നിങ്ങൾക്ക് അധീനപ്പെടും. ഖസ്വീൻ എന്ന പട്ടണം നിങ്ങളുടെ കീഴിൽ വരും. ആരെങ്കിലും നാൽപത് പകലോ രാത്രിയോ അവിടെ കാവൽ നിന്നാൽ സ്വർഗത്തിൽ അവന് സ്വർണ്ണത്താലുള്ള ഒരു തൂണുണ്ടാകും. അതിന്മേൽ മുന്തിയ ഇനം പച്ച ഗോമേതകവും, ഗോമേതകത്തിനു മേൽ ചുവന്ന മാണിക്യത്തിന്റെ ഒരു ഖുബ്ബയുമുണ്ടാകും. ആ ഖുബ്ബക്ക് സ്വർണ്ണത്താലുള്ള എഴുപതിനായിരം വാതിൽ പൊളികളുണ്ടാകും. ഓരോ വാതിൽ പൊളിക്കരികിലും ഹൂറുൽ ഈനുകളിൽപെട്ട ഓരോ ഭാര്യയുമുണ്ടാകും." ഇബ്നുമാജ(റ) പറഞ്ഞു: ഈ ഹദീസ് ബലഹീനമാണ്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 965, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ الْيَهُودُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكَ، فَلَعَنْتُهُمْ، فَقَالَ: "مَا لَكِ؟" قُلْتُ: أَوَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: "فَلَمْ تَسْمَعِي مَا قُلْتُ؟ وَعَلَيْكُمْ". (خ)', 'ആഇശ(റ): ജൂതന്മാർ നബി(സ)യുടെ അടുത്ത് വന്ന് അസ്സാമു അലൈക (നിങ്ങൾക്ക് മരണം സംഭവിക്കട്ടെ) എന്ന് ചൊല്ലി. അപ്പോൾ ഞാനവരെ ശപിച്ചു. നബി(സ) ചോദിച്ചു: "നിനക്കെന്തു പറ്റി?" ഞാൻ പറഞ്ഞു: അവർ പറഞ്ഞത് അങ്ങ് ശ്രദ്ധിച്ചില്ലേ? നബി(സ) പറഞ്ഞു: "ഞാൻ അവരോട് വഅലൈകും (നിങ്ങൾക്കും അത് സംഭവിക്കട്ടെ) എന്ന് പറഞ്ഞതും നീ ശ്രദ്ധിച്ചില്ലേ?" (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 966, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمَ طُفَيْلُ ابْنُ عَمْرٍو الدَّوْسِيُّ وَأَصْحَابُهُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّ دَوْسًا عَصَتْ وَأَبَتْ، فَادْعُ اللَّهَ عَلَيْهَا، فَقِيلَ: هَلَكَتْ دَوْسٌ، فَقَالَ: "اللَّهُمَّ اهْدِ دَوْسًا وَائْتِ بِهِمْ". (خ)', 'അബൂഹുറൈറ(റ): ത്വുഫൈലുബ്നു അംരിദ്ദൗസി(റ)വും അനുചരരും നബി(സ)യുടെ അടുത്ത് വന്നു. അവർ പറഞ്ഞു: റസൂലേ, ദൗസ് ഗോത്രക്കാർ ഇസ്ലാമിനോട് വൈമുഖ്യം കാണിക്കുകയാണ്. അവരെ നശിപ്പിക്കുവാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും. ഗൗസ് ഗോത്രം നശിക്കട്ടെ എന്ന് അപ്പോൾ ആരോ പ്രാർത്ഥിക്കുകയും ചെയ്തു. തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, ഗൗസ് ഗോത്രത്തെ സന്മാർഗ്ഗത്തിലാക്കുകയും അവരെ നല്ല വഴിക്ക് കൊണ്ടുവരികയും ചെയ്യേണമേ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 966, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَوْمَ خَيْبَرَ: "لَأُعْطِيَنَّ الرَّايَةَ رَجُلًا يَفْتَحُ اللَّهُ عَلَى يَدَيْهِ". فَقَامُوا يَرْجُونَ لِذَلِكَ أَيُّهُمْ يُعْطَى، فَغَدَوْا وَكُلُّهُمْ يَرْجُو أَنْ يُعْطَى، فَقَالَ: "أَيْنَ عَلِيٌّ؟" فَقِيلَ: يَشْتَكِي عَيْنَيْهِ فَأَمَرَ فَدُعِيَ لَهُ فَبَصَقَ فِي عَيْنَيْهِ فَبَرَأَ مَكَانَهُ، حَتَّى كَأَنَّهُ لَمْ يَكُنْ بِهِ شَيْءٌ، فَقَالَ: نُقَاتِلُهُمْ حَتَّى يَكُونُوا مِثْلَنَا، فَقَالَ: "عَلَى رِسْلِكَ! حَتَّى تَنْزِلَ بِسَاحَتِهِمْ، ثُمَّ ادْعُهُمْ إِلَى الْإِسْلَامِ وَأَخْبِرْهُمْ بِمَا يَجِبُ عَلَيْهِمْ، فَوَاللَّهِ لَأَنْ يُهْدَى بِكَ رَجُلٌ وَاحِدٌ خَيْرٌ لَكَ مِنْ حُمْرِ النَّعَمِ". (خ)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): ഖൈബർ യുദ്ധദിവസം തിരുമേനി(സ) പ്രഖ്യാപിക്കുന്നത് അവർ കേട്ടു: "ആരുടെ കയ്യാലാണോ അല്ലാഹു ഖൈബർ കീഴടക്കുക, അദ്ദേഹത്തിന് ഞാനീ കൊടി നൽകുക തന്നെ ചെയ്യും." അങ്ങനെ കൊടി തനിക്ക് കിട്ടിയിരുന്നെങ്കിൽ എന്ന് ആശിച്ചുകൊണ്ട് അവരെല്ലാവരും എഴുന്നേറ്റുപോയി. പ്രഭാതത്തിൽ തനിക്കാണ് കൊടി ലഭിക്കുക എന്ന് പ്രതീക്ഷിച്ച് എല്ലാവരും ചെന്നു. നബി(സ) ചോദിച്ചു: "അലി എവിടെ?" അലി(റ)വിന് നേത്രരോഗം ബാധിച്ചിരിക്കുകയാണെന്ന് മറുപടി വന്നു. ഉടനെ നബി(സ)യുടെ ആജ്ഞപ്രകാരം അലി(റ)വിനെ കൂട്ടിക്കൊണ്ടുവരികയും തിരുമേനി(സ) അലി(റ)വിന്റെ കണ്ണിൽ അൽപം തുപ്പുനീർ പുരട്ടുകയും ചെയ്തു. തൽസമയം രോഗം ബാധിച്ചിട്ടില്ലാത്ത മട്ടിൽ അത് സുഖമായി. അലി(റ) പറഞ്ഞു: നമ്മെപ്പോലെയാകും വരെ നാം അവരോട് യുദ്ധം ചെയ്യും. നബി(സ) പറഞ്ഞു: "അവരുടെ വീടുകളുടെ മുമ്പിൽ ഇറങ്ങും വരെ നീ ധൃതി പിടിക്കേണ്ട. ശേഷം നീ അവരെ ഇസ്ലാമിലേക്ക് ക്ഷണിക്കുകയും അവർക്ക് നിർബന്ധമാകുന്ന കാര്യങ്ങൾ പറഞ്ഞുകൊടുക്കുകയും ചെയ്യുക. അല്ലാഹു തന്നെ സത്യം, ഒരു മനുഷ്യൻ നീ കാരണത്താൽ സന്മാർഗ്ഗത്തിലാകുന്നത് ചുവന്ന ഒട്ടകങ്ങളേക്കാൾ നിനക്ക് ഉത്തമമാണ്." (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 966, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنِ ابْنِ عَوْنٍ قَالَ: كَتَبْتُ إِلَى نَافِعٍ أَسْأَلُهُ عَنْ دُعَاءِ الْمُشْرِكِينَ عِنْدَ الْقِتَالِ، فَكَتَبَ إِلَيَّ: أَنَّ ذَلِكَ كَانَ فِي أَوَّلِ الْإِسْلَامِ، وَقَدْ أَغَارَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى بَنِي الْمُصْطَلِقِ وَهُمْ غَارُّونَ، وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ، فَقَتَلَ مُقَاتِلَتَهُمْ وَسَبَى سَبِيَهُمْ، وَأَصَابَ يَوْمَئِذٍ جُوَيْرِيَةَ بِنْتَ الْحَارِثِ، حَدَّثَنِي بِذَلِكَ عَبْدُ اللَّهِ وَكَانَ فِي ذَلِكَ الْجَيْشِ. (ق,د)', 'ഇബ്നുഔൻ(റ): യുദ്ധസമയത്ത് ബഹുദൈവാരാധകരെ പ്രബോധനം ചെയ്യുന്നതിനെക്കുറിച്ച് ചോദിച്ചുകൊണ്ട് ഞാൻ നാഫിഅ്(റ)വിന് സന്ദേശമയച്ചു. അപ്പോൾ അദ്ദേഹം എനിക്ക് ഇപ്രകാരം എഴുതി: അത് ഇസ്ലാമിന്റെ ആദ്യകാലത്തായിരുന്നു. ബനൂമുസ്ത്വലിഖ് ഗോത്രക്കാരെ അവർ അശ്രദ്ധരായിരിക്കെ നബി(സ) ആക്രമിച്ചിട്ടുണ്ട്. അന്നേരം അവരുടെ ഒട്ടകങ്ങൾ വെള്ളം കുടിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അങ്ങനെ അവരിലെ യോദ്ധാക്കളെ വധിക്കുകയും കുറെ പേരെ ബന്ധികളാക്കുകയും ചെയ്തു. ജുവൈരിയതുബിൻതുൽ ഹാരിസ്(റ)യെ അന്നാണ് നബി(സ)ക്ക് ലഭിച്ചത്. ഈ വിവരം എനിക്ക് പറഞ്ഞുതന്നത് ആ സൈന്യത്തിലുണ്ടായിരുന്ന അബ്ദുല്ല(റ)വാണ്. (ബു,മു,ദ)', 'ابْنِ عَوْنٍ قَالَ', 'ഇബ്നുഔൻ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 967, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُغِيرُ عِنْدَ صَلَاةِ الصُّبْحِ، وَكَانَ يَتَسَمَّعُ، فَإِذَا سَمِعَ أَذَانًا أَمْسَكَ، وَإِلَّا أَغَارَ. (م,د,ت)', 'അനസ്(റ): സുബ്ഹ് നിസ്കാരത്തിന്റെ സമയത്ത് നബി(സ) ശത്രുക്കളെ അക്രമിക്കാറുണ്ടായിരുന്നു. നബി(സ) ശ്രദ്ധിച്ചുനോക്കും. എന്നിട്ട് ബാങ്ക് കേൾക്കുകയാണെങ്കിൽ യുദ്ധം ഒഴിവാക്കുകയും ഇല്ലായെങ്കിൽ അക്രമിക്കുകയും ചെയ്യുമായിരുന്നു. (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 967, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ أَبِي الْبَخْتَرِيِّ: أَنَّ جَيْشًا مِنْ جُيُوشِ الْمُسْلِمِينَ – كَانَ أَمِيرُهُمْ سَلْمَانُ الْفَارِسِيُّ رَضِيَ اللَّهُ عَنْهُ – حَاصَرُوا قَصْرًا مِنْ قُصُورِ فَارِسَ، فَقَالُوا: يَا أَبَا عَبْدِ اللَّهِ، أَلَا نَنْهَدُ إِلَيْهِمْ؟ قَالَ: دَعُونِي أَدْعُهُمْ كَمَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُوهُمْ. فَأَتَاهُمْ سَلْمَانُ فَقَالَ لَهُمْ: إِنَّمَا أَنَا رَجُلٌ مِنْكُمْ فَارِسِيٌّ تَرَوْنَ الْعَرَبَ يُطِيعُونَنِي، فَإِنْ أَسْلَمْتُمْ فَلَكُمْ مِثْلُ الَّذِي لَنَا وَعَلَيْكُمْ مِثْلُ الَّذِي عَلَيْنَا، وَإِنْ أَبَيْتُمْ إِلَّا دِينَكُمْ تَرَكْنَاكُمْ عَلَيْهِ، وَأَعْطُونَا الْجِزْيَةَ عَنْ يَدٍ وَأَنْتُمْ صَاغِرُونَ. قَالَ: وَرَطَنَ إِلَيْهِمْ بِالْفَارِسِيَّةِ: وَأَنْتُمْ غَيْرُ مَحْمُودِينَ، وَإِنْ أَبَيْتُمْ نَابَذْنَاكُمْ عَلَى سَوَاءٍ. قَالُوا: مَا نَحْنُ بِالَّذِي نُعْطِي الْجِزْيَةَ، وَلَكِنَّا نُقَاتِلُكُمْ. فَقَالُوا: يَا أَبَا عَبْدِ اللَّهِ، أَلَا نَنْهَدُ إِلَيْهِمْ؟ قَالَ: لَا. فَدَعَاهُمْ ثَلَاثَةَ أَيَّامٍ إِلَى مِثْلِ هَذَا، ثُمَّ قَالَ: انْهَدُوا إِلَيْهِمْ، قَالَ: فَنَهَدْنَا إِلَيْهِمْ فَفَتَحْنَا ذَلِكَ الْقَصْرَ. قَالَ تِرْمِذِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'അബുൽബഖ്തരി(റ): സൽമാനുബ്നുൽ ഫാരിസി(റ)വിന്റെ നേതൃത്വത്തിലുള്ള മുസ്ലിംകളുടെ ഒരു സൈന്യം പേർഷ്യക്കാരുടെ ഒരു കോട്ട ഉപരോധിച്ചു. സൈന്യം സൽമാൻ(റ)വിനോട് ചോദിച്ചു: അബൂഅബ്ദുല്ലാ, നാം അവരിലേക്ക് ഇരച്ചുകയറുകയല്ലെയോ? സൽമാൻ(റ) പറഞ്ഞു: റസൂൽ(സ) ശത്രുക്കളെ ക്ഷണിച്ചതു പോലെ ഇവരെയും ഞാൻ ക്ഷണിക്കുന്നതുവരെ നിങ്ങൾ അടങ്ങിനിൽക്കുക. ശേഷം സൽമാൻ(റ) അവരിലേക്ക് ചെല്ലുകയും അവരോട് ഇപ്രകാരം പറയുകയും ചെയ്തു: ഞാനും നിങ്ങളെപ്പോലെ പേർഷ്യക്കാരനാണ്. അറബികൾ എന്നെ അനുസരിക്കുന്നത് നിങ്ങൾ കാണുന്നില്ലേ. നിങ്ങൾ മുസ്ലിംകളാകുന്ന പക്ഷം ഞങ്ങൾക്ക് ലഭിക്കുന്ന ആനുകൂല്യങ്ങൾ നിങ്ങൾക്കും ലഭിക്കുകയും ഞങ്ങളുടെ മേൽ നടപ്പാക്കപ്പെടുന്ന വിധികൾ നിങ്ങളുടെ മേലിലും നടപ്പാക്കപ്പെടുകയും ചെയ്യും. നിങ്ങൾ തങ്ങളുടെ വിശ്വാസത്തിൽ തന്നെ ഉറച്ചുനിൽക്കുന്നുവെങ്കിൽ ഞങ്ങൾ നിങ്ങളെ വിടാം. പക്ഷേ, വളരെ നിന്ദ്യരായി നിങ്ങൾ ജിസ്യ നൽകേണ്ടതാണ്. നിവേദകൻ പറയുന്നു: ശേഷം പേർഷ്യൻ ഭാഷയിൽ സൽമാൻ(റ) അവരോട് ഇപ്രകാരം പറഞ്ഞു: നിങ്ങൾ സ്തുതിക്കപ്പെടുന്നവരല്ല. നിങ്ങൾ വിസമ്മതിക്കുന്നുവെങ്കിൽ ഞങ്ങൾ നിങ്ങൾക്ക് കാണിച്ചുതരാം. പേർഷ്യക്കാർ പറഞ്ഞു: ഞങ്ങൾ ജിസ്യ നൽകാൻ തയ്യാറല്ല. നിങ്ങളോട് യുദ്ധം ചെയ്യാം. മുസ്ലിംകൾ സൽമാൻ(റ)വിനോട് ചോദിച്ചു: അബൂഅബ്ദില്ലാ, നാമവരിലേക്ക് ഇരച്ചുകയറുകയല്ലെയോ? സൽമാൻ(റ) പറഞ്ഞു: വേണ്ട. അങ്ങനെ മൂന്ന് ദിവസം സൽമാൻ(റ) പേർഷ്യക്കാരെ ഇക്കാര്യത്തിലേക്ക് ക്ഷണിച്ചു. ശേഷം മുസ്ലിംകളോട് പറഞ്ഞു: നിങ്ങൾ അവരിലേക്ക് ഇരച്ചുകയറുക. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ അവരിലേക്ക് ഇരച്ചുകയറുകയും ആ കോട്ട കീഴടക്കുകയും ചെയ്തു. തിർമിദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي الْبَخْتَرِيِّ', 'അബുൽബഖ്തരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 967, 968, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى كِسْرَى وَإِلَى قَيْصَرَ وَإِلَى النَّجَاشِيِّ، وَإِلَى كُلِّ جَبَّارٍ يَدْعُوهُمْ إِلَى اللَّهِ تَعَالَى، وَلَيْسَ بِالنَّجَاشِيِّ الَّذِي صَلَّى عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അനസ്(റ): അല്ലാഹുവിലേക്ക് ക്ഷണിച്ചുകൊണ്ട് കിസ്റ, വൈസർ, നജാശി എന്നീ രാജാക്കന്മാർക്കും അക്രമികളായ എല്ലാ നേതാക്കൾക്കും നബി(സ) സന്ദേശമയച്ചു. ഇവിടെപ്പറഞ്ഞ നജാശി നബി(സ) മയ്യിത്ത് നമസ്കരിച്ച നജാശിയല്ല. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 968, 968, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ أَبَا سُفْيَانَ رَضِيَ اللَّهُ عَنْهُ أَخْبَرَهُ مِنْ فِيهِ إِلَى فِيهِ قَالَ: انْطَلَقْتُ فِي الْمُدَّةِ الَّتِي كَانَتْ بَيْنِي وَبَيْنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَبَيْنَا أَنَا بِالشَّامِ إِذْ جِيءَ بِكِتَابٍ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى هِرِقْلَ، قَالَ: يَعْنِي عَظِيمَ الرُّومِ، قَالَ: وَكَانَ دِحْيَةُ الْكَلْبِيُّ جَاءَ بِهِ، فَدَفَعَهُ إِلَى عَظِيمِ بُصْرَى، فَدَفَعَهُ عَظِيمُ بُصْرَى إِلَى هِرِقْلَ، فَقَالَ هِرِقْلُ: هَلْ هَاهُنَا أَحَدٌ مِنْ قَوْمِ هَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ؟ قَالُوا: نَعَمْ، قَالَ: فَدُعِيتُ فِي نَفَرٍ مِنْ قُرَيْشٍ، فَدَخَلْنَا عَلَى هِرَقْلَ، فَأُجْلِسْنَا بَيْنَ يَدَيْهِ، فَقَالَ: أَيُّكُمْ أَقْرَبُ نَسَبًا مِنْ هَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ؟ فَقَالَ أَبُو سُفْيَانَ: فَقُلْتُ: أَنَا، فَأَجْلَسُونِي بَيْنَ يَدَيْهِ، وَأَجْلَسُوا أَصْحَابِي خَلْفِي، ثُمَّ دَعَا بِتَرْجُمَانِهِ فَقَالَ [لَهُ]: قُلْ لَهُمْ: إِنِّي سَائِلٌ هَذَا عَنِ الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ فَإِنْ كَذَبَنِي فَكَذِّبُوهُ، قَالَ: فَقَالَ أَبُو سُفْيَانَ: وَايْمُ اللَّهِ، لَوْلَا مَخَافَةُ أَنْ يُؤْثَرَ عَلَيَّ الْكَذِبُ لَكَذَبْتُ، ثُمَّ قَالَ لِتَرْجُمَانِهِ: سَلْهُ كَيْفَ حَسَبُهُ فِيكُمْ؟ قَالَ: قُلْتُ: هُوَ فِينَا ذُو حَسَبٍ، قَالَ: فَهَلْ كَانَ مِنْ آبَائِهِ مَلِكٌ؟ قُلْتُ: لَا، قَالَ: فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ؟ قُلْتُ: لَا، قَالَ: وَمَنْ يَتَّبِعُهُ، أَشْرَافُ النَّاسِ أَمْ ضُعَفَاؤُهُمْ؟ قَالَ: قُلْتُ: بَلْ ضُعَفَاؤُهُمْ، قَالَ: أَيَزِيدُونَ أَمْ يَنْقُصُونَ؟ قَالَ: قُلْتُ: لَا، بَلْ يَزِيدُونَ، قَالَ: هَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ عَنْ دِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ سَخْطَةً لَهُ؟ قَالَ: قُلْتُ: لَا، قَالَ: فَهَلْ قَاتَلْتُمُوهُ؟ قُلْتُ: نَعَمْ، قَالَ: فَكَيْفَ كَانَ قِتَالُكُمْ إِيَّاهُ؟ قَالَ: قُلْتُ: تَكُونُ الْحَرْبُ بَيْنَنَا وَبَيْنَهُ سِجَالًا: يُصِيبُ مِنَّا وَنُصِيبُ مِنْهُ، قَالَ: فَهَلْ يَغْدِرُ؟ قُلْتُ: لَا، وَنَحْنُ مِنْهُ فِي مُدَّةٍ لَا نَدْرِي مَا هُوَ صَانِعٌ فِيهَا، قَالَ: فَوَاللَّهِ مَا أَمْكَنَنِي مِنْ كَلِمَةٍ أُدْخِلُ فِيهَا شَيْئًا غَيْرَ هَذِهِ، قَالَ: فَهَلْ قَالَ هَذَا الْقَوْلَ أَحَدٌ قَبْلَهُ؟ قَالَ: قُلْتُ: لَا. قَالَ لِتَرْجُمَانِهِ: قُلْ لَهُ: إِنِّي سَأَلْتُكَ عَنْ حَسَبِهِ، فَزَعَمْتَ أَنَّهُ فِيكُمْ ذُو حَسَبٍ، وَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي أَحْسَابِ قَوْمِهَا. وَسَأَلْتُكَ هَلْ كَانَ فِي آبَائِهِ مَلِكٌ، فَزَعَمْتَ: أَنْ لَا، فَقُلْتُ: لَوْ كَانَ مِنْ آبَائِهِ مَلِكٌ، قُلْتُ رَجُلٌ يَطْلُبُ مُلْكَ آبَائِهِ. وَسَأَلْتُكَ عَنْ أَتْبَاعِهِ أَضُعَفَاؤُهُمْ أَمْ أَشْرَافُهُمْ؟ فَقُلْتَ: بَلْ ضُعَفَاؤُهُمْ، وَهُمْ أَتْبَاعُ الرُّسُلِ. وَسَأَلْتُكَ: هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ؟ فَزَعَمْتَ: أَنْ لَا، فَقَدْ عَرَفْتُ أَنَّهُ لَمْ يَكُنْ لِيَدَعَ الْكَذِبَ عَلَى النَّاسِ، ثُمَّ يَذْهَبَ فَيَكْذِبَ عَلَى اللَّهِ. وَسَأَلْتُكَ: هَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ عَنْ دِينِهِ – بَعْدَ أَنْ يَدْخُلَهُ – سَخْطَةً لَهُ؟ فَزَعَمْتَ: أَنْ لَا، وَكَذَلِكَ الْإِيمَانُ إِذَا خَالَطَ بَشَاشَةَ الْقُلُوبِ. وَسَأَلْتُكَ هَلْ يَزِيدُونَ أَوْ يَنْقُصُونَ؟ فَزَعَمْتَ أَنَّهُمْ يَزِيدُونَ، وَكَذَلِكَ الْإِيمَانُ حَتَّى يَتِمَّ. وَسَأَلْتُكَ هَلْ قَاتَلْتُمُوهُ؟ فَزَعَمْتَ: أَنَّكُمْ قَدْ قَاتَلْتُمُوهُ، فَتَكُونُ الْحَرْبُ بَيْنَكُمْ وَبَيْنَهُ سِجَالًا: يَنَالُ مِنْكُمْ وَتَنَالُونَ مِنْهُ، وَكَذَلِكَ الرُّسُلُ تُبْتَلَى، ثُمَّ تَكُونُ لَهُمُ الْعَاقِبَةُ. وَسَأَلْتُكَ: هَلْ يَغْدِرُ؟ فَزَعَمْتَ أَنَّهُ لَا يَغْدِرُ، وَكَذَلِكَ الرُّسُلُ لَا تَغْدِرُ. وَسَأَلْتُكَ: هَلْ قَالَ هَذَا الْقَوْلَ أَحَدٌ قَبْلَهُ؟ فَزَعَمْتَ: أَنْ لَا، فَقُلْتُ: لَوْ قَالَ هَذَا الْقَوْلَ أَحَدٌ قَبْلَهُ، قُلْتُ: رَجُلٌ ائْتَمَّ بِقَوْلٍ قِيلَ قَبْلَهُ. [قَالَ]: ثُمَّ قَالَ: بِمَ يَأْمُرُكُمْ؟ قُلْتُ: يَأْمُرُنَا بِالصَّلَاةِ وَالزَّكَاةِ وَالصِّلَةِ وَالْعَفَافِ. قَالَ: إِنْ يَكُنْ مَا تَقُولُ فِيهِ حَقًّا فَإِنَّهُ نَبِيٌّ، وَقَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ، وَلَمْ أَكُنْ أَظُنُّهُ مِنْكُمْ، وَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ لَأَحْبَبْتُ لِقَاءَهُ، وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمَيْهِ، وَلَيَبْلُغَنَّ مُلْكُهُ مَا تَحْتَ قَدَمَيَّ. قَالَ: ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَهُ، فَإِذَا فِيهِ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى. أَمَّا بَعْدُ: فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ، أَسْلِمْ تَسْلَمْ، وَأَسْلِمْ يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، وَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الْأَرِيسِيِّينَ، {يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَنْ لَا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ} [آل عمران: ٦٤]". فَلَمَّا فَرَغَ مِنْ قِرَاءَةِ الْكِتَابِ، ارْتَفَعَتِ الْأَصْوَاتُ عِنْدَهُ وَكَثُرَ اللَّغَطُ، وَأَمَرَ بِنَا فَأُخْرِجْنَا. قَالَ: فَقُلْتُ لِأَصْحَابِي حِينَ خَرَجْنَا: لَقَدْ أَمِرَ أَمْرُ ابْنِ أَبِي كَبْشَةَ، إِنَّهُ لَيَخَافُهُ مَلِكُ بَنِي الْأَصْفَرِ. قَالَ: فَمَا زِلْتُ مُوقِنًا بِأَمْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللَّهُ عَلَيَّ الْإِسْلَامَ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): അബൂസുഫ്യാൻ(റ) എനിക്ക് ഒരു സംഭവം പറഞ്ഞുതന്നു: റസൂൽ(സ)യും ഞാനും സന്ധിയിലായിരുന്ന കാലത്ത് ഞാനൊരു യാത്രപോയി. അങ്ങനെ ഞാൻ ശാമിലായിരിക്കുമ്പോഴാണ് റോമൻ രാജാവായ ഹിർഖലിനുള്ള റസൂൽ(സ)യുടെ സന്ദേശം അവിടെയെത്തുന്നത്. നിവേദകൻ പറയുന്നു: ദിഹ്യതുൽ കൽബി(റ)വാണ് ആ സന്ദേശം കൊണ്ടുവന്നത്. അദ്ദേഹമത് ബസ്വറയിലെ ഗവർണ്ണർക്ക് നൽകുകയും ഗവർണ്ണർ അത് ഹിർഖലിന് കൈമാറുകയും ചെയ്തു. ഹിർഖൽ ചോദിച്ചു: താൻ നബിയാണെന്ന് അവകാശപ്പെടുന്ന ഈ വ്യക്തിയുടെ സമൂഹത്തിൽപെട്ട ആരെങ്കിലുമിവിടെയുണ്ടോ? അവർ പറഞ്ഞു: അതെ. അങ്ങനെ ഖുറൈശികളിൽ പെട്ട ഒരു സംഘത്തോടൊപ്പം ഞാനും ക്ഷണിക്കപ്പെടുകയും ഞങ്ങൾ ഹിർഖലിന്റെ അടുത്ത് പോവുകയും അദ്ദേഹം ഞങ്ങളെ മുന്നിൽ ഇരുത്തുകയും ചെയ്തു. എന്നിട്ട് ഹിർഖൽ ചക്രവർത്തി ചോദിച്ചു: താൻ നബിയാണെന്ന് അവകാശപ്പെടുന്ന ഈ വ്യക്തിയോട് നിങ്ങളിൽ ആർക്കാണ് അടുത്ത കുടുംബബന്ധമുള്ളത്? ഞാൻ പറഞ്ഞു: എനിക്ക്. അപ്പോൾ അവർ എന്നെ ഹിർഖലിന്റെ തൊട്ടുമുന്നിൽ ഇരുത്തുകയും എന്റെ കൂടെയുള്ളവരെ എന്റെ പിന്നിൽ ഇരുത്തുകയും ചെയ്തു. ശേഷം ഹിർഖൽ തന്റെ പരിഭാഷകനെ വിളിച്ച് ഇപ്രകാരം പറഞ്ഞു: താൻ നബിയാണെന്ന് അവകാശപ്പെടുന്ന ആ വ്യക്തിയെക്കുറിച്ച് ഞാനിവനോട് ചോദിക്കും. ഇവൻ കളവു പറയുകയാണെങ്കിൽ നിങ്ങൾ അത് എനിക്ക് പറഞ്ഞുതരണമെന്ന് നീ അവരോട് പറയുക. അബൂസുഫ്യാൻ പറയുന്നു: അല്ലാഹുവാണ് സത്യം, ഞാൻ കളവ് പറഞ്ഞുവെന്ന് ആക്ഷേപിക്കപ്പെടും എന്ന് ഭയമില്ലായിരുന്നുവെങ്കിൽ ഞാൻ കളവ് പറയുമായിരുന്നു. ശേഷം ഹിർഖൽ പരിഭാഷകനോട് പറഞ്ഞു: നിങ്ങൾക്കിടയിൽ ആ വ്യക്തിയുടെ കുടുംബം എങ്ങിനെയാണ്? എന്ന് നീ അദ്ദേഹത്തോട് ചോദിക്കുക. അബൂസുഫ്യാൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അദ്ദേഹം വലിയ കുടുംബ മഹിമയുള്ളയാളാണ്. ഹിർഖൽ ചോദിച്ചു: അദ്ദേഹത്തിന്റെ പിതാമഹന്മാരിൽ ആരെങ്കിലും രാജാക്കന്മാരാണോ? ഞാൻ പറഞ്ഞു: അല്ല. ഹിർഖൽ ചോദിച്ചു: ഈ വാദം ഉന്നയിക്കുന്നതിനു മുമ്പ് അദ്ദേഹം കളവ് പറയുന്നെന്ന് നിങ്ങൾ സംശയിച്ചിരുന്നോ? ഞാൻ പറഞ്ഞു: ഇല്ല. ഹിർഖൽ ചോദിച്ചു: പൗരപ്രമുഖരാണോ പാവങ്ങളാണോ അദ്ദേഹത്തെ പിന്തുടരുന്നത്? ഞാൻ പറഞ്ഞു: പാവപ്പെട്ട ജനങ്ങൾ. ഹിർഖൽ ചോദിച്ചു: അവർ അധികരിച്ചുകൊണ്ടിരിക്കുകയാണോ അതോ കുറഞ്ഞുകൊണ്ടിരിക്കുകയാണോ? ഞാൻ പറഞ്ഞു: അധികരിച്ചുകൊണ്ടിരിക്കുകയാണ്. ഹിർഖൽ ചോദിച്ചു: ആ മതത്തിൽ പ്രവേശിച്ചതിനു ശേഷം ആരെങ്കിലും അദ്ദേഹത്തോട് ദേഷ്യപ്പെട്ട് അതിൽ നിന്ന് പരിവർത്തനം ചെയ്യുന്നുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. ഹിർഖൽ ചോദിച്ചു: നിങ്ങൾ അദ്ദേഹത്തോട് യുദ്ധം ചെയ്തിട്ടുണ്ടോ? ഞാൻ പറഞ്ഞു: അതെ. ഹിർഖൽ ചോദിച്ചു: അദ്ദേഹത്തോടുള്ള യുദ്ധത്തിന്റെ ഫലം എന്തായിരുന്നു? ഞാൻ പറഞ്ഞു: ജയം ഞങ്ങൾക്കും അദ്ദേഹത്തിനും ഉണ്ടാവാറുണ്ട്. ഞങ്ങൾ അദ്ദേഹത്തിന്റെ കൂട്ടത്തിലുള്ളവരെയും അദ്ദേഹം ഞങ്ങളോടൊപ്പമുള്ളവരെയും വധിക്കാറുണ്ട്. ഹിർഖൽ ചോദിച്ചു: അദ്ദേഹം വഞ്ചിക്കാറുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. പക്ഷേ, ഞങ്ങൾ പ്രത്യേക കാലം വരെ അദ്ദേഹത്തോട് സന്ധിയിലാണ്. ഈ കാലയളവിൽ അദ്ദേഹം എന്തുചെയ്യുമെന്ന് ഞങ്ങൾക്കറിയില്ല. അബൂസുഫ്യാൻ(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം, നബി(സ)ക്ക് എതിരായി എനിക്ക് പറയാൻ സാധിച്ചത് ഇപ്പറഞ്ഞ വാക്ക് മാത്രമായിരുന്നു. ഹിർഖൽ ചോദിച്ചു: അദ്ദേഹത്തിന്റെ മുമ്പ് ഈ അവകാശവാദം ആരെങ്കിലും നടത്തിയിട്ടുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോൾ ഹിർഖൽ തന്റെ പരിഭാഷകനോട് പറഞ്ഞു: നീ ഇവനോട് (അബൂസുഫ്യാനോട്) ഇപ്രകാരം പറയുക: ഞാൻ അദ്ദേഹത്തിന്റെ കുടുംബ മഹിമയെക്കുറിച്ച് നിന്നോട് ചോദിച്ചു. അദ്ദേഹം കുടംബമഹിമയുള്ളവനാണെന്ന് നീ മറുപടി പറഞ്ഞു. പ്രവാചകന്മാർ തങ്ങളുടെ സമൂഹത്തിലെ ഉന്നതകുലത്തിലായിരിക്കും അവതരിക്കുക. അദ്ദേഹത്തിന്റെ പിതാമഹന്മാരിൽ വല്ല രാജാക്കന്മാരുമുണ്ടായിരുന്നോ എന്ന് ഞാൻ ചോദിച്ചു. ഇല്ല എന്ന് നീ മറുപടി പറഞ്ഞു. അദ്ദേഹത്തിന്റെ പിതാമഹന്മാരിൽ വല്ല രാജാവുമുണ്ടെങ്കിൽ തന്റെ പിതാമഹന്മാരുടെ രാജാധികാരം തിരികെ ചോദിക്കുന്നവനെന്ന് അദ്ദേഹത്തെ എനിക്ക് ആക്ഷേപിക്കാം. പൗരപ്രമുഖരാണോ ദുർബലരാണോ അദ്ദേഹത്തിന്റെ അനുയായികളെന്ന് ഞാൻ ചോദിച്ചു. അവർ ദുർബലരാണെന്ന് നീ മറുപടി പറഞ്ഞു. ദുർബലർ തന്നെയായിരിക്കും പ്രവാചകന്മാരുടെ അനുയായികൾ. ഈ വാദം ഉന്നയിക്കുന്നതിന് മുമ്പ് അദ്ദേഹം കളവ് പറയുന്നുണ്ടെന്ന് നിങ്ങൾ സംശയിച്ചിരുന്നോ എന്ന് ഞാൻ ചോദിച്ചു. ഇല്ല എന്ന് നീ മറുപടി പറഞ്ഞു. ജനങ്ങളോട് കളവ് പറയാത്ത ആ വ്യക്തി ശേഷം അല്ലാഹുവിന്റെ മേൽ കളവ് ചമച്ചുണ്ടാക്കുകയില്ലെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. അദ്ദേഹത്തിന്റെ മതത്തിൽ പ്രവേശിച്ച ശേഷം അദ്ദേഹത്തോട് ദേഷ്യപ്പെട്ട് ആരെങ്കിലും അതിൽ നിന്ന് മടങ്ങുന്നുണ്ടോ എന്ന് ഞാൻ നിന്നോട് ചോദിച്ചു. നീ ഇല്ല എന്ന് മറുപടി പറഞ്ഞു. സത്യവിശ്വാസം ഹൃദയത്തിന്റെ അടിത്തട്ടിലേക്ക് ചേർന്നാൽ ഇപ്രകാരം തന്നെയായിരിക്കും. അനുയായികൾ അധികരിക്കുകയാണോ കുറയുകയാണോ എന്ന് ഞാൻ നിന്നോട് ചോദിച്ചു. അധികരിക്കുകയാണെന്ന് നീ മറുപടി പറഞ്ഞു. സത്യവിശ്വാസം പൂർണ്ണതയിൽ എത്തുന്നതുവരെ അപ്രകാരം തന്നെയായിരിക്കും. നിങ്ങൾ അദ്ദേഹത്തോട് യുദ്ധം ചെയ്തിട്ടുണ്ടോ എന്ന് ഞാൻ ചോദിച്ചു. നിങ്ങൾ അദ്ദേഹത്തോട് യുദ്ധം ചെയ്തിട്ടുണ്ടെന്നും വിജയപരാജയം അങ്ങോട്ടുമിങ്ങോട്ടും മാറിമാറി ഉണ്ടാവാറുണ്ടെന്നും രണ്ടു കൂട്ടരും വധിക്കപ്പെടാറുണ്ടെന്നും നീ മറുപടി പറഞ്ഞു. പ്രവാചകന്മാർ ഇപ്രകാരം പരീക്ഷിക്കപ്പെടും. അവസാന വിജയം അവർ നേടുകയും ചെയ്യും. അദ്ദേഹം വഞ്ചിക്കാറുണ്ടോ എന്ന് ഞാൻ ചോദിച്ചു. വഞ്ചിക്കാറില്ല എന്ന് നീ മറുപടിയും പറഞ്ഞു. പ്രവാചകന്മാർ അപ്രകാരം തന്നെ വഞ്ചിക്കാത്തവരായിരിക്കും. ഈ അവകാശവാദവുമായി മുമ്പ് ആരെങ്കിലും വന്നിട്ടുണ്ടോ എന്ന് ഞാൻ ചോദിച്ചു. ഇല്ല എന്ന് നീ മറുപടിയും പറഞ്ഞു. മുമ്പ് ആരെങ്കിലും അപ്രകാരം അവകാശപ്പെട്ടിട്ടുണ്ടെങ്കിൽ ഇദ്ദേഹവും ആ അവകാശവാദത്തെ ഏറ്റുപറയുകയാണെന്ന് എനിക്കദ്ദേഹത്തെ ആക്ഷേപിക്കാം. ശേഷം ഹിർഖൽ ചക്രവർത്തി ചോദിച്ചു: എന്തെല്ലാമാണ് ആ നബി നിങ്ങളോട് കൽപിക്കുന്നത്? ഞാൻ പറഞ്ഞു: നിസ്കരിക്കണമെന്നും നിർബന്ധദാനം (സകാത്ത്) നൽകണമെന്നും കുടുംബബന്ധം ചേർക്കണമെന്നും സച്ചരിതത്വം പാലിക്കണമെന്നും അദ്ദേഹം ഞങ്ങളോട് കൽപിക്കുന്നു. ഹിർഖൽ പറഞ്ഞു: അദ്ദേഹത്തിന്റെ കാര്യത്തിൽ നീ പറഞ്ഞതെല്ലാം സത്യമാണെങ്കിൽ അദ്ദേഹം നബി തന്നെയാണ്. ആ നബി പുറപ്പെടാനായിട്ടുണ്ടെന്ന് എനിക്കറിയാമായിരുന്നു. പക്ഷേ, ആ നബി നിങ്ങളിൽ പെട്ടവനാണെന്ന് ഞാൻ കരുതിയിരുന്നില്ല. എനിക്ക് അവിടുത്തെ സമീപത്തേക്ക് എത്തിപ്പെടാൻ സാധിക്കുകയാണങ്കിൽ അവിടുത്തെ നേരിൽ കാണാൻ ഞാൻ താൽപര്യപ്പെടുന്നു. ഞാൻ അവിടുത്തെ സന്നിധിയിലായിരുന്നെങ്കിൽ അവിടുത്തെ പാദങ്ങൾ കഴുകിക്കൊടുക്കുമായിരുന്നു. എന്റെ കാൽപാദങ്ങൾക്കടിയിൽ വരെ അവിടുത്തെ അധികാരമെത്തുക തന്നെ ചെയ്യും. ശേഷം ഹിർഖൽ ചക്രവർത്തി റസൂൽ(സ)യുടെ കത്ത് കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും അത് വായിക്കുകയും ചെയ്തു. അതിൽ ഇപ്രകാരം കുറിച്ചിരുന്നു: "പരമകാരുണികനും കരുണാവാരിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിന്റെ റസൂലായ മുഹമ്മദ്(സ)യിൽ നിന്നും റോമൻ ചക്രവർത്തി ഹിർഖലിനുള്ള സന്ദേശം, സന്മാർഗ്ഗം പിന്തുടർന്നവർക്ക് രക്ഷയുണ്ടാവട്ടെ. ഞാൻ അങ്ങയെ ഇസ്ലാമിന്റെ പാതയിലേക്ക് ക്ഷണിക്കുന്നു. താങ്കൾ മുസ്ലിമാവുക, എന്നാൽ രക്ഷപ്പെടാം. താങ്കൾ മുസ്ലിമായാൽ അല്ലാഹു താങ്കൾക്ക് ഇരട്ടി പ്രതിഫലം നൽകും. പിന്തിരിയുന്ന പക്ഷം റോമക്കാരുടെ മുഴുവൻ ശിക്ഷ താങ്കൾ ഏറ്റുവാങ്ങേണ്ടിവരും. ''മുമ്പ് ഗ്രന്ഥം നൽകപ്പെട്ട സമൂഹമേ, നമുക്കിടയിൽ സ്വീകാര്യമായ വചനത്തിലേക്ക് നിങ്ങൾ വരിക. അഥവാ നാം അല്ലാഹുവിനെയല്ലാതെ മറ്റാരെയും ആരാധിക്കാതിരിക്കുക. അവനോട് ഒരാളെയും പങ്കുചേർക്കാതിരിക്കുക. നമ്മിൽ ചിലർ മറ്റു ചിലരെ അല്ലാഹുവിന് പുറമെയുള്ള അധികാരികളാക്കാതിരിക്കുക. അവർ പിന്തിരിയുന്നുവെങ്കിൽ അവരോട് ഇപ്രകാരം പറയുക: ഞങ്ങൾ മുസ്ലിംകളാണെന്ന് നിങ്ങൾ സാക്ഷ്യം വഹിക്കുക.'' (ആലുഇംറാൻ: 64)." ഹിർഖൽ ചക്രവർത്തി കത്ത് വായിച്ചുകഴിഞ്ഞപ്പോൾ അവിടെ വലിയ ശബ്ദകോലാഹങ്ങളുയർന്നു. അങ്ങനെ ഞങ്ങളെ പുറത്തുവിടാൻ അദ്ദേഹം കൽപിച്ചു. ഞങ്ങൾ പുറത്തുവന്നപ്പോൾ ഞാൻ എന്റെ കൂടെയുള്ളവരോട് പറഞ്ഞു: റോമൻ ചക്രവർത്തി പോലും ഭയപ്പെടും വിധം ഇബ്നുഅബീകബ്ശയുടെ (നബി(സ)യെ ആക്ഷേപിക്കാൻ അബൂസുഫ്യാൻ ഉപയോഗിച്ച നാമമാണിത്) കാര്യം പടർന്നു കഴിഞ്ഞിരിക്കുന്നു. അബൂസുഫ്യാൻ(റ) പറഞ്ഞു: റസൂൽ(സ)യുടെ സന്ദേശം തീർച്ചയായും വിജയം വരിക്കുമെന്ന് എനിക്ക് ഉറപ്പുണ്ടായിരുന്നു. അങ്ങനെ ഇരിക്കവെയാണ് അല്ലാഹു എന്നെ ഇസ്ലാമിലേക്കെത്തിച്ചത്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'آل عمران: ٦٤', null, 968, 971, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنْ قَيْسِ بْنِ عُبَادٍ قَالَ: كَانَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُونَ الصَّوْتَ عِنْدَ الْقِتَالِ. عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِمِثْلِ ذَلِكَ. (د)', 'ഖൈസുബ്നു ഉബാദ്(റ): നബി(സ)യുടെ അനുചരന്മാർ യുദ്ധസമയത്ത് ശബ്ദ കോലഹലങ്ങളെ വെറുക്കുമായിരുന്നു. നബി(സ)യെക്കുറിച്ച് അബൂമൂസൽ അശ്അരി(റ) ഇതുപോലുള്ള ഒരു ഹദീസ് റിപ്പോർട്ട് ചെയ്തിട്ടുണ്ട്. (ദ)', 'قَيْسِ بْنِ عُبَادٍ قَالَ', 'ഖൈസുബ്നു ഉബാദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 971, 971, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا لَقِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُشْرِكِينَ يَوْمَ حُنَيْنٍ فَانْكَشَفُوا، نَزَلَ عَنْ بَغْلَتِهِ فَتَرَجَّلَ. (خ,د)', 'ബറാഅ്(റ): ഹുനൈൻ യുദ്ധദിവസം നബി(സ) ബഹുദൈവാരാധകരോട് പോരാടുകയും അവർ പിന്തിരിയുകയും ചെയ്തപ്പോൾ നബി(സ) തന്റെ കഴുതപ്പുറത്തു നിന്നിറങ്ങി കാൽനടയായി സഞ്ചരിച്ചു. (ബു,ദ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 971, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أَبُو طَلْحَةَ لَا يَصُومُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَجْلِ الْغَزْوِ، فَلَمَّا قُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ أَرَهُ مُفْطِرًا إِلَّا يَوْمَ فِطْرٍ أَوْ أَضْحَى. (خ)', 'അനസ്(റ): യുദ്ധം കാരണത്താൽ അബൂത്വൽഹ(റ) റസൂൽ(സ)യുടെ കാലത്ത് നോമ്പനുഷ്ഠിക്കാറുണ്ടായിരുന്നില്ല. നബി(സ) വഫാത്തായപ്പോൾ ചെറിയ പെരുന്നാൾ ദിവസമോ വലിയ പെരുന്നാൾ ദിവസമോ മാത്രമാണ് നോമ്പനുഷ്ഠിക്കാത്തവരായി ഞാനവരെ കണ്ടത്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا بَلَغَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ مَرَّ الظَّهْرَانِ، فَآذَنَنَا بِلِقَاءِ الْعَدُوِّ، فَأَمَرَنَا بِالْفِطْرِ، فَأَفْطَرْنَا أَجْمَعُونَ. (ت)', 'അബൂസഇൗദുൽ ഖുദ്രി(റ): മക്കാ വിജയത്തിന്റെ വർഷം നബി(സ) മർറുള്ളഹ്റാൻ എന്ന സ്ഥലത്തെത്തിയപ്പോൾ ശത്രുക്കളോട് പോരാടുവാൻ ഞങ്ങൾക്ക് അനുമതി നൽകുകയും നോമ്പ് മുറിക്കാൻ ഞങ്ങളോട് കൽപിക്കുകയും ചെയ്തു. അങ്ങനെ ഞങ്ങളെല്ലാവരും നോമ്പ് മുറിച്ചു. (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദുൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ يَوْمَ أُحُدٍ: "اللَّهُمَّ إِنَّكَ إِنْ تَشَأْ لَا تُعْبَدْ فِي الْأَرْضِ". (م)', 'അനസ്(റ): ഉഹ്ദ് യുദ്ധദിവസം റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞിരുന്നു: "അല്ലാഹുവേ, നീ ഉദ്ദേശിക്കുന്ന പക്ഷം നീ ഈ ഭൂമിയിൽ ആരാധിക്കപ്പെടുകയില്ല." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا غَزَا قَالَ: "اللَّهُمَّ أَنْتَ عَضُدِي وَنَصِيرِي، بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ". (د,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) യുദ്ധം ചെയ്താൽ ഇപ്രകാരം പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ, എന്റെ അവലംബവും സഹായിയും നീയാണ്. നിന്നെക്കൊണ്ട് ഞാൻ തന്ത്രം പ്രയോഗിക്കുകയും ധൈര്യത്തോടെ മുന്നേറുകയും യുദ്ധം ചെയ്യുകയും ചെയ്യുന്നു." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثِنْتَانِ لَا تُرَدَّانِ، أَوْ قَلَّمَا تُرَدَّانِ: الدُّعَاءُ عِنْدَ النِّدَاءِ، وَعِنْدَ الْبَأْسِ حِينَ يُلْحِمُ بَعْضُهُمْ". وَفِي رِوَايَةٍ: "وَوَقْتُ الْمَطَرِ". (د)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു കാര്യങ്ങൾ തട്ടപ്പെടുകയില്ല. അല്ലെങ്കിൽ അവ തട്ടപ്പെടുന്നത് വളരെ വിരളമാണ്. ബാങ്ക് വിളിക്കുന്ന സമയത്ത് പ്രാർത്ഥിക്കൽ, ഒരു സൈന്യം മറ്റേ സൈന്യത്തിലേക്ക് ഇരച്ചുകയറുമ്പോൾ (യുദ്ധസമയത്ത്) പ്രാർത്ഥിക്കൽ." മറ്റൊരു നിവേദനത്തിൽ: "മഴയുടെ സമയത്ത് പ്രാർത്ഥിക്കലും." (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=371), 1, 'وَفِي رِوَايَةٍ: "وَوَقْتُ الْمَطَرِ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "മഴയുടെ സമയത്ത് പ്രാർത്ഥിക്കലും." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُهُ يَقُولُ – يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – يَدْعُو عَلَى الْأَحْزَابِ، فَقَالَ: "اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الْأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ". (ق,د,ت,جه)', 'ഇബ്നു അബീഔഫാ(റ): ശത്രുസമൂഹ(അഹ്സാബ്)ത്തിനെതിരെ നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കുന്നത് ഞാൻ കേട്ടു: "ഗ്രന്ഥമിറക്കിയവനും വിചാരണയെ വേഗത്തിലാക്കുന്നവനുമായ അല്ലാഹുവേ, നീ ശത്രുസമൂഹങ്ങളെ പരാജയപ്പെടുത്തേണമേ, അല്ലാഹുവേ നീയവരെ പരാജയപ്പെടുത്തുകയും അവരെ വിറപ്പിക്കുകയും ചെയ്യേണമേ." (ബു,മു,ദ,തു,ജ)', 'ابْنِ أَبِي أَوْفَى', 'ഇബ്നു അബീഔഫാ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 972, 973, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكِبَ حِمَارًا عَلَيْهِ إِكَافٌ، تَحْتَهُ قَطِيفَةٌ فَدَكِيَّةٌ، وَأَرْدَفَ وَرَاءَهُ أُسَامَةَ، وَهُوَ يَعُودُ سَعْدَ بْنَ عُبَادَةَ فِي بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ، وَذَاكَ قَبْلَ وَقْعَةِ بَدْرٍ، حَتَّى مَرَّ بِمَجْلِسٍ فِيهِ أَخْلَاطٌ مِنَ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الْأَوْثَانِ وَالْيَهُودِ، فِيهِمْ عَبْدُ اللَّهِ بْنُ أُبَيٍّ وَفِي الْمَجْلِسِ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ، فَلَمَّا غَشِيَتِ الْمَجْلِسَ عَجَاجَةُ الدَّابَّةِ خَمَّرَ عَبْدُ اللَّهِ بْنُ أُبَيٍّ أَنْفَهُ بِرِدَائِهِ، ثُمَّ قَالَ: لَا تُغَبِّرُوا عَلَيْنَا. فَسَلَّمَ عَلَيْهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ وَقَفَ فَنَزَلَ، فَدَعَاهُمْ إِلَى اللَّهِ وَقَرَأَ عَلَيْهِمُ الْقُرْآنَ، فَقَالَ عَبْدُ اللَّهِ بْنُ أُبَيٍّ: أَيُّهَا الْمَرْءُ، لَا أَحْسَنَ مِنْ هَذَا، إِنْ كَانَ مَا تَقُولُ حَقًّا فَلَا تُؤْذِنَا فِي مَجَالِسِنَا، وَارْجِعْ إِلَى رَحْلِكَ، فَمَنْ جَاءَكَ مِنَّا فَاقْصُصْ عَلَيْهِ. فَقَالَ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ رَضِيَ اللَّهُ عَنْهُ: اغْشَنَا فِي مَجَالِسِنَا، فَإِنَّا نُحِبُّ ذَلِكَ. قَالَ: فَاسْتَبَّ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْيَهُودُ حَتَّى هَمُّوا أَنْ يَتَوَاثَبُوا، فَلَمْ يَزَلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخَفِّضُهُمْ، ثُمَّ رَكِبَ دَابَّتَهُ حَتَّى دَخَلَ عَلَى سَعْدِ بْنِ عُبَادَةَ، فَقَالَ: "أَيْ سَعْدُ أَلَمْ تَسْمَعْ إِلَى مَا قَالَ أَبُو حُبَابٍ – يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَيٍّ – قَالَ: كَذَا وَكَذَا". قَالَ: اعْفُ عَنْهُ يَا رَسُولَ اللَّهِ وَاصْفَحْ، فَوَاللَّهِ لَقَدْ أَعْطَاكَ اللَّهُ الَّذِي أَعْطَاكَ، وَلَقَدِ اصْطَلَحَ أَهْلُ هَذِهِ الْبُحَيْرَةِ أَنْ يُتَوِّجُوهُ فَيُعَصِّبُوهُ بِالْعِصَابَةِ، فَلَمَّا رَدَّ اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَهُ شَرِقَ بِذَلِكَ، فَذَلِكَ فَعَلَ بِهِ مَا رَأَيْتَ. فَعَفَا عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'ഉസാമതുബ്നു സൈദ്(റ): ഫദക് എന്ന നാട്ടിൽ നിന്ന് നിർമ്മിച്ച വസ്ത്രത്തിനു മുകളിൽ ജീനിവെച്ച് ഉസാമ(റ)വിനെ പിന്നിലിരുത്തി റസൂൽ(സ) ഒരു കഴുതപ്പുറത്ത് കയറി. ബനുൽഹാരിസുബ്നു ഖസ്റജുകാരിൽപെട്ട സഅ്ദുബ്നു ഉബാദ(റ)വിനെ സന്ദർശിക്കാൻ പോവുകയായിരുന്നു റസൂൽ(സ). ഈ സംഭവം ബദർ യുദ്ധത്തിനു മുമ്പായിരുന്നു. അങ്ങനെ റസൂൽ(സ) മുസ്ലിംകളും ബിംബാരാധകരായ മുശ്രികുകളും യഹൂദരുമടങ്ങുന്ന ഒരു വേദിക്കടുത്തുകൂടെ നടന്നുപോയി. അക്കൂട്ടത്തിൽ അബ്ദുല്ലാഹിബ്നു ഉബയ്യും വേദിയിൽ അബ്ദുല്ലാഹിബ്നു റവാഹ(റ)വുമെല്ലാം ഉണ്ടായിരുന്നു. മൃഗത്തിന്റെ കാലടികളിൽ നിന്നും പൊടി പടലങ്ങൾ ആ വേദിയിലേക്കെത്തിയപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് തന്റെ തട്ടംകൊണ്ട് മൂക്ക് പൊത്തി. എന്നിട്ട് പറഞ്ഞു: നിങ്ങൾ ഞങ്ങളുടെ മേൽ പൊടി പാറിക്കരുത്. അപ്പോൾ നബി(സ) അവരോട് സലാം പറയുകയും വാഹനം നിർത്തി അവിടെ ഇറങ്ങുകയും ചെയ്തു. എന്നിട്ട് അവരെ അല്ലാഹുവിലേക്ക് ക്ഷണിക്കുകയും അവർക്ക് ഖുർആൻ ഓതിക്കേൾപിക്കുകയും ചെയ്തു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് പറഞ്ഞു: മനുഷ്യാ, ഇതിനേക്കാൾ നല്ല ഒന്നുമില്ല. നീ പറയുന്നത് സത്യമാണെങ്കിൽ ഞങ്ങളുടെ വേദിയിൽ വന്ന് ശല്യപ്പെടുത്തരുത്. നീ നിന്റെ വീട്ടിലേക്ക് മടങ്ങുക. ആരെങ്കിലും അങ്ങോട്ട് വരുന്നുവെങ്കിൽ അവർക്കിത് പറഞ്ഞുകൊടുക്കുക. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു റവാഹ(റ) പറഞ്ഞു: റസൂലേ, അങ്ങ് ഞങ്ങളുടെ വേദിയിലേക്ക് വരണം. ഞങ്ങളത് ഇഷടപ്പെടുന്നു. നിവേദകൻ പറഞ്ഞു: അപ്പോൾ മുസ്ലിംകളും ബഹുദൈവാരാധകരും ജൂതന്മാരുമെല്ലാം പരസ്പരം ആക്ഷേപിക്കാൻ തുടങ്ങുകയും അതൊരു കലഹത്തിന്റെ വക്കോളമെത്തുകയും ചെയ്തു. നബി(സ) അവരെ ശാന്തമാക്കിക്കൊണ്ടേയിരുന്നു. ശേഷം നബി(സ) വാഹനത്തിൽ കയറി സഅ്ദുബ്നു ഉബാദ(റ)വിന്റെ അടുത്തു പോയി. എന്നിട്ട് പറഞ്ഞു: "സഅ്ദേ, അബൂഹുബാബ് (അബ്ദുല്ലാഹിബ്നു ഉബയ്യ്) ഇപ്രകാരം പറഞ്ഞതെല്ലാം നീ കേട്ടില്ലേ." സഅ്ദ്(റ) പറഞ്ഞു: റസൂലേ, അങ്ങ് അവന് മാപ്പ് കൊടുത്താലും. അല്ലാഹു തന്നെ സത്യം, അങ്ങേക്ക് അല്ലാഹു ധാരാളം ഗുണങ്ങൾ ചെയ്തുതന്നിരിക്കുന്നു. ഈ നാട്ടുകാർ ആ മനുഷ്യനെ അവരുടെ നേതാവാക്കാനും കിരീടധാരണം നടത്താനും തീരുമാനിച്ചിരുന്നു. അങ്ങേക്ക് അവതരിപ്പിച്ചു തന്ന സത്യസന്ദേശം കൊണ്ട് അല്ലാഹു ആ കാര്യത്തെ ഇല്ലാതാക്കിയപ്പോൾ അവൻ അങ്ങയുടെ അസൂയാലുവായി. അതിനാലാണ് അങ്ങ് കണ്ട ഈ പ്രവർത്തനങ്ങൾ അവൻ ചെയ്തത്. അങ്ങനെ നബി(സ) അബ്ദുല്ലാഹിബ്നു ഉബയ്യിന് മാപ്പു നൽകി. (മു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 973, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَعَدَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ الْهِنْدِ، فَإِنْ أَدْرَكْتُهَا أُنْفِقْ فِيهَا نَفْسِي وَمَالِي، فَإِنْ أُقْتَلْ – وَفِي رِوَايَةٍ: قُلْتُ – كُنْتُ مِنْ أَفْضَلِ الشُّهَدَاءِ، وَإِنْ أَرْجِعْ – فِي رِوَايَةٍ: رَجَعْتُ – فَأَنَا أَبُو هُرَيْرَةَ الْمُحَرَّرُ. (ن)', 'അബൂഹുറൈറ(റ): ഇന്ത്യയോട് യുദ്ധമുണ്ടാവുമെന്ന് റസൂൽ(സ) ഞങ്ങളോട് വാഗ്ദാനം ചെയ്തു. അന്ന് ഞാനുണ്ടാവുകയാണെങ്കിൽ എന്റെ ശരീരവും മുതലും ഞാൻ അതിൽ ചെലവഴിക്കും. ഞാൻ കൊല്ലപ്പെടുകയാണെങ്കിൽ ഏറ്റവും ശ്രേഷ്ഠരായ രക്തസാക്ഷികളുടെ കൂട്ടത്തിലായിരിക്കും. ജീവനോടെ മടങ്ങുകയാണെങ്കിൽ സ്വതന്ത്രനായ അബൂഹുറൈറയായി ഞാൻ മടങ്ങും. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=374), 1, 'وَفِي رِوَايَةٍ: قُلْتُ – كُنْتُ مِنْ أَفْضَلِ الشُّهَدَاءِ، وَإِنْ أَرْجِعْ – فِي رِوَايَةٍ: رَجَعْتُ – فَأَنَا أَبُو هُرَيْرَةَ الْمُحَرَّرُ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 375, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ، مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عِصَابَتَانِ مِنْ أُمَّتِي أَحْرَزَهُمَا اللَّهُ مِنَ النَّارِ: عِصَابَةٌ تَغْزُو الْهِنْدَ، وَعِصَابَةٌ تَكُونُ مَعَ عِيسَى بْنِ مَرْيَمَ عَلَيْهِمَا السَّلَامُ". (ن)', 'റസൂൽ(സ)യുടെ സേവകനായിരുന്ന സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽപെട്ട രണ്ട് സംഘങ്ങളെ അല്ലാഹു നരകത്തിൽ നിന്ന് സംരക്ഷിക്കും: ഇന്ത്യയോട് യുദ്ധം ചെയ്യുന്ന കൂട്ടർ, ഈസബ്നു മർയം(അ)നോടൊപ്പമുണ്ടാവുന്ന കൂട്ടർ എന്നിവരാണവർ." (ന)', 'ثَوْبَانَ', 'റസൂൽ(സ)യുടെ സേവകനായിരുന്ന സൗബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 376, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا التُّرْكَ، صِغَارَ الْأَعْيُنِ، حُمْرَ الْوُجُوهِ، ذُلْفَ الْأُنُوفِ، كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ، وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمُ الشَّعَرُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ചെറിയ കണ്ണുകളും ചുവന്ന മുഖങ്ങളും പതിഞ്ഞ മൂക്കുകളുമുള്ള തുർക്കികളുമായി നിങ്ങൾ യുദ്ധം ചെയ്യുംവരെ ലോകം അവസാനിക്കുകയില്ല. അവരുടെ മുഖങ്ങൾ തോൽ കൊണ്ട് പൊതിഞ്ഞ പരിച പോലെയായിരിക്കും. അപ്രകാരം തന്നെ രോമം കൊണ്ടുണ്ടാക്കിയ ചെരിപ്പ് ധരിക്കുന്ന ഒരു ജനതയുമായി നിങ്ങൾ യുദ്ധം ചെയ്യുംവരെയും ലോകം അവസാനിക്കുകയില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 377, 'عَنْ أَبِي سُكَيْنَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمَّا أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَفْرِ الْخَنْدَقِ عَرَضَتْ لَهُمْ صَخْرَةٌ، حَالَتْ بَيْنَهُمْ وَبَيْنَ الْحَفْرِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَخَذَ الْمِعْوَلَ وَوَضَعَ رِدَاءَهُ نَاحِيَةَ الْخَنْدَقِ وَقَالَ: {تَمَّتْ كَلِمَةُ رَبِّكَ صِدْقًا وَعَدْلًا لَا مُبَدِّلَ لِكَلِمَاتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ} [الأنعام: ١١٥] فَنَدَرَ ثُلُثُ الْحَجَرِ، وَسَلْمَانُ الْفَارِسِيُّ قَائِمٌ يَنْظُرُ، فَبَرَقَ مَعَ ضَرْبَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَرْقَةٌ، ثُمَّ ضَرَبَ الثَّانِيَةَ وَقَالَ: {تَمَّتْ كَلِمَةُ رَبِّكَ صِدْقًا وَعَدْلًا لَا مُبَدِّلَ لِكَلِمَاتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ} فَنَدَرَ الثُّلُثُ الْآخَرُ، فَبَرَقَتْ بَرْقَةٌ فَرَآهَا سَلْمَانُ، ثُمَّ ضَرَبَ الثَّالِثَةَ وَقَالَ: {تَمَّتْ كَلِمَةُ رَبِّكَ صِدْقًا وَعَدْلًا لَا مُبَدِّلَ لِكَلِمَاتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ} فَنَدَرَ الثُّلُثُ الْبَاقِي، وَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخَذَ رِدَاءَهُ وَجَلَسَ. قَالَ سَلْمَانُ: يَا رَسُولَ اللَّهِ، رَأَيْتُكَ حِينَ ضَرَبْتَ مَا تَضْرِبُ ضَرْبَةً إِلَّا كَانَتْ مَعَهَا بَرْقَةٌ؟ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا سَلْمَانُ، رَأَيْتَ ذَلِكَ". فَقَالَ: إِي وَالَّذِي بَعَثَكَ بِالْحَقِّ يَا رَسُولَ اللَّهِ. قَالَ: "فَإِنِّي حِينَ ضَرَبْتُ الضَّرْبَةَ الْأُولَى رُفِعَتْ لِي مَدَائِنُ كِسْرَى وَمَا حَوْلَهَا، وَمَدَائِنُ كَثِيرَةٌ حَتَّى رَأَيْتُهَا بِعَيْنَيَّ". قَالَ لَهُ مَنْ حَضَرَهُ مِنْ أَصْحَابِهِ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَفْتَحَهَا عَلَيْنَا، وَيُغَنِّمَنَا دِيَارَهُمْ وَيُخَرِّبَ بِأَيْدِينَا بِلَادَهُمْ. فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ. "ثُمَّ ضَرَبْتُ الضَّرْبَةَ الثَّانِيَةَ فَرُفِعَتْ لِي مَدَائِنُ قَيْصَرَ وَمَا حَوْلَهَا حَتَّى رَأَيْتُهَا بِعَيْنَيَّ". قَالُوا: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَفْتَحَهَا عَلَيْنَا، وَيُغَنِّمَنَا دِيَارَهُمْ وَيُخَرِّبَ بِأَيْدِينَا بِلَادَهُمْ. فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ. "ثُمَّ ضَرَبْتُ الثَّالِثَةَ فَرُفِعَتْ لِي مَدَائِنُ الْحَبَشَةِ وَمَا حَوْلَهَا مِنَ الْقُرَى، حَتَّى رَأَيْتُهَا بِعَيْنَيَّ". قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "دَعُوا الْحَبَشَةَ مَا وَدَعُوكُمْ، وَاتْرُكُوا التُّرْكَ مَا تَرَكُوكُمْ". (ن)', 'നബി(സ)യുടെ ഒരു അനുചരനിൽ നിന്നും അബൂസുകൈന(റ): നബി(സ) കിടങ്ങ് കുഴിക്കാൻ പറഞ്ഞപ്പോൾ ഒരു പാറ പ്രത്യക്ഷപ്പെട്ടു. സ്വഹാബികൾക്ക് കിടങ്ങ് കുഴിക്കാൻ അത് തടസ്സമായി. അപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റു കോടാലി എടുക്കുകയും തന്റെ തട്ടം കിടങ്ങിന്റെ ഒരു ഭാഗത്ത് വെക്കുകയും ചെയ്തു. എന്നിട്ട് ഇപ്രകാരം ചൊല്ലി: ''നീതി പൂർവ്വവും സത്യസന്ധവുമായി നിന്റെ നാഥന്റെ വചനങ്ങൾ പൂർത്തിയായിരിക്കുന്നു. അവന്റെ വചനങ്ങളെ മാറ്റിമറിക്കുന്ന ഒരു കാര്യവുമില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്.'' (അൽഅൻആം: 115) അപ്പോൾ പാറയുടെ മൂന്നിലൊരു ഭാഗം അടർന്നു പോന്നു. സൽമാനുൽ ഫാരിസി(റ) അത് നോക്കി അവിടെ നിൽക്കുകയായിരുന്നു. റസൂൽ(സ)യുടെ വെട്ടോടൊപ്പം ഒരു പ്രകാശം മിന്നി. ശേഷം ''നീതി പൂർവ്വവും സത്യസന്ധവുമായി നിന്റെ നാഥന്റെ വചനങ്ങൾ പൂർത്തിയായിരിക്കുന്നു. അവന്റെ വചനങ്ങളെ മാറ്റിമറിക്കുന്ന ഒരു കാര്യവുമില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്'' എന്ന് ചൊല്ലി രണ്ടാമത്തെ വെട്ടും വെട്ടി. അപ്പോൾ മൂന്നിലൊരു ബാഗം കൂടി അടർന്നു പോന്നു. അപ്പോഴും ഒരു പ്രകാശം മിന്നുകയും സൽമാൻ(റ) അത് കാണുകയും ചെയ്തു. വീണ്ടും ''നീതി പൂർവ്വവും സത്യസന്ധവുമായി നിന്റെ നാഥന്റെ വചനങ്ങൾ പൂർത്തിയായിരിക്കുന്നു. അവന്റെ വചനങ്ങളെ മാറ്റിമറിക്കുന്ന ഒരു കാര്യവുമില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്'' എന്ന് ചൊല്ലി മൂന്നാമത്തെ വെട്ട് വെട്ടി. അതോടെ ബാക്കിയുള്ള മൂന്നിലൊരു ഭാഗം കൂടി അടർന്നു പോന്നു. ശേഷം നബി(സ) തന്റെ തട്ടം എടുത്ത് ഒരു സ്ഥലത്ത് ഇരുന്നു. സൽമാൻ(റ) പറഞ്ഞു: റസൂലേ, അങ്ങ് ഓരോ വെട്ട് വെട്ടുമ്പോഴും അതിന്റെ കൂടെ ഞാനൊരു പ്രകാശം കണ്ടിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "സൽമാനേ, നീയതു കണ്ടോ?" സൽമാൻ(റ) പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയെ സത്യവുമായി അയച്ച അല്ലാഹു തന്നെ സത്യം. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ഒന്നാമത്തെ വെട്ട് വെട്ടിയപ്പോൾ കിസ്റയുടെ പട്ടണങ്ങളും അതിന്റെ ചുറ്റു ഭാഗങ്ങളും വേറെ കുറെ പട്ടണങ്ങളും എനിക്ക് പ്രദർശിപ്പിക്കപ്പെടുകയും ഞാൻ അവയെല്ലാം കാണുകയും ചെയ്തു." ഇതു കേട്ട് അവിടെ സന്നിഹിതരായിരുന്ന റസൂൽ(സ)യുടെ അനുചരന്മാർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവയെ അല്ലാഹു ഞങ്ങൾക്ക് കീഴ്പെടുത്തിത്തരാനും അവരുടെ വീടുകളെ യുദ്ധമുതലായി ഞങ്ങൾക്ക് നൽകുവാനും അവരുടെ നാടുകളെ ഞങ്ങളുടെ കരങ്ങളാൽ നശിപ്പിക്കുവാനും അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുക. അപ്പോൾ റസൂൽ(സ) അപ്രകാരം പ്രാർത്ഥിച്ചു. തുടർന്നു പറഞ്ഞു: "ശേഷം ഞാൻ രണ്ടാമത്തെ വെട്ട് വെട്ടിയപ്പോൾ വൈസറിന്റെ പട്ടണങ്ങളും അതിന്റെ ചുറ്റുഭാഗങ്ങളും എനിക്ക് പ്രദർശിപ്പിക്കപ്പെടുകയും ഞാനവ കാണുകയും ചെയ്തു." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവയെ അല്ലാഹു ഞങ്ങൾക്ക് കീഴ്പെടുത്തിത്തരാനും അവരുടെ വീടുകളെ യുദ്ധമുതലായി ഞങ്ങൾക്ക് നൽകുവാനും അവരുടെ നാടുകളെ ഞങ്ങളുടെ കരങ്ങളാൽ നശിപ്പിക്കുവാനും അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുക. അപ്പോൾ റസൂൽ(സ) അപ്രകാരം പ്രാർത്ഥച്ചു. എന്നിട്ട് പറഞ്ഞു: "ശേഷം മൂന്നാമത്തെ വെട്ട് വെട്ടിയപ്പോൾ അബ്സീനിയക്കാരുടെ പട്ടണങ്ങളും അതിന്റെ ചുറ്റുഭാഗത്തുള്ള പ്രദേശങ്ങളും എനിക്ക് പ്രദർശിപ്പിക്കപ്പെടുകയും ഞാനവ കാണുകയും ചെയ്തു." തുടർന്ന് പറഞ്ഞു: "അബ്സീനിയക്കാർ നിങ്ങളെ ഒഴിവാക്കുന്ന കാലത്തോളം നിങ്ങൾ അവരെയും ഒഴിവാക്കിയിടുക. തുർക്കികൾ നിങ്ങളെ ഒഴിവാക്കുന്നിടത്തോളം നിങ്ങൾ അവരെയും ഒഴിവാക്കുക." (ന)', 'أَبِي سُكَيْنَةَ', 'നബി(സ)യുടെ ഒരു അനുചരനിൽ നിന്നും അബൂസുകൈന(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأنعام: ١١٥', null, 975, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 378, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يُقَاتِلَ الْمُسْلِمُونَ التُّرْكَ، قَوْمًا وُجُوهُهُمْ كَالْمَجَانِّ الْمُطْرَقَةِ، يَلْبَسُونَ الشَّعَرَ وَيَمْشُونَ فِي الشَّعَرِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തോൽ കൊണ്ട് പൊതിഞ്ഞ പരിചകൾ പോലുള്ള മുഖങ്ങളുള്ള, രോമത്താലുണ്ടാക്കിയ ചെരിപ്പും വസ്ത്രവും ധരിക്കുന്ന തുർക്കികളോട് മുസ്ലിംകൾ യുദ്ധം ചെയ്യുംവരെ അന്ത്യനാളുണ്ടാവുകയില്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 976, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 379, 'عَنْ أُمِّ حَرَامٍ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا سَمِعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَوَّلُ جَيْشٍ مِنْ أُمَّتِي يَغْزُونَ الْبَحْرَ قَدْ أَوْجَبُوا". قَالَتْ أُمُّ حَرَامٍ: قُلْتُ: يَا رَسُولَ اللَّهِ أَنَا فِيهِمْ؟ قَالَ: "أَنْتِ فِيهِمْ". قَالَتْ: ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَوَّلُ جَيْشٍ مِنْ أُمَّتِي يَغْزُونَ مَدِينَةَ قَيْصَرَ مَغْفُورٌ لَهُمْ". فَقُلْتُ: أَنَا فِيهِمْ يَا رَسُولَ اللَّهِ؟ قَالَ: "لَا". (خ)', 'ഉമ്മുഹറാം(റ): നബി(സ) പറയുന്നത് അവർ കേട്ടു: "കടലിലൂടെ യാത്ര ചെയ്ത് യുദ്ധം ചെയ്യുന്ന എന്റെ സമുദായത്തിലെ ആദ്യ സൈന്യം സ്വർഗ്ഗത്തിന്റെ അവകാശികളാണ്." ഉമ്മുഹറാം(റ) ചോദിച്ചു: റസൂലേ, ഞാനും അവരുടെ കൂട്ടത്തിലുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ. നീയും അവരുടെ കൂട്ടത്തിലുണ്ട്." ശേഷം നബി(സ) പറഞ്ഞു: "വൈസറിന്റെ പട്ടണത്തോട് യുദ്ധം ചെയ്യുന്ന എന്റെ സമുദായത്തിലെ ആദ്യ സൈന്യം പാപമോചനം നൽകപ്പെടുന്നവരാണ്." ഉമ്മുഹറാം(റ) ചോദിച്ചു: റസൂലേ, ഞാനും അവരുടെ കൂട്ടത്തിലുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "ഇല്ല." (ബു)', 'أُمِّ حَرَامٍ', 'ഉമ്മുഹറാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 976, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 380, 'عَنْ قَيْسِ بْنِ شَمَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهَا أُمُّ خَلَّادٍ، وَهِيَ مُنْتَقِبَةٌ، تَسْأَلُ عَنِ ابْنِهَا وَهُوَ مَقْتُولٌ، فَقَالَ لَهَا بَعْضُ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جِئْتِ تَسْأَلِينَ عَنِ ابْنِكِ وَأَنْتِ مُنْتَقِبَةٌ؟ فَقَالَتْ: إِنْ أُرْزَأْ إِبْنِي فَلَنْ أُرْزَأَ حَيَائِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ابْنُكِ لَهُ أَجْرُ شَهِيدَيْنِ". قَالَتْ: وَلِمَ ذَاكَ يَا رَسُولَ اللَّهِ؟ قَالَ: "لِأَنَّهُ قَتَلَهُ أَهْلُ الْكِتَابِ". (د)', 'ഖൈസുബ്നു ശമ്മാസ്(റ): ഉമ്മുഖല്ലാദ്(റ) എന്ന് പേരുള്ള ഒരു സ്ത്രീ മുഖം മറച്ചുകൊണ്ട്, കൊല്ലപ്പെട്ട തന്റെ മകനെക്കുറിച്ച് ചോദിക്കാൻ വേണ്ടി നബി(സ)യുടെ സന്നിധിയിൽ വന്നു. നബി(സ)യുടെ അനുചരരിൽ ചിലർ മഹതിയോട് ഇപ്രകാരം ചോദിച്ചു: മുഖം മറച്ചുകൊണ്ടാണോ തന്റെ മകനെക്കുറിച്ച് ചോദിക്കാൻ നിങ്ങൾ വരുന്നത്? മഹതി പറഞ്ഞു: എന്റെ മകനെ എനിക്ക് നഷ്ടപ്പെട്ടെങ്കിലും എന്റെ ലജ്ജ നഷ്ടപ്പെടുകയില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ മകന് രണ്ട് രക്തസാക്ഷികളുടെ പ്രതിഫലമുണ്ട്." മഹതി ചോദിച്ചു: റസൂലേ, എന്ത് കൊണ്ടാണത്? റസൂൽ(സ) പറഞ്ഞു: "കാരണം അവനെ വേദക്കാരാണ് വധിച്ചത്." (ദ)', 'قَيْسِ بْنِ شَمَّاسٍ', 'ഖൈസുബ്നു ശമ്മാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 976, 977, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 381, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا نَحْنُ فِي الْمَسْجِدِ إِذْ خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَقَالَ انْطَلِقُوا". فَخَرَجْنَا مَعَهُ حَتَّى جِئْنَاهُمْ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَادَاهُمْ، فَقَالَ: "يَا مَعْشَرَ يَهُودَ أَسْلِمُوا تَسْلَمُوا". فَقَالُوا: قَدْ بَلَّغْتَ يَا أَبَا الْقَاسِمِ. فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَلِكَ أُرِيدُ، أَسْلِمُوا تَسْلَمُوا". فَقَالُوا: قَدْ بَلَّغْتَ يَا أَبَا الْقَاسِمِ. فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَلِكَ أُرِيدُ". فَقَالَ لَهُمُ الثَّالِثَةَ، فَقَالَ: "اعْلَمُوا أَنَّمَا الْأَرْضُ لِلَّهِ وَرَسُولِهِ، وَأَنِّي أُرِيدُ أَنْ أُجْلِيَكُمْ مِنْ هَذِهِ الْأَرْضِ، فَمَنْ وَجَدَ مِنْكُمْ بِمَالِهِ شَيْئًا فَلْيَبِعْهُ، وَإِلَّا فَاعْلَمُوا أَنَّ الْأَرْضَ لِلَّهِ وَرَسُولِهِ". (ق,د)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ പള്ളിയിൽ ഇരുന്നുകൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു പറഞ്ഞു: "നിങ്ങൾ (യഹൂദികളുടെ അടുത്തേക്ക്) വരിക." അങ്ങനെ റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ജൂതന്മാരുടെ അടുത്ത് പോയി. റസൂൽ(സ) എഴുന്നേറ്റ് അവരോട് ഇപ്രകാരം വിളിച്ചുപറഞ്ഞു: "യഹൂദികളേ, നിങ്ങൾ മുസ്ലിംകളാവുക, എന്നാൽ രക്ഷപ്പെടാം." അവർ പറഞ്ഞു: അബൂൽ ഖാസിമേ, നിന്റെ സന്ദേശം നീ ഞങ്ങൾക്ക് എത്തിച്ചു തന്നിരിക്കുന്നു. റസൂൽ(സ) അവരോട് പറഞ്ഞു: "അതു തന്നെയാണ് ഞാനുദ്ദേശിക്കുന്നത്, നിങ്ങൾ മുസ്ലിംകളാവുക, രക്ഷപ്പെടാം." അവർ പറഞ്ഞു: അബൂൽ ഖാസിമേ, നിന്റെ സന്ദേശം നീ ഞങ്ങൾക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു. റസൂൽ(സ) അവരോട് പറഞ്ഞു: "അതുതന്നെയാണ് ഞാൻ ഉദ്ദേശിക്കുന്നത്." മൂന്നാം പ്രാവശ്യം അവരോട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അറിയുക, ഈ ഭൂമി അല്ലാഹുവിന്റേതും അവന്റെ റസൂലിന്റേതുമാണ്, നിങ്ങളെ ഈ നാട്ടിൽനിന്ന് തുരത്താൻ ഞാൻ ആഗ്രഹിക്കുന്നു. നിങ്ങളുടെ മുതലിൽ നിന്ന് കയ്യിൽ കിട്ടുന്നതെല്ലാം നിങ്ങൾ വിൽക്കുക, ഇല്ലായെങ്കിൽ ഈ ഭൂമി അല്ലാഹുവിന്റേതും അവന്റെ റസൂലിന്റേതുമാണ് നിങ്ങൾ മനസ്സിലാക്കുക." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 977, 977, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 382, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُقَاتِلُونَ الْيَهُودَ حَتَّى يَخْتَبِيَ أَحَدُهُمْ وَرَاءَ الْحَجَرِ، فَيَقُولُ: يَا عَبْدَ اللَّهِ، هَذَا يَهُودِيٌّ وَرَائِي فَاقْتُلْهُ". وَفِي رِوَايَةٍ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا الْيَهُودَ". بَاقِي الْحَدِيثِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ജൂതന്മാരോട് യുദ്ധം ചെയ്യും. അങ്ങനെ അവർ കല്ലുകൾക്കപ്പുറത്ത് മറഞ്ഞു നിൽക്കും. അപ്പോൾ കല്ല് പറയും. ഓ ദൈവദാസാ (മുസ്ലിമേ), ഇതാ ഒരു ജൂതൻ എന്റെ മറുവശത്തിരിക്കുന്നു, അവനെ നീ വധിക്കുക." മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "ജൂതന്മാരോട് നിങ്ങൾ പോരാടുംവരെ അന്ത്യനാളുണ്ടാവുകയില്ല." ശേഷം ഹദീസിന്റെ ബാക്കി ഭാഗം പറഞ്ഞു. (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 977, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=382), 1, 'وَفِي رِوَايَةٍ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا الْيَهُودَ". بَاقِي الْحَدِيثِ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: "ജൂതന്മാരോട് നിങ്ങൾ പോരാടുംവരെ അന്ത്യനാളുണ്ടാവുകയില്ല." ശേഷം ഹദീസിന്റെ ബാക്കി ഭാഗം പറഞ്ഞു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 383, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَأُخْرِجَنَّ الْيَهُودَ وَالنَّصَارَى مِنْ جَزِيرَةِ الْعَرَبِ، حَتَّى لَا أَدَعَ إِلَّا مُسْلِمًا". (م)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ജൂതന്മാരെയും കൃസ്ത്യാനികളെയും അറേബ്യൻ ഉപഭൂഘണ്ഡത്തിൽ നിന്ന് ഞാൻ പുറത്താക്കുക തന്നെ ചെയ്യും, അവിടെ മുസ്ലിംകളെ മാത്രമേ ഞാൻ അവശേഷിപ്പിക്കൂ." (മു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 384, 'عَنْ جَابِرٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَئِنْ عِشْتُ – إِنْ شَاءَ اللَّهُ – لَأُخْرِجَنَّ الْيَهُودَ وَالنَّصَارَى مِنْ جَزِيرَةِ الْعَرَبِ". (م,د,ت)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)വിൽ നിന്ന് ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ജീവിച്ചിരിക്കുകയാണെങ്കിൽ ജൂതന്മാരേയും ക്രസ്താനികളേയും അറേബ്യൻ ഉപഭൂഖണ്ഡത്തിൽനിന്ന് - അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം - ഞാൻ പുറത്താക്കുക തന്നെ ചെയ്യും." (മു,ദ,തു)', 'جَابِرٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 385, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ: {وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ} [الأنفال: ٦٠] أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ، أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ، أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ". [قَالَهَا ثَلَاثًا] (م,ت,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) മിമ്പറിലിരുന്ന് പറയുന്നത് ഞാൻ കേട്ടു: "ശത്രുക്കൾക്കെതിരെ നിങ്ങൾക്കാവുന്ന ശക്തി നിങ്ങൾ സംഭരിക്കുക.'' (അൻഫാൽ: 60) അറിയുക, ശക്തി എന്നാൽ അമ്പെയ്താണ്. അറിയുക, ശക്തി എന്നാൽ അമ്പെയ്താണ്. അറിയുക, ശക്തി എന്നാൽ അമ്പെയ്താണ്." (മു,തു,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], 'قَالَهَا ثَلَاثًا', null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 386, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هَلَكَ كِسْرَى، ثُمَّ لَا يَكُونُ كِسْرَى بَعْدَهُ، وَقَيْصَرُ لَيَهْلِكُنَّ ثُمَّ لَا يَكُونُ قَيْصَرُ بَعْدَهُ، وَلَتُقْسَمَنَّ كُنُوزُهَا فِي سَبِيلِ اللَّهِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കിസ്റാ ചക്രവർത്തിയുടെ നാശം അടുത്തിരിക്കുന്നു. അയാൾക്കു ശേഷം വേറെയൊരു കിസ്റയുണ്ടാവില്ല. കൈസർ ചക്രവർത്തി നശിക്കുകതന്നെ ചെയ്യും. അയാൾക്കു ശേഷം വേറെയൊരു കൈസറുണ്ടാവുകയില്ല. കിസ്റയുടേയും കൈസറിന്റേയും നിധികൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വീതിക്കപ്പെടുകതന്നെ ചെയ്യും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 387, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ غَزْوَةً وَرَّى غَيْرَهَا، وَكَانَ يَقُولُ: "الْحَرْبُ خِدْعَةٌ". (ق,د,ت,ن,جه)', 'കഅ്ബുബ്നു മാലിക്(റ): നബി(സ) യുദ്ധത്തിന് പുറപ്പെടുകയാണെങ്കിൽ വേറെ എന്തിനെങ്കിലുമാണെന്ന് തോന്നിക്കും വിധം സംസാരിക്കുമായിരുന്നു, നബി(സ) ഇപ്രകാരം പറയാറുമുണ്ടായിരുന്നു: "യുദ്ധമെന്നാൽ തന്ത്രം പ്രയോഗിക്കലാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 388, 'عَنِ ابْنِ جَابِرِ بْنِ عَتِيكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "مِنَ الْغَيْرَةِ مَا يُحِبُّ اللَّهُ، وَمِنْهَا مَا يُبْغِضُ اللَّهُ: فَأَمَّا الَّتِي يُحِبُّهَا اللَّهُ فَالْغَيْرَةُ فِي الرِّيبَةِ، وَأَمَّا الْغَيْرَةُ الَّتِي يُبْغِضُهَا اللَّهُ فَالْغَيْرَةُ فِي غَيْرِ رِيبَةٍ. وَإِنَّ مِنَ الْخُيَلَاءِ مَا يُبْغِضُ اللَّهُ، وَمِنْهَا مَا يُحِبُّ اللَّهُ: فَأَمَّا الْخُيَلَاءُ الَّتِي يُحِبُّ اللَّهُ فَاخْتِيَالُ الرَّجُلِ نَفْسَهُ عِنْدَ الْقِتَالِ، وَاخْتِيَالُهُ عِنْدَ الصَّدَقَةِ. وَأَمَّا الَّتِي يُبْغِضُ اللَّهُ: فَاخْتِيَالُهُ فِي الْبَغْيِ وَالْفَخْرِ". (د,ن)', 'ഇബ്നുജാബിറുബ്നു അതീക്(റ): നബി(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹു ഇഷ്ടപ്പെടുന്ന ദേഷ്യവും വെറുക്കുന്ന ദേഷ്യവുമുണ്ട്. സംശയത്തിന്റെ പേരിലുള്ള ദേഷ്യമാണ് അവൻ ഇഷ്ടപ്പെടുന്ന ദേഷ്യം, സംശയത്തിന്റെ പേരിലല്ലാത്ത ദേഷ്യമാണ് അവൻ വെറുക്കുന്ന ദേഷ്യം³. അല്ലാഹു ഇഷ്ടപ്പടുന്ന അഭിമാനവും വെറുക്കുന്ന അഭിമാനവുമുണ്ട്. ധാനധർമ്മം ചെയ്യുമ്പോഴും യുദ്ധം ചെയ്യുമ്പോഴും ഒരാൾക്കുണ്ടാകുന്ന അഭിമാനമാണ് അല്ലാഹു ഇഷ്ടപ്പെടുന്ന അഭിമാനം. അധർമ്മത്തിലും അഹന്തതയിലുമുള്ള അഭിമാനമാണ് അല്ലാഹു വെറുക്കുന്ന അഭിമാനം." (ദ,ന)', 'ابْنِ جَابِرِ بْنِ عَتِيكٍ', 'ഇബ്നുജാബിറുബ്നു അതീക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 979, 979, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 389, 'عَنْ أَسْلَمَ أَبِي عِمْرَانَ قَالَ: غَزَوْنَا مِنَ الْمَدِينَةِ، نُرِيدُ الْقُسْطَنْطِينِيَّةَ وَعَلَى الْجَمَاعَةِ عَبْدُ الرَّحْمَنِ بْنُ خَالِدِ بْنِ الْوَلِيدِ، وَالرُّومُ مُلْصِقُو ظُهُورِهِمْ بِحَائِطِ الْمَدِينَةِ، فَحَمَلَ رَجُلٌ عَلَى الْعَدُوِّ، فَقَالَ النَّاسُ: مَهْ، مَهْ، لَا إِلَهَ إِلَّا اللَّهُ، يُلْقِي بِيَدَيْهِ إِلَى التَّهْلُكَةِ. فَقَالَ أَبُو أَيُّوبَ: إِنَّمَا نَزَلَتْ هَذِهِ الْآيَةُ فِينَا مَعْشَرَ الْأَنْصَارِ: لَمَّا نَصَرَ اللَّهُ نَبِيَّهُ وَأَظْهَرَ الْإِسْلَامَ قُلْنَا: هَلُمَّ نُقِيمُ فِي أَمْوَالِنَا وَنُصْلِحُهَا، فَأَنْزَلَ اللَّهُ تَعَالَى: {وَأَنْفِقُوا فِي سَبِيلِ اللَّهِ وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ} [البقرة: ١٩٥]. فَالْإِلْقَاءُ بِالْأَيْدِي إِلَى التَّهْلُكَةِ: أَنْ نُقِيمَ فِي أَمْوَالِنَا وَنُصْلِحَهَا وَنَدَعَ الْجِهَادَ. قَالَ أَبُو عِمْرَانَ: فَلَمْ يَزَلْ أَبُو أَيُّوبَ يُجَاهِدُ فِي سَبِيلِ اللَّهِ حَتَّى دُفِنَ بِالْقُسْطَنْطِينِيَّةِ. (د,ت)', 'അസ്ലം അബൂഇംറാൻ(റ): ഖുസ്തുൻതീനിയ എന്ന പട്ടണം ലക്ഷ്യമാക്കി ഞങ്ങൾ മദീനയിൽ നിന്നും യുദ്ധത്തിന് പുറപ്പെട്ടു. സംഘത്തിലെ നേതാവ് അബ്ദുർറഹ്മാനുബ്നു ഖാലിദുബ്നുവലീദ്(റ) ആയിരുന്നു. റോമക്കാർ പട്ടണത്തിന്റെ അതിർത്തിയോട് ചേർന്ന് നിൽക്കുകയായിരുന്നു. അങ്ങനെയിരിക്കെ ഒരാൾ ശത്രുക്കളെ അക്രമിച്ചു. അപ്പോൾ ജനങ്ങൾ പറഞ്ഞു: അത് ചെയ്യരുത്, അവൻ സ്വന്തത്തെ നാശത്തിലേക്ക് തള്ളിവിടുകയാണ്, അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല. അപ്പോൾ അബൂഅയ്യൂബ്(റ) പറഞ്ഞു: നിങ്ങൾ ഈ പറഞ്ഞ സൂക്തം ഞങ്ങൾ അൻസാറുകളുടെ കാര്യത്തിലാണ് അവതരിച്ചത്. അല്ലാഹു തന്റെ നബി(സ)യെ സഹായിക്കുകയും ഇസ്ലാമിന് വിജയം നൽകുകയും ചെയതപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: ഇനി നമുക്ക് പോയി നമ്മുടെ മുതൽ നോക്കി നടത്തുകയും പരിപാലിക്കുകയും ചെയ്യാം. അപ്പോൾ അല്ലാഹു ''നിങ്ങൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുക, സ്വന്തത്തെ നിങ്ങൾ നാശത്തിലാക്കരുത്'' (അൽബഖറ: 195) എന്ന സൂക്തമിറക്കി. സ്വന്തത്തെ നാശത്തിലേക്കിടുക എന്നാൽ നാം നമ്മുടെ മുതലിനെ പരിപാലിച്ച് കൂടലും ജിഹാദിനെ ഒഴിവാക്കലുമാണ്. അബൂഇംറാൻ(റ) പറഞ്ഞു: ശേഷം അബൂഅയ്യൂബ്(റ) അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടിക്കൊണ്ടേയിരുന്നു. അങ്ങനെ ഖുസ്തുൻതീനിയ്യയിലാണ് അവർ മറവ് ചെയ്യപ്പെട്ടത്. (ദ,തു)', 'أَسْلَمَ أَبِي عِمْرَانَ قَالَ', 'അസ്ലം അബൂഇംറാൻ(റ)', '3. തിന്മയാണെന്ന് സംശയിക്കപ്പെടുന്ന കാര്യത്തിലുള്ള ദേഷ്യമാണ് അല്ലാഹു ഇഷ്ടപ്പെടുന്നത്. തിന്മയാണെന്ന് സംശയിക്കപ്പെടാത്ത കാര്യത്തിലുള്ള (നന്മയിലുള്ള) ദേഷ്യമാണ് അവൻ വെറുക്കുന്നത്.', null, array['د','ت']::text[], array['ദ','തു']::text[], 'البقرة: ١٩٥', null, 979, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 390, 'عَنْ قَيْسِ بْنِ عُبَادٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ أَبَا ذَرٍّ – رَضِيَ اللَّهُ عَنْهُ – يُقْسِمُ: لَنَزَلَتْ هَذِهِ الْآيَةُ فِي هَؤُلَاءِ الرَّهْطِ السِّتَّةِ يَوْمَ بَدْرٍ: {هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ} [الحج: ١٩] إِلَى قَوْلِهِ: {إِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ} فِي حَمْزَةَ بْنِ عَبْدِ الْمُطَّلِبِ، وَعَلِيِّ بْنِ أَبِي طَالِبٍ، وَعُبَيْدَةَ بْنِ الْحَارِثِ. وَعُتْبَةَ بْنِ رَبِيعَةَ، وَشَيْبَةَ بْنِ رَبِيعَةَ، وَالْوَلِيدِ بْنِ عُتْبَةَ، اخْتَصَمُوا فِي الْحُجَجِ يَوْمَ بَدْرٍ. (ق,جه)', 'ഖൈസുബ്നു ഉബാദ്(റ): അബൂദർറ്(റ) ഇപ്രകാരം സത്യം ചെയ്ത് പറയുന്നത് ഞാൻ കേട്ടു: ''തങ്ങളുടെ രക്ഷിതാവിന്റെ കാര്യത്തിൽ തർക്കിച്ച രണ്ട് വിഭാഗമാണിത്'' (ഹജ്ജ്: 19) എന്നത് മുതൽ ''തീർച്ചയായും അല്ലാഹു താൻ ഉദ്ദേശിച്ചത് പ്രവർത്തിക്കുകതന്നെ ചെയ്യും'' എന്നത് വരെയുള്ള സൂക്തം ബദർ യുദ്ധ ദിവസം ഹംസത്തുബ്നു അബ്ദിൽ മുത്വലിബ്(റ), അലിയ്യുബ്നു അബീത്വാലിബ്(റ), ഉബൈദതുബ്നുൽ ഹാരിസ്(റ), ഉത്ബതുബ്നു റബീഅ, ശൈബതുബ്നു റബീഅ, വലീദുബ്നു ഉത്ബ എന്നീ ആറുപേരുടെ കാര്യത്തിലാണ് ഇറങ്ങിയത്. അവർ ബദർ യുദ്ധദിവസം പല വാദങ്ങളിൽ തർക്കിച്ചു. (ബു,മു,ജ)', 'قَيْسِ بْنِ عُبَادٍ', 'ഖൈസുബ്നു ഉബാദ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], 'الحج: ١٩', null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 391, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَارَزْتُ رَجُلًا فَقَتَلْتُهُ فَنَفَّلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَلَبَهُ. (جه)', 'സലമതുബ്നുൽ അക്വഅ്(റ): ഞാൻ ഒരുത്തനോട് ദ്വന്ദ്വയുദ്ധത്തിലേർപ്പെടുകയും അവനെ വധിക്കുകയും ചെയ്തു. അപ്പോൾ അവന്റെ ശരീരത്തിലുണ്ടായിരുന്ന മുതലും ആയുധവും (സലബ്) റസൂൽ(സ) എനിക്ക് നൽകി. (ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 392, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَّلَهُ سَلَبَ قَتِيلٍ، قَتَلَهُ يَوْمَ حُنَيْنٍ. (ق,د,ت,جه)', 'അബൂഖതാദ(റ): ഹുനൈൻ യുദ്ധ ദിവസം അദ്ദേഹം വധിച്ച ഒരുത്തന്റെ മുതലും ആയുധവും റസൂൽ(സ) അദ്ദേഹത്തിന് നൽകി. (ബു,മു,ദ,തു,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 393, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ فَلَهُ السَّلَبُ". فِيهِ رَاوٍ مُخْتَلَفٌ فِيهِ. (جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വധിച്ചവനാണ് വധിക്കപ്പെട്ടവന്റെ ആയുധവും മുതലും." ഈ ഹദീസിലെ ഒരു നിവേദകനെക്കുറിച്ച് അഭിപ്രായവ്യത്യാസമുണ്ട്. (ജ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 394, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: تَقَدَّمَ – يَعْنِي عُتْبَةَ بْنَ رَبِيعَةَ – وَتَبِعَهُ ابْنُهُ وَأَخُوهُ، فَنَادَى: مَنْ يُبَارِزُ؟ فَانْتَدَبَ لَهُ شَبَابٌ مِنَ الْأَنْصَارِ، فَقَالَ: مَنْ أَنْتُمْ؟ فَأَخْبَرُوهُ، فَقَالَ: لَا حَاجَةَ لَنَا فِيكُمْ، إِنَّمَا أَرَدْنَا بَنِي عَمِّنَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُمْ يَا حَمْزَةُ، قُمْ يَا عَلِيُّ، قُمْ يَا عُبَيْدَةَ بْنَ الْحَارِثِ". فَأَقْبَلَ حَمْزَةُ إِلَى عُتْبَةَ، وَأَقْبَلْتُ إِلَى شَيْبَةَ، وَاخْتَلَفَ بَيْنَ عُبَيْدَةَ وَالْوَلِيدِ ضَرْبَتَانِ، فَأَثْخَنَ كُلُّ وَاحِدٍ مِنْهُمَا صَاحِبَهُ، ثُمَّ مِلْنَا عَلَى الْوَلِيدِ، فَقَتَلْنَاهُ، وَاحْتَمَلْنَا عُبَيْدَةَ. (د)', 'അലി(റ): ഉത്ബതുബ്നു റബീഅ മുന്നിട്ടുവന്നു. അവന്റെ മകനും സഹോദരനും അവനെ പിന്തുടരുകയും ചെയ്തു. എന്നിട്ടവൻ വിളിച്ചുപറഞ്ഞു: ആരാണ് ദ്വന്ദ്വയുദ്ധത്തിനുള്ളത്? അപ്പോൾ അൻസാരികളായ യുവാക്കൾ അവർക്കു നേരെ ചെന്നു. ഉത്ബ ചോദിച്ചു: നിങ്ങൾ ആരാണ്? അവർ വിവരം പറഞ്ഞുകൊടുത്തു. ഉത്ബ പറഞ്ഞു: ഞങ്ങൾക്ക് നിങ്ങളെ ആവശ്യമില്ല. ഞങ്ങളുടെ കുടുംബക്കാരെയാണ് ഞങ്ങൾക്ക് വേണ്ടത്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഹംസ, താങ്കൾ ചെല്ലുക! അലീ, താങ്കൾ ചെല്ലുക! ഉബൈദതുബ്നുൽ ഹാരിസ്, താങ്കളും ചെല്ലുക!" അങ്ങനെ ഹംസ(റ) ഉത്ബയുടെ അടുക്കലേക്കും ഞാൻ ശൈബതിന്റെയടുത്തേക്കും ചെന്നു. ഉബൈദ(റ)വും വലീദും പരസ്പരം രണ്ട് വെട്ടുകൾ വെട്ടുകയും പരസ്പരം ശക്തമായി മുറിവേൽപിക്കുകയും ചെയ്തു. ശേഷം ഞങ്ങൾ വലീദിനെ നേരിടുകയും അവനെ വധിക്കുകയും ഉബൈദ(റ)വിനെ ചുമന്ന് കൊണ്ടുപോവുകയും ചെയ്തു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 980, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 395, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَزَلَتْ {إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ} [الأنفال: ٦٥] فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ حِينَ فَرَضَ اللَّهُ عَلَيْهِمْ أَنْ لَا يَفِرَّ وَاحِدٌ مِنْ عَشَرَةٍ، ثُمَّ إِنَّهُ جَاءَ تَخْفِيفٌ، فَقَالَ: {الْآنَ خَفَّفَ اللَّهُ عَنْكُمْ} إِلَى قَوْلِهِ: {يَغْلِبُوا مِائَتَيْنِ} [الأنفال: ٦٦] قَالَ: فَلَمَّا خَفَّفَ اللَّهُ تَعَالَى عَنْهُمْ مِنَ الْعِدَّةِ نَقَصَ مِنَ الصَّبْرِ بِقَدْرِ مَا خَفَّفَ عَنْهُمْ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങളിൽ ക്ഷമാശീലരായ ഇരുപത് പേരുണ്ടെങ്കിൽ ഇരുന്നൂറ് പേരോട് അവർ വിജയിക്കും'' (അൻഫാൽ: 65) എന്ന സൂക്തമിറങ്ങി. പത്ത് പേരോട് യുദ്ധം ചെയ്യുന്ന ഒരാൾക്ക് പിന്തിരിയൽ പാടില്ല എന്ന ഈ നിയമം മുസ്ലിംകൾക്ക് പ്രയാസകരമായി തോന്നി. ശേഷം അൽപം ലോലമാക്കി അല്ലാഹുവിന്റെ നിയമം വന്നു. അല്ലാഹു പറഞ്ഞു: ''ഇപ്പോൾ അല്ലാഹു നിങ്ങൾക്ക് ഇളവ് അനുവദിച്ചിരിക്കുന്നു'' എന്നത് മുതൽ ''നിങ്ങൾ ഇരുനൂറ് പേരെ നേരിടും'' (അൻഫാൽ: 66) നിവേദകൻ പറയുന്നു: എണ്ണത്തിൽ അല്ലാഹു അവർക്ക് ഇളവ് കൊടുത്തപ്പോൾ ആ ഇളവിനനുസരിച്ച് അവരുടെ ക്ഷമ കുറഞ്ഞു. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'الأنفال: ٦٦', null, 981, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 396, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ، فَحَاصَ النَّاسُ حَيْصَةً، فَقَدِمْنَا الْمَدِينَةَ فَاخْتَبَيْنَا بِهَا وَقُلْنَا هَلَكْنَا، ثُمَّ أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، نَحْنُ الْفَرَّارُونَ. قَالَ: "بَلْ أَنْتُمُ الْعَكَّارُونَ، وَأَنَا فِئَتُكُمْ". قَالَ تِرْمِذِي هَذَا حَدِيثٌ حَسَنٌ. (د,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരു സൈന്യത്തോടൊപ്പം ഞങ്ങളെ അയച്ചു. അങ്ങനെ ജനങ്ങൾ പിന്തിരിയുകയും ഞങ്ങൾ മദീനയിൽ വന്ന് അവിടെ ഒളിഞ്ഞ് താമസിക്കുകയും ചെയ്തു. ഞങ്ങൾ പരസ്പരം പറഞ്ഞു: നാം നശിച്ചിരിക്കുന്നു. ശേഷം ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: റസൂലേ, ഞങ്ങൾ പിന്തിരിഞ്ഞവരാണ്. റസൂൽ(റ) പറഞ്ഞു: "അല്ല, നിങ്ങൾ യുദ്ധത്തിലേക്ക് തിരിച്ച് പോകുന്നവരാണ്, നിങ്ങൾക്ക് ശക്തി പകരാൻ ഞാനുണ്ട്." തിർമിദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 981, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 397, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لَنَا رَجُلٌ: أَفَرَرْتُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَبَا عُمَارَةَ؟ قَالَ: لَا وَاللَّهِ، مَا وَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنْ وَلَّى سَرَعَانُ النَّاسِ، تَلَقَّتْهُمْ هَوَازِنُ بِالنَّبْلِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى بَغْلَتِهِ، وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ آخِذٌ بِلِجَامِهَا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَنَا النَّبِيُّ لَا كَذِبْ، أَنَا ابْنُ عَبْدِ الْمُطَّلِبْ". (ق,ت)', 'ബറാഉബ്നു ആസിബ്(റ): ഞങ്ങളോട് ഒരാൾ ചോദിച്ചു: അല്ലയോ അബൂഉമാറ! നിങ്ങൾ റസൂൽ(സ)യുടെ അടുത്ത് നിന്ന് പിന്തിരിഞ്ഞുവോ? അവർ പറഞ്ഞു: ഇല്ല; അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ) പിന്തിരിഞ്ഞിട്ടില്ല. ജനങ്ങളിൽ വേഗത്തിൽ ഓടാൻ കഴിയുന്നവരാണ് പിന്തിരിഞ്ഞത്. ഹവാസിൻ ഗോത്രക്കാർ അവരെ അമ്പെയ്തു. റസൂൽ(സ) തന്റെ കോവർക്കഴുതയുടെ പുറത്തിരിക്കുകയായിരുന്നു. അബൂസുഫ്യാനുബ്നു ഹാരിസിബ്നി അബ്ദിൽമുത്തലിബ്(റ) അതിന്റെ കടിഞ്ഞാൺ പിടിച്ച് നിൽക്കുകയായിരുന്നു. റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞ് കൊണ്ടിരുന്നു: "ഞാൻ നബിയാണ്, കളവല്ല. ഞാൻ അബ്ദുൽമുത്വലിബിന്റെ മകനാണ്." (ബു,മു,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 981, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 398, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَقَدْ رَأَيْتُنَا يَوْمَ حُنَيْنٍ، وَإِنَّ الْفِئَتَيْنِ لَمُوَلِّيَتَانِ، وَمَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِائَةُ رَجُلٍ. قَالَ تِرْمِذِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): ഹുനൈൻ യുദ്ധദിവസം ഇരു കൂട്ടരും പിന്തിരിയുന്ന അവസ്ഥയിൽ ഞങ്ങളെ ഞാൻ കണ്ടു. അപ്പോൾ റസൂൽ(സ)യുടെ കൂടെ നൂറ് ആളുകൾ പോലും ഇല്ലായിരുന്നു. തിർമിദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 982, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 399, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ فَزَعٌ بِالْمَدِينَةِ، فَاسْتَعَارَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَسًا لَنَا يُقَالُ لَهُ مَنْدُوبٌ، فَقَالَ: "مَا رَأَيْنَا مِنْ فَزَعٍ، وَإِنْ وَجَدْنَاهُ لَبَحْرًا". (ق,د,ت)', 'അനസുബ്നു മാലിക്(റ): മദീനയിൽ ഭീതി പരന്നു. അപ്പോൾ റസൂൽ(സ) മൻദൂബ് എന്ന് പേരുള്ള ഞങ്ങളുടെ ഒരു കുതിരയെ വായ്പ വാങ്ങി (അതിനു മേൽ സഞ്ചരിച്ചു). എന്നിട്ട് പറഞ്ഞു: "പേടിപ്പെടുത്തുന്ന ഒന്നും നാം കണ്ടില്ല, വളരെ ഉന്മേശത്തോടെ നടക്കുന്നതായി ഞാൻ ഈ കുതിരയെ കണ്ടു." (ബു,മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 982, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 400, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَجْرَإِ النَّاسِ، وَأَجْوَدِ النَّاسِ، وَأَشْجَعِ النَّاسِ. قَالَ: وَقَدْ فَزِعَ أَهْلُ الْمَدِينَةِ لَيْلَةً، سَمِعُوا صَوْتًا، قَالَ: فَتَلَقَّاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى فَرَسٍ لِأَبِي طَلْحَةَ عُرْيٍ، وَهُوَ مُتَقَلِّدٌ سَيْفَهُ، فَقَالَ: "لَمْ تُرَاعُوا لَمْ تُرَاعُوا". فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَجَدْتُهُ بَحْرًا" يَعْنِي الْفَرَسَ. (ق,ت)', 'അനസ്(റ): നബി(സ) ജനങ്ങളിൽ ഏറ്റവും ധൈര്യശാലിയും ദാനശീലനും പ്രതാപിയുമായിരുന്നു. ഒരു രാത്രി മദീനാ നിവാസികൾ ഒരു ശബ്ദം കേൾക്കുകയും അവർ ഭയവിഹ്വലരാവുകയും ചെയ്തു. അപ്പോൾ അബൂത്വൽഹ(റ)വിന്റെ ജീനിയില്ലാത്ത കുതിരപ്പുറത്ത് കയറി, വാളേന്തിയവനായി നബി(സ) ജനങ്ങളുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: "നിങ്ങൾക്ക് പേടിക്കേണ്ടതായി ഒന്നുമില്ല." ശേഷം പറഞ്ഞു: "ഇതിനെ വളരെ ഉന്മേശത്തോടെ നടക്കുന്നതായിട്ട് ഞാൻ കണ്ടു." കുതിരയെയാണ് അവിടന്ന് ഉദ്ദേശിക്കുന്നത്. (ബു,മു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 982, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 401, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا". (ق,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "യുദ്ധത്തിന് വിളിക്കപ്പെട്ടാൽ നിങ്ങൾ ഓടിച്ചെല്ലുക." (ബു,മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 982, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 402, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ جَيْشَيْنِ، وَأَمَّرَ عَلَى أَحَدِهِمَا عَلِيَّ بْنَ أَبِي طَالِبٍ وَعَلَى الْآخَرِ خَالِدَ بْنَ الْوَلِيدِ، فَقَالَ: "إِذَا كَانَ الْقِتَالُ فَعَلِيٌّ". قَالَ: فَافْتَتَحَ عَلِيٌّ حِصْنًا فَأَخَذَ مِنْهُ جَارِيَةً، فَكَتَبَ مَعِي خَالِدُ بْنُ الْوَلِيدِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشِي بِهِ، فَقَدِمْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ الْكِتَابَ، فَتَغَيَّرَ لَوْنُهُ، ثُمَّ قَالَ: "مَا تَرَى فِي رَجُلٍ يُحِبُّ اللَّهَ وَرَسُولَهُ، وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ". قَالَ: قُلْتُ: أَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ وَغَضَبِ رَسُولِهِ، وَإِنَّمَا أَنَا رَسُولٌ. فَسَكَتَ. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'ബർറാഅ്(റ): നബി(സ) രണ്ട് സൈന്യങ്ങളെ പറഞ്ഞയച്ചു. ഒരു സൈന്യത്തിന്റെ നേതൃത്വം അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിനും മറ്റൊന്നിന്റെ നേതൃത്വം ഖാലിദുബ്നു വലീദ്(റ)വിനും നൽകി. എന്നിട്ട് പറഞ്ഞു: "യുദ്ധം തുടങ്ങിയാൽ നേതൃത്വം അലി(റ)വിനായിരിക്കും." നിവേദകൻ പറഞ്ഞു: അങ്ങനെ അലി(റ) ഒരു കോട്ട കീഴടക്കുകയും അവിടെ നിന്ന് ബന്ധികളിൽ പെട്ട ഒരു അടിമസ്ത്രയെ കൈവശപ്പെടുത്തുകയും ചെയ്തു. അപ്പോൾ ഖാലിദുബ്നു വലീദ്(റ) അലി(റ)വിനെക്കുറിച്ച് പരാതിപ്പെട്ട് നബി(സ)യിലേക്ക് എന്റെയടുത്ത് ഒരു കത്ത് അയച്ചു. ഞാൻ നബി(സ)യുടെ അടുത്ത് വരികയും അവിടന്ന് കത്ത് വായിക്കുകയും ചെയ്തു. ഉടനെ അവിടത്തെ മുഖം വിവർണ്ണമായി. അവിടന്ന് ചോദിച്ചു: "അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും സ്നേഹിക്കുന്ന അല്ലാഹുവും അവന്റെ റസൂലും സ്നേഹിക്കുന്ന ഒരാളെ (അലി) കുറിച്ച് നിന്റെ അഭിപ്രായമെന്താണ്?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും ദേഷ്യത്തിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. ഞാൻ ഒരു ദൂതൻ മാത്രമാണ് (അത് എന്റെ അഭിപ്രായമല്ല) അപ്പോൾ തിരുമേനി(സ) മൗനം പാലിച്ചു. തിർമിദി(റ) പറഞ്ഞു: ഈ ഹദീസ് ഹസനാണ്. (തു)', 'الْبَرَاءِ', 'ബർറാഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 983, 983, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 403, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رُمِيَ يَوْمَ الْأَحْزَابِ سَعْدُ بْنُ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ، فَقَطَعُوا أَكْحَلَهُ أَوْ أَبْجَلَهُ، فَحَسَمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّارِ، فَانْتَفَخَتْ يَدُهُ، فَتَرَكَهُ فَنَزَفَهُ الدَّمُ، فَحَسَمَهُ أُخْرَى فَانْتَفَخَتْ يَدُهُ، فَلَمَّا رَأَى ذَلِكَ قَالَ: اللَّهُمَّ لَا تُخْرِجْ نَفْسِي حَتَّى تُقِرَّ عَيْنِي مِنْ بَنِي قُرَيْظَةَ. فَاسْتَمْسَكَ عِرْقُهُ، فَمَا قَطَرَ قَطْرَةً حَتَّى نَزَلُوا عَلَى حُكْمِ سَعْدِ بْنِ مُعَاذٍ، فَأُرْسِلَ إِلَيْهِ فَحَكَمَ: أَنْ يُقْتَلَ رِجَالُهُمْ وَيُسْتَحْيَا نِسَاؤُهُمْ، يَسْتَعِينُ بِهِنَّ الْمُسْلِمُونَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَصَبْتَ حُكْمَ اللَّهِ فِيهِمْ". وَكَانُوا أَرْبَعَ مِائَةٍ، فَلَمَّا فَرَغَ مِنْ قَتْلِهِمُ انْفَتَقَ عِرْقُهُ فَمَاتَ. (ت,ن)', 'ജാബിർ(റ): അഹ്സാബ് യുദ്ധ ദിവസം സഅ്ദുബ്നു മുആദ്(റ)വിന് അമ്പേറ്റു. അപ്പോൾ അവർ അദ്ദേഹത്തിന്റെ തണ്ടൻകയ്യിന്റെ നടുവിലുള്ളതും ഉള്ളിലുള്ളതുമായ ഞരമ്പുകൾ മുറിക്കുകയും റസൂൽ(സ) അദ്ദേഹത്തിന്റെ കയ്യറ്റം (രക്തവാർച്ച നിലക്കാൻ വേണ്ടി) തീകൊണ്ട് കരിക്കുകയും ചെയ്തു. അങ്ങനെ സഅ്ദ്(റ)വിന്റെ കൈ വീർത്തു വന്നു. നബി(സ) ആ ചികിത്സ നിർത്തുകയും അവരുടെ കയ്യിൽ നിന്ന് വീണ്ടും രക്തം ഒഴുകുകയും ചെയ്തു. അങ്ങനെ രണ്ടാം പ്രാവശ്യവും കരിക്കുകയും സഅ്ദ്(റ)വിന്റെ കൈ വീർത്ത് വരികയും ചെയ്തു. അത് കണ്ടപ്പോൾ സഅ്ദ്(റ) പറഞ്ഞു: അല്ലാഹുവേ, ബനൂഖുറൈള ഗോത്രക്കാരുടെ കാര്യത്തിൽ എനിക്ക് കൺകുളിർമ്മ ഉണ്ടാകുംവരെ നീ എന്നെ മരിപ്പിക്കരുതേ. അങ്ങനെ അദ്ദേഹത്തിന്റെ ഞരമ്പുകളിൽ നിന്നുള്ള രക്തവാർച്ച നിലക്കുകയും ചയ്തു. ശേഷം ബനൂഖുറൈളക്കാർ സഅ്ദുബ്നു മുആദ്(റ)വിന്റെ വിധിപ്രകാരം ഇറങ്ങും വരെ ഒരു തുള്ളി രക്തം പോലും ഉറ്റിയില്ല. അങ്ങനെ സഅ്ദ്(റ) അവരിലേക്ക് ഇപ്രകാരം വിധി പറഞ്ഞയച്ചു: അവരിലെ പുരുഷന്മാരെ വധിക്കുകയും സ്ത്രീകളെ മുസ്ലിംകൾക്ക് സഹായകരമാകും വിധം വെറുതെ വിടുകയും ചെയ്യണം. ഇത് കേട്ട് റസൂൽ(സ) പറഞ്ഞു: "നീ അവരിൽ അല്ലാഹുവിന്റെ വിധിയെ നടപ്പാക്കിയിരിക്കുന്നു." ബനൂഖുറൈളക്കാർ നാനൂറ് പേരായിരുന്നു. അവരെ വധിച്ചുകഴിഞ്ഞപ്പോൾ സഅ്ദ്(റ)വിന്റെ ഞരമ്പുകൾ വീർത്ത് വരികയും അദ്ദേഹം വഫാത്താകുകയും ചെയ്തു. (തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 983, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 404, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ وَاسْتَحْيُوا شَرْخَهُمْ". وَالشَّرْخُ: الْغِلْمَانُ الَّذِينَ لَمْ يُنْبِتُوا. (د,ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ബഹുദൈവാരാധകരിലെ പ്രായമെത്തിയ പുരുഷന്മാരെ നിങ്ങൾ വധിച്ചുകളയുകയും പ്രായപൂർത്തിയാകാത്തവരെ വെറുതെ വിടുകയും ചെയ്യുക." പ്രായപൂർത്തിയാകാത്തവർ എന്നാൽ ഗുഹ്യരോമം മുളക്കാത്ത കുട്ടികളാണ്. (ദ,തു)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 405, 'عَنْ عَطِيَّةَ الْقُرَظِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: عُرِضْنَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ قُرَيْظَةَ: فَكَانَ مَنْ أَنْبَتَ قُتِلَ، وَمَنْ لَمْ يُنْبِتْ خُلِّيَ سَبِيلُهُ، فَكُنْتُ مِمَّنْ لَمْ يُنْبِتْ، فَخُلِّيَ سَبِيلِي. (د,ت,ن,جه)', 'അതിയ്യതുൽ ഖുറളി(റ): ഖുറൈളക്കാരോടുള്ള യുദ്ധദിവസം ഞങ്ങളെയെല്ലാം നബി(സ)ക്ക് പ്രദർശിപിക്കപ്പെട്ടു. ഗുഹ്യരോമം മുളച്ചവർ കൊല്ലപ്പെടുകയും മുളച്ചിട്ടില്ലാത്തവരെ വെറുതെ വിടുകയുമായിരുന്നു ചെയ്തിരുന്നത്. ഞാൻ ഗുഹ്യരോമം മുളച്ചിട്ടില്ലാത്തവനായിരുന്നു, അങ്ങനെ എന്നെ വെറുതെ വിട്ടു. (ദ,തു,ന,ജ)', 'عَطِيَّةَ الْقُرَظِيِّ', 'അതിയ്യതുൽ ഖുറളി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 406, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَتَقَدَّمَ سَرْعَانُ النَّاسِ، فَتَعَجَّلُوا مِنَ الْغَنَائِمِ فَاطَّبَخُوا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أُخْرَى النَّاسِ، فَمَرَّ بِالْقُدُورِ فَأَمَرَ بِهَا فَأُكْفِئَتْ، ثُمَّ قَسَمَ بَيْنَهُمْ، فَعَدَلَ بَعِيرًا بِعَشْرِ شِيَاهٍ. (ق,د,ت,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ഒരു യാത്രയിലായിരുന്നു. കൂട്ടത്തിൽ വേഗത്തിൽ സഞ്ചരിക്കുന്നവർ മുന്നിൽ പോവുകയും ഗനീമത്തെടുത്ത് അവർ പാചകം ചെയ്യുകയും ചെയ്തു. റസൂൽ(സ) പിന്നിലുള്ളവരോടൊപ്പമായിരുന്നു. അങ്ങനെ റസൂൽ(സ) ആ കലങ്ങളുടെ സമീപത്തുകൂടെ സഞ്ചരിക്കുകയും കലങ്ങൾ കമിഴ്ത്താൻ കൽപിക്കുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) അവർക്കിടയിൽ വീതിച്ചു. ഒരു ഒട്ടകത്തെ പത്ത് ആടുകൾക്കാണ് റസൂൽ(സ) സമമാക്കിയത്. (ബു,മു,ദ,തു,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 407, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ انْتَهَبَ فَلَيْسَ مِنَّا". (ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കവർച്ച നടത്തുന്നവൻ നമ്മിൽ പെട്ടവനല്ല." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 408, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنَّهُ أَتَى يَوْمَ الْيَمَامَةِ إِلَى ثَابِتِ بْنِ قَيْسٍ وَقَدْ حَسَرَ عَنْ فَخِذَيْهِ، وَهُوَ يَتَحَنَّطُ، فَقَالَ: يَا عَمِّ مَا يَحْبِسُكَ أَنْ لَا تَجِيءَ؟ فَقَالَ: الْآنَ يَا ابْنَ أَخِي، وَجَعَلَ يَتَحَنَّطُ يَعْنِي مِنَ الْحَنُوطِ، ثُمَّ جَاءَ فَجَلَسَ فَذَكَرَ فِي الْحَدِيثِ انْكِشَافًا مِنَ النَّاسِ فَقَالَ: هَكَذَا عَنْ وُجُوهِنَا حَتَّى نُضَارِبَ الْقَوْمَ، مَا هَكَذَا كُنَّا نَفْعَلُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِئْسَ مَا عَوَّدْتُمْ أَقْرَانَكُمْ. (خ)', 'അനസ്(റ): യമാമ യുദ്ധദിവസം അദ്ദേഹം സാബിതുബ്നു ഖൈസ്(റ)വിന്റെ അടുത്ത് ചെന്നു. സാബിത്(റ) തന്റെ തുടകളിലെ വസ്ത്രം പൊക്കി സുഗന്ധദ്രവ്യം പൂശിക്കൊണ്ടിരിക്കുകയായിരുന്നു. അനസ്(റ) ചോദിച്ചു: എന്റെ പിതൃവ്യാ, എന്ത് കൊണ്ടാണ് നിങ്ങൾ യുദ്ധരംഗത്തുനിന്ന് പിന്തിനിൽക്കുന്നത്. സാബിത്(റ) പറഞ്ഞു: സഹോദരപുത്രാ, ഇതാ ഞാൻ പറഞ്ഞുതരാം. പിന്നെയും അദ്ദേഹം സുഗന്ധദ്രവ്യം പൂശിക്കൊണ്ടിരുന്നു. ശേഷം അദ്ദേഹം വന്ന് ഇരുന്നു. സംസാരിച്ച കൂട്ടത്തിൽ ജനങ്ങൾ യുദ്ധക്കളം വിട്ടോടിയ വാർത്ത വിവരിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഞങ്ങൾ ശത്രുക്കളുമായി ഇങ്ങനെ നേരിട്ടാണ് യുദ്ധം ചെയ്തിരുന്നത്. അല്ലാതെ ഇന്നു കാണുന്ന ഈ രൂപത്തിലായിരുന്നില്ല റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ സമരം നടത്തിയിരുന്നത്. നിങ്ങൾ നിങ്ങളുടെ തലമുറക്കാർക്ക് പരിശീലിപ്പിച്ച സമ്പ്രദായം വളരെ മോശമായിപ്പോയി. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 984, 985, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 409, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَأْتِينِي بِخَبَرِ الْقَوْمِ". يَوْمَ الْأَحْزَابِ، قَالَ الزُّبَيْرُ: أَنَا، ثُمَّ قَالَ: "مَنْ يَأْتِينِي بِخَبَرِ الْقَوْمِ". قَالَ الزُّبَيْرُ: أَنَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِكُلِّ نَبِيٍّ حَوَارِيًّا وَحَوَارِيَّ الزُّبَيْرُ". (خ)', 'ജാബിർ(റ): അഹ്സാബ് യുദ്ധദിവസം റസൂൽ(സ) ചോദിച്ചു: "ശത്രുക്കളുടെ വാർത്തയറിഞ്ഞുവരാൻ ആരുണ്ട്?" സുബൈർ(റ) പറഞ്ഞു: ഞാൻ. റസൂൽ(സ) വീണ്ടും ചോദിച്ചു: "ശത്രുക്കളുടെ വാർത്തയറിഞ്ഞുവരാൻ ആരുണ്ട്?" സുബൈർ(റ) പറഞ്ഞു: ഞാൻ. റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ നബിമാർക്കും ചില ഹവാരികൾ (ത്യാഗ പ്രതിജ്ഞ ചെയ്തവർ) ഉണ്ട്. എന്റെ ഹവാരി സുബൈറാണ്." (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 985, 985, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 410, 'عَنْ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْتُ مِنَ الْمَدِينَةِ ذَاهِبًا نَحْوَ الْغَابَةِ، حَتَّى إِذَا كُنْتُ بِثَنِيَّةِ الْغَابَةِ لَقِيَنِي غُلَامٌ لِعَبْدِالرَّحْمَنِ بْنِ عَوْفٍ قُلْتُ: وَيْحَكَ مَا بِكَ؟ قَالَ: أُخِذَتْ لِقَاحُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: مَنْ أَخَذَهَا؟ قَالَ: غَطَفَانُ وَفَزَارَةُ، فَصَرَخْتُ ثَلَاثَ صَرَخَاتٍ أَسْمَعْتُ مَا بَيْنَ لابَتَيْهَا: يَا صَبَاحَاهْ يَا صَبَاحَاهْ، ثُمَّ انْدَفَعْتُ حَتَّى أَلْقَاهُمْ، وَقَدْ أَخَذُوهَا فَجَعَلْتُ أَرْمِيهِمْ وَأَقُولُ: أَنَا ابْنُ الْأَكْوَعِ وَالْيَوْمُ يَوْمُ الرُّضَّعْ، فَاسْتَنْقَذْتُهَا مِنْهُمْ قَبْلَ أَنْ يَشْرَبُوا، فَأَقْبَلْتُ بِهَا أَسُوقُهَا فَلَقِيَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ الْقَوْمَ عِطَاشٌ وَإِنِّي أَعْجَلْتُهُمْ أَنْ يَشْرَبُوا سِقْيَهُمْ فَابْعَثْ فِي إِثْرِهِمْ، فَقَالَ: "يَا ابْنَ الْأَكْوَعِ مَلَكْتَ فَأَسْجِحْ، إِنَّ الْقَوْمَ يُقْرَوْنَ فِي قَوْمِهِمْ". (خ)', 'സലമ(റ): ഒരിക്കൽ ഞാൻ മദീനയിൽ നിന്ന് ഗാബയുടെ ഭാഗത്തേക്ക് പുറപ്പെട്ടു. ഗാബ മലയിടുക്കിലെത്തിയപ്പോൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിന്റെ ഭൃത്യൻ എന്നെ കണ്ടുമുട്ടി. ഞാൻ ചോദിച്ചു: നിനക്കെന്തുപറ്റി? ഭൃത്യൻ പറഞ്ഞു: നബി(സ)യുടെ പാൽ കറക്കുന്ന ഒട്ടകങ്ങളെ തട്ടിക്കൊണ്ടുപോയിരിക്കുന്നു. ഞാൻ ചോദിച്ചു: ആരാണവയെ തട്ടിക്കൊണ്ടുപോയത്? ഭൃത്യൻ പറഞ്ഞു: ഖത്ഫാൻ, ഫസാറ എന്നീ ഗോത്രക്കാർ. അന്നേരം ഞാൻ മൂന്ന് പ്രാവശ്യം ''പ്രഭാതത്തിലെ മഹാ വിപത്ത്, പ്രഭാതത്തിലെ മഹാ വിപത്ത്'' എന്ന് അത്യുച്ചത്തിൽ വിളിച്ചു പറഞ്ഞു. ദേശവാസികളെയെല്ലാം ഞാനത് കേൾപിച്ചു. ശേഷം ആ ഒട്ടകങ്ങളെ തട്ടിയെടുത്തവരെ കണ്ടുമുട്ടുന്നത് വരെ ഞാൻ ഓടി. അവർ അവയെ എടുത്തിട്ടുണ്ടായിരുന്നു. ഞാൻ ഇപ്രകാരം പാടിക്കൊണ്ട് അവർക്കുനേരെ അമ്പെയ്യാൻ തുടങ്ങി: ''ഞാൻ അക്വഇന്റെ പുത്രനാണ്, ഇന്ന് നീചന്മാരുടെ നാശദിവസമാണ്.'' അവസാനം അവർ ആ ഒട്ടകങ്ങളുടെ പാൽ കുടിക്കും മുമ്പ് തന്നെ ഞാൻ അവയെ മോചിപ്പിച്ചു. അവയെ തെളിച്ച് കൊണ്ട് ഞാൻ വരികയും നബി(സ)യെ കണ്ടുമുട്ടിയപ്പോൾ ഇപ്രകാരം പറയുകയും ചെയ്തു: റസൂലേ, അക്കൂട്ടർ ദാഹിച്ചവരായിരുന്നു, അവർ അവയെ കറന്നു കുടിക്കുന്നതിന് മുമ്പ് ഞാനവയെ മോചിപ്പിച്ചു. അതുകൊണ്ട് അവരുടെ പിറകിൽ വേഗം ഒരു കൂട്ടം ആളുകളെ അവിടന്ന് അയച്ചാലും. റസൂൽ(സ) പറഞ്ഞു: "അക്വഇന്റെ മകനേ, ഒട്ടകങ്ങളെ നീ അധീനപ്പെടുത്തിക്കഴിഞ്ഞിരിക്കുന്നു. ഇനി അക്കാര്യം വിട്ടേക്കുക, അവരെ തങ്ങളുടെ ഗോത്രക്കാർ ഇപ്പോൾ സൽക്കരിച്ചുകൊണ്ടിരിക്കുകയാവും." (ബു)', 'سَلَمَةَ', 'സലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 985, 986, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 411, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، ذَبَحْنَا بُهَيْمَةً لَنَا وَطَحَنْتُ صَاعًا مِنْ شَعِيرٍ فَتَعَالَ أَنْتَ وَنَفَرٌ، فَصَاحَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَهْلَ الْخَنْدَقِ، إِنَّ جَابِرًا قَدْ صَنَعَ سُؤْرًا فَحَيَّ هَلًا بِكُمْ". (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞാൻ പറഞ്ഞു: റസൂലേ, ഞങ്ങളുടെ ഒരാട്ടിൻകുട്ടിയെ ഞാൻ അറുത്തു. ഒരു സ്വാഅ് ബാർലി പൊടിച്ചിട്ടുമുണ്ട്. അതിനാൽ അവിടുന്നും അൽപം അനുചരന്മാരും വന്നാലും. ഉടനെ റസൂൽ(സ) ഇപ്രകാരം വിളിച്ച് പറഞ്ഞു: "കിടങ്ങ് കുഴിക്കുന്നവരേ, ഇതാ ജാബിർ(റ) കുറച്ച് ഭക്ഷണം തയ്യാറാക്കിയിരിക്കുന്നു, നിങ്ങൾ വേഗം വരിക." (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 986, 986, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 412, 'عَنْ أُمِّ خَالِدٍ بِنْتِ خَالِدِ بْنِ سَعِيدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ أَبِي وَعَلَيَّ قَمِيصٌ أَصْفَرُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَنَهْ سَنَهْ". وَهِيَ بِالْحَبَشِيَّةِ حَسَنَةٌ، قَالَتْ: فَذَهَبْتُ أَلْعَبُ بِخَاتَمِ النُّبُوَّةِ فَزَبَرَنِي أَبِي، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "دَعْهَا". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبْلِي وَأَخْلِفِي، ثُمَّ أَبْلِي وَأَخْلِفِي، ثُمَّ أَبْلِي وَأَخْلِفِي". (خ)', 'ഉമ്മുഖാലിദു ബിൻതുഖാലിദുബ്നു സഈദ്(റ): ഒരിക്കൽ ഞാനെന്റെ പിതാവിന്റെ കൂടെ നബി തിരുമേനി(സ)യുടെ അടുക്കൽ ചെന്നു. ഞാൻ ഒരു മഞ്ഞക്കുപ്പായമാണ് ധരിച്ചിരുന്നത്. അതുകണ്ട തിരുമേനി(സ) "സന, സന" എന്ന് പറഞ്ഞു. എത്യോപ്യൻ ഭാഷയിൽ അതിന്റെ അർത്ഥം ഭംഗിയുള്ളത് എന്നാണ്. ഉമ്മു ഖാലിദ്(റ) പറയുന്നു: പിന്നെ ഞാൻ ഖാത്വമുന്നുബുവ്വത് പിടിച്ചു കളിക്കാൻ തുടങ്ങി. അപ്പോൾ എന്റെ പിതാവ് എന്നെ ശാസിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അവളെ വിട്ടേക്കുക." അനന്തരം റസൂൽ(സ) ഇങ്ങനെ പ്രാർത്ഥിച്ചു: "വസ്ത്രം പഴകി നുരുമ്പുന്നതുവരെ ധരിക്കുക, വസ്ത്രം പഴകി നുരുമ്പുന്നതുവരെ ധരിക്കുക, വസ്ത്രം പഴകി നുരുമ്പുന്നതുവരെ ധരിക്കുക." (ദീർഘകാലം ജീവിക്കട്ടെ എന്നാണ് പ്രാർത്ഥനയുടെ അർത്ഥം). (ബു)', 'أُمِّ خَالِدٍ بِنْتِ خَالِدِ بْنِ سَعِيدٍ', 'ഉമ്മുഖാലിദു ബിൻതുഖാലിദുബ്നു സഈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 986, 986, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 413, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نُصِيبُ فِي مَغَازِينَا الْعَسَلَ وَالْعِنَبَ فَنَأْكُلُهُ وَلَا نَرْفَعُهُ. (خ)', 'ഇബ്നുഉമർ(റ): യുദ്ധങ്ങളിൽ ഞങ്ങൾക്ക് തേനും മുന്തിരിയും ലഭിക്കുകയും ഞങ്ങൾ അവ ഭക്ഷിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഞങ്ങൾ അത് കൊണ്ടുപോകാറുണ്ടായിരുന്നില്ല. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 986, 986, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 414, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَصَبْتُ جِرَابًا مِنْ شَحْمٍ يَوْمَ خَيْبَرَ، قَالَ: فَالْتَزَمْتُهُ، فَقُلْتُ: لَا أُعْطِي الْيَوْمَ أَحَدًا مِنْ هَذَا شَيْئًا، قَالَ: فَالْتَفَتُّ فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَبَسِّمًا. (ق,د,ن)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): ഖൈബർ യുദ്ധദിവസം എനിക്ക് ഒരു കൊട്ട നിറയെ നെയ്യ് ലഭിച്ചു. അത് സ്വന്തമാക്കിക്കൊണ്ട് ഞാൻ ഇപ്രകാരം പറഞ്ഞു: ഒരാൾക്കും ഇന്ന് ഇതിൽനിന്ന് ഒന്നും ഞാൻ കൊടുക്കുകയില്ല. നിവേദകൻ പറയുന്നു: ഞാൻ തിരിഞ്ഞുനോക്കുമ്പോൾ റസൂൽ(സ) പുഞ്ചിരിച്ചുകൊണ്ട് നിൽക്കുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 986, 987, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 415, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ جَيْشًا غَنِمُوا فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا وَعَسَلًا، فَلَمْ يُؤْخَذْ مِنْهُمُ الْخُمُسُ. (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഒരു സൈന്യത്തിന് ഭക്ഷണവും തേനും യുദ്ധമുതലായി ലഭിച്ചു. പക്ഷേ, അതിൽനിന്ന് അഞ്ചിലൊന്ന് വിഹിതം എടുക്കപ്പെട്ടില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 987, 987, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 416, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ بِكَابُلَ، فَأَصَابَ النَّاسُ غَنِيمَةً، فَانْتَهَبُوهَا، فَقَامَ خَطِيبًا فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النُّهْبَى. فَرَدُّوا مَا أَخَذُوا، فَقَسَمَهُ بَيْنَهُمْ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ): അദ്ദേഹം കാബൂളിലായിരിക്കുമ്പോൾ ജനങ്ങൾക്ക് യുദ്ധമുതൽ ലഭിക്കുകയും അവർ അത് കയ്യടക്കിവെക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പ്രസംഗിക്കാൻ വേണ്ടി എഴുന്നേൽക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: കവർന്നെടുത്ത (വിഹിതം വെക്കപ്പെടാതെ കയ്യടക്കപ്പെട്ട) മുതൽ റസൂൽ(സ) നിരോധിക്കുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ തങ്ങൾ എടുത്തിരുന്നതെല്ലാം അവർ തിരിച്ചു നൽകുകയും അദ്ദേഹം അത് അവർക്കിടയിൽ വീതിക്കുകയും ചെയ്തു. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 987, 987, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 417, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا سُئِلَ: هَلْ كُنْتُمْ تُخَمِّسُونَ – يَعْنِي الطَّعَامَ – فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: أَصَبْنَا طَعَامًا يَوْمَ خَيْبَرَ، فَكَانَ الرَّجُلُ يَجِيءُ فَيَأْخُذُ مِنْهُ مِقْدَارَ مَا يَكْفِيهِ ثُمَّ يَنْصَرِفُ. (د)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): റസൂൽ(സ)യുടെ കാലത്ത് നിങ്ങൾ ഭക്ഷണം (യുദ്ധത്തിൽ ലഭിച്ചത്) അഞ്ച് വിഹിതമാക്കാറുണ്ടായിരുന്നോ? എന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: ഖൈബർ യുദ്ധദിവസം ഞങ്ങൾക്ക് അൽപം ഭക്ഷണം ലഭിച്ചു. അങ്ങനെ ഓരോരുത്തർ വന്നുകൊണ്ട് അതിൽനിന്ന് തനിക്കാവശ്യമുള്ളയത്ര എടുത്ത് കൊണ്ടുപോവുകയായിരുന്നു ചെയ്തിരുന്നത്. (ദ)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 987, 987, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 418, 'عَنْ كُلَيْبِ بْنِ شِهَابٍ، عَنْ رَجُلٍ مِنَ الْأَنْصَارِ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأَصَابَ النَّاسَ حَاجَةٌ شَدِيدَةٌ وَجَهْدٌ، وَأَصَابُوا غَنَمًا فَانْتَهَبُوهَا، فَإِنَّ قُدُورَنَا لَتَغْلِي إِذْ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي عَلَى قَوْسِهِ، فَأَكْفَأَ قُدُورَنَا بِقَوْسِهِ، ثُمَّ جَعَلَ يُرَمِّلُ اللَّحْمَ بِالتُّرَابِ، ثُمَّ قَالَ: "إِنَّ النُّهْبَةَ لَيْسَتْ بِأَحَلَّ مِنَ الْمَيْتَةِ". أَوْ: "إِنَّ الْمَيْتَةَ لَيْسَتْ بِأَحَلَّ مِنَ النُّهْبَةِ". (د)', 'അൻസാരികളിൽപ്പെട്ട ഒരാളിൽ നിന്ന് കുലൈബുബ്നു ശിഹാബ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ ജനങ്ങൾക്ക് പ്രയാസങ്ങളും ശക്തമായ വിശപ്പും അനുഭവപ്പെട്ടു. അവർക്ക് അൽപം ആടുകളെ കിട്ടുകയും അവർ അവയെ കയ്യടക്കുകയും ചെയ്തു. ഞങ്ങളുടെ കലങ്ങൾ തിളച്ച് കൊണ്ടിരിക്കുമ്പോഴാണ് തന്റെ വില്ലും കുത്തിപ്പിടിച്ച് റസൂൽ(സ) നടന്നു വന്നത്. റസൂൽ(സ) തന്റെ വില്ലുകൊണ്ട് ഞങ്ങളുടെ കലങ്ങൾ കമിഴ്ത്തുകയും മാംസത്തിലേക്ക് മണ്ണ് കലർത്തുകയും ചെയ്തു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "കവർച്ച മുതൽ ശവത്തേക്കാൾ അനുവദനീയമല്ല." അല്ലെങ്കിൽ "ശവം കവർച്ച മുതലിനേക്കാൾ അനുവദനീയമല്ല." (ദ)', 'كُلَيْبِ بْنِ شِهَابٍ، عَنْ رَجُلٍ مِنَ الْأَنْصَارِ قَالَ', 'അൻസാരികളിൽപ്പെട്ട ഒരാളിൽ നിന്ന് കുലൈബുബ്നു ശിഹാബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 987, 987, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 419, 'عَنِ الْقَاسِمِ مَوْلَى عَبْدِ الرَّحْمَنِ، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنَّا نَأْكُلُ الْجَزَرَ فِي الْغَزْوِ، وَلَا نَقْسِمُهُ، حَتَّى إِنْ كُنَّا لَنَرْجِعُ إِلَى رِحَالِنَا وَأَخْرِجَتُنَا مِنْهُ مُمْلَأَةٌ. (د)', 'നബി(സ)യുടെ ഒരു അനുചരനിൽ നിന്ന് അബ്ദുർറഹ്മാൻ(റ)വിന്റെ അടിമയായ കാസിം(റ): വിഹിതം വെക്കാതെ തന്നെ യുദ്ധസമയങ്ങളിൽ ഞങ്ങൾ ഒട്ടകങ്ങളെ ഭക്ഷിക്കാറുണ്ടായിരുന്നു. ചിലപ്പോൾ പാത്രങ്ങൾ നിറയെ അവ എടുത്താണ് ഞങ്ങൾ തമ്പുകളിലേക്ക് മടങ്ങിയിരുന്നത്. (ദ)', 'الْقَاسِمِ مَوْلَى عَبْدِ الرَّحْمَنِ، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'നബി(സ)യുടെ ഒരു അനുചരനിൽ നിന്ന് അബ്ദുർറഹ്മാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 988, 988, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 420, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ غَنْمِ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَابَطْنَا مَدِينَةَ قِنَّسْرِينَ مَعَ شُرَحْبِيلَ بْنِ السِّمْطِ، فَلَمَّا فَتَحَهَا أَصَابَ فِيهَا غَنَمًا وَبَقَرًا، فَقَسَمَ فِينَا طَائِفَةً مِنْهَا وَجَعَلَ بَقِيَّتَهَا فِي الْمَغْنَمِ، فَلَقِيتُ مُعَاذَ بْنَ جَبَلٍ فَحَدَّثْتُهُ، فَقَالَ مُعَاذٌ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، فَأَصَبْنَا فِيهَا غَنَمًا، فَقَسَمَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَائِفَةً، وَجَعَلَ بَقِيَّتَهَا فِي الْمَغْنَمِ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു ഗൻമുൽ അശ്അരി(റ): ശുറഹ്ബീലുബ്നുസ്സിംത്(റ)വിനോടൊപ്പം ഞങ്ങൾ ഖിന്നസ്രീൻ പട്ടണം ഉപരോധിച്ചു. അങ്ങനെ ആ പട്ടണം ജയിച്ചടക്കിയപ്പോൾ ധാരാളം ആടുകളെയും പശുക്കളെയും ലഭിച്ചു. അതിലൊരു ഭാഗം ശുറഹ്ബീൽ(റ) ഞങ്ങൾക്ക് വീതിച്ചു തരികയും ബാക്കിയുള്ളവ യുദ്ധമുതലുകളിൽ വെക്കുകയും ചെയ്തു. ശേഷം ഞാൻ മുആദുബ്നു ജബൽ(റ)വിനെ കണ്ടുമുട്ടുകയും അദ്ദേഹത്തോട് വിവരം പറയുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ഖൈബറിനോട് യുദ്ധം ചെയ്യുകയും കുറേ ആടുകളെ ലഭിക്കുകയും ചെയ്തു. അവയിൽ ഒരു ഭാഗം റസൂൽ(സ) ഞങ്ങൾക്ക് വീതിച്ചു തരികയും ബാക്കിയുള്ളവ യുദ്ധമുതലിനൊപ്പം വെക്കുകയും ചെയ്തു. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ غَنْمِ الْأَشْعَرِيِّ', 'അബ്ദുർറഹ്മാനുബ്നു ഗൻമുൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 988, 988, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 421, 'عَنْ عُبَيْدِ اللَّهِ بْنِ سَلْمَانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُ قَالَ: لَمَّا فَتَحْنَا خَيْبَرَ أَخْرَجُوا غَنَائِمَهُمْ مِنَ الْمَتَاعِ وَالسَّبْيِ، فَجَعَلَ النَّاسُ يَتَبَايَعُونَ غَنَائِمَهُمْ، فَجَاءَ رَجُلٌ – حِينَ صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فَقَالَ: يَا رَسُولَ اللَّهِ، لَقَدْ رَبِحْتُ رِبْحًا مَا رَبِحَ الْيَوْمَ مِثْلَهُ أَحَدٌ مِنْ أَهْلِ هَذَا الْوَادِي، قَالَ: "وَيْحَكَ وَمَا رَبِحْتَ". قَالَ: مَا زِلْتُ أَبِيعُ وَأَبْتَاعُ حَتَّى رَبِحْتُ ثَلَاثَ مِائَةِ أُوقِيَّةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أُنَبِّئُكَ بِخَيْرِ رَجُلٍ رَبِحَ". قَالَ: مَا هُوَ يَا رَسُولَ اللَّهِ؟ قَالَ: "رَكْعَتَيْنِ بَعْدَ الصَّلَاةِ". (د)', 'ഉബൈദില്ലാഹിബ്നു സൽമാൻ(റ): നബി(സ)യുടെ അനുചരരിലൊരാൾ അദ്ദേഹത്തോട് പറഞ്ഞു: ഞങ്ങൾ ഖൈബർ ജയിച്ചടക്കിയപ്പോൾ യുദ്ധമുതലായി ലഭിച്ച ബന്ധികൾ, ചരക്കുകൾ എന്നിവയെടുത്ത് ജനങ്ങൾ പരസ്പരം കച്ചവടം നടത്താൻ തുടങ്ങി. അങ്ങനെ റസൂൽ(സ) നമസ്കരിക്കുമ്പോൾ ഒരാൾ വന്ന് പറഞ്ഞു: റസൂലേ, ഈ താഴ്വരയിൽ ഇന്ന് ഒരുത്തനും ലഭിച്ചിട്ടില്ലാത്തയത്ര ലാഭം എനിക്ക് ലഭിച്ചിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് നാശം, എപ്രകാരമാണ് നീ ലാഭമുണ്ടാക്കിയത്?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ വാങ്ങുകയും വിൽക്കുകയും ചെയ്തുകൊണ്ടേയിരുന്നു. അങ്ങനെ എനിക്ക് മുന്നൂറ് ഊഖിയ (ഒരു ഊഖിയ പന്ത്രണ്ട് വെള്ളിത്തൂക്കമാണ്) ലാഭമായി ലഭിക്കുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് ലാഭം കൊയ്യാൻ പറ്റുന്ന ഉത്തമമായ കാര്യം ഞാൻ നിനക്ക് പറഞ്ഞു തരാം." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണത്? റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് ശേഷം രണ്ട് റക്അത് (സുന്നത്തായി) നമസ്കരിക്കൽ." (ദ)', 'عُبَيْدِ اللَّهِ بْنِ سَلْمَانَ', 'ഉബൈദില്ലാഹിബ്നു സൽമാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 988, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 422, 'عَنْ خَارِجَةَ بْنِ زَيْدِ بْنِ ثَابِتٍ – رَضِيَ اللَّهُ عَنْهُ – قَالَ: رَأَيْتُ رَجُلًا يَسْأَلُ أَبِي عَنِ الرَّجُلِ يَغْزُو، فَيَشْتَرِي وَيَبِيعُ وَيَتَّجِرُ فِي غَزْوَتِهِ؟ فَقَالَ لَهُ أَبِي: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَبُوكَ، نَشْتَرِي وَنَبِيعُ، وَهُوَ يَرَانَا وَلَا يَنْهَانَا. قَالَ ابْنُ مَاجَه: إِسْنَادُهُ ضَعِيفٌ. (جه)', 'ഖാരിജതുബ്നു സൈദുബ്നു സാബിത്(റ): യുദ്ധം ചെയ്യുന്നതോടൊപ്പം യുദ്ധവേളയിൽ വാങ്ങലും വിൽപനയും നടത്തുന്ന വ്യക്തിയെക്കുറിച്ച് എന്റെ പിതാവിനോട് ഒരാൾ ചോദിക്കുന്നത് ഞാൻ കണ്ടു. എന്റെ പിതാവ് അദ്ദേഹത്തോട് പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പം നിൽക്കുമ്പോൾ തബൂക്ക് യുദ്ധവേളയിൽ ഞങ്ങൾ വാങ്ങലും വിൽപനയും നടത്തിയിരുന്നു. റസൂൽ(സ) ഞങ്ങളെ കണ്ടിട്ടും ഞങ്ങളെ വിലക്കിയിരുന്നില്ല. ഇബ്നുമാജ(റ) പറഞ്ഞു: ഇതിന്റെ പരമ്പര ബലഹീനമാണ്. (ജ)', 'خَارِجَةَ بْنِ زَيْدِ بْنِ ثَابِتٍ –', 'ഖാരിജതുബ്നു സൈദുബ്നു സാബിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 989, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 423, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَتُفْتَحُ عَلَيْكُمُ الْأَمْصَارُ، وَسَتَكُونُ جُنُودٌ مُجَنَّدَةٌ تُقْطَعُ عَلَيْكُمْ فِيهَا بُعُوثٌ، فَيَكْرَهُ الرَّجُلُ مِنْكُمُ الْبَعْثَ فِيهَا، فَيَتَخَلَّصُ مِنْ قَوْمِهِ، ثُمَّ يَتَصَفَّحُ الْقَبَائِلَ يَعْرِضُ نَفْسَهُ عَلَيْهِمْ، يَقُولُ: مَنْ أَكْفِيهِ بَعْثَ كَذَا، مَنْ أَكْفِيهِ بَعْثَ كَذَا؟ أَلَا وَذَلِكَ الْأَجِيرُ إِلَى آخِرِ قَطْرَةٍ مِنْ دَمِهِ". (د)', 'അബൂഅയ്യൂബ്(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് അദ്ദേഹം കേട്ടു: "വരും കാലങ്ങളിൽ പട്ടണങ്ങൾ നിങ്ങൾക്കുമുന്നിൽ കീഴടങ്ങും. അപ്പോൾ കൂടുതൽ സംഘങ്ങളുള്ള സൈന്യങ്ങളുണ്ടാവുകയും നിങ്ങൾ അവയിലേക്ക് യുദ്ധസംഘങ്ങളെ അയക്കേണ്ടി വരികയും ചെയ്യും. ആ സൈന്യത്തിൽ ചേരുന്നത് വെറുത്ത് നിങ്ങളിൽ ചിലർ തന്റെ സമൂഹത്തിൽ നിന്ന് ഒളിച്ചോടുകയും മറ്റു ഗോത്രങ്ങളിൽ ചെന്ന്, ആർക്ക് പകരമാണ് ഞാൻ ഇന്ന സൈന്യത്തിൽ ചേരേണ്ടത്? ആർക്ക് പകരമാണ് ഞാൻ ഇന്ന സൈന്യത്തിൽ ചേരേണ്ടത്? (വേതനത്തിന് പകരമായി അവരിലെ സൈനികനാവുക) എന്ന് ചോദിക്കുകയും ചെയ്യും. അറിയുക! തന്റെ അവസാന തുള്ളി രക്തം വീഴും വരെയും വേതനക്കാരനായി കഴിയുന്നവൻ അവനാണ്." (ദ)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 989, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 424, 'عَنْ يَعْلَى بْنِ مُنْيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: آذَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْغَزْوِ وَأَنَا شَيْخٌ كَبِيرٌ، لَيْسَ لِي خَادِمٌ، فَالْتَمَسْتُ أَجِيرًا يَكْفِينِي وَأُجْرِي لَهُ سَهْمَهُ، فَوَجَدْتُ رَجُلًا، فَلَمَّا دَنَا الرَّحِيلُ أَتَانِي فَقَالَ: مَا أَدْرِي مَا السُّهْمَانِ، وَمَا يَبْلُغُ سَهْمِي؟ فَسَمِّ لِي شَيْئًا كَانَ السَّهْمُ أَوْ لَمْ يَكُنْ. فَسَمَّيْتُ لَهُ ثَلَاثَةَ دَنَانِيرَ، فَلَمَّا حَضَرَتْ غَنِيمَتُهُ أَرَدْتُ أَنْ أُجْرِيَ لَهُ سَهْمَهُ، فَذَكَرْتُ الدَّنَانِيرَ، فَجِئْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ لَهُ أَمْرَهُ، فَقَالَ: "مَا أَجِدُ لَهُ فِي غَزْوَتِهِ هَذِهِ فِي الدُّنْيَا وَالْآخِرَةِ إِلَّا دَنَانِيرَهُ الَّتِي سَمَّى". (د)', 'യഅ്ലബ്നു മുൻയ(റ): ഞാൻ വൃദ്ധനായിരിക്കെ റസൂൽ(സ) യുദ്ധാഹ്വാനം നടത്തി. എനിക്ക് സേവകൻ ഉണ്ടായിരുന്നില്ല. അതിനാൽ എനിക്ക് പകരം പോരാടുന്നതിന് വേതനക്കാരനെ ഞാൻ അന്വേഷിക്കുകയും അവന് വിഹിതം നിശ്ചയിക്കാൻ തീരുമാനിക്കുകയും ചെയ്തു. അങ്ങനെ ഞാൻ ഒരാളെ കണ്ടെത്തി. യാത്രയുടെ സമയമായപ്പോൾ എന്റെയടുത്ത് വന്നുകൊണ്ട് അവൻ പറഞ്ഞു: രണ്ടു വിഹിതങ്ങൾ ഏതൊക്കെയെന്നോ എനിക്കുള്ള വിഹിതം എത്രയുണ്ടാകുമെന്നോ എനിക്കറിയില്ല. അതിനാൽ വിഹിതമുണ്ടെങ്കിലും ഇല്ലെങ്കിലും താങ്കൾ എനിക്ക് അൽപം വേതനം നിശ്ചയിക്കുക. അങ്ങനെ ഞാനവന് മൂന്ന് ദിർഹം വേതനം നിശ്ചയിച്ചു. ശേഷം യുദ്ധമുതൽ എത്തിയപ്പോൾ അവന്റെ വിഹിതം അവന് നൽകാമെന്ന് ഞാൻ കരുതി. പക്ഷേ, ദീനാറുകളുടെ കാര്യം എനിക്ക് ഓർമ്മവന്നു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് അവന്റെ കാര്യം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ യുദ്ധത്തിന് പകരം അവന് ഐഹിക ലോകത്തും പാരത്രിക ലോകത്തും വെച്ച് താൻ നിശ്ചയിച്ച ആ ദീനാറുകളല്ലാതെ ഒന്നും ലഭിക്കുന്നതായി ഞാൻ കാണുന്നില്ല." (ദ)', 'يَعْلَى بْنِ مُنْيَةَ', 'യഅ്ലബ്നു മുൻയ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 989, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 425, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِلْغَازِي أَجْرُهُ وَلِلْجَاعِلِ أَجْرُهُ وَأَجْرُ الْغَازِي". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "യോദ്ധാവിന് തന്റെ പ്രതിഫലമുണ്ട്. വേതനം നൽകുന്നവന് (യോദ്ധാവിന് വേതനം നൽകുന്നവന്) തന്റെ പ്രതിഫലവും യോദ്ധാവിന്റെ പ്രതിഫലവുമുണ്ട്." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 990, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 426, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خَيْبَرَ أَخْدُمُهُ، فَلَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاجِعًا وَبَدَا لَهُ أُحُدٌ، قَالَ: "هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ". (خ)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യോടൊപ്പം അവിടുത്തേക്ക് സേവനം ചെയ്യാൻ വേണ്ടി ഞാൻ ഖൈബറിലേക്ക് പോയി. അങ്ങനെ നബി(സ) മടങ്ങുകയും ഉഹ്ദ് പർവ്വതം അവിടുത്തേക്ക് വെളിവാകുകയും ചെയ്തപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നമ്മെ സ്നേഹിക്കുകയും നാം സ്നേഹിക്കുകയും ചെയ്യുന്ന പർവ്വതമാണിത്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 990, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 427, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرُنَا ظِلًّا الَّذِي يَسْتَظِلُّ بِكِسَائِهِ، وَأَمَّا الَّذِينَ صَامُوا فَلَمْ يَعْمَلُوا شَيْئًا، وَأَمَّا الَّذِينَ أَفْطَرُوا فَبَعَثُوا الرِّكَابَ وَامْتَهَنُوا وَعَالَجُوا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَهَبَ الْمُفْطِرُونَ الْيَوْمَ بِالْأَجْرِ". (خ)', 'അനസ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. തങ്ങളുടെ വസ്ത്രങ്ങൾ കൊണ്ട് തണൽ കൊണ്ടവർക്കായിരുന്നു ഞങ്ങളുടെ കൂട്ടത്തിൽ കൂടുതൽ തണൽ കിട്ടിയിരുന്നത്. നോമ്പനുഷ്ഠിച്ചിരുന്നവർ അന്ന് ഒരു പ്രവർത്തനവും ചെയ്തില്ല. നോമ്പനുഷ്ഠിക്കാത്തവർ ഒട്ടകങ്ങളെ വെള്ളമുള്ള സ്ഥലത്തേക്കയക്കുകയും ജോലിയിൽ വ്യാപൃതരാവുകയും ഒട്ടകങ്ങളെ പരിപാലിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നോമ്പനുഷ്ഠിക്കാത്തവരാണ് ഇന്ന് പ്രതിഫലത്തിനർഹരായത്." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 990, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 428, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "خِدْمَةُ عَبْدٍ فِي سَبِيلِ اللَّهِ، أَوْ ظِلُّ فُسْطَاطٍ، أَوْ طَرُوقَةُ فَحْلٍ فِي سَبِيلِ اللَّهِ". (ت)', 'അദിയ്യുബ്നു ഹാതിമുത്ത്വാഈ(റ): അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു: ഏത് ദാനമാണ് ഏറ്റവും ഉത്തമമായത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാടുന്നവന്) സേവനത്തിനായി അടിമയെ നൽകൽ, (പോരാളിക്ക് വിശ്രമിക്കാൻ വേണ്ടി) കൂടാരം കെട്ടി തണൽ സൃഷ്ടിക്കൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാട്ടത്തിനായി ഒട്ടകത്തെ നൽകൽ എന്നിവയാണത്." (തു)', 'عَدِيِّ بْنِ حَاتِمٍ الطَّائِيِّ', 'അദിയ്യുബ്നു ഹാതിമുത്ത്വാഈ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 990, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 429, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ الصَّدَقَاتِ ظِلُّ فُسْطَاطٍ فِي سَبِيلِ اللَّهِ، وَمَنِيحَةُ خَادِمٍ فِي سَبِيلِ اللَّهِ، أَوْ طَرُوقَةُ فَحْلٍ فِي سَبِيلِ اللَّهِ". (ت)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാടുന്നവർക്ക്) കൂടാരം കെട്ടി തണൽ സൃഷ്ടിക്കൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സേവകനെ നൽകൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാട്ടത്തിനായി) ഒട്ടകത്തെ നൽകൽ എന്നിവയാണ് ഏറ്റവും ഉത്തമമായ ദാനങ്ങൾ." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 430, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ زَحْزَحَهُ اللَّهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا". وَفِي رِوَايَةٍ: "أَرْبَعِينَ خَرِيفًا". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുമ്പോൾ ഒരാൾ ഒരു ദിവസം നോമ്പനുഷ്ഠിച്ചാൽ അല്ലാഹു അവനെ നരകത്തിൽ നിന്ന് എഴുപത് ഖരീഫ് (വർഷം) - മറ്റൊരു നിവേദനം: നാൽപത് വർഷം - അകലെയാക്കും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=430), 1, 'وَفِي رِوَايَةٍ: "أَرْبَعِينَ خَرِيفًا". (ت)', 'മറ്റൊരു നിവേദനം: നാൽപത് വർഷം - അകലെയാക്കും." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 431, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَصُومُ عَبْدٌ يَوْمًا فِي سَبِيلِ اللَّهِ إِلَّا بَاعَدَ ذَلِكَ الْيَوْمُ النَّارَ عَنْ وَجْهِهِ سَبْعِينَ خَرِيفًا". (ق,ت,ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുമ്പോൾ ഒരു ദിവസം നോമ്പനുഷ്ഠിച്ച അടിമയുടെ മുഖത്തെ, ആ ഒരു ദിവസത്തെ നോമ്പ് നരകത്തിൽ നിന്ന് എഴുപത് ഖരീഫ് (വർഷം) അകലെയാക്കുന്നതാണ്." (ബു,മു,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 432, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ جَعَلَ اللَّهُ بَيْنَهُ وَبَيْنَ النَّارِ خَنْدَقًا كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ". (ت)', 'അബൂഉമാമതുൽ ബാഹിലി(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുമ്പോൾ ഒരു ദിവസം നോമ്പനുഷ്ഠിച്ച വ്യക്തിക്കും നരകത്തിനുമിടയിൽ ആകാശഭൂമികൾക്കിടയിലുള്ള അത്ര അകലമുള്ള കിടങ്ങ് അല്ലാഹു നിർമ്മിക്കുന്നതാണ്." (തു)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 433, 'عَنْ كَعْبِ بْنِ مُرَّةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ شَابَ شَيْبَةً فِي الْإِسْلَامِ – وَفِي رِوَايَةٍ: فِي سَبِيلِ اللَّهِ – كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ". (ت,ن)', 'കഅ്ബുബ്നു മുർറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഇസ്ലാമിലായി ജീവിച്ച് കൊണ്ട് - മറ്റൊരു നിവേദനം: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാടിക്കൊണ്ട്) - ഒരാൾക്ക് നര ബാധിച്ചാൽ അന്ത്യനാളിൽ അത് അവന്റെ പ്രകാശമായി മാറുന്നതാണ്." (തു,ന)', 'كَعْبِ بْنِ مُرَّةَ', 'കഅ്ബുബ്നു മുർറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=433), 1, 'وَفِي رِوَايَةٍ: فِي سَبِيلِ اللَّهِ – كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ". (ت,ن)', 'മറ്റൊരു നിവേദനം: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാടിക്കൊണ്ട്) - ഒരാൾക്ക് നര ബാധിച്ചാൽ അന്ത്യനാളിൽ അത് അവന്റെ പ്രകാശമായി മാറുന്നതാണ്." (തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 434, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَهِرَ فَلَمَّا قَدِمَ الْمَدِينَةَ قَالَ: "لَيْتَ رَجُلًا مِنْ أَصْحَابِي صَالِحًا يَحْرُسُنِي اللَّيْلَةَ". إِذْ سَمِعْنَا صَوْتَ سِلَاحٍ، فَقَالَ: "مَنْ هَذَا؟" قَالَ: أَنَا سَعْدُ بْنُ أَبِي وَقَّاصٍ جِئْتُ لِأَحْرُسَكَ وَنَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ആഇശ(റ): നബി(സ) ഉറക്കമൊഴിച്ചിരുന്നു. ശേഷം അവിടന്ന് മദീനയിൽ വന്നപ്പോൾ ഇപ്രകാരം പറഞ്ഞു: "എന്റെ അനുചരരിൽപെട്ട നല്ല ഒരു വ്യക്തി ഇന്ന് രാത്രി എനിക്ക് കാവൽ നിന്നിരുന്നെങ്കിൽ." ഉടൻ തന്നെ ഞങ്ങൾ ആയുധങ്ങളുടെ ശബ്ദം കേട്ടു. തിരുമേനി(സ) ചോദിച്ചു: "ആരാണത്?" ആഗതൻ പറഞ്ഞു: ഞാൻ സഅ്ദുബ്നു അബീവഖാസാണ്, അങ്ങേക്ക് കാവൽ നിൽക്കുവാൻ വേണ്ടിയാണ് ഞാൻ വന്നത്. അങ്ങനെ തിരുമേനി(സ) ഉറങ്ങി. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 435, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَعِسَ عَبْدُ الدِّينَارِ، وَعَبْدُ الدِّرْهَمِ، وَعَبْدُ الْخَمِيصَةِ إِنْ أُعْطِيَ رَضِيَ، وَإِنْ لَمْ يُعْطَ سَخِطَ، تَعِسَ وَانْتَكَسَ، وَإِذَا شِيكَ فَلَا انْتَقَشَ، طُوبَى لِعَبْدٍ آخِذٍ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ، أَشْعَثَ رَأْسُهُ، مُغْبَرَّةٍ قَدَمَاهُ، إِنْ كَانَ فِي الْحِرَاسَةِ كَانَ فِي الْحِرَاسَةِ، وَإِنْ كَانَ فِي السَّاقَةِ كَانَ فِي السَّاقَةِ، إِنِ اسْتَأْذَنَ لَمْ يُؤْذَنْ لَهُ، وَإِنْ شَفَعَ لَمْ يُشَفَّعْ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നൽകപ്പെട്ടാൽ തൃപ്തനാവുകയും ഇല്ലെങ്കിൽ ദേഷ്യപ്പെടുകയും ചെയ്യുന്ന, ദീനാറിന്റെയും ദിർഹമിന്റെയും കറുത്തവരയുള്ള വസ്ത്രത്തിന്റെയും അടിമ നശിക്കട്ടെ. അവൻ നശിക്കുകയും തലകുത്തി വീഴുകയും ചെയ്യട്ടെ. അവന് മുള്ള് തറച്ചാൽ അത് പറിച്ചെടുക്കാൻ സാധിക്കാതെ വരട്ടെ. കാലുകളിൽ പൊടി പുരണ്ട്, തലമുടി ജഢപിടിച്ച്, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുവാൻ വേണ്ടി തന്റെ കുതിരയുടെ കണിഞ്ഞാൺ പിടിക്കുന്ന അടിമക്കാണ് നന്മ. മുന്നണി സൈന്യത്തിലാണ് നിൽക്കേണ്ടതെങ്കിൽ അവൻ അതിൽ നിൽക്കും. പിന്നണി സൈന്യത്തിലാണ് നിൽക്കേണ്ടതെങ്കിൽ അവൻ അതിൽ നിൽക്കും. അവൻ സമ്മതം ചോദിച്ചാൽ അനുവാദം ലഭിക്കുകയോ ശുപാർശ ചെയ്താൽ സ്വീകരിക്കപ്പെടുകയോ ചെയ്യില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 436, 'عَنْ سَهْلِ بْنِ الْحَنْظَلِيَّةِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُمْ سَارُوا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ، فَأَطْنَبُوا السَّيْرَ حَتَّى كَانَتْ عَشِيَّةً، فَحَضَرْتُ الصَّلَاةَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ رَجُلٌ فَارِسٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي انْطَلَقْتُ بَيْنَ أَيْدِيكُمْ حَتَّى طَلَعْتُ جَبَلَ كَذَا وَكَذَا، فَإِذَا أَنَا بِهَوَازِنَ عَلَى بَكْرَةِ آبَائِهِمْ – بِظُعُنِهِمْ وَنَعَمِهِمْ وَشَائِهِمْ – اجْتَمَعُوا إِلَى حُنَيْنٍ. فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "تِلْكَ غَنِيمَةُ الْمُسْلِمِينَ غَدًا إِنْ شَاءَ اللَّهُ". ثُمَّ قَالَ: "مَنْ يَحْرُسُنَا اللَّيْلَةَ". قَالَ أَنَسُ بْنُ أَبِي مَرْثَدٍ الْغَنَوِيُّ رَضِيَ اللَّهُ عَنْهُ: أَنَا يَا رَسُولَ اللَّهِ، قَالَ: "فَارْكَبْ". فَرَكِبَ فَرَسًا لَهُ، فَجَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْتَقْبِلْ هَذَا الشِّعْبَ حَتَّى تَكُونَ فِي أَعْلَاهُ، وَلَا نُغَرَّنَّ مِنْ قِبَلِكَ اللَّيْلَةَ". فَلَمَّا أَصْبَحْنَا خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى مُصَلَّاهُ فَرَكَعَ رَكْعَتَيْنِ ثُمَّ قَالَ: "هَلْ أَحْسَسْتُمْ فَارِسَكُمْ". قَالُوا: يَا رَسُولَ اللَّهِ مَا أَحْسَسْنَاهُ. فَثُوِّبَ بِالصَّلَاةِ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَهُوَ يَلْتَفِتُ إِلَى الشِّعْبِ، حَتَّى إِذَا قَضَى صَلَاتَهُ وَسَلَّمَ قَالَ: "أَبْشِرُوا فَقَدْ جَاءَكُمْ فَارِسُكُمْ". فَجَعَلْنَا نَنْظُرُ إِلَى خِلَالِ الشَّجَرِ فِي الشِّعْبِ، فَإِذَا هُوَ قَدْ جَاءَ حَتَّى وَقَفَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ فَقَالَ: إِنِّي انْطَلَقْتُ حَتَّى كُنْتُ فِي أَعْلَى هَذَا الشِّعْبِ حَيْثُ أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَصْبَحْتُ اطَّلَعْتُ الشِّعْبَيْنِ كِلَيْهِمَا فَنَظَرْتُ فَلَمْ أَرَ أَحَدًا. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ نَزَلْتَ اللَّيْلَةَ". قَالَ: لَا، إِلَّا مُصَلِّيًا أَوْ قَاضِيًا حَاجَةً. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَوْجَبْتَ، فَلَا عَلَيْكَ أَنْ لَا تَعْمَلَ بَعْدَهَا". (د,ن)', 'സഹ്ലുബ്നുൽ ഹൻളലിയ്യ(റ): ഹുനൈൻ യുദ്ധദിവസം അവർ റസൂൽ(സ)യോടൊപ്പം സഞ്ചരിക്കുകയും ധാരാളം സഞ്ചരിച്ച് രാത്രിയാവുകയും ചെയ്തു. തിരുമേനി(സ)യോടൊപ്പം ഞാൻ നമസ്കാരം നിർവ്വഹിച്ചു. ഉടനെ ഒരു കുതിരസവാരിക്കാരൻ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ നിങ്ങളുടെ മുന്നിൽ സഞ്ചരിക്കുകയും ഇന്നാലിന്ന പർവ്വതത്തിനു മുകളിൽ കയറുകയും ചെയ്തു. നോക്കുമ്പോൾ ഹവാസിനുകാർ തങ്ങളുടെ സ്ത്രീകളും ആടുകളും ഒട്ടകങ്ങളുമായി ഹൂനൈൻ എന്ന സ്ഥലത്ത് ഒരുമിച്ചുകൂടിയിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പുഞ്ചിരിച്ചുകൊണ്ട് പറഞ്ഞു: "അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം നാളെ അവയെല്ലാം മുസ്ലിംകളുടെ യുദ്ധമുതലായിരിക്കും." ശേഷം അവിടന്ന് ചോദിച്ചു: "ഇന്ന് രാത്രി ആരാണ് നമുക്ക് കാവൽ നിൽക്കുക?" അനസുബ്നു അബീമർസദുൽ ഗനവി(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ കാവൽ നിൽക്കാം. തിരുമേനി(സ) പറഞ്ഞു: "എങ്കിൽ നീ വാഹനം കയറുക." അദ്ദേഹം തന്റെ കുതിരപ്പുറത്ത് കയറുകയും റസൂൽ(സ)യുടെ അടുത്ത് വരികയും ചെയ്തു. തിരുമേനി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ ഈ മലഞ്ചെരുവിന്റെ ഭാഗത്തേക്ക് പോയി ഏറ്റവും ഉയർന്ന ഭാഗത്ത് നിൽക്കുക. ഇന്നുരാത്രി നിന്റെ ഭാഗത്തുകൂടെ ഞങ്ങൾ ഒരിക്കലും അക്രമിക്കപ്പെടാൻ പാടില്ല." നേരം പുലർന്നപ്പോൾ തിരുമേനി(സ) നമസ്കരിക്കാൻ വേണ്ടി പോവുകയും രണ്ട് റക്അത് നമസ്കരിച്ച ശേഷം ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: "നിങ്ങൾ ആ കുതിരപ്പടയാളിയുടെ വല്ല വിവരവും അറിഞ്ഞോ?" അവർ പറഞ്ഞു: ഇല്ല, റസൂലേ, ഞങ്ങൾ അവന്റെ വിവരം അറിഞ്ഞിട്ടില്ല. ഉടൻ തന്നെ നമസ്കാരത്തിന് ഇഖാമത് കൊടുത്തു. റസൂൽ(സ) ആ മലഞ്ചെരുവിന്റെ ഭാഗത്തേക്ക് തിരിഞ്ഞുനോക്കിക്കൊണ്ട് നമസ്കരിച്ചു. നമസ്കാരം കഴിഞ്ഞ് സലാം വീട്ടിയപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ സന്തോഷിക്കുക, ആ കുതിരപ്പടയാളി വന്നിരിക്കുന്നു." ഞങ്ങൾ മലഞ്ചെരുവിലുള്ള മരങ്ങൾക്കിടയിലേക്ക് നോക്കി. അപ്പോൾ അദ്ദേഹം വന്ന് തിരുമേനി(സ)യുടെ മുന്നിൽ നിന്ന് സലാം ചോല്ലി. എന്നിട്ട് പറഞ്ഞു: ഞാൻ പോയി റസൂൽ(സ) കൽപിച്ചതു പ്രകാരം ഈ മലഞ്ചെരുവിന്റെ ഏറ്റവും ഉയർന്ന ഭാഗത്ത് നിന്നു. നേരം പുലർന്നപ്പോൾ ഞാൻ രണ്ട് മലഞ്ചെരുവുകളിലേക്കും നോക്കിയെങ്കിലും ഒരാളെയും കണ്ടില്ല. റസൂൽ(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "രാത്രി നീ (അവിടെ നിന്ന്) ഇറങ്ങിയിരുന്നോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല, നമസ്കരിക്കാനോ മറ്റു ആവശ്യങ്ങൾ നിറവേറ്റാനോ വേണ്ടിയല്ലാതെ ഞാൻ ഇറങ്ങിയിട്ടില്ല. തിരുമേനി(സ) പറഞ്ഞു: "നീ (സ്വർഗ്ഗം) ഉറപ്പായവനാണ്, ഇതിന് ശേഷം കർമ്മം ചെയ്യാതിരിക്കുന്നതിൽ നിനക്ക് പ്രശ്നമില്ല." (ദ,ന)', 'سَهْلِ بْنِ الْحَنْظَلِيَّةِ', 'സഹ്ലുബ്നുൽ ഹൻളലിയ്യ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 992, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 437, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "عَيْنَانِ لَا تَمَسُّهُمَا النَّارُ: عَيْنٌ بَكَتْ مِنْ خَشْيَةِ اللَّهِ، وَعَيْنٌ بَاتَتْ تَحْرُسُ فِي سَبِيلِ اللَّهِ". قَالَ تِرْمِذِي: وَفِي الْبَابِ عَنْ عُثْمَانَ وَأَبِي رَيْحَانَةَ، وَحَدِيثُ ابْنِ عَبَّاسٍ حَدِيثٌ حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുമ്പോൾ കാവൽ നിന്ന് ഉറക്കമൊഴിച്ച കണ്ണ്, അല്ലാഹുവിനെ ഭയന്ന് കരഞ്ഞ കണ്ണ് എന്നീ രണ്ട് കണ്ണുകളെ നരകം സ്പർശിക്കുകയില്ല." തുർമുദി(റ) പറഞ്ഞു: ഇതേ വിഷയത്തിൽ ഉസ്മാൻ(റ)വിൽ നിന്നും അബൂറൈഹാന(റ)വിൽ നിന്നും റിപ്പോർട്ടുകളുണ്ട്. ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ ഹദീസ് ഹസനാണ്. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 438, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رَحِمَ اللَّهُ حَارِسَ الْحَرَسِ". إِسْنَادُهُ ضَعِيفٌ. (جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "കാവൽ നിൽക്കുന്നവർക്ക് (സൈനികർക്ക്) കാവൽ നിൽക്കുന്നവന് അല്ലാഹു കരുണ ചെയ്യട്ടെ." ഇതിന്റെ പരമ്പര ബലഹീനമാണ്. (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 439, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "حَرَسُ لَيْلَةٍ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِنْ صِيَامِ رَجُلٍ وَقِيَامِهِ فِي أَهْلِهِ أَلْفَ سَنَةٍ: السَّنَةُ ثَلَاثُ مِائَةٍ وَسِتُّونَ يَوْمًا، وَالْيَوْمُ كَأَلْفِ سَنَةٍ". فِي إِسْنَادِهِ سَعِيدُ بْنُ خَالِدِ بْنِ أَبِي الطَّوِيلِ، يَرْوِي عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ مَنَاكِيرَ. (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുമ്പോൾ ഒരു രാത്രി കാവൽ നിൽക്കൽ, ഒരാൾ തന്റെ കുടുംബത്തോടൊപ്പം നിന്ന് ആയിരം വർഷം നമസ്കരിക്കുകയും നോമ്പെടുക്കുകയും ചെയ്യുന്നതിനേക്കാൾ ശ്രേഷ്ടമാണ്. ഒരു വർഷമെന്നാൽ മുന്നൂറ്റി അറുപത് ദിവസമാണ്. ഒരു ദിവസം തന്നെ ആയിരം വർഷങ്ങളെപ്പോലെയാണ്." ഈ ഹദീസിന്റെ പരമ്പരയിൽ സഈദുബ്നു ഖാലിദുബ്നു അബിത്ത്വവീലുണ്ട്. അദ്ദേഹം അനസ്(റ)വിൽ നിന്ന് മുൻകറായ ഹദീസുകൾ റപ്പോർട്ട് ചെയ്യുന്നയാളാണ്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 440, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "أُوصِيكَ بِتَقْوَى اللَّهِ، وَالتَّكْبِيرِ عَلَى كُلِّ شَرَفٍ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഒരാളോട് ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവിന് തഖ്വ ചെയ്യണമെന്നും എല്ലാ ഉയർന്ന സ്ഥലത്തുവെച്ചും തക്ബീർ ചൊല്ലണമെന്നും ഞാൻ നിന്നെ ഉപദേശിക്കുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 441, 'عَنْ أَبِي رَيْحَانَةَ – شَمْعُونِ بْنِ زَيْدِ الْأَزْدِي – رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "حُرِّمَتْ عَيْنٌ عَلَى النَّارِ سَهِرَتْ فِي سَبِيلِ اللَّهِ". (ن)', 'അബൂറൈഹാന ശംഊനുബ്നു സൈദിൽ അസ്ദി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഉറക്കമൊഴിക്കുന്ന കണ്ണ് നരകത്തിന് നിഷിദ്ധമാണ്." (ന)', 'أَبِي رَيْحَانَةَ – شَمْعُونِ بْنِ زَيْدِ الْأَزْدِي –', 'അബൂറൈഹാന ശംഊനുബ്നു സൈദിൽ അസ്ദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 442, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَفْلَةٌ كَغَزْوَةٍ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "യുദ്ധമുഖത്ത് നിന്ന് മടങ്ങൽ യുദ്ധം ചെയ്യുന്നത് പോലെയാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 443, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: {لَا يَسْتَأْذِنُكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ} الْآيَةَ، نَسَخَتْهَا الَّتِي فِي النُّورِ: {إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ} إِلَى قَوْلِهِ {غَفُورٌ رَحِيمٌ}. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നവർ (യുദ്ധത്തിൽ നന്ന് ഒഴിഞ്ഞ് നിൽക്കാൻ) അങ്ങയോട് അനുവാദം ചോദിക്കുകയില്ല.'' എന്ന ആയത്തിനെ നൂർ സൂറത്തിലെ ഈ സൂക്തം നസ്ഖ് ചെയ്തു (ദുർബലപ്പെടുത്തി): ''അല്ലാഹുവിലും അവന്റെ ദൂതരിലും വിശ്വസിച്ചവർ മാത്രമാണ് സത്യവിശ്വാസികൾ'' എന്നതു മുതൽ ''അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു'' എന്നതു വരെ. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, 'ദുർബലപ്പെടുത്തി', 994, 995, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 444, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ فَتًى مِنْ أَسْلَمَ قَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُرِيدُ الْجِهَادَ، وَلَيْسَ لِي مَالٌ أَتَجَهَّزُ بِهِ. قَالَ: "اذْهَبْ إِلَى فُلَانٍ الْأَنْصَارِيِّ، فَإِنَّهُ كَانَ قَدْ تَجَهَّزَ فَمَرِضَ، فَقُلْ لَهُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُكَ السَّلَامَ، وَقُلْ لَهُ: ادْفَعْ إِلَيَّ مَا تَجَهَّزْتَ بِهِ". فَأَتَاهُ فَقَالَ لَهُ ذَلِكَ، فَقَالَ لِامْرَأَتِهِ: يَا فُلَانَةُ، ادْفَعِي لَهُ مَا جَهَّزْتِنِي بِهِ، وَلَا تَحْبِسِي مِنْهُ شَيْئًا، فَوَاللَّهِ لَا تَحْبِسِينَ مِنْهُ شَيْئًا فَيُبَارِكَ اللَّهُ فِيهِ. (م,د)', 'അനസുബ്നു മാലിക്(റ): അസ്ലം ഗോത്രക്കാരനായ ഒരു യുവാവ് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് യുദ്ധത്തിന് പോകാൻ ആഗ്രഹമുണ്ട്. പക്ഷേ, അതിനൊരുങ്ങാനുള്ള സമ്പത്ത് എനിക്കില്ല. നബി(സ) പറഞ്ഞു: "നീ ഇന്നാലിന്ന അൻസാരിയുടെയടുത്ത് പോകുക. അദ്ദേഹം യുദ്ധത്തിന് പോകാനൊരുങ്ങിയിരുന്നു. പക്ഷേ, രോഗം ബാധിച്ചു. നീ അവനോട് പറയുക, റസൂൽ(സ) താങ്കളോട് സലാം പറഞ്ഞിട്ടുണ്ട്. ശേഷം പറയുക: നീ ഒരുക്കിയ സാധനങ്ങൾ എനിക്ക് തരിക." അദ്ദേഹം അൻസാരിയുടെയടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു: അപ്പോൾ അദ്ദേഹം തന്റെ ഭാര്യയോട് പറഞ്ഞു: എടീ, നീ എനിക്ക് ഒരുക്കിത്തന്നിരുന്ന സാധനങ്ങൾ അദ്ദേഹത്തിന് നൽകുക. അതിൽ നിന്ന് ഒന്നും തന്നെ എടുത്തുവെക്കേണ്ട, അല്ലാഹുവിനെ തന്നെ സത്യം, നീ അതിൽ നിന്ന് എന്തെങ്കിലും പിടിച്ചുവെച്ചാൽ അല്ലാഹു അതിൽ ബറകത് ചെയ്യുകയില്ല. (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 995, 995, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 445, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْوَامًا مِنْ بَنِي سُلَيْمٍ إِلَى بَنِي عَامِرٍ فِي سَبْعِينَ، فَلَمَّا قَدِمُوا قَالَ لَهُمْ خَالِي: أَتَقَدَّمُكُمْ، فَإِنْ أَمَّنُونِي حَتَّى أُبَلِّغَهُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَّا كُنْتُمْ مِنِّي قَرِيبًا، فَتَقَدَّمَ فَأَمَّنُوهُ، فَبَيْنَمَا يُحَدِّثُهُمْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَوْمَئُوا إِلَى رَجُلٍ مِنْهُمْ فَطَعَنَهُ فَأَنْفَذَهُ فَقَالَ: اللَّهُ أَكْبَرُ، فُزْتُ وَرَبِّ الْكَعْبَةِ. ثُمَّ مَالُوا عَلَى بَقِيَّةِ أَصْحَابِهِ، فَقَتَلُوهُمْ إِلَّا رَجُلًا أَعْرَجَ صَعِدَ الْجَبَلَ، فَأَخْبَرَ جِبْرِيلُ عَلَيْهِ السَّلَامُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُمْ قَدْ لَقُوا رَبَّهُمْ، فَرَضِيَ عَنْهُمْ وَأَرْضَاهُمْ، فَكُنَّا نَقْرَأُ: أَنْ بَلِّغُوا قَوْمَنَا أَنْ قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا. ثُمَّ نُسِخَ بَعْدُ فَدَعَا عَلَيْهِمْ أَرْبَعِينَ صَبَاحًا، عَلَى رِعْلٍ، وَذَكْوَانَ، وَبَنِي لَحْيَانَ، وَبَنِي عُصَيَّةَ، الَّذِينَ عَصَوُا اللَّهَ وَرَسُولَهُ. (خ)', 'അനസുബ്നു മാലിക്(റ): ബനൂസുലൈം ഗോത്രത്തിൽ നിന്നുള്ള എഴുപതംഗ സംഘത്തെ നബി(സ) ബനൂആമിർ ഗോത്രത്തിലേക്ക് അയച്ചു. അവർ അവിടെ എത്തിയപ്പോൾ എന്റെ അമ്മാവൻ അവരോട് പറഞ്ഞു: ഞാൻ നിങ്ങൾക്ക് മുമ്പേ പോകാം. തിരുമേനി(സ)യുടെ സന്ദേശം ഞാനവർക്കെത്തിക്കും വരെ അവരെനിക്ക് അഭയം നൽകുകയാണെങ്കിൽ അങ്ങനെയാവാം. അല്ലാത്ത പക്ഷം നിങ്ങളെന്റെ സമീപത്തായി നിന്നാൽ മതി. അങ്ങനെ അദ്ദേഹം ആദ്യം പോയി. അവർ അദ്ദേഹത്തിന് അഭയം നൽകി. അങ്ങനെ അദ്ദേഹം നബി(സ)യെക്കുറിച്ച് അവരോട് സംസാരിക്കുന്നതിനിടയിൽ അവർ കൂട്ടത്തിലൊരാളോട് ആംഗ്യം കാണിച്ചു. അപ്പോൾ അയാൾ അദ്ദേഹത്തെ കുത്തുകയും അത് അദ്ദേഹത്തിനേൽക്കുകയും ചെയ്തു. അദ്ദേഹം വിളിച്ചു പറഞ്ഞു: അല്ലാഹു അക്ബർ, കഅ്ബയുടെ നാഥൻ തന്നെ സത്യം! ഞാൻ വിജയിച്ചിരിക്കുന്നു. ശേഷം അവർ അദ്ദേഹത്തിന്റെ ശേഷിച്ച കൂട്ടുകാരെ വളയുകയും മുടന്തനായ ഒരാളെ ഒഴികെ എല്ലാവരെയും വധിച്ചുകളയുകയും ചെയ്തു. മുടന്തൻ മലമുകളിൽ കയറി രക്ഷപ്പെട്ടു. അന്നേരം ജിബ്രീൽ(അ), അവർ (വധിക്കപ്പെട്ടവർ) തങ്ങളുടെ രക്ഷിതാവിനെ കണ്ടുമുട്ടിയെന്നും അവരുടെ കാര്യത്തിൽ അവൻ തൃപ്തനായെന്നും അവരെ അവൻ തൃപ്തിപ്പെടുത്തിയെന്നും നബി(സ)യെ അറിയിച്ചു. ഞങ്ങൾ ഇങ്ങനെ ഓതാറുണ്ടായിരുന്നു: ''ഞങ്ങളുടെ നാഥനെ ഞങ്ങൾ കണ്ടുമുട്ടിയെന്നും നാഥൻ ഞങ്ങളുടെ കാര്യത്തിൽ തൃപ്തനായിരിക്കുന്നുവെന്നും ഞങ്ങളെ അവൻ തൃപ്തിപ്പെടുത്തിയിരിക്കുന്നുവെന്നും ഞങ്ങളുടെ ആളുകൾക്ക് നിങ്ങൾ എത്തിക്കുക.'' പിന്നീട് ഇത് ദുർബ്ബലപ്പെടുത്തപ്പെട്ടു. ശേഷം, അല്ലാഹുവിനോടും അവന്റെ ദൂതനോടും ധിക്കാരം കാണിച്ച റിഅ്ല്, ദക്വാൻ, ബനൂലിഹ്യാൻ, ബനൂഉസയ്യ എന്നീ ഗോത്രങ്ങൾക്കെതിരിൽ നബി(സ) നാൽപത് സുബ്ഹി നിസ്കാരങ്ങളിൽ പ്രാർത്ഥിച്ചു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 995, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 446, 'عَنْ جُنْدُبِ بْنِ سُفْيَانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي بَعْضِ الْمَشَاهِدِ وَقَدْ دَمِيَتْ إِصْبَعُهُ فَقَالَ: "هَلْ أَنْتِ إِلَّا إِصْبَعٌ دَمِيتِ وَفِي سَبِيلِ اللَّهِ مَا لَقِيتِ". (خ)', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ): ഒരു യുദ്ധത്തിൽ നബി(സ)യുടെ വിരൽ മുറിഞ്ഞു രക്തമൊഴുകാൻ തുടങ്ങി. അപ്പോൾ അവിടന്ന് ഇങ്ങനെ പാടി: "രക്തമൊഴുകുന്ന ഒരു വിരലല്ലാതെ മറ്റൊന്നുമല്ല നീ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാണ് നിനക്കിത് സംഭവിച്ചത്." (ബു)', 'جُنْدُبِ بْنِ سُفْيَانَ', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 996, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 447, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا كَانَ يَوْمُ أُحُدٍ وَوَلَّى النَّاسُ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَاحِيَةٍ فِي اثْنَيْ عَشَرَ رَجُلًا مِنَ الْأَنْصَارِ، وَفِيهِمْ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ، فَأَدْرَكَهُمُ الْمُشْرِكُونَ، فَالْتَفَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "مَنْ لِلْقَوْمِ". فَقَالَ طَلْحَةُ: أَنَا. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَمَا أَنْتَ". فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: أَنَا يَا رَسُولَ اللَّهِ. فَقَالَ: "أَنْتَ". فَقَاتَلَ حَتَّى قُتِلَ، ثُمَّ الْتَفَتَ فَإِذَا الْمُشْرِكُونَ، فَقَالَ: "مَنْ لِلْقَوْمِ". فَقَالَ طَلْحَةُ: أَنَا. قَالَ: "كَمَا أَنْتَ". فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: أَنَا. فَقَالَ: "أَنْتَ". فَقَاتَلَ حَتَّى قُتِلَ، ثُمَّ لَمْ يَزَلْ يَقُولُ ذَلِكَ وَيَخْرُجُ إِلَيْهِمْ رَجُلٌ مِنَ الْأَنْصَارِ فَيُقَاتِلُ قِتَالَ مَنْ قَبْلَهُ حَتَّى يُقْتَلَ، حَتَّى بَقِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَطَلْحَةُ بْنُ عُبَيْدِ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لِلْقَوْمِ". فَقَالَ طَلْحَةُ: أَنَا. فَقَاتَلَ طَلْحَةُ قِتَالَ الْأَحَدَ عَشَرَ حَتَّى ضُرِبَتْ يَدُهُ فَقُطِعَتْ أَصَابِعُهُ، فَقَالَ: حَسِّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ قُلْتَ: بِسْمِ اللَّهِ، لَرَفَعَتْكَ الْمَلَائِكَةُ وَالنَّاسُ يَنْظُرُونَ". ثُمَّ رَدَّ اللَّهُ الْمُشْرِكِينَ. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉഹ്ദ് യുദ്ധത്തിൽ ജനങ്ങളെല്ലാം പിന്തിരിഞ്ഞപ്പോൾ റസൂൽ(സ) പന്ത്രണ്ട് അൻസാരികളോട് കൂടെ ഒരു ഭാഗത്ത് നിൽക്കുകയായിരുന്നു. അവരിൽ ത്വൽഹതുബ്നു അബ്ദില്ല(റ)വുമുണ്ടായിരുന്നു. അന്നേരം മുശ്രിക്കുകൾ അവരെ ആക്രമിക്കാൻ വന്നു. അപ്പോൾ നബി(സ) തിരിഞ്ഞു നിന്നുകൊണ്ട് ചോദിച്ചു: "അവരെ ആര് നേരിടും?" ത്വൽഹ(റ) പറഞ്ഞു: ഞാൻ നേരിടും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവിടത്തെന്നെ നിൽക്ക്." അപ്പോൾ അൻസാരികളിലൊരാൾ പറഞ്ഞു: ഞാൻ നേരിടാം. നബി(സ) പറഞ്ഞു: "നീ നേരിടൂ." അങ്ങനെ അദ്ദേഹം അവരോട് യുദ്ധം ചെയ്യുകയും കൊല്ലപ്പെടുകയും ചെയ്തു. പിന്നെ നബി(സ) തിരിഞ്ഞു നോക്കുമ്പോൾ മുശ്രികുകൾ അതാ വരുന്നു. നബി(സ) ചോദിച്ചു: "അവരോടേറ്റുമുട്ടാനാരുണ്ട്?" ത്വൽഹ(റ) പറഞ്ഞു: ഞാൻ. നബി(സ) പറഞ്ഞു: "നീ അവിടത്തെന്നെ നിൽക്ക്." അപ്പോൾ ഒരു അൻസാരി പറഞ്ഞു: ഞാൻ നേരിടാം. നബി(സ) പറഞ്ഞു: "നീ നേരിടൂ." അങ്ങനെ അദ്ദേഹവും ശത്രുക്കളോടേറ്റുമുട്ടി വധിക്കപ്പെട്ടു. ശേഷം റസൂൽ(സ) ഇപ്രകാരം വീണ്ടും വീണ്ടും പറയുകയും അപ്പോഴെല്ലാം ഓരോ അൻസാരികൾ വീതം ശത്രുക്കളിലേക്ക് ചെന്ന് ആദ്യത്തവരെപ്പോലെ പോരാടുകയും വധിക്കപ്പെടുകയും ചെയ്തുകൊണ്ടേയിരുന്നു. അവസാനം നബി(സ)യും ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)വും മാത്രം ബാക്കിയായി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അവരെ ആര് നേരിടും?" ത്വൽഹ(റ) പറഞ്ഞു: ഞാൻ. അങ്ങനെ ത്വൽഹ(റ) പതിനൊന്ന് പേരുടെ യുദ്ധം ഒറ്റക്ക് ചെയ്തു. അദ്ദേഹത്തിന്റെ കയ്യിന് വെട്ടേറ്റ് വിരലുകൾ മുറിഞ്ഞുപോയി. അപ്പോൾ അദ്ദേഹം ''ഹസ്സി'' (വേദനിക്കുമ്പോൾ ഉണ്ടാക്കുന്ന ശബ്ദം) എന്ന് പറഞ്ഞു: ഉടനെ നബി(സ) പറഞ്ഞു: "നീ ബിസ്മില്ലാഹി എന്നു പറയുകയായിരുന്നെങ്കിൽ ജനങ്ങൾ നോക്കിനിൽക്കെ മലക്കുകൾ നിന്നെ ഉയർത്തുമായിരുന്നു." പിന്നെ അല്ലാഹു മുശ്രിക്കുകളെ അകറ്റി. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 996, 997, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 448, 'عَنِ ابْنِ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَيْنٌ مِنَ الْمُشْرِكِينَ وَهُوَ فِي سَفَرٍ، فَجَلَسَ عِنْدَ أَصْحَابِهِ ثُمَّ انْسَلَّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اطْلُبُوهُ فَاقْتُلُوهُ". قَالَ: فَسَبَقْتُهُمْ إِلَيْهِ فَقَتَلْتُهُ وَأَخَذْتُ سَلَبَهُ، فَنَفَّلَنِي إِيَّاهُ. (خ,د,جه)', 'സലമതുബ്നുൽ അക്വഅ്(റ): ഒരു യാത്രയിലായിരിക്കെ മുശ്രിക്കുകളുടെ ഒരു ചാരൻ നബി(സ)യുടെ അടുത്ത് വന്നു. അയാൾ സ്വഹാബികളുടെ അടുത്ത് വന്നിരുന്നു. പിന്നെ മെല്ലെ അവിടന്ന് സ്ഥലം വിട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവനെ തേടിപ്പിടിച്ച് വധിക്കുക." സലമത്(റ) പറയുന്നു: ഞാൻ മറ്റുള്ളവരേക്കാൾ മുമ്പിലെത്തുകയും അയാളെ വധിക്കുകയും അയാളുടെ ആയുധങ്ങൾ എടുക്കുകയും ചെയ്തു. അങ്ങനെ നബി(സ) അവ എനിക്ക് നൽകി. (ബു,ദ,ജ)', 'ابْنِ سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 997, 997, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 449, 'عَنْ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَوَازِنَ، قَالَ: فَبَيْنَمَا نَحْنُ نَتَضَحَّى وَعَامَّتُنَا مُشَاةٌ وَفِينَا ضَعَفَةٌ إِذْ جَاءَ رَجُلٌ عَلَى جَمَلٍ أَحْمَرَ، فَانْتَزَعَ طَلَقًا مِنْ حَقْوِ الْبَعِيرِ فَقَيَّدَ بِهِ جَمَلَهُ، ثُمَّ جَاءَ يَتَغَدَّى مَعَ الْقَوْمِ، فَلَمَّا رَأَى ضَعْفَتَهُمْ وَرِقَّةَ ظَهْرِهِمْ خَرَجَ يَعْدُو إِلَى جَمَلِهِ، فَأَطْلَقَهُ ثُمَّ أَنَاخَهُ فَقَعَدَ عَلَيْهِ، ثُمَّ خَرَجَ يَرْكُضُهُ، وَاتَّبَعَهُ رَجُلٌ مِنْ أَسْلَمَ عَلَى نَاقَةٍ وَرْقَاءَ هِيَ أَمْثَلُ ظَهْرِ الْقَوْمِ، قَالَ: فَخَرَجْتُ أَعْدُو، فَأَدْرَكْتُهُ وَرَأْسُ النَّاقَةِ عِنْدَ وَرِكِ الْجَمَلِ، وَكُنْتُ عِنْدَ وَرِكِ النَّاقَةِ، ثُمَّ تَقَدَّمْتُ حَتَّى كُنْتُ عِنْدَ وَرِكِ الْجَمَلِ، ثُمَّ تَقَدَّمْتُ حَتَّى أَخَذْتُ بِخِطَامِ الْجَمَلِ فَأَنَخْتُهُ، فَلَمَّا وَضَعَ رُكْبَتَهُ بِالْأَرْضِ اخْتَرَطْتُ سَيْفِي فَأَضْرِبُ رَأْسَهُ، فَنَدَرَ، فَجِئْتُ بِرَاحِلَتِهِ وَمَا عَلَيْهَا، أَقُودُهَا فَاسْتَقْبَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّاسِ مُقْبِلًا، فَقَالَ: "مَنْ قَتَلَ الرَّجُلَ". فَقَالُوا: ابْنُ الْأَكْوَعِ. قَالَ: "لَهُ سَلَبُهُ أَجْمَعُ". (م,د)', 'സലമത്(റ): ഹവാസിൻ ഗോത്രവുമായി നബി(സ)യുടെ കൂടെ ഞാൻ യുദ്ധം ചെയ്തു. ഞങ്ങളുടെ കൂടെ അധികവും നടക്കുന്നവരായിരുന്നു, കൂട്ടത്തിൽ ബലഹീനരായ ആളുകളുമുണ്ടായിരുന്നു. ഞങ്ങൾ ഉച്ച ഭക്ഷണം കഴിക്കുമ്പോൾ ഒരു ചുവന്ന ഒട്ടകപ്പുറത്ത് ഒരാൾ വന്നു. ഒട്ടകത്തിന്റെ പിന്നിലെ പാത്രത്തിൽ നിന്ന് അയാൾ ഒരു കയർ ഊരിയെടുത്ത് തന്റെ ഒട്ടകത്തിന്മേൽ കെട്ടി. പിന്നെ ജനങ്ങളോട് കൂടെ ഭക്ഷണം കഴിക്കാൻ വന്നു. അവരുടെ ബലഹീനതയും അവരുടെ മുതുകിന്റെ നൈർമല്യവും കണ്ടപ്പോൾ അയാൾ വേഗം തന്റെ ഒട്ടകത്തിന്റെയടുത്തേക്ക് പോയി. അതിനെ കെട്ടഴിക്കുകയും മുട്ടുകുത്തിക്കുകയും എന്നിട്ട് അതിന്റെ മേൽ ഇരുക്കുകയും ചെയ്തു. ശേഷം അതിനെ ചാടിച്ചു കൊണ്ട് പുറപ്പെട്ടു. അപ്പോൾ അയാളെ അസ്ലം ഗോത്രത്തിൽ പെട്ട ഒരാൾ തവിട്ടുനിറത്തിലുള്ള ഒരു പെൺഒട്ടകത്തിന്മേൽ കയറി പിന്തുടർന്നു. അവരുടെയടുത്തുള്ള ഏറ്റവും നല്ല ഒട്ടകമായിരുന്നു അത്. സലമത്(റ) പറയുന്നു: ഞാനും ഓടിക്കൊണ്ട് പുറപ്പെട്ടു. അങ്ങനെ അവന്റെ അടുത്തെത്തി. അപ്പോൾ പെൺഒട്ടകത്തിന്റെ തല ആദ്യത്തെ ഒട്ടകത്തിന്റെ ഊരയുടെ അടുത്തായിരുന്നു. ഞാൻ പെൺഒട്ടകത്തിന്റെ ഊരയുടെ ഭാഗത്തായിരുന്നു. ഞാൻ വീണ്ടും മുന്നോട്ട് പോയി ആദ്യത്തെ ഒട്ടകത്തിന്റെ ഊരയുടെ ഭാഗത്തെത്തി. പിന്നെയും മുന്നോട്ടോടി ഒട്ടകത്തിന്റെ മൂക്കയറിൽ പിടിച്ചു അതിനെ മുട്ടുകുത്തിച്ചു. അത് ഭൂമിയിൽ മുട്ടുകുത്തിയ ഉടനെ ഞാനെന്റെ വാളൂരി അയാളുടെ തലവെട്ടി. അവൻ താഴേക്ക് വീണു. എന്നിട്ട് ഞാനവന്റെ ഒട്ടകത്തെ അതിന്മേലുള്ള സാധനങ്ങളോടുകൂടെ തെളിച്ചുകൊണ്ടുവന്നു. നബി(സ) ജനങ്ങളോടൊന്നിച്ച് എന്നെ സ്വീകരിച്ചു. അവിടുന്ന് ചോദിച്ചു: "ആരാണ് അയാളെ വധിച്ചത്?" അവർ പറഞ്ഞു: ഇബ്നുൽ അക്വഅ്(റ). നബി(സ) പറഞ്ഞു: "അയാളുടെ മുഴുവൻ സാധനങ്ങളും അദ്ദേഹത്തിനാണ്." (മു,ദ)', 'سَلَمَةَ', 'സലമത്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 997, 998, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 450, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَالزُّبَيْرُ وَالْمِقْدَادُ، فَقَالَ: "انْطَلِقُوا حَتَّى تَأْتُوا رَوْضَةَ خَاخٍ، فَإِنَّ بِهَا ظَعِينَةً مَعَهَا كِتَابٌ فَخُذُوهُ مِنْهَا". فَانْطَلَقْنَا تَتَعَادَى بِنَا خَيْلُنَا حَتَّى أَتَيْنَا الرَّوْضَةَ، فَإِذَا نَحْنُ بِالظَّعِينَةِ، فَقُلْنَا: هَلُمِّي الْكِتَابَ، قَالَتْ: مَا عِنْدِي مِنْ كِتَابٍ. فَقُلْتُ: لَتُخْرِجِنَّ الْكِتَابَ، أَوْ لَنُلْقِيَنَّ الثِّيَابَ. فَأَخْرَجَتْهُ مِنْ عِقَاصِهَا، فَأَتَيْنَا بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا هُوَ مِنْ حَاطِبِ بْنِ أَبِي بَلْتَعَةَ إِلَى نَاسٍ مِنَ الْمُشْرِكِينَ، يُخْبِرُهُمْ بِبَعْضِ أَمْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَا هَذَا يَا حَاطِبُ". فَقَالَ: يَا رَسُولَ اللَّهِ، لَا تَعْجَلْ عَلَيَّ، فَإِنِّي كُنْتُ امْرَأً مُلْصَقًا فِي قُرَيْشٍ وَلَمْ أَكُنْ مِنْ أَنْفُسِهَا، وَإِنَّ قُرَيْشًا لَهُمْ بِهَا قَرَابَاتٌ يَحْمُونَ بِهَا أَهْلِيهِمْ بِمَكَّةَ، فَأَحْبَبْتُ إِذْ فَاتَنِي ذَلِكَ أَنْ أَتَّخِذَ فِيهِمْ يَدًا يَحْمُونَ قَرَابَتِي بِهَا، وَاللَّهِ يَا رَسُولَ اللَّهِ مَا كَانَ بِي مِنْ كُفْرٍ وَلَا ارْتِدَادٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صَدَقَكُمْ". فَقَالَ عُمَرُ: دَعْنِي أَضْرِبُ عُنُقَ هَذَا الْمُنَافِقِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ شَهِدَ بَدْرًا، وَمَا يُدْرِيكَ لَعَلَّ اللَّهَ اطَّلَعَ عَلَى أَهْلِ بَدْرٍ، فَقَالَ: اعْمَلُوا مَا شِئْتُمْ، فَقَدْ غَفَرْتُ لَكُمْ". وَفِي رِوَايَةٍ: قَالَ: انْطَلَقَ حَاطِبٌ، فَكَتَبَ إِلَى أَهْلِ مَكَّةَ: أَنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ سَارَ إِلَيْكُمْ، وَقَالَ فِيهِ: قَالَتْ: مَا مَعِي كِتَابٌ، فَانْتَحَيْنَاهَا فَمَا وَجَدْنَا مَعَهَا كِتَابًا، فَقَالَ عَلِيٌّ: وَالَّذِي يُحْلَفُ بِهِ لَأَقْتُلَنَّكِ أَوْ لَتُخْرِجِنَّ الْكِتَابَ...... وَسَاقَ الْحَدِيثَ. (ق,د,ت)', 'അലി(റ): എന്നെയും സുബൈർ(റ) മിഖ്ദാദ്(റ) എന്നിവരെയും പറഞ്ഞയച്ചുകൊണ്ട് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ''ഖാഖ്'' തോട്ടം വരെ ചെല്ലുക. അവിടെ യാത്ര ചെയ്യുന്ന ഒരു സ്ത്രീയുണ്ട്. അവളുടെ കയ്യിൽ ഒരു എഴുത്തുമുണ്ട്. അത് അവളിൽ നിന്നും വാങ്ങിക്കൊണ്ടുവരിക." ഞങ്ങൾ ആ തോട്ടത്തിലെത്തുംവരെ കുതിരയെക്കൊണ്ട് പരസ്പരം മത്സരിച്ച് പോയി. അങ്ങനെ ഞങ്ങൾ ആ സ്ത്രീയെ കണ്ടു. അവളോട് ഞങ്ങൾ പറഞ്ഞു: ആ എഴുത്ത് ഞങ്ങൾക്ക് തരണം. അവൾ പറഞ്ഞു: എന്റെയടുത്ത് ഒരു എഴുത്തുമില്ലല്ലോ. ഞാൻ പറഞ്ഞു: കത്ത് പുറത്തെടുക്ക്. അല്ലെങ്കിൽ നിന്റെ വസ്ത്രമുരിഞ്ഞ് കളയും. അപ്പോൾ തന്റെ മുടിക്കുത്തിൽ നിന്നും അവൾ കത്ത് പുറത്തെടുത്തു. ഞങ്ങളതുമായി നബി(സ)യുടെ അടുത്തേക്ക് ചെന്നു. മുശ്രിക്കുകൾക്ക് നബി(സ)യെക്കുറിച്ചുള്ള ചില കാര്യങ്ങൾ അറിയിക്കാൻ വേണ്ടി ഹാത്വിബുബ്നു അബീബൽതഅ(റ) എഴുതിയതായിരുന്നു ആ കത്ത്. നബി(സ) ചോദിച്ചു: "ഹാത്വിബ്, എന്താണിത്?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കെതിരെ പെട്ടെന്ന് നടപടിയെടുക്കരുത്, ഞാൻ ഖുറൈശികളിൽ പെട്ടവനല്ലെങ്കിലും അവരോട് സന്ധിചെയ്ത് ജീവിച്ചിരുന്നവനാണ്. (മുഹാജിറുകളായ) ഖുറൈശികൾ അവരുമായി കുടുംബബന്ധമുള്ളവരാണ്. അതുമുഖേന മക്കയിലുള്ള തങ്ങളുടെ കുടുംബങ്ങളെ അവർ സംരക്ഷിക്കുന്നുണ്ട്. എനിക്ക് അവരുമായുള്ള സന്ധി ഇല്ലാതായപ്പോൾ, എന്റെ കുടുംബത്തെ സംരക്ഷിക്കാൻ വേണ്ടി അവർക്ക് ഒരു സഹായം ചെയ്യാൻ ഞാനുദ്ദേശിച്ചു. അല്ലാഹു തന്നെ സത്യം, റസൂലേ, എന്റടുത്ത് നിന്ന് കുഫ്റോ രിദ്ദതോ (സത്യനിഷേധമോ, മതം തൃജിക്കലോ) ഉണ്ടായിട്ടില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം നിങ്ങളോട് പറഞ്ഞത് സത്യമാണ്." അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഈ കപടവിശ്വാസിയുടെ പിരടി വെട്ടാൻ എനിക്ക് അനുമതി തരിക. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം ബദ്റിൽ പങ്കെടുത്തയാളാണ്. ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്തവരെ അല്ലാഹു പരിഗണിച്ചത് താങ്കൾക്കറിയില്ലേ, എന്നിട്ട് അല്ലാഹു പറഞ്ഞു: നിങ്ങൾ ആഗ്രഹിക്കുന്നത് ചെയ്തുകൊള്ളുക, നിശ്ചയം നിങ്ങൾക്ക് ഞാൻ പൊറുത്തുതന്നിയിരിക്കുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=450), 1, 'وَفِي رِوَايَةٍ: قَالَ: انْطَلَقَ حَاطِبٌ، فَكَتَبَ إِلَى أَهْلِ مَكَّةَ: أَنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ سَارَ إِلَيْكُمْ، وَقَالَ فِيهِ: قَالَتْ: مَا مَعِي كِتَابٌ، فَانْتَحَيْنَاهَا فَمَا وَجَدْنَا مَعَهَا كِتَابًا، فَقَالَ عَلِيٌّ: وَالَّذِي يُحْلَفُ بِهِ لَأَقْتُلَنَّكِ أَوْ لَتُخْرِجِنَّ الْكِتَابَ...... وَسَاقَ الْحَدِيثَ. (ق,د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: നിവേദകൻ പറയുന്നു: ഹാത്വിബ്(റ) പോയി മക്കക്കാർക്ക് ഇപ്രകാരമെഴുതി: മുഹമ്മദ്(സ) നിങ്ങളുടെയടുത്തേക്ക് പുറപ്പെട്ടിട്ടുണ്ട്. ഈ ഹദീസിൽ നിവേദകൻ പറയുന്നു: ആ സ്ത്രീ പറഞ്ഞു: എന്റെയടുത്ത് ഒരു കത്തുമില്ല. അപ്പോൾ ഞങ്ങളവളെ സസൂക്ഷമം പരിശേധിച്ചു. പക്ഷേ, ഞങ്ങൾ ഒരു കത്തും കണ്ടില്ല. അപ്പോൾ അലി(റ) പറഞ്ഞു: ആരെക്കൊണ്ടാണോ സത്യം ചെയ്യപ്പെടുക, അവൻ തന്നെ സത്യം, നിന്നെ ഞാൻ കൊല്ലും. അല്ലെങ്കിൽ കത്ത് പുറത്തെടുക്ക്........... ശേഷം ബാക്കി ഹദീസ് പറഞ്ഞു. (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 451, 'عَنْ فُرَاتِ بْنِ حَيَّانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلِهِ، وَكَانَ عَيْنًا لِأَبِي سُفْيَانَ، وَكَانَ حَلِيفًا لِرَجُلٍ مِنَ الْأَنْصَارِ، فَمَرَّ بِحَلْقَةٍ مِنَ الْأَنْصَارِ فَقَالَ: إِنِّي مُسْلِمٌ، فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللَّهِ، إِنَّهُ يَقُولُ إِنِّي مُسْلِمٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْكُمْ رِجَالًا نَكِلُهُمْ إِلَى إِيمَانِهِمْ، مِنْهُمْ فُرَاتُ بْنُ حَيَّانَ". (خ)', 'ഫുറാതുബ്നു ഹയ്യാൻ(റ): അദ്ദേഹത്തെ നബി(സ) വധിക്കാൻ കൽപിച്ചു. അദ്ദേഹം അബൂസുഫ്യാന്റെ ചാരനായിരുന്നു. അദ്ദേഹം അൻസാറുകളിൽപെട്ട ഒരാളുമായി സന്ധിയിലേർപെട്ടിരുന്നു. അങ്ങനെ അദ്ദേഹം അൻസാറുകളുടെ ഒരു സംഘത്തിനടുത്തുകൂടെ നടന്നു പോകുമ്പോൾ പറഞ്ഞു: ഞാൻ മുസ്ലിമാണ്. അപ്പോൾ ഒരു അൻസാരി പറഞ്ഞു: റസൂലേ, അവൻ ഞാൻ മുസ്ലിമാണെന്നു പറയുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "വിശ്വാസകാര്യത്തിൽ അവരെത്തന്നെ നാം ഭരമേൽപിക്കുന്ന ചിലയാളുകൾ നിങ്ങളുടെ കൂട്ടത്തിലുണ്ട്. നിശ്ചയം ഫുറാതുബ്നു ഹയ്യാൻ അക്കൂട്ടത്തിൽപെട്ട ആളാണ്." (ബു)', 'فُرَاتِ بْنِ حَيَّانَ', 'ഫുറാതുബ്നു ഹയ്യാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 999, 999, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 452, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعَفُّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "വധിക്കുന്നതിൽ ഏറ്റവും മാന്യത കാണിക്കുന്നവർ വിശ്വാസമുടയവരാണ്." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 999, 999, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 453, 'عَنِ الْهَيَّاجِ بْنِ عِمْرَانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عِمْرَانَ أَبَقَ لَهُ غُلَامٌ فَجَعَلَ لِلَّهِ عَلَيْهِ: لَئِنْ قَدَرَ عَلَيْهِ لَيَقْطَعَنَّ يَدَهُ. فَأَرْسَلَنِي لِأَسْأَلَ لَهُ، فَأَتَيْتُ سَمُرَةَ بْنَ جُنْدُبٍ فَسَأَلْتُهُ، فَقَالَ: كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّنَا عَلَى الصَّدَقَةِ، وَيَنْهَانَا عَنِ الْمُثْلَةِ. فَأَتَيْتُ عِمْرَانَ بْنَ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُ فَسَأَلْتُهُ، فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّنَا عَلَى الصَّدَقَةِ، وَيَنْهَانَا عَنِ الْمُثْلَةِ. (د)', 'ഹയ്യാജുബ്നു ഇംറാൻ(റ): ഇംറാന്റെ ഒരു അടിമ ഓടിപ്പോയി. അപ്പോൾ അദ്ദേഹം അല്ലാഹുവിൽ ഇപ്രകാരം പ്രതിജ്ഞ ചെയ്തു. അവനെപ്പിടിക്കാൻ സാധിച്ചാൽ അവന്റെ കൈ ഞാൻ ഛേദിച്ചുകളയും. അതിനെപ്പറ്റി ചോദിക്കാൻ അദ്ദേഹം എന്നെ പറഞ്ഞയച്ചു. അങ്ങനെ ഞാൻ സമുറതുബ്നു ജുൻദുബ്(റ)വിന്റെയടുക്കലേക്ക് ചെന്നു. അദ്ദേഹത്തോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഞങ്ങളെ ദാനം ചെയ്യാൻ പ്രേരിപ്പിക്കുകയും അംഗഛേദം നടത്തുന്നതിൽ നിന്ന് വിലക്കുകയും ചെയ്യുമായിരുന്നു. പിന്നെ ഞാൻ ഇംറാനുബ്നു ഹുസൈൻ(റ)വിന്റെ അടുത്തുചെന്ന് അതിനെക്കുറിച്ച് ചോദിച്ചു: അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഞങ്ങളെ ദാനം ചെയ്യാൻ പ്രേരിപ്പിക്കുകയും അംഗഛേദം നടത്തുന്നതിൽ നിന്ന് വിലക്കുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'الْهَيَّاجِ بْنِ عِمْرَانَ', 'ഹയ്യാജുബ്നു ഇംറാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 999, 1000, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 454, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – أَنَّهَا قَالَتْ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَلَ بَدْرٍ، فَلَمَّا كَانَ بِحَرَّةِ الْوَبَرَةِ أَدْرَكَهُ رَجُلٌ، قَدْ كَانَ يُذْكَرُ مِنْهُ جُرْأَةٌ وَنَجْدَةٌ، فَفَرِحَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَأَوْهُ، فَلَمَّا أَدْرَكَهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جِئْتُ لِأَتَّبِعَكَ وَأُصِيبَ مَعَكَ، قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ". قَالَ: لَا، قَالَ: "فَارْجِعْ، فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ". قَالَتْ: ثُمَّ مَضَى، حَتَّى إِذَا كُنَّا بِالشَّجَرَةِ أَدْرَكَهُ الرَّجُلُ، فَقَالَ لَهُ كَمَا قَالَ أَوَّلَ مَرَّةٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا قَالَ أَوَّلَ مَرَّةٍ، قَالَ: "فَارْجِعْ، فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ". قَالَتْ: ثُمَّ رَجَعَ فَأَدْرَكَهُ بِالْبَيْدَاءِ، فَقَالَ لَهُ كَمَا قَالَ أَوَّلَ مَرَّةٍ: "تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ". قَالَ: نَعَمْ، فَقَالَ [لَهُ] رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَانْطَلِقْ". (م)', 'ആഇശ(റ): നബി(സ) ബദ്റിലേക്ക് പുറപ്പെട്ടു. ''ഹർറതുൽ വബറ'' എന്ന സ്ഥലത്തെത്തിയപ്പോൾ ധീരതക്കും ശൂരതക്കും പേരുകേട്ട ഒരാൾ അങ്ങോട്ട് വന്നു. അദ്ദേഹത്തെ കണ്ടപ്പോൾ സ്വഹാബികൾ സന്തോഷിച്ചു. അയാൾ അവിടെയെത്തിയപ്പോൾ നബി(സ)യോട് അയാൾ പറഞ്ഞു: താങ്കളെ പിന്തുടർന്ന് (യുദ്ധം ചെയ്ത്) വല്ല വിഹിതവും നേടാനാണ് ഞാൻ വന്നിരിക്കുന്നത്. റസൂൽ(സ) ചോദിച്ചു: "നീ അല്ലാഹുവിലും അവന്റെ ദൂതരിലും വിശ്വസിക്കുന്നുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ തിരിച്ചു പോകൂ, ബഹുദൈവവിശ്വാസിയോട് ഞാൻ സഹായം തേടുകയില്ല." ആഇശ(റ) പറയുന്നു: പിന്നെയും അവിടന്ന് പോയി. പിന്നെ ഞങ്ങൾ ''ശജറ'' എന്ന സ്ഥലത്തെത്തിയപ്പോൾ അയാൾ വീണ്ടും വന്നു. അയാൾ ആദ്യം പറഞ്ഞത് പോലെത്തന്നെ വീണ്ടും പറഞ്ഞു. ആദ്യം ചോദിച്ചതുപോലെ അയാളോട് വീണ്ടും റസൂൽ(സ) ചോദിച്ചു. ശേഷം പറഞ്ഞു: "എങ്കിൽ തിരിച്ചു പോകൂ, ബഹുദൈവവിശ്വാസിയോട് ഞാൻ സഹായം തേടുകയില്ല." ആഇശ(റ) പറയുന്നു. പിന്നെ അയാൾ മടങ്ങുകയും ''ബൈദാഅ്'' എന്ന സ്ഥലത്തു വെച്ച് തിരുമേനി(സ)യെ കണ്ടുമുട്ടുകയും ചെയ്തു. അപ്പോഴും ആദ്യം ചോദിച്ച പ്രകാരം അവിടുന്ന് അയാളോട് ചോദിച്ചു: "നീ അല്ലാഹുവിലും അവന്റെ റസൂലിലും വിശ്വസിക്കുന്നുണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ, അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ വരിക." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَهُ', null, 1000, 1000, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 455, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهُ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّا لَا نَسْتَعِينُ بِمُشْرِكٍ". (م,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം നാം ബഹുദൈവവിശ്വാസിയോട് സഹായം തേടുകയില്ല." (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 1000, 1001, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 456, 'عَنْ عَلِيٍّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ كِسْرَى أَهْدَى لَهُ فَقَبِلَ، وَأَنَّ الْمُلُوكَ أَهْدَوْا إِلَيْهِ فَقَبِلَ مِنْهُمْ. (ت)', 'അലി(റ): നബി(സ)യെക്കുറിച്ച് നിവേദനം ചെയ്യുന്നു: കിസ്റാ രാജാവ് നബി(സ)ക്ക് ഹദ്യ (സമ്മാനം) നൽകി. നബി(സ) അത് സ്വീകരിച്ചു. രാജാക്കന്മാർ നബി(സ)ക്ക് ഹദ്യകൾ നൽകുകയും അവരിൽ നിന്ന് തിരുമേനി(സ) അവ സ്വീകരിക്കുകയും ചെയ്തു. (തു)', 'عَلِيٍّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1001, 1001, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 457, 'عَنْ عِيَاضِ بْنِ حِمَارٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ أَهْدَى لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَدِيَّةً لَهُ، أَوْ نَاقَةً. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَسْلَمْتَ". قَالَ: لَا. قَالَ: "فَإِنِّي نُهِيتُ عَنْ زَبْدِ الْمُشْرِكِينَ". (د,ت)', 'ഇയാളുബ്നു ഹിമാർ(റ): അദ്ദേഹം നബി(സ)ക്ക് എന്തോ ഉപഹാരമോ ഒരൊട്ടകമോ സമ്മാനമായി നൽകി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നീ മുസ്ലിമായിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "ബഹുദൈവവിശ്വാസികളുടെ പാരിതോഷികം എനിക്ക് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു." (ദ,തു)', 'عِيَاضِ بْنِ حِمَارٍ', 'ഇയാളുബ്നു ഹിമാർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 1001, 1001, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 458, 'عَنْ هُلْبِ الطَّائِي رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ طَعَامِ النَّصَارَى، فَقَالَ: "لَا يَخْتَلِجَنَّ فِي صَدْرِكَ طَعَامٌ ضَارَعْتَ فِيهِ نَصْرَانِيَّةً". (د,ت,جه)', 'ഹുൽബുത്ത്വാഈ(റ): ക്രൈസ്തവരുടെ ഭക്ഷണത്തെക്കുറിച്ച് ഞാൻ നബി(സ)യോട് ചോദിച്ചു. അന്നേരം അവിടുന്ന് പറഞ്ഞു: "ക്രൈസ്തവതയോട് താൻ സദൃശ്യമുള്ളവനായോ എന്ന സംശയം, ഒരു ഭക്ഷണവും നിന്റെ ഹൃദയത്തിൽ വരുത്താതിരിക്കട്ടെ." (ആ ഭക്ഷണം കഴിക്കരുത്.) (ദ,തു,ജ)', 'هُلْبِ الطَّائِي', 'ഹുൽബുത്ത്വാഈ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 1001, 1001, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 459, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قُدُورِ الْمَجُوسِ، فَقَالَ: "أَنْقُوهَا غَسْلًا وَاطْبُخُوا فِيهَا". وَنَهَى عَنْ كُلِّ سَبُعٍ وَذِي نَابٍ. وَفِي رِوَايَةٍ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ كِتَابٍ، نَأْكُلُ فِي آنِيَتِهِمْ؟ قَالَ: "إِنْ وَجَدْتُمْ غَيْرَ آنِيَتِهِمْ فَلَا تَأْكُلُوا فِيهَا، فَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا وَكُلُوا فِيهَا". (ق,ت)', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ): മജൂസി(അഗ്നിയാരാധകർ)കളുടെ പാത്രങ്ങളുപയോഗിക്കുന്നതിനെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അത് കഴുകി ശുദ്ധിയാക്കുക, പിന്നെ അതിൽ പാചകം ചെയ്യുക." പിടിമൃഗങ്ങളെയും തേറ്റപ്പല്ലുകളുള്ള ജീവികളെയും ഭക്ഷിക്കുന്നത് തിരുമേനി(സ) നിരോധിച്ചു. മറ്റൊരു നിവേദനത്തിൽ പറയുന്നു: ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ വേദക്കാരുടെ നാട്ടിലാണ് താമസിക്കുന്നത്. ഞങ്ങളവരുടെ പാത്രത്തിൽ ഭക്ഷിക്കട്ടെയോ? തിരുമേനി(സ) പറഞ്ഞു: "അവരുടേതല്ലാത്ത പാത്രം കിട്ടുകയാണെങ്കിൽ അവരുടേതിൽ ഭക്ഷിക്കരുത്. ഇനി നിങ്ങൾക്ക് മറ്റു പാത്രങ്ങളൊന്നും ലഭിച്ചില്ലെങ്കിൽ അത് കഴുകി അതിൽ ഭക്ഷിക്കുക." (ബു,മു,തു)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 1001, 1002, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=459), 1, 'وَفِي رِوَايَةٍ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ كِتَابٍ، نَأْكُلُ فِي آنِيَتِهِمْ؟ قَالَ: "إِنْ وَجَدْتُمْ غَيْرَ آنِيَتِهِمْ فَلَا تَأْكُلُوا فِيهَا، فَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا وَكُلُوا فِيهَا". (ق,ت)', 'മറ്റൊരു നിവേദനത്തിൽ പറയുന്നു: ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ വേദക്കാരുടെ നാട്ടിലാണ് താമസിക്കുന്നത്. ഞങ്ങളവരുടെ പാത്രത്തിൽ ഭക്ഷിക്കട്ടെയോ? തിരുമേനി(സ) പറഞ്ഞു: "അവരുടേതല്ലാത്ത പാത്രം കിട്ടുകയാണെങ്കിൽ അവരുടേതിൽ ഭക്ഷിക്കരുത്. ഇനി നിങ്ങൾക്ക് മറ്റു പാത്രങ്ങളൊന്നും ലഭിച്ചില്ലെങ്കിൽ അത് കഴുകി അതിൽ ഭക്ഷിക്കുക." (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 460, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهُ فَقُلْتُ: يَا رَسُولَ اللَّهِ، قُدُورُ الْمُشْرِكِينَ نَطْبُخُ فِيهَا؟ قَالَ: "لَا تَطْبُخُوا فِيهَا". قُلْتُ: فَإِنِ احْتَجْنَا إِلَيْهَا، فَلَمْ نَجِدْ مِنْهَا بُدًّا؟ قَالَ: "فَارْحَضُوهَا رَحْضًا حَسَنًا، ثُمَّ اطْبُخُوا وَكُلُوا". (خ,د,ت,جه)', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മുശ്രിക്കുകളുടെ പാത്രങ്ങളിൽ ഞങ്ങൾ പാചകം ചെയ്യട്ടെയോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അതിൽ പാചകം ചെയ്യരുത്." ഞാൻ ചോദിച്ചു: ഞങ്ങൾക്കത് അത്യാവശ്യമായി വരികയും അതല്ലാതെ മറ്റൊന്നും ലഭിക്കാതെ വരികയും ചെയ്താലോ? നബി(സ) പറഞ്ഞു: "അവ നന്നായി കഴുകുകയും ശേഷം പാചകം ചെയ്യുകയും ഭക്ഷിക്കുകയും ചെയ്യുക." (ബു,ദ,തു,ജ)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 1002, 1002, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 461, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ أَهْلِ كِتَابٍ، فَنَطْبُخُ فِي قُدُورِهِمْ وَنَشْرَبُ فِي آنِيَتِهِمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ لَمْ تَجِدُوا غَيْرَهَا فَارْحَضُوهَا بِالْمَاءِ". ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ صَيْدٍ، فَكَيْفَ نَصْنَعُ، قَالَ: "إِذَا أَرْسَلْتَ كَلْبَكَ الْمُكَلَّبَ، وَذَكَرْتَ اسْمَ اللَّهِ، فَقَتَلَ فَكُلْ. وَإِنْ كَانَ غَيْرَ مُكَلَّبٍ فَذَكِّ وَكُلْ، وَإِذَا رَمَيْتَ بِسَهْمِكَ وَذَكَرْتَ اسْمَ اللَّهِ فَقَتَلَ فَكُلْ". (ت)', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ വേദക്കാരുടെ നാട്ടിലാണ് വസിക്കുന്നത്. അതിനാൽ ഞങ്ങൾ അവരുടെ പാത്രങ്ങളിൽ കുടിക്കുകയും ഭക്ഷിക്കുകയും ചെയ്യട്ടെയോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് അതല്ലാതെ കിട്ടുന്നില്ലെങ്കിൽ അതിനെ വെള്ളം കൊണ്ട് കഴുകുക." പിന്നെ അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ വേട്ടയുള്ള സ്ഥലത്താണ് താമസിക്കുന്നത്. ഞങ്ങളെന്താണ് ചെയ്യുക? നബി(സ) പറഞ്ഞു: "ബിസ്മി ചൊല്ലി നിന്റെ പരിശീലിപ്പിക്കപ്പെട്ട നായയെ നീ അയക്കുകയും അത് വേട്ടമൃഗത്തെ കൊല്ലുകയും ചെയ്താൽ നിനക്കത് ഭക്ഷിക്കാം. പരിശീലിക്കപ്പെടാത്ത നായയാണെങ്കിൽ നീ അറുത്ത് തിന്നുക. ബിസ്മി ചൊല്ലി നീ അമ്പെയ്യുകയും അതേറ്റ് വധിക്കപ്പെടുകയും ചെയ്തതിനെ നീ ഭക്ഷിക്കുക." (തു)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബതുൽ ഖുശനി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1002, 1002, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 462, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَبْدَءُوا الْيَهُودَ وَالنَّصَارَى بِالسَّلَامِ، وَإِذَا لَقِيتُمْ أَحَدَهُمْ فِي الطَّرِيقِ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِهِ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജൂതന്മാരോടും ക്രൈസ്തവരോടും നിങ്ങൾ അങ്ങോട്ട് സലാം പറയരുത്. അവരെയാരെയെങ്കിലും വഴിയിൽ വെച്ച് നിങ്ങൾ കണ്ടുമുട്ടിയാൽ ഏറ്റവും ഇടുങ്ങിയ ഭാഗത്തുകൂടെ സഞ്ചരിക്കാൻ അവരെ നിങ്ങൾ നിർബന്ധിതരാക്കുക." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 1002, 1002, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 463, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْيَهُودَ إِذَا سَلَّمَ عَلَيْكُمْ أَحَدُهُمْ فَإِنَّمَا يَقُولُ: السَّامُ عَلَيْكُمْ، فَقُلْ: عَلَيْكَ". (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒരു ജൂതൻ നിങ്ങളോട് സലാം പറയുകയാണെങ്കിൽ ഇപ്രകാരമാണ് പറയുക: ''അസ്സാമു അലൈകും'' (പെട്ടെന്നുള്ള മരണം നിന്റെ മേലുണ്ടാവട്ടെ), അപ്പോൾ ''വ അലൈക'' (നിന്റെ മേലിലും) എന്ന് മാത്രം മടക്കുക." (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 1002, 1003, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 464, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً إِلَى خَثْعَمٍ، فَاعْتَصَمَ نَاسٌ بِالسُّجُودِ، فَأَسْرَعَ فِيهِمُ الْقَتْلَ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ لَهُمْ بِنِصْفِ الْعَقْلِ، وَقَالَ: "أَنَا بَرِيءٌ مِنْ كُلِّ مُسْلِمٍ يُقِيمُ بَيْنَ أَظْهُرِ الْمُشْرِكِينَ". قَالُوا: يَا رَسُولَ اللَّهِ، وَلِمَ؟ قَالَ: "لَا تَرَاءَى نَارَاهُمَا". (د,ت,ن)', 'ജരീറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഖസ്അം ഗോത്രത്തിലേക്ക് ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അവിടെയെത്തിയപ്പോൾ കുറച്ചാളുകൾ പെട്ടെന്ന് സുജൂദിൽ വീണു അഭയം തേടി. അപ്പോൾ അവരെ പെട്ടെന്ന് വധിച്ചു. ഈ വാർത്ത നബി(സ)ക്കെത്തിയപ്പോൾ അവർക്ക് പകുതി നഷ്ടപരിഹാരം നൽകാൻ കൽപിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "മുശ്രിക്കുകളുടെയിടയിൽ ജീവിക്കുന്ന മുഴുവൻ മുസ്ലിമിൽ നിന്നും ഞാൻ മുക്തനാണ്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അതെന്തുകൊണ്ടാണ്? തിരുമേനി(സ) പറഞ്ഞു: "അവർ രണ്ടുകൂട്ടരുടെയും തീ പരസ്പരം കാണാൻ പാടില്ല." (ദ,തു,ന)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 1003, 1003, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 465, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَّا بَعْدُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَامَعَ الْمُشْرِكَ وَسَكَنَ مَعَهُ فَإِنَّهُ مِثْلُهُ". (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): മുഖവുരയ്ക്കു ശേഷം, റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ബഹുദൈവവിശ്വാസിയോട് കൂടിക്കലർന്ന് അവന്റെ കൂടെ താമസിച്ചാൽ ഇവനും അവനെപ്പോലെത്തന്നെയാണ്." (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1003, 1003, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 466, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ فِي بِضْعَ عَشْرَةَ مِائَةً مِنْ أَصْحَابِهِ، حَتَّى إِذَا كَانُوا بِذِي الْحُلَيْفَةِ قَلَّدَ الْهَدْيَ وَأَشْعَرَهُ وَأَحْرَمَ بِالْعُمْرَةِ، وَسَاقَ الْحَدِيثَ، قَالَ: وَسَارَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا كَانَ بِالثَّنِيَّةِ الَّتِي يَهْبِطُ عَلَيْهِمْ مِنْهَا بَرَكَتْ بِهِ رَاحِلَتُهُ، فَقَالَ النَّاسُ: حَلْ حَلْ، خَلَأَتِ الْقَصْوَاءُ، مَرَّتَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا خَلَأَتْ وَمَا ذَلِكَ لَهَا بِخُلُقٍ، وَلَكِنْ حَبَسَهَا حَابِسُ الْفِيلِ". ثُمَّ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَا يَسْأَلُونِي الْيَوْمَ خُطَّةً يُعَظِّمُونَ بِهَا حُرُمَاتِ اللَّهِ إِلَّا أَعْطَيْتُهُمْ إِيَّاهَا". ثُمَّ زَجَرَهَا فَوَثَبَتْ، فَعَدَلَ عَنْهُمْ حَتَّى نَزَلَ بِأَقْصَى الْحُدَيْبِيَةِ عَلَى ثَمَدٍ قَلِيلِ الْمَاءِ، فَجَاءَهُ بُدَيْلُ بْنُ وَرْقَاءَ الْخُزَاعِيُّ، ثُمَّ أَتَاهُ – يَعْنِي عُرْوَةَ بْنَ مَسْعُودٍ – فَجَعَلَ يُكَلِّمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكُلَّمَا كَلَّمَهُ أَخَذَ بِلِحْيَتِهِ، وَالْمُغِيرَةُ بْنُ شُعْبَةَ قَائِمٌ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ السَّيْفُ وَعَلَيْهِ الْمِغْفَرُ، فَضَرَبَ يَدَهُ بِنَعْلِ السَّيْفِ وَقَالَ: أَخِّرْ يَدَكَ عَنْ لِحْيَتِهِ، فَرَفَعَ عُرْوَةُ رَأْسَهُ فَقَالَ: مَنْ هَذَا؟ قَالُوا: الْمُغِيرَةُ بْنُ شُعْبَةَ، فَقَالَ: أَيْ غُدَرُ، أَوَلَسْتُ أَسْعَى فِي غَدْرَتِكَ؟ – وَكَانَ الْمُغِيرَةُ صَحِبَ قَوْمًا فِي الْجَاهِلِيَّةِ فَقَتَلَهُمْ وَأَخَذَ أَمْوَالَهُمْ، ثُمَّ جَاءَ فَأَسْلَمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا الْإِسْلَامُ فَقَدْ قَبِلْنَا، وَأَمَّا الْمَالُ فَإِنَّهُ مَالُ غَدْرٍ لَا حَاجَةَ لَنَا فِيهِ" – فَذَكَرَ الْحَدِيثَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اكْتُبْ: هَذَا مَا قَاضَى عَلَيْهِ مُحَمَّدٌ رَسُولُ اللَّهِ". وَقَصَّ الْخَبَرَ، فَقَالَ سُهَيْلٌ: وَعَلَى أَنَّهُ لَا يَأْتِيكَ مِنَّا رَجُلٌ وَإِنْ كَانَ عَلَى دِينِكَ إِلَّا رَدَدْتَهُ إِلَيْنَا، فَلَمَّا فَرَغَ مِنْ قَضِيَّةِ الْكِتَابِ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "قُومُوا فَانْحَرُوا، ثُمَّ احْلِقُوا". ثُمَّ جَاءَ نِسْوَةٌ مُؤْمِنَاتٌ مُهَاجِرَاتٌ، الْآيَةَ، فَنَهَاهُمُ اللَّهُ أَنْ يَرُدُّوهُنَّ، وَأَمَرَهُمْ أَنْ يَرُدُّوا الصَّدَاقَ، ثُمَّ رَجَعَ إِلَى الْمَدِينَةِ، فَجَاءَهُ أَبُو بَصِيرٍ – رَجُلٌ مِنْ قُرَيْشٍ، يَعْنِي – فَأَرْسَلُوا فِي طَلَبِهِ، فَدَفَعَهُ إِلَى الرَّجُلَيْنِ، فَخَرَجَا بِهِ حَتَّى إِذْ بَلَغَا ذَا الْحُلَيْفَةِ نَزَلُوا يَأْكُلُونَ مِنْ تَمْرٍ لَهُمْ، فَقَالَ أَبُو بَصِيرٍ لِأَحَدِ الرَّجُلَيْنِ: وَاللَّهِ إِنِّي لَأَرَى سَيْفَكَ هَذَا يَا فُلَانُ جَيِّدًا، فَاسْتَلَّهُ الْآخَرُ، فَقَالَ: أَجَلْ قَدْ جَرَّبْتُ بِهِ، فَقَالَ أَبُو بَصِيرٍ: أَرِنِي أَنْظُرْ إِلَيْهِ، فَأَمْكَنَهُ مِنْهُ، فَضَرَبَهُ حَتَّى بَرَدَ، وَفَرَّ الْآخَرُ حَتَّى أَتَى الْمَدِينَةَ، فَدَخَلَ الْمَسْجِدَ يَعْدُو، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ رَأَى هَذَا ذُعْرًا". فَقَالَ: قَدْ قُتِلَ وَاللَّهِ صَاحِبِي، وَإِنِّي لَمَقْتُولٌ. فَجَاءَ أَبُو بَصِيرٍ فَقَالَ: قَدْ أَوْفَى اللَّهُ ذِمَّتَكَ، فَقَدْ رَدَدْتَنِي إِلَيْهِمْ ثُمَّ نَجَّانِي اللَّهُ مِنْهُمْ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَيْلُ أُمِّهِ، مِسْعَرَ حَرْبٍ لَوْ كَانَ لَهُ أَحَدٌ". فَلَمَّا سَمِعَ ذَلِكَ عَرَفَ أَنَّهُ سَيَرُدُّهُ إِلَيْهِمْ، فَخَرَجَ حَتَّى أَتَى سِيفَ الْبَحْرِ، وَيَنْفَلِتُ أَبُو جَنْدَلٍ، فَلَحِقَ بِأَبِي بَصِيرٍ، حَتَّى اجْتَمَعَتْ مِنْهُمْ عِصَابَةٌ. (ق,د,ن)', 'മിസ്വറുബ്നു മഖ്റമ(റ): നബി(സ) ഹുദൈബിയ്യ സന്ധിയുടെ അന്ന് ആയിരത്തിൽ പരം സ്വഹാബികളുമായി പുറപ്പെട്ടു. അവർ ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ ബലിമൃഗങ്ങളെ നബി(സ) ഹാരമണിയിക്കുകയും അവകളെ പ്രത്യേകം അടയാളപ്പെടുത്തുകയും ചെയ്തു. പിന്നെ നബി(സ) ഉംറക്ക് ഇഹ്റാം കെട്ടി. ഹദീസ് ബാക്കി തുടർന്ന് പറഞ്ഞു: മിസ്വർ(റ) പറയുന്നു: നബി(സ) സഞ്ചാരം തുടർന്നു. അങ്ങനെ മക്കയിലേക്ക് ഇറങ്ങിപ്പോകുന്ന താഴ്വരയിലേക്കെത്തിയപ്പോൾ നബി(സ)യുടെ ഒട്ടകം മുട്ടുകുത്തി. അപ്പോൾ കൂടെയുള്ള അനുയായികൾ വിളിച്ചു പറഞ്ഞു: എഴുന്നേൽക്ക്, എഴുന്നേൽക്ക്, ഖസ്വാഅ് (പ്രായമുള്ള ചെവിയറ്റം മുറിക്കപ്പെട്ട പെൺ) ഒട്ടകം ക്ഷീണിച്ച് പെട്ടെന്ന് നിന്നിരിക്കുന്നു. രണ്ട് പ്രാവശ്യം ഇങ്ങനെ പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവൾക്ക് ക്ഷീണം ബാധിച്ചതല്ല, ക്ഷീണം ബാധിക്കൽ അതിന്റെ സ്വഭാവത്തിൽ പെട്ടതുമല്ല. ആനയെ (അബ്രഹതിന്റെ ആനക്കലഹ സംഭവത്തിൽ) തടഞ്ഞുവെച്ചവൻ (അല്ലാഹു) അതിനെയും തടഞ്ഞിരിക്കുകയാണ്." പിന്നീട് പറഞ്ഞു: "ഞാൻ ഏതൊരാളുടെ കരങ്ങളിലാണോ സമർപ്പിതമായിരിക്കുന്നത് അവൻ തന്നെ സത്യം, അല്ലാഹു പരിശുദ്ധമാക്കിയ കാര്യങ്ങളെ ആദരിക്കാൻ വേണ്ടി അവർ ഇന്ന് എന്നോട് എന്ത് ആവശ്യപ്പെട്ടാലും ഞാൻ നൽകുക തന്നെ ചെയ്യും." പിന്നെ നബി(സ) ഒട്ടകത്തെ തെളിച്ചു. അത് ഉയർന്നെണീറ്റു. എന്നിട്ട് അവരിൽ നിന്ന് അൽപം മാറി സഞ്ചരിക്കുകയും ഹുദൈബിയ്യയുടെ അങ്ങേഅറ്റത്ത് വെള്ളം കുറഞ്ഞ ഒരു ജലാശയത്തിന് സമീപം ചെന്ന് നിൽക്കുകയും ചെയ്തു. അന്നേരം ബുദൈലുബ്നു വർഖാഉൽ ഖുസാഈ അങ്ങോട്ടു വന്നു. ശേഷം ഉർവ്വതുബ്നു മസ്ഊദും വന്നു. എന്നിട്ട് അദ്ദേഹം തിരുനബി(സ)യോട് സംസാരിക്കാൻ തുടങ്ങി. സംസാരിക്കുമ്പോഴെല്ലാം അയാൾ തിരുമേനി(സ)യുടെ താടി പിടിച്ചുകൊണ്ടിരുന്നു. മുഗീറതുബ്നു ശുഅ്ബ(റ) നബി(സ)യുടെ സമീപം നിൽക്കുന്നുണ്ടായിരുന്നു. അദ്ദേഹത്തിന്റെ പക്കൽ വാളുണ്ട്, അദ്ദേഹം പടത്തൊപ്പിയും ധരിച്ചിട്ടുണ്ട്. അദ്ദേഹം വാളിന്റെ തലപ്പ് കൊണ്ട് അയാളുടെ കയ്യിലടിച്ചുകൊണ്ട് പറഞ്ഞു: നബി(സ)യുടെ താടിയിൽ നിന്ന് കയ്യെടുത്തുമാറ്റ്. ഉർവ്വത് തലയുയർത്തിയിട്ട് ചോദിച്ചു: ആരാണിത്? ബാക്കിയുള്ളവർ പറഞ്ഞു: മുഗീറതുബ്നു ശുഅ്ബ. അയാൾ പറഞ്ഞു: ഓ വഞ്ചകാ, നിന്റെ വഞ്ചനയുടെ കാര്യത്തിലല്ലേ ഞാൻ ഇത്രയും പണിപ്പെട്ടത്? - ജാഹിലിയ്യാ കാലത്ത് മുഗീറതുബ്നു ശുഅ്ബ(റ) ഒരു സംഘമാളുകളോട് കൂട്ടുകൂടി അവരെ വധിച്ച് മുതലുകൾ അപഹരിച്ചിട്ടുണ്ടായിരുന്നു. ശേഷം അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് മുസ്ലിമായി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ മുസ്ലിമായത് ഞങ്ങൾ സ്വീകരിച്ചു, പക്ഷേ, ഈ സമ്പത്ത് ചതിയിലൂടെ നേടിയതാണ്. അതുകൊണ്ട് ഞങ്ങൾക്കത് ആവശ്യമില്ല." - ശേഷം നിവേദകൻ ഹദീസ് തുടർന്നു പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ എഴുതുക: അല്ലാഹുവിന്റെ ദൂതരായ മുഹമ്മദ്(സ) സന്ധിയിലേർപെട്ട കാര്യമാണിത്." എന്നിട്ട് നബി(സ) കാര്യങ്ങൾ പറഞ്ഞു. അപ്പോൾ സുഹൈൽ പറഞ്ഞു: താങ്കളുടെ മാർഗ്ഗം സ്വീകരിച്ചവനാണെങ്കിലും ശരി, ഞങ്ങളിൽ ഒരാൾ താങ്കളുടെ അടുത്തേക്ക് വന്നാൽ അവനെ ഞങ്ങളിലേക്ക് പറഞ്ഞയക്കണമെന്നും നിബന്ധന വേണം. എഴുത്ത് കഴിഞ്ഞപ്പോൾ നബി(സ) സ്വഹാബികളോട് പറഞ്ഞു: "നിങ്ങൾ ബലിയറുക്കുകയും തലമുണ്ഡനം ചെയ്യുകയും ചെയ്യുക." ഇതിനു ശേഷം വിശ്വാസിനികളായ ചില സ്ത്രീകൾ പലായനം ചെയ്തുകൊണ്ട് വന്നു. അവരെ തിരിച്ചയക്കുന്നതിൽ നിന്ന് അല്ലാഹു മുസ്ലിംകളെ വിലക്കി. തങ്ങളുടെ മഹർ തിരിച്ചേൽപിക്കാൻ അല്ലാഹു അവരോട് കൽപിക്കുകയും ചെയ്തു. പിന്നീട് നബി(സ) മദീനയിലേക്ക് തിരിച്ചു. അന്നേരം അബൂബസ്വീർ(റ) തിരുസന്നിധിയിൽ വന്നു. ഖുറൈശികൾ അദ്ദേഹത്തെ അന്വേഷിക്കാൻ രണ്ട് പേരെ അയച്ചിരുന്നു. അങ്ങനെ അബൂബസ്വീർ(റ)വിനെ നബി(സ) ആ രണ്ടുപേർക്ക് കൈമാറുകയും അവർ അദ്ദേഹത്തെയും കൂട്ടി പുറപ്പെടുകയും ചെയ്തു. ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ അവർ കാരക്ക തിന്നാൻ വേണ്ടി ഇറങ്ങി. അപ്പോൾ അബൂബസ്വീർ അവരിലൊരാളോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, നിന്റെ ഈ വാൾ വളരെ നല്ലതാണെന്നു തോന്നുന്നു. രണ്ടാമത്തെയാൾ പെട്ടെന്ന് അത് കൈക്കലാക്കിക്കൊണ്ട് പറഞ്ഞു: ഞാനിത് പരീക്ഷിച്ചുനോക്കിയിട്ടുണ്ട്. അബൂബസ്വീർ(റ) പറഞ്ഞു: ആ വാൾ തരൂ, ഞനൊന്ന് നോക്കട്ടെ. അയാൾ കൊടുത്തു. ഉടനെ അദ്ദേഹം അയാളെ വെട്ടി. അയാൾ മരിച്ചുവീണു. മറ്റെയാൾ പേടിച്ചോടി മദീനയിൽ പോയി ഓടിച്ചെന്ന് പള്ളിയിൽ കയറി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവൻ പേടിപ്പെടുത്തുന്ന എന്തോ കണ്ടിരിക്കുന്നു." അയാൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, എന്റെ കൂട്ടുകാരൻ കൊല്ലപ്പെട്ടിരിക്കുന്നു, ഞാനും കൊല്ലപ്പെട്ടേക്കാം. അപ്പോൾ അബൂബസ്വീർ(റ) അങ്ങോട്ടെത്തി. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു അങ്ങയുടെ കരാർ പൂർത്തിയാക്കിയിരിക്കുന്നു. അവിടന്ന് എന്നെ അവർക്ക് തന്നെ മടക്കി നൽകുകയും പിന്നെ അല്ലാഹു അവരിൽ നിന്ന് എന്നെ രക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിന്റെ ഉമ്മാക്ക് നാശം (ആക്ഷേപ വാക്കാണെങ്കിലും പ്രശംസിച്ചുകൊണ്ട്), അവന് ബന്ധുക്കളാരെങ്കിലും ഉണ്ടെങ്കിൽ ഇത് യുദ്ധത്തെ ക്ഷണിച്ചുവരുത്തിയേക്കാം." ഇത് കേട്ടപ്പോൾ നബി(സ) തന്നെ വീണ്ടും അവരിലേക്ക് മടക്കി അയക്കുമെന്ന് അബൂബസ്വീർ(റ)വിന് മനസ്സിലായി. അങ്ങനെ അദ്ദേഹം പുറത്തു പോകുകയും കടൽതീരത്ത് ചെന്നെത്തുകയും ചെയ്തു. ശേഷം അബൂജുൻദൽ(റ)വും രക്ഷപ്പെട്ട്, അബൂബസ്വീർ(റ)വിനോടൊപ്പം ചേർന്നു. അങ്ങനെ ഒരു സംഘം ആളുകൾ അവിടെ ഒരുമിച്ചുകൂടി. (ബു,മു,ദ,ന)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 1003, 1005, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 467, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا وَمَرْوَانَ بْنِ الْحَكَمِ: أَنَّهُمُ اصْطَلَحُوا عَلَى وَضْعِ الْحَرْبِ عَشْرَ سِنِينَ يَأْمَنُ فِيهِنَّ النَّاسُ، وَعَلَى أَنَّ بَيْنَنَا عَيْبَةً مَكْفُوفَةً، وَأَنَّهُ لَا إِسْلَالَ وَلَا إِغْلَالَ. (د)', 'മിസ്വറുബ്നു മഖ്റമ(റ), മർവാനുബ്നുൽ ഹകം(റ): പത്ത് വർഷത്തേക്ക് യുദ്ധം അവസാനിപ്പിക്കാൻ അവർ തീരുമനിച്ചു. അക്കാലയളവിൽ ജനങ്ങൾ സുരക്ഷിതരായി കഴിയും. ഞങ്ങൾക്കിടയിൽ മുൻകാല ശത്രുത മറക്കുന്ന മാനസികാവസ്ഥയുണ്ടകണമെന്നും, വഞ്ചനയോ കവർച്ചയോ ഉണ്ടാവരുതെന്നും കരാർ ചെയ്തു. (ദ)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1005, 1005, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 468, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْإِمَامُ جُنَّةٌ، يُقَاتَلُ بِهِ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഇമാം യുദ്ദം ചെയ്യുമ്പോൾ ഉപയോഗിക്കപ്പെടുന്ന ഒരു പരിചയാണ് (സംരക്ഷകനാണ്)." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 1005, 1006, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 469, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَتْنِي قُرَيْشٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُلْقِيَ فِي قَلْبِي الْإِسْلَامُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي وَاللَّهِ لَا أَرْجِعُ إِلَيْهِمْ أَبَدًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَا أَخِيسُ بِالْعَهْدِ وَلَا أَحْبِسُ الْبُرُدَ، وَلَكِنِ ارْجِعْ فَإِنْ كَانَ فِي نَفْسِكَ الَّذِي فِي نَفْسِكَ الْآنَ فَارْجِعْ". قَالَ: فَذَهَبْتُ، ثُمَّ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمْتُ. (د)', 'അബൂറാഫിഅ്(റ): ഖുറൈശികൾ എന്നെ നബി(സ)യുടെ അടുത്തേക്കയച്ചു. നബി(സ)യെ ദർശിച്ചപ്പോൾ എന്റെ ഹൃദയത്തിൽ ഇസ്ലാമിനോട് താൽപര്യം ജനിച്ചു. അന്നേരം ഞാൻ പറഞ്ഞു: തിരുദൂതരേ, അല്ലാഹുവാണ് സത്യം, ഞാനവരിലേക്ക് ഇനിയൊരിക്കലും മടങ്ങുകയില്ല. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാനൊരിക്കലും കരാർ പൊളിക്കുകയോ, ദൂതനെ ബന്ധനസ്ഥനാക്കുകയോ ചെയ്യുകയില്ല. അതിനാൽ നീ മടങ്ങുക. ഇപ്പോൾ നിന്റെ മനസ്സിലുള്ള താൽപര്യം നിലനൽക്കുകയാണെങ്കിൽ ശേഷം നീ മടങ്ങി വരിക." അദ്ദേഹം പറയുന്നു: അങ്ങനെ ഞാൻ പോകുകയും പിന്നീട് നബി(സ)യുടെ അടുത്ത് വന്ന് ഇസ്ലാം സ്വീകരിക്കുകയും ചെയ്തു. (ദ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1006, 1006, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 470, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَبُوكَ وَأَهْدَى مَلِكُ أَيْلَةَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةً بَيْضَاءَ وَكَسَاهُ بُرْدًا وَكَتَبَ لَهُ بِبَحْرِهِمْ. (خ)', 'അബൂഹുമൈദിസ്സാഇദി(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ തബൂക്കിനോട് യുദ്ധം ചെയ്തു. ഐലയിലെ രാജാവ് നബി(സ)ക്ക് ഒരു വെളുത്ത കോവർ കഴുതയെ സമ്മാനമായി നൽകി. അദ്ദേഹം നബി(സ)ക്കൊരു പുതപ്പ് ധരിപ്പിച്ചു. അവരുടെ കടലിലെ നിയന്ത്രണം നബി(സ)ക്ക് നൽകുകയും ചെയ്തു. (ബു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദിസ്സാഇദി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1006, 1006, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 471, 'عَنْ سُلَيْمِ بْنِ عَامِرٍ – رَجُلٌ مِنْ حِمْيَرَ – قَالَ: كَانَ بَيْنَ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ وَبَيْنَ الرُّومِ عَهْدٌ، وَكَانَ يَسِيرُ نَحْوَ بِلَادِهِمْ، حَتَّى إِذَا انْقَضَى الْعَهْدُ غَزَاهُمْ، فَجَاءَ رَجُلٌ عَلَى فَرَسٍ أَوْ بِرْذَوْنٍ وَهُوَ يَقُولُ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، وَفَاءٌ لَا غَدَرٌ. فَنَظَرُوا فَإِذَا عَمْرُو بْنُ عَبَسَةَ، فَأَرْسَلَ إِلَيْهِ مُعَاوِيَةُ فَسَأَلَهُ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ بَيْنَهُ وَبَيْنَ قَوْمٍ عَهْدٌ: فَلَا يَشُدُّ عُقْدَةً وَلَا يَحُلُّهَا حَتَّى يَنْقَضِيَ أَمَدُهَا، أَوْ يَنْبِذَ إِلَيْهِمْ عَلَى سَوَاءٍ". فَرَجَعَ مُعَاوِيَةُ. (د,ت)', 'സുലൈമുബ്നു ആമിർ(റ) - അദ്ദേഹം ഹിംയറിൽ പെട്ടയാളാണ് - റോമക്കാരുടെയും മുആവിയ(റ)വിന്റെയുമിടയിൽ ഒരു ഉടമ്പടിയുണ്ടായിരുന്നു. അക്കാലയളവിൽ അദ്ദേഹം അവരുടെ നാട്ടിലേക്ക് പുറപ്പെടാറുണ്ടായിരുന്നു. ഉടമ്പടി അവസാനിച്ചപ്പോൾ അദ്ദേഹം യുദ്ധം ചെയ്യാൻ പുറപ്പെട്ടു. അപ്പോൾ ഒരാൾ തന്റെ കുതിരപ്പുറത്ത് അല്ലെങ്കിൽ ബിർദൗൻ എന്ന മുന്തിയ കുതിരയുടെ പുറത്ത് വന്നു. അയാൾ ഇങ്ങനെ വിളിച്ചുപറയുന്നുണ്ടായിരുന്നു: അല്ലാഹു അക്ബർ (അല്ലാഹുവാണ് വലിയവൻ), അല്ലാഹു അക്ബർ, കരാർ പൂർത്തീകരണമുണ്ടാവട്ടെ. വിശ്വാസവഞ്ചനയില്ലാതിരിക്കട്ടെ. അവർ നോക്കുമ്പോൾ അത് അംറുബ്നു അബസ(റ)വായിരുന്നു. മുആവിയ(റ) അദ്ദേഹത്തെ വിളിച്ചുവരുത്തി കാര്യം ചോദിച്ചു: അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഓരാൾ ഒരു കൂട്ടരോട് കരാറിലേർപെട്ടിട്ടുണ്ടെങ്കിൽ, അതിന്റെ കാലാവധി തീരുകയോ ആ കരാർ ലംഘിക്കപ്പെടുകയോ ചെയ്യുന്നത് വരെ അവൻ അതിൽ ശക്തിവരുത്തുകയോ ഇളവുണ്ടാക്കുകയോ ചെയ്യരുത്. അപ്പോൾ മുആവിയ(റ) മടങ്ങി. (ദ,തു)', 'سُلَيْمِ بْنِ عَامِرٍ – رَجُلٌ مِنْ حِمْيَرَ – قَالَ', 'സുലൈമുബ്നു ആമിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 1006, 1007, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 472, 'عَنْ نُعَيْمِ بْنِ مَسْعُودٍ الْأَشْجَعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَهُمَا حِينَ قَرَأَ كِتَابَ مُسَيْلِمَةَ: "مَا تَقُولَانِ أَنْتُمَا". قَالَا: نَقُولُ كَمَا قَالَ، قَالَ: "أَمَا وَاللَّهِ، لَوْلَا أَنَّ الرُّسُلَ لَا تُقْتَلُ لَضَرَبْتُ أَعْنَاقَكُمَا". (د)', 'നുഐമുബ്നു മസ്ഊദുൽ അശ്ജഈ(റ): മുസൈലിമതുൽ കദ്ദാബിന്റെ കത്ത് വായിച്ചുകഴിഞ്ഞപ്പോൾ ദൂതരായി വന്ന രണ്ടാളുകളോട് നബി(സ) ചോദിക്കുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങൾ രണ്ടുപേരും എന്തു പറയുന്നു?" അവർ പറഞ്ഞു: അദ്ദേഹം പറയുന്നത് തന്നെയാണ് ഞങ്ങളുടെയും അഭിപ്രായം. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് സത്യം, ദൂതന്മാർ കൊല്ലപ്പെടാൻ പാടില്ല എന്ന നിയമം ഇല്ലായിരുന്നെങ്കിൽ ഞാൻ നിങ്ങളുടെ രണ്ടുപേരുടെയും തലയെടുക്കുമായിരുന്നു." (ദ)', 'نُعَيْمِ بْنِ مَسْعُودٍ الْأَشْجَعِيِّ', 'നുഐമുബ്നു മസ്ഊദുൽ അശ്ജഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1007, 1007, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 473, 'عَنْ حَارِثَةَ بْنِ مُضَرِّبٍ: أَنَّهُ أَتَى عَبْدَ اللَّهِ بْنَ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: مَا بَيْنِي وَبَيْنَ أَحَدٍ مِنَ الْعَرَبِ حِنَةٌ، وَإِنِّي مَرَرْتُ بِمَسْجِدٍ لِبَنِي حَنِيفَةَ فَإِذَا هُمْ يُؤْمِنُونَ بِمُسَيْلِمَةَ. فَأَرْسَلَ إِلَيْهِمْ عَبْدُ اللَّهِ فَجِيءَ بِهِمْ. فَاسْتَتَابَهُمْ غَيْرَ ابْنِ النَّوَّاحَةِ، قَالَ لَهُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَوْلَا أَنَّكَ رَسُولٌ لَضَرَبْتُ عُنُقَكَ". فَأَنْتَ الْيَوْمَ لَسْتَ بِرَسُولٍ، فَأَمَرَ قَرَظَةَ بْنَ كَعْبٍ فَضَرَبَ عُنُقَهُ فِي السُّوقِ، ثُمَّ قَالَ: مَنْ أَرَادَ أَنْ يَنْظُرَ إِلَى ابْنِ النَّوَّاحَةِ قَتِيلًا بِالسُّوقِ. (د)', 'ഹാരിസതുബ്നു മുളർറബ്(റ): അദ്ദേഹം അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെയടുക്കൽ വന്നുകൊണ്ട് പറഞ്ഞു: എനിക്ക് അറബികളിൽ ആരുമായിട്ടും ശത്രുതയില്ല. ബനൂ ഹനീഫ ഗോത്രക്കാരുടെ ഒരു പള്ളിയുടെ സമീപത്തുകൂടെ ഞാൻ നടന്നുപോയപ്പോൾ അവർ മുസൈലിമയിൽ വിശ്വസിക്കുന്നുവെന്ന് മനസ്സിലായി. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) അവരിലേക്ക് ആളെ അയച്ചു അവരെ വരുത്തുകയും ഇബ്നുന്നവ്വാഹ ഒഴികെയുള്ള എല്ലാവരോടും തൗബ ചെയ്തു മടങ്ങാൻ കൽപിക്കുകയും ചെയ്തു. അയാളോട് അബ്ദുല്ല(റ) പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നീ ദൂതനായിരുന്നില്ലെങ്കിൽ നിന്റെ തല ഞാൻ വെട്ടുമായിരുന്നു." ഇന്ന് നീ ദൂതനല്ല. എന്നിട്ടദ്ദേഹം ഖറളതുബ്നു കഅ്ബ്(റ)വിനോട് അയാളെ വധിക്കാൻ കൽപിച്ചു. അദ്ദേഹം അങ്ങാടിയിൽ വെച്ചയാളെ വധിച്ചു. എന്നിട്ട് അബ്ദുല്ല(റ) പറഞ്ഞു: ഇബ്നുന്നവ്വാഹ അങ്ങാടിയിൽ വെച്ച് വധിക്കപ്പെട്ടത് കാണണമെങ്കിൽ കണ്ടുകൊള്ളുക. (ദ)', 'حَارِثَةَ بْنِ مُضَرِّبٍ', 'ഹാരിസതുബ്നു മുളർറബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1007, 1007, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 474, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا مَنَعَنِي أَنْ أَشْهَدَ بَدْرًا إِلَّا أَنِّي خَرَجْتُ أَنَا وَأَبِي حُسَيْلٌ، قَالَ: فَأَخَذَنَا كُفَّارُ قُرَيْشٍ، قَالُوا: إِنَّكُمْ تُرِيدُونَ مُحَمَّدًا، فَقُلْنَا: مَا نُرِيدُهُ، مَا نُرِيدُ إِلَّا الْمَدِينَةَ. فَأَخَذُوا مِنَّا عَهْدَ اللَّهِ وَمِيثَاقَهُ لَنَنْصَرِفَنَّ إِلَى الْمَدِينَةِ وَلَا نُقَاتِلُ مَعَهُ. فَأَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْنَاهُ الْخَبَرَ، فَقَالَ: "انْصَرِفَا، نَفِي لَهُمْ بِعَهْدِهِمْ وَنَسْتَعِينُ اللَّهَ عَلَيْهِمْ". (م)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): ബദ്റിൽ പങ്കെടുക്കാൻ എന്നെ തടഞ്ഞത് ഇതുമാത്രമാണ്: ഞാനും എന്റെ പിതാവ് ഹുസൈലും യാത്ര തിരിച്ചു. അദ്ദേഹം പറയുന്നു: അപ്പോൾ ഖുറൈശികളിലെ സത്യനിഷേധികൾ ഞങ്ങളെ തടഞ്ഞുവെച്ച് ചോദിച്ചു: നിങ്ങൾ മുഹമ്മദിന്റെ അടുത്തേക്കാണോ പോകുന്നത്? ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ അദ്ദേഹത്തിന്റെയടുത്തേക്ക് പോകുന്നില്ല. മദീനയിൽ പോവുകയെന്ന ഉദ്ദേശ്യമേയുള്ളൂ. അപ്പോൾ അവർ, നബി(സ)യോടൊപ്പം ഞങ്ങൾ യുദ്ധത്തിന് പോവുകയില്ലെന്നും മദീനയിലേക്ക് മാത്രമേ പോകൂ എന്നും, അല്ലാഹുവിന്റെ പേരിൽ ഞങ്ങളെക്കൊണ്ട് സത്യം ചെയ്യിക്കുകയും കരാർ ചെയ്യിക്കുകയും ചെയ്തു. ഞങ്ങൾ നബി(സ)യുടെ അടുത്തേക്ക് ചെന്ന് വിവരങ്ങളെല്ലാം പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടുപേരും പിന്തിരിഞ്ഞുപോവുക, നമുക്ക് അവരോടുള്ള കരാർ പൂർത്തീകരിക്കുകയും അവർക്കെതിരിൽ അല്ലാഹുവിനോട് സഹായം തേടുകയും ചെയ്യാം." (മു)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1007, 1008, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 475, 'عَنْ عَبْدِاللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَتَلَ مُعَاهَدًا لَمْ يَرِحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا تُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا". (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നു: "ആരെങ്കിലും സന്ധിയിലേർപ്പെട്ടവനെ വധിച്ചാൽ അവന് സ്വർഗ്ഗത്തിന്റെ വാസന പോലും കിട്ടുകയില്ല. നിശ്ചയം സ്വർഗ്ഗത്തിന്റെ വാസന നാൽപത് വർഷത്തെ വഴിദൂരം വരെ എത്തുന്നതാണ്." (ബു)', 'عَبْدِاللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1008, 1008, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 476, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَيْفَ أَنْتُمْ إِذَا لَمْ تَجْتَبُوا دِينَارًا وَلَا دِرْهَمًا، فَقِيلَ لَهُ: وَكَيْفَ تَرَى ذَلِكَ كَائِنًا يَا أَبَا هُرَيْرَةَ؟ قَالَ: إِي، وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ عَنْ قَوْلِ الصَّادِقِ الْمَصْدُوقِ قَالُوا: عَمَّ ذَاكَ، قَالَ: تُنْتَهَكُ ذِمَّةُ اللَّهِ، وَذِمَّةُ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَشُدُّ اللَّهُ قُلُوبَ أَهْلِ الذِّمَّةِ فَيَمْنَعُونَ مَا فِي أَيْدِيهِمْ. (خ)', 'അബൂഹുറൈറ(റ): ഒരു ദിർഹമോ ദീനാറോ വരുമാനമായി കിട്ടുന്നില്ലെങ്കിൽ നിങ്ങൾ എങ്ങനെയായിരിക്കും? അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: അബൂഹുറൈറ(റ)! അതെങ്ങനെ സംഭവിക്കും? അബൂഹുറൈറ(റ) പറഞ്ഞു: എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം. സത്യസന്ധനാകുകയും സത്യസന്ധനാക്കപ്പെടുകയും ചെയ്തവരുടെ വാക്കാണ്. ജനങ്ങൾ അവിടത്തോട് ചോദിച്ചു: അതെങ്ങനെയാണ്? അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഉടമ്പടിയും അവന്റെ റസൂലിന്റെ ഉടമ്പടിയും പിച്ചിച്ചീന്തപ്പെടും. അപ്പോൾ സന്ധിയിലേർപ്പെട്ടവരുടെ ഹൃദയങ്ങളെ അല്ലാഹു കഠിനമാക്കുകയും തരാനുള്ളതിനെ അവർ തടഞ്ഞുവെക്കുകയും ചെയ്യുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1008, 1008, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 477, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْطَلَقَ عَبْدُاللَّهِ بْنُ سَهْلٍ وَمُحَيِّصَةُ بْنُ مَسْعُودِ بْنِ زَيْدٍ إِلَى خَيْبَرَ وَهِيَ يَوْمَئِذٍ صُلْحٌ فَتَفَرَّقَا فَأَتَى مُحَيِّصَةُ إِلَى عَبْدِاللَّهِ بْنِ سَهْلٍ، وَهُوَ يَتَشَمَّطُ فِي دَمِهِ قَتِيلًا فَدَفَنَهُ، ثُمَّ قَدِمَ الْمَدِينَةَ، فَانْطَلَقَ عَبْدُالرَّحْمَنِ بْنُ سَهْلٍ وَمُحَيِّصَةُ وَحُوَيِّصَةُ ابْنَا مَسْعُودٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَهَبَ عَبْدُالرَّحْمَنِ يَتَكَلَّمُ فَقَالَ: "كَبِّرْ كَبِّرْ". وَهُوَ أَحْدَثُ الْقَوْمِ، فَسَكَتَ، فَتَكَلَّمَا، فَقَالَ: "أَتَحْلِفُونَ وَتَسْتَحِقُّونَ قَاتِلَكُمْ أَوْ صَاحِبَكُمْ". قَالُوا: وَكَيْفَ نَحْلِفُ وَلَمْ نَشْهَدْ وَلَمْ نَرَ! قَالَ: "فَتُبْرِيكُمْ يَهُودُ بِخَمْسِينَ". فَقَالُوا: كَيْفَ نَأْخُذُ أَيْمَانَ قَوْمٍ كُفَّارٍ. فَعَقَلَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِهِ. (خ)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ): അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ), മുഹയ്യിസതുബ്നു മസ്ഊദുബ്നു സൈദ്(റ) എന്നിവർ ഖൈബറിലേക്ക് പോയി. അന്ന് ഖൈബറുകാരുമായി തിരുമേനി(സ) സന്ധിയിലായിരുന്നു. അവിടെവെച്ച് അവർ രണ്ടുപേരും വിട്ടുപിരിഞ്ഞു. പിന്നീട് മുഹയ്യിസ(റ) തിരിച്ചുവന്നപ്പോൾ അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ) രക്തത്തിൽ കുളിച്ചു പിടഞ്ഞുകൊണ്ടിരിക്കുകയാണ്. അങ്ങനെ അദ്ദേഹത്തെ മറവുചെയ്തു. ശേഷം അദ്ദേഹം മദീനയിൽ ചെന്നു. അങ്ങനെ അബ്ദുറഹ്മാനുബ്നു സഹ്ൽ(റ)വും മുഹയ്യിസതുബ്നു മസ്ഊദ്(റ)വും ഹുവയ്യിസതുബ്നു മസ്ഊദ്(റ)വും തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പോയി. അങ്ങനെ അബ്ദുർറഹ്മാൻ(റ) സംസാരിക്കാൻ തുടങ്ങി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ വലിയവർ സംസാരിക്കട്ടെ." അദ്ദേഹം ചെറിയ (പ്രായം കുറഞ്ഞവൻ) ആളായിരുന്നു. അപ്പോൾ അദ്ദേഹം മൗനമവലംബിച്ചു. ശേഷം അവർ രണ്ടുപേർ സംസാരിച്ചു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "സത്യം ചെയ്ത് നിങ്ങളുടെ ഘാതകന് അല്ലെങ്കിൽ നിങ്ങളുടെയാൾക്ക് (അയാളെ കൊല്ലുന്നതിന്) അവകാശികളാകാൻ നിങ്ങൾ തയ്യാറാണോ?" അവർ ചോദിച്ചു: അത് കണ്ടിട്ടില്ലെന്നിരിക്കെ ഞങ്ങളെങ്ങനെ സത്യം ചെയ്യും? തിരുമേനി(സ) പറഞ്ഞു: "എങ്കിൽ അമ്പത് സത്യം ചെയ്ത് ജൂതന്മാർ അവരുടെ നിരപരാധിത്വം തെളിയിച്ചാൽ നിങ്ങൾ സമ്മതിക്കുമോ?" അവർ പറഞ്ഞു: സത്യനിഷേധികളായ ഒരു സമൂഹത്തിന്റെ സത്യം ഞങ്ങളെങ്ങനെ അംഗീകരിക്കും? അപ്പോൾ നബി(സ) തന്നെ അതിനുള്ള നഷ്ടപരിഹാരം നൽകി. (ബു)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1008, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 478, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أُصِيبَ سَعْدٌ يَوْمَ الْخَنْدَقِ، رَمَاهُ رَجُلٌ مِنْ قُرَيْشٍ [يُقَالُ لَهُ] ابْنُ الْعَرِقَةِ، رَمَاهُ فِي الْأَكْحَلِ، فَضَرَبَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْمَةً فِي الْمَسْجِدِ يَعُودُهُ مِنْ قَرِيبٍ، فَلَمَّا رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْخَنْدَقِ وَضَعَ السِّلَاحَ فَاغْتَسَلَ، فَأَتَاهُ جِبْرِيلُ وَهُوَ يَنْفُضُ رَأْسَهُ مِنَ الْغُبَارِ، فَقَالَ: وَضَعْتَ السِّلَاحَ؟ وَاللَّهِ مَا وَضَعْنَاهُ، اخْرُجْ إِلَيْهِمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَأَيْنَ". فَأَشَارَ إِلَى بَنِي قُرَيْظَةَ، فَقَاتَلَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَزَلُوا عَلَى حُكْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحُكْمَ فِيهِمْ إِلَى سَعْدٍ، قَالَ: فَإِنِّي أَحْكُمُ فِيهِمْ أَنْ تُقْتَلَ الْمُقَاتِلَةُ، وَأَنْ تُسْبَى الذُّرِّيَّةُ وَالنِّسَاءُ، وَتُقْسَمَ أَمْوَالُهُمْ. قَالَ هِشَامٌ: قَالَ أَبِي: فَأُخْبِرْتُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَقَدْ حَكَمْتَ فِيهِمْ بِحُكْمِ اللَّهِ عَزَّ وَجَلَّ". وَفِي رِوَايَةٍ: "حَكَمْتَ بِحُكْمِ اللَّهِ". وَقَالَ مَرَّةً: "لَقَدْ حَكَمْتَ بِحُكْمِ الْمَلِكِ". (م)', 'ആഇശ(റ): ഖൻദഖ് ദിവസം സഅ്ദ്(റ)വിനെ ഖുറൈശിലെ ഇബ്നുൽഅരിഖ എന്നൊരാൾ അമ്പ് ചെയ്തു. സഅ്ദിന്റെ കൺപോളക്കായിരുന്നു അമ്പേറ്റത്. അപ്പോൾ നബി(സ) അദ്ദേഹത്തിന് വേണ്ടി പള്ളിയിൽ ഒരു ടെന്റ് ഉണ്ടാക്കി. പെട്ടെന്ന് സന്ദർശിക്കാനുയിരുന്നു അത്. അങ്ങനെ ഖൻദഖിൽ നിന്ന് തിരിച്ചുവന്ന് നബി(സ) ആയുധം വെച്ചു കുളിച്ചുകഴിഞ്ഞപ്പോൾ പൊടിയിൽ നിന്നും തലകുടഞ്ഞ് ജിബ്രീൽ(അ) തിരുമേനി(സ)യുടെ അടുത്തുവന്ന് ചോദിച്ചു: അങ്ങ് ആയുധം വെച്ചോ? അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ വെച്ചിട്ടില്ല, അവിടന്ന് അവരിലേക്കിറങ്ങുക. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "എവിടെയാണ്?" അപ്പോൾ ബനൂഖുറൈളയെ സൂചിപ്പിച്ചു. അങ്ങനെ തിരുമേനി(സ) അവരോട് യുദ്ധം ചെയ്തു. അപ്പോൾ അവർ റസൂൽ(സ)യുടെ വിധിയോട് യോജിച്ചു. അപ്പോൾ റസൂൽ(സ) അവരുടെ വിധി സഅ്ദ്(റ)വിലേക്ക് ഏൽപിച്ചു കൊടുത്തു. സഅ്ദ്(റ) പറഞ്ഞു: ഞാൻ അവരിൽ വിധിക്കുന്നത്, യുദ്ധം ചെയ്തവരെ വധിച്ച് കളയാനും കുട്ടികളെയും സ്ത്രീകളെയും ബന്ധികളാക്കാനും അവരുടെ ധനം ഓഹരിവെക്കാനുമാണ്. ഹിശാം(റ) പറയുന്നു: എന്റെ പിതാവ് പറഞ്ഞു: എന്നോട് ഇപ്രകാരം അറിയിക്കപ്പെട്ടു: (സഅ്ദ്(റ)വിന്റെ വിധി കേട്ടപ്പോൾ) റസൂൽ(സ) പറഞ്ഞു: "അവരിൽ താങ്കൾ വിധിച്ചത് അല്ലാഹുവിന്റെ വിധിയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "താങ്കൾ അല്ലാഹുവിന്റെ വധി കൊണ്ട് വിധിച്ചിരിക്കുന്നു." മുർറ(റ) പറയുന്നു: "നിങ്ങൾ വിധിച്ചത് സർവ്വാധിരാജന്റെ വിധിയാണ്." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'يُقَالُ لَهُ', null, 1009, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=16 and h.hadith_no=478), 1, 'وَفِي رِوَايَةٍ: "حَكَمْتَ بِحُكْمِ اللَّهِ". وَقَالَ مَرَّةً: "لَقَدْ حَكَمْتَ بِحُكْمِ الْمَلِكِ". (م)', 'മറ്റൊരു നിവേദനിൽ: "താങ്കൾ അല്ലാഹുവിന്റെ വധി കൊണ്ട് വിധിച്ചിരിക്കുന്നു." മുർറ(റ) പറയുന്നു: "നിങ്ങൾ വിധിച്ചത് സർവ്വാധിരാജന്റെ വിധിയാണ്." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 479, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ مُعَاهِدًا فِي غَيْرِ كُنْهِهِ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ". (د,ن)', 'അബൂബക്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "സന്ധിയിലേർപ്പെട്ടവനെ അനുവദനീയമായ സമയത്തല്ലാതെ ആരെങ്കിലും വധിച്ചാൽ അവന്റെ മേൽ അല്ലാഹു സ്വർഗ്ഗം നിഷേധിച്ചിരിക്കുന്നു." (ദ,ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 1009, 1010, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 480, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا فُتِحَتْ خَيْبَرُ أُهْدِيَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةٌ فِيهَا سُمٌّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْمَعُوا إِلَيَّ مَنْ كَانَ هَا هُنَا مِنْ يَهُودَ". فَجُمِعُوا لَهُ، فَقَالَ: "إِنِّي سَائِلُكُمْ عَنْ شَيْءٍ فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْهُ". فَقَالُوا: نَعَمْ، فَقَالَ لَهُمْ: "مَنْ أَبُوكُمْ؟" قَالُوا: فُلَانٌ، فَقَالَ: "كَذَبْتُمْ بَلْ أَبُوكُمْ فُلَانٌ". قَالُوا: صَدَقْتَ، قَالَ: "فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ إِنْ سَأَلْتُ عَنْهُ؟" فَقَالُوا: نَعَمْ يَا أَبَا الْقَاسِمِ، وَإِنْ كَذَبْنَا عَرَفْتَ كَذِبَنَا كَمَا عَرَفْتَهُ فِي أَبِينَا، فَقَالَ لَهُمْ: "مَنْ أَهْلُ النَّارِ؟" قَالُوا: نَكُونُ فِيهَا يَسِيرًا ثُمَّ تَخْلُفُونَا فِيهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اخْسَئُوا فِيهَا وَاللَّهِ لَا نَخْلُفُكُمْ فِيهَا أَبَدًا". ثُمَّ قَالَ: "هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ إِنْ سَأَلْتُكُمْ عَنْهُ؟" فَقَالُوا: نَعَمْ يَا أَبَا الْقَاسِمِ، قَالَ: "هَلْ جَعَلْتُمْ فِي هَذِهِ الشَّاةِ سُمًّا؟" قَالُوا: نَعَمْ، قَالَ: "مَا حَمَلَكُمْ عَلَى ذَلِكَ؟" قَالُوا: أَرَدْنَا إِنْ كُنْتَ كَاذِبًا نَسْتَرِيحُ، وَإِنْ كُنْتَ نَبِيًّا لَمْ يَضُرَّكَ. (خ)', 'അബൂഹുറൈറ(റ): ഖൈബർ ജയിച്ചടക്കിയപ്പോൾ നബി(സ)ക്ക് വിഷം കലർത്തിയ ആടുമാംസം സമ്മാനിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "ഇവിടെയുള്ള മഴുവൻ ജൂതരേയും എനിക്കായി ഒരുമിച്ചുകൂട്ടുക." അങ്ങനെ അവർ ഒരുമിച്ചുകൂട്ടപ്പെട്ടു. അവരോട് നബി(സ) ചോദിച്ചു: "ഞാൻ നിങ്ങളോട് ഒരു കാര്യം അന്വേഷിക്കാൻ പോകുന്നു. നിങ്ങളെന്നോട് സത്യം പറയുമോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) അവരോട് ചോദിച്ചു: "നിങ്ങളുടെ ബാപ്പയാരാകുന്നു?" അവർ പറഞ്ഞു: ഇന്നയാൾ. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കള്ളം പറഞ്ഞിരിക്കുന്നു. നിങ്ങളുടെ ബാപ്പ ഇന്നവരല്ലേ?" അവർ പറഞ്ഞു: താങ്കൾ സത്യം പറഞ്ഞിരിക്കുന്നു. നബി(സ) ചോദിച്ചു: "ഞാനൊരു കാര്യം ചോദിച്ചാൽ നിങ്ങൾ സത്യം പറയുമോ?" അവർ പറഞ്ഞു: അതെ, അബുൽ ഖാസിം, ഞങ്ങൾ കള്ളം പറഞ്ഞാൽ താങ്കൾ അതു അറിയും. ഞങ്ങളുടെ ബാപ്പമാരുടെ വിഷയത്തിൽ താങ്കൾ അറിഞ്ഞതുപോലെ. നബി(സ) അവരോട് ചോദിച്ചു: "ആരാണ് നരകാവകാശികൾ?" അവർ പറഞ്ഞു: കുറച്ചുകാലം അവിടെ ഞങ്ങളുണ്ടാവും. പിന്നെ ഞങ്ങൾക്കുശേഷം നിങ്ങൾ വരും. നബി(സ) പറഞ്ഞു: "നിങ്ങളതിൽ നിന്ദ്യരായി കിടക്കേണ്ടി വരും. അല്ലാഹുവാണെ സത്യം, നിങ്ങളുടെ പിറകിൽ ഞങ്ങൾ അതിൽ കിടക്കുകയില്ല." ശേഷം റസൂൽ(സ) ചോദിച്ചു: "ഞാനൊരുകാര്യം ചോദിച്ചാൽ നിങ്ങൾ സത്യം പറയുമോ?" അവർ പറഞ്ഞു: അതെ, അബുൽഖാസിം. നബി(സ) ചോദിച്ചു: "ഈ ആട്ടിൻ മാംസത്തിൽ നിങ്ങൾ വിഷം ചേർത്തിട്ടുണ്ടോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "നിങ്ങളെ ഇതിനു പ്രേരിപ്പിച്ചതെന്താണ്?" അവർ പറഞ്ഞു: ഞങ്ങൾ ഉദ്ദേശിച്ചത്; താങ്കൾ കള്ളവാദിയാണെങ്കിൽ ഞങ്ങൾക്ക് താങ്കളിൽ നിന്ന് രക്ഷപ്പെടാം, നബിയാണെങ്കിലോ താങ്കൾക്ക് അത് ഒരു ബുദ്ധിമുട്ടും വരുത്തുകയുമില്ല. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1010, 1010, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 481, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشَرَةً عَيْنًا، وَأَمَّرَ عَلَيْهِمْ عَاصِمَ بْنَ ثَابِتٍ، فَنَفَرُوا لَهُمْ هُذَيْلٌ بِقَرِيبٍ مِنْ مِائَةِ رَجُلٍ رَامٍ، فَلَمَّا أَحَسَّ بِهِمْ عَاصِمٌ لَجَئُوا إِلَى قَرْدَدٍ، فَقَالُوا لَهُمْ: انْزِلُوا فَأَعْطُوا بِأَيْدِيكُمْ، وَلَكُمُ الْعَهْدُ وَالْمِيثَاقُ: أَنْ لَا نَقْتُلَ مِنْكُمْ أَحَدًا. فَقَالَ عَاصِمٌ: أَمَّا أَنَا فَلَا أَنْزِلُ فِي ذِمَّةِ كَافِرٍ. فَرَمَوْهُمْ بِالنَّبْلِ، فَقَتَلُوا عَاصِمًا فِي سَبْعَةِ نَفَرٍ، وَنَزَلَ إِلَيْهِمْ ثَلَاثَةُ نَفَرٍ عَلَى الْعَهْدِ وَالْمِيثَاقِ - مِنْهُمْ خُبَيْبٌ، وَزَيْدُ بْنُ الدَّثِنَةِ، وَرَجُلٌ آخَرُ - فَلَمَّا اسْتَمْكَنُوا مِنْهُمْ أَطْلَقُوا أَوْتَارَ قِسِيِّهِمْ فَرَبَطُوهُمْ بِهَا، فَقَالَ الرَّجُلُ الثَّالِثُ: هَذَا أَوَّلُ الْغَدْرِ، وَاللَّهِ لَا أَصْحَبُكُمْ، إِنَّ لِي بِهَؤُلَاءِ لَأُسْوَةً. فَجَرُّوهُ فَأَبَى أَنْ يَصْحَبَهُمْ، فَقَتَلُوهُ، فَلَبِثَ خُبَيْبٌ أَسِيرًا حَتَّى أَجْمَعُوا قَتْلَهُ، فَاسْتَعَارَ مُوسَى يَسْتَحِدُّ بِهَا، فَلَمَّا خَرَجُوا بِهِ لِيَقْتُلُوهُ قَالَ لَهُمْ خُبَيْبٌ: دَعُونِي أَرْكَعُ رَكْعَتَيْنِ، ثُمَّ قَالَ: وَاللَّهِ لَوْلَا أَنْ تَحْسَبُوا مَا بِي جَزَعًا لَزِدْتُ. (خ,د)', 'അബൂഹുറൈറ(റ): ശത്രുക്കളെ നിരീക്ഷിക്കാൻ വേണ്ടി നബി(സ) പത്തുപേരെ നിയോഗിക്കുകയും ആസിമുബ്നു സാബിത്(റ)വിനെ അവരുടെ തലവനാക്കുകയും ചെയ്തു. അവരെ നേരിടാൻ വേണ്ടി ഹുദൈൽ ഗോത്രക്കാരായ നൂറോളം അമ്പെയ്ത്തുകാർ പുറപ്പെട്ടു. അവർ വരുന്നുണ്ടെന്ന് ആസിം(റ) അറിയുകയും അവർ ഒരു മലയിലേക്ക് അഭയം പ്രാപിക്കുകയും ചെയ്തു. അപ്പോൾ ഹുദൈൽ ഗോത്രക്കാർ പറഞ്ഞു: നിങ്ങൾ ഇറങ്ങിവരികയും ആയുധം വെക്കുകയും ചെയ്യുക. നിങ്ങളിൽ ഒരാളെയും വധിക്കില്ലെന്ന് ഞങ്ങൾ കരാർ ചെയ്യാം. ആസിം(റ) പറഞ്ഞു: ഞാൻ ഒരിക്കലും സത്യനിഷേധിയുടെ കരാറിനെ സ്വീകരിക്കുകയില്ല. അങ്ങനെ മുസ്ലിംകൾ അവർക്കുനേരെ അമ്പെയ്യുകയും ആസിം(റ) അടക്കം ഏഴുപേരെ ശത്രുക്കൾ വധിക്കുകയും ചെയ്തു. ഖുബൈബ്(റ)വും സൈദുബ്നുദ്ദസീന(റ)വും മറ്റൊരാളുമടക്കം മൂന്നുപേർ ശത്രുക്കളുടെ കരാർ പ്രകാരം മലയിൽ നിന്നിറങ്ങി. അവർ ശത്രുക്കളുടെ കീഴിലകപ്പെട്ടപ്പോൾ ശത്രുക്കൾ അമ്പിൻവില്ല് ഊരുകയും അവരെ ബന്ധികളാക്കുകയും ചെയ്തു. അപ്പോൾ അവരിലെ മൂന്നാമൻ പറഞ്ഞു: ഇത് ആദ്യത്തെ ചതിയാണ്, അല്ലാഹു തന്നെ സത്യം, ഞാൻ നിങ്ങളോടൊപ്പം നിൽക്കുകയില്ല. എനിക്ക് എന്റെ കൂട്ടുകാരിൽ മാതൃകയുണ്ട്. അപ്പോൾ ശത്രുക്കൾ അദ്ദേഹത്തെ വലിക്കുകയും അദ്ദേഹം അവരോടൊപ്പം പോകാൻ വിസമ്മതിക്കുകയും ചെയ്തു. അങ്ങനെ അവർ അദ്ദേഹത്തെയും വധിച്ചു. ശേഷം ഖുബൈബ്(റ) ബന്ധിയായി ശേഷിക്കുകയും അവർ ഖുബൈബ്(റ)വിനെ വധിക്കാൻ തീരുമാനിക്കുകയും ചെയ്തു. ഖുബൈബ്(റ) തന്റെ ഗുഹ്യരോമങ്ങൾ നീക്കാൻ ആവശ്യമായ കത്തി വായ്പ വാങ്ങി. കൊല്ലാൻ വേണ്ടി കൊണ്ടുപോയപ്പോൾ ഖുബൈബ്(റ) അവരോട് പറഞ്ഞു: രണ്ട് റക്അത്ത് നിസ്കരിക്കുവാൻ നിങ്ങൾ എന്നെ അനുവദിക്കുക. ശേഷം പറഞ്ഞു: അല്ലാഹുവാണ, മരണഭയത്താലാണ് ഞാനിത് ചെയ്യുന്നതെന്ന് നിങ്ങൾ സംശയിക്കില്ലായിരുന്നെങ്കിൽ ഞാൻ റക്അത്തുകളുടെ എണ്ണം അധികരിപ്പിക്കുമായിരുന്നു. (ബു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 1010, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 482, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ قَوْمٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ". (خ,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ചങ്ങലകളിൽ ബന്ധിക്കപ്പെട്ടവരായി സ്വർഗത്തിൽ പ്രവേശിക്കുന്ന ചിലയാളുകളെ ദർശിച്ച് നമ്മുടെ രക്ഷിതാവ് അൽഭുതപ്പെട്ടിരിക്കുന്നു." (ബു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 1011, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 483, 'عَنْ جُنْدُبِ بْنِ مَكِيثٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدَ اللَّهِ بْنَ غَالِبٍ اللَّيْثِيَّ فِي سَرِيَّةٍ، وَكُنْتُ فِيهِمْ، وَأَمَرَهُمْ أَنْ يَشُنُّوا الْغَارَةَ عَلَى بَنِي الْمُلَوَّحِ بِالْكَدِيدِ، فَخَرَجْنَا حَتَّى إِذَا كُنَّا بِالْكَدِيدِ لَقِينَا الْحَارِثَ بْنَ الْبَرْصَاءِ اللَّيْثِيَّ، فَأَخَذْنَاهُ، فَقَالَ: إِنَّمَا جِئْتُ أُرِيدُ الْإِسْلَامَ، وَإِنَّمَا خَرَجْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقُلْنَا: إِنْ تَكُنْ مُسْلِمًا لَمْ يَضُرَّكَ رِبَاطُنَا يَوْمًا وَلَيْلَةً، وَإِنْ تَكُنْ غَيْرَ ذَلِكَ نَسْتَوْثِقُ مِنْكَ، فَشَدَدْنَاهُ وِثَاقًا. (د)', 'ജുൻദുബ്ബ്നു മകീസ്(റ): അബ്ദുല്ലാഹിബിൻ ഗാലിബുല്ലൈസി(റ)വിനെ റസൂൽ(സ) ഒരു യുദ്ധസംഘത്തിന്റെ നേതാവായി പറഞ്ഞയച്ചു. ഞാനും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. ബനൂ മുലവ്വിഹ് ഗോത്രത്തിന്റെ മേൽ കദീദിൽ വെച്ച് അക്രമം അഴിച്ചുവിടാൻ തിരുമേനി(സ) അവരോട് ആജ്ഞാപിച്ചു. അങ്ങനെ ഞങ്ങൾ കദീദിൽ എത്തിയപ്പോൾ ഹാരിസുബ്നു ബർസാഉൽ ലൈസിയെ കണ്ടുമുട്ടി. ഞങ്ങൾ അയാളെ പിടികൂടി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇസ്ലാം സ്വീകരിക്കണമെന്ന ഉദ്ദേശ്യത്തോടെയാണ് ഞാൻ വന്നിരിക്കുന്നത്. റസൂൽ(സ)യുടെ അടുത്തേക്കാണ് ഞാൻ പുറപ്പെട്ടിരിക്കുന്നത്. അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: നീ മുസ്ലിമാകുകയാണെങ്കിൽ ഒരു ദിവസത്തെ ഞങ്ങളുടെ ബന്ധനം നിന്നെ ബുദ്ധിമുട്ടിക്കുകയില്ല. നീ മറ്റുവല്ലതുമാകുകയാണെങ്കിൽ നിന്നെ ഞങ്ങൾക്ക് പിടിച്ചുവെക്കുകയും ചെയ്യാം. അങ്ങനെ ഞങ്ങൾ അദ്ദേഹത്തെ ശക്തിയായി കെട്ടിയിട്ടു. (ദ)', 'جُنْدُبِ بْنِ مَكِيثٍ', 'ജുൻദുബ്ബ്നു മകീസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1011, 1012, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 484, 'عَنْ سَوْدَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهُ قُدِمَ بِالْأُسَارَى حِينَ قُدِمَ بِهِمْ وَسَوْدَةُ بِنْتُ زَمْعَةَ عِنْدَ آلِ عَفْرَاءَ فِي مُنَاخِهِمْ عَلَى عَوْفٍ وَمُعَوِّذٍ ابْنَيْ عَفْرَاءَ، قَالَ: وَذَلِكَ قَبْلَ أَنْ يُضْرَبَ عَلَيْهِنَّ الْحِجَابُ، قَالَ: تَقُولُ سَوْدَةُ: وَاللَّهِ إِنِّي لَعِنْدَهُمْ إِذْ أُتِيتُ فَقِيلَ: هَؤُلَاءِ الْأُسَارَى قَدْ أُتِيَ بِهِمْ، فَرَجَعْتُ إِلَى بَيْتِي وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ، وَإِذَا أَبُو يَزِيدَ - سُهَيْلُ بْنُ عَمْرٍو - فِي نَاحِيَةِ الْحُجْرَةِ، مَجْمُوعَةٌ يَدَاهُ إِلَى عُنُقِهِ بِحَبْلٍ. (د)', 'സൗദ(റ): ബദ്റിലെ ബന്ധികളെ കൊണ്ടുവന്നപ്പോൾ അഫ്റാഇന്റെ മക്കളായ ഔഫിന്റെയും മുഅവ്വിദിന്റെയും കൂടെ, അവരുടെ ഒട്ടകം മുട്ടുകുത്തുന്ന സ്ഥലത്ത് സൗദബിൻത് സംഅ(റ)യും ഉണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: ഇത് നടന്നത് ഹിജാബ് നിർബന്ധമാക്കപ്പെടുന്നതിന്റെ മുമ്പായിരുന്നു. നിവേദകൻ പറയുന്നു: സൗദ(റ) പറയുന്നു: അല്ലാഹുവാണ് സത്യം. ഞാൻ അവരുടെ അടുക്കലായിരുന്നു. അപ്പോൾ ഒരാൾ എന്റെ അടുത്ത് വന്ന് പറഞ്ഞു: ഇതാ യുദ്ധത്തടവുകാരെ കൊണ്ടുവന്നിരിക്കുന്നു. അപ്പോൾ ഞാൻ എന്റെ വീട്ടിലേക്ക് പോയി. അവിടെ റസൂൽ(സ) ഉണ്ടായിരുന്നു. അന്നേരം മുറിയുടെ ഒരു മൂലയിൽ അബൂയസീദ് - സുഹൈലുബ്നു അംറ് - തന്റെ കൈകൾ പിരടിയിലേക്ക് ബന്ധിക്കപ്പെട്ട് ഇരിക്കുന്നുണ്ടായിരുന്നു. (ദ)', 'سَوْدَةَ', 'സൗദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1012, 1012, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 485, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رِجَالًا مِنَ الْأَنْصَارِ اسْتَأْذَنُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ، ائْذَنْ فَلْنَتْرُكْ لِابْنِ أُخْتِنَا عَبَّاسٍ فِدَاءَهُ، فَقَالَ: "لَا تَدَعُونَ مِنْهَا دِرْهَمًا". (خ)', 'അനസുബ്നു മാലിക്(റ): അൻസാറുകളായ കുറെ ആളുകൾ നബി(സ)യുടെ തിരുസന്നിധിയിൽ വന്ന് അപേക്ഷിച്ചു: ദൈവദൂതരേ, ഞങ്ങളുടെ സഹോദരീപുത്രനായ അബ്ബാസിന് അദ്ദേഹത്തിന്റെ പേരിലുള്ള മോചനദ്രവ്യം ഒഴിവാക്കിക്കൊടുക്കാൻ ഞങ്ങളെ അനുവദിച്ചാലും. തിരുമേനി(സ) അരുളി: "അതിൽനിന്ന് ഒരു ദിർഹം പോലും നിങ്ങൾ ഒഴിവാക്കിക്കൊടുക്കരുത്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1012, 1012, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=171 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 486, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حَدَّثَنِي عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ بَدْرٍ فَأَخَذَ - يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - الْفِدَاءَ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى يُثْخِنَ فِي الْأَرْضِ} إِلَى قَوْلِهِ: {لَمَسَّكُمْ فِيمَا أَخَذْتُمْ} مِنَ الْفِدَاءِ، ثُمَّ أَحَلَّ لَهُمُ اللَّهُ الْغَنَائِمَ. (م,د)', 'ഇബ്നുഅബ്ബാസ്(റ): എന്നോട് ഉമർ(റ) പറഞ്ഞു: ബദ്ർ ദിനത്തിൽ നബി(സ) മോചനദ്രവ്യം സ്വീകരിച്ചു. അപ്പോൾ അല്ലാഹു സൂക്തമിറക്കി. ''ബന്ധികളെ വധിക്കാതെ വെച്ചേക്കുന്നത് ഒരു പ്രവാചകന് നല്ലതല്ല.'' എന്നതു മുതൽ ''നിങ്ങൾ (മോചനദ്രവ്യം) സ്വീകരിച്ചതിൽ ശിക്ഷ ലഭിക്കുമായിരുന്നു.'' എന്നത് വരെ. പിന്നീട് അല്ലാഹു അവർക്ക് യുദ്ധമുതൽ അനുവദനീയമാക്കി. (മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 1012, 1013, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 487, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعَلَ فِدَاءَ أَهْلِ الْجَاهِلِيَّةِ يَوْمَ بَدْرٍ أَرْبَعَ مِائَةٍ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ജാഹിലിയ്യക്കാരുടെ മോചന ദ്രവ്യമായി നാനൂറ് ദിർഹമാണ് ബദ്ർ ദിനത്തിൽ നിശ്ചയിച്ചത്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1013, 1013, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 488, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا بَعَثَ أَهْلُ مَكَّةَ فِي فِدَاءِ أَسْرَاهُمْ بَعَثَتْ زَيْنَبُ فِي فِدَاءِ أَبِي الْعَاصِ بِمَالٍ، وَبَعَثَتْ فِيهِ بِقِلَادَةٍ لَهَا كَانَتْ عِنْدَ خَدِيجَةَ أَدْخَلَتْهَا بِهَا عَلَى أَبِي الْعَاصِ، قَالَتْ: فَلَمَّا رَآهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَقَّ لَهَا رِقَّةً شَدِيدَةً، وَقَالَ: "إِنْ رَأَيْتُمْ أَنْ تُطْلِقُوا لَهَا أَسِيرَهَا وَتَرُدُّوا عَلَيْهَا الَّذِي لَهَا". فَقَالُوا: نَعَمْ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ عَلَيْهِ - أَوْ: وَعَدَهُ - أَنْ يُخَلِّيَ سَبِيلَ زَيْنَبَ إِلَيْهِ، وَبَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَيْدَ بْنَ حَارِثَةَ وَرَجُلًا مِنَ الْأَنْصَارِ، فَقَالَ: "كُونَا بِبَطْنِ يَأْجَجَ حَتَّى تَمُرَّ بِكُمَا زَيْنَبُ، فَتَصْحَبَاهَا حَتَّى تَأْتِيَا بِهَا". (د)', 'ആഇശ(റ): മക്കാ നിവാസികൾ തങ്ങളുടെ ബന്ധികൾക്ക് മോചനദ്രവ്യമായി നിശ്ചയിച്ച കൂട്ടത്തിൽ സൈനബ് ബീവി(റ) അബുൽ ആസ്വിന്റെ മോചനത്തിനായി കുറച്ച് സമ്പത്ത് കൊടുത്തയച്ചു. മഹതിയുടെ വിവാഹ സമയത്ത് ഖദീജ(റ) അബുൽ ആസ്വിന് നൽകിയിരുന്ന ഖദീജ(റ)യുടെ മാലയും, അബുൽആസ്വിന്റെ മോചനത്തിനായി മഹതി അതോടൊപ്പം വെച്ചിരുന്നു. ആഇശ(റ) പറയുന്നു: മാല കണ്ടപ്പോൾ നബി(സ)യുടെ മനസ്സലിഞ്ഞു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിചാരിക്കുന്നുവെങ്കിൽ അവളുടെ ബന്ധിയെ മോചിപ്പിക്കുകയും അവളുടേത് അവൾക്ക് തിരിച്ച് കൊടുക്കുകയും ചെയ്തേക്കുക." അപ്പോൾ അവർ പറഞ്ഞു: അതെ. നബി(സ) അബുൽആസ്വിനോട് സൈനബ്(റ)ക്ക് തന്നിലേക്കുള്ള വഴി തുറന്നിടണമെന്ന് കരാർ ചെയ്തിരുന്നു. റസൂൽ(സ) സൈദുബ്നു ഹാരിസ(റ)വിനെയും അൻസാരികളിൽ പെട്ട ഒരാളെയും അയച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ബത്നുയഅ്ജജിൽ തങ്ങുക. അങ്ങനെ സൈനബ് നിങ്ങളുടെ അടുത്ത് വരും. പിന്നെ അവളെ നിങ്ങൾ കൂടെക്കൂട്ടി കൊണ്ടുവരിക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1013, 1013, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 489, 'عَنْ مَرْوَانَ وَالْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ حِينَ جَاءَهُ وَفْدُ هَوَازِنَ مُسْلِمِينَ، فَسَأَلُوهُ أَنْ يَرُدَّ إِلَيْهِمْ أَمْوَالَهُمْ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَعِي مَنْ تَرَوْنَ، وَأَحَبُّ الْحَدِيثِ إِلَيَّ أَصْدَقُهُ، فَاخْتَارُوا: إِمَّا السَّبْيَ وَإِمَّا الْمَالَ". فَقَالُوا: نَخْتَارُ سَبْيَنَا، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَثْنَى عَلَى اللَّهِ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنَّ إِخْوَانَكُمْ هَؤُلَاءِ جَاءُوا تَائِبِينَ، وَإِنِّي قَدْ رَأَيْتُ أَنْ أَرُدَّ إِلَيْهِمْ سَبْيَهُمْ، فَمَنْ أَحَبَّ مِنْكُمْ أَنْ يُطَيِّبَ ذَلِكَ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَكُونَ عَلَى حَظِّهِ حَتَّى نُعْطِيَهُ إِيَّاهُ مِنْ أَوَّلِ مَا يُفِيءُ اللَّهُ عَلَيْنَا فَلْيَفْعَلْ". فَقَالَ النَّاسُ: قَدْ طَيَّبْنَا ذَلِكَ لَهُمْ يَا رَسُولَ اللَّهِ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّا لَا نَدْرِي مَنْ أَذِنَ مِنْكُمْ مِمَّنْ لَمْ يَأْذَنْ، فَارْجِعُوا حَتَّى يَرْفَعَ إِلَيْنَا عُرَفَاؤُكُمْ أَمْرَكُمْ". فَرَجَعَ النَّاسُ، وَكَلَّمَهُمْ عُرَفَاؤُهُمْ فَأَخْبَرُوهُمْ أَنَّهُمْ قَدْ طَيَّبُوا وَأَذِنُوا. (خ,د)', 'മർവാൻ(റ), മിസ്വറുബ്നുമഖ്റമ(റ): ഹവാസാനിലെ സംഘം മുസ്ലിംകളായി നബി(സ)യുടെ അടുത്ത് വന്നു. അവർ നബി(സ)യോട് സമ്പത്ത് തിരിച്ച് നൽകാൻ ആവശ്യപ്പെട്ടു. അപ്പോൾ അവരോട് റസൂൽ(സ) പറഞ്ഞു: "എന്റെ കൂടെ നിങ്ങൾ കാണുന്നവരൊക്കെയുണ്ട്. എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ട സംസാരം സത്യസന്ധമായതാണ്. സമ്പത്തിൽ നിന്നും ബന്ധികളിൽ നിന്നും നിങ്ങൾക്ക് ഇഷ്ടമുള്ളത് തിരഞ്ഞെടുക്കുക." അവർ പറഞ്ഞു: ഞങ്ങൾ ഞങ്ങളുടെ ബന്ധികളെ തിരഞ്ഞെടുത്തിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റു, അല്ലാഹുവിനെ പുകഴ്ത്തി, എന്നിട്ട് പറഞ്ഞു: "നിങ്ങളുടെ ഈ സഹോദരങ്ങൾ പശ്ചാതാപ മനസ്സോടെയാണ് വന്നത്. ഞാനവർക്ക് അവരുടെ ബന്ധികളെ തിരിച്ച് കൊടുക്കാൻ ഉദ്ദേശിക്കുന്നു. ആരെങ്കിലും ഇത് തൃപ്തിപൂർവ്വം ചെയ്യാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവനത് ചെയ്യട്ടെ. ആർക്കെങ്കിലും സ്വന്തം വിഹിതം ലഭിക്കണമെന്നാണെങ്കിൽ അല്ലാഹു നമുക്ക് ആദ്യം നൽകുന്നതിൽ നിന്ന് നാമവന് നൽകും." ജനങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ തൃപ്തിയോടെ നൽകുന്നു. അപ്പോൾ അവരോട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ സമ്മതം നൽകിയവരേയും നൽകാത്തവരേയും നമുക്ക് വേർത്തിരിച്ചറിയില്ല. നിങ്ങൾ മടങ്ങിപ്പോവുക. നിങ്ങളുടെ നേതാക്കൾ നിങ്ങളുടെ വിഷയം നമ്മെ അറിയിക്കട്ടെ." അപ്പോൾ ജനങ്ങൾ മടങ്ങിപ്പോയി. ശേഷം നേതാക്കൾ അവരോട് സംസാരിച്ചു. തങ്ങൾ തൃപ്തിപൂർവ്വം നൽകിയെന്നും സമ്മതം നൽകിയെന്നും അവർ നേതാക്കളെ അറിയിച്ചു. (ബു,ദ)', 'مَرْوَانَ وَالْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മർവാൻ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 1013, 1014, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 490, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا - فِي هَذِهِ الْقِصَّةِ - قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رُدُّوا عَلَيْهِمْ نِسَاءَهُمْ وَأَبْنَاءَهُمْ، فَمَنْ مَسَكَ بِشَيْءٍ مِنْ هَذَا الْفَيْءِ فَإِنَّ لَهُ بِهِ عَلَيْنَا سِتَّ فَرَائِضَ مِنْ أَوَّلِ شَيْءٍ يُفِيئُهُ اللَّهُ عَلَيْنَا". ثُمَّ دَنَا - يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - مِنْ بَعِيرٍ، فَأَخَذَ وَبَرَةً مِنْ سَنَامِهِ، ثُمَّ قَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّهُ لَيْسَ لِي مِنْ هَذَا الْفَيْءِ شَيْءٌ، وَلَا هَذَا". وَرَفَعَ أُصْبُعَيْهِ "إِلَّا الْخُمُسَ، وَالْخُمُسُ مَرْدُودٌ عَلَيْكُمْ، فَأَدُّوا الْخِيَاطَ وَالْمِخْيَطَ". فَقَامَ رَجُلٌ فِي يَدِهِ كُبَّةٌ مِنْ شَعْرٍ، فَقَالَ: أَخَذْتُ هَذِهِ لِأُصْلِحَ بِهَا بَرْذَعَةً لِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا مَا كَانَ لِي وَلِبَنِي عَبْدِ الْمُطَّلِبِ فَهُوَ لَكَ". فَقَالَ: أَمَّا إِذْ بَلَغَتْ مَا أَرَى فَلَا أَرَبَ لِي فِيهَا، وَنَبَذَهَا. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മേൽ പറഞ്ഞ സംഭവത്തിൽ നിന്ന്: റസൂൽ(സ) പറഞ്ഞു: "അവർക്ക് സ്ത്രീകളെയും, കുട്ടികളെയും തിരിച്ച് നൽകുക. ഈ സ്വത്തിൽ നിന്ന് ആരെങ്കിലും എടുക്കാനുദ്ദേശിക്കുന്നുവെങ്കിൽ അതിന് പകരമായി നാം അവന് നമുക്കള്ളാഹു യുദ്ധമുതലായി നൽകുന്ന ആദ്യത്തേതിൽ നിന്ന് ആറു വിഹിതം നൽകും." പിന്നെ നബി(സ) ഒരു ഒട്ടകത്തോട് അടുത്തു. നബി(സ) അതിന്റെ പൂഞ്ഞയിൽ നിന്നൊരു രോമമെടുത്തു. പിന്നെ അവിടന്ന് പറഞ്ഞു: "ഓ ജനങ്ങളേ, എനിക്ക് ഈ സ്വത്തിൽ ഒന്നുമില്ല, ഇതുപോലുമില്ല." നബി(സ) രണ്ട് വിരലുകളുയർത്തിയിട്ട് പറഞ്ഞു: "എനിക്ക് അഞ്ചിലൊന്ന് മാത്രമേയുള്ളൂ, ആ അഞ്ചിലൊന്ന് നിങ്ങളിലേക്ക് തന്നെ മടക്കപ്പെടുന്നതാണ്. അതിനാൽ സൂചിയും നൂലും നിങ്ങൾ തിരികെ നൽകുക." അപ്പോൾ ഒരാൾ രോമകൂമ്പാരം കയ്യിലെടുത്തുകൊണ്ട് പറഞ്ഞു: ഒട്ടകപ്പുറത്തെ വിരി ഉണ്ടാക്കാൻ വേണ്ടിയാണ് ഞാൻ ഇതെടുത്തത്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എനിക്കും അബ്ദുൽ മുത്വലിബിന്റെ സന്താനങ്ങൾക്കുമുള്ളത് നിനക്കുള്ളതാണ്." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാൻ കാണുന്നയത്രയും അതുണ്ടെങ്കിൽ പിന്നെ എനിക്കതിൽ ആവശ്യമില്ല. അയാൾ രോമങ്ങൾ നിലത്തിട്ടു. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1014, 1014, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 491, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْلًا قِبَلَ نَجْدٍ، فَجَاءَتْ بِرَجُلٍ مِنْ بَنِي حَنِيفَةَ يُقَالُ لَهُ: ثُمَامَةُ بْنُ أُثَالٍ سَيِّدُ أَهْلِ الْيَمَامَةِ، فَرَبَطُوهُ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، فَخَرَجَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: "مَاذَا عِنْدَكَ يَا ثُمَامَةُ". فَقَالَ: عِنْدِي يَا مُحَمَّدُ خَيْرٌ، إِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ، وَإِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ، وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ. فَتَرَكَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى كَانَ بَعْدَ الْغَدِ، فَقَالَ: "مَا عِنْدَكَ يَا ثُمَامَةُ". قَالَ: مَا قُلْتُ لَكَ: إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ، وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ، وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ. فَتَرَكَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى كَانَ مِنَ الْغَدِ، فَقَالَ: "مَاذَا عِنْدَكَ يَا ثُمَامَةُ". فَقَالَ: عِنْدِي مَا قُلْتُ لَكَ: إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ، وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ، وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَطْلِقُوا ثُمَامَةَ". فَانْطَلَقَ إِلَى نَخْلٍ قَرِيبٍ مِنَ الْمَسْجِدِ فَاغْتَسَلَ، ثُمَّ دَخَلَ الْمَسْجِدَ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، يَا مُحَمَّدُ، وَاللَّهِ مَا كَانَ عَلَى الْأَرْضِ [وَجْهٌ] أَبْغَضَ إِلَيَّ مِنْ وَجْهِكَ، فَقَدْ أَصْبَحَ وَجْهُكَ أَحَبَّ الْوُجُوهِ كُلِّهَا إِلَيَّ، وَاللَّهِ مَا كَانَ مِنْ دِينٍ أَبْغَضَ إِلَيَّ مِنْ دِينِكَ، فَأَصْبَحَ دِينُكَ أَحَبَّ الدِّينِ كُلِّهِ إِلَيَّ، وَاللَّهِ مَا كَانَ مِنْ بَلَدٍ أَبْغَضَ إِلَيَّ مِنْ بَلَدِكَ، فَأَصْبَحَ بَلَدُكَ أَحَبَّ الْبِلَادِ كُلِّهَا إِلَيَّ، وَإِنَّ خَيْلَكَ أَخَذَتْنِي وَأَنَا أُرِيدُ الْعُمْرَةَ، فَمَاذَا تَرَى؟ فَبَشَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَرَهُ أَنْ يَعْتَمِرَ، فَلَمَّا قَدِمَ مَكَّةَ، قَالَ لَهُ قَائِلٌ: أَصَبَوْتَ؟ فَقَالَ: لَا، وَلَكِنِّي أَسْلَمْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا وَاللَّهِ لَا يَأْتِيكُمْ مِنَ الْيَمَامَةِ حَبَّةُ حِنْطَةٍ حَتَّى يَأْذَنَ فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) കുറച്ച് കുതിരപ്പടയാളികളെ നജ്ദിന്റെ ഭാഗത്തേക്ക് പറഞ്ഞയച്ചു. അങ്ങനെ ബനൂഹനീഫയിൽപെട്ട യമാമ ഗോത്രത്തിന്റെ നേതാവായ സുമാമതുബ്നു ഉസാൽ എന്നയാളെ അവർ കൊണ്ടുവരികയും പള്ളിയിലെ തൂണുകളിലൊന്നിൽ ബന്ധിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) അവിടേക്ക് വന്നു. അദ്ദേഹത്തോട് ചോദിച്ചു: "നിന്റെയടുത്ത് എന്താണുള്ളത്, സുമാമ". അദ്ദേഹം പറഞ്ഞു: മുഹമ്മദേ, എന്റെയടുത്ത് നന്മയുണ്ട്. താങ്കൾ വധിക്കുകയാണെങ്കിൽ രക്തമുള്ളവനെയാണ് വധിക്കുന്നത്, താങ്കൾ അനുഗ്രഹം ചെയ്യുകയാണെങ്കിൽ, നന്ദിചെയ്യുന്നവന്നാണ് താങ്കൾ അനുഗ്രഹം ചെയ്യുന്നത്. ഇനി ധനമാണ് താങ്കൾ ഉദ്ദേശിക്കുന്നതെങ്കിൽ ചോദിക്കൂ, വേണ്ടത്ര നൽകാം. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ ഒഴിവാക്കി. പിറ്റേ ദിവസമായപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "നിന്റെയടുക്കൽ എന്താണെന്നുള്ളത്, സുമാമ?" അദ്ദേഹം പറഞ്ഞു: എന്റെയടുത്ത് താങ്കളോട് ഞാൻ പറഞ്ഞതേയുള്ളൂ. താങ്കൾ അനുഗ്രഹം ചെയ്യുകയാണെങ്കൽ നന്ദി ചെയ്യുന്നവന്നാണ് അനുഗ്രഹം ചെയ്യുന്നത്. താങ്കൾ വധിക്കുകയാണെങ്കിൽ രക്തമുള്ളവനെയാണ് വധിക്കുന്നത്. ഇനി ധനമാണ് താങ്കൾ ഉദ്ദേശിക്കുന്നതെങ്കിൽ ചോദിക്കൂ, വേണ്ടത്ര നൽകാം. അപ്പോഴും റസൂൽ(സ) അദ്ദേഹത്തെ ഒഴിവാക്കി. പിറ്റേ ദിവസം വന്ന് നബി(സ) ചോദിച്ചു: "നിന്റെയടുത്ത് എന്താണുള്ളത്, സുമാമ?" അദ്ദേഹം പറഞ്ഞു: എന്റെയടുത്ത് താങ്കളോട് പറഞ്ഞത് മാത്രമാണുള്ളത്. താങ്കൾ അനുഗ്രഹം ചെയ്യുകയാണെങ്കൽ നന്ദി ചെയ്യുന്നവന്നാണ് അനുഗ്രഹം ചെയ്യുന്നത്. താങ്കൾ വധിക്കുകയാണെങ്കിൽ രക്തമുള്ളവനെയാണ് വധിക്കുന്നത്. ഇനി ധനമാണ് താങ്കൾ ഉദ്ദേശിക്കുന്നതെങ്കിൽ ചോദിക്കൂ, വേണ്ടത്ര നൽകാം. റസൂൽ(സ) പറഞ്ഞു: "സുമാമയെ മോചിപ്പക്കുക." അങ്ങനെ അദ്ദേഹം പള്ളിയുടെ അടുത്തുള്ള ഒരു ഈത്തപ്പനത്തോട്ടത്തിൽ പോയി കുളിച്ചു, പള്ളിയിൽ വന്നു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതരുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. ഓ മുഹമ്മദേ, അല്ലാഹുവാണ് സത്യം, ഈ ഭൂമുഖത്ത് താങ്കളുടെ മുഖത്തേക്കാൾ എനിക്ക് ദേഷ്യമുള്ള വേറെയൊരു മുഖവുമുണ്ടായിരുന്നില്ല. ഇപ്പോൾ അവിടത്തെ മുഖം എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ട മുഖമായിരിക്കുന്നു. അല്ലാഹുവാണ് സത്യം, അവിടത്തെ മതത്തേക്കാൾ എനിക്ക് വെറുപ്പുള്ള ഒരു മതവും ഉണ്ടായിരുന്നില്ല, പക്ഷേ, ഇന്ന് അങ്ങയുടെ മതം എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ട മതമായി മാറിയിരിക്കുന്നു. അല്ലാഹുവാണ് സത്യം, താങ്കളുടെ നാടിനേക്കാൾ എനിക്ക് ദേഷ്യമുള്ള ഒരു നാടുമുണ്ടായിരുന്നില്ല. പക്ഷേ, ഇന്ന് അങ്ങയുടെ നാട് എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ട നാടായി മാറിയിരിക്കുന്നു. ഞാൻ ഉംറ ഉദ്ദേശിച്ച് പോകുമ്പോഴായിരുന്നു അങ്ങയുടെ സൈന്യം എന്നെ പിടികൂടിയത്, ഇനി എന്തു ചെയ്യണമെന്നാണ് അങ്ങയുടെ അഭിപ്രായം? അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ സന്തോഷവാർത്തയറിയിക്കുകയും ഉംറ ചെയ്യാൻ കൽപിക്കുകയും ചെയ്തു. അങ്ങനെ അദ്ദേഹം മക്കയിലെത്തിയപ്പോൾ ഒരാൾ ചോദിച്ചു: നീ മതം മാറിയോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല, മറിച്ച് ഞാൻ റസൂൽ(സ)യുടെ കൂടെ മുസ്ലിമായി. അല്ലാഹുവാണ് സത്യം, യമാമയിൽ നിന്ന് ഒരു ഗോതമ്പ് ധാന്യം പോലും റസൂൽ(സ)യുടെ അനുവാദമില്ലാതെ ഇനി നിങ്ങളിലേക്ക് എത്തുകയില്ല. (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], 'وَجْهٌ', null, 1014, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 492, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ ثَمَانِينَ رَجُلًا مِنْ أَهْلِ مَكَّةَ هَبَطُوا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ مِنْ جِبَالِ التَّنْعِيمِ عِنْدَ صَلَاةِ الْفَجْرِ لِيَقْتُلُوهُمْ، فَأَخَذَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِلْمًا، فَأَعْتَقَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ مَكَّةَ} إِلَى آخِرِ الْآيَةِ. (م,د,ت)', 'അനസ്(റ): മക്കക്കാരായ എൺപത് ആളുകൾ നബി(സ)യെയും അനുചരന്മാരെയും വധിക്കാൻ വേണ്ടി തൻഈം മലയുടെ ഭാഗത്തുനിന്ന് സ്വുബ്ഹ് നിസ്കാര സമയത്ത് ചാടിവീണു. അവരെ റസൂൽ(സ) ബന്ധികളാക്കി പിടിച്ചു. പിന്നെ നബി(സ) അവരെ മോചിപ്പിച്ചു. അപ്പോൾ അല്ലാഹു ഈ സൂക്തം ഇറക്കി: ''മക്കയിൽ വെച്ച് അവരുടെ കരങ്ങളെ നിങ്ങളിൽ നിന്നും നിങ്ങളുടെ കരങ്ങളെ അവരിൽ നിന്നും തടഞ്ഞുവെച്ചവനാണ് അവൻ.'' ഈ സൂക്തത്തിന്റെ അവസാനം വരെ. (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 1016, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 493, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأُسَارَى بَدْرٍ: "لَوْ كَانَ مُطْعِمُ بْنُ عَدِيٍّ حَيًّا، ثُمَّ كَلَّمَنِي فِي هَؤُلَاءِ النَّتْنَى، لَأَطْلَقْتُهُمْ لَهُ". (خ,د)', 'ജുബൈറുബ്നു മുത്ഇം(റ): നബി(സ) ബദ്റിലെ ബന്ധികളെക്കുറിച്ച് പറഞ്ഞു: "മുത്ഇമുബിനു അദിയ്യ് ജീവിച്ചിരിക്കുകയും ഈ ദുഷ്ടരുടെ വിഷയത്തിൽ എന്നോട് സംസാരിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ ഞാൻ അദ്ദേഹത്തിനുവേണ്ടി ഇവരെ വെറുതെ വിടുമായിരുന്നു." (ബു,ദ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 1016, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 494, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فُكُّوا الْعَانِيَ يَعْنِي الْأَسِيرَ، وَأَطْعِمُوا الْجَائِعَ، وَعُودُوا الْمَرِيضَ". (خ)', 'അബുമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ബന്ധിയെ മോചിപ്പിക്കുക, വിശന്നവന് ഭക്ഷണം നൽകുക, രോഗിയെ സന്ദർശിക്കുക." (ബു)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1016, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 495, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ لِعَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: هَلْ عِنْدَكُمْ شَيْءٌ مِنَ الْوَحْيِ إِلَّا مَا فِي كِتَابِ اللَّهِ، فَقَالَ: لَا وَالَّذِي فَلَقَ الْحَبَّةَ وَبَرَأَ النَّسَمَةَ، مَا أَعْلَمُهُ إِلَّا فَهْمًا يُعْطِيهِ اللَّهُ رَجُلًا فِي الْقُرْآنِ وَمَا فِي هَذِهِ الصَّحِيفَةِ، قُلْتُ: وَمَا فِي الصَّحِيفَةِ؟ قَالَ: الْعَقْلُ، وَفَكَاكُ الْأَسِيرِ، وَأَنْ لَا يُقْتَلَ مُسْلِمٌ بِكَافِرٍ. (خ)', 'അബൂജുഹൈഫ(റ): ഞാൻ അലി(റ)വിനോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലില്ലാത്ത വല്ലതും ദൈവിക സന്ദേശമായി താങ്കളുടെ പക്കലുണ്ടോ? അലി(റ) പറഞ്ഞു: ഇല്ല, വിത്ത് മുളപ്പിച്ചവനും മനുഷ്യനെ സൃഷ്ടിച്ചവനുമായ അല്ലാഹുവാണ് സത്യം. ഈ ഏടിലുള്ളതും ഒരാൾക്ക് അല്ലാഹു നൽകുന്ന ഖുർആനിലുള്ള ബുദ്ധിയും ഒഴികെ വല്ലതുമുള്ളതായി എന്റെ അറിവിലില്ല. ഞാൻ ചോദിച്ചു: ഈ ഏടിൽ എന്താണുള്ളത്? അലി(റ) പറഞ്ഞു: "നഷ്ടപരിഹാരം, ബന്ധികളെ മോചിപ്പിക്കൽ, സത്യനിഷേധിക്ക് പകരമായി ഒരു സത്യവിശ്വാസിയെ വധിക്കാൻ പാടില്ല എന്നിവയാണ് ഈ ഏടിലുള്ളത്. (ബു)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1016, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 496, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَدَبَ أَصْحَابَهُ، فَانْطَلَقُوا إِلَى بَدْرٍ، فَإِذَا هُمْ بِرَوَايَا قُرَيْشٍ فِيهَا عَبْدٌ أَسْوَدُ لِبَنِي الْحَجَّاجِ، فَأَخَذَهُ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلُوا يَسْأَلُونَهُ: أَيْنَ أَبُو سُفْيَانَ؟ فَيَقُولُ: وَاللَّهِ مَالِي بِشَيْءٍ مِنْ أَمْرِهِ عِلْمٌ، وَلَكِنْ هَذِهِ قُرَيْشٌ قَدْ جَاءَتْ فِيهِمْ أَبُو جَهْلٍ وَعُتْبَةُ وَشَيْبَةُ ابْنَا رَبِيعَةَ، وَأُمَيَّةُ بْنُ خَلَفٍ. فَإِذَا قَالَ لَهُمْ ذَلِكَ ضَرَبُوهُ، فَيَقُولُ: دَعُونِي دَعُونِي أُخْبِرْكُمْ، فَإِذَا تَرَكُوهُ قَالَ: وَاللَّهِ مَالِي بِأَبِي سُفْيَانَ مِنْ عِلْمٍ، وَلَكِنْ هَذِهِ قُرَيْشٌ قَدْ أَقْبَلَتْ فِيهِمْ أَبُو جَهْلٍ وَعُتْبَةُ وَشَيْبَةُ ابْنَا رَبِيعَةَ، وَأُمَيَّةُ بْنُ خَلَفٍ قَدْ أَقْبَلُوا. وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَهُوَ يَسْمَعُ ذَلِكَ، فَلَمَّا انْصَرَفَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّكُمْ لَتَضْرِبُونَهُ إِذَا صَدَقَكُمْ، وَتَدَعُونَهُ إِذَا كَذَبَكُمْ، هَذِهِ قُرَيْشٌ قَدْ أَقْبَلَتْ لِتَمْنَعَ أَبَا سُفْيَانَ". قَالَ أَنَسٌ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا مَصْرَعُ فُلَانٍ غَدًا". وَوَضَعَ يَدَهُ عَلَى الْأَرْضِ "وَهَذَا مَصْرَعُ فُلَانٍ غَدًا". وَوَضَعَ يَدَهُ عَلَى الْأَرْضِ "وَهَذَا مَصْرَعُ فُلَانٍ غَدًا". وَوَضَعَ يَدَهُ عَلَى الْأَرْضِ، فَقَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، مَا جَاوَزَ أَحَدٌ مِنْهُمْ عَنْ مَوْضِعِ يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ بِهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُخِذَ بِأَرْجُلِهِمْ، فَسُحِبُوا، فَأُلْقُوا فِي قَلِيبِ بَدْرٍ. (م,د)', 'അനസ്(റ): റസൂൽ(സ) തന്റെ അനുചരന്മാരെ യുദ്ധസജ്ജരാക്കി. അങ്ങനെ അവർ ബദ്റിലേക്ക് പോയി, ഖുറൈശികളുടെ ഒട്ടകങ്ങളുടെ അടുത്തെത്തി. അതിൽ ബനുൽഹജ്ജാജ് ഗോത്രക്കാരുടെ ഒരു കറുത്ത അടിമയുമുണ്ട്. അവനെ റസൂൽ(സ)യുടെ അനുചരന്മാർ പിടിച്ചു ഇപ്രകാരം ചോദിക്കാൻ തുടങ്ങി: അബൂസുഫ്യാൻ എവിടെ? അവൻ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അദ്ദേഹത്തെക്കുറിച്ച് ഒരു അറിവും എനിക്കില്ല, മറിച്ച് ഇത് ഖുറൈശികളാണ്. അവരിൽ അബൂജഹലും റബീഅയുടെ മക്കളായ ഉത്ബതും ശൈബതും ഉമയ്യതുബ്നു ഖലഫും ഉണ്ട്. അത് പറയുമ്പോൾ അവർ അവനെ അടിക്കുമായിരുന്നു. അപ്പോൾ അവൻ പറയും: എന്നെ വെറുതെ വിടുക, ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരാം. അങ്ങനെ അവനെ ഒഴിവാക്കിയാൽ അവൻ പറയും: അബൂസുഫ്യാനെക്കുറിച്ച് എനിക്കൊന്നും അറിയില്ല. പക്ഷേ, ഇത് ഖുറൈശികളാകുന്നു. അബൂ ജഹലും റബീഅയുടെ മക്കളായ ഉത്ബതും ശൈബതും ഉമയ്യതുബ്നു ഖലഫും അവരോടൊപ്പം വന്നിട്ടുണ്ട്. അന്നേരം നബി(സ) നിസ്കരിക്കുകയായിരുന്നു. അവിടന്ന് ഇതെല്ലാം കേൾക്കുന്നുണ്ടായിരുന്നു. അങ്ങനെ നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം, നിങ്ങളോട് സത്യം പറയുമ്പോൾ അവനെ നിങ്ങൾ അടിക്കുന്നു, കള്ളം പറയുമ്പോൾ അവനെ വെറുതെ വിടുന്നു. ഇത് ഖുറൈശികളാണ്, അവർ അബൂസുഫ്യാനുവേണ്ടി പ്രതിരോധിക്കാൻ വന്നതാണ്." അനസ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നു: "നാളെ ഈ സ്ഥലം ഇന്നയാൾ വീഴുന്ന സ്ഥലമാണ്." അവിടുന്ന് തന്റെ കൈ നിലത്ത് വെച്ചു. "ഇത് ഇന്നവൻ നാളെ വീഴുന്ന സ്ഥലമാണ്." അവിടുന്ന് തന്റെ കൈ നിലത്ത് വെച്ചു. "ഇത് ഇന്നയാൾ നാളെ വീഴുന്ന സ്ഥലമാണ്." അവിടുന്ന് തന്റെ കൈ ഭൂമിയിൽ വെച്ചു. നിവേദകൻ പറയുന്നു: എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം, റസൂൽ(സ)യുടെ കൈ വെച്ച സ്ഥലം അവരിൽ നിന്നാരും മറികടന്നിട്ടില്ലായിരുന്നു. അങ്ങനെ റസൂൽ(സ) ആജ്ഞാപിച്ചതു പ്രകാരം അവരുടെയെല്ലാം (ബദ്റിൽ വധിക്കപ്പെട്ട ശത്രുക്കൾ) കാല് പിടിച്ച് വലിച്ച് അവരെ ബദ്റിലെ കിണറ്റിലിട്ടു. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 1017, 1017, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 497, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتِ الْمَرْأَةُ تَكُونُ مِقْلَاتًا فَتَجْعَلُ عَلَى نَفْسِهَا إِنْ عَاشَ لَهَا وَلَدٌ أَنْ تُهَوِّدَهُ، فَلَمَّا أُجْلِيَتْ بَنُو النَّضِيرِ كَانَ فِيهِمْ مِنْ أَبْنَاءِ الْأَنْصَارِ، فَقَالُوا: لَا نَدَعُ أَبْنَاءَنَا، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {لَا إِكْرَاهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ} [البقرة: ٢٥٦]. قَالَ أَبُو دَاوُدَ: الْمِقْلَاتُ الَّتِي لَا يَعِيشُ لَهَا وَلَدٌ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): കുട്ടികൾ വളരാത്ത സ്ത്രീ തനിക്ക് ഒരു കുട്ടി വളർന്നാൽ അതിനെ ജൂതനാക്കി മാറ്റും എന്ന് സത്യം ചെയ്യുന്ന പതിവുണ്ടായിരുന്നു. അങ്ങനെ ബനുന്നളീർ ഗേത്രക്കാർ ആട്ടിയോടിക്കപ്പെട്ടപ്പോൾ അവരിൽ അൻസാരികളുടെ മക്കളുമുണ്ടായിരുന്നു. അപ്പോൾ അൻസാറുകൾ പറഞ്ഞു: ഞങ്ങളുടെ മക്കളെ ഞങ്ങൾ ഒഴിവാക്കുകയില്ല. അപ്പോൾ അല്ലാഹു ഈ സൂക്തം ഇറക്കി. ''ദീനിൽ നിർബന്ധിക്കലില്ല. സന്മാർഗ്ഗം ദുർമാർഗ്ഗത്തിൽ നിന്നും വ്യക്തമായിരിക്കുന്നു.'' (അൽബഖറ: 256) അബൂദാവൂദ്(റ) പറയുന്നു: ''മിഖ്ലാത്'' എന്നാൽ സന്താനങ്ങളുണ്ടാവാത്ത സ്ത്രീയാണ്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة: ٢٥٦', null, 1017, 1018, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=174 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 498, 'عَنْ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ فَتْحِ مَكَّةَ أَمَّنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ إِلَّا أَرْبَعَةَ نَفَرٍ وَامْرَأَتَيْنِ، وَسَمَّاهُمْ، وَابْنُ أَبِي سَرْحٍ، قَالَ: وَأَمَّا ابْنُ أَبِي سَرْحٍ فَإِنَّهُ اخْتَبَأَ عِنْدَ عُثْمَانَ بْنِ عَفَّانَ، فَلَمَّا دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ إِلَى الْبَيْعَةِ جَاءَ بِهِ حَتَّى أَوْقَفَهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا نَبِيَّ اللَّهِ، بَايِعْ عَبْدَ اللَّهِ. فَرَفَعَ رَأْسَهُ، فَنَظَرَ إِلَيْهِ ثَلَاثًا، كُلُّ ذَلِكَ يَأْبَى، فَبَايَعَهُ بَعْدَ ثَلَاثٍ، ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ: "أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ، يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ فَيَقْتُلُهُ". فَقَالُوا: مَا نَدْرِي يَا رَسُولَ اللَّهِ مَا فِي نَفْسِكَ، أَلَا أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ؟ قَالَ: "إِنَّهُ لَا يَنْبَغِي لِنَبِيٍّ أَنْ تَكُونَ لَهُ خَائِنَةُ الْأَعْيُنِ". قَالَ أَبُو دَاوُدَ: كَانَ عَبْدُ اللَّهِ أَخَا عُثْمَانَ مِنَ الرَّضَاعَةِ، وَكَانَ الْوَلِيدُ بْنُ عُقْبَةَ أَخَا عُثْمَانَ لِأُمِّهِ، وَضَرَبَهُ عُثْمَانُ الْحَدَّ إِذْ شَرِبَ الْخَمْرَ. (د,ن)', 'സഅ്ദ്(റ): മക്കാ വിജയദിവസം റസൂൽ(സ) പേരെടുത്തു പറഞ്ഞ നാലു പേർക്കും രണ്ടു സ്ത്രീകൾക്കും ഇബ്നു അബീസർഹിനും ഒഴികെ എല്ലാവർക്കും തിരുമേനി(സ) അഭയം നൽകി. നിവേദകൻ പറയുന്നു: ഇബ്നു അബീസർഹ് ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വിന്റെയടുക്കൽ ഒളിഞ്ഞിരുന്നു. അങ്ങനെ റസൂൽ(സ) ബൈഅത്തിനുവേണ്ടി ജനങ്ങളെ വിളിച്ചപ്പോൾ ഉസ്മാൻ(റ) അയാളെ കൊണ്ടുവന്ന് നബി(സ)യുടെ മുന്നിൽ നിർത്തി, എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അബ്ദുല്ലാക്ക് ബൈഅത്ത് കൊടുത്താലും. റസൂൽ(സ) തലയുയർത്തി അവനെ മൂന്ന് പ്രാവശ്യം നോക്കി. എല്ലാ നോട്ടവും വിസമ്മതത്തിന്റേതായിരുന്നു. മൂന്നാമത്തേതിന്റെ ശേഷം ബൈഅത്ത് കൊടുത്തു. പിന്നെ അവിടത്തെ അനുചരന്മാരോട് പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ ബൈഅത്ത് ഞാൻ തടഞ്ഞുവെക്കുമ്പോൾ അവനെ കൊല്ലണമെന്ന് മനസ്സിലാക്കാൻ ബുദ്ധിയുള്ള ആരും നിങ്ങളുടെ കൂട്ടത്തിലുണ്ടായില്ലേ?" അപ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ മനസ്സിലുള്ളത് ഞങ്ങൾ അറിഞ്ഞിരുന്നില്ല. അങ്ങ് കണ്ണുകൊണ്ട് ആംഗ്യം കാണിച്ചിരുന്നെങ്കിൽ? റസൂൽ(സ) പറഞ്ഞു: "വഞ്ചനയോടെയുള്ള നോട്ടം ഒരു പ്രവാചകനും യോജിച്ചതല്ല." അബൂദാവൂദ്(റ) പറഞ്ഞു: അബ്ദുല്ല ഉസ്മാൻ(റ)വിന്റെ മുലകുടി ബന്ധത്തിലുള്ള സഹോദരനായിരുന്നു. വലീദുബ്നു ഉഖ്ബ ഉസ്മാൻ(റ)വിന്റെ ഉമ്മയൊത്ത സഹോദരനായിരുന്നു. മദ്യപിച്ചതിന്റെ പേരിൽ ഉസ്മാൻ(റ) അദ്ദേഹത്തെ ഹദ്ദടിച്ചിരുന്നു. (ദ,ന)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 1018, 1018, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 499, 'عَنْ سَعِيدِ بْنِ يَرْبُوعٍ الْمَخْزُومِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ فَتْحِ مَكَّةَ: "أَرْبَعَةٌ لَا أُؤَمِّنُهُمْ فِي حِلٍّ وَلَا حَرَمٍ". فَسَمَّاهُمْ، قَالَ: وَقَيْنَتَيْنِ كَانَتَا لِمِقْيَسٍ، فَقُتِلَتْ إِحْدَاهُمَا، وَأَفْلَتَتِ الْأُخْرَى فَأَسْلَمَتْ. (د)', 'സഈദുബ്നു യർബൂഇൽ മഖ്സൂമി(റ): റസൂൽ(സ) ഫത്ഹ് മക്കയുടെ ദിനത്തിൽ പറഞ്ഞു: "നാലു പേർക്ക് ഹറമിൽ നിന്നോ അതിന്റെ പുറം പ്രദേശത്ത് നിന്നോ ഞാൻ അഭയം നൽകുകയില്ല." എന്നിട്ട് റസൂൽ(സ) അവരുടെ പേര് പറഞ്ഞു. നിവേദകൻ പറയുന്നു: മിഖ്യസിന്റെ രണ്ട് അടിമസ്ത്രീകൾക്കും അവിടുന്ന് അഭയം നൽകിയില്ല. അവരിൽ ഒരാൾ കൊല്ലപ്പെട്ടു. രണ്ടാമത്തവൾ രക്ഷപ്പെടുകയും ശേഷം മുസ്ലിമാവുകയും ചെയ്തു. (ദ)', 'سَعِيدِ بْنِ يَرْبُوعٍ الْمَخْزُومِيِّ', 'സഈദുബ്നു യർബൂഇൽ മഖ്സൂമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1018, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 500, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ الْمِغْفَرُ، فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ فَقَالَ: ابْنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ؟ فَقَالَ: "اقْتُلُوهُ". (ق,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): മക്കാവിജയ വർഷം റസൂൽ(സ) അവിടത്തെ ശിരസ്സിൽ ഇരുമ്പ് തൊപ്പിയണിഞ്ഞ് മക്കയിൽ പ്രവേശിച്ചു. അവിടന്ന് അത് ഊരിവെച്ചപ്പോൾ ഒരാൾ വന്നു പറഞ്ഞു: ഇബ്നുഖതൽ കഅ്ബയുടെ വിരികളിൽ പിടിച്ചു നിൽക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അവനെ വധിച്ച് കളയുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 1019, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 501, 'عَنْ إِبْرَاهِيمَ النَّخَعِيِّ قَالَ: أَرَادَ الضَّحَّاكُ بْنُ قَيْسٍ أَنْ يَسْتَعْمِلَ مَسْرُوقًا، فَقَالَ لَهُ عُمَارَةُ بْنُ عُقْبَةَ: أَتَسْتَعْمِلُ رَجُلًا مِنْ بَقَايَا قَتَلَةِ عُثْمَانَ؟ فَقَالَ لَهُ مَسْرُوقٌ: حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْعُودٍ - وَكَانَ فِي أَنْفُسِنَا مَوْثُوقَ الْحَدِيثِ - أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَرَادَ قَتْلَ أَبِيكَ قَالَ: مَنْ لِلصِّبْيَةِ؟ قَالَ: "النَّارُ". فَقَدْ رَضِيتُ لَكَ مَا رَضِيَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ഇബ്റാഹീമുന്നഖഈ(റ): ളഹ്ഹാകുബ്നു ഖൈസ്(റ) മസ്റൂഖിനെ ഉദ്യോഗമേൽപിക്കാൻ ഉദ്ദേശിച്ചപ്പോൾ ഉമാറതുബ്നു ഉഖ്ബ അദ്ദേഹത്തോട് ചോദിച്ചു: ഉസ്മാൻ(റ)വിന്റെ ഘാതകരിൽ പെട്ടയാളെയാണോ താങ്കൾ ഉദ്യോഗമേൽപിക്കുന്നത്? അപ്പോൾ മസ്റൂഖ് അദ്ദേഹത്തോട് പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) ഞങ്ങൾക്ക് ഇപ്രകാരം പറഞ്ഞുതന്നു - അദ്ദേഹം ഞങ്ങളുടെ പക്കൽ ഹദീസ് സ്വീകരിക്കപ്പെടുന്ന വ്യക്തിയാണ് -: നിന്റെ പിതാവിനെ വധിക്കാൻ നബി(സ) ഉദ്ദേശിച്ചപ്പോൾ അബ്ദുല്ല(റ) ചോദിച്ചു: അദ്ദേഹത്തിന്റെ സന്താനങ്ങൾക്ക് ആരാണുള്ളത്? നബി(സ) പറഞ്ഞു: "നരകം." റസൂൽ(സ) നിനക്ക് ആഗ്രഹിച്ചതു തന്നെ ഞാനും നിനക്ക് തൃപ്തിപ്പെട്ടിരിക്കുന്നു. (ദ)', 'إِبْرَاهِيمَ النَّخَعِيِّ قَالَ', 'ഇബ്റാഹീമുന്നഖഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1019, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 502, 'عَنْ عُبَيْدِ بْنِ تِعْلَى قَالَ: غَزَوْنَا مَعَ عَبْدِ الرَّحْمَنِ بْنِ خَالِدِ بْنِ الْوَلِيدِ، فَأُتِيَ بِأَرْبَعَةِ أَعْلَاجٍ مِنَ الْعَدُوِّ، فَأَمَرَ بِهِمْ فَقُتِلُوا صَبْرًا. فَبَلَغَ ذَلِكَ أَبَا أَيُّوبَ الْأَنْصَارِيَّ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ قَتْلِ الصَّبْرِ، فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَتْ دَجَاجَةً مَا صَبَرْتُهَا. فَبَلَغَ ذَلِكَ عَبْدَ الرَّحْمَنِ بْنَ خَالِدِ بْنِ الْوَلِيدِ فَأَعْتَقَ أَرْبَعَ رِقَابٍ. (د)', 'ഉബൈദുബ്നു തിഅ്ല(റ): ഖാലിദുബ്നു വലീദ്(റ)വിന്റെ മകൻ അബ്ദുർറഹ്മാൻ(റ)വിന്റെ കൂടെ ഞങ്ങൾ യുദ്ധം ചെയ്തു. അങ്ങനെ ശതുക്കളിൽ നിന്ന് നാല് ശക്തന്മാരെ കൊണ്ടുവരപ്പെടുകയും അവരെ വധിക്കാൻ അദ്ദേഹം കൽപിക്കുകയും അവർ ജീവനോടെ എറിഞ്ഞു കൊല്ലപ്പെടുകയും ചെയ്തു. ഈ വിഷയം അബൂഅയ്യൂബുൽ അൻസ്വാരി(റ)വിന്റെയടുത്ത് എത്തി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇങ്ങനെ കൊല്ലുന്നതിനെ നിരോധിച്ചതായി റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. അതുകൊണ്ട് എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, അത് ഒരു കോഴിയാണെങ്കിലും ഞാൻ ക്ഷമിക്കുകയില്ല. ഈ വിവരം ഖാലിദുബ്നു വലീദ്(റ)വിന്റെ മകൻ അബ്ദുർറഹ്മാൻ(റ) അറിഞ്ഞു. അപ്പോൾ അദ്ദേഹം നാല് അടിമകളെ മോചിപ്പിച്ചു. (ദ)', 'عُبَيْدِ بْنِ تِعْلَى قَالَ', 'ഉബൈദുബ്നു തിഅ്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1019, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 503, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ جِبْرَائِيلَ هَبَطَ عَلَيْهِ فَقَالَ لَهُ: خَيِّرْهُمْ - يَعْنِي - أَصْحَابَكَ فِي أُسَارَى بَدْرٍ: الْقَتْلَ، أَوِ الْفِدَاءَ، عَلَى أَنْ يُقْتَلَ مِنْهُمْ قَابِلًا مِثْلُهُمْ". قَالُوا: الْفِدَاءَ وَيُقْتَلُ مِنَّا. (ت)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ജിബ്രീൽ(അ) അവിടത്തെയടുത്ത് ഇറങ്ങിക്കൊണ്ട് പറഞ്ഞു: ബദ്റിലെ ബന്ധികളുടെ വിഷയത്തിൽ അങ്ങ് അവിടത്തെ അനുചരരോട് ഇഷ്ടാനുസരണം ചെയ്യാൻ പറയുക. ഒന്നുകിൽ വധിക്കുക. അല്ലെങ്കിൽ അടുത്ത വർഷം അവരിൽ നിന്ന് അത്രയും ആളുകൾ വധിക്കപ്പെടുമെന്ന നിബന്ധനയോടെ മോചനദ്രവ്യം സ്വീകരിക്കുക." അവർ പറഞ്ഞു: മോചനദ്രവ്യം വാങ്ങുകയും, ഞങ്ങളിൽ നിന്ന് വധിക്കപ്പെടുകയും ചെയ്യുക. (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1020, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 504, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَى رَجُلَيْنِ مِنَ الْمُسْلِمِينَ بِرَجُلٍ مِنَ الْمُشْرِكِينَ. (ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) മുശ്രിക്കുകളിൽ പെട്ട ഒരാളെ രണ്ട് മുസ്ലിംകൾക്കുള്ള മോചനദ്രവ്യമായി നൽകി. (തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1020, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 505, 'عَنْ إِيَاسِ بْنِ سَلَمَةَ، عَنْ أَبِيهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْنَا فَزَارَةَ وَعَلَيْنَا أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، أَمَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا، فَلَمَّا كَانَ بَيْنَنَا وَبَيْنَ الْمَاءِ سَاعَةٌ أَمَرَنَا أَبُو بَكْرٍ فَعَرَّسْنَا، ثُمَّ شَنَّ الْغَارَةَ فَوَرَدَ الْمَاءَ، فَقَتَلَ مَنْ قَتَلَ عَلَيْهِ وَسَبَى، وَأَنْظُرُ إِلَى عُنُقٍ مِنَ النَّاسِ فِيهِمُ الذَّرَارِيُّ، فَخَشِيتُ أَنْ يَسْبِقُونِي إِلَى الْجَبَلِ، فَرَمَيْتُ بِسَهْمٍ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ، فَلَمَّا رَأَوُا السَّهْمَ وَقَفُوا، فَجِئْتُ بِهِمْ أَسُوقُهُمْ وَفِيهِمُ امْرَأَةٌ مِنْ بَنِي فَزَارَةَ، عَلَيْهَا قَشْعٌ مِنْ أَدَمٍ - قَالَ: الْقَشْعُ: النِّطَعُ - مَعَهَا ابْنَةٌ لَهَا مِنْ أَحْسَنِ الْعَرَبِ، فَسُقْتُهُمْ حَتَّى أَتَيْتُ بِهِمْ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، فَنَفَّلَنِي أَبُو بَكْرٍ ابْنَتَهَا، فَقَدِمْنَا الْمَدِينَةَ وَمَا كَشَفْتُ لَهَا ثَوْبًا، فَلَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السُّوقِ، فَقَالَ: "يَا سَلَمَةُ، هَبْ لِيَ الْمَرْأَةَ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، [وَاللَّهِ] لَقَدْ أَعْجَبَتْنِي وَمَا كَشَفْتُ لَهَا ثَوْبًا. ثُمَّ لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَدِ فِي السُّوقِ فَقَالَ لِي: "يَا سَلَمَةُ، هَبْ لِيَ الْمَرْأَةَ لِلَّهِ أَبُوكَ". فَقُلْتُ: هِيَ لَكَ يَا رَسُولَ اللَّهِ، فَوَاللَّهِ مَا كَشَفْتُ لَهَا ثَوْبًا، فَبَعَثَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِ مَكَّةَ، فَفَدَى بِهَا نَاسًا مِنَ الْمُسْلِمِينَ، كَانُوا أُسِرُوا بِمَكَّةَ. (م,د,جه)', 'തന്റെ പിതാവിൽ നിന്ന് ഇയാസുബ്നു സലമ(റ): അദ്ദേഹം പറഞ്ഞു: അബൂബക്കർ(റ)വിന്റെ നേതൃത്വത്തിൽ ഞങ്ങൾ ഫസാറ ഗോത്രത്തോട് യുദ്ധം ചെയ്തു. റസൂൽ(സ)യാണ് അദ്ദേഹത്തെ ഞങ്ങളുടെ നേതാവാക്കിയത്. അങ്ങനെ ഞങ്ങളുടെയും വെള്ളത്തിന്റെയുമിടയിൽ ഒരു മണിക്കൂർ നേരത്തെ യാത്രാദൂരമുണ്ടായപ്പോൾ, അബൂബക്കർ(റ) (വിശ്രമിക്കാൻ) കൽപിക്കുകയും ഞങ്ങൾ യാത്രാമദ്ധ്യേ വിശ്രമിക്കുകയും ചെയ്തു. പിന്നെ, നാനാഭാഗത്തു നിന്നും ശത്രുക്കളെ അക്രമിക്കുകയും, അങ്ങനെ വെള്ളത്തിന്റെയടുക്കൽ എത്തുകയും ചെയ്തു. അവിടെ വെച്ച് പലരെയും വധിക്കുകയും ബന്ധികളാക്കുകയും ചെയ്തു. ഉടനെ കുട്ടികളടങ്ങുന്ന ഒരു ആൾക്കൂട്ടത്തെ ഞാൻ കണ്ടു. അവർ എനിക്ക് മുമ്പ് മലയിലേക്ക് എത്തിച്ചേരുമോ എന്ന് ഞാൻ ഭയപ്പെട്ടു. അവരുടെയും മലയുടെയും ഇടയിലേക്കായി ഞാൻ അമ്പെയ്തു. അമ്പ് കണ്ടപ്പോൾ അവരവിടെ നിന്നു. അപ്പോൾ ഞാൻ അവരെ തെളിച്ച് കൊണ്ടുവന്നു. അവരിൽ തോൽവസ്ത്രം ധരിച്ച, ബനൂഫസാറയിൽ പെട്ട ഒരു സ്ത്രീയുണ്ടായിരുന്നു. അവളുടെ കൂടെ അറേബ്യയിലെ ഏറ്റവും ഭംഗിയുള്ളവരിൽ പെട്ട അവളുടെ ഒരു പെൺകുട്ടിയുണ്ടായിരുന്നു. ഞാനവരെ തെളിച്ച് കൊണ്ടുപോവുകയും അങ്ങനെ അബൂബക്കർ(റ)വിന്റെ സന്നിധിയിൽ വരികയും ചെയ്തു. അവളുടെ മകളെ അബൂബക്കർ(റ) എനിക്ക് അധിക വിഹിതമായി വീതിച്ചുതന്നു. അങ്ങനെ ഞങ്ങൾ മദീനയിൽ വന്നു. ഞാനവളുടെ ഒരു വസ്ത്രവും വെളിവാക്കിയിട്ടില്ല താനും. അപ്പോൾ അങ്ങാടിയിൽ വെച്ച് അല്ലാഹുവിന്റെ റസൂൽ(സ) എന്നെ കണ്ടുമുട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഏ സലമ, ആ പെണ്ണിനെ നീ എനിക്ക് നൽകുക." അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, (അല്ലാഹുവാണ് സത്യം) തീർച്ചയായും ഇവളെന്നെ അത്ഭുതപ്പെടുത്തിയിരിക്കുന്നു. ഞാനാണെങ്കിൽ അവളുടെ ഒരു വസ്ത്രവും വെളിവാക്കിയിട്ടില്ല താനും. പിന്നെ അടുത്ത ദിവസവും അല്ലാഹുവിന്റെ റസൂൽ(സ) അങ്ങാടിയിൽ വെച്ച് എന്നെ കണ്ടുമുട്ടുകയും എന്നോട് ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഏ സലമാ, നീയാ പെണ്ണിനെ എനിക്ക് നൽകുക, നിന്റെ പിതാവ് അല്ലാഹുവിന് ദണ്ഡമാണ്." അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവൾ താങ്കൾക്കുള്ളതാണ്. അല്ലാഹുവാണ് സത്യം, ഞാനവളുടെ ഒരു വസ്ത്രവും വെളിവാക്കിയിട്ടുണ്ടായിരുന്നില്ല. അങ്ങനെ അല്ലാഹുവിന്റെ റസൂൽ(സ) അവളെ മക്കക്കാരിലേക്ക് അയക്കുകയും മക്കയിൽ ബന്ധികളായിരുന്ന ചില മുസ്ലിംകൾക്കുള്ള മോചന ദ്രവ്യമായി അവളെ നൽകുകയും ചെയ്തു. (മു,ദ,ജ)', 'إِيَاسِ بْنِ سَلَمَةَ، عَنْ أَبِيهِ', 'തന്റെ പിതാവിൽ നിന്ന് ഇയാസുബ്നു സലമ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], 'وَاللَّهِ', null, 1020, 1021, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 506, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ الْمُشْرِكِينَ أَرَادُوا أَنْ يَشْتَرُوا جَسَدَ رَجُلٍ مِنَ الْمُشْرِكِينَ، فَأَبَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَهُمْ إِيَّاهُ. حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മുശ്രിക്കുകൾ അവരിൽപെട്ട ഒരാളുടെ ശവശരീരം വാങ്ങാനുദ്ദേശിച്ചു. എന്നാൽ നബി(സ) അതവർക്ക് വിൽക്കാൻ വിസമ്മതിച്ചു. ഹദീസ് ഹസനാണ്. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1021, 1021, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=178 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 507, 'عَنْ خَبَّابٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُتَوَسِّدٌ بُرْدَةً فِي ظِلِّ الْكَعْبَةِ، فَشَكَوْنَا إِلَيْهِ فَقُلْنَا: أَلَا تَسْتَنْصِرُ لَنَا، أَلَا تَدْعُو اللَّهَ لَنَا؟ فَجَلَسَ مُحْمَرًّا وَجْهُهُ فَقَالَ: "قَدْ كَانَ مَنْ قَبْلَكُمْ يُؤْخَذُ الرَّجُلُ، فَيُحْفَرُ لَهُ فِي الْأَرْضِ، ثُمَّ يُؤْتَى بِالْمِنْشَارِ فَيُجْعَلُ عَلَى رَأْسِهِ فَيُجْعَلُ فِرْقَتَيْنِ، مَا يَصْرِفُهُ ذَلِكَ عَنْ دِينِهِ. وَيُمْشَطُ بِأَمْشَاطِ الْحَدِيدِ مَا دُونَ عَظْمِهِ مِنْ لَحْمٍ وَعَصَبٍ، مَا يَصْرِفُهُ ذَلِكَ عَنْ دِينِهِ. وَاللَّهِ لَيُتِمَّنَّ اللَّهُ هَذَا الْأَمْرَ، حَتَّى يَسِيرَ الرَّاكِبُ مَا بَيْنَ صَنْعَاءَ وَحَضْرَمَوْتَ مَا يَخَافُ إِلَّا اللَّهَ تَعَالَى وَالذِّئْبَ عَلَى غَنَمِهِ، وَلَكِنَّكُمْ تَعْجَلُونَ". (ق,د,ن)', 'ഖബ്ബാബ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുക്കൽ പോയി. അവിടുന്ന് കഅ്ബയുടെ തണലിൽ ഒരു പുതപ്പ് തലയിണയാക്കിവെച്ച് കിടക്കുകയായിരുന്നു. ഞങ്ങൾ നബി(സ)യോട് വേവലാതി പറഞ്ഞു: അങ്ങ് ഞങ്ങൾക്ക് വേണ്ടി സഹായം തേടുന്നില്ലേ? അങ്ങ് ഞങ്ങൾക്ക് വേണ്ടി പ്രാർത്ഥിക്കുന്നില്ലേ? ഉടനെ വിവർണ്ണമായ മുഖവുമായി അവിടുന്ന് ഇരുന്നു. ശേഷം പറഞ്ഞു: "നിങ്ങൾക്ക് മുമ്പുള്ള സമൂഹത്തിൽ പെട്ട ഒരാളെ പിടിച്ച് അയാൾക്ക് വേണ്ടി കുഴി കുഴിക്കപ്പെടുകയും എന്നിട്ട് തലയിൽ വാൾ വെച്ച് അവനെ രണ്ടാക്കി ഭാഗിക്കപ്പെടുകയും ചെയ്യുമായിരുന്നു. ഇതൊന്നുമവനെ തന്റെ മതത്തിൽ നിന്ന് പിന്തിരിപ്പിക്കുമായിരുന്നില്ല. ഇരുമ്പിന്റെ ചീർപ്പ് കൊണ്ട് എല്ലിന്റെ മുകളിൽ മാംസത്തലും ഞരമ്പിലും ചീകുമായിരുന്നു. ഇതുമവനെ തന്റെ മതത്തിൽ നിന്ന് പിന്തിരിപ്പിച്ചിരുന്നില്ല. അല്ലാഹു തന്നെ സത്യം, ഈ കാര്യം അല്ലാഹു പൂർത്തീകരിക്കുക തന്നെ ചെയ്യും. അങ്ങനെ അല്ലാഹുവിനെയോ, തന്റെ ആടിന്റെ മേൽ ചെന്നായയെയോ അല്ലാതെ മറ്റൊന്നിനെയും ഭയക്കാതെ സൻആ മുതൽ ഹളർമൗത് വരെ ഒരാൾക്ക് യാത്ര ചെയ്യാൻ സാധിക്കും. പക്ഷേ, നിങ്ങൾ ധൃതി പിടിക്കുകയാണ്." (ബു,മു,ദ,ന)', 'خَبَّابٍ', 'ഖബ്ബാബ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 1021, 1022, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=179 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 508, 'عَنْ أَبِي النَّضْرِ، عَنْ كِتَابِ رَجُلٍ مِنْ أَسْلَمَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى، فَكَتَبَ إِلَى عُمَرَ بْنِ عُبَيْدِ اللَّهِ حِينَ سَارَ إِلَى الْحَرُورِيَّةِ يُخْبِرُهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا الْعَدُوَّ يَنْتَظِرُ، حَتَّى إِذَا مَالَتِ الشَّمْسُ قَامَ فِيهِمْ، فَقَالَ: "يَا أَيُّهَا النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ، وَاسْأَلُوا اللَّهَ الْعَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا، وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ". ثُمَّ قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "اللَّهُمَّ مُنْزِلَ الْكِتَابِ، وَمُجْرِيَ السَّحَابِ، وَهَازِمَ الْأَحْزَابِ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ". (ق,د,ت)', 'അബൂന്നള്ർ(റ): അബ്ദുല്ലാഹിബ്നു അബീഔഫ(റ) എന്ന് പേരുള്ള, നബി(സ)യുടെ അനുചരന്മാരിൽപ്പെട്ട, അസ്ലം ഗോത്രക്കാരനായ ഒരു വ്യക്തിയുടെ കത്തിൽ നിന്ന് അദ്ദേഹം ഉദ്ധരിക്കുന്നു: ഉമറുബ്നു ഉബൈദില്ല ഹറൂരിയാക്കളി(ഖവാരിജുകൾ)ലേക്ക് യുദ്ധത്തിന് പുറപ്പെട്ടപ്പോൾ അദ്ദേഹത്തിന് അബുന്നള്ർ(റ) ഇപ്രകാരം സന്ദേശമയച്ചു: ശത്രുക്കളോട് ഏറ്റുമുട്ടിയ ചില ദിവസങ്ങളിൽ നബി(സ) അൽപ സമയം കാത്തിരിക്കുമായിരുന്നു. അങ്ങനെ സൂര്യൻ ഉച്ചയിൽ നിന്ന് തെറ്റിയാൽ അവർക്കിടയിൽ എഴുന്നേറ്റു നിന്നുകൊണ്ട് അവിടുന്ന് പറയും: "ജനങ്ങളേ, ശത്രുക്കളെ അഭിമുഖീകരിക്കണമെന്ന് നിങ്ങൾ ആഗ്രഹിക്കരുത്. അല്ലാഹുവിനോട് നിങ്ങൾ സൗഖ്യത്തെ ചോദിക്കുക. ശത്രുക്കളെ അഭിമുഖീകരിക്കുമ്പോൾ ക്ഷമിച്ച് നിലകൊള്ളുക. തീർച്ചയായും സ്വർഗം വാളുകളുടെ നിഴലുകൾക്കടിയിലാണെന്ന് നിങ്ങൾ അറിയുക." ശേഷം എഴുന്നേറ്റുനിന്നുകൊണ്ട് അവിടുന്ന് പറയും: "ഗ്രന്ഥത്തെ ഇറക്കിയവനും മേഘത്തെ ചലിപ്പിക്കുന്നവനും സഖ്യകക്ഷികളെ തുരത്തിയവനുമായ അല്ലാഹുവേ, അവരെ നീ പരാചയപ്പെടുത്തുകയും അവർക്കെതിരായി ഞങ്ങളെ സഹായിക്കുകയും ചെയ്യണേ." (ബു,മു,ദ,തു)', 'أَبِي النَّضْرِ، عَنْ كِتَابِ رَجُلٍ مِنْ أَسْلَمَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى، فَكَتَبَ إِلَى عُمَرَ بْنِ عُبَيْدِ اللَّهِ حِينَ سَارَ إِلَى الْحَرُورِيَّةِ يُخْبِرُهُ', 'അബൂന്നള്ർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 1022, 1022, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=180 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 509, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ نَخْلَ بَنِي النَّضِيرِ وَحَرَّقَ. وَلَهَا يَقُولُ حَسَّانُ رَضِيَ اللَّهُ عَنْهُ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 510, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ، فَخَرَجْتُ إِلَى أَهْلِي، فَأَقْبَلْتُ وَقَدْ خَرَجَ أَوَّلُ صَحَابَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَطَفِقْتُ فِي الْمَدِينَةِ أُنَادِي: أَلَا مَنْ يَحْمِلُ رَجُلًا لَهُ سَهْمُهُ؟ فَنَادَى شَيْخٌ مِنَ الْأَنْصَارِ قَالَ: لَنَا سَهْمُهُ عَلَى أَنْ نَحْمِلَهُ عَقَبَةً وَطَعَامُهُ مَعَنَا؟ قُلْتُ: نَعَمْ. قَالَ: فَسِرْ عَلَى بَرَكَةِ اللَّهِ تَعَالَى، قَالَ: فَخَرَجْتُ مَعَ خَيْرِ صَاحِبٍ حَتَّى أَفَاءَ اللَّهُ عَلَيْنَا، فَأَصَابَنِي قَلَائِصُ فَسُقْتُهُنَّ حَتَّى أَتَيْتُهُ، فَخَرَجَ فَقَعَدَ عَلَى حَقِيبَةٍ مِنْ حَقَائِبِ إِبِلِهِ، ثُمَّ قَالَ: سُقْهُنَّ مُدْبِرَاتٍ، ثُمَّ قَالَ: سُقْهُنَّ مُقْبِلَاتٍ، فَقَالَ: مَا أَرَى قَلَائِصَكَ إِلَّا كِرَامًا. قَالَ: إِنَّمَا هِيَ غَنِيمَتُكَ الَّتِي شَرَطْتُ لَكَ، قَالَ: خُذْ قَلَائِصَكَ يَا ابْنَ أَخِي، فَغَيْرَ سَهْمِكَ أَرَدْنَا. (د)', 'വാസിലതുബ്നുൽ അസ്കഅ്(റ): നബി(സ) തബൂക്ക് യുദ്ധത്തിലായിരുന്നു. അപ്പോൾ ഞാനെന്റെ കുടുംബത്തിലേക്ക് പോയി. ഞാൻ തിരിച്ചെത്തിയപ്പോഴേക്കും നബി(സ)യുടെ അനുചരന്മാരിൽ നിന്നുള്ള ആദ്യവിഭാഗം പുറപ്പെട്ടിരുന്നു. അപ്പോൾ ഞാൻ മദീനയിൽ വിളിച്ച് പറയാൻ തുടങ്ങി: ഒരാളെ അയാളുടെ വിഹിതം കൈപ്പറ്റി, (യുദ്ധത്തിനായി) കൊണ്ടുപോകാൻ തയ്യാറുള്ള ആരുണ്ട്? അപ്പോൾ അൻസാറുകളിൽ പെട്ട ഒരു വൃദ്ധൻ വിളിച്ചു ചോദിച്ചു: ഭക്ഷണവും വാഹനപ്പുറത്ത് യാത്രക്ക് ഒരു ഊഴവും നൽകി ഞങ്ങളോടൊപ്പം അയാളെ കൊണ്ടുപോയാൽ അയാളുടെ ഓഹരി ഞങ്ങൾക്കായിരിക്കുമോ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: എന്നാൽ നീ അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിലായി യാത്ര ചെയ്യുക. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ ഏറ്റവും നല്ല ഒരു കൂട്ടുകാരന്റെ കൂടെ പുറപ്പെടുകയും, ഒടുവിൽ അല്ലാഹു ഞങ്ങൾക്ക് യുദ്ധമുതൽ നൽകുകയും ചെയ്തു. അപ്പോൾ എനിക്ക് കുറച്ച് നല്ല ഒട്ടകങ്ങൾ ലഭിക്കുകയും ഞാനവയെയും തെളിച്ച് അദ്ദേഹത്തിന്റെയടുക്കൽ പോവുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം തന്റെ ഒട്ടകത്തിന്റെ പുറത്ത് വെക്കുന്ന സഞ്ചികളിൽ ഒന്നിന്റെ മുകളിൽ പോയി ഇരിക്കുകയും പിന്നെ ഇപ്രകാരം പറയുകയും ചെയ്തു: നീ അവയെ മടങ്ങിപ്പോകുന്ന രൂപത്തിൽ തെളിക്കുക. പിന്നെ പറഞ്ഞു: നീ അവയെ മുന്നിട്ട് വരുന്നതായി തെളിക്കുക. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: നിന്റെ ഒട്ടകങ്ങൾ വളരെ നല്ലതാണെന്നല്ലാതെ മറ്റൊരഭിപ്രായം എനിക്കില്ല. നിവേദകൻ പറഞ്ഞു: ഇത് ഞാൻ അങ്ങേക്ക് (നൽകാനായി) വ്യവസ്ഥയാക്കിയ അങ്ങയുടെ യുദ്ധമുതലാണ്. അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദരപുത്രാ, നീ നിന്റെ ഒട്ടകങ്ങളെ എടുത്തു കൊള്ളുക. നിന്റെ ഓഹരിയല്ലാത്തതിനെയാണ് (പ്രതിഫലം) ഞങ്ങൾ ഉദ്ദേശിച്ചത്. (ദ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലതുബ്നുൽ അസ്കഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1023, 1023, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=182 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 511, 'عَنْ عِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُوطَأَ السَّبَايَا حَتَّى يَضَعْنَ مَا فِي بُطُونِهِنَّ. (ت)', 'ഇർബാളുബ്നു സാരിയ(റ): ഗർഭത്തിലുള്ളതിനെ പ്രസവിക്കുന്നത് വരെ ബന്ധികളുമായി ശാരീരിക ബന്ധത്തിലേർപ്പെടുന്നതിനെ അല്ലാഹുവിന്റെ റസൂൽ(സ) നിരോധിച്ചു. (തു)', 'عِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1023, 1024, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 512, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ عِبْدَانٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يَعْنِي يَوْمَ الْحُدَيْبِيَةِ - قَبْلَ الصُّلْحِ، فَكَتَبَ إِلَيْهِ مَوَالِيهِمْ فَقَالُوا: يَا مُحَمَّدُ، وَاللَّهِ مَا خَرَجُوا إِلَيْكَ رَغْبَةً فِي دِينِكَ، وَإِنَّمَا خَرَجُوا هَرَبًا مِنَ الرِّقِّ. فَقَالَ نَاسٌ: صَدَقُوا يَا رَسُولَ اللَّهِ، رُدَّهُمْ إِلَيْهِمْ. فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "مَا أُرَاكُمْ تَنْتَهُونَ يَا مَعْشَرَ قُرَيْشٍ حَتَّى يَبْعَثَ اللَّهُ عَلَيْكُمْ مَنْ يَضْرِبُ رِقَابَكُمْ عَلَى هَذَا". وَأَبَى أَنْ يَرُدَّهُمْ وَقَالَ: "هُمْ عُتَقَاءُ اللَّهِ عَزَّ وَجَلَّ". (ت)', 'അലി(റ): ഹുദൈബിയ്യാ ദിവസത്തിൽ സന്ധിക്ക് മുമ്പായി (ശത്രുക്കളുടെ)ചില അടിമകൾ റസൂൽ(സ)യുടെ അടുത്തേക്ക് പുറപ്പെട്ടു. അപ്പോൾ അവരുടെ യജമാനന്മാർ തിരുമേനി(സ)ക്ക് ഇപ്രകാരം സന്ദേശമെഴുതി: മുഹമ്മദേ, അല്ലാഹുവാണ് സത്യം, താങ്കളുടെ മതത്തോടുള്ള തൃപ്തികാരണമല്ല അവർ നിങ്ങളുടെയടുക്കൽ വരുന്നത്. മറിച്ച് അടിമത്വത്തെ പേടിച്ചിട്ടാണ് അവർ പുറപ്പെട്ടിട്ടുള്ളത്. അപ്പോൾ ചിലയാളുകൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവർ പറയുന്നത് സത്യമാണ്. അതുകൊണ്ട് അവരെ അവർക്ക് തന്നെ മടക്കിക്കൊടുത്താലും. അപ്പോൾ റസൂൽ(സ) ദേഷ്യപ്പെടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഖുറൈശീ സമൂഹമേ, ഇവ്വിഷയകമായി നിങ്ങളുടെ പിരടിവെട്ടുന്നവരെ അല്ലാഹു നിങ്ങളിലേക്ക് അയക്കുന്നതുവരെ നിങ്ങളിത് അവസാനിപ്പിക്കുമെന്ന് എനിക്ക് തോന്നുന്നില്ല." അവരെ തിരുച്ചുകൊടുക്കാൻ അവിടന്ന് വിസമ്മതിക്കുകയും "അവർ അത്യുന്നതനായ അല്ലാഹുവിനാൽ മോചിപ്പിക്കപ്പെട്ടവരാണ്" എന്ന് പറയുകയും ചെയ്തു. (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 1024, 1024, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=184 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 513, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ إِذَا جَاءَهُ أَمْرُ سُرُورٍ - أَوْ بُشِّرَ بِهِ - خَرَّ سَاجِدًا شَاكِرًا لِلَّهِ. (د,ت,جه)', 'അബൂബക്റ(റ): നിശ്ചയം നബി(സ)യിലേക്ക് സന്തോഷമുള്ള വല്ല കാര്യങ്ങളും എത്തിയാൽ - അല്ലെങ്കിൽ അവിടന്ന് വല്ല സന്തോഷവാർത്തയുമറിയിക്കപ്പെട്ടാൽ - അല്ലാഹുവിന് നന്ദിചെയ്യുന്നവരായി അവിടന്ന് സുജൂദ് ചെയ്യാറുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 1024, 1024, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 514, 'عَنْ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ نُرِيدُ الْمَدِينَةَ، فَلَمَّا كُنَّا قَرِيبًا مِنْ عَزْوَرَا نَزَلَ، ثُمَّ رَفَعَ يَدَيْهِ فَدَعَا اللَّهَ سَاعَةً، ثُمَّ خَرَّ سَاجِدًا، فَمَكَثَ طَوِيلًا، ثُمَّ قَامَ فَرَفَعَ يَدَيْهِ فَدَعَا اللَّهَ سَاعَةً ثُمَّ خَرَّ سَاجِدًا، فَمَكَثَ طَوِيلًا، ثُمَّ قَامَ فَرَفَعَ يَدَيْهِ سَاعَةً ثُمَّ خَرَّ سَاجِدًا، قَالَ: "إِنِّي سَأَلْتُ رَبِّي، وَشَفَعْتُ لِأُمَّتِي، فَأَعْطَانِي ثُلُثَ أُمَّتِي، فَخَرَرْتُ سَاجِدًا شُكْرًا لِرَبِّي، ثُمَّ رَفَعْتُ رَأْسِي فَسَأَلْتُ رَبِّي لِأُمَّتِي، فَأَعْطَانِي ثُلُثَ أُمَّتِي، فَخَرَرْتُ سَاجِدًا لِرَبِّي شُكْرًا، ثُمَّ رَفَعْتُ رَأْسِي فَسَأَلْتُ رَبِّي لِأُمَّتِي، فَأَعْطَانِي الثُّلُثَ الْآخِرَ، فَخَرَرْتُ سَاجِدًا لِرَبِّي". (د)', 'സഅ്ദ്(റ): റസൂൽ(സ)യോടൊപ്പം മക്കയിൽ നിന്ന് ഞങ്ങൾ മദീന ലക്ഷ്യമാക്കി പുറപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾ ഗസ്വറ എന്ന സ്ഥലത്തിന്റെ അടുത്തെത്തിയപ്പോൾ തിരുമേനി(സ) അവിടെ ഇറങ്ങി. പിന്നീടവിടന്ന് ഇരുകരങ്ങൾ ഉയർത്തുകയും അൽപനേരം അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുകയും ചെയ്തു. പിന്നീടവിടന്ന് സുജൂദിലായി വീണു. ഒരുപാടു നേരം അങ്ങനെത്തന്നെ കഴിച്ചുകൂട്ടി. പിന്നീടവിടന്ന് എഴുന്നേൽക്കുകയും അന്നേരം ഇരുകരങ്ങളും ഉയർത്തി അൽപനേരം അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുകയും വീണ്ടും സുജൂദിലായി വീഴുകയും ചെയ്തു. അങ്ങനെ കുറേനേരം കഴിച്ചുകൂട്ടി. വീണ്ടും അവിടന്ന് എഴുന്നേറ്റ് അൽപനേരം കൈകളുയർത്തി. വീണ്ടും സുജൂദിലായി വീണു. അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം ഞാൻ എന്റെ സമുദായത്തിനുവേണ്ടി എന്റെ രക്ഷിതാവിനോട് ചോദിക്കുകയും ശിപാർശ ചെയ്യുകയും ചെയ്തു. അപ്പോൾ അവനെനിക്ക് എന്റെ സമുദായത്തിന്റെ മൂന്നിൽ ഒന്ന് നൽകി, അപ്പോൾ എന്റെ രക്ഷിതാവിനോടുള്ള നന്ദിസൂചകമായി ഞാൻ സുജൂദിൽ വീണു. പിന്നെ ഞാൻ എന്റെ തല ഉയർത്തുകയും എന്റെ രക്ഷിതാവിനോട് എന്റെ ഉമ്മത്തിന് വേണ്ടി ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ അവനെനിക്ക് എന്റെ സമുദായത്തിന്റെ മൂന്നിലൊന്നുകൂടി നൽകി. അപ്പോൾ നന്ദിസൂചകമായി ഞാൻ എന്റെ റബ്ബിന് സുജൂദിലായി വീണു. പിന്നെ ഞാൻ തല ഉയർത്തുകയും എന്റെ രക്ഷിതാവിനോട് എന്റെ സമുദായത്തിനുവേണ്ടി ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ അവനെനിക്ക് അവസാനത്തെ മൂന്നിൽ ഒന്നും നൽകി. അപ്പോൾ ഞാൻ എന്റെ റബ്ബിന് സുജൂദിലായി വീണു." (ദ)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1024, 1025, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 515, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا تُرِيحُنِي مِنْ ذِي الْخَلَصَةِ". فَأَتَاهَا فَحَرَّقَهَا، ثُمَّ بَعَثَ رَجُلًا مِنْ أَحْمَسَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُبَشِّرُهُ، يُكْنَى أَبَا أَرْطَاةَ. (خ)', 'ജരീർ(റ): റസൂൽ(സ) എന്നോട് ചോദിച്ചു: "ദുൽഖലസ(ജനങ്ങൾ ആരാധിച്ചിരുന്ന വിഗ്രഹത്തിന്റെ വീട്)യിൽ നിന്ന് നീയെനിക്ക് ആശ്വാസം തരില്ലെയോ." അപ്പോഴദ്ദേഹം അവിടെപ്പോവുകയും അത് കരിച്ച് കളയുകയും ചെയ്തു. പിന്നെയദ്ദേഹം അബൂഅർത്വാഅ് എന്ന് ഓമനപ്പേരുള്ള, അഹ്മസ് ഗോത്രത്തിൽ പെട്ട ഒരാളെ നബി(സ)യുടെ അടുത്തേക്ക് സന്തോഷവാർത്ത അറിയിക്കാനായി അയച്ചു. (ബു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1025, 1025, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=186 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 516, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالْمَسْجِدِ فَرَكَعَ فِيهِ رَكْعَتَيْنِ، ثُمَّ جَلَسَ لِلنَّاسِ، وَقَصَّ الْحَدِيثَ، قَالَ: وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمِينَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ، حَتَّى إِذَا طَالَ عَلَيَّ تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ - وَهُوَ ابْنُ عَمِّي - فَسَلَّمْتُ عَلَيْهِ، فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ، ثُمَّ صَلَّيْتُ الصُّبْحَ صَبَاحَ خَمْسِينَ لَيْلَةً عَلَى ظَهْرِ بَيْتٍ مِنْ بُيُوتِنَا، فَسَمِعْتُ صَارِخًا: يَا كَعْبُ بْنَ مَالِكٍ، أَبْشِرْ. فَلَمَّا جَاءَنِي الَّذِي سَمِعْتُ صَوْتَهُ يُبَشِّرُنِي نَزَعْتُ لَهُ ثَوْبَيَّ فَكَسَوْتُهُمَا إِيَّاهُ، فَانْطَلَقْتُ حَتَّى إِذَا دَخَلْتُ الْمَسْجِدَ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَقَامَ إِلَيَّ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ يُهَرْوِلُ حَتَّى صَافَحَنِي وَهَنَّأَنِي. (ق,د,ن)', 'കഅ്ബുബ്നു മാലിക്(റ): നബി(സ) യാത്ര കഴിഞ്ഞ് തിരിച്ചുവന്നാൽ ആദ്യം പള്ളിയിൽ വന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. പിന്നെ ജനങ്ങൾക്ക് വേണ്ടി ഇരിക്കും. അദ്ദേഹം ആ ഹദീസ് വിവരിച്ചു. അദ്ദേഹം പറയുന്നു: അല്ലാഹുവിന്റെ റസൂൽ(സ) ഞങ്ങൾ ഈ മൂന്ന് പേരോട് സംസാരിക്കുന്നതിനെത്തൊട്ട് മുസ്ലിംകളെ വിലക്കി. അങ്ങനെ ഈ അവസ്ഥ ഒരുപാട് ദിവസത്തേക്ക് നീണ്ടുനിന്നപ്പോൾ ഞാൻ അബൂഖതാദ(റ)വിന്റെ - അദ്ദേഹം എന്റെ പിതൃവ്യപുത്രനാണ് - തോട്ടത്തിന്റെ ചുമരിൽ കയറി അദ്ദേഹത്തോട് സലാം പറഞ്ഞു. അല്ലാഹുവാണ് സത്യം, അദ്ദേഹമെന്റെ സലാം മടക്കിയില്ല. പിന്നെ ഞാൻ അൻപത് പ്രഭാതങ്ങളിൽ സുബ്ഹി നമസ്കാരം ഞങ്ങളുടെ വീടുകളിൽ പെട്ട ഒരു വീടിനു മുകളിൽവെച്ച് നിർവ്വഹിച്ചു. ഒടുവിൽ ഒരാൾ വിളിച്ചുപറയുന്നതായി ഞാൻ കേട്ടു: കഅ്ബുബ്നു മാലികേ, നീ സന്തോഷിച്ചുകൊള്ളുക. എനിക്ക് സന്തോഷവാർത്തയറിയിച്ച് ശബ്ദമുയർത്തിയ ആ വ്യക്തി എന്റെ അടുക്കൽ വന്നപ്പോൾ ഞാൻ എന്റെ രണ്ടുവസ്ത്രങ്ങൾ അഴിക്കുകയും അദ്ദേഹത്തെ ധരിപ്പിക്കുകയും ചെയ്തു. പിന്നെ ഞാൻ പോയി പള്ളിയിൽ പ്രവേശിച്ചു. അന്നേരം റസൂൽ(സ) ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ത്വൽഹതുബ്നു ഉബൈദില്ല(റ) എന്റെ അടുത്തേക്ക് വേഗത്തിൽ എഴുന്നേറ്റ് വരികയും എനിക്ക് ഹസ്തദാനം ചെയ്യുകയും എന്നെ സന്തോഷമറിയിക്കുകയും ചെയ്തു. (ബു,മു,ദ,ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 1025, 1026, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=187 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 517, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا رَجَعَ يَوْمَ الْخَنْدَقِ وَوَضَعَ السِّلَاحَ وَاغْتَسَلَ، فَأَتَاهُ جِبْرِيلُ وَقَدْ عَصَبَ رَأْسَهُ الْغُبَارُ، فَقَالَ: وَضَعْتَ السِّلَاحَ فَوَاللَّهِ مَا وَضَعْتُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَأَيْنَ؟" قَالَ: هَا هُنَا، وَأَوْمَأَ إِلَى بَنِي قُرَيْظَةَ. قَالَتْ: فَخَرَجَ إِلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ആഇശ(റ): നിശ്ചയം ഖൻദഖ് ദിനത്തിൽ റസൂൽ(സ) മടങ്ങിവരികയും ആയുധങ്ങൾ ഒരിടത്ത് വെച്ച് കുളിക്കുകയും ചെയ്തപ്പോൾ, അവിടത്തെ തിരുസന്നിധിയിലേക്ക് ജിബ്രീൽ(അ), പൊടി തലയിൽ പറ്റിപ്പിടിച്ച അവസ്ഥയിൽ വരികയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: അങ്ങ് ആയുധങ്ങൾ വെച്ചുവോ, അല്ലാഹുവാണ് സത്യം, ഞാനത് വെച്ചിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അപ്പോൾ എവിടെയാണ്?" ജിബ്രീൽ(അ) പറഞ്ഞു: ഇവിടെയിതാ. ജിബ്രീൽ(അ) ബനൂഖുറൈള ഗോത്രത്തിലേക്ക് ആംഗ്യം കാണിക്കുകയും ചെയ്തു. ആഇശ ബീവി(റ) പറയുന്നു: അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) അവരിലേക്ക് പുറപ്പെട്ടു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1026, 1026, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=188 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 518, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ - يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بُسْبَسَةَ عَيْنًا يَنْظُرُ مَا صَنَعَتْ عِيرُ أَبِي سُفْيَانَ. (م,د)', 'അനസ്(റ): അബൂസുഫ്യാന്റെ ഒട്ടകക്കൂട്ടം എന്താണ് ചെയ്യുന്നതെന്ന് നിരീക്ഷിക്കാനായി നബി(സ) ബുസ്ബസ(റ)വിനെ ചാരനായി അയച്ചു. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 1026, 1026, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=189 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 519, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "شَرُّ مَا فِي رَجُلٍ شُحٌّ هَالِعٌ، وَجُبْنٌ خَالِعٌ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു മനുഷ്യനിലെ ഏറ്റവും മോശപ്പെട്ട സ്വഭാവം പേടി ജനിപ്പിക്കുന്ന പിശുക്കും ഹൃദയം പൊട്ടിക്കുന്ന ഭീരുത്വവുമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1027, 1027, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=190 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 520, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُقَدَّ السَّيْرُ بَيْنَ إِصْبَعَيْنِ. (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): നിശ്ചയം റസൂൽ(സ) രണ്ട് വിരലുകൾക്കിടയിലുള്ള തോൽ മുറിക്കുന്നത് നിരോധിച്ചു. (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 1027, 1027, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=191 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 521, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَفَلَ مِنْ غَزْوٍ أَوْ حَجٍّ أَوْ عُمْرَةٍ يُكَبِّرُ عَلَى كُلِّ شَرَفٍ مِنَ الْأَرْضِ ثَلَاثَ تَكْبِيرَاتٍ، وَيَقُولُ: "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. آيِبُونَ، تَائِبُونَ، عَابِدُونَ، سَاجِدُونَ، لِرَبِّنَا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ". (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിശ്ചയം അല്ലാഹുവിന്റെ റസൂൽ(സ) യുദ്ധങ്ങളും ഹജ്ജും ഉംറയുമെല്ലാം കഴിഞ്ഞ് മടങ്ങുമ്പോൾ എല്ലാ ഉയർന്ന സ്ഥലങ്ങളിലെത്തുമ്പോഴും മൂന്ന് തവണ തക്ബീർ ചൊല്ലുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനാണ്, അവന് യാതൊരു പങ്കുകാരുമില്ല, അവന്നാണ് ആധിപത്യം, അവന് തന്നെയാണ് സ്തുതി. അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്. ഖേദിച്ച് മടങ്ങുന്നവരായി, പശ്ചാത്തപിച്ച് മടങ്ങുന്നവരായി, ആരാധിക്കുന്നവരായി, സാഷ്ടാംഗം നമിക്കുന്നവരായി, ഞങ്ങളുടെ രക്ഷിതാവിന് സ്തുതിയർപ്പിക്കുന്നവരായി (ഞങ്ങൾ മടങ്ങുന്നു). അല്ലാഹു അവന്റെ വാഗ്ദത്തം സത്യമാക്കിയിരിക്കുന്നു. അവന്റെ അടിമയെ സഹായിച്ചിരിക്കുന്നു. അവൻ ഒറ്റക്ക് സൈന്യങ്ങളെ പരാജയപ്പെടുത്തിയിരിക്കുന്നു." (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 1027, 1027, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=192 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 522, 'عَنِ ابْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ لِابْنِ جَعْفَرٍ: أَتَذْكُرُ إِذْ تَلَقَّيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَنْتَ وَابْنُ عَبَّاسٍ؟ قَالَ: نَعَمْ، فَحَمَلَنَا وَتَرَكَكَ. (خ)', 'ഇബ്നുസുബൈർ(റ): അദ്ദേഹം ഇബ്നുജഅ്ഫർ(റ)വിനോട് ചോദിച്ചു: ഞാനും നീയും ഇബ്നുഅബ്ബാസ്(റ)വും അല്ലാഹുവിന്റെ റസൂൽ(സ)യെ സ്വീകരിച്ച സന്ദർഭം നീ ഓർക്കുന്നുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, അപ്പോൾ ഞങ്ങളെ അവിടന്ന് വഹിക്കുകയും താങ്കളെ ഒഴിവാക്കുകയും ചെയ്തു. (ബു)', 'ابْنِ الزُّبَيْرِ', 'ഇബ്നുസുബൈർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1027, 1027, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 523, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَهَبْنَا نَتَلَقَّى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ الصِّبْيَانِ إِلَى ثَنِيَّةِ الْوَدَاعِ. (خ)', 'സാഇബുബ്നു യസീദ്(റ): റസൂൽ(സ)യെ സ്വീകരിക്കാനായി ഞങ്ങൾ കുട്ടികളോടൊപ്പം സനിയ്യതുൽ വദാഅ് എന്ന സ്ഥലത്തേക്ക് പോയി. (ബു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1027, 1028, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 524, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقْفَلَهُ مِنْ عُسْفَانَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَاحِلَتِهِ، وَقَدْ أَرْدَفَ صَفِيَّةَ بِنْتَ حُيَيٍّ، فَعَثَرَتْ نَاقَتُهُ فَصُرِعَا جَمِيعًا فَاقْتَحَمَ أَبُو طَلْحَةَ فَقَالَ: يَا رَسُولَ اللَّهِ، جَعَلَنِي اللَّهُ فِدَاءَكَ، قَالَ: "عَلَيْكَ الْمَرْأَةَ". فَقَلَبَ ثَوْبًا عَلَى وَجْهِهِ وَأَتَاهَا، فَأَلْقَاهُ عَلَيْهَا وَأَصْلَحَ لَهُمَا مَرْكَبَهُمَا فَرَكِبَا، وَاكْتَنَفْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا أَشْرَفْنَا عَلَى الْمَدِينَةِ قَالَ: "آيِبُونَ تَائِبُونَ، عَابِدُونَ لِرَبِّنَا حَامِدُونَ". فَلَمْ يَزَلْ يَقُولُ ذَلِكَ حَتَّى دَخَلَ الْمَدِينَةَ. (خ)', 'അനസുബ്നു മാലിക്(റ): ഉസ്ഫാനിൽ നിന്നുള്ള നബി(സ)യുടെ മടക്കയാത്രയിൽ ഞങ്ങൾ അവിടത്തോടൊപ്പമായിരുന്നു. റസൂൽ(സ) അവിടത്തെ വാഹനത്തിന്മേലായിരുന്നു. സ്വഫിയ്യ ബിൻത് ഹുയയ്യ്(റ)യെ അവിടന്ന് തന്റെ വാഹനത്തിന്റെ പിന്നിലിരുത്തിയിരുന്നു. അപ്പോൾ അവിടത്തെ ഒട്ടകം വീഴുകയും അവർ രണ്ടുപേരും വീഴ്ത്തപ്പെടുകയും ചെയ്തു. അപ്പോൾ അബൂത്വൽഹ(റ) ആലോചന കൂടാതെ കാര്യത്തിൽ ചാടിവീഴുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ അല്ലാഹു അങ്ങേക്ക് ദണ്ഡമാക്കിയിരിക്കുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ആ സ്ത്രീയെ പിടിക്കൂ." അപ്പോൾ അദ്ദേഹം തന്റെ മുഖത്ത് ഒരു വസ്ത്രം കമിഴ്ത്തുകയും മഹതിയുടെ അടുത്ത് ചെല്ലുകയും അത് മഹതിയുടെ മേൽ ഇടുകയും അവർക്ക് രണ്ട് പേർക്കുമായി അവരുടെ വാഹനം ശരിയാക്കിക്കൊടുക്കുകയും ചെയ്തു. അങ്ങനെ അവർ രണ്ടുപേരും വാഹനം കയറി. ശേഷം ഞങ്ങൾ റസൂൽ(സ)ക്ക് കക്കൂസ് നിർമ്മിച്ചു കൊടുത്തു. അങ്ങനെ ഞങ്ങൾ മദീനയിലേക്ക് അടുത്തപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഖേദിച്ചു മടങ്ങിയവരായി, പശ്ചാത്തപിച്ചു മടങ്ങിയവരായി, ആരാധിക്കുന്നവരായി, ഞങ്ങളുടെ രക്ഷിതാവിന് സ്തുതിയർപ്പിക്കുന്നവരായി (ഞങ്ങൾ മടങ്ങുന്നു)." മദീനയിലേക്ക് പ്രവേശിക്കുന്നതുവരെ അവിടന്ന് അത് പറഞ്ഞു കൊണ്ടേയിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 1028, 1028, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 525, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ تَبُوكَ خَرَجَ النَّاسُ يَتَلَقَّوْنَهُ إِلَى ثَنِيَّةِ الْوَدَاعِ، قَالَ السَّائِبُ: فَخَرَجْتُ مَعَ النَّاسِ وَأَنَا غُلَامٌ. (خ,د,ت)', 'സാഇബുബ്നു യസീദ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) തബൂക്കിൽ നിന്ന് മടങ്ങിവന്നപ്പോൾ അവിടത്തെ സ്വീകരിക്കാനായി ജനങ്ങൾ സനിയ്യതുൽ വിദാഇലേക്ക് പുറപ്പെട്ടു. സാഇബ്(റ) പറഞ്ഞു: അപ്പോൾ ജനങ്ങളോടൊപ്പം കുട്ടിയായ ഞാനും പുറപ്പെട്ടു. (ബു,ദ,തു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 1028, 1028, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=3 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
